import ConfirmationModal from '@/components/custom-modal/ConfirmationModal';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import WarningModal from '@/components/custom-modal/WarningModal';
import Icon from '@/components/Icon';
import { useModal } from '@/components/ModalProvider';
import PalRiderText from '@/components/PalRiderText';
import {
	useLazyDeleteBankAccountQuery,
	useLazySetPrimaryBankAccountQuery,
} from '@/services/api/courier/courier-bank-account';
import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { font, PADDING } from '@/theme/responsive';
import { isFetchBaseQueryError } from '@/utils';
import { CourierBankAccountDTO } from 'palriderapptypes/courier';
import { useCallback } from 'react';
import { ListRenderItemInfo, Pressable, StyleSheet, View } from 'react-native';
import Swipeable from 'react-native-gesture-handler/Swipeable';

const CourierBankAccountItemRenderer: React.FC<
	ListRenderItemInfo<CourierBankAccountDTO> & {
		load: () => void;
		navigation: any;
	}
> = ({ item, load }) => {
	const [deleteCourierBankAccount] = useLazyDeleteBankAccountQuery();
	const [setPrimaryCourierBankAccount] = useLazySetPrimaryBankAccountQuery();
	const { showGlobalModal, hideGlobalModal } = useModal();
	const handleRemove = async () => {
		showGlobalModal({
			padding: 0,
			children: (
				<ConfirmationModal
					icon={<Icon name="TrashIconSvg" width={20} height={20} color={colors.red[600]} />}
					text="Are you sure want to delete bank account?"
					onConfirm={async () => {
						hideGlobalModal();
						showGlobalModal({
							children: <LoadingModal />,
							backgroundColor: 'transparent',
						});
						const res = await deleteCourierBankAccount(item.id);
						if (res.error && isFetchBaseQueryError(res.error)) {
							showGlobalModal({
								children: <WarningModal text={res.error.data.title} />,
							});
							return;
						}
						showGlobalModal({
							children: <SuccessModal text="Bank Account deleted" />,
							whenClose() {
								load();
							},
						});
					}}
					onCancel={() => hideGlobalModal()}
				/>
			),
			onClose: () => hideGlobalModal(),
		});
	};
	const handlePrimary = () => {
		showGlobalModal({
			padding: 0,
			children: (
				<ConfirmationModal
					icon={<Icon name="VerifiedIconSvg" width={20} height={20} color={colors.green[600]} />}
					text="Are you sure want to change that bank account primary?"
					onConfirm={async () => {
						hideGlobalModal();
						showGlobalModal({
							children: <LoadingModal />,
							backgroundColor: 'transparent',
						});
						const res = await setPrimaryCourierBankAccount(item.id);
						if (res.error && isFetchBaseQueryError(res.error)) {
							showGlobalModal({
								children: <WarningModal text={res.error.data.title} />,
							});
							return;
						}
						showGlobalModal({
							children: <SuccessModal text="Bank Account setted primary" />,
							whenClose() {
								load();
							},
						});
					}}
					onCancel={() => hideGlobalModal()}
				/>
			),
			onClose: () => hideGlobalModal(),
		});
	};
	const handleUpdate = () => {
		//TODO : handle update?
		return;
	};
	const renderRightActions = useCallback(() => {
		return (
			<View style={styles.rightButtoContainer}>
				<Pressable style={styles.rightActionButton} onPress={handleUpdate}>
					<Icon name="EditIconSvg" color={colors.green[600]} />
				</Pressable>
				<Pressable style={styles.rightActionButton} onPress={handlePrimary}>
					<Icon name="CheckCircleIconSvg" color={colors.green[600]} />
				</Pressable>
				<Pressable style={styles.rightActionButton} onPress={handleRemove}>
					<Icon name="TrashIconSvg" color={colors.red[600]} />
				</Pressable>
			</View>
		);
	}, []);
	return (
		<Swipeable
			friction={2}
			enableTrackpadTwoFingerGesture
			rightThreshold={40}
			renderRightActions={() => renderRightActions()}
			childrenContainerStyle={styles.itemContainer}
		>
			<View style={{ paddingRight: PADDING.medium }}>
				<Icon name="CreditCardIconSvg" width={30} height={30} />
			</View>
			<View style={styles.informationContainer}>
				<PalRiderText style={styles.accountHolder}>
					{item.title} ({item.account_holder_name})
				</PalRiderText>
				<PalRiderText style={styles.account}>
					{item.sort_code} {item.account_number}
				</PalRiderText>
			</View>
			<View style={styles.primaryContainer}>
				<Icon name="VerifiedIconSvg" color={item.is_primary ? colors.green[600] : colors.gray[600]} />
			</View>
		</Swipeable>
	);
};
const styles = StyleSheet.create({
	itemContainer: {
		marginVertical: PADDING.medium,
		flexDirection: 'row',
		gap: PADDING.medium,
		borderWidth: 1,
		alignItems: 'center',
		padding: PADDING.medium,
		borderColor: colors.gray[300],
		borderRadius: PADDING.large,
		backgroundColor: colors.white,
	},
	bankImage: {
		width: 40,
		height: 40,
		borderRadius: PADDING.medium,
	},
	accountHolder: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.medium,
	},
	account: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.mini,
		color: colors.gray[400],
	},
	informationContainer: {
		flex: 1,
	},
	deleteIconContainer: {},
	rightButtoContainer: {
		flexDirection: 'row',
		gap: PADDING.mini,
	},
	rightActionButton: {
		padding: PADDING.large,
		justifyContent: 'center',
		alignItems: 'center',
	},
	primaryContainer: {
		alignItems: 'center',
		paddingRight: PADDING.medium,
	},
});

export default CourierBankAccountItemRenderer;
