import React, { useEffect } from 'react';
import { Pressable, RefreshControl, ScrollView, StyleSheet, View } from 'react-native';
import colors from '@/theme/colors.ts';
import PalRiderText from '@/components/PalRiderText.tsx';
import { FontFamily } from '@/theme/fonts.ts';
import { font, PADDING } from '@/theme/responsive.ts';
import { useGetCompanyAreaQuery } from '@/services/api/company/company-area';
import { CompositeScreenProps } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import {
	AppCompanyProfileCompanyAreaParamList,
	AppCompanyProfileParamList,
	AppCompanyTabParamList,
} from '@/navigation/company-navigation';
import { useTranslation } from 'react-i18next';
import Icon from '@/components/Icon';

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList, 'CompanyAreaView'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyAreaStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
			CompositeScreenProps<
				NativeStackScreenProps<RootStackParamList>,
				NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList>
			>
		>
	>
>;
const AppCompanyProfileCompanyAreaViewScreen: React.FC<Props> = ({ route, navigation }) => {
	const { t } = useTranslation();
	if (!route?.params?.company_area_id) navigation.goBack();
	const { data, fulfilledTimeStamp, refetch, isLoading } = useGetCompanyAreaQuery(route.params.company_area_id);
	const refreshList = () => refetch();
	useEffect(() => {
		if (!fulfilledTimeStamp) refreshList();
	}, [fulfilledTimeStamp]);

	return (
		<View style={styles.container}>
			<ScrollView
				style={{ flex: 1 }}
				contentContainerStyle={{ gap: PADDING.large, padding: PADDING.large }}
				contentInsetAdjustmentBehavior="automatic"
				refreshControl={<RefreshControl onRefresh={refreshList} refreshing={isLoading} />}
			>
				<View style={styles.areaInfoContainer}>
					<View style={styles.areaInfoItem}>
						<PalRiderText style={styles.areaInfoTitle}>{t('common.name')}</PalRiderText>
						<Pressable style={styles.editRow}>
							<PalRiderText style={styles.areaInfoText}>{data?.data.name}</PalRiderText>
							<Icon name="EditIconSvg" width={12} height={12} />
						</Pressable>
					</View>
					<View style={styles.areaInfoItem}>
						<PalRiderText style={styles.areaInfoTitle}>{t('common.email')}</PalRiderText>
						<Pressable style={styles.editRow}>
							<PalRiderText style={styles.areaInfoText}>{data?.data.email}</PalRiderText>
							<Icon name="EditIconSvg" width={12} height={12} />
						</Pressable>
					</View>
				</View>
			</ScrollView>
		</View>
	);
};
const styles = StyleSheet.create({
	container: {
		backgroundColor: colors.white,
		flex: 1,
	},

	areaInfoContainer: {
		borderWidth: 1,
		borderColor: colors.gray[200],
		borderRadius: PADDING.large,
	},
	areaInfoTitle: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.small,
	},
	areaInfoText: {
		fontFamily: FontFamily.Regular,
		fontSize: font.mini,
		color: colors.gray[500],
	},
	areaInfoItem: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
		padding: PADDING.large,
		borderBottomWidth: 1,
		borderColor: colors.gray[200],
	},
	editRow: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: PADDING.medium,
	},
});
export default AppCompanyProfileCompanyAreaViewScreen;
