import React, { useRef, useState, useEffect } from 'react';
import PalDivider from '@/components/PalDivider';
import PalRiderButton from '@/components/PalRiderButton';
import PalRiderCheckBox from '@/components/PalRiderCheckBox';
import PalRiderPhoneInput from '@/components/PalRiderPhoneInput';
import PalRiderText from '@/components/PalRiderText';
import PalRiderTextInput from '@/components/PalRiderTextInput';
import { useAuthenticateUserMutation, useVerifyUserMutation } from '@/services/api/user';
import colors from '@/theme/colors';
import { buttonStyling } from '@/theme/defaults';
import { FontFamily } from '@/theme/fonts';
import { normalize, PADDING } from '@/theme/responsive';
import { Shape } from '@/types';
import { isFetchBaseQueryError, phoneNumberRegex } from '@/utils';
import { useFormik } from 'formik';
import { Alert, Dimensions, LayoutAnimation, Platform, StyleSheet, TouchableOpacity, View } from 'react-native';
import { KeyboardAwareScrollView } from 'react-native-keyboard-aware-scroll-view';
import { boolean, object, string } from 'yup';
import { useModal } from '@/components/ModalProvider';
import WarningModal from '@/components/custom-modal/WarningModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { AuthStackParamList } from '@/navigation/auth-navigation';
import { CompositeScreenProps } from '@react-navigation/native';
import { RootStackParamList } from '@/navigation';
import { useTranslation } from 'react-i18next';
import Dropdown from 'react-native-input-select';
import { DropdownSelectHandle } from 'react-native-input-select/lib/typescript/src/types/index.types';
import { convertStringToJsx } from '@/utils/string';
import PalRiderPhoneCodeInput from '@/components/PalRiderPhoneCodeInput';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { useAppDispatch } from '@/redux/hooks';
import { setToken } from '@/redux/slices/userSlice';
import useUserNavigation from '@/hooks/useUserNavigation';
import LinearGradient from 'react-native-linear-gradient';
import hotUpdate from 'react-native-ota-hot-update';
import Icon from '@/components/Icon';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { HOT_UPDATE_VERSION } from '@env';
import { Pressable } from 'react-native-gesture-handler';

type FormikType = {
	phone_number: string;
	email: string;
	authentication_type: 'phone' | 'email';
	agreement: boolean;
};

type Props = CompositeScreenProps<
	NativeStackScreenProps<AuthStackParamList, 'PhoneInfo'>,
	NativeStackScreenProps<RootStackParamList>
>;

const PhoneInfoScreen: React.FC<Props> = ({ navigation }) => {
	const { t } = useTranslation();
	const [authenticateUser, { isLoading: isLoadingAuthenticateUser }] = useAuthenticateUserMutation();
	const [verifyUser, { isError }] = useVerifyUserMutation();
	const { showGlobalModal, hideGlobalModal } = useModal();
	const dispatch = useAppDispatch();
	const areaCodeRef = useRef<DropdownSelectHandle | null>(null);
	const { handle: handleUserNavigation } = useUserNavigation();
	const [areaCode, setAreaCode] = useState('44');
	const [showOtpVerification, setShowOtpVerification] = useState(false);

	const [_, setProgress] = useState<number>(0);
	const [cooldown, setCooldown] = useState(0);

	// cooldown interval
	useEffect(() => {
		if (cooldown > 0) {
			const timer = setInterval(() => setCooldown((c) => c - 1), 1000);
			return () => clearInterval(timer);
		}
	}, [cooldown]);

	// format helper
	const formatCooldown = (seconds: number) => {
		const m = Math.floor(seconds / 60);
		const s = seconds % 60;
		return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
	};

	const onCheckGitVersion = () => {
		showGlobalModal({
			children: <LoadingModal />,
			preventHiding: true,
			backgroundColor: colors.transparent,
		});
		hotUpdate.git.checkForGitUpdate({
			branch: Platform.OS === 'ios' ? 'iOS' : 'android',
			bundlePath: Platform.OS === 'ios' ? 'ios/output/main.jsbundle' : 'android/output/index.android.bundle',
			url: 'https://github.com/akncnkoc/palriderapp-bundle.git',
			restartAfterInstall: true,
			onCloneFailed(msg: string) {
				Alert.alert('Clone project failed!', msg, [{ text: 'Cancel', style: 'cancel' }]);
			},
			onCloneSuccess() {
				Alert.alert('Clone project success!', 'Restart to apply the changes', [
					{ text: 'OK', onPress: () => hotUpdate.resetApp() },
					{ text: 'Cancel', style: 'cancel' },
				]);
			},
			onPullFailed(msg: string) {
				Alert.alert('Pull project failed!', msg, [{ text: 'Cancel', style: 'cancel' }]);
			},
			onPullSuccess() {
				Alert.alert('Pull project success!', 'Restart to apply the changes', [
					{ text: 'OK', onPress: () => hotUpdate.resetApp() },
					{ text: 'Cancel', style: 'cancel' },
				]);
			},
			onProgress(received: number, total: number) {
				const percent = (+received / +total) * 100;
				LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);
				setProgress(percent);
				showGlobalModal({
					children: <LoadingModal text={`${percent}%`} />,
					preventHiding: true,
					backgroundColor: colors.transparent,
				});
			},
			onFinishProgress() {
				hideGlobalModal();
				setProgress(0);
			},
		});
	};

	const signUpFormik = useFormik<FormikType>({
		initialValues: {
			authentication_type: 'phone',
			phone_number: '',
			email: '',
			agreement: true,
		},
		validationSchema: object<Shape<FormikType>>({
			authentication_type: string(),
			phone_number: string().when('authentication_type', {
				is: (value: string) => value === 'phone',
				then: (schema) =>
					schema
						.required(t('validation.required', { field: t('common.phone_number') }))
						.test('phone-regex', t(t('validation.regex')), function (value) {
							return phoneNumberRegex.test('+' + areaCode + value);
						}),
				otherwise: (schema) => schema,
			}),
			email: string().when('authentication_type', {
				is: (value: string) => value === 'email',
				then: (schema) =>
					schema.required(t('validation.required', { field: t('common.email') })).email(t('validation.email')),
				otherwise: (schema) => schema,
			}),
			agreement: boolean()
				.required()
				.oneOf([true], t('validation.required', { field: t('common.agreement') })),
		}),
		onSubmit: async (values) => {
			const result = await authenticateUser({
				phone_number: '+' + areaCode + values.phone_number.replace(/\D/g, ''),
			});

			if (result.error && isFetchBaseQueryError(result.error)) {
				if (result.error.status === 429) {
					const data = result.error.data as unknown as {
						message: string;
						limit: number;
						remainingAttempts: number;
						retryAfterSeconds: number;
					};

					setCooldown(data.retryAfterSeconds);

					showGlobalModal({
						children: (
							<WarningModal
								text={`${data.message}. You can request a maximum of ${data.limit} times per hour. Remaining attempts: ${data.remainingAttempts}. Please wait ${Math.ceil(
									data.retryAfterSeconds / 60,
								)} minutes.`}
							/>
						),
					});
					return;
				}
				showGlobalModal({
					children: <WarningModal text={result.error.data.title} />,
				});
				return;
			}
			if (result.data) {
				setShowOtpVerification(true);
			}
		},
	});

	const verificationCodeComplete = async (code: string) => {
		const result = await verifyUser({
			phone_number: '+' + areaCode + signUpFormik.values.phone_number.replace(/\D/g, ''),
			code,
		});
		if (result.error && isFetchBaseQueryError(result.error)) {
			showGlobalModal({
				maxHeight: 200,
				children: <WarningModal text={result.error.data.title} />,
			});
			return;
		}

		if (result.data) {
			await AsyncStorage.setItem('token', result.data?.data);
			dispatch(setToken(result.data.data));
			showGlobalModal({
				children: <SuccessModal text={result.data.message} />,
				closeAfterDelay: 1500,
				async whenClose() {
					await handleUserNavigation();
				},
			});
		}
	};

	const resendOtpCode = async () => {
		if (cooldown > 0) return;
		signUpFormik.handleSubmit();
	};

	const changePhoneNumber = () => {
		setShowOtpVerification(false);
		signUpFormik.setFieldValue('phone_number', '', false);
	};

	const goToSignUp = () => {
		navigation.navigate('AuthStack', { screen: 'AuthSelect' });
	};

	return (
		<KeyboardAwareScrollView style={{ flex: 1 }}>
			<LinearGradient
				colors={[colors.orange[600], colors.red[500]]}
				start={{ x: 0, y: 0 }}
				end={{ x: 1, y: 0 }}
				style={{
					height: Dimensions.get('screen').height * 0.35,
					position: 'absolute',
					top: 0,
					left: 0,
					justifyContent: 'center',
					alignItems: 'center',
					backgroundColor: 'rgba(0,0,0,0.5)',
					width: '100%',
				}}
			>
				<PalRiderText style={{ fontFamily: FontFamily.Bold, color: colors.white, fontSize: normalize(25) }}>
					{t('screen.auth.user.phone_info.title')}
				</PalRiderText>
				<PalRiderText style={styles.description}>
					{convertStringToJsx(t('screen.auth.user.phone_info.description'))}
				</PalRiderText>
			</LinearGradient>

			<View style={{ flex: 1, marginTop: Dimensions.get('screen').height * 0.3 }}>
				<KeyboardAwareScrollView
					style={styles.container}
					alwaysBounceVertical={false}
					bounces={false}
					contentContainerStyle={styles.scrollViewContentContainerStyle}
					showsVerticalScrollIndicator={false}
					keyboardShouldPersistTaps="handled"
				>
					<View style={styles.contentContainer}>
						<Dropdown
							ref={areaCodeRef}
							dropdownStyle={{ display: 'none' }}
							options={[
								{ label: t('country.united_kingdom', { code: '+44' }), value: '44' },
								{ label: t('country.turkey', { code: '+90' }), value: '90' },
							]}
							selectedValue={areaCode}
							onValueChange={(value) => setAreaCode(value != '' ? (value as string) : '44')}
							autoCloseOnSelect
							isMultiple={false}
						/>

						{signUpFormik.values.authentication_type === 'phone' && (
							<PalRiderPhoneInput
								onAreaCodePress={() => areaCodeRef.current?.open()}
								areaCode={areaCode}
								title={t('common.phone_number')}
								editable={!showOtpVerification}
								onChangeText={(text) => signUpFormik.setFieldValue('phone_number', text, true)}
								error={signUpFormik.errors.phone_number}
								touched={!signUpFormik.errors.phone_number}
								value={signUpFormik.values.phone_number}
								keyboardType="number-pad"
							/>
						)}

						{signUpFormik.values.authentication_type === 'email' && (
							<PalRiderTextInput
								title={t('common.email')}
								value={signUpFormik.values.email}
								onChangeText={(text: string) => signUpFormik.setFieldValue('email', text)}
								error={signUpFormik.errors.email}
								keyboardType="email-address"
								autoComplete="email"
								autoCapitalize="none"
								autoCorrect={false}
								leftComponent={<Icon name="EmailSignIconSvg" width={16} height={16} />}
							/>
						)}

						{showOtpVerification && (
							<View style={{ marginHorizontal: PADDING.medium }}>
								<PalRiderPhoneCodeInput
									containerStyle={{
										borderWidth: 1,
										borderColor: isError ? colors.red[600] : colors.transparent,
										width: 50,
										height: 50,
									}}
									onComplete={verificationCodeComplete}
								/>
							</View>
						)}

						{showOtpVerification && (
							<View
								style={{
									marginVertical: PADDING.medium,
									justifyContent: 'space-between',
									flexDirection: 'row',
									alignItems: 'center',
								}}
							>
								{cooldown === 0 && (
									<Pressable onPress={() => resendOtpCode()}>
										<PalRiderText color={colors.blue[800]} fontFamily={FontFamily.Semibold}>
											Resend Code
										</PalRiderText>
									</Pressable>
								)}
								{cooldown > 0 && (
									<PalRiderText color={colors.gray[700]} fontFamily={FontFamily.Semibold}>
										Resend available in {formatCooldown(cooldown)}
									</PalRiderText>
								)}
								<Pressable onPress={() => changePhoneNumber()}>
									<PalRiderText color={colors.blue[800]} fontFamily={FontFamily.Semibold}>
										Change Phone Number
									</PalRiderText>
								</Pressable>
							</View>
						)}

						<View style={{ flexDirection: 'row', alignItems: 'center', marginHorizontal: normalize(4) }}>
							<PalRiderCheckBox
								value={signUpFormik.values.agreement}
								error={signUpFormik.errors.agreement}
								onValueChange={(val) => signUpFormik.setFieldValue('agreement', val)}
							/>
							<View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: normalize(4), marginVertical: normalize(8) }}>
								<PalRiderText>
									<PalRiderText style={styles.linkedText}>
										{convertStringToJsx(t('screen.auth.user.phone_info.aggrement_line_1'))}
									</PalRiderText>
									<TouchableOpacity>
										<PalRiderText style={[styles.linkText, { top: 3, marginRight: normalize(4) }]}>
											{t('common.terms_of_use')}
										</PalRiderText>
									</TouchableOpacity>
									<PalRiderText style={styles.linkedText}>{t('common.and')}</PalRiderText>
									<TouchableOpacity>
										<PalRiderText style={[styles.linkText, { top: 3, left: 4 }]}>
											{t('common.privacy_policy')}
										</PalRiderText>
									</TouchableOpacity>
								</PalRiderText>
							</View>
						</View>

						<PalRiderButton
							style={[buttonStyling.success, styles.continueButton]}
							onPress={() => signUpFormik.handleSubmit()}
							loading={isLoadingAuthenticateUser}
						>
							<PalRiderText style={styles.continueButtonText}>
								{showOtpVerification ? 'Verify' : 'Send OTP'}
							</PalRiderText>
						</PalRiderButton>
					</View>

					<PalDivider containerStyle={{ padding: normalize(20) }} text="Or" />
					<View style={{ flex: 1 }}>
						<View style={{ paddingHorizontal: normalize(20), rowGap: normalize(10) }}>
							<PalRiderButton variant="dark" style={[styles.signUpButton, styles.signUpButtonGoogle]}>
								<PalRiderText style={styles.signUpButtonText}>
									{t('screen.auth.user.phone_info.sign_in_with')}{' '}
								</PalRiderText>
								<Icon name="GooglePlusSquareIconSvg" />
								<PalRiderText style={styles.signUpButtonText}>(WIP)</PalRiderText>
							</PalRiderButton>

							<PalRiderButton style={[buttonStyling.dark, styles.signUpButton, styles.signUpButtonFacebook]}>
								<PalRiderText style={styles.signUpButtonText}>
									{t('screen.auth.user.phone_info.sign_in_with')}{' '}
								</PalRiderText>
								<Icon name="FacebookSquareIconSvg" width={16} height={16} />
								<PalRiderText style={styles.signUpButtonText}>(WIP)</PalRiderText>
							</PalRiderButton>

							<PalRiderButton onPress={() => onCheckGitVersion()}>
								<PalRiderText color="white">Check for new updates ({HOT_UPDATE_VERSION})</PalRiderText>
							</PalRiderButton>

							<View style={styles.dontHaveAccount}>
								<PalRiderText>{t('screen.auth.user.phone_info.dont_have_an_account')}</PalRiderText>
								<TouchableOpacity onPress={goToSignUp}>
									<PalRiderText
										color={colors.orange[600]}
										fontFamily={FontFamily.Bold}
										style={{ textDecorationLine: 'underline' }}
									>
										{t('screen.auth.user.phone_info.sign_up')}
									</PalRiderText>
								</TouchableOpacity>
							</View>
						</View>
					</View>
				</KeyboardAwareScrollView>
			</View>
		</KeyboardAwareScrollView>
	);
};

const styles = StyleSheet.create({
	container: { flex: 1 },
	contentContainer: { paddingHorizontal: normalize(20), backgroundColor: colors.gray[100], justifyContent: 'center' },
	title: { textAlign: 'center', fontSize: normalize(30), color: colors.black, fontFamily: FontFamily.Bold },
	description: {
		textAlign: 'center',
		fontSize: normalize(14),
		fontFamily: FontFamily.Semibold,
		fontWeight: '600',
		color: colors.gray[200],
		marginTop: normalize(10),
		marginBottom: normalize(30),
	},
	scrollViewContentContainerStyle: {
		paddingTop: normalize(20),
		alignContent: 'center',
		backgroundColor: colors.gray[100],
		flex: 1,
		borderTopLeftRadius: normalize(20),
		borderTopRightRadius: normalize(20),
	},
	continueButton: { marginTop: normalize(8) },
	continueButtonText: { fontFamily: FontFamily.Bold, color: colors.white },
	signUpButton: { flexDirection: 'row', columnGap: 10, alignItems: 'center', justifyContent: 'center' },
	signUpButtonGoogle: { backgroundColor: colors.orange[600] },
	signUpButtonFacebook: { backgroundColor: colors.blue[700] },
	signUpButtonText: { color: 'white', fontSize: normalize(12), fontFamily: FontFamily.Bold },
	signUpWithEmailContainer: { marginVertical: normalize(8), alignItems: 'flex-end' },
	signUpWithEmailText: {
		fontFamily: FontFamily.Semibold,
		textDecorationStyle: 'solid',
		textDecorationLine: 'underline',
	},
	linkContainer: { marginBottom: normalize(40), justifyContent: 'center', flexDirection: 'row' },
	linkText: { color: colors.orange[600], fontFamily: FontFamily.Semibold, fontSize: normalize(12) },
	linkedText: { fontFamily: FontFamily.Semibold, fontSize: normalize(12) },
	dontHaveAccount: {
		flexDirection: 'row',
		alignItems: 'center',
		columnGap: PADDING.large,
		justifyContent: 'center',
		width: '100%',
	},
	signUpText: { textDecorationLine: 'underline', color: colors.orange[500], fontFamily: FontFamily.Semibold },
});

export default PhoneInfoScreen;
