import React, { useRef } from 'react';
import { Pressable, StyleSheet, View } from 'react-native';
import PalRiderFilePicker, { PalRiderFilePickerRef } from '@/components/PalRiderFilePicker';
import { useFormik } from 'formik';
import { DocumentPickerResponse } from '@react-native-documents/picker';
import { FileType } from '@/@types';
import { FlatList } from 'react-native-gesture-handler';
import PalRiderText from '@/components/PalRiderText';
import PalRiderButton from '@/components/PalRiderButton';
import { FontFamily } from '@/theme/fonts';
import colors from '@/theme/colors';
import { font, PADDING } from '@/theme/responsive';
import { yupTyped } from '@/types';
import { array, number, object, string } from 'yup';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { isFetchBaseQueryError } from '@/utils';
import WarningModal from '@/components/custom-modal/WarningModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import { CreateCompanyAreaAddressDocumentRequestDTO } from 'palriderapptypes/company';

import { CompositeScreenProps } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import {
	AppCompanyProfileCompanyAreaParamList,
	AppCompanyProfileParamList,
	AppCompanyTabParamList,
} from '@/navigation/company-navigation';
import { useTranslation } from 'react-i18next';
import { useStoreCompanyAreaAddressDocumentMutation } from '@/services/api/company/company-area-address-documents';
import Icon from '@/components/Icon';

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList, 'CompanyAreaAddressDocumentCreate'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyAreaStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
			CompositeScreenProps<
				NativeStackScreenProps<RootStackParamList>,
				NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList>
			>
		>
	>
>;
const AppCompanyProfileCompanyAreaAddressDocumentAddScreen: React.FC<Props> = ({ route, navigation }) => {
	const { t } = useTranslation();
	const filePickerRef = useRef<PalRiderFilePickerRef>(null);
	const { showGlobalModal } = useModal();
	const [storeCompanyAreaAddressDocument] = useStoreCompanyAreaAddressDocumentMutation();
	const documentFormik = useFormik<CreateCompanyAreaAddressDocumentRequestDTO>({
		initialValues: {
			company_area_address_id: route.params.company_area_address_id,
			documents: [],
		},
		validationSchema: yupTyped<CreateCompanyAreaAddressDocumentRequestDTO>({
			documents: array()
				.of(
					object().shape({
						name: string().required('File name required'),
						size: number().required().max(10000000),
						uri: string().required('File uri is required'),
						type: string().required('File type is required'),
					}),
				)
				.required()
				.label('Company Area Documents')
				.min(1, 'At least one document is required'),
		}),
		onSubmit: async (values) => {
			showGlobalModal({
				children: <LoadingModal />,
				backgroundColor: colors.transparent,
			});
			const res = await storeCompanyAreaAddressDocument({
				company_area_address_id: values.company_area_address_id,
				documents: values.documents,
			});
			if (res.error && isFetchBaseQueryError(res.error)) {
				showGlobalModal({
					children: <WarningModal text={res.error.data.title} />,
				});
				return;
			}
			showGlobalModal({
				children: <SuccessModal text={res.data?.message} />,
				whenClose() {
					navigation.goBack();
				},
			});
		},
	});
	const onFileSelected = (files: DocumentPickerResponse[]) => {
		const oldDocuments = documentFormik.values.documents;
		const newDocuments: Array<FileType> = [];
		files.map((file) => {
			if (!file.name || !file.uri || !file.size || !file.type) return;
			newDocuments.push({
				name: file.name,
				uri: file.uri,
				size: file.size,
				type: file.type,
			});
		});

		documentFormik.setFieldValue('documents', [...oldDocuments, ...newDocuments]);
	};
	const handleRemoveDocumentItem = (index: number) => {
		const documents = documentFormik.values.documents;
		const filteredDocuments = documents.filter((_, i) => i !== index);
		documentFormik.setFieldValue('documents', filteredDocuments);
	};
	return (
		<View style={[styles.container, { paddingBottom: PADDING.large }]}>
			<View style={styles.selectedDocumentsContainer}>
				{documentFormik.values.documents.length > 0 && (
					<FlatList
						data={documentFormik.values.documents}
						keyExtractor={(_, index) => index.toString()}
						style={{ width: '100%' }}
						contentContainerStyle={styles.selectedDocumentsContentContainerStyle}
						renderItem={({ item, index }) => (
							<View style={styles.documentItemContainer}>
								<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.mini}>
									{item.name}
								</PalRiderText>
								<Pressable onPress={() => handleRemoveDocumentItem(index)}>
									<Icon name="TrashIconSvg" width={20} height={20} color={colors.red[600]} />
								</Pressable>
							</View>
						)}
					/>
				)}
			</View>
			<View
				style={[
					styles.documentContainer,
					{
						justifyContent: documentFormik.values.documents.length > 0 ? 'flex-start' : 'center',
						paddingBottom: documentFormik.values.documents.length > 0 ? PADDING.medium : 0,
					},
				]}
			>
				<PalRiderText style={styles.infoText}>
					{t('screen.auth.sign_up_company.document_info.documents_description')}
				</PalRiderText>
				<View style={styles.infoListContainer}>
					<PalRiderText style={styles.infoListText}>
						1. {t('screen.auth.sign_up_company.document_info.document_list_1')}
					</PalRiderText>
					<PalRiderText style={styles.infoListText}>
						2. {t('screen.auth.sign_up_company.document_info.document_list_2')}
					</PalRiderText>
					<PalRiderText style={styles.infoListText}>
						3. {t('screen.auth.sign_up_company.document_info.document_list_3')}
					</PalRiderText>
				</View>
				<View style={styles.chooseContainer}>
					<PalRiderFilePicker ref={filePickerRef} onFileSelected={onFileSelected} />
					<PalRiderButton
						onPress={() => filePickerRef.current?.openFilePicker()}
						variant="dark"
						contentStyle={{ flexDirection: 'row', gap: PADDING.large }}
					>
						<PalRiderText fontFamily={FontFamily.Semibold} color={colors.white}>
							Upload Document
						</PalRiderText>
						<Icon name="UploadIconSvg" color={colors.white} width={16} height={16} />
					</PalRiderButton>
				</View>
			</View>
			<View style={[styles.buttonContainer]}>
				<PalRiderButton variant="dark" style={{ flex: 1 }} onPress={() => documentFormik.handleSubmit()}>
					<PalRiderText color="white">{t('common.add')}</PalRiderText>
				</PalRiderButton>
			</View>
		</View>
	);
};
const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.white,
		padding: PADDING.large,
	},
	documentContainer: {
		flex: 1,
	},
	infoText: {
		textAlign: 'left',
		fontSize: font.mini,
		paddingHorizontal: PADDING.large,
		marginBottom: PADDING.medium,
		fontFamily: FontFamily.Semibold,
	},
	infoListContainer: {
		alignItems: 'center',
		paddingHorizontal: PADDING.large,
		gap: PADDING.small,
		marginBottom: PADDING.medium,
		fontFamily: FontFamily.Semibold,
		fontSize: font.mini,
	},
	infoListText: {
		alignSelf: 'flex-start',
		color: colors.green[700],
		fontSize: font.mini,
		fontFamily: FontFamily.Semibold,
	},
	chooseContainer: {
		paddingHorizontal: PADDING.large,
	},
	buttonContainer: {
		flexDirection: 'row',
		gap: PADDING.large,
	},
	selectedDocumentsContainer: {
		width: '100%',
		marginBottom: PADDING.large,
	},
	selectedDocumentsContentContainerStyle: {
		gap: PADDING.medium,
		width: '100%',
	},
	documentItemContainer: {
		padding: PADDING.large,
		paddingVertical: PADDING.xxlarge,
		borderWidth: 1,
		borderColor: colors.gray[600],
		flexDirection: 'row',
		flex: 1,
		alignItems: 'center',
		justifyContent: 'space-between',
		gap: PADDING.large,
	},
});

export default AppCompanyProfileCompanyAreaAddressDocumentAddScreen;
