import React from 'react';
import { Platform } from 'react-native';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import { createNativeStackNavigator } from '@react-navigation/native-stack';

import { HomeIconSvg, ShippingBoxIconSvg } from '@/assets/svg/custom';
import AppActiveOrderShipmentScreen from '@/screens/app/order/active-order-shipment';
import AppActiveOrderHomeScreen from '@/screens/app/order/active-order/AppActiveOrderHomeScreen';
import AppActiveOrderShipmentsScreen from '@/screens/app/order/active-order/AppActiveOrderShipmentsScreen';
import AppActiveOrderCreateOrderShipmentScreen from '@/screens/app/order/active-order/create-order-shipment';
import AppOrderArriveWaitingScreen from '@/screens/app/order/AppOrderArriveWaiting';
import AppOrderArrivingScreen from '@/screens/app/order/AppOrderArrivingScreen';

import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { font } from '@/theme/responsive';
import { NavigatorScreenParams } from '@react-navigation/native';
import { CourierActiveOrderDTO, OrderShipmentDTO } from 'palriderapptypes/order';
import { useTranslation } from 'react-i18next';
import AppActiveOrderUpdateOrderShipmentScreen from '@/screens/app/order/active-order/update-order-shipment';

// Define param lists
export type AppActiveOrderTabParamList = {
	Home: { order_id: string };
	Shipments: { order_id: string };
};

export type AppOrderStackParamList = {
	OrderArriving: { order_id: string };
	OrderArriveWaiting: { order_id: string };
	ActiveOrderStack: NavigatorScreenParams<AppActiveOrderTabParamList>;
	CreateShipment: { order: CourierActiveOrderDTO };
	UpdateShipment: { shipment: OrderShipmentDTO };
	OrderShipmentDelivery: { order_id: string; order_shipment_id: string };
};

const ActiveOrderTab = createBottomTabNavigator<AppActiveOrderTabParamList>();

function AppActiveOrderStackNavigator() {
	const { t } = useTranslation();
	return (
		<ActiveOrderTab.Navigator
			screenOptions={{
				headerShadowVisible: false,
				tabBarStyle: {
					height: Platform.OS == 'android' ? 60 : 80,
					paddingBottom: 5,
					paddingTop: 5,
				},
				tabBarLabelStyle: {
					fontFamily: FontFamily.Semibold,
					fontSize: font.mini,
					paddingBottom: 5,
				},
				headerTitleAlign: 'center',
				tabBarActiveTintColor: colors.orange[600],
				tabBarInactiveTintColor: colors.black,
				headerTintColor: colors.white,
				headerStyle: { backgroundColor: colors.orange[600] },
			}}
		>
			<ActiveOrderTab.Screen
				name="Home"
				component={AppActiveOrderHomeScreen}
				options={{
					headerShown: true,
					headerTitle: 'Home',
					headerTitleAlign: 'center',
					tabBarIcon: ({ focused }) => (
						<HomeIconSvg width={20} height={20} color={focused ? colors.orange[600] : colors.black} />
					),
				}}
			/>
			<ActiveOrderTab.Screen
				name="Shipments"
				component={AppActiveOrderShipmentsScreen}
				options={{
					headerShown: true,
					headerTitleAlign: 'center',
					headerTitle: 'Shipments',
					tabBarIcon: ({ focused }) => (
						<ShippingBoxIconSvg width={20} height={20} color={focused ? colors.orange[600] : colors.black} />
					),
				}}
			/>
		</ActiveOrderTab.Navigator>
	);
}

const OrderStack = createNativeStackNavigator<AppOrderStackParamList>();

export function AppOrderStackNavigator() {
	return (
		<OrderStack.Navigator
			screenOptions={{
				headerShadowVisible: false,
				headerTitleAlign: 'center',
				headerTintColor: colors.white,
				headerStyle: { backgroundColor: colors.orange[600] },

				headerBackButtonDisplayMode: 'minimal',
			}}
		>
			<OrderStack.Screen
				name="OrderArriving"
				component={AppOrderArrivingScreen}
				options={{ title: 'Order Arriving', headerTitleAlign: 'center' }}
			/>
			<OrderStack.Screen
				name="OrderArriveWaiting"
				component={AppOrderArriveWaitingScreen}
				options={{
					title: 'Order Arrive Waiting',
					headerTitleAlign: 'center',
					headerBackButtonDisplayMode: 'minimal',
					headerBackButtonMenuEnabled: false,
				}}
			/>
			<OrderStack.Screen
				name="ActiveOrderStack"
				component={AppActiveOrderStackNavigator}
				options={{ headerShown: false }}
			/>
			<OrderStack.Screen
				name="CreateShipment"
				component={AppActiveOrderCreateOrderShipmentScreen}
				options={{
					title: 'Create Order Shipment',
					headerTitleAlign: 'center',
					headerShown: true,
				}}
			/>
			<OrderStack.Screen
				name="UpdateShipment"
				component={AppActiveOrderUpdateOrderShipmentScreen}
				options={{
					title: 'Update Shipment',
					headerTitleAlign: 'center',
					headerShown: true,
				}}
			/>
			<OrderStack.Screen
				name="OrderShipmentDelivery"
				component={AppActiveOrderShipmentScreen}
				options={{
					title: 'Order Shipment Delivery',
					headerTitleAlign: 'center',
					headerShown: false,
				}}
			/>
		</OrderStack.Navigator>
	);
}
