import { PaginatedRequestDTO, PaginationDataResultTypeTDTO } from '@/@types';
import { createApi } from '@reduxjs/toolkit/query/react';
import { baseQueryConfigWithReAuth } from '../baseQueryConfig';
import { NotificationDto } from '@/services/api/notification/notification-types.ts';

export const notificationApi = createApi({
	reducerPath: 'notification',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		getNotifications: builder.query<PaginationDataResultTypeTDTO<NotificationDto>, PaginatedRequestDTO>({
			query(query) {
				return {
					method: 'GET',
					params: {
						page: query.page_number,
						size: query.page_size,
					},
					url: `notification`,
				};
			},
		}),
	}),
});

export const { useLazyGetNotificationsQuery } = notificationApi;
