import PalRiderButton from '@/components/PalRiderButton.tsx';
import PalRiderText from '@/components/PalRiderText.tsx';
import colors from '@/theme/colors.ts';
import { FontFamily } from '@/theme/fonts.ts';
import { normalize } from '@/theme/responsive.ts';
import React, { Dispatch, SetStateAction, useCallback } from 'react';
import { StyleSheet, View } from 'react-native';
import Swipeable from 'react-native-gesture-handler/ReanimatedSwipeable';
import { CreateCourierVehicleRequestDTO } from 'palriderapptypes/courier';
import Icon from '@/components/Icon';
type Props = {
	vehicles: Array<CreateCourierVehicleRequestDTO>;
	setVehicles: Dispatch<SetStateAction<Array<CreateCourierVehicleRequestDTO>>>;
};
const SignUpCourierVehicles: React.FC<Props> = (props) => {
	const { vehicles, setVehicles } = props;
	const renderRightActions = useCallback(
		(vehicleId: string) => {
			return (
				<PalRiderButton
					style={styles.rightActionDeleteButton}
					onPress={() => setVehicles((v) => [...v.filter((x) => x.plate_number !== vehicleId)])}
				>
					<Icon name="TrashIconSvg" color={colors.red[600]} />
				</PalRiderButton>
			);
		},
		[vehicles],
	);
	return (
		<View style={styles.container}>
			{vehicles.map((vehicle) => (
				<Swipeable renderRightActions={() => renderRightActions(vehicle.plate_number)} key={vehicle.plate_number}>
					<View style={styles.vehicleContainer}>
						<View style={styles.vehicleIconContainer}>
							{vehicle.type === 'bike' && <Icon name="BikeIconSvg" />}
							{vehicle.type === 'motorcycle' && <Icon name="MotorcycleIconSvg" />}
							{vehicle.type === 'car' && <Icon name="CarIconSvg" />}
						</View>
						<PalRiderText style={styles.vehicleText}>{vehicle.plate_number || 'Bike'}</PalRiderText>
					</View>
				</Swipeable>
			))}
		</View>
	);
};
const styles = StyleSheet.create({
	container: {
		marginVertical: normalize(10),
		gap: normalize(8),
	},
	vehicleContainer: {
		backgroundColor: colors.gray[200],
		padding: normalize(16),
		flexDirection: 'row',
		alignItems: 'center',
		borderRadius: normalize(10),
	},
	vehicleIconContainer: {
		marginRight: normalize(8),
	},
	vehicleText: {
		fontFamily: FontFamily.Semibold,
		fontSize: normalize(12),
		flex: 1,
		color: colors.black,
	},
	deleteIconContainer: {},
	rightActionDeleteButton: {
		padding: normalize(16),
		justifyContent: 'center',
		alignItems: 'center',
	},
});
export default SignUpCourierVehicles;
