import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { normalize, PADDING } from '@/theme/responsive';
import React, { useEffect, useState } from 'react';
import { StyleSheet, View, ViewStyle } from 'react-native';
import { CodeField, Cursor, useBlurOnFulfill, useClearByFocusCell } from 'react-native-confirmation-code-field';
import PalRiderText from './PalRiderText';

type Props = {
	onComplete: (code: string) => void;
	autoComplete?: string;
	containerStyle?: ViewStyle;
};

const PalRiderPhoneCodeInput = ({ onComplete, containerStyle, autoComplete }: Props) => {
	const [value, setValue] = useState('');
	const [autoCompleteValue, setAutoCompleteValue] = useState('');
	const ref = useBlurOnFulfill({ value, cellCount: 6 });
	const [props, getCellOnLayoutHandler] = useClearByFocusCell({
		value,
		setValue,
	});

	useEffect(() => {
		if (autoComplete) {
			setValue(autoComplete);
			setAutoCompleteValue(autoComplete);
			return;
		}
	}, [autoComplete]);

	const autoFillCodeField = (text: string) => {
		if (autoCompleteValue) {
			setAutoCompleteValue('');
		}
		setValue(text);
		if (text.length === 6) {
			onComplete(text);
		}
	};

	useEffect(() => {
		ref.current?.focus();
	}, []);

	return (
		<CodeField
			ref={ref}
			autoFocus
			value={value}
			onChangeText={autoFillCodeField}
			cellCount={6}
			rootStyle={styles.codeFieldRoot}
			keyboardType="number-pad"
			textContentType="oneTimeCode"
			renderCell={({ index, symbol, isFocused }) => (
				<View style={[styles.cell, containerStyle]} key={index}>
					<PalRiderText
						key={index}
						style={[styles.cellText, isFocused && styles.focusCell]}
						onLayout={getCellOnLayoutHandler(index)}
					>
						{symbol || (isFocused ? <Cursor /> : null)}
					</PalRiderText>
				</View>
			)}
			{...props}
		/>
	);
};
export default PalRiderPhoneCodeInput;

const styles = StyleSheet.create({
	codeFieldRoot: { marginTop: normalize(30), gap: PADDING.medium, justifyContent: 'center' },
	cell: {
		backgroundColor: colors.gray[200],
		width: normalize(50),
		height: normalize(50),
		borderRadius: normalize(6),
		justifyContent: 'center',
		borderColor: colors.transparent,
	},
	cellText: {
		fontSize: normalize(24),
		textAlign: 'center',
		fontFamily: FontFamily.Regular,
		color: colors.black,
	},
	focusCell: {
		borderColor: colors.gray[100],
	},
});
