import React, { useEffect, useState } from 'react';
import { Alert, Linking, Platform, StyleSheet, View } from 'react-native';
import colors from '@/theme/colors';
import PalRiderText from '@/components/PalRiderText';
import {
	check,
	checkNotifications,
	openSettings,
	Permission,
	PERMISSIONS,
	request,
	requestNotifications,
	RESULTS,
} from 'react-native-permissions';
import { useSharedValue } from 'react-native-reanimated';
import PalRirderSwitch from '@/components/PalRiderSwitch';

type PermissionStatus = 'unavailable' | 'denied' | 'blocked' | 'granted' | 'limited' | 'loading';

const AppCompanyProfileSettingScreen: React.FC = () => {
	const [locationStatus, setLocationStatus] = useState<PermissionStatus>('loading');
	const [mediaStatus, setMediaStatus] = useState<PermissionStatus>('loading');
	const [notificationStatus, setNotificationStatus] = useState<PermissionStatus>('loading');

	const locationValue = useSharedValue(0);
	const mediaValue = useSharedValue(0);
	const notificationValue = useSharedValue(0);

	// Helper: update shared values based on status
	const updateSharedValue = (status: PermissionStatus, sharedValue: any) => {
		sharedValue.value =
			status === RESULTS.GRANTED || status === RESULTS.LIMITED || status === RESULTS.UNAVAILABLE ? 1 : 0;
	};

	// Permissions constants
	const locationPermission =
		Platform.OS === 'ios' ? PERMISSIONS.IOS.LOCATION_WHEN_IN_USE : PERMISSIONS.ANDROID.ACCESS_FINE_LOCATION;
	const mediaPermission =
		Platform.OS === 'ios' ? PERMISSIONS.IOS.PHOTO_LIBRARY : PERMISSIONS.ANDROID.READ_EXTERNAL_STORAGE;

	const checkAllPermissions = async () => {
		try {
			const locStatus = await check(locationPermission);
			setLocationStatus(locStatus);
			updateSharedValue(locStatus, locationValue);

			const medStatus = await check(mediaPermission);
			setMediaStatus(medStatus);
			updateSharedValue(medStatus, mediaValue);

			const { status: notiStatus } = await checkNotifications();
			setNotificationStatus(notiStatus as PermissionStatus);
			updateSharedValue(notiStatus as PermissionStatus, notificationValue);
		} catch (error) {
			console.error('Error checking permissions', error);
		}
	};

	useEffect(() => {
		checkAllPermissions();
	}, []);

	// Request a permission
	const requestPermission = async (permission: string) => {
		try {
			const result = await request(permission as Permission);
			return result;
		} catch (error) {
			console.error('Error requesting permission', error);
			return 'denied';
		}
	};

	// Handle toggling permission for location or media
	const handleTogglePermission = async (
		currentValue: number,
		permission: string,
		setStatus: React.Dispatch<React.SetStateAction<PermissionStatus>>,
		sharedValue: any,
	) => {
		if (currentValue === 0) {
			// Not granted, request permission
			const result = await requestPermission(permission);
			setStatus(result as PermissionStatus);
			updateSharedValue(result as PermissionStatus, sharedValue);
		} else {
			// Granted, can't revoke programmatically, prompt to open settings
			Alert.alert(
				'Revoke Permission',
				'To revoke this permission, please go to app settings.',
				[
					{ text: 'Cancel', style: 'cancel' },
					{
						text: 'Open Settings',
						onPress: () => {
							openSettings().catch(() => {
								Alert.alert('Unable to open settings');
							});
						},
					},
				],
				{ cancelable: true },
			);
		}
	};

	// Handle toggle for notifications (different API)
	const handleToggleNotification = async (currentValue: number) => {
		if (currentValue === 0) {
			if (Platform.OS === 'ios') {
				const { status } = await requestNotifications(['alert', 'sound', 'badge']);
				setNotificationStatus(status as PermissionStatus);
				updateSharedValue(status as PermissionStatus, notificationValue);
			} else if (Platform.OS === 'android') {
				// Android 13+ permission request remains same
				const androidNotifPerm = PERMISSIONS.ANDROID.POST_NOTIFICATIONS;
				try {
					const result = await request(androidNotifPerm);
					setNotificationStatus(result as PermissionStatus);
					updateSharedValue(result as PermissionStatus, notificationValue);
				} catch {
					Alert.alert('Failed to request notifications permission');
				}
			}
		} else {
			Alert.alert(
				'Revoke Permission',
				'To revoke this permission, please go to app settings.',
				[
					{ text: 'Cancel', style: 'cancel' },
					{
						text: 'Open Settings',
						onPress: () => {
							openSettings().catch(() => {
								Alert.alert('Unable to open settings');
							});
						},
					},
				],
				{ cancelable: true },
			);
		}
	};

	return (
		<View style={styles.container}>
			<PalRiderText style={styles.title}>Permissions Allowed</PalRiderText>

			<View style={styles.permissionRow}>
				<PalRirderSwitch
					value={locationValue}
					onPress={() =>
						handleTogglePermission(locationValue.value, locationPermission, setLocationStatus, locationValue)
					}
					textComponent={<PalRiderText>Location</PalRiderText>}
				/>
			</View>

			<View style={styles.permissionRow}>
				<PalRirderSwitch
					value={mediaValue}
					onPress={() => handleTogglePermission(mediaValue.value, mediaPermission, setMediaStatus, mediaValue)}
					textComponent={<PalRiderText>Media</PalRiderText>}
				/>
			</View>

			<View style={styles.permissionRow}>
				<PalRirderSwitch
					value={notificationValue}
					onPress={() => handleToggleNotification(notificationValue.value)}
					textComponent={<PalRiderText>Notifications</PalRiderText>}
				/>
			</View>
		</View>
	);
};

const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.white,
		padding: 16,
	},
	title: {
		fontWeight: '700',
		fontSize: 18,
		marginBottom: 24,
	},
	permissionRow: {
		marginBottom: 20,
	},
});

export default AppCompanyProfileSettingScreen;
