import React from 'react';
import { ListRenderItemInfo, StyleSheet, View } from 'react-native';
import PalRiderText from '@/components/PalRiderText';
import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { font, PADDING } from '@/theme/responsive';
import { OrderDTO } from 'palriderapptypes/order';
import { priceFormat } from '@/utils';

const CompanyNearbyOrderOrderBonusesModal = (prop: ListRenderItemInfo<OrderDTO>) => {
	const bonuses = prop.item.order_bonuses;

	return (
		<View style={styles.bonusContainer}>
			{prop.item.order_bonus_type == 'none' && (
				<View>
					<PalRiderText>No order bonues</PalRiderText>
				</View>
			)}
			<View style={{ flex: 1 }}>
				<View style={{ flexDirection: 'row' }}>
					<View style={styles.bonusItemHeader}>
						<PalRiderText>From</PalRiderText>
					</View>
					<View style={styles.bonusItemHeader}>
						<PalRiderText>To</PalRiderText>
					</View>
					<View style={styles.bonusItemHeader}>
						<PalRiderText>Price</PalRiderText>
					</View>
				</View>
				{bonuses &&
					bonuses.length > 0 &&
					bonuses.map((order_bonus) => (
						<View key={order_bonus.id} style={{ flexDirection: 'row' }}>
							<View style={styles.bonusItem}>
								<PalRiderText style={styles.bonusItemText}>
									{order_bonus.min_value} {prop.item.order_bonus_type == 'by_distance' ? 'Mile' : 'Shipment'}
								</PalRiderText>
							</View>
							<View style={styles.bonusItem}>
								<PalRiderText style={styles.bonusItemText}>
									{order_bonus.max_value} {prop.item.order_bonus_type == 'by_distance' ? 'Mile' : 'Shipment'}
								</PalRiderText>
							</View>
							<View style={styles.bonusItem}>
								<PalRiderText style={styles.bonusItemText}>{priceFormat(order_bonus.price)}</PalRiderText>
							</View>
						</View>
					))}
			</View>
		</View>
	);
};

const styles = StyleSheet.create({
	bonusContainer: {
		height: '100%',

		shadowColor: colors.gray[200],
		shadowOffset: {
			width: 0,
			height: 0,
		},
		shadowOpacity: 0.3,
		shadowRadius: 3,
	},
	bonusItemHeader: {
		flex: 1,
		alignItems: 'center',
		padding: PADDING.medium,
	},
	bonusItem: {
		flex: 1,
		alignItems: 'center',
		padding: PADDING.medium,
		backgroundColor: colors.orange[600],
		paddingVertical: PADDING.xlarge,
	},
	bonusItemText: {
		color: colors.white,
		fontFamily: FontFamily.Semibold,
		fontSize: font.mini,
	},
});

export default CompanyNearbyOrderOrderBonusesModal;
