import { createApi } from '@reduxjs/toolkit/query/react';
import { PaginationDataResultT, SuccessfulResponse, SuccessfulResponseT } from 'palriderapptypes';
import {
	CompanyAreaAddressDocumentDTO,
	CompanyAreaAddressDTO,
	CompanyAreaAddressPhotoDTO,
	CompanyAreaAddressWalletDTO,
	CreateCompanyAreaAddressRequestDTO,
	UpdateCompanyAreaAddressRequestDTO,
} from 'palriderapptypes/company';
import { PaginationRequestDTO } from 'palriderapptypes/common';

import { baseQueryConfigWithReAuth } from 'src/services/api/baseQueryConfig.ts';

export const companyAreaAddressApi = createApi({
	reducerPath: 'companyAreaAddress',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		getAllCompanyAreaAddresses: builder.query<PaginationDataResultT<CompanyAreaAddressDTO>, PaginationRequestDTO>({
			query({ page, size }) {
				return {
					url: `company-area-address?page=${page}&size=${size}`,
					method: 'GET',
				};
			},
		}),
		getCompanyAreaAddress: builder.query<SuccessfulResponseT<CompanyAreaAddressDTO>, string>({
			query(company_area_address_id) {
				return {
					url: `company-area-address/${company_area_address_id}`,
					method: 'GET',
				};
			},
		}),

		getCompanyAreaAddressWalletList: builder.query<PaginationDataResultT<CompanyAreaAddressWalletDTO>, string>({
			query(company_area_address_id) {
				return {
					url: `company-area-address/${company_area_address_id}/wallets?page=1&size=100`,
					method: 'GET',
				};
			},
		}),

		getCompanyAreaAddressDocuments: builder.query<PaginationDataResultT<CompanyAreaAddressDocumentDTO>, string>({
			query(company_area_address_id) {
				return {
					url: `company-area-address/${company_area_address_id}/documents`,
					method: 'GET',
				};
			},
		}),
		getCompanyAreaAddressPhotos: builder.query<PaginationDataResultT<CompanyAreaAddressPhotoDTO>, string>({
			query(company_area_address_id) {
				return {
					url: `company-area-address/${company_area_address_id}/photos?page=1&size=100`,
					method: 'GET',
				};
			},
		}),
		storeCompanyAreaAddress: builder.mutation<
			SuccessfulResponseT<CompanyAreaAddressDTO>,
			CreateCompanyAreaAddressRequestDTO
		>({
			query(body) {
				const formData = new FormData();
				formData.append('address', body.address);
				formData.append('building_name_or_number', body.building_name_or_number);
				formData.append('directions', body.directions);
				formData.append('latitude', body.latitude);
				formData.append('longitude', body.longitude);
				formData.append('post_code', body.post_code);
				formData.append('phone', body.phone);
				formData.append('company_area_name', body.company_area_name);

				for (let i = 0; i < body.address_documents.length; i++) {
					formData.append('address_documents', body.address_documents[i]);
				}
				for (let i = 0; i < body.address_photos.length; i++) {
					formData.append('address_photos', body.address_photos[i]);
				}
				return {
					method: 'POST',
					url: `company-area-address`,
					headers: {
						'Content-Type': 'multipart/form-data',
					},
					body: formData,
				};
			},
		}),
		updateCompanyAreaAddress: builder.mutation<
			SuccessfulResponseT<CompanyAreaAddressDTO>,
			UpdateCompanyAreaAddressRequestDTO
		>({
			query(body) {
				return {
					method: 'PATCH',
					url: `company-area-address/${body.company_area_address_id}`,
					body,
				};
			},
		}),
		deleteCompanyAreaAddress: builder.mutation<SuccessfulResponse, { company_area_address_id: string }>({
			query(body) {
				return {
					method: 'DELETE',
					url: `company-area-address/${body.company_area_address_id}`,
				};
			},
		}),
	}),
});

export const {
	useLazyGetAllCompanyAreaAddressesQuery,
	useGetCompanyAreaAddressQuery,
	useGetCompanyAreaAddressWalletListQuery,
	useLazyGetCompanyAreaAddressQuery,
	useLazyGetCompanyAreaAddressDocumentsQuery,
	useLazyGetCompanyAreaAddressPhotosQuery,
	useStoreCompanyAreaAddressMutation,
	useUpdateCompanyAreaAddressMutation,
	useDeleteCompanyAreaAddressMutation,
} = companyAreaAddressApi;
