import React, { useState, ReactNode, FC } from 'react';
import { Modal, View, Text, TouchableOpacity, StyleSheet, Dimensions } from 'react-native';
import { font, PADDING } from '@/theme/responsive.ts';
import { FontFamily } from '@/theme/fonts.ts';
import PalRiderText from './PalRiderText';

interface PalRiderPopupMenuProps {
	trigger: ReactNode;
	children: (closeModal: () => void) => ReactNode;
}

interface MenuItemProps {
	text: string;
	onPress: () => void;
}

const PalRiderPopupMenu: FC<PalRiderPopupMenuProps> & {
	MenuItem: FC<MenuItemProps>;
} = ({ trigger, children }) => {
	const [visible, setVisible] = useState(false);
	const [triggerLayout, setTriggerLayout] = useState({ x: 0, y: 0, width: 0, height: 0 });

	const openModal = () => {
		triggerRef.current?.measureInWindow((x: number, y: number, width: number, height: number) => {
			setTriggerLayout({ x, y, width, height });
			setVisible(true);
		});
	};
	const closeModal = () => setVisible(false);

	const triggerRef = React.createRef<View>();
	const { width: screenWidth, height: screenHeight } = Dimensions.get('window');

	return (
		<View>
			<TouchableOpacity ref={triggerRef} onPress={openModal}>
				{trigger}
			</TouchableOpacity>
			<Modal transparent visible={visible} animationType="none">
				<TouchableOpacity style={styles.overlay} onPress={closeModal}>
					<View
						style={[
							styles.menu,
							{
								top: Math.min(triggerLayout.y + triggerLayout.height, screenHeight - 50),
								left: Math.min(triggerLayout.x, screenWidth - 250),
							},
						]}
					>
						{children(closeModal)}
					</View>
				</TouchableOpacity>
			</Modal>
		</View>
	);
};

const MenuItem: FC<MenuItemProps> = ({ text, onPress }) => {
	return (
		<TouchableOpacity onPress={onPress} style={styles.menuItem}>
			<PalRiderText fontSize={font.mini} fontFamily={FontFamily.Semibold} style={styles.menuItemText}>
				{text}
			</PalRiderText>
		</TouchableOpacity>
	);
};

PalRiderPopupMenu.MenuItem = MenuItem;

const styles = StyleSheet.create({
	overlay: {
		flex: 1,
	},
	menu: {
		position: 'absolute',
		minWidth: 250,
		width: 'auto',
		backgroundColor: 'white',
		borderRadius: 10,
		padding: 10,
		elevation: 5, // for Android shadow
		shadowColor: '#000', // for iOS shadow
		shadowOffset: { width: 0, height: 2 }, // for iOS shadow
		shadowOpacity: 0.25, // for iOS shadow
		shadowRadius: 3.84, // for iOS shadow
	},
	menuItem: {
		padding: PADDING.medium,
	},
	menuItemText: {
		fontSize: font.small,
		fontFamily: FontFamily.Semibold,
	},
});

export default PalRiderPopupMenu;
