import React, { useCallback, useMemo } from 'react';
import { useLazyAbondonOrderQuery, useLazyGetOrderQuery } from '@/services/api/order';
import colors from '@/theme/colors';
import { useEffect, useRef, useState } from 'react';
import { ActivityIndicator, Pressable, StyleSheet, View } from 'react-native';
import MapView, { Marker } from 'react-native-maps';
import BottomSheet, { BottomSheetView } from '@gorhom/bottom-sheet';
import PalRiderText from '@/components/PalRiderText';
import LottieView from 'lottie-react-native';
import PalRiderSwipeButton from '@/components/PalRiderSwipeButton';
import PalRiderButton from '@/components/PalRiderButton';
import { font, PADDING } from '@/theme/responsive';
import { buttonStyling } from '@/theme/defaults';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { FontFamily } from '@/theme/fonts';
import { useLazyGetUserQuery } from '@/services/api/user';
import { CompositeScreenProps, StackActions, useFocusEffect } from '@react-navigation/native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { useModal } from '@/components/ModalProvider';
import { OrderDTO } from 'palriderapptypes/order';
import { AppOrderStackParamList } from '@/navigation/order-navigation';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { RootStackParamList } from '@/navigation';
import { useAppDispatch, useAppSelector } from '@/redux/hooks';
import useUserNavigation from '@/hooks/useUserNavigation';
import { setToken } from '@/redux/slices/userSlice';
import { useOrderHub } from '@/hooks/useOrderHub';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import Icon from '@/components/Icon';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppOrderStackParamList, 'OrderArriveWaiting'>,
	CompositeScreenProps<NativeStackScreenProps<AppOrderStackParamList>, NativeStackScreenProps<RootStackParamList>>
>;
const AppOrderArriveWaitingScreen: React.FC<Props> = ({ route, navigation }) => {
	const user = useAppSelector((x) => x.userSlice);
	const [order, setOrder] = useState<OrderDTO | null>(null);
	const [isLoadingOrder, setIsLoadingOrder] = useState(true);
	const [getUser] = useLazyGetUserQuery();
	const [abondonOrder] = useLazyAbondonOrderQuery();
	const [getOrder] = useLazyGetOrderQuery();
	const [loadingCourier, setLoadingCourier] = useState(false);
	const dispatch = useAppDispatch();
	const { handle: hanldeLogoutNavigation } = useUserNavigation();

	const handleLogout = async () => {
		dispatch(setToken(null));
		await AsyncStorage.removeItem('token');
		await hanldeLogoutNavigation();
	};

	const mapRef = useRef<MapView>(null);
	const bottomSheetModalRef = useRef<BottomSheet>(null);
	const insets = useSafeAreaInsets();

	const { hideGlobalModal, showGlobalModal } = useModal();

	// 🧠 order yükleme
	const loadOrder = useCallback(async () => {
		setIsLoadingOrder(true);
		try {
			const res = await getOrder(route.params.order_id).unwrap();
			setOrder(res.data);
		} catch (err) {
			console.error('Order load error', err);
		} finally {
			setIsLoadingOrder(false);
		}
	}, [getOrder, route.params.order_id]);

	const loadCourier = useCallback(async () => {
		setLoadingCourier(true);
		try {
			const res = await getUser().unwrap();
			const courier = res.data.courier;
			if (courier?.current_active_order_id) {
				showGlobalModal({
					children: <SuccessModal text={'Your request accepted, you can work now'} />,
					closeAfterDelay: 1000,
					async whenClose() {
						await AsyncStorage.setItem('current_active_order_id', courier.current_active_order_id);
						navigation.navigate('AppOrderStack', {
							screen: 'ActiveOrderStack',
							params: {
								screen: 'Home',
								params: { order_id: courier.current_active_order_id },
							},
						});
					},
				});
			}
		} catch (e) {
			console.log('Courier fetch error', e);
		} finally {
			setLoadingCourier(false);
		}
	}, [getUser, navigation]);

	useEffect(() => {
		loadOrder();
	}, [loadOrder]);

	const { joinOrderRoom, leaveOrderRoom } = useOrderHub(user.token!, loadCourier);

	// Join a room for a specific order
	useEffect(() => {
		if (!order?.id) return;
		joinOrderRoom(order.id);

		return () => {
			leaveOrderRoom(order?.id);
		};
	}, [order]);

	// 📍 Harita pozisyonu
	const region = useMemo(
		() => ({
			latitude: order?.company_area_address?.latitude ?? 0,
			longitude: order?.company_area_address?.longitude ?? 0,
			latitudeDelta: 0.1,
			longitudeDelta: 0.1,
		}),
		[order],
	);

	const handleAbondon = useCallback(() => {
		if (!order) return;
		showGlobalModal({
			maxHeight: 200,
			children: (
				<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', gap: PADDING.large }}>
					<Icon name="CloseIconSvg" width={32} height={32} color={colors.red[600]} />
					<PalRiderText>Abondoning order please wait...</PalRiderText>
				</View>
			),
		});
		abondonOrder(order.id)
			.unwrap()
			.then(() => {
				setTimeout(() => {
					hideGlobalModal();
					navigation.dispatch(
						StackActions.replace('AppStack', {
							screen: 'AppCourierStack',
							params: { screen: 'Home' },
						}),
					);
				}, 2000);
			})
			.catch(() => {
				showGlobalModal({
					maxHeight: 200,
					children: (
						<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', gap: PADDING.large }}>
							<Icon name="CloseIconSvg" width={32} height={32} color={colors.red[600]} />
							<PalRiderText>Cannot abondoning order, please call customer service.</PalRiderText>
						</View>
					),
				});
			});
	}, [order, abondonOrder, hideGlobalModal, navigation, showGlobalModal]);

	if (!order && !isLoadingOrder) {
		return (
			<View style={[styles.container, { justifyContent: 'center', alignItems: 'center', gap: PADDING.large }]}>
				<PalRiderText>Order Cannot Load</PalRiderText>
				<PalRiderButton style={buttonStyling.dark} onPress={loadOrder}>
					<PalRiderText color={colors.white}>Reload</PalRiderText>
				</PalRiderButton>
			</View>
		);
	}

	return (
		<View style={styles.container}>
			{order && (
				<MapView
					ref={mapRef}
					provider="google"
					style={StyleSheet.absoluteFillObject}
					userInterfaceStyle="light"
					region={region}
					onMapLoaded={() => {
						mapRef.current?.animateToRegion(region);
					}}
				>
					<Marker coordinate={region} />
				</MapView>
			)}
			<View style={{ flex: 1, paddingBottom: insets.bottom }}>
				<BottomSheet
					ref={bottomSheetModalRef}
					snapPoints={[]}
					enableDynamicSizing
					enablePanDownToClose={false}
					animateOnMount
					index={0}
					handleComponent={null}
				>
					<BottomSheetView style={{ paddingBottom: insets.bottom, flex: 1 }}>
						<View style={{ height: 500, paddingHorizontal: PADDING.large }}>
							{loadingCourier && <ActivityIndicator size="large" color={colors.black} />}
							{!isLoadingOrder && (
								<View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}>
									<LottieView
										style={{ width: 200, height: 300, paddingVertical: PADDING.xxlarge }}
										source={require('@/assets/animations/courier-waiting-approval-animation.json')}
										autoPlay
										loop
									/>
								</View>
							)}
							<View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}>
								<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.mini}>
									Waiting For Company Approval
								</PalRiderText>
								<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.mini}>
									#{order?.order_no}
								</PalRiderText>
							</View>
							<PalRiderSwipeButton
								swipeText="Abondon Order"
								swipedText="I'm abondoning this order"
								firstColor={colors.red[200]}
								secondColor={colors.red[600]}
								swipeColor={colors.red[600]}
								button={
									<Pressable>
										<Icon name="ChevronRightIconSvg" color={colors.white} width={20} height={20} />
									</Pressable>
								}
								onSwipe={handleAbondon}
							/>

							<PalRiderButton variant="warning" onPress={handleLogout} style={{ marginTop: PADDING.medium }}>
								<PalRiderText color={colors.white} fontFamily={FontFamily.Semibold}>
									Logout
								</PalRiderText>
							</PalRiderButton>
						</View>
					</BottomSheetView>
				</BottomSheet>
			</View>
		</View>
	);
};
const styles = StyleSheet.create({
	container: {
		flex: 1,
	},
	loadingContainer: {
		padding: PADDING.large,
		flex: 1,
		borderRadius: PADDING.large,
		gap: PADDING.large,
		justifyContent: 'center',
		alignItems: 'center',
	},
});

export default AppOrderArriveWaitingScreen;
