import React, { createContext, ReactNode, useContext } from 'react';
import { StyleSheet, Text, TouchableOpacity, View } from 'react-native';

interface RadioGroupContextProps {
	selectedValue: string | null;
}

const RadioGroupContext = createContext<RadioGroupContextProps | undefined>(undefined);

interface RadioGroupProps {
	value: string | null;
	children: (value: string | null) => React.ReactElement;
}

const PalRiderRadio: React.FC<RadioGroupProps> = ({ value, children }) => {
	return (
		<RadioGroupContext.Provider value={{ selectedValue: value }}>
			<View style={styles.radioGroup}>{children(value)}</View>
		</RadioGroupContext.Provider>
	);
};

interface RadioButtonProps {
	label: string;
	value: string;
	children?: ReactNode;
}

const styles = StyleSheet.create({
	radioGroup: {},
	radioButton: {
		flexDirection: 'row',
		alignItems: 'center',
		marginBottom: 10,
	},
	radioCircle: {
		height: 20,
		width: 20,
		borderRadius: 10,
		borderWidth: 2,
		borderColor: '#000',
		alignItems: 'center',
		justifyContent: 'center',
	},
	selectedRadioCircle: {
		backgroundColor: '#000',
	},
	radioLabel: {
		marginLeft: 10,
		fontSize: 16,
	},
});

export { PalRiderRadio };
