import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { CreateOrderShipmentDestinationRequestDTO, CreateOrderShipmentRequestDTO } from 'palriderapptypes/order';

type CombinedRequestType = CreateOrderShipmentRequestDTO & {
	order_id: string;
	courier_id: string;
	notes: string;
	overview_polyline: string;
	departure: {
		company_area_address_id: string;
	};
};
export const createOrderShipmentInitialState: CombinedRequestType = {
	order_id: '',
	courier_id: '',
	notes: '',
	overview_polyline: '',
	departure: {
		company_area_address_id: '',
	},
	destinations: [],
};
const createOrderShipmentSlice = createSlice({
	name: 'createOrderShipmentSlice',
	initialState: createOrderShipmentInitialState,
	reducers: {
		setCreateOrderShipment: (_, action: PayloadAction<CombinedRequestType>) => {
			return {
				...action.payload,
			};
		},
		setCreateOrderShipmentAddDestination: (state, action: PayloadAction<CreateOrderShipmentDestinationRequestDTO>) => {
			return {
				...state,
				destinations: [...state.destinations, action.payload],
			};
		},
		removeCreateOrderShipmentDestination: (state, action: PayloadAction<number>) => {
			return {
				...state,
				destinations: state.destinations.filter((_, index) => index != action.payload),
			};
		},
	},
});
export const { setCreateOrderShipmentAddDestination, setCreateOrderShipment, removeCreateOrderShipmentDestination } =
	createOrderShipmentSlice.actions;
export default createOrderShipmentSlice.reducer;
