import { createApi } from '@reduxjs/toolkit/query/react';
import { PaginationDataResultT, SuccessfulResponse, SuccessfulResponseT } from 'palriderapptypes';
import { PaginationRequestDTO } from 'palriderapptypes/common';
import {
	CompanyAreaAddressWalletDTO,
	CompanyAreaAddressWalletTransactionDTO,
	CompanyWalletTransferRequestDTO,
	UpdateCompanyAreaAddressWalletRequestDTO,
} from 'palriderapptypes/company';
import { baseQueryConfigWithReAuth } from 'src/services/api/baseQueryConfig.ts';

export const companyAreaAddressWalletApi = createApi({
	reducerPath: 'companyAreaAddressWallet',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		getCompanyAreaAddressWallet: builder.query<SuccessfulResponseT<CompanyAreaAddressWalletDTO>, string>({
			query(company_area_address_wallet_id) {
				return {
					url: `company-area-address-wallet/${company_area_address_wallet_id}`,
					method: 'GET',
				};
			},
		}),
		getCompanyAreaAddressWalletTransactionList: builder.query<
			PaginationDataResultT<CompanyAreaAddressWalletTransactionDTO>,
			PaginationRequestDTO & { company_area_address_wallet_id: string }
		>({
			query(body) {
				return {
					url: `company-area-address-wallet/${body.company_area_address_wallet_id}/wallet-transaction-list?page=${body.page}&size=${body.size}`,
					method: 'GET',
				};
			},
		}),
		getCompanyAreaAddressWalletTransferRequestList: builder.query<
			PaginationDataResultT<CompanyWalletTransferRequestDTO>,
			PaginationRequestDTO & { company_area_address_wallet_id: string }
		>({
			query(body) {
				return {
					url: `company-area-address-wallet/${body.company_area_address_wallet_id}/transfer-requests?page=${body.page}&size=${body.size}`,
					method: 'GET',
				};
			},
		}),
		addNewBalance: builder.mutation<SuccessfulResponse, number>({
			query(body) {
				return {
					url: `company-area/add-new-balance`,
					method: 'POST',
					body: {
						amount: body,
					},
				};
			},
		}),
		addCompanyAreaAddressWallet: builder.mutation<
			SuccessfulResponse,
			{ name: string; company_area_address_id: string }
		>({
			query(body) {
				return {
					url: `company-area-address-wallet`,
					method: 'POST',
					body: {
						name: body.name,
						company_area_address_id: body.company_area_address_id,
					},
				};
			},
		}),
		updateCompanyAreaAddressWallet: builder.mutation<
			SuccessfulResponse,
			{ name: string; company_area_address_wallet_id: string }
		>({
			query(body) {
				return {
					url: `company-area-address-wallet/${body.company_area_address_wallet_id}`,
					method: 'PUT',
					body,
				};
			},
		}),
		deleteCompanyAreaAddressWallet: builder.mutation<SuccessfulResponse, { company_area_address_wallet_id: string }>({
			query(body) {
				return {
					url: `company-area-wallet/${body.company_area_address_wallet_id}`,
					method: 'DELETE',
					body,
				};
			},
		}),
	}),
});

export const {
	useLazyGetCompanyAreaAddressWalletQuery,
	useAddNewBalanceMutation,
	useAddCompanyAreaAddressWalletMutation,
	useDeleteCompanyAreaAddressWalletMutation,
	useLazyGetCompanyAreaAddressWalletTransactionListQuery,
	useUpdateCompanyAreaAddressWalletMutation,
	useLazyGetCompanyAreaAddressWalletTransferRequestListQuery,
} = companyAreaAddressWalletApi;
