import PalRiderText from '@/components/PalRiderText.tsx';
import PalRiderTextInput from '@/components/PalRiderTextInput.tsx';
import { useLazyGetAllCompanyCategoriesQuery } from '@/services/api/company/company-category.ts';
import colors from '@/theme/colors.ts';
import { FontFamily } from '@/theme/fonts.ts';
import { normalize, PADDING } from '@/theme/responsive.ts';
import { yupTyped } from '@/types';
import { useFormik } from 'formik';
import React, { useEffect } from 'react';
import { KeyboardAvoidingView, Platform, StyleSheet, View } from 'react-native';
import { useAppDispatch, useAppSelector } from '@/redux/hooks.ts';
import { string } from 'yup';
import { SafeAreaView } from 'react-native-safe-area-context';
import { setCompanyInfoOnboardingState } from '@/redux/slices/company-onboarding.ts';
import { globalStyles } from '@/utils/global-styles';
import { useModal } from '@/components/ModalProvider';
import WarningModal from '@/components/custom-modal/WarningModal';
import Dropdown from 'react-native-input-select';
import PalRiderButton from '@/components/PalRiderButton';
import { ScrollView } from 'react-native-gesture-handler';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { safeAreaEdges } from '@/utils';
import { OnboardingCompanyInfoRequestDTO } from 'palriderapptypes/company';
import { useTranslation } from 'react-i18next';

const SignUpCompanyInfoStep: React.FC<{ nextStep: () => void }> = ({ nextStep }) => {
	const { t } = useTranslation();
	const companyOnboardingSelector = useAppSelector((x) => x.companyOnboardingSlice.company);
	const dispatch = useAppDispatch();
	const { showGlobalModal, hideGlobalModal } = useModal();
	const [getCompanyCategories, { data: companyCategories }] = useLazyGetAllCompanyCategoriesQuery();
	const companyOnboardingInfoFormik = useFormik<OnboardingCompanyInfoRequestDTO>({
		initialValues: {
			name: companyOnboardingSelector.name,
			official_name: companyOnboardingSelector.official_name,
			company_category_id: companyOnboardingSelector.company_category_id,
		},
		validateOnChange: false,
		validateOnBlur: false,
		validationSchema: yupTyped<OnboardingCompanyInfoRequestDTO>({
			company_category_id: string()
				.required(t('validation.required', 'Required', { field: t('common.company_category') }))
				.min(3),
			name: string()
				.required(t('validation.required', { field: t('common.name') }))
				.max(255, t('validation.max', { field: t('common.name'), max: 255 }))
				.min(3, t('validation.min', { field: t('common.name'), min: 3 })),
			official_name: string()
				.required(t('validation.required', { field: t('common.official_name') }))
				.max(255, t('validation.max', { field: t('common.official_name'), max: 255 }))
				.min(3, t('validation.min', { field: t('common.official_name'), min: 3 })),
		}),
		onSubmit: async (values) => {
			try {
				showGlobalModal({
					children: <LoadingModal />,
					backgroundColor: colors.transparent,
				});
				dispatch(setCompanyInfoOnboardingState(values));
				nextStep();
				hideGlobalModal();
			} catch {
				showGlobalModal({
					children: <WarningModal text={t('error.cannot_save_changes')} />,
					closeAfterDelay: 1500,
				});
			}
		},
	});
	useEffect(() => {
		getCompanyCategories({
			page: 1,
			size: 100,
		});
	}, []);
	return (
		<SafeAreaView style={styles.safeAreaContainer} edges={safeAreaEdges}>
			<KeyboardAvoidingView
				style={styles.container}
				behavior={Platform.OS === 'ios' ? 'padding' : undefined}
				keyboardVerticalOffset={Platform.OS === 'ios' ? 0 : 20} // optional tweak
			>
				<ScrollView keyboardShouldPersistTaps="handled">
					<View
						style={{
							flex: 1,
							rowGap: PADDING.large,
						}}
					>
						<PalRiderTextInput
							title={'Company Name'}
							onChangeText={companyOnboardingInfoFormik.handleChange('name')}
							value={companyOnboardingInfoFormik.values.name}
							onBlur={companyOnboardingInfoFormik.handleBlur('name')}
							error={companyOnboardingInfoFormik.errors.name}
							required
						/>
						<PalRiderTextInput
							title={'Company Official Name'}
							onChangeText={companyOnboardingInfoFormik.handleChange('official_name')}
							value={companyOnboardingInfoFormik.values.official_name}
							error={companyOnboardingInfoFormik.errors.official_name}
							onBlur={companyOnboardingInfoFormik.handleBlur('official_name')}
							required
						/>

						<View>
							<View style={{ flexDirection: 'row', columnGap: normalize(2) }}>
								<PalRiderText style={styles.titleText}>{t('common.company_category')}</PalRiderText>
							</View>

							<Dropdown
								{...globalStyles.dropdownProps}
								options={
									companyCategories?.data.map((category) => ({
										value: category.id,
										label: category.name,
									})) ?? []
								}
								isSearchable
								isMultiple={false}
								selectedValue={companyOnboardingInfoFormik.values.company_category_id}
								onValueChange={(value) => companyOnboardingInfoFormik.setFieldValue('company_category_id', value)}
								maxSelectableItems={1}
							/>
							{companyOnboardingInfoFormik.errors.company_category_id && (
								<PalRiderText style={globalStyles.errorTextStyle}>
									{companyOnboardingInfoFormik.errors.company_category_id}
								</PalRiderText>
							)}
						</View>
					</View>
				</ScrollView>
				<PalRiderButton variant="dark" onPress={() => companyOnboardingInfoFormik.handleSubmit()}>
					<PalRiderText color={colors.white}>{t('common.continue')}</PalRiderText>
				</PalRiderButton>
			</KeyboardAvoidingView>
		</SafeAreaView>
	);
};
const styles = StyleSheet.create({
	safeAreaContainer: {
		flex: 1,
		backgroundColor: colors.white,
	},
	container: {
		backgroundColor: colors.white,
		padding: PADDING.large,
		flex: 1,
	},
	selectInput: {
		minHeight: normalize(40),
		borderWidth: 1,
		borderRadius: normalize(8),
		backgroundColor: colors.gray[100],
		paddingHorizontal: PADDING.large,
		borderColor: colors.gray[300],
		justifyContent: 'center',
	},
	selectInputIos: {
		minHeight: normalize(40),
		borderWidth: 1,
		borderRadius: normalize(8),
		backgroundColor: colors.gray[100],
		justifyContent: 'center',
		paddingHorizontal: PADDING.large,
		borderColor: colors.gray[300],
	},
	titleText: {
		fontFamily: FontFamily.Semibold,
		fontSize: normalize(12),
		marginBottom: normalize(6),
		paddingLeft: normalize(4),
	},
	buttonContainer: {
		marginTop: PADDING.medium,
		width: '100%',
		zIndex: 999999,
	},

	radioButton: {
		width: 20,
		height: 20,
		borderRadius: 20 / 2,
		borderWidth: 3,
		borderColor: 'white',
	},
});
export default SignUpCompanyInfoStep;
