import colors from '@/theme/colors';
import React, { useCallback, useEffect, useRef, useState } from 'react';
import { StyleSheet, TouchableOpacity, View } from 'react-native';
import { PADDING } from '@/theme/responsive.ts';
import CompanyAppOrders from '@/screens/app/company/orders/tabs/CompanyAppOrders';
import PalRiderButton from '@/components/PalRiderButton';
import { buttonStyling } from '@/theme/defaults';
import PalRiderText from '@/components/PalRiderText';
import { CompositeScreenProps, useFocusEffect } from '@react-navigation/native';
import { AppCompanyOrderParamList, AppCompanyTabParamList } from '@/navigation/company-navigation';
import { RootStackParamList } from '@/navigation';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { useTranslation } from 'react-i18next';
import { BottomSheetModal } from '@gorhom/bottom-sheet';
import AppCompanyOrdersHomeFilterModal from './filter';
import { DateType } from 'react-native-ui-datepicker';
import Icon from '@/components/Icon';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyOrderParamList, 'CompanyOrderHome'>,
	CompositeScreenProps<
		BottomTabScreenProps<AppCompanyTabParamList, 'CompanyOrderStack'>,
		NativeStackScreenProps<RootStackParamList>
	>
>;

const AppCompanyOrdersHomeScreen: React.FC<Props> = ({ navigation }) => {
	const { t } = useTranslation();
	const filterBottomSheet = useRef<BottomSheetModal>(null);
	const [filtering, setFiltering] = useState<{
		status: string;
		company_area_id: string | null;
		company_area_address_id: string | null;
		order_start_date: DateType | undefined;
		order_end_date: DateType | undefined;
		order_no: string;
	}>({
		status: 'all',
		company_area_id: null,
		company_area_address_id: null,
		order_start_date: undefined,
		order_end_date: undefined,
		order_no: '',
	});
	const handleCreateOrder = () => {
		navigation.navigate('AppCompanyStack', {
			screen: 'CompanyOrderStack',
			params: {
				screen: 'CompanyCallRider',
			},
		});
	};

	useEffect(() => {
		navigation.setOptions({
			headerRight: () => (
				<View style={{ paddingRight: PADDING.large }}>
					<TouchableOpacity
						activeOpacity={0.6}
						onPress={() => {
							filterBottomSheet.current?.present();
							filterBottomSheet.current?.expand();
						}}
					>
						<PalRiderText color={colors.white}>Filter</PalRiderText>
					</TouchableOpacity>
				</View>
			),
		});
	}, []);

	useFocusEffect(
		useCallback(() => {
			navigation.getParent()?.setOptions({
				title: 'Orders',
				tabBarIcon: ({ focused }: any) => (
					<Icon name="ShippingBoxIconSvg" width={20} height={20} color={focused ? colors.orange[600] : colors.black} />
				),
			});
		}, []),
	);
	const loadFilteredOrders = async (
		status: string,
		company_area_id: string | null,
		company_area_address_id: string | null,
		order_start_date: DateType | undefined,
		order_end_date: DateType | undefined,
		order_no: string,
	) => {
		setFiltering({ status, company_area_id, company_area_address_id, order_start_date, order_end_date, order_no });
	};

	return (
		<View style={styles.container}>
			<AppCompanyOrdersHomeFilterModal filterBottomSheet={filterBottomSheet as any} filterOrders={loadFilteredOrders} />
			<CompanyAppOrders
				status={filtering.status}
				navigation={navigation}
				company_area_id={filtering.company_area_id}
				company_area_address_id={filtering.company_area_address_id}
				order_start_date={filtering.order_start_date}
				order_end_date={filtering.order_end_date}
				order_no={filtering.order_no}
				setFiltering={setFiltering}
			/>

			<View style={{ padding: PADDING.large }}>
				<PalRiderButton style={buttonStyling.dark} onPress={handleCreateOrder}>
					<PalRiderText color={colors.white}>{t('common.callrider')}</PalRiderText>
				</PalRiderButton>
			</View>
		</View>
	);
};
const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.white,
		width: '100%',
	},
});
export default AppCompanyOrdersHomeScreen;
