import React, { useCallback, useState } from 'react';
import { Linking, SectionList, StyleSheet, TouchableOpacity, View } from 'react-native';
import PalRiderText from '@/components/PalRiderText.tsx';
import { useLazyGetNotificationsQuery } from '@/services/api/notification';
import { font, PADDING } from '@/theme/responsive.ts';
import { NotificationDto, SectionListNotificationType } from '@/services/api/notification/notification-types.ts';
import colors from '@/theme/colors.ts';
import { FontFamily } from '@/theme/fonts.ts';
import { CompositeScreenProps, useFocusEffect } from '@react-navigation/native';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { RootStackParamList } from '@/navigation';
import { SafeAreaView } from 'react-native-safe-area-context';
import { AppCompanyTabParamList } from '@/navigation/company-navigation';
import { useTranslation } from 'react-i18next';
import Icon from '@/components/Icon';

type Props = CompositeScreenProps<
	BottomTabScreenProps<AppCompanyTabParamList, 'CompanyNotifications'>,
	NativeStackScreenProps<RootStackParamList>
>;

// Helper function to determine time group
const getTimeGroup = (createdAt: string): string => {
	const now = new Date();
	const notificationDate = new Date(createdAt);

	// Reset time to start of day for accurate comparison
	const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
	const yesterday = new Date(today);
	yesterday.setDate(yesterday.getDate() - 1);

	const notificationDay = new Date(
		notificationDate.getFullYear(),
		notificationDate.getMonth(),
		notificationDate.getDate(),
	);

	if (notificationDay.getTime() === today.getTime()) {
		return 'Today';
	} else if (notificationDay.getTime() === yesterday.getTime()) {
		return 'Yesterday';
	} else {
		return 'Older';
	}
};

// Helper function to group notifications by time
const groupNotificationsByTime = (notifications: NotificationDto[]): Array<SectionListNotificationType> => {
	const groups: { [key: string]: NotificationDto[] } = {
		Today: [],
		Yesterday: [],
		Older: [],
	};

	// Group notifications
	notifications.forEach((notification) => {
		const timeGroup = getTimeGroup(notification.created_at);
		groups[timeGroup].push(notification);
	});

	// Convert to section list format, only including non-empty sections
	const sections: Array<SectionListNotificationType> = [];

	if (groups.Today.length > 0) {
		sections.push({
			title: 'Today',
			data: groups.Today,
		});
	}

	if (groups.Yesterday.length > 0) {
		sections.push({
			title: 'Yesterday',
			data: groups.Yesterday,
		});
	}

	if (groups.Older.length > 0) {
		sections.push({
			title: 'Older',
			data: groups.Older,
		});
	}

	return sections;
};

const AppCompanyNotificationsScreen: React.FC<Props> = ({ navigation }) => {
	const [notifications, setNotifications] = useState<Array<SectionListNotificationType>>([]);
	const [getNotifications] = useLazyGetNotificationsQuery();

	const { t } = useTranslation();
	useFocusEffect(
		useCallback(() => {
			getNotifications({
				page_number: 1,
				page_size: 100,
			}).then((res) => {
				if (res?.data?.data) {
					// Sort notifications by created_at (newest first)
					const sortedNotifications = [...res.data.data].sort(
						(a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
					);

					// Group notifications by time
					const groupedNotifications = groupNotificationsByTime(sortedNotifications);
					setNotifications(groupedNotifications);
				}
			});
		}, [getNotifications]),
	);
	const navigateTo = (item: NotificationDto) => {
		if (item.action) {
			Linking.openURL(item.action);
		}
	};

	return (
		<SafeAreaView edges={['top']} style={styles.container}>
			<SectionList
				scrollEnabled
				sections={notifications}
				keyExtractor={(item, _) => item.id}
				contentContainerStyle={{ paddingBottom: PADDING.large, flex: 1 }}
				renderSectionHeader={({ section }) => (
					<View style={styles.section}>
						<PalRiderText fontSize={font.mini} color={colors.gray[500]} fontFamily={FontFamily.Semibold}>
							{section.title}
						</PalRiderText>
					</View>
				)}
				ListEmptyComponent={
					<View
						style={{
							flex: 1,
							justifyContent: 'center',
							alignItems: 'center',
							gap: PADDING.large,
						}}
					>
						<Icon name="NotificationIconSvg" width={40} height={40} color={colors.gray[600]} />
						<PalRiderText>{t('screen.company.notifications.no_notifications')}</PalRiderText>
					</View>
				}
				renderItem={({ item }) => (
					<TouchableOpacity activeOpacity={0.5} style={styles.item} onPress={() => navigateTo(item)}>
						<View style={{ width: 20, justifyContent: 'center' }}>
							{item.notification_type.name == 'Success' && (
								<Icon name="CheckCircleIconSvg" color={colors.green[600]} width={20} height={20} />
							)}
							{item.notification_type.name == 'Warning' && (
								<Icon name="WarningIconSvg" color={colors.orange[600]} width={20} height={20} />
							)}
							{item.notification_type.name == 'Error' && (
								<Icon name="CloseIconSvg" color={colors.red[600]} width={20} height={20} />
							)}
							{item.notification_type.name == 'Information' && (
								<Icon name="InfoIconSvg" color={colors.blue[600]} width={20} height={20} />
							)}
						</View>
						<View style={{ flex: 1 }}>
							<PalRiderText style={styles.title}>{item.title}</PalRiderText>
							<PalRiderText style={styles.description}>{item.description}</PalRiderText>
						</View>
					</TouchableOpacity>
				)}
			/>
		</SafeAreaView>
	);
};

const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.white,
	},
	section: {
		margin: PADDING.medium,
		paddingVertical: PADDING.medium,
		borderBottomWidth: 1,
		borderBottomColor: colors.gray[300],
	},
	item: {
		padding: PADDING.medium,
		flexDirection: 'row',
		gap: PADDING.medium,
		flexWrap: 'wrap',
	},
	title: {
		fontSize: font.small,
		color: colors.black,
		fontFamily: FontFamily.Semibold,
	},
	description: {
		fontSize: font.mini,
		color: colors.gray[500],
	},
	actionItem: {
		alignItems: 'center',
		justifyContent: 'center',
	},
});

export default AppCompanyNotificationsScreen;
