import { createApi } from '@reduxjs/toolkit/query/react';
import { baseQueryConfigWithReAuth } from '../baseQueryConfig';
import { OnboardCourierRequestDTO } from 'palriderapptypes/courier';
import { SuccessfulResponse, SuccessfulResponseT } from 'palriderapptypes';

export const courierApi = createApi({
	reducerPath: 'courier',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		onboardCourier: builder.mutation<SuccessfulResponse, OnboardCourierRequestDTO>({
			query(body) {
				const formData = new FormData();
				formData.append('user.name', body.user.name);
				formData.append('user.surname', body.user.surname);
				formData.append('user.birthday', body.user.birthday);

				formData.append('document.profile_photo', body.documents.profile_photo);
				formData.append('document.identity_card_front', body.documents.identity_card_front);
				formData.append('document.identity_card_back', body.documents.identity_card_back);
				formData.append('document.driver_licence_front', body.documents.driver_licence_front);
				formData.append('document.driver_licence_back', body.documents.driver_licence_back);

				for (let i = 0; i < body.vehicles.length; i++) {
					const vehicle = body.vehicles[i];
					formData.append(`vehicles[${i}].plate_number`, vehicle.plate_number);
					formData.append(`vehicles[${i}].type`, vehicle.type.toUpperCase());
					for (let j = 0; j < vehicle.photos.length; j++) {
						formData.append(`vehicles[${i}].photos`, vehicle.photos[j]);
					}
				}

				return {
					headers: {
						'Content-Type': 'multipart/form-data',
					},
					method: 'POST',
					url: 'courier/onboarding',
					body: formData,
				};
			},
		}),
		statistics: builder.query<SuccessfulResponseT<any>, void>({
			query() {
				return {
					url: 'courier/statistics',
				};
			},
		}),
	}),
});

export const { useOnboardCourierMutation, useLazyStatisticsQuery } = courierApi;
