import { FileType } from '@/@types';
import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { CreateCompanyAreaAddressRequestDTO } from 'palriderapptypes/company';
export const createCompanyAreaAddressInitialState: CreateCompanyAreaAddressRequestDTO = {
	address: '',
	building_name_or_number: '',
	directions: '',
	latitude: 0,
	longitude: 0,
	phone: '',
	post_code: '',
	company_area_name: '',
	address_documents: [],
	address_photos: [],
};

const createCompanyAreaAddressSlice = createSlice({
	name: 'companyAreaAddressCreate',
	initialState: createCompanyAreaAddressInitialState,
	reducers: {
		setCreateCompanyAreaAddress: (
			state,
			action: PayloadAction<Omit<CreateCompanyAreaAddressRequestDTO, 'address_documents' | 'address_photos'>>,
		) => {
			return {
				...state,
				...action.payload,
			};
		},
		setCreateCompanyAreaAddressDocuments: (state, action: PayloadAction<Array<FileType>>) => {
			return {
				...state,
				address_documents: action.payload,
			};
		},

		setCreateCompanyAreaAddressPhotos: (state, action: PayloadAction<Array<FileType>>) => {
			return {
				...state,
				address_photos: action.payload,
			};
		},
	},
});
export const { setCreateCompanyAreaAddress, setCreateCompanyAreaAddressDocuments, setCreateCompanyAreaAddressPhotos } =
	createCompanyAreaAddressSlice.actions;
export default createCompanyAreaAddressSlice.reducer;
