import React, { createContext, useContext, useState, useCallback } from 'react';
import PalRiderCustomModal, { PalRiderCustomModalProps } from './PalRiderCustomModal';

type ModalContextType = {
	showGlobalModal: (props: Omit<PalRiderCustomModalProps, 'isVisible' | 'onClose'> & { onClose?: () => void }) => void;
	hideGlobalModal: () => void;
};

const ModalContext = createContext<ModalContextType | undefined>(undefined);

export const ModalProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
	const [modalProps, setModalProps] = useState<PalRiderCustomModalProps | null>(null);

	const showGlobalModal = useCallback(
		(props: Omit<PalRiderCustomModalProps, 'isVisible' | 'onClose'> & { onClose?: () => void }) => {
			setModalProps({ ...props, isVisible: true, onClose: () => hideGlobalModal() });
		},
		[],
	);

	const hideGlobalModal = useCallback(() => {
		setModalProps(null);
		if (modalProps?.onClose) modalProps.onClose();
	}, [modalProps]);

	return (
		<ModalContext.Provider value={{ showGlobalModal, hideGlobalModal }}>
			{children}
			{modalProps && (
				<PalRiderCustomModal {...modalProps} isVisible={modalProps.isVisible} onClose={hideGlobalModal}>
					{modalProps.children}
				</PalRiderCustomModal>
			)}
		</ModalContext.Provider>
	);
};

export const useModal = (): ModalContextType => {
	const context = useContext(ModalContext);
	if (!context) throw new Error('useModal must be used within a ModalProvider');
	return context;
};
