import { createApi } from '@reduxjs/toolkit/query/react';
import { baseQueryConfigWithReAuth } from '../baseQueryConfig';
import { PaginationDataResultT, SuccessfulResponse, SuccessfulResponseT } from 'palriderapptypes';
import { CourierVehicleDTO, CreateCourierVehicleRequestDTO } from 'palriderapptypes/courier';
import { PaginationRequestDTO } from 'palriderapptypes/common';
export const courierVehicleApi = createApi({
	reducerPath: 'courierVehicle',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		getCourierVehicles: builder.query<
			PaginationDataResultT<CourierVehicleDTO>,
			PaginationRequestDTO & { courier_id: string }
		>({
			query({ page, size, courier_id }) {
				return {
					url: `courier/${courier_id}/vehicles?page=${page}&size=${size}`,
					method: 'GET',
				};
			},
		}),
		getCourierVehicle: builder.query<SuccessfulResponseT<CourierVehicleDTO>, { courier_vehicle_id: string }>({
			query({ courier_vehicle_id }) {
				return {
					url: `courier-vehicle/${courier_vehicle_id}`,
					method: 'GET',
				};
			},
		}),
		createVehicle: builder.mutation<SuccessfulResponse, CreateCourierVehicleRequestDTO>({
			query(body) {
				const data = new FormData();
				data.append('type', body.type);
				data.append('plate_number', body.plate_number);
				for (let i = 0; i < body.photos.length; i++) {
					data.append(`photos`, body.photos[i]);
				}
				return {
					method: 'POST',
					url: 'courier-vehicle',
					headers: {
						'Content-Type': 'multipart/form-data',
					},
					body: data,
				};
			},
		}),
		deleteVehicle: builder.query<SuccessfulResponse, string>({
			query(vehicle_id) {
				return {
					method: 'DELETE',
					url: `courier-vehicle/${vehicle_id}`,
				};
			},
		}),
		setActiveVehicle: builder.mutation<SuccessfulResponse, string>({
			query(vehicle_id) {
				return {
					method: 'GET',
					url: `courier-vehicle/${vehicle_id}/set-active`,
				};
			},
		}),
	}),
});

export const {
	useLazyGetCourierVehiclesQuery,
	useLazyGetCourierVehicleQuery,
	useLazyDeleteVehicleQuery,
	useCreateVehicleMutation,
	useSetActiveVehicleMutation,
} = courierVehicleApi;
