import React, { useRef } from 'react';
import { ListRenderItemInfo, Pressable, ScrollView, StyleSheet, View } from 'react-native';
import { font, PADDING } from '@/theme/responsive.ts';
import PalRiderText from '@/components/PalRiderText.tsx';
import colors from '@/theme/colors.ts';
import PalRiderButton from '@/components/PalRiderButton.tsx';
import PalRiderBadge from '@/components/PalRiderBadge.tsx';
import { FontFamily } from '@/theme/fonts.ts';
import CompanyNearbyOrderOrderBonusesModal from './modal/CompanyNearbyOrderOrderBonusesModal.tsx';
import { useAttendOrderMutation } from '@/services/api/order';
import { isFetchBaseQueryError, requestLocationPermission } from '@/utils';
import Geolocation from '@react-native-community/geolocation';
import { CompositeNavigationProp } from '@react-navigation/native';
import { useModal } from '@/components/ModalProvider';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import WarningModal from '@/components/custom-modal/WarningModal';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { OrderDTO } from 'palriderapptypes/order';
import { BaseUserDTO } from 'palriderapptypes/common';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import Icon from '@/components/Icon';
import { BottomSheetModal, BottomSheetView } from '@gorhom/bottom-sheet';
import PalRiderSwipeButton from '@/components/PalRiderSwipeButton';
import MapView, { Marker, Polyline } from 'react-native-maps';
import haversine from 'haversine-distance';

const CompanyNearbyOrderItemRender = React.memo(
	(
		prop: ListRenderItemInfo<OrderDTO> & {
			user: BaseUserDTO | null;
			reloadOrders: () => void;
			navigation: CompositeNavigationProp<any, any>;
		},
	) => {
		const { hideGlobalModal, showGlobalModal } = useModal();
		const insets = useSafeAreaInsets();
		const [attendOrder] = useAttendOrderMutation();
		const orderBonusesModalRef = useRef<BottomSheetModal>(null);
		const confirmAttendModalRef = useRef<BottomSheetModal>(null);

		const [userLocation, setUserLocation] = React.useState<{ latitude: number; longitude: number } | null>(null);
		const mapRef = useRef<MapView>(null);

		// confirm attend with swipe
		const handleConfirmAttend = async () => {
			confirmAttendModalRef.current?.dismiss();

			const requestAccess = await requestLocationPermission();
			if (!requestAccess) {
				showGlobalModal({
					children: (
						<WarningModal
							icon={<Icon name="LocationNotGrantedIconSvg" width={96} height={96} color={colors.red[600]} />}
							text="Please enable location to attend orders."
						/>
					),
				});
				return;
			}

			Geolocation.getCurrentPosition(
				async (position) => {
					showGlobalModal({ children: <LoadingModal text={'Attending order…'} /> });

					const result = await attendOrder({
						courier_id: '',
						order_id: prop.item.id,
						latitude: position.coords.latitude,
						longitude: position.coords.longitude,
					});

					hideGlobalModal();

					if (result.error && isFetchBaseQueryError(result.error)) {
						showGlobalModal({
							children: (
								<WarningModal
									icon={<Icon name="WarningIconSvg" width={72} height={72} color={colors.red[600]} />}
									text={result.error.data.title}
								/>
							),
						});
						return;
					}

					showGlobalModal({
						maxHeight: 200,
						children: <SuccessModal text="Order accepted! Redirecting…" />,
						preventHiding: true,
						closeAfterDelay: 1500,
						whenClose() {
							prop.navigation.navigate('AppOrderStack', {
								screen: 'OrderArriving',
								params: { order_id: prop.item.id },
							});
						},
					});
				},
				() => {
					showGlobalModal({
						children: (
							<WarningModal
								icon={<Icon name="LocationNotGrantedIconSvg" width={72} height={72} color={colors.red[600]} />}
								text="Location unavailable. Please enable it to attend."
							/>
						),
					});
				},
				{ enableHighAccuracy: true, timeout: 15000, maximumAge: 10000 },
			);
		};

		return (
			<View style={styles.orderContainer} key={prop.item.id}>
				{/* Header */}
				<View style={styles.orderHeader}>
					<View style={{ flex: 1 }}>
						<PalRiderText style={styles.orderNumber}>#{prop.item.order_no}</PalRiderText>
						<PalRiderText style={styles.orderDate}>{new Date(prop.item.created_at).toLocaleString()}</PalRiderText>
					</View>
					<Pressable onPress={() => orderBonusesModalRef.current?.present()}>
						<PalRiderText style={styles.showBonuses}>Show Bonuses</PalRiderText>
					</Pressable>
				</View>

				{/* Badges */}
				<ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.badgesContainer}>
					<PalRiderBadge text={`£${prop.item.hourly_rate} / Hour`} color={colors.orange[500]} />
					<PalRiderBadge text={`${prop.item.duration} Hours`} color={colors.orange[500]} />
					<PalRiderBadge text={`Max ${prop.item.order_courier_attendees.length} Couriers`} color={colors.orange[500]} />
					<PalRiderBadge
						text={`${Number(prop.item.courier_proximity ?? 0).toFixed(2)} Miles`}
						color={colors.orange[500]}
					/>
				</ScrollView>

				{/* Action */}
				<PalRiderButton
					style={styles.orderActionButton}
					onPress={() => {
						confirmAttendModalRef.current?.present();
						Geolocation.getCurrentPosition(
							(pos) => setUserLocation({ latitude: pos.coords.latitude, longitude: pos.coords.longitude }),
							() => setUserLocation(null),
							{ enableHighAccuracy: true, timeout: 10000, maximumAge: 1000 },
						);
					}}
				>
					<PalRiderText color={colors.white} fontFamily={FontFamily.Semibold}>
						Attend Order
					</PalRiderText>
				</PalRiderButton>

				{/* Bonuses Modal */}
				<BottomSheetModal ref={orderBonusesModalRef} enableDynamicSizing index={0}>
					<BottomSheetView style={{ flex: 1, paddingBottom: PADDING.large + insets.bottom }}>
						<CompanyNearbyOrderOrderBonusesModal {...prop} />
					</BottomSheetView>
				</BottomSheetModal>

				{/* Confirm Attend Modal with Swipe & Map */}
				<BottomSheetModal ref={confirmAttendModalRef} enableDynamicSizing index={0}>
					<BottomSheetView
						style={{
							flex: 1,
							padding: PADDING.large,
							paddingBottom: PADDING.large + insets.bottom,
							gap: PADDING.large,
						}}
					>
						<MapView
							ref={mapRef}
							style={{ height: 220, borderRadius: 12 }}
							userInterfaceStyle="light"
							provider="google"
							pointerEvents="none"
							onMapLoaded={() => {
								if (userLocation && prop.item.company_area_address?.latitude) {
									mapRef.current?.fitToCoordinates(
										[
											userLocation,
											{
												latitude: prop.item.company_area_address.latitude,
												longitude: prop.item.company_area_address.longitude,
											},
										],
										{
											edgePadding: { top: 50, right: 50, bottom: 50, left: 50 },
											animated: true,
										},
									);
								}
							}}
							initialRegion={{
								latitude: prop.item.company_area_address?.latitude ?? 0,
								longitude: prop.item.company_area_address?.longitude ?? 0,
								latitudeDelta: 0.05,
								longitudeDelta: 0.05,
							}}
						>
							{/* Company Marker */}
							<Marker
								coordinate={{
									latitude: prop.item.company_area_address?.latitude ?? 0,
									longitude: prop.item.company_area_address?.longitude ?? 0,
								}}
							>
								<Icon name="CompanyIconSvg" width={32} height={32} />
							</Marker>

							{/* User Marker */}
							{userLocation && (
								<Marker coordinate={userLocation}>
									<Icon
										name="LocationIconSvg"
										width={28}
										height={28}
										colorSpace={[colors.green[400], colors.green[600]]}
									/>
								</Marker>
							)}

							{/* Polyline */}
							{userLocation && (
								<Polyline
									coordinates={[
										userLocation,
										{
											latitude: prop.item.company_area_address?.latitude ?? 0,
											longitude: prop.item.company_area_address?.longitude ?? 0,
										},
									]}
									strokeColor={colors.orange[600]}
									strokeWidth={4}
								/>
							)}
						</MapView>

						{/* Distance */}
						{userLocation && (
							<PalRiderText
								fontFamily={FontFamily.Semibold}
								fontSize={font.small}
								style={{ textAlign: 'center', marginTop: PADDING.small }}
							>
								You are{' '}
								{(
									haversine(userLocation, {
										latitude: prop.item.company_area_address?.latitude ?? 0,
										longitude: prop.item.company_area_address?.longitude ?? 0,
									}) / 1609.34
								).toFixed(2)}{' '}
								miles away
							</PalRiderText>
						)}

						<View style={{ alignItems: 'center', gap: PADDING.small }}>
							<Icon name="VerifiedIconSvg" width={48} height={48} color={colors.green[600]} />
							<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.medium}>
								Swipe to confirm attending
							</PalRiderText>
						</View>

						<PalRiderSwipeButton
							swipeText="Swipe to Attend Order"
							swipedText="Attending…"
							onSwipe={handleConfirmAttend}
							button={
								<Pressable>
									<Icon name="ChevronRightIconSvg" color={colors.white} width={20} height={20} />
								</Pressable>
							}
						/>

						<PalRiderButton onPress={() => confirmAttendModalRef.current?.dismiss()}>
							<PalRiderText color={colors.white} fontFamily={FontFamily.Semibold}>
								Cancel
							</PalRiderText>
						</PalRiderButton>
					</BottomSheetView>
				</BottomSheetModal>
			</View>
		);
	},
);

const styles = StyleSheet.create({
	orderContainer: {
		backgroundColor: colors.white,
		padding: PADDING.large,
		borderRadius: 16,
		borderWidth: 1,
		borderColor: colors.gray[100],
		shadowColor: colors.black,
		shadowOpacity: 0.06,
		shadowRadius: 6,
		elevation: 4,
	},
	orderHeader: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
		marginBottom: PADDING.medium,
	},
	orderNumber: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.medium,
		color: colors.gray[900],
	},
	orderDate: {
		fontFamily: FontFamily.Regular,
		fontSize: font.mini,
		color: colors.gray[500],
	},
	showBonuses: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.small,
		color: colors.orange[600],
	},
	badgesContainer: {
		flexDirection: 'row',
		gap: PADDING.small,
		marginBottom: PADDING.large,
	},
	orderActionButton: {
		backgroundColor: colors.green[600],
		height: 44,
		borderRadius: 12,
		alignItems: 'center',
		justifyContent: 'center',
		marginTop: PADDING.small,
	},
});

export default CompanyNearbyOrderItemRender;
