// Type definitions
interface CompanyStatistics {
	area_count: number;
	area_address_count: number;
	successful_shipment_destination_count: number;
	unsuccessful_shipment_destination_count: number;
	total_worked_courier: number;
	current_month_invoice_total: number;
}

interface StatisticConfig {
	key: keyof CompanyStatistics;
	label: string;
	icon: string;
	accentColor: string;
	description: string;
}

interface ApiResponse {
	data: CompanyStatistics;
}

interface StatCardProps {
	stat: StatisticConfig;
	value: number;
	onPress: (stat: StatisticConfig) => void;
	index?: number;
}

interface StatDetailModalProps {
	visible: boolean;
	stat: StatisticConfig | null;
	value: number;
	onClose: () => void;
}

interface ApiError {
	data: {
		title: string;
	};
}

