// Utility functions
const formatNumber = (num: number): string => {
	if (!num && num !== 0) return '0';
	if (num >= 1000000) return `${(num / 1000000).toFixed(1)}M`;
	if (num >= 1000) return `${(num / 1000).toFixed(1)}K`;
	return num.toLocaleString();
};

const formatCurrency = (num: number): string => {
	if (!num && num !== 0) return '$0';
	return `$${formatNumber(num)}`;
};

const getGreeting = (): string => {
	const hour = new Date().getHours();
	if (hour < 12) return 'Good Morning';
	if (hour < 18) return 'Good Afternoon';
	return 'Good Evening';
};

// Components
const StatCard: React.FC<StatCardProps> = ({ stat, value, onPress }) => {
	const [scaleAnim] = useState<Animated.Value>(new Animated.Value(1));
	const displayValue: string = formatNumber(value);
	const safeIcon = typeof stat.icon === 'string' && stat.icon.length <= 3 ? stat.icon : '❓';

	const handlePress = useCallback((): void => {
		Animated.sequence([
			Animated.timing(scaleAnim, {
				toValue: 0.95,
				duration: 100,
				useNativeDriver: true,
			}),
			Animated.timing(scaleAnim, {
				toValue: 1,
				duration: 100,
				useNativeDriver: true,
			}),
		]).start();
		onPress?.(stat);
	}, [scaleAnim, onPress, stat]);

	return (
		<TouchableOpacity style={styles.lightCard} activeOpacity={0.8} onPress={handlePress}>
			<Animated.View style={[styles.lightCardInner, { transform: [{ scale: scaleAnim }] }]}>
				<View style={styles.lightIconContainer}>
					<PalRiderText style={styles.lightIcon}>{safeIcon}</PalRiderText>
				</View>
				<View style={styles.lightContent}>
					<PalRiderText style={styles.lightValue}>{displayValue}</PalRiderText>
					<PalRiderText style={styles.lightLabel}>{stat.label}</PalRiderText>
				</View>
			</Animated.View>
		</TouchableOpacity>
	);
};

const StatDetailModal: React.FC<StatDetailModalProps> = ({ visible, stat, value, onClose }) => {
	if (!stat) return null;
	const displayValue: string = formatNumber(value);

	return (
		<Modal visible={visible} transparent animationType="fade" onRequestClose={onClose}>
			<View style={styles.modalOverlay}>
				<Pressable style={styles.modalBackdrop} onPress={onClose} />
				<View style={styles.modalContent}>
					<View style={styles.modalHeader}>
						<View style={[styles.modalIcon, { backgroundColor: stat.accentColor + '15' }]}>
							<PalRiderText style={styles.modalIconText}>{stat.icon}</PalRiderText>
						</View>
						<TouchableOpacity style={styles.closeButton} onPress={onClose}>
							<PalRiderText style={styles.closeButtonText}>×</PalRiderText>
						</TouchableOpacity>
					</View>
					<PalRiderText style={styles.modalTitle}>{stat.label}</PalRiderText>
					<PalRiderText style={styles.modalDescription}>{stat.description}</PalRiderText>
					<PalRiderText
						style={[
							styles.modalStatValue,
							{
								color: stat.accentColor,
								fontSize: 28,
								textAlign: 'center',
								marginTop: 20,
							},
						]}
					>
						{displayValue}
					</PalRiderText>
				</View>
			</View>
		</Modal>
	);
};

// Main component
const AppCompanyHomeScreen: React.FC = () => {
	const [getStats, { data, isFetching, isLoading, isError, error }] = useLazyGetCompanyStatisticsQuery<{
		data?: ApiResponse;
		isFetching: boolean;
		isLoading: boolean;
		isError: boolean;
		error?: unknown;
	}>();

	const [selectedStat, setSelectedStat] = useState<StatisticConfig | null>(null);
	const [showStatModal, setShowStatModal] = useState<boolean>(false);
	const [lastRefresh, setLastRefresh] = useState<Date>(new Date());
	const [retryCount, setRetryCount] = useState<number>(0);

	// Animation values
	const [fadeAnim] = useState<Animated.Value>(new Animated.Value(0));
	const [slideAnim] = useState<Animated.Value>(new Animated.Value(30));

	useEffect(() => {
		loadData();

		// Animate in on mount
		Animated.parallel([
			Animated.timing(fadeAnim, {
				toValue: 1,
				duration: 800,
				useNativeDriver: true,
			}),
			Animated.timing(slideAnim, {
				toValue: 0,
				duration: 600,
				useNativeDriver: true,
			}),
		]).start();
	}, []);

	const loadData = useCallback(async (): Promise<void> => {
		try {
			await getStats();
			setLastRefresh(new Date());
			setRetryCount(0);
		} catch (err) {
			console.error('Error loading stats:', err);
		}
	}, [getStats]);

	const handleRefresh = useCallback((): void => {
		loadData();
	}, [loadData]);

	const handleRetry = useCallback((): void => {
		if (retryCount < 3) {
			setRetryCount((prev: number) => prev + 1);
			loadData();
		} else {
			Alert.alert(
				'Connection Issue',
				'Unable to load data after multiple attempts. Please check your internet connection and try again.',
				[
					{ text: 'OK', style: 'cancel' },
					{
						text: 'Retry',
						onPress: (): void => {
							setRetryCount(0);
							loadData();
						},
					},
				],
			);
		}
	}, [retryCount, loadData]);

	const handleStatPress = useCallback((stat: StatisticConfig): void => {
		setSelectedStat(stat);
		setShowStatModal(true);
	}, []);

	const stats: CompanyStatistics | undefined = data?.data;

	const successRate: number = useMemo((): number => {
		if (!stats || !stats.successful_shipment_destination_count) return 0;
		const total: number = stats.successful_shipment_destination_count + stats.unsuccessful_shipment_destination_count;
		return total > 0 ? Math.round((stats.successful_shipment_destination_count / total) * 100) : 0;
	}, [stats]);

	const handleCloseModal = useCallback((): void => {
		setShowStatModal(false);
	}, []);

	if (isError && isFetchBaseQueryError(error)) {
		const apiError = error as ApiError;
		return (
			<View style={styles.container}>
				<StatusBar barStyle="dark-content" backgroundColor="#ffffff" />
				<View style={styles.errorContainer}>
					<View style={styles.errorCard}>
						<PalRiderText style={styles.errorIcon}>📡</PalRiderText>
						<PalRiderText style={styles.errorTitle}>Connection Issue</PalRiderText>
						<PalRiderText style={styles.errorMessage}>
							{apiError?.data?.title || 'Unable to load dashboard data'}
						</PalRiderText>
						<TouchableOpacity style={styles.retryButton} onPress={handleRetry}>
							<PalRiderText style={styles.retryButtonText}>
								{retryCount > 0 ? `Retry (${retryCount}/3)` : 'Try Again'}
							</PalRiderText>
						</TouchableOpacity>
					</View>
				</View>
			</View>
		);
	}

	return (
		<SafeAreaView style={styles.container} edges={['top']}>
			<StatusBar barStyle="dark-content" backgroundColor="#ffffff" />

			{/* Animated Background */}
			<View style={styles.backgroundContainer}>
				<View style={[styles.floatingOrb, styles.orb1]} />
				<View style={[styles.floatingOrb, styles.orb2]} />
				<View style={[styles.floatingOrb, styles.orb3]} />
			</View>

			{/* Enhanced Header with Performance Indicator */}
			<Animated.View
				style={[
					styles.headerContainer,
					{
						opacity: fadeAnim,
						transform: [{ translateY: slideAnim }],
					},
				]}
			>
				<View style={styles.glassmorphHeader}>
					<View style={styles.headerContent}>
						<View style={styles.headerLeft}>
							<PalRiderText style={styles.greetingText}>{getGreeting()}</PalRiderText>
							<PalRiderText style={styles.companyName}>PalRider Analytics</PalRiderText>
						</View>
						<TouchableOpacity style={styles.profileButton}>
							<PalRiderText style={styles.profileIcon}>👤</PalRiderText>
						</TouchableOpacity>
					</View>
				</View>
			</Animated.View>

			<ScrollView
				refreshControl={
					<RefreshControl
						refreshing={isFetching}
						onRefresh={handleRefresh}
						tintColor="#667eea"
						colors={['#667eea']}
						title={`Last updated: ${lastRefresh.toLocaleTimeString()}`}
					/>
				}
				contentContainerStyle={styles.scrollContent}
				showsVerticalScrollIndicator={false}
			>
				{/* Hero Statistics Cards */}
				<Animated.View
					style={[
						styles.heroSection,
						{
							opacity: fadeAnim,
							transform: [{ translateY: slideAnim }],
						},
					]}
				>
					<View style={styles.primaryCard}>
						<View style={styles.primaryCardGradient}>
							<View style={styles.primaryCardContent}>
								<View style={styles.primaryCardHeader}>
									<PalRiderText style={styles.primaryCardLabel}>Courier Payments</PalRiderText>
									<PalRiderText style={styles.primaryCardIcon}>💸</PalRiderText>
								</View>
								<PalRiderText style={styles.primaryCardValue}>
									{formatCurrency(stats?.current_month_invoice_total ?? 0)}
								</PalRiderText>
								<View style={styles.primaryCardFooter}>
									<PalRiderText style={styles.primaryCardSubtext}>
										Paid to couriers • {new Date().toLocaleDateString('en-GB', { month: 'long' })}
									</PalRiderText>
								</View>

								<View style={styles.floatingElement1} />
								<View style={styles.floatingElement2} />
							</View>
						</View>
					</View>

					{/* Enhanced Success Rate Card */}
					<View style={styles.secondaryCard}>
						<View style={styles.secondaryCardGradient}>
							<View style={styles.secondaryCardContent}>
								<PalRiderText style={styles.secondaryCardIcon}>📊</PalRiderText>
								<PalRiderText style={styles.secondaryCardValue}>{successRate}%</PalRiderText>
								<PalRiderText style={styles.secondaryCardLabel}>Delivery Success Rate</PalRiderText>
								<View style={styles.successRateBar}>
									<View style={[styles.successRateFill, { width: `${successRate}%` }]} />
								</View>
							</View>
						</View>
					</View>
				</Animated.View>

				{/* Enhanced Stats Grid */}
				<View style={styles.statsGrid}>
					{statistics.slice(0, 6).map((stat: StatisticConfig, index: number) => (
						<StatCard
							key={stat.key}
							stat={stat}
							value={stats?.[stat.key] ?? 0}
							onPress={handleStatPress}
							index={index}
						/>
					))}
				</View>

				<CompanyHomeNearestCouriers />

				{/* Enhanced Loading State */}
				{isLoading && (
					<View style={styles.loadingContainer}>
						<View style={styles.loadingCard}>
							<ActivityIndicator size="large" color="#667eea" />
							<PalRiderText style={styles.loadingText}>Syncing dashboard...</PalRiderText>
							<View style={styles.loadingProgress}>
								<View style={styles.loadingProgressBar} />
							</View>
						</View>
					</View>
				)}
			</ScrollView>

			{/* Stat Detail Modal */}
			<StatDetailModal
				visible={showStatModal}
				stat={selectedStat}
				value={stats?.[selectedStat?.key ?? 'area_count'] ?? 0}
				onClose={handleCloseModal}
			/>
		</SafeAreaView>
	);
};

