import React, { useState } from 'react';
import { Image, Pressable, ScrollView, StyleSheet, View } from 'react-native';
import PalRiderText from '@/components/PalRiderText';
import PalRiderButton from '@/components/PalRiderButton';
import PalRiderTextInput from '@/components/PalRiderTextInput';
import { normalize, PADDING } from '@/theme/responsive';
import { maskUKPlate } from '@/utils';
import { yupTyped } from '@/types';
import { useFormik } from 'formik';
import { string, array, object, number } from 'yup';
import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { globalStyles } from '@/utils/global-styles';
import { buttonStyling } from '@/theme/defaults';
import { useCreateVehicleMutation } from '@/services/api/courier/courier-vehicle';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import WarningModal from '@/components/custom-modal/WarningModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import { CompositeScreenProps } from '@react-navigation/native';
import Dropdown from 'react-native-input-select';
import { CreateCourierVehicleRequestDTO } from 'palriderapptypes/courier';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import {
	AppCourierProfileStackParamList,
	AppCourierTabParamList,
	AppCourierVehiclesStackParamList,
} from '@/navigation/courier-navigation';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import { useTranslation } from 'react-i18next';
import Icon from '@/components/Icon';

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCourierVehiclesStackParamList, 'CourierVehicleCreate'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCourierProfileStackParamList, 'CourierVehiclesStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCourierTabParamList, 'CourierProfileStack'>,
			NativeStackScreenProps<RootStackParamList>
		>
	>
>;
const AppCourierProfileVehicleCreateVehicleScreen: React.FC<Props> = ({ navigation }) => {
	const { t } = useTranslation();
	const [imageModalVisible, setImageModalVisible] = useState(false);
	const [createVehicle] = useCreateVehicleMutation();
	const { showGlobalModal, hideGlobalModal } = useModal();
	const vehicleAddFormik = useFormik<CreateCourierVehicleRequestDTO>({
		initialValues: {
			type: 'bike',
			plate_number: '',
			photos: [],
		},
		validationSchema: yupTyped<CreateCourierVehicleRequestDTO>({
			type: string().required().label('Type'),
			plate_number: string()
				.label('Plate Number')
				.when('type', (type, schema) => {
					if (type && (type.includes('motorcycle') || type.includes('car'))) {
						return schema.required().min(3);
					}
					return schema;
				}),
			photos: array()
				.of(
					object().shape({
						name: string().required('File name required'),
						size: number().required().max(10000000),
					}),
				)
				.required()
				.label('Vehicle Images')
				.min(1, 'At least one image required')
				.max(3, 'No more than 3 images are allowed'),
		}),
		onSubmit: async (values) => {
			try {
				showGlobalModal({
					children: <LoadingModal />,
					backgroundColor: 'transparent',
				});
				createVehicle(values)
					.unwrap()
					.then(() => {
						hideGlobalModal();
						showGlobalModal({
							minWidth: 100,
							minHeight: 100,
							children: <SuccessModal text="Vehicle Added" />,
							whenClose() {
								navigation.goBack();
							},
						});
					})
					.catch(() => {
						hideGlobalModal();
						showGlobalModal({
							minWidth: 100,
							minHeight: 100,
							children: <WarningModal text="Vehicle not added" />,
						});
					});
			} catch {}
		},
	});
	const isNotBicycle = () =>
		vehicleAddFormik.values.type &&
		(vehicleAddFormik.values.type.includes('motorcycle') || vehicleAddFormik.values.type.includes('car'));
	return (
		<View style={{ flex: 1 }}>
			<ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={{ gap: PADDING.large }}>
				<View style={styles.container}>
					<View>
						<View style={{ flexDirection: 'row', columnGap: normalize(2) }}>
							<PalRiderText style={globalStyles.titleTextStyle}>{t('common.vehicle_type')}</PalRiderText>
						</View>
						<Dropdown
							{...globalStyles.dropdownProps}
							options={[
								{
									value: 'bike',
									label: t('common.bike'),
								},
								{
									value: 'motorcycle',
									label: t('common.motorcycle'),
								},
								{
									value: 'car',
									label: t('common.car'),
								},
							]}
							isSearchable
							isMultiple={false}
							selectedValue={vehicleAddFormik.values.type as 'car' | 'motorcycle' | 'bike'}
							onValueChange={(value) => vehicleAddFormik.setFieldValue('type', value as 'car' | 'motorcycle' | 'bike')}
							maxSelectableItems={1}
						/>
						{vehicleAddFormik.errors.type && (
							<PalRiderText style={globalStyles.errorTextStyle}>{vehicleAddFormik.errors.type}</PalRiderText>
						)}
					</View>
					{vehicleAddFormik.values.type !== undefined && (
						<View style={vehicleSytles.container}>
							{isNotBicycle() && (
								<View>
									<PalRiderTextInput
										title={t('common.plate_number')}
										onChangeText={(text) => vehicleAddFormik.setFieldValue('plate_number', text, true)}
										maxLength={8}
										onBlur={vehicleAddFormik.handleBlur('plate_number')}
										value={vehicleAddFormik.values.plate_number}
										error={vehicleAddFormik.errors.plate_number}
										autoCapitalize="characters"
										required
									/>
								</View>
							)}
							<View
								style={[
									vehicleSytles.addImageContainer,
									{
										marginTop: isNotBicycle() ? normalize(0) : normalize(10),
									},
								]}
							>
								<PalRiderText style={vehicleSytles.imageTitle}>Vehicle Images</PalRiderText>
								<View
									style={{
										flexDirection: 'column',
										gap: normalize(8),
										marginTop: 10,
									}}
								>
									{vehicleAddFormik.values.photos.length > 0 &&
										vehicleAddFormik.values.photos.map((vehicleImage, vehicleImageIndex) => (
											<View style={vehicleSytles.vehicleImageContainer} key={vehicleImageIndex}>
												<PalRiderButton
													onPress={async () => {
														const images = vehicleAddFormik.values.photos.filter(
															(_, _vehicleImageIndex) => vehicleImageIndex !== _vehicleImageIndex,
														);
														await vehicleAddFormik.setFieldValue('photos', images);
													}}
													style={vehicleSytles.vehicleImageRemoveButton}
												>
													<Icon name="TrashIconSvg" width={20} height={20} color="white" />
												</PalRiderButton>
												<Image
													source={{
														uri: vehicleImage.uri,
													}}
													style={{
														width: '100%',
														height: normalize(160),
													}}
												/>
											</View>
										))}
									{vehicleAddFormik.values.photos.length > 0 && vehicleAddFormik.values.photos.length < 3 && (
										<View style={vehicleSytles.vehicleImageContainer}>
											<PalRiderButton
												style={vehicleSytles.vehicleImageAddButton}
												onPress={() => setImageModalVisible(true)}
											>
												<Icon name="PlusIconSvg" width={20} height={20} color="white" />
											</PalRiderButton>
										</View>
									)}
								</View>
								{vehicleAddFormik.values.photos.length === 0 && (
									<Pressable style={vehicleSytles.addImageContainerInner} onPress={() => setImageModalVisible(true)}>
										<View style={vehicleSytles.addImageButton}>
											<Icon name="CameraIconSvg" />
										</View>
										<View style={vehicleSytles.takeAPhotoContainer}>
											<PalRiderText style={vehicleSytles.takeAPhotoText}>
												{t('screen.courier.vehicle.add_vehicle_screen.take_photo')}
											</PalRiderText>
											<PalRiderText style={vehicleSytles.takeAPhotoDescription} lineBreakStrategyIOS="standard">
												{t('screen.courier.vehicle.add_vehicle_screen.take_photo_desc')}
											</PalRiderText>
										</View>
									</Pressable>
								)}
							</View>
							<View>
								<PalRiderButton
									style={[buttonStyling.dark, { width: '100%' }]}
									onPress={() => vehicleAddFormik.handleSubmit()}
								>
									<PalRiderText color="white">{t('common.add')}</PalRiderText>
								</PalRiderButton>
							</View>
						</View>
					)}
				</View>
			</ScrollView>
		</View>
	);
};
const styles = StyleSheet.create({
	container: { flex: 1, padding: PADDING.large, gap: PADDING.large },
});
const vehicleSytles = StyleSheet.create({
	container: {
		gap: normalize(10),
	},
	addImageContainer: {
		gap: normalize(4),
	},
	imageTitle: {
		fontFamily: FontFamily.Semibold,
	},
	addImageContainerInner: {
		flexDirection: 'row',
		alignItems: 'center',
		width: '100%',
		gap: normalize(12),
	},
	addImageButton: {
		backgroundColor: 'rgba(0,0,0,.1)',
		justifyContent: 'center',
		alignItems: 'center',
		width: normalize(80),
		height: normalize(80),
		borderRadius: normalize(12),
	},
	vehicleImageContainer: {
		backgroundColor: 'rgba(0,0,0,.1)',
		justifyContent: 'center',
		alignItems: 'center',
		width: '100%',
		height: normalize(160),
		borderRadius: normalize(12),
		overflow: 'hidden',
	},
	vehicleImageRemoveButton: {
		position: 'absolute',
		width: '100%',
		height: '100%',
		justifyContent: 'center',
		alignItems: 'center',
		backgroundColor: 'rgba(0,0,0,.4)',
		zIndex: 999,
	},
	vehicleImageAddButton: {
		position: 'absolute',
		width: '100%',
		height: '100%',
		justifyContent: 'center',
		alignItems: 'center',
		backgroundColor: 'rgba(0,0,0,.7)',
		zIndex: 999,
	},
	takeAPhotoContainer: {
		flex: 1,
	},
	takeAPhotoText: {
		fontFamily: FontFamily.Semibold,
		fontSize: normalize(14),
	},
	takeAPhotoDescription: {
		fontFamily: FontFamily.Regular,
		fontSize: normalize(10),
		color: colors.gray[400],
	},
	radioButton: {
		width: 20,
		height: 20,
		borderRadius: 20 / 2,
		borderWidth: 3,
		borderColor: 'white',
	},
});
export default AppCourierProfileVehicleCreateVehicleScreen;
