import { createNativeStackNavigator } from '@react-navigation/native-stack';
import LinearGradient from 'react-native-linear-gradient';

import AuthSelectScreen from '@/screens/auth/AuthSelectScreen';
import PhoneInfoScreen from '@/screens/auth/user/PhoneInfoScreen';
import SignUpCourierScreen from '@/screens/auth/signup/courier';
import SignUpCompanyAreaUserScreen from '@/screens/auth/signup/company';

import colors from '@/theme/colors';
import { useTranslation } from 'react-i18next';

export type AuthStackParamList = {
	AuthSelect: undefined;
	PhoneInfo: undefined;
	SignUpCourier: undefined;
	SignUpCompanyAreaUser: undefined;
};

const Stack = createNativeStackNavigator<AuthStackParamList>();

export const AuthStackNavigator = () => {
	const { t } = useTranslation();
	return (
		<Stack.Navigator
			screenOptions={{
				headerTintColor: colors.white,
				headerBackButtonDisplayMode: 'minimal',
				headerShadowVisible: false,
				headerBackButtonMenuEnabled: false,
			}}
		>
			<Stack.Screen
				name="AuthSelect"
				component={AuthSelectScreen}
				options={{
					headerShown: true,
					headerTitle: t('screen.titles.auth.auth_select'),
					headerTitleAlign: 'center',
					headerBackButtonDisplayMode: 'minimal',
					headerBackground: () => (
						<LinearGradient
							style={{ flex: 1 }}
							colors={[colors.orange[600], colors.red[500]]}
							start={{ x: 0, y: 0 }}
							end={{ x: 1, y: 0 }}
						/>
					),
				}}
			/>
			<Stack.Screen name="PhoneInfo" component={PhoneInfoScreen} options={{ headerShown: false }} />
			<Stack.Screen
				name="SignUpCourier"
				component={SignUpCourierScreen}
				options={{
					headerShown: true,
					headerTitle: t('screen.titles.auth.sign_up_courier'),
					headerTitleAlign: 'center',
					headerBackButtonDisplayMode: 'minimal',
					headerBackground: () => (
						<LinearGradient
							style={{ flex: 1 }}
							colors={[colors.orange[600], colors.red[500]]}
							start={{ x: 0, y: 0 }}
							end={{ x: 1, y: 0 }}
						/>
					),
				}}
			/>
			<Stack.Screen
				name="SignUpCompanyAreaUser"
				component={SignUpCompanyAreaUserScreen}
				options={{
					headerShown: true,
					headerTitle: t('screen.titles.auth.sign_up_company'),
					headerTitleAlign: 'center',
					headerBackButtonDisplayMode: 'minimal',
					headerBackground: () => (
						<LinearGradient
							style={{ flex: 1 }}
							colors={[colors.orange[600], colors.red[500]]}
							start={{ x: 0, y: 0 }}
							end={{ x: 1, y: 0 }}
						/>
					),
				}}
			/>
		</Stack.Navigator>
	);
};
