import { createApi } from '@reduxjs/toolkit/query/react';
import { baseQueryConfigWithReAuth } from '../baseQueryConfig';
export const googleMapsApi = createApi({
	reducerPath: 'googleMaps',
	baseQuery: baseQueryConfigWithReAuth,
	keepUnusedDataFor: 0,
	endpoints: (builder) => ({
		autocomplete: builder.mutation<
			any,
			{
				input: string;
				languageCode: string;
			}
		>({
			query(body) {
				return {
					url: `maps/v1/places:autocomplete`,
					method: 'POST',
					body: body,
				};
			},
		}),
		getPlace: builder.mutation<
			any,
			{
				placeId: string;
				sessionToken: string;
			}
		>({
			query(body) {
				return {
					url: `maps/v1/places/${body.placeId}?sessionToken=${body.sessionToken}`,
					method: 'POST',
				};
			},
		}),
	}),
});

export const { useAutocompleteMutation, useGetPlaceMutation } = googleMapsApi;
