import { createApi } from '@reduxjs/toolkit/query/react';
import { PaginationDataResultT, SuccessfulResponse, SuccessfulResponseT } from 'palriderapptypes';
import { PaginationRequestDTO } from 'palriderapptypes/common';
import {
	CompanyWalletDTO,
	CompanyWalletTransactionDTO,
	CompanyWalletTransferRequestDTO,
} from 'palriderapptypes/company';
import { baseQueryConfigWithReAuth } from 'src/services/api/baseQueryConfig.ts';

export const companyWalletApi = createApi({
	reducerPath: 'companyWallet',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		getCompanyWallet: builder.query<SuccessfulResponseT<CompanyWalletDTO>, string>({
			query(company_wallet_id) {
				return {
					url: `company-wallet/${company_wallet_id}`,
					method: 'GET',
				};
			},
		}),
		getCompanyWalletTransactionList: builder.query<
			PaginationDataResultT<CompanyWalletTransactionDTO>,
			PaginationRequestDTO & { company_wallet_id: string }
		>({
			query(body) {
				return {
					url: `company-wallet/${body.company_wallet_id}/wallet-transaction-list?page=${body.page}&size=${body.size}`,
					method: 'GET',
				};
			},
		}),
		getCompanyWalletTransferRequestList: builder.query<
			PaginationDataResultT<CompanyWalletTransferRequestDTO>,
			PaginationRequestDTO & { company_wallet_id: string }
		>({
			query(body) {
				return {
					url: `company-wallet/${body.company_wallet_id}/transfer-requests?page=${body.page}&size=${body.size}`,
					method: 'GET',
				};
			},
		}),
		transferBalance: builder.mutation<
			SuccessfulResponse,
			{ company_wallet_id: string; company_area_address_wallet_id: string; amount: number }
		>({
			query(body) {
				return {
					url: `company-wallet/${body.company_wallet_id}/transfer`,
					method: 'POST',
					body: {
						amount: body.amount,
						company_area_address_wallet_id: body.company_area_address_wallet_id,
					},
				};
			},
		}),
	}),
});

export const {
	useLazyGetCompanyWalletQuery,
	useLazyGetCompanyWalletTransferRequestListQuery,
	useLazyGetCompanyWalletTransactionListQuery,
	useTransferBalanceMutation,
} = companyWalletApi;
