import React, { useEffect, useMemo, useState } from 'react';
import { RefreshControl, ScrollView, StyleSheet, View } from 'react-native';
import colors from '@/theme/colors';
import { font, PADDING } from '@/theme/responsive';
import { FontFamily } from '@/theme/fonts';
import { useUpdateCompanyAreaAddressMutation } from '@/services/api/company/company-area-address';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { isFetchBaseQueryError, parsePhoneNumber } from '@/utils';
import WarningModal from '@/components/custom-modal/WarningModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import PalRiderButton from '@/components/PalRiderButton';

import { CompositeScreenProps } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import {
	AppCompanyProfileCompanyAreaParamList,
	AppCompanyProfileParamList,
	AppCompanyTabParamList,
} from '@/navigation/company-navigation';
import { useLazyGetCompanyAreaAddressUserQuery } from '@/services/api/company/company-area-address-user';

import { PalRiderInfoCard, PalRiderInfoRow } from '@/components/PalRiderInfoCard';

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList, 'CompanyAreaAddressUserView'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyAreaStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
			CompositeScreenProps<
				NativeStackScreenProps<RootStackParamList>,
				NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList>
			>
		>
	>
>;

const AppCompanyProfileCompanyAreaAddressUserViewScreen: React.FC<Props> = ({ route, navigation }) => {
	const { showGlobalModal } = useModal();
	if (!route?.params?.company_area_address_user_id) navigation.goBack();
	const [getCompanyAreaAddressUser, { data, isLoading }] = useLazyGetCompanyAreaAddressUserQuery();
	const [updateCompanyAreaAddress] = useUpdateCompanyAreaAddressMutation();

	const [updateValues, setUpdateValues] = useState({
		showName: false,
		showSurname: false,
		name: '',
		surname: '',
	});

	const handleUpdate = async () => {
		if (!data?.data) return;
		showGlobalModal({
			children: <LoadingModal />,
			backgroundColor: colors.transparent,
		});
		const res = await updateCompanyAreaAddress({ ...updateValues, company_area_address_id: data.data.id });
		if (res.error && isFetchBaseQueryError(res.error)) {
			showGlobalModal({
				children: <WarningModal text={res.error.data.title} />,
			});
			return;
		}
		showGlobalModal({
			children: <SuccessModal text="User information updated" />,
			closeAfterDelay: 1000,
			whenClose() {
				loadCompanyAreaUser();
				setUpdateValues((prev) => ({
					...prev,
					showName: false,
					showSurname: false,
				}));
			},
		});
	};

	const hasManager = useMemo(() => {
		return (
			(data?.data?.company_area_address_user_role?.name &&
				data?.data?.company_area_address_user_role?.name === 'Manager') ??
			false
		);
	}, [data, data?.data]);

	const loadCompanyAreaUser = async () => {
		const res = await getCompanyAreaAddressUser(route.params.company_area_address_user_id);
		if (res.error && isFetchBaseQueryError(res.error)) {
			showGlobalModal({
				children: <WarningModal text={res.error.data.title} />,
			});
			return;
		}
	};

	useEffect(() => {
		loadCompanyAreaUser();
	}, []);

	return (
		<View style={styles.container}>
			<ScrollView
				contentContainerStyle={{ gap: PADDING.large, padding: PADDING.large }}
				refreshControl={<RefreshControl onRefresh={loadCompanyAreaUser} refreshing={isLoading} />}
			>
				<PalRiderInfoCard title="User Information">
					<PalRiderInfoRow
						label="Name"
						value={data?.data?.name}
						editable
						showInput={updateValues.showName}
						inputValue={updateValues.name}
						onChangeText={(text) => setUpdateValues((p) => ({ ...p, name: text }))}
						onPress={() => setUpdateValues((p) => ({ ...p, showName: true }))}
						onSubmit={handleUpdate}
					/>
					<PalRiderInfoRow
						label="Surname"
						value={data?.data?.surname}
						editable
						showInput={updateValues.showSurname}
						inputValue={updateValues.surname}
						onChangeText={(text) => setUpdateValues((p) => ({ ...p, surname: text }))}
						onPress={() => setUpdateValues((p) => ({ ...p, showSurname: true }))}
						onSubmit={handleUpdate}
					/>
					<PalRiderInfoRow label="Phone Number" value={parsePhoneNumber(data?.data?.phone_number)} />
					<PalRiderInfoRow label="Email" value={data?.data?.email} />
					<PalRiderInfoRow label="Is Active" value={data?.data?.is_active ? 'Yes' : 'No'} />
					<PalRiderInfoRow label="Area" value={data?.data?.company_area?.name} />
				</PalRiderInfoCard>

				{hasManager && (
					<View style={{ gap: PADDING.medium }}>
						<PalRiderButton variant="warning">Remove User (WIP)</PalRiderButton>
						<PalRiderButton variant="warning">Make Inactive (WIP)</PalRiderButton>
					</View>
				)}
			</ScrollView>
		</View>
	);
};

const styles = StyleSheet.create({
	container: {
		backgroundColor: colors.gray[50],
		flex: 1,
	},
	sectionTitle: {
		fontFamily: FontFamily.Bold,
		fontSize: font.medium,
		color: colors.gray[800],
		paddingHorizontal: PADDING.large,
		paddingBottom: PADDING.medium,
	},
});

export default AppCompanyProfileCompanyAreaAddressUserViewScreen;
