import React, { useMemo, useState } from 'react';
import { ScrollView, StyleSheet, View, Image, TouchableOpacity } from 'react-native';
import colors from '@/theme/colors';
import { useAppSelector } from '@/redux/hooks';
import { useFormik } from 'formik';
import { PADDING } from '@/theme/responsive';
import PalRiderButton from '@/components/PalRiderButton';
import PalRiderText from '@/components/PalRiderText';
import Icon from '@/components/Icon';
import { FontFamily } from '@/theme/fonts';
import { parseAuthPhoneNumber } from '@/utils';
import { PalRiderInfoCard, PalRiderInfoRow } from '@/components/PalRiderInfoCard';

type ProfileFormikType = {
	name?: string;
	surname?: string;
	email?: string;
	phone_number?: string;
};

const AppCompanyProfileMyAccountScreen: React.FC = () => {
	const userSlice = useAppSelector((x) => x.userSlice.user!);

	const [updateValues, setUpdateValues] = useState({
		showName: false,
		showSurname: false,
		showEmail: false,
		name: userSlice.name ?? '',
		surname: userSlice.surname ?? '',
		email: userSlice.email ?? '',
	});

	const companyUserMyAccountFormik = useFormik<ProfileFormikType>({
		initialValues: {
			name: userSlice.name ?? '',
			surname: userSlice.surname ?? '',
			email: userSlice.email ?? '',
			phone_number: userSlice.phone_number,
		},
		onSubmit: () => {
			// Handle update logic (API integration here)
		},
	});

	const emailStatus = useMemo(() => {
		if (userSlice.email && !userSlice.email_verified_at) {
			return (
				<View style={styles.badgeUnverified}>
					<Icon name="UnverifiedIconSvg" width={14} height={14} color={colors.red[600]} />
					<PalRiderText fontSize={12} color={colors.red[600]}>
						Unverified
					</PalRiderText>
				</View>
			);
		} else if (userSlice.email && userSlice.email_verified_at) {
			return (
				<View style={styles.badgeVerified}>
					<Icon name="VerifiedIconSvg" width={14} height={14} color={colors.green[600]} />
					<PalRiderText fontSize={12} color={colors.green[600]}>
						Verified
					</PalRiderText>
				</View>
			);
		}
		return null;
	}, [userSlice.email, userSlice.email_verified_at]);

	return (
		<View style={styles.container}>
			<ScrollView contentContainerStyle={styles.scrollContent} contentInsetAdjustmentBehavior="automatic">
				{/* Profile Header */}
				<View style={styles.header}>
					<View style={styles.avatarContainer}>
						<Image source={{ uri: 'https://avatar.iran.liara.run/public/boy' }} style={styles.avatar} />
						<TouchableOpacity style={styles.editAvatar}>
							<Icon name="EditIconSvg" width={16} height={16} color={colors.white} />
						</TouchableOpacity>
					</View>
					<PalRiderText fontSize={18} fontFamily={FontFamily.Semibold}>
						{userSlice.name} {userSlice.surname}
					</PalRiderText>
					<View style={styles.emailRow}>
						<PalRiderText fontSize={14} color={colors.gray[600]}>
							{userSlice.email}
						</PalRiderText>
						{emailStatus}
					</View>
				</View>

				{/* Info Card with rows */}
				<PalRiderInfoCard title="Account Details">
					<PalRiderInfoRow
						label="First Name"
						value={userSlice.name}
						editable
						showInput={updateValues.showName}
						inputValue={updateValues.name}
						onChangeText={(text) => setUpdateValues((p) => ({ ...p, name: text }))}
						onPress={() => setUpdateValues((p) => ({ ...p, showName: true }))}
						onSubmit={companyUserMyAccountFormik.submitForm}
					/>
					<PalRiderInfoRow
						label="Last Name"
						value={userSlice.surname}
						editable
						showInput={updateValues.showSurname}
						inputValue={updateValues.surname}
						onChangeText={(text) => setUpdateValues((p) => ({ ...p, surname: text }))}
						onPress={() => setUpdateValues((p) => ({ ...p, showSurname: true }))}
						onSubmit={companyUserMyAccountFormik.submitForm}
					/>
					<PalRiderInfoRow
						label="Email"
						value={userSlice.email}
						editable
						showInput={updateValues.showEmail}
						inputValue={updateValues.email}
						onChangeText={(text) => setUpdateValues((p) => ({ ...p, email: text }))}
						onPress={() => setUpdateValues((p) => ({ ...p, showEmail: true }))}
						onSubmit={companyUserMyAccountFormik.submitForm}
					/>
					<PalRiderInfoRow label="Phone Number" value={parseAuthPhoneNumber(userSlice.phone_number)} />
					<PalRiderInfoRow label="Status" value={userSlice.email_verified_at ? 'Active' : 'Inactive'} />
				</PalRiderInfoCard>
			</ScrollView>

			{/* Sticky Footer Button */}
			<View style={styles.footer}>
				<PalRiderButton style={styles.updateButton} onPress={companyUserMyAccountFormik.submitForm}>
					<PalRiderText color={colors.white} fontFamily={FontFamily.Semibold}>
						Update Profile
					</PalRiderText>
				</PalRiderButton>
			</View>
		</View>
	);
};

const styles = StyleSheet.create({
	container: {
		backgroundColor: colors.gray[50],
		flex: 1,
	},
	scrollContent: {
		padding: PADDING.large,
		paddingBottom: 120,
	},
	header: {
		alignItems: 'center',
		marginBottom: PADDING.large,
	},
	avatarContainer: {
		position: 'relative',
		marginBottom: PADDING.medium,
	},
	avatar: {
		width: 90,
		height: 90,
		borderRadius: 45,
		backgroundColor: colors.gray[200],
	},
	editAvatar: {
		position: 'absolute',
		bottom: 0,
		right: 0,
		backgroundColor: colors.orange[600],
		borderRadius: 16,
		padding: 6,
	},
	emailRow: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: 6,
		marginTop: 4,
	},
	badgeVerified: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: 4,
		backgroundColor: colors.green[50],
		paddingHorizontal: 8,
		paddingVertical: 2,
		borderRadius: 12,
	},
	badgeUnverified: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: 4,
		backgroundColor: colors.red[50],
		paddingHorizontal: 8,
		paddingVertical: 2,
		borderRadius: 12,
	},
	footer: {
		position: 'absolute',
		bottom: 0,
		left: 0,
		right: 0,
		padding: PADDING.large,
		backgroundColor: colors.white,
		borderTopWidth: StyleSheet.hairlineWidth,
		borderTopColor: colors.gray[200],
	},
	updateButton: {
		backgroundColor: colors.orange[600],
		borderRadius: 12,
	},
});

export default AppCompanyProfileMyAccountScreen;
