import PalRiderButton from '@/components/PalRiderButton.tsx';
import PalRiderText from '@/components/PalRiderText.tsx';
import PalRiderTextInput from '@/components/PalRiderTextInput.tsx';
import { normalize, PADDING } from '@/theme/responsive.ts';
import { yupTyped } from '@/types';
import { useFormik } from 'formik';
import React, { useState } from 'react';
import { KeyboardAvoidingView, Platform, ScrollView, StyleSheet, View } from 'react-native';
import { date, string } from 'yup';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useAppDispatch, useAppSelector } from '@/redux/hooks.ts';
import { setCompanyAreaUserInfoOnboardingState } from '@/redux/slices/company-onboarding.ts';
import DatePicker from 'react-native-date-picker';
import { format } from 'date-fns';
import CalendarIconSvg from '@/assets/svg/custom/CalenderIconSvg';
import { useModal } from '@/components/ModalProvider';
import { safeAreaEdges } from '@/utils';
import { OnboardingCompanyAreaUserRequestDTO } from 'palriderapptypes/company';
import { useTranslation } from 'react-i18next';
import WarningModal from '@/components/custom-modal/WarningModal';
import colors from '@/theme/colors';

type Props = {
	nextStep: () => void;
	prevStep: () => void;
};
const SignUpCompanyAreaUserInfoStep: React.FC<Props> = ({ nextStep, prevStep }) => {
	const { t } = useTranslation();
	const dispatch = useAppDispatch();
	const [datePickerOpened, setDatePickerOpened] = useState(false);
	const companyAreaUserInfoSlice = useAppSelector((x) => x.companyOnboardingSlice.area.user);
	const { showGlobalModal } = useModal();
	const minDate = new Date(new Date().setFullYear(new Date().getFullYear() - 80)); // 80 years before today
	const maxDate = new Date(new Date().setFullYear(new Date().getFullYear() - 18)); // 18 years before today
	const companyAreaUserInfoOnboardingFormik = useFormik<OnboardingCompanyAreaUserRequestDTO>({
		initialValues: {
			name: companyAreaUserInfoSlice.name,
			surname: companyAreaUserInfoSlice.surname,
			birthday: companyAreaUserInfoSlice.birthday,
		},
		validationSchema: yupTyped<OnboardingCompanyAreaUserRequestDTO>({
			name: string()
				.min(2, t('validation.min', { field: t('common.name'), min: 2 }))
				.max(80, t('validation.max', { field: t('common.name'), min: 80 }))
				.required(t('validation.required', { field: t('common.name') })),
			surname: string()
				.min(2, t('validation.min', { field: t('common.surname'), min: 2 }))
				.max(80, t('validation.max', { field: t('common.surname'), min: 80 }))
				.required(t('validation.required', { field: t('common.surname') })),
			birthday: date()
				.max(maxDate, t('validation.max_date', { max_date: maxDate }))
				.min(minDate, t('validation.min_date', { min_date: minDate }))
				.required(t('validation.required', { field: t('common.birthday') })),
		}),
		onSubmit: async (values) => {
			try {
				dispatch(
					setCompanyAreaUserInfoOnboardingState({
						birthday: values.birthday,
						name: values.name,
						phone_number: companyAreaUserInfoSlice.phone_number,
						surname: values.surname,
					}),
				);
				nextStep();
			} catch (err) {
				showGlobalModal({
					children: <WarningModal text={t('error.cannot_save_changes')} />,
				});
			}
		},
	});
	return (
		<SafeAreaView style={styles.safeAreaContainer} edges={safeAreaEdges}>
			<KeyboardAvoidingView
				style={styles.container}
				behavior={Platform.OS === 'ios' ? 'padding' : undefined}
				keyboardVerticalOffset={Platform.OS === 'ios' ? 0 : 20} // optional tweak
			>
				<ScrollView keyboardShouldPersistTaps="handled">
					<View style={{ flex: 1, gap: PADDING.large }}>
						<PalRiderTextInput
							title={'Manager Name'}
							onChangeText={companyAreaUserInfoOnboardingFormik.handleChange('name')}
							value={companyAreaUserInfoOnboardingFormik.values.name}
							error={companyAreaUserInfoOnboardingFormik.errors.name}
							required
						/>
						<PalRiderTextInput
							title={'Manager Surname'}
							onChangeText={companyAreaUserInfoOnboardingFormik.handleChange('surname')}
							value={companyAreaUserInfoOnboardingFormik.values.surname}
							error={companyAreaUserInfoOnboardingFormik.errors.surname}
							required
						/>
						<PalRiderTextInput
							required
							title={'Manager Birthday'}
							value={companyAreaUserInfoOnboardingFormik.values.birthday!}
							onPressIn={() => setDatePickerOpened(true)}
							error={companyAreaUserInfoOnboardingFormik.errors.birthday}
							leftComponent={<CalendarIconSvg width={16} height={16} />}
						/>
						<DatePicker
							modal
							locale="en"
							mode="date"
							title={t('common.birthday')}
							theme="dark"
							date={new Date(new Date().setFullYear(new Date().getFullYear() - 18))}
							open={datePickerOpened}
							maximumDate={new Date(new Date().setFullYear(new Date().getFullYear() - 18))}
							minimumDate={new Date(new Date().setFullYear(new Date().getFullYear() - 80))}
							onConfirm={(seletectedDate) => {
								setDatePickerOpened(false);
								companyAreaUserInfoOnboardingFormik.setFieldValue(
									'birthday',
									format(seletectedDate, 'yyyy-MM-dd'),
									true,
								);
								companyAreaUserInfoOnboardingFormik.validateField('birthday');
							}}
							onCancel={() => {
								setDatePickerOpened(false);
							}}
						/>
					</View>
				</ScrollView>
				<View
					style={{
						flexDirection: 'row',
						gap: normalize(10),
					}}
				>
					<PalRiderButton style={{ flex: 1 }} variant="dark" onPress={() => prevStep()}>
						<PalRiderText color="white">{t('common.go_back')}</PalRiderText>
					</PalRiderButton>
					<PalRiderButton
						variant="dark"
						style={{ flex: 1 }}
						onPress={() => {
							companyAreaUserInfoOnboardingFormik.handleSubmit();
						}}
					>
						<PalRiderText color="white">{t('common.continue')}</PalRiderText>
					</PalRiderButton>
				</View>
			</KeyboardAvoidingView>
		</SafeAreaView>
	);
};
const styles = StyleSheet.create({
	safeAreaContainer: {
		flex: 1,
		backgroundColor: colors.white,
	},
	container: {
		flex: 1,
		padding: PADDING.large,
	},
	contentContainer: {
		alignItems: 'center',
		padding: normalize(16),
	},
});
export default SignUpCompanyAreaUserInfoStep;
