import { createApi } from '@reduxjs/toolkit/query/react';
import { baseQueryConfigWithReAuth } from '../baseQueryConfig';
import { PaginationDataResultT, SuccessfulResponse, SuccessfulResponseT } from 'palriderapptypes';
import {
	CourierActiveOrderDTO,
	CreateOrderRequestDTO,
	OrderAcceptAttendeeRequestDTO,
	OrderAcceptAttendeesRequestDTO,
	OrderCourierAttendeRequestDTO,
	OrderDTO,
	OrderShipmentDTO,
} from 'palriderapptypes/order';
import { PaginationRequestDTO } from 'palriderapptypes/common';
import { DateType } from 'react-native-ui-datepicker';

export const orderApi = createApi({
	reducerPath: 'order',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		getOrders: builder.query<
			PaginationDataResultT<OrderDTO>,
			PaginationRequestDTO & {
				status: string;
				company_area_id: string | null;
				company_area_address_id: string | null;
				order_start_date: DateType | undefined;
				order_end_date: DateType | undefined;
				order_no: string | null;
			}
		>({
			query(query) {
				return {
					method: 'POST',
					params: {
						page: query.page,
						size: query.size,
						sorting_column: 'id',
						sorting: 'desc',
					},
					url: `order/all`,
					body: {
						status: query.status,
						company_area_id: query.company_area_id,
						company_area_address_id: query.company_area_address_id,
						order_start_date: query.order_start_date ?? null,
						order_end_date: query.order_end_date ?? null,
						order_no: query.order_no,
					},
				};
			},
		}),
		getNearbyOrders: builder.query<
			PaginationDataResultT<OrderDTO>,
			PaginationRequestDTO & {
				latitude: number;
				longitude: number;
			}
		>({
			query(query) {
				return {
					method: 'GET',
					params: {
						page: query.page,
						size: query.size,
						latitude: query.latitude,
						longitude: query.longitude,
					},
					url: `order/get-nearby-orders`,
				};
			},
		}),
		getOrder: builder.query<SuccessfulResponseT<OrderDTO>, string>({
			query(order_id) {
				return {
					method: 'GET',
					url: `order/${order_id}`,
				};
			},
		}),
		getCourierActiveOrder: builder.query<SuccessfulResponseT<CourierActiveOrderDTO>, string>({
			query(order_id) {
				return {
					method: 'GET',
					url: `order/${order_id}/courier`,
					headers: {
						Cache: 'no-cache',
					},
				};
			},
		}),
		getOrderShipments: builder.query<
			PaginationDataResultT<OrderShipmentDTO>,
			PaginationRequestDTO & {
				order_id: string;
			}
		>({
			query(query) {
				return {
					method: 'GET',
					params: {
						page: query.page,
						size: query.size,
					},
					url: `order/${query.order_id}/shipments`,
				};
			},
			keepUnusedDataFor: 0.001,
		}),
		getCourierActiveOrderShipments: builder.query<PaginationDataResultT<OrderShipmentDTO>, void>({
			query() {
				return {
					method: 'GET',
					url: `order/courier/shipments`,
				};
			},
		}),
		createOrder: builder.mutation<SuccessfulResponse, CreateOrderRequestDTO>({
			query(body) {
				return {
					method: 'POST',
					url: 'order/create-order',
					body,
				};
			},
		}),
		attendOrder: builder.mutation<SuccessfulResponse, OrderCourierAttendeRequestDTO & { order_id: string }>({
			query(body) {
				return {
					method: 'POST',
					url: `order/${body.order_id}/attend`,
					body: {
						latitude: body.latitude,
						longitude: body.longitude,
					},
				};
			},
		}),
		arrivingOrder: builder.query<SuccessfulResponse, { order_id: string; courier_id: string }>({
			query(body) {
				return {
					method: 'GET',
					url: `order/${body.order_id}/${body.courier_id}/arriving`,
				};
			},
		}),

		arriveOrder: builder.query<SuccessfulResponse, { order_id: string; courier_id: string }>({
			query(body) {
				return {
					method: 'GET',
					url: `order/${body.order_id}/${body.courier_id}/arrived`,
				};
			},
		}),
		abondonOrder: builder.query<SuccessfulResponse, string>({
			query(order_id) {
				return {
					method: 'GET',
					url: `order/${order_id}/abondon`,
				};
			},
		}),
		abondonActiveOrder: builder.query<SuccessfulResponse, string>({
			query(order_id) {
				return {
					method: 'GET',
					url: `order/${order_id}/abondon-active-order`,
				};
			},
		}),
		acceptAttendees: builder.mutation<SuccessfulResponse, OrderAcceptAttendeesRequestDTO>({
			query(body) {
				return {
					method: 'POST',
					url: `order/${body.order_id}/accept-attendees`,
					body: {
						courier_ids: body.courier_ids,
					},
				};
			},
		}),
		acceptAttendee: builder.query<SuccessfulResponse, OrderAcceptAttendeeRequestDTO>({
			query(body) {
				return {
					method: 'GET',
					url: `order/${body.order_id}/${body.courier_id}/accept-attendee`,
				};
			},
		}),
		completeActiveCourierOrder: builder.query<SuccessfulResponse, void>({
			query() {
				return {
					method: 'GET',
					url: 'order/complete-active-courier-order',
				};
			},
		}),

		finishOrderEarly: builder.mutation<SuccessfulResponse, string>({
			query(order_id) {
				return {
					method: 'POST',
					url: `order/${order_id}/finish-order-early`,
				};
			},
		}),
	}),
});

export const {
	useLazyGetOrdersQuery,
	useLazyGetOrderQuery,
	useLazyGetOrderShipmentsQuery,
	useLazyGetNearbyOrdersQuery,
	useCreateOrderMutation,
	useAttendOrderMutation,
	useLazyAbondonOrderQuery,
	useLazyAbondonActiveOrderQuery,
	useAcceptAttendeesMutation,
	useLazyArrivingOrderQuery,
	useLazyArriveOrderQuery,
	useLazyAcceptAttendeeQuery,
	useLazyGetCourierActiveOrderQuery,
	useLazyGetCourierActiveOrderShipmentsQuery,
	useLazyCompleteActiveCourierOrderQuery,
	useFinishOrderEarlyMutation,
} = orderApi;
