import React, { useCallback, useEffect } from 'react';
import { FlatList, RefreshControl, StyleSheet, View } from 'react-native';
import colors from '@/theme/colors.ts';
import { PADDING } from '@/theme/responsive';
import { CompositeScreenProps } from '@react-navigation/native';
import {
	AppCompanyProfileCompanyAreaParamList,
	AppCompanyProfileParamList,
	AppCompanyTabParamList,
} from '@/navigation/company-navigation';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import { useLazyGetCompanyAreaAddressWalletTransferRequestListQuery } from '@/services/api/company/company-area-address-wallet';
import PalRiderText from '@/components/PalRiderText';

import { FontFamily } from '@/theme/fonts';
import { CompanyWalletTransferRequestDTO } from 'palriderapptypes/company';
import { TZDate } from '@date-fns/tz';
import Icon from '@/components/Icon';

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList, 'CompanyAreaAddressWalletTransferRequests'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyAreaStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
			CompositeScreenProps<
				NativeStackScreenProps<RootStackParamList>,
				NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList>
			>
		>
	>
>;

const AppCompanyProfileCompanyAreaAddressWalletTransferRequestScreen: React.FC<Props> = ({ navigation, route }) => {
	const [getCompanyAreaAddressWalletTransferRequestList, { data, isFetching }] =
		useLazyGetCompanyAreaAddressWalletTransferRequestListQuery();

	if (!route.params.company_area_address_wallet_id) navigation.goBack();

	const refreshList = useCallback(() => {
		getCompanyAreaAddressWalletTransferRequestList({
			page: 1,
			size: 100,
			company_area_address_wallet_id: route.params.company_area_address_wallet_id,
		});
	}, []);

	useEffect(() => {
		refreshList();
	}, []);
	const getStatusIcon = (status: CompanyWalletTransferRequestDTO['status']) => {
		switch (status) {
			case 'pending':
				return <Icon name="TimerPauseRoundedIconSvg" width={20} height={20} color={colors.orange[500]} />;
			case 'approved':
				return <Icon name="CheckCircleIconSvg" width={20} height={20} color={colors.green[500]} />;
			case 'rejected':
				return <Icon name="CloseIconSvg" width={20} height={20} color={colors.red[500]} />;
			default:
				return <Icon name="TimerPauseRoundedIconSvg" width={20} height={20} color={colors.gray[400]} />;
		}
	};

	const getStatusColor = (status: CompanyWalletTransferRequestDTO['status']) => {
		switch (status) {
			case 'pending':
				return colors.orange[100];
			case 'approved':
				return colors.green[100];
			case 'rejected':
				return colors.red[100];
			default:
				return colors.gray[100];
		}
	};

	const getStatusTextColor = (status: CompanyWalletTransferRequestDTO['status']) => {
		switch (status) {
			case 'pending':
				return colors.orange[700];
			case 'approved':
				return colors.green[700];
			case 'rejected':
				return colors.red[700];
			default:
				return colors.gray[700];
		}
	};

	const formatDate = (dateString: string) => {
		return new TZDate(dateString, 'Europe/London').toUTCString();
	};

	const formatAmount = (amount: number) => {
		return `£${amount.toFixed(2)}`;
	};

	const renderTransferRequest = ({ item }: { item: CompanyWalletTransferRequestDTO }) => {
		return (
			<View style={styles.requestContainer}>
				{/* Header with amount and status */}
				<View style={styles.requestHeader}>
					<View style={styles.amountContainer}>
						<Icon name="PoundBanknoteIconSvg" width={24} height={24} />
						<PalRiderText fontFamily={FontFamily.Bold} fontSize={20} color={colors.gray[900]}>
							{formatAmount(item.amount)}
						</PalRiderText>
					</View>
					<View style={[styles.statusBadge, { backgroundColor: getStatusColor(item.status) }]}>
						{getStatusIcon(item.status)}
						<PalRiderText fontFamily={FontFamily.Semibold} fontSize={12} color={getStatusTextColor(item.status)}>
							{item.status.charAt(0).toUpperCase() + item.status.slice(1)}
						</PalRiderText>
					</View>
				</View>

				{/* User information */}
				<View style={styles.userInfoContainer}>
					<View style={styles.userDetails}>
						<PalRiderText fontFamily={FontFamily.Semibold} fontSize={14} color={colors.gray[700]}>
							Requested by
						</PalRiderText>
						<PalRiderText fontFamily={FontFamily.Bold} fontSize={16} color={colors.gray[900]}>
							{item.company_area_address_user?.name} {item.company_area_address_user?.surname}
						</PalRiderText>
					</View>
				</View>

				{/* Timestamp */}
				<View style={styles.timestampContainer}>
					<PalRiderText fontFamily={FontFamily.Regular} fontSize={12} color={colors.gray[500]}>
						Created: {formatDate(item.created_at)}
					</PalRiderText>
					{item.status === 'approved' && item.approved_at && (
						<PalRiderText fontFamily={FontFamily.Regular} fontSize={12} color={colors.green[600]}>
							Approved: {formatDate(item.approved_at)}
						</PalRiderText>
					)}
					{item.status === 'rejected' && item.rejected_at && (
						<PalRiderText fontFamily={FontFamily.Regular} fontSize={12} color={colors.red[600]}>
							Rejected: {formatDate(item.rejected_at)}
						</PalRiderText>
					)}
				</View>
			</View>
		);
	};

	const EmptyState = () => (
		<View style={styles.emptyStateContainer}>
			<Icon name="PoundBanknoteIconSvg" width={64} height={64} />
			<PalRiderText fontFamily={FontFamily.Semibold} fontSize={18} color={colors.gray[600]}>
				No Transfer Requests
			</PalRiderText>
			<PalRiderText fontFamily={FontFamily.Regular} fontSize={14} color={colors.gray[500]}>
				When transfer requests are made, they will appear here
			</PalRiderText>
		</View>
	);

	return (
		<View style={styles.container}>
			<FlatList
				data={data?.data ?? []}
				renderItem={renderTransferRequest}
				keyExtractor={(item) => item.id}
				showsVerticalScrollIndicator={false}
				contentContainerStyle={[styles.listContainer, { flexGrow: 1 }]}
				ItemSeparatorComponent={() => <View style={styles.separator} />}
				ListEmptyComponent={<EmptyState />}
				refreshControl={
					<RefreshControl
						onRefresh={refreshList}
						refreshing={isFetching}
						colors={[colors.orange[600]]}
						tintColor={colors.orange[600]}
					/>
				}
			/>
		</View>
	);
};

const styles = StyleSheet.create({
	container: {
		backgroundColor: colors.gray[50],
		flex: 1,
	},
	listContainer: {
		padding: PADDING.large,
		paddingBottom: PADDING.large * 2,
	},
	requestContainer: {
		backgroundColor: colors.white,
		borderRadius: 16,
		padding: PADDING.large,
		shadowColor: colors.black,
		shadowOffset: {
			width: 0,
			height: 2,
		},
		shadowOpacity: 0.1,
		shadowRadius: 8,
		elevation: 4,
		borderWidth: 1,
		borderColor: colors.gray[100],
	},
	requestHeader: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
		marginBottom: PADDING.medium,
	},
	amountContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: PADDING.small,
	},
	statusBadge: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: PADDING.small,
		paddingHorizontal: PADDING.medium,
		paddingVertical: PADDING.small,
		borderRadius: 20,
	},
	userInfoContainer: {
		paddingVertical: PADDING.small,
		marginBottom: PADDING.medium,
	},
	userDetails: {
		flex: 1,
		gap: 4,
	},
	timestampContainer: {
		borderTopWidth: 1,
		borderTopColor: colors.gray[100],
		paddingTop: PADDING.medium,
		gap: 4,
	},
	separator: {
		height: PADDING.medium,
	},
	emptyStateContainer: {
		flex: 1,
		justifyContent: 'center',
		alignItems: 'center',
		paddingVertical: PADDING.large * 3,
		gap: PADDING.medium,
	},
});

export default AppCompanyProfileCompanyAreaAddressWalletTransferRequestScreen;
