import React from 'react';
import { StyleSheet, View } from 'react-native';
import colors from '@/theme/colors.ts';
import { useFormik } from 'formik';
import PalRiderTextInput from '@/components/PalRiderTextInput';
import { PADDING } from '@/theme/responsive';
import PalRiderButton from '@/components/PalRiderButton';
import { useCreateBankAccountMutation } from '@/services/api/courier/courier-bank-account';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { formatSortNumber, isFetchBaseQueryError } from '@/utils';
import WarningModal from '@/components/custom-modal/WarningModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import { CompositeScreenProps, useNavigation } from '@react-navigation/native';
import { object, string } from 'yup';
import PalRiderText from '@/components/PalRiderText';
import { CreateCourierBankAccountRequestDTO } from 'palriderapptypes/courier';

import { AppCourierProfileStackParamList, AppCourierTabParamList } from '@/navigation/courier-navigation';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { RootStackParamList } from '@/navigation';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCourierProfileStackParamList, 'CourierCreateBankAccount'>,
	CompositeScreenProps<
		BottomTabScreenProps<AppCourierTabParamList, 'CourierProfileStack'>,
		NativeStackScreenProps<RootStackParamList>
	>
>;

const AppCourierProfileBankAccountCreateScreen: React.FC<Props> = ({ navigation }) => {
	const [createBankAccount] = useCreateBankAccountMutation();
	const { showGlobalModal } = useModal();
	const createBankAccountFormik = useFormik<CreateCourierBankAccountRequestDTO>({
		initialValues: {
			title: '',
			account_holder_name: '',
			sort_code: '',
			account_number: '',
		},
		validateOnChange: false,
		validationSchema: object({
			title: string().label('Title').min(3).required('Title is required'),
			account_holder_name: string()
				.label('Account Holder Name')
				.min(3)
				.matches(/^[a-zA-Z\s'-]+$/, 'Invalid name format')
				.required('Account holder name is required'),
			sort_code: string()
				.label('Sort Code')
				.matches(/^\d{2}-?\d{2}-?\d{2}$/g, 'Sort code must be in format XX-XX-XX')
				.required('Sort code is required'),
			account_number: string()
				.label('Account Number')
				.matches(/^\d{8}$/, 'Account number must be exactly 8 digits')
				.required('Account number is required'),
		}),

		onSubmit: async (values) => {
			showGlobalModal({
				children: <LoadingModal />,
			});
			const res = await createBankAccount(values);
			if (res.error && isFetchBaseQueryError(res.error)) {
				showGlobalModal({
					children: <WarningModal text={res.error.data.title} />,
				});
				return;
			}

			showGlobalModal({
				children: <SuccessModal text="Bank Account Added" />,
				whenClose() {
					navigation.goBack();
				},
			});
		},
	});
	return (
		<View style={styles.container}>
			<View style={styles.formContainer}>
				<PalRiderTextInput
					title="Title"
					value={createBankAccountFormik.values.title}
					error={createBankAccountFormik.errors.title}
					onChangeText={createBankAccountFormik.handleChange('title')}
				/>
				<PalRiderTextInput
					title="Account Holder Name"
					value={createBankAccountFormik.values.account_holder_name}
					error={createBankAccountFormik.errors.account_holder_name}
					onChangeText={createBankAccountFormik.handleChange('account_holder_name')}
				/>
				<PalRiderTextInput
					title="Sort Code"
					value={createBankAccountFormik.values.sort_code}
					error={createBankAccountFormik.errors.sort_code}
					maxLength={8}
					keyboardType="numeric"
					onChangeText={(text) => createBankAccountFormik.setFieldValue('sort_code', formatSortNumber(text))}
				/>
				<PalRiderTextInput
					title="Account Number"
					value={createBankAccountFormik.values.account_number}
					error={createBankAccountFormik.errors.account_number}
					onChangeText={createBankAccountFormik.handleChange('account_number')}
					keyboardType="numeric"
				/>
				<PalRiderButton variant="dark" onPress={() => createBankAccountFormik.handleSubmit()}>
					<PalRiderText color={colors.white}>Add</PalRiderText>
				</PalRiderButton>
			</View>
		</View>
	);
};
const styles = StyleSheet.create({
	container: {
		backgroundColor: colors.white,
		flex: 1,
	},
	formContainer: {
		gap: PADDING.large,
		padding: PADDING.large,
	},
});
export default AppCourierProfileBankAccountCreateScreen;
