import { yupTyped } from '@/types';
import { isFetchBaseQueryError } from '@/utils';
import { useFormik } from 'formik';
import React, { useState } from 'react';
import { Image, Pressable, StyleSheet, View, Alert } from 'react-native';
import { KeyboardAwareScrollView } from 'react-native-keyboard-aware-scroll-view';
import SignUpCourierDocumentInfoScreenDocument from 'src/screens/auth/signup/courier/components/courier-document/components/SignUpCourierDocumentInfoScreenDocument.tsx';
import { font, PADDING } from '@/theme/responsive.ts';
import PalRiderText from '@/components/PalRiderText.tsx';
import colors from '@/theme/colors.ts';
import { FontFamily } from '@/theme/fonts.ts';
import PalRiderButton from '@/components/PalRiderButton.tsx';
import { useAppDispatch, useAppSelector } from '@/redux/hooks.ts';
import { setCourierDocumentOnboardingState } from '@/redux/slices/courier-onboarding.ts';
import { buttonStyling } from '@/theme/defaults.ts';
import { globalStyles } from '@/utils/global-styles';
import { mixed } from 'yup';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import PalRiderBottomSelectModal from '@/components/PalRiderBottomSelectModal';
import { launchCamera, launchImageLibrary } from 'react-native-image-picker';
import { FileType } from '@/@types';
import { OnboardingCourierDocumentInfoRequestDTO } from 'palriderapptypes/courier';
import Icon from '@/components/Icon';

type Props = {
	nextStep: () => void;
	prevStep: () => void;
};

type DocumentKey =
	| 'profile_photo'
	| 'identity_card_front'
	| 'identity_card_back'
	| 'driver_licence_front'
	| 'driver_licence_back';

const SignUpCourierDocumentInfoStep: React.FC<Props> = ({ nextStep, prevStep }) => {
	const dispatch = useAppDispatch();
	const courierOnboardingSelector = useAppSelector((x) => x.courierOnboardingSlice);
	const insets = useSafeAreaInsets();

	// Simple state management
	const [activeModal, setActiveModal] = useState<DocumentKey | null>(null);

	const signUpCourierOnboardDocumentFormik = useFormik<OnboardingCourierDocumentInfoRequestDTO>({
		initialValues: {
			profile_photo: courierOnboardingSelector.documents.profile_photo,
			identity_card_front: courierOnboardingSelector.documents.identity_card_front,
			identity_card_back: courierOnboardingSelector.documents.identity_card_back,
			driver_licence_front: courierOnboardingSelector.documents.driver_licence_front,
			driver_licence_back: courierOnboardingSelector.documents.driver_licence_back,
		},
		validationSchema: yupTyped<OnboardingCourierDocumentInfoRequestDTO>({
			profile_photo: mixed().required().label('Profile Photo'),
			identity_card_front: mixed().required().label('Identity Card Front'),
			identity_card_back: mixed().required().label('Identity Card Back'),
			driver_licence_front: mixed().required().label('Driver Licence Front'),
			driver_licence_back: mixed().required().label('Driver Licence Back'),
		}),
		validateOnChange: false,
		onSubmit: async (values) => {
			try {
				dispatch(setCourierDocumentOnboardingState(values));
				nextStep();
			} catch (err) {
				if (isFetchBaseQueryError(err)) {
					// handle error
				}
			}
		},
	});

	// Simplified image picker functions (like your working example)
	const pickFromLibrary = async (documentKey: DocumentKey) => {
		try {
			const result = await launchImageLibrary({
				mediaType: 'photo',
				selectionLimit: 1,
				quality: 0.8,
			});

			// Close modal after getting result
			setActiveModal(null);

			if (result.assets && result.assets.length > 0) {
				const file = result.assets[0];
				const fileData: FileType = {
					name: file.fileName || `${documentKey}_${Date.now()}.jpg`,
					size: file.fileSize || 0,
					type: file.type || 'image/jpeg',
					uri: file.uri || '',
				};

				signUpCourierOnboardDocumentFormik.setFieldValue(documentKey, fileData);
			}
		} catch (error) {
			console.error('Error picking from library:', error);
			setActiveModal(null); // Make sure to close modal on error
			Alert.alert('Error', 'Failed to pick image from library');
		}
	};

	const takePhoto = async (documentKey: DocumentKey) => {
		try {
			const result = await launchCamera({
				mediaType: 'photo',
				saveToPhotos: true,
				quality: 0.8,
			});

			// Close modal after getting result
			setActiveModal(null);

			if (result.assets && result.assets.length > 0) {
				const file = result.assets[0];
				const fileData: FileType = {
					name: file.fileName || `${documentKey}_${Date.now()}.jpg`,
					size: file.fileSize || 0,
					type: file.type || 'image/jpeg',
					uri: file.uri || '',
				};

				signUpCourierOnboardDocumentFormik.setFieldValue(documentKey, fileData);
			}
		} catch (error) {
			console.error('Error taking photo:', error);
			setActiveModal(null); // Make sure to close modal on error
			Alert.alert('Error', 'Failed to take photo');
		}
	};

	const showDocumentModal = (documentKey: DocumentKey) => {
		setActiveModal(documentKey);
	};

	const hideDocumentModal = () => {
		setActiveModal(null);
	};

	return (
		<KeyboardAwareScrollView
			contentContainerStyle={[styles.scrollViewContainer, { paddingBottom: insets.bottom }]}
			style={styles.container}
		>
			{/* Keep modal mounted, control visibility with isVisible prop */}
			<PalRiderBottomSelectModal
				data={[
					{
						text: 'Pick From Library',
						onPress: () => activeModal && pickFromLibrary(activeModal),
					},
					{
						text: 'Take A Photo',
						onPress: () => activeModal && takePhoto(activeModal),
					},
				]}
				isVisible={activeModal !== null}
				title="Select Image Source"
				cancelOnPress={hideDocumentModal}
				isCoverScreen
			/>

			<View style={{ flex: 1 }}>
				<View style={{ paddingVertical: PADDING.xxlarge }}>
					{/* Profile Photo Section */}
					<View>
						<View style={styles.headerRow}>
							<PalRiderText style={styles.profileTitle}>Profile Photo</PalRiderText>
							<PalRiderText color={colors.red[600]} fontFamily={FontFamily.Semibold}>
								*
							</PalRiderText>
						</View>
						<View style={styles.profilePhotoContainer}>
							{signUpCourierOnboardDocumentFormik.values.profile_photo ? (
								<View>
									<Pressable style={styles.overlayCameraButton} onPress={() => showDocumentModal('profile_photo')}>
										<Icon name="CameraIconSvg" color="white" />
									</Pressable>
									<Image
										source={{ uri: signUpCourierOnboardDocumentFormik.values.profile_photo.uri }}
										style={styles.profilePhotoImage}
										resizeMode="cover"
									/>
								</View>
							) : (
								<View style={{ justifyContent: 'center', alignItems: 'center' }}>
									<Pressable
										style={[
											styles.profilePhotoSelectButton,
											{
												borderColor: signUpCourierOnboardDocumentFormik.errors.profile_photo
													? colors.red[600]
													: colors.gray[300],
											},
										]}
										onPress={() => showDocumentModal('profile_photo')}
									>
										<Icon name="CameraIconSvg" />
										<PalRiderText style={styles.profileDescription}>Upload Photo</PalRiderText>
									</Pressable>
									{signUpCourierOnboardDocumentFormik.errors.profile_photo && (
										<PalRiderText style={globalStyles.errorTextStyle}>
											{signUpCourierOnboardDocumentFormik.errors.profile_photo}
										</PalRiderText>
									)}
								</View>
							)}
						</View>
					</View>

					{/* Document Upload Components */}
					<SignUpCourierDocumentInfoScreenDocument
						title="Identity Card Front"
						onPress={() => showDocumentModal('identity_card_front')}
						value={signUpCourierOnboardDocumentFormik.values.identity_card_front}
						error={signUpCourierOnboardDocumentFormik.errors.identity_card_front}
					/>
					<SignUpCourierDocumentInfoScreenDocument
						title="Identity Card Back"
						onPress={() => showDocumentModal('identity_card_back')}
						value={signUpCourierOnboardDocumentFormik.values.identity_card_back}
						error={signUpCourierOnboardDocumentFormik.errors.identity_card_back}
					/>
					<SignUpCourierDocumentInfoScreenDocument
						title="Driver Licence Front"
						onPress={() => showDocumentModal('driver_licence_front')}
						value={signUpCourierOnboardDocumentFormik.values.driver_licence_front}
						error={signUpCourierOnboardDocumentFormik.errors.driver_licence_front}
					/>
					<SignUpCourierDocumentInfoScreenDocument
						title="Driver Licence Back"
						onPress={() => showDocumentModal('driver_licence_back')}
						value={signUpCourierOnboardDocumentFormik.values.driver_licence_back}
						error={signUpCourierOnboardDocumentFormik.errors.driver_licence_back}
					/>
				</View>

				{/* Navigation Buttons */}
				<View style={{ flexDirection: 'row', gap: PADDING.medium }}>
					<PalRiderButton style={[buttonStyling.dark, { flex: 1 }]} onPress={prevStep}>
						<PalRiderText color="white">Go Back</PalRiderText>
					</PalRiderButton>
					<PalRiderButton
						style={[buttonStyling.dark, { flex: 1 }]}
						onPress={() => signUpCourierOnboardDocumentFormik.handleSubmit()}
					>
						<PalRiderText color="white">Continue</PalRiderText>
					</PalRiderButton>
				</View>
			</View>
		</KeyboardAwareScrollView>
	);
};

export default SignUpCourierDocumentInfoStep;

const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.white,
		padding: PADDING.large,
	},
	scrollViewContainer: {
		rowGap: PADDING.large,
		flex: 1,
	},
	profilePhotoContainer: {
		padding: PADDING.large,
		alignItems: 'center',
	},
	profileTitle: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.small,
	},
	profileDescription: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.mini,
	},
	profilePhotoImage: {
		width: PADDING.medium * 13,
		height: PADDING.medium * 13,
		borderRadius: PADDING.medium * 13,
	},
	profilePhotoSelectButton: {
		width: PADDING.medium * 13,
		height: PADDING.medium * 13,
		borderRadius: PADDING.medium * 13,
		borderWidth: 1,
		borderColor: colors.gray[300],
		justifyContent: 'center',
		alignItems: 'center',
	},
	overlayCameraButton: {
		backgroundColor: 'rgba(0,0,0,0.2)',
		position: 'absolute',
		zIndex: 999,
		top: 0,
		left: 0,
		right: 0,
		bottom: 0,
		justifyContent: 'center',
		alignItems: 'center',
		borderRadius: PADDING.medium * 13,
	},
	headerRow: {
		flexDirection: 'row',
		columnGap: 2,
		justifyContent: 'center',
		alignItems: 'center',
	},
});
