import { isFetchBaseQueryError, requestLocationPermission } from '@/utils';
import Geolocation from '@react-native-community/geolocation';
import React, { useEffect, useState } from 'react';
import { ActivityIndicator, FlatList, StyleSheet, View, InteractionManager } from 'react-native';
import { useLazyGetNearbyOrdersQuery } from '@/services/api/order';
import { PADDING } from '@/theme/responsive';
import colors from '@/theme/colors';
import CompanyNearbyOrderItemRender from './components/CompanyNearbyOrderItemRender';
import { useAppSelector } from '@/redux/hooks';
import PalRiderText from '@/components/PalRiderText';
import { useModal } from '@/components/ModalProvider';
import WarningModal from '@/components/custom-modal/WarningModal';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { OrderDTO } from 'palriderapptypes/order';
import { AppCourierTabParamList } from '@/navigation/courier-navigation';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { RootStackParamList } from '@/navigation';
import Icon from '@/components/Icon';

type Props = BottomTabScreenProps<AppCourierTabParamList, 'CourierOrder'> & NativeStackScreenProps<RootStackParamList>;

const AppCourierOrderScreen: React.FC<Props> = ({ navigation }) => {
	const { showGlobalModal } = useModal();
	const [currentPage, setCurrentPage] = useState(1);
	const [totalPages, setTotalPages] = useState(1);
	const [data, setData] = useState<Array<OrderDTO>>([]);
	const [userLocation, setUserLocation] = useState<{ latitude: number; longitude: number } | null>(null);

	const [getNearbyOrders, { isLoading, isFetching }] = useLazyGetNearbyOrdersQuery();
	const userSelector = useAppSelector((x) => x.userSlice.user);

	// helper: get current location
	const getCurrentLocation = (): Promise<{ latitude: number; longitude: number }> => {
		return new Promise((resolve, reject) => {
			Geolocation.getCurrentPosition(
				(pos) =>
					resolve({
						latitude: pos.coords.latitude,
						longitude: pos.coords.longitude,
					}),
				reject,
				{ enableHighAccuracy: true, timeout: 10000, maximumAge: 1000 },
			);
		});
	};

	// fetch orders
	const fetchOrders = async (page: number, refresh = false, location?: { latitude: number; longitude: number }) => {
		if (page > totalPages || isFetching) return;

		try {
			const pos = location ?? (await getCurrentLocation());
			if (!pos) return;

			const res = await getNearbyOrders({
				page,
				size: 10,
				latitude: pos.latitude,
				longitude: pos.longitude,
			}).unwrap();

			if (!res?.data) return;

			setData((prev) => (refresh ? res.data : [...prev, ...res.data]));
			setTotalPages(res.total_pages ?? 1);
			setCurrentPage(page);
		} catch (err: any) {
			if (isFetchBaseQueryError(err)) {
				showGlobalModal({
					children: (
						<WarningModal
							icon={<Icon name="WarningIconSvg" color={colors.orange[600]} width={56} height={56} />}
							text={err.data?.title ?? 'Error fetching orders'}
						/>
					),
				});
			} else {
				showGlobalModal({ children: <WarningModal text={err.message} /> });
			}
		}
	};

	// On mount: request location and fetch
	useEffect(() => {
		const task = InteractionManager.runAfterInteractions(async () => {
			const requestAccess = await requestLocationPermission();
			if (!requestAccess) {
				showGlobalModal({
					children: (
						<WarningModal
							text="Location is disabled. Please enable it to view orders."
							icon={<Icon name="LocationNotGrantedIconSvg" width={64} height={64} color={colors.red[600]} />}
						/>
					),
					whenClose() {
						navigation.jumpTo('CourierHome');
					},
				});
				return;
			}

			try {
				const pos = await getCurrentLocation();
				setUserLocation(pos);
				await fetchOrders(1, true, pos);
			} catch (geoError: any) {
				showGlobalModal({ children: <WarningModal text={geoError.message} /> });
			}
		});

		return () => task.cancel();
	}, []);

	return (
		<View style={styles.container}>
			<FlatList
				data={data}
				refreshing={isFetching}
				onRefresh={() => fetchOrders(1, true, userLocation!)}
				keyExtractor={(item: OrderDTO) => `${item.status}-${item.id}`}
				renderItem={(props) => (
					<CompanyNearbyOrderItemRender
						{...props}
						navigation={navigation}
						user={userSelector}
						reloadOrders={() => fetchOrders(1, true, userLocation!)}
					/>
				)}
				showsVerticalScrollIndicator={false}
				contentContainerStyle={styles.listContainer}
				onEndReached={() => fetchOrders(currentPage + 1, false, userLocation!)}
				onEndReachedThreshold={0.3}
				ItemSeparatorComponent={() => <View style={{ height: PADDING.large }} />}
				ListFooterComponent={
					isLoading || isFetching ? <ActivityIndicator size="large" color={colors.orange[600]} /> : null
				}
				ListEmptyComponent={
					<View style={styles.emptyContainer}>
						<Icon name="MapPinsIconSvg" width={72} height={72} color={colors.gray[400]} />
						<PalRiderText style={styles.emptyText}>No orders nearby</PalRiderText>
					</View>
				}
			/>
		</View>
	);
};

const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.gray[50],
	},
	header: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
		paddingHorizontal: PADDING.large,
		paddingVertical: PADDING.medium,
		backgroundColor: colors.white,
		borderBottomWidth: StyleSheet.hairlineWidth,
		borderBottomColor: colors.gray[200],
		elevation: 2,
	},
	headerTitle: {
		fontSize: 20,
		fontWeight: '600',
		color: colors.gray[900],
	},
	listContainer: {
		padding: PADDING.large,
	},
	emptyContainer: {
		flex: 1,
		justifyContent: 'center',
		alignItems: 'center',
		paddingVertical: PADDING.xxlarge,
	},
	emptyText: {
		marginTop: PADDING.medium,
		color: colors.gray[500],
		fontSize: 16,
	},
});

export default AppCourierOrderScreen;
