import React from 'react';
import colors from '@/theme/colors';
import { useFormik } from 'formik';
import { StyleSheet, View } from 'react-native';
import { ScrollView } from 'react-native-gesture-handler';
import { PADDING } from '@/theme/responsive';
import { yupTyped } from '@/types';
import { string } from 'yup';
import { useStoreCompanyAreaMutation } from '@/services/api/company/company-area';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import WarningModal from '@/components/custom-modal/WarningModal';
import PalRiderButton from '@/components/PalRiderButton';
import PalRiderText from '@/components/PalRiderText';

import { CompositeScreenProps } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import {
	AppCompanyProfileCompanyAreaParamList,
	AppCompanyProfileParamList,
	AppCompanyTabParamList,
} from '@/navigation/company-navigation';
import { useTranslation } from 'react-i18next';
import { englandCountiesByRegion, isFetchBaseQueryError } from '@/utils';
import Dropdown from 'react-native-input-select';
import { globalStyles } from '@/utils/global-styles';

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList, 'CompanyAreaCreate'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyAreaStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
			CompositeScreenProps<
				NativeStackScreenProps<RootStackParamList>,
				NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList>
			>
		>
	>
>;
type FormikType = {
	name: string;
	email: string;
};

const AppCompanyProfileAreaCreateScreen: React.FC<Props> = ({ route, navigation }) => {
	const { t } = useTranslation();
	if (!route.params.company_id) navigation.goBack();
	const [storeCompanyArea] = useStoreCompanyAreaMutation();
	const { showGlobalModal, hideGlobalModal } = useModal();

	if (!route.params.company_id) {
		navigation.goBack();
		return;
	}

	const addCompanyAreaFormik = useFormik({
		initialValues: {
			name: '',
			email: '',
		},
		validationSchema: yupTyped<FormikType>({
			name: string().label('Name').required().max(50),
			email: string().label('Email').nullable().email().notRequired(),
		}),
		onSubmit: async (values) => {
			showGlobalModal({
				children: <LoadingModal />,
				preventHiding: true,
				backgroundColor: colors.transparent,
			});

			const res = await storeCompanyArea({
				...values,
				company_id: route.params.company_id,
			});
			if (res.error && isFetchBaseQueryError(res.error)) {
				showGlobalModal({
					children: <WarningModal text={res.error.data.title} />,
				});
				return;
			}
			showGlobalModal({
				children: <SuccessModal text={res.data?.message} />,
				whenClose() {
					navigation.goBack();
				},
			});
		},
	});
	return (
		<View style={styles.container}>
			<ScrollView
				style={styles.scrollContainer}
				contentContainerStyle={styles.scrollContainer}
				showsVerticalScrollIndicator={false}
			>
				<View style={styles.formContainer}>
					<View style={styles.formInnerContainer}>
						<View>
							<View style={{ flexDirection: 'row', columnGap: PADDING.medium }}>
								<PalRiderText style={globalStyles.titleTextStyle}>Select An Area</PalRiderText>
							</View>
							<Dropdown
								{...globalStyles.dropdownProps}
								options={englandCountiesByRegion.map((county) => ({
									value: county,
									label: county,
								}))}
								isSearchable
								isMultiple={false}
								selectedValue={addCompanyAreaFormik.values.name}
								onValueChange={(value) => addCompanyAreaFormik.setFieldValue('name', value)}
								maxSelectableItems={1}
								autoCloseOnSelect
							/>
							{addCompanyAreaFormik.errors.name && (
								<PalRiderText style={globalStyles.errorTextStyle}>{addCompanyAreaFormik.errors.name}</PalRiderText>
							)}
						</View>
						{/* <PalRiderTextInput */}
						{/* 	title={t('common.name')} */}
						{/* 	onChangeText={(text) => addCompanyAreaFormik.setFieldValue('name', text, true)} */}
						{/* 	maxLength={50} */}
						{/* 	onBlur={addCompanyAreaFormik.handleBlur('name')} */}
						{/* 	value={addCompanyAreaFormik.values.name} */}
						{/* 	error={addCompanyAreaFormik.errors.name} */}
						{/* 	autoCapitalize="characters" */}
						{/* 	required */}
						{/* /> */}
						{/* <PalRiderTextInput */}
						{/* 	title={t('common.email')} */}
						{/* 	onChangeText={addCompanyAreaFormik.handleChange} */}
						{/* 	maxLength={50} */}
						{/* 	onBlur={addCompanyAreaFormik.handleBlur('email')} */}
						{/* 	value={addCompanyAreaFormik.values.email} */}
						{/* 	error={addCompanyAreaFormik.errors.email} */}
						{/* /> */}
					</View>
					<View style={styles.addButtonContainer}>
						<PalRiderButton variant="dark" onPress={() => addCompanyAreaFormik.handleSubmit()}>
							<PalRiderText color={colors.white}>{t('common.add')}</PalRiderText>
						</PalRiderButton>
					</View>
				</View>
			</ScrollView>
		</View>
	);
};
const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.white,
	},
	scrollContainer: {
		flex: 1,
		backgroundColor: colors.white,
	},
	formContainer: {
		padding: PADDING.large,
		flex: 1,
	},
	formInnerContainer: {
		flex: 1,
		gap: PADDING.xxlarge,
	},
	addButtonContainer: {},
});
export default AppCompanyProfileAreaCreateScreen;
