import React, { useCallback, useState } from 'react';
import { font, normalize, PADDING } from '@/theme/responsive.ts';
import { Image, Pressable, StyleSheet, View } from 'react-native';
import PalRiderButton from '@/components/PalRiderButton.tsx';
import PalRiderText from '@/components/PalRiderText.tsx';
import colors from '@/theme/colors.ts';
import { FontFamily } from '@/theme/fonts';
import { useFormik } from 'formik';
import { FileType } from '@/@types';
import { array, number, object, string } from 'yup';
import { yupTyped } from '@/types';
import { useAppDispatch, useAppSelector } from '@/redux/hooks';
import { buttonStyling } from '@/theme/defaults';
import { useTranslation } from 'react-i18next';
import { setCreateCompanyAreaAddressPhotos } from '@/redux/slices/create-company-area-address-slice';
import { launchCamera, launchImageLibrary } from 'react-native-image-picker';
import PalRiderBottomSelectModal from '@/components/PalRiderBottomSelectModal';
import { useStoreCompanyAreaAddressMutation } from '@/services/api/company/company-area-address';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { isFetchBaseQueryError } from '@/utils';
import WarningModal from '@/components/custom-modal/WarningModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import { useNavigation } from '@react-navigation/native';
import Icon from '@/components/Icon';

type Props = {
	prevStep: () => void;
};
type AppCompanyProfileCompanyAreaAddressCreatePhotoType = {
	address_photos: Array<FileType>;
};
const AppCompanyProfileCompanyAreaAddressCreatePhoto: React.FC<Props> = ({ prevStep }) => {
	const { t } = useTranslation();
	const dispatch = useAppDispatch();
	const { showGlobalModal } = useModal();
	const createCompanyAreaAddressSlice = useAppSelector((x) => x.createCompanyAreaAddressSlice);
	const [createCompanyAreaAddress] = useStoreCompanyAreaAddressMutation();
	const navigation = useNavigation();

	const [activeModal, setActiveModal] = useState<boolean>(false);
	const createCompanyAreaAddressFormik = useFormik<AppCompanyProfileCompanyAreaAddressCreatePhotoType>({
		initialValues: {
			address_photos: createCompanyAreaAddressSlice.address_photos,
		},
		validationSchema: yupTyped<AppCompanyProfileCompanyAreaAddressCreatePhotoType>({
			address_photos: array()
				.of(
					object().shape({
						name: string().required(t('validation.required', { field: t('common.name') })),
						size: number().required().max(10000000),
						uri: string().required('File uri is required'),
						type: string().required('File type is required'),
					}),
				)
				.required()
				.min(1, 'At least one photo is required'),
		}),
		onSubmit: async (values) => {
			showGlobalModal({
				children: <LoadingModal />,
			});

			try {
				const res = await createCompanyAreaAddress({
					...createCompanyAreaAddressSlice,
					address_photos: values.address_photos,
				});
				if (res.error && isFetchBaseQueryError(res.error)) {
					showGlobalModal({
						children: <WarningModal title={res.error.data.title} />,
					});
					return;
				}

				showGlobalModal({
					children: <SuccessModal text={res.data?.message} />,
					closeAfterDelay: 1000,
					whenClose() {
						navigation.goBack();
					},
				});
			} catch {
				showGlobalModal({
					children: <WarningModal title={'Something went wrong '} />,
				});
			}
		},
	});
	const onFileSelected = (files: FileType[]) => {
		const oldPhotos = createCompanyAreaAddressFormik.values.address_photos;
		const newPhotos: Array<FileType> = [];
		files.map((file) => {
			if (!file.name || !file.uri || !file.size || !file.type) return;
			newPhotos.push({
				name: file.name,
				uri: file.uri,
				size: file.size,
				type: file.type,
			});
		});

		dispatch(setCreateCompanyAreaAddressPhotos([...oldPhotos, ...newPhotos]));
		createCompanyAreaAddressFormik.setFieldValue('address_photos', [...oldPhotos, ...newPhotos]);
		setActiveModal(false);
	};

	// Simplified image picker functions (like your working example)
	const pickFromLibrary = async () => {
		try {
			const result = await launchImageLibrary({
				mediaType: 'photo',
				selectionLimit: 1,
				quality: 0.8,
			});

			if (result.assets && result.assets.length > 0) {
				const file = result.assets[0];
				const fileData: FileType = {
					name: file.fileName ?? '',
					size: file.fileSize || 0,
					type: file.type || 'image/jpeg',
					uri: file.uri || '',
				};

				onFileSelected([fileData]);
			}
		} catch (error) {
			console.error('Error picking from library:', error);
		}
	};

	const takePhoto = async () => {
		try {
			const result = await launchCamera({
				mediaType: 'photo',
				saveToPhotos: true,
				quality: 0.8,
			});

			if (result.assets && result.assets.length > 0) {
				const file = result.assets[0];
				const fileData: FileType = {
					name: file.fileName ?? '',
					size: file.fileSize || 0,
					type: file.type || 'image/jpeg',
					uri: file.uri || '',
				};

				onFileSelected([fileData]);
			}
		} catch (error) {
			console.error('Error taking photo:', error);
		}
	};

	const handleRemoveCancellationImage = (index: number) => {
		const cloned = [...createCompanyAreaAddressFormik.values.address_photos];
		createCompanyAreaAddressFormik.setFieldValue(
			'address_photos',
			cloned.filter((_, indexFilter) => index != indexFilter),
		);
	};
	const renderAddressPhotos = useCallback(() => {
		if (createCompanyAreaAddressFormik.values.address_photos.length > 0) {
			return createCompanyAreaAddressFormik.values.address_photos.map((image, index) => (
				<View style={{ width: 100, height: 100, position: 'relative' }}>
					<Pressable
						style={{
							width: 25,
							height: 25,
							backgroundColor: colors.black,
							position: 'absolute',
							top: 5,
							right: 5,
							zIndex: 999,
							borderRadius: PADDING.large,
							justifyContent: 'center',
							alignItems: 'center',
						}}
						onPress={() => handleRemoveCancellationImage(index)}
					>
						<Icon name="CloseIconSvg" color={colors.white} width={20} height={20} />
					</Pressable>
					<Image source={{ uri: image.uri }} width={100} height={100} />
				</View>
			));
		}
	}, [createCompanyAreaAddressFormik.values.address_photos]);
	return (
		<View style={styles.container}>
			<PalRiderBottomSelectModal
				data={[
					{
						text: 'Pick From Library',
						onPress: () => pickFromLibrary(),
					},
					{
						text: 'Take A Photo',
						onPress: () => takePhoto(),
					},
				]}
				isVisible={activeModal}
				title="Select Image Source"
				cancelOnPress={() => setActiveModal(false)}
				isCoverScreen
			/>

			<View style={styles.selectedDocumentsContainer}>{renderAddressPhotos()}</View>
			<View
				style={[
					styles.documentContainer,
					{
						justifyContent: createCompanyAreaAddressFormik.values.address_photos.length > 0 ? 'flex-start' : 'center',
						paddingBottom: createCompanyAreaAddressFormik.values.address_photos.length > 0 ? PADDING.medium : 0,
					},
				]}
			>
				<PalRiderText style={styles.infoText}>
					We are waiting for the user to provide photos for the address location photos to approval such as
				</PalRiderText>
				<View style={styles.infoListContainer}>
					<PalRiderText style={styles.infoListText}>1. Interior Photo</PalRiderText>
					<PalRiderText style={styles.infoListText}>2. Exterior Photo</PalRiderText>
				</View>
				<View style={styles.chooseContainer}>
					<PalRiderButton
						onPress={() => setActiveModal(true)}
						variant="dark"
						contentStyle={{ flexDirection: 'row', gap: PADDING.large }}
					>
						<PalRiderText fontFamily={FontFamily.Semibold} color={colors.white}>
							Upload Photo
						</PalRiderText>
						<Icon name="UploadIconSvg" color={colors.white} width={16} height={16} />
					</PalRiderButton>
				</View>
			</View>
			<View style={[styles.buttonContainer]}>
				<PalRiderButton style={[buttonStyling.dark, { flex: 1 }]} onPress={() => prevStep()}>
					<PalRiderText color="white">{t('common.go_back')}</PalRiderText>
				</PalRiderButton>
				<PalRiderButton
					variant="success"
					style={{ flex: 1 }}
					onPress={() => createCompanyAreaAddressFormik.handleSubmit()}
				>
					<PalRiderText color="white">{t('common.add')}</PalRiderText>
				</PalRiderButton>
			</View>
		</View>
	);
};
const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.white,
		padding: PADDING.large,
	},
	documentContainer: {
		flex: 1,
	},
	infoText: {
		textAlign: 'left',
		fontSize: font.mini,
		paddingHorizontal: PADDING.large,
		marginBottom: PADDING.medium,
		fontFamily: FontFamily.Semibold,
	},
	infoListContainer: {
		alignItems: 'center',
		paddingHorizontal: PADDING.large,
		gap: PADDING.small,
		marginBottom: PADDING.medium,
		fontFamily: FontFamily.Semibold,
		fontSize: font.mini,
	},
	infoListText: {
		alignSelf: 'flex-start',
		color: colors.green[700],
		fontSize: font.mini,
		fontFamily: FontFamily.Semibold,
	},
	chooseContainer: {
		paddingHorizontal: PADDING.large,
	},
	buttonContainer: {
		flexDirection: 'row',
		gap: normalize(10),
	},
	selectedDocumentsContainer: {
		width: '100%',
		marginBottom: PADDING.large,
		flexDirection: 'row',
		gap: PADDING.medium,
		flexWrap: 'wrap',
	},
	selectedDocumentsContentContainerStyle: {
		gap: PADDING.medium,
		width: '100%',
	},
	documentItemContainer: {
		padding: PADDING.large,
		paddingVertical: PADDING.xxlarge,
		borderWidth: 1,
		borderColor: colors.gray[600],
		flexDirection: 'row',
		flex: 1,
		alignItems: 'center',
		justifyContent: 'space-between',
		gap: PADDING.large,
	},
});
export default AppCompanyProfileCompanyAreaAddressCreatePhoto;
