import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { normalize, PADDING } from '@/theme/responsive';
import React, { LegacyRef, ReactNode, useState } from 'react';
import {
	LayoutChangeEvent,
	StyleProp,
	StyleSheet,
	TextInput,
	TextInputProps,
	TextStyle,
	View,
	ViewStyle,
} from 'react-native';
import PalRiderText from './PalRiderText';
import { FormikErrors } from 'formik';

export type PalRiderTextInputProps = TextInputProps & {
	error?: FormikErrors<unknown>;
	touched?: boolean;
	title?: string;
	inputStyle?: StyleProp<TextStyle> | undefined;
	required?: boolean;
	containerStyle?: ViewStyle;
	leftComponent?: ReactNode;
	rightComponent?: ReactNode;
	leftComponentStyle?: ViewStyle;
};
const PalRiderTextInput: React.FC<PalRiderTextInputProps> = React.forwardRef((props, ref: LegacyRef<TextInput>) => {
	const {
		error,
		touched,
		title,
		inputStyle,
		required,
		containerStyle,
		leftComponent,
		rightComponent,
		...textInputProps
	} = props;

	const [leftComponentDimensions, setLeftComponentDimensions] = useState({
		width: 0,
		height: 0,
	});
	const [rightComponentDimensions, setRightComponentDimensions] = useState({
		width: 0,
		height: 0,
	});
	const [inputHeight, setInputHeight] = useState(0);
	const onLeftComponentLayout = (event: LayoutChangeEvent) => {
		const { width, height } = event.nativeEvent.layout;

		setLeftComponentDimensions({
			width: width,
			height: height,
		});
	};
	const onRightComponentLayout = (event: LayoutChangeEvent) => {
		const { width, height } = event.nativeEvent.layout;

		setRightComponentDimensions({
			width: width,
			height: height,
		});
	};
	const onInputLayout = (event: LayoutChangeEvent) => {
		const { height } = event.nativeEvent.layout;
		setInputHeight(height);
	};
	const calculateLeftComponentTop = () => {
		return inputHeight / 2 - leftComponentDimensions.height / 2;
	};
	const calculateRightComponentTop = () => {
		return inputHeight / 2 - rightComponentDimensions.height / 2;
	};

	const findLeftComponentLeft = () => {
		if (title) {
			return normalize(leftComponentDimensions.width + 4);
		} else {
			return normalize(leftComponentDimensions.width + 4);
		}
	};
	const findRightComponentRight = () => {
		if (title) {
			return normalize(rightComponentDimensions.width + 12 + 4);
		} else {
			return normalize(rightComponentDimensions.width + 12 + 4);
		}
	};
	const calculatePaddingLeft = () => {
		if (leftComponent) {
			return findLeftComponentLeft();
		}
		return normalize(8);
	};
	const calculatePaddingRight = () => {
		if (rightComponent) {
			return findRightComponentRight();
		}
		return normalize(8);
	};

	return (
		<View style={[styles.container, containerStyle]}>
			{title && (
				<View style={{ flexDirection: 'row', columnGap: normalize(2) }}>
					<PalRiderText style={styles.titleText}>{title}</PalRiderText>
					{required && (
						<PalRiderText color={colors.red[600]} fontFamily={FontFamily.Semibold}>
							*
						</PalRiderText>
					)}
				</View>
			)}
			<View style={{ position: 'relative' }}>
				{leftComponent && (
					<View
						onLayout={onLeftComponentLayout}
						style={[styles.leftComponentContainer, { top: calculateLeftComponentTop() }]}
					>
						{leftComponent}
					</View>
				)}
				<TextInput
					onLayout={onInputLayout}
					placeholderTextColor={colors.gray[500]}
					autoCapitalize="none"
					style={[
						styles.textInputStyle,
						{
							borderColor: touched || error ? colors.red[500] : colors.gray[300],
							paddingLeft: calculatePaddingLeft(),
							paddingRight: calculatePaddingRight(),
							color: colors.black,
							fontFamily: FontFamily.Semibold,
						},
						inputStyle,
					]}
					ref={ref}
					{...textInputProps}
				/>
				{rightComponent && (
					<View
						onLayout={onRightComponentLayout}
						style={[styles.rightComponentContainer, { top: calculateRightComponentTop() }]}
					>
						{rightComponent}
					</View>
				)}
			</View>

			{touched || (error && <PalRiderText style={styles.errorText}>{error as ReactNode}</PalRiderText>)}
		</View>
	);
});

const styles = StyleSheet.create({
	container: {
		height: 'auto',
	},
	textInputStyle: {
		minHeight: normalize(40),
		borderWidth: normalize(1),
		borderRadius: PADDING.large,
		backgroundColor: colors.gray[100],
	},
	titleText: {
		fontFamily: FontFamily.Semibold,
		fontSize: normalize(12),
		marginBottom: normalize(6),
		paddingLeft: normalize(4),
	},
	errorText: {
		fontFamily: FontFamily.Semibold,
		color: colors.red[500],
		fontSize: normalize(12),
		paddingLeft: normalize(4),
		marginTop: normalize(6),
	},
	leftComponentContainer: {
		position: 'absolute',
		padding: normalize(12),
		height: '100%',
		justifyContent: 'center',
		alignItems: 'center',
		borderTopLeftRadius: PADDING.large,
		borderBottomLeftRadius: PADDING.large,
		zIndex: 999,
		backgroundColor: colors.gray[200],
	},
	rightComponentContainer: {
		position: 'absolute',
		right: normalize(8),
		padding: normalize(4),
		borderRadius: PADDING.large,
		zIndex: 999,
	},
});

export default PalRiderTextInput;
