import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import React from 'react';
import { View, ViewStyle } from 'react-native';
import PalRiderText from './PalRiderText';

type Props = {
	containerStyle?: ViewStyle;
	dividerColor?: string;
	text?: string;
} & ViewStyle;
const PalDivider: React.FC<Props> = (props) => {
	return (
		<View style={[props.containerStyle, { flexDirection: 'row', alignItems: 'center' }]}>
			<View
				style={{
					flex: 1,
					height: 1,
					backgroundColor: props.dividerColor ?? colors.gray[400],
				}}
			/>
			{props.text && (
				<View>
					<PalRiderText
						style={{
							width: 50,
							textAlign: 'center',
							fontFamily: FontFamily.Semibold,
						}}
					>
						{props.text}
					</PalRiderText>
				</View>
			)}
			<View
				style={{
					flex: 1,
					height: 1,
					backgroundColor: props.dividerColor ?? colors.gray[400],
				}}
			/>
		</View>
	);
};
export default PalDivider;
