// hooks/useTrackAppLifecycle.ts
import { AppState, AppStateStatus } from 'react-native';
import { useEffect, useRef, useCallback } from 'react';
import { useUpdateUserAppInformationMutation } from '@/services/api/user';
import { useAppSelector } from '@/redux/hooks';
import { UpdateUserAppInformationRequestDTO } from 'palriderapptypes/common';

export const useAppLifecycle = () => {
	const appState = useRef(AppState.currentState);
	const [sendUserAppInfo] = useUpdateUserAppInformationMutation();
	const userId = useAppSelector((x) => x.userSlice.user?.id); // Extract only the ID
	const isRequestInProgress = useRef(false); // Prevent concurrent requests

	const handleAppStateChange = useCallback(
		async (nextState: AppStateStatus) => {
			// Early returns to prevent unnecessary processing
			if (!userId) return;
			if (appState.current === nextState) return;
			if (isRequestInProgress.current) return; // Prevent concurrent requests

			const previousState = appState.current;
			appState.current = nextState;

			const now = new Date();
			const isBackground = nextState === 'background';
			const isActive = nextState === 'active';

			// Only send requests for meaningful state changes
			if (!isBackground && !isActive) return;

			try {
				isRequestInProgress.current = true;

				const appInfo: Partial<UpdateUserAppInformationRequestDTO> = {
					app_opened_at: isActive ? now.toISOString() : undefined,
					app_closed_at: isBackground ? now.toISOString() : undefined,
					last_seen_at: now.toISOString(),
				};

				// Remove undefined values to avoid sending empty strings
				Object.keys(appInfo).forEach((key) => {
					if (appInfo[key as keyof typeof appInfo] === undefined) {
						delete appInfo[key as keyof typeof appInfo];
					}
				});

				await sendUserAppInfo(appInfo).unwrap();
			} catch (err) {
				console.warn('❌ Failed to send user app info', err);
			} finally {
				isRequestInProgress.current = false;
			}
		},
		[userId, sendUserAppInfo],
	);

	useEffect(() => {
		// Only set up listener if user is logged in
		if (!userId) return;

		const subscription = AppState.addEventListener('change', handleAppStateChange);

		return () => {
			subscription.remove();
			isRequestInProgress.current = false; // Reset on cleanup
		};
	}, [userId, handleAppStateChange]);
};

// Alternative version with debouncing (if you're still getting rapid state changes)
export const useAppLifecycleDebounced = () => {
	const appState = useRef(AppState.currentState);
	const [sendUserAppInfo] = useUpdateUserAppInformationMutation();
	const userId = useAppSelector((x) => x.userSlice.user?.id);
	const isRequestInProgress = useRef(false);
	const debounceTimer = useRef<number>(null);

	const handleAppStateChange = useCallback(
		async (nextState: AppStateStatus) => {
			if (!userId) return;
			if (appState.current === nextState) return;
			if (isRequestInProgress.current) return;

			// Clear any existing debounce timer
			if (debounceTimer.current) {
				clearTimeout(debounceTimer.current);
			}

			const previousState = appState.current;
			appState.current = nextState;

			// Debounce the API call by 500ms
			debounceTimer.current = setTimeout(async () => {
				const now = new Date();
				const isBackground = nextState === 'background';
				const isActive = nextState === 'active';

				if (!isBackground && !isActive) return;

				console.log(`🔄 App state changed (debounced): ${previousState} → ${nextState}`);

				try {
					isRequestInProgress.current = true;

					const appInfo: Partial<UpdateUserAppInformationRequestDTO> = {
						app_opened_at: isActive ? now.toISOString() : undefined,
						app_closed_at: isBackground ? now.toISOString() : undefined,
						last_seen_at: now.toISOString(),
					};

					Object.keys(appInfo).forEach((key) => {
						if (appInfo[key as keyof typeof appInfo] === undefined) {
							delete appInfo[key as keyof typeof appInfo];
						}
					});

					await sendUserAppInfo(appInfo).unwrap();
				} catch (err) {
					console.warn('❌ Failed to send user app info', err);
				} finally {
					isRequestInProgress.current = false;
				}
			}, 500);
		},
		[userId, sendUserAppInfo],
	);

	useEffect(() => {
		if (!userId) return;

		const subscription = AppState.addEventListener('change', handleAppStateChange);

		return () => {
			console.log('🧹 Cleaning up debounced AppState listener');
			subscription.remove();
			isRequestInProgress.current = false;
			if (debounceTimer.current) {
				clearTimeout(debounceTimer.current);
				debounceTimer.current = null;
			}
		};
	}, [userId, handleAppStateChange]);
};
