import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { CompanyAreaAddressUserDTO, CompanyDTO } from 'palriderapptypes/company';

export const companyInitialValues: {
	company: CompanyDTO | null;
	company_area_address_user: CompanyAreaAddressUserDTO | null;
} = {
	company: null,
	company_area_address_user: null,
};

const companySlice = createSlice({
	name: 'company',
	initialState: companyInitialValues,
	reducers: {
		setCompany: (state, action: PayloadAction<CompanyDTO | null>) => {
			return {
				...state,
				company: action.payload,
			};
		},
		setCompanyAreaAddressUser: (state, action: PayloadAction<CompanyAreaAddressUserDTO | null>) => {
			return {
				...state,
				company_area_user: action.payload,
			};
		},
	},
});
export const { setCompany, setCompanyAreaAddressUser } = companySlice.actions;
export default companySlice.reducer;
