import PalRiderButton from '@/components/PalRiderButton.tsx';
import PalRiderCheckBox from '@/components/PalRiderCheckBox.tsx';
import PalRiderPhoneInput from '@/components/PalRiderPhoneInput.tsx';
import PalRiderText from '@/components/PalRiderText.tsx';
import { useAuthenticateCompanyAreaAddressUserMutation } from '@/services/api/company/auth-company-area-address-user';
import colors from '@/theme/colors.ts';
import { buttonStyling } from '@/theme/defaults.ts';
import { FontFamily } from '@/theme/fonts.ts';
import { font, normalize, PADDING } from '@/theme/responsive.ts';
import { Shape } from '@/types';
import { isFetchBaseQueryError, phoneNumberRegex } from '@/utils';
import { useFormik } from 'formik';
import React, { useRef, useState } from 'react';
import { StyleSheet, View } from 'react-native';
import { KeyboardAwareScrollView } from 'react-native-keyboard-aware-scroll-view';
import { boolean, object, string } from 'yup';
import { useAppDispatch, useAppSelector } from '@/redux/hooks.ts';
import { setCompanyAreaUserInfoOnboardingState } from '@/redux/slices/company-onboarding.ts';
import LottieView from 'lottie-react-native';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { useTranslation } from 'react-i18next';
import { DropdownSelectHandle } from 'react-native-input-select/lib/typescript/src/types/index.types';
import Dropdown from 'react-native-input-select';
import WarningModal from '@/components/custom-modal/WarningModal';
import { globalStyles } from '@/utils/global-styles';

type FormikType = {
	phone_number: string;
	authentication_type: 'phone' | 'email';
	agreement: boolean;
};
type Props = {
	nextStep: () => void;
	prevStep: () => void;
};
const SignUpCompanyPhoneInfoStep: React.FC<Props> = ({ prevStep, nextStep }) => {
	const { t } = useTranslation();
	const dispatch = useAppDispatch();
	const companyOnboardingSelector = useAppSelector((x) => x.companyOnboardingSlice.area.user);
	const [authenticateCompanyAreaAddressUser] = useAuthenticateCompanyAreaAddressUserMutation();
	const { showGlobalModal, hideGlobalModal } = useModal();

	const areaCodeRef = useRef<DropdownSelectHandle | null>(null);
	const [areaCode, setAreaCode] = useState('44');
	const removeAreaCode = (phone_number: string) => {
		return phone_number.replace('+44', '');
	};
	const signUpCompanyAreaUserFormik = useFormik<FormikType>({
		initialValues: {
			authentication_type: 'phone',
			phone_number: removeAreaCode(companyOnboardingSelector.phone_number) ?? '',
			agreement: false,
		},
		validationSchema: object<Shape<FormikType>>({
			authentication_type: string(),
			phone_number: string().when('authentication_type', {
				is: (value: string) => value === 'phone',
				then: (schema) =>
					schema
						.required(t('validation.required', { field: t('common.phone_number') }))
						.test('phone-regex', t(t('validation.regex')), function (value) {
							return phoneNumberRegex.test('+' + areaCode + value);
						}),
				otherwise: (schema) => schema,
			}),
			email: string().when('authentication_type', {
				is: (value: string) => value === 'email',
				then: (schema) =>
					schema.required(t('validation.required', { field: t('common.email') })).email(t('validation.email')),
				otherwise: (schema) => schema,
			}),
			agreement: boolean().required().oneOf([true], 'You must approve Terms And Policy'),
		}),
		onSubmit: async (values) => {
			showGlobalModal({
				children: <LoadingModal />,
				backgroundColor: colors.transparent,
			});
			const result = await authenticateCompanyAreaAddressUser({
				phone_number: '+' + areaCode + values.phone_number.replace(/\D/g, ''),
			});
			if (result.error && isFetchBaseQueryError(result.error)) {
				showGlobalModal({
					children: <WarningModal text={result.error.data.title} />,
				});
				return;
			}

			dispatch(
				setCompanyAreaUserInfoOnboardingState({
					...companyOnboardingSelector,
					phone_number: '+' + areaCode + values.phone_number.replace(/\D/g, ''),
				}),
			);
			nextStep();
			hideGlobalModal();
		},
	});
	return (
		<KeyboardAwareScrollView
			style={styles.container}
			overScrollMode="never"
			contentContainerStyle={styles.scrollViewContentContainerStyle}
			extraHeight={normalize(15)}
			showsVerticalScrollIndicator={false}
			keyboardShouldPersistTaps="handled"
		>
			<View style={styles.contentContainer}>
				<View style={{ alignItems: 'center', gap: PADDING.large }}>
					<LottieView
						style={{ width: '100%', height: 220 }}
						source={require('@/assets/animations/phone-verication.json')}
						autoPlay
						loop
					/>
					<PalRiderText fontSize={font.xxlarge} fontFamily={FontFamily.Semibold}>
						{t('screen.auth.sign_up_company.user_auth.phone_verification')}
					</PalRiderText>
					<PalRiderText fontSize={font.mini} color={colors.gray[600]} style={{ textAlign: 'center' }}>
						{t('screen.auth.sign_up_company.user_auth.authenticate_description')}
					</PalRiderText>
				</View>
				<Dropdown
					ref={areaCodeRef}
					dropdownStyle={{
						display: 'none',
					}}
					options={[
						{
							label: t('country.united_kingdom', { code: '+44' }),
							value: '44',
						},
						{
							label: t('country.turkey', { code: '+90' }),
							value: '90',
						},
					]}
					isMultiple={false}
					selectedValue={areaCode}
					onValueChange={(value) => setAreaCode(value as string)}
					maxSelectableItems={1}
				/>
				{signUpCompanyAreaUserFormik.values.authentication_type === 'phone' && (
					<PalRiderPhoneInput
						onAreaCodePress={() => areaCodeRef.current?.open()}
						areaCode={areaCode}
						title={t('common.phone_number')}
						onChangeText={(text) => {
							signUpCompanyAreaUserFormik.setFieldValue('phone_number', text, true);
						}}
						error={signUpCompanyAreaUserFormik.errors.phone_number}
						touched={!signUpCompanyAreaUserFormik.errors.phone_number}
						value={signUpCompanyAreaUserFormik.values.phone_number}
					/>
				)}
				<View
					style={{
						flexDirection: 'row',
						alignItems: 'center',
						marginHorizontal: normalize(4),
					}}
				>
					<PalRiderCheckBox
						value={signUpCompanyAreaUserFormik.values.agreement}
						error={signUpCompanyAreaUserFormik.errors.agreement}
						onValueChange={(val) => signUpCompanyAreaUserFormik.setFieldValue('agreement', val)}
					/>
					<View
						style={{
							flexDirection: 'row',
							gap: normalize(4),
							marginVertical: normalize(8),
							flex: 1,
							flexWrap: 'wrap',
						}}
					>
						<PalRiderText
							style={{
								justifyContent: 'center',
							}}
						>
							<PalRiderText style={styles.linkedText}>
								{t('screen.auth.sign_up_company.user_auth.aggreement_description')}
							</PalRiderText>
						</PalRiderText>

						{signUpCompanyAreaUserFormik.errors.agreement && (
							<PalRiderText style={globalStyles.errorTextStyle}>
								{signUpCompanyAreaUserFormik.errors.agreement}
							</PalRiderText>
						)}
					</View>
				</View>
			</View>
			<View
				style={{
					flexDirection: 'row',
					gap: normalize(10),
				}}
			>
				<PalRiderButton style={[buttonStyling.dark, { flex: 1 }]} onPress={() => prevStep()}>
					<PalRiderText color="white">{t('common.go_back')}</PalRiderText>
				</PalRiderButton>
				<PalRiderButton
					style={[buttonStyling.dark, { flex: 1 }]}
					onPress={() => signUpCompanyAreaUserFormik.handleSubmit()}
				>
					<PalRiderText color="white">{t('common.continue')}</PalRiderText>
				</PalRiderButton>
			</View>
		</KeyboardAwareScrollView>
	);
};
const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.white,
		padding: PADDING.large,
	},
	contentContainer: {
		backgroundColor: colors.white,
		justifyContent: 'center',
	},
	title: {
		textAlign: 'center',
		fontSize: normalize(30),
		color: colors.black,
		fontFamily: FontFamily.Bold,
	},
	description: {
		textAlign: 'center',
		fontSize: normalize(14),
		fontFamily: FontFamily.Semibold,
		color: colors.gray[200],
		marginTop: normalize(10),
		marginBottom: normalize(30),
	},
	scrollViewContentContainerStyle: {
		paddingTop: normalize(20),
		alignContent: 'center',
		justifyContent: 'center',
		flex: 1,
		borderTopLeftRadius: normalize(20),
		borderTopRightRadius: normalize(20),
	},
	continueButton: {
		marginTop: normalize(8),
	},
	continueButtonText: {
		fontFamily: FontFamily.Bold,
		color: colors.white,
	},
	signUpButton: {
		flex: 1,
		flexDirection: 'row',
		columnGap: 10,
		alignItems: 'center',
		justifyContent: 'center',
	},
	signUpButtonGoogle: {
		backgroundColor: colors.orange[600],
	},
	signUpButtonFacebook: {
		backgroundColor: colors.blue[700],
	},
	signUpButtonText: {
		color: 'white',
		fontSize: normalize(12),
		fontFamily: FontFamily.Bold,
	},
	signUpWithEmailContainer: {
		marginVertical: normalize(8),
		alignItems: 'flex-end',
	},
	signUpWithEmailText: {
		fontFamily: FontFamily.Semibold,
		textDecorationStyle: 'solid',
		textDecorationLine: 'underline',
	},
	linkContainer: {
		marginBottom: normalize(40),
		justifyContent: 'center',
		flexDirection: 'row',
	},
	linkText: {
		color: colors.orange[600],
		fontFamily: FontFamily.Semibold,
		fontSize: normalize(12),
	},
	linkedText: {
		fontFamily: FontFamily.Semibold,
		fontSize: normalize(12),
	},
});
export default SignUpCompanyPhoneInfoStep;
