import React from 'react';
import { View } from 'react-native';
import PalRiderText from '../PalRiderText';
import { VerifiedIconSvg } from '@/assets/svg/custom';
import colors from '@/theme/colors';
import { font, PADDING } from '@/theme/responsive';
import { FontFamily } from '@/theme/fonts';
type SuccessModalProps = {
	title?: string;
	text: string | null | undefined;
	width?: number;
	height?: number;
};
const SuccessModal: React.FC<SuccessModalProps> = (props) => {
	return (
		<View
			style={{
				height: props.height ?? 100,
				width: props.width ?? 'auto',
				justifyContent: 'center',
				alignItems: 'center',
				gap: PADDING.large,
			}}
		>
			<VerifiedIconSvg width={32} height={32} color={colors.green[600]} />
			{props.text && (
				<PalRiderText fontSize={font.small} fontFamily={FontFamily.Regular} style={{ textAlign: 'center' }}>
					{props.text}
				</PalRiderText>
			)}
		</View>
	);
};

export default SuccessModal;
