import { createApi } from '@reduxjs/toolkit/query/react';
import { PaginationDataResultT } from 'palriderapptypes';
import { PaginationRequestDTO } from 'palriderapptypes/common';
import { CompanyCategoryDTO } from 'palriderapptypes/company';
import { baseQueryConfigWithReAuth } from 'src/services/api/baseQueryConfig.ts';
export const companyCategoryApi = createApi({
	reducerPath: 'companyCategory',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		getAllCompanyCategories: builder.query<PaginationDataResultT<CompanyCategoryDTO>, PaginationRequestDTO>({
			query({ page = 1, size = 50 }) {
				return {
					method: 'GET',
					url: 'company-category?page=' + page + '&size=' + size,
				};
			},
		}),
	}),
});

export const { useLazyGetAllCompanyCategoriesQuery } = companyCategoryApi;
