import PalRiderText from '@/components/PalRiderText';
import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { font, normalize, PADDING } from '@/theme/responsive';
import React from 'react';
import { useAppSelector } from '@/redux/hooks.ts';
import { maskUKPlate } from '@/utils';
import { useTranslation } from 'react-i18next';
import { StyleSheet, View } from 'react-native';
import Icon from '@/components/Icon';

const CourierHomeActiveVehicle: React.FC = () => {
	const { t } = useTranslation();
	const userSlice = useAppSelector((x) => x.userSlice);

	const activeVehicle = userSlice.user?.courier?.active_vehicle;

	return (
		<View style={styles.card}>
			<View style={styles.row}>
				<PalRiderText style={styles.title}>{t('screen.courier.home.active_vehicle')}</PalRiderText>

				{activeVehicle ? (
					<View style={styles.vehicleInfo}>
						{activeVehicle.type !== 'bike' && (
							<PalRiderText fontSize={font.xmini}>{maskUKPlate(activeVehicle?.plate_number ?? '')}</PalRiderText>
						)}
						{activeVehicle.type === 'bike' && (
							<PalRiderText fontSize={font.xmini}>{activeVehicle?.type?.toUpperCase()}</PalRiderText>
						)}
						{activeVehicle.status === 'pending' && (
							<Icon name="UnverifiedIconSvg" width={20} height={20} color={colors.yellow[600]} />
						)}
						{activeVehicle.status === 'refused' && (
							<Icon name="UnverifiedIconSvg" width={20} height={20} color={colors.red[600]} />
						)}
						{activeVehicle.status === 'approved' && (
							<Icon name="VerifiedIconSvg" width={20} height={20} color={colors.green[600]} />
						)}
						<PalRiderText fontSize={font.xmini}>{activeVehicle.status.toUpperCase()}</PalRiderText>
					</View>
				) : (
					<View style={styles.vehicleInfo}>
						<Icon name="CommentQuestionIconSvg" width={16} height={16} color={colors.yellow[600]} />
						<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.mini}>
							{t('screen.courier.home.pending_for_approval')}
						</PalRiderText>
					</View>
				)}
			</View>
		</View>
	);
};

const styles = StyleSheet.create({
	card: {
		backgroundColor: colors.white,
		borderRadius: 16,
		padding: PADDING.large,
		shadowColor: colors.black,
		shadowOpacity: 0.06,
		shadowRadius: 6,
		elevation: 3,
	},
	row: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
	},
	title: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.small,
		color: colors.gray[800],
	},
	vehicleInfo: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: normalize(6),
	},
});

export default CourierHomeActiveVehicle;
