import { createApi } from '@reduxjs/toolkit/query/react';
import { PaginationDataResultT, SuccessfulResponse, SuccessfulResponseT } from 'palriderapptypes';
import { PaginationRequestDTO } from 'palriderapptypes/common';
import {
	CompanyAreaAddressUserDTO,
	CompanyAreaAddressUserRoleDTO,
	CreateCompanyAreaAddressUserRequestDTO,
} from 'palriderapptypes/company';
import { baseQueryConfigWithReAuth } from 'src/services/api/baseQueryConfig.ts';

export const companyAreaAddressUserApi = createApi({
	reducerPath: 'companyAreaAddressUser',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		getAllCompanyAreaAddressUsers: builder.query<
			PaginationDataResultT<CompanyAreaAddressUserDTO>,
			PaginationRequestDTO & { company_area_address_id: string }
		>({
			query({ page, size, company_area_address_id }) {
				return {
					url: `company-area-address/${company_area_address_id}/users?page=${page}&size=${size}`,
					method: 'GET',
				};
			},
		}),
		getCompanyAreaAddressUser: builder.query<SuccessfulResponseT<CompanyAreaAddressUserDTO>, string>({
			query(company_area_address_user_id) {
				return {
					url: `company-area-address-user/${company_area_address_user_id}`,
					method: 'GET',
				};
			},
		}),
		getCompanyAreaAddressUserRoles: builder.query<
			PaginationDataResultT<CompanyAreaAddressUserRoleDTO>,
			PaginationRequestDTO
		>({
			query({ page, size }) {
				return {
					url: `company-area-address-user-role?page=${page}&size=${size}`,
					method: 'GET',
				};
			},
		}),
		storeCompanyAreaAddressUser: builder.mutation<SuccessfulResponse, CreateCompanyAreaAddressUserRequestDTO>({
			query(body) {
				return {
					url: `company-area-address-user`,
					method: 'POST',
					headers: {
						'Content-Type': 'application/json',
					},
					body,
				};
			},
		}),
	}),
});

export const {
	useGetAllCompanyAreaAddressUsersQuery,
	useLazyGetAllCompanyAreaAddressUsersQuery,
	useLazyGetCompanyAreaAddressUserQuery,
	useStoreCompanyAreaAddressUserMutation,
	useLazyGetCompanyAreaAddressUserRolesQuery,
} = companyAreaAddressUserApi;
