import React, { useCallback } from 'react';
import { SafeAreaView, StyleSheet, View } from 'react-native';
import PalRiderText from '@/components/PalRiderText';
import colors from '@/theme/colors';
import {
	useLazyDeleteVehicleQuery,
	useLazyGetCourierVehiclesQuery,
	useSetActiveVehicleMutation,
} from '@/services/api/courier/courier-vehicle';
import { useAppSelector } from '@/redux/hooks';
import { FlatList, RefreshControl } from 'react-native-gesture-handler';
import { font, PADDING } from '@/theme/responsive';
import PalRiderButton from '@/components/PalRiderButton';
import { isFetchBaseQueryError, maskUKPlate, snakeToHumanReadable } from '@/utils';
import VehicleAddIconSvg from './ui-components/svg/VehicleAddIconSvg';
import { useModal } from '@/components/ModalProvider';
import ConfirmationModal from '@/components/custom-modal/ConfirmationModal';
import { CompositeScreenProps, useFocusEffect } from '@react-navigation/native';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import WarningModal from '@/components/custom-modal/WarningModal';

import { CourierVehicleDTO } from 'palriderapptypes/courier';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import {
	AppCourierProfileStackParamList,
	AppCourierTabParamList,
	AppCourierVehiclesStackParamList,
} from '@/navigation/courier-navigation';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import { useTranslation } from 'react-i18next';
import { MenuAction, MenuView } from '@react-native-menu/menu';
import Icon from '@/components/Icon';
import { FontFamily } from '@/theme/fonts';

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCourierVehiclesStackParamList, 'CourierVehicles'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCourierProfileStackParamList, 'CourierVehiclesStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCourierTabParamList, 'CourierProfileStack'>,
			NativeStackScreenProps<RootStackParamList>
		>
	>
>;

const AppCourierProfileVehiclesHomeScreen: React.FC<Props> = ({ navigation }) => {
	const { t } = useTranslation();
	const userSlice = useAppSelector((x) => x.userSlice.user?.courier);
	const [getCourierVehicles, { data, isFetching }] = useLazyGetCourierVehiclesQuery();
	const [updateActiveVehicle] = useSetActiveVehicleMutation();
	const { showGlobalModal, hideGlobalModal } = useModal();
	const [deleteCourierVehicle] = useLazyDeleteVehicleQuery();
	const handleSetActiveVehicleAction = useCallback(async (vehicle_id: string, status: CourierVehicleDTO['status']) => {
		if (status === 'pending' || status === 'refused') {
			showGlobalModal({
				minWidth: 100,
				minHeight: 100,
				children: (
					<WarningModal
						text={`This vehicle cannot make active because currently in ${snakeToHumanReadable(status)} status`}
					/>
				),
			});
			return;
		}
		hideGlobalModal();
		showGlobalModal({
			children: <LoadingModal />,
			backgroundColor: 'transparent',
		});
		const res = await updateActiveVehicle(vehicle_id);
		if (res.error && isFetchBaseQueryError(res.error)) {
			hideGlobalModal();
			showGlobalModal({
				minWidth: 100,
				minHeight: 100,
				children: <WarningModal text={res.error.data.title} />,
			});
			return;
		}

		hideGlobalModal();
		showGlobalModal({
			minWidth: 100,
			minHeight: 100,
			children: <SuccessModal text={res.data?.message} />,
			whenClose() {
				loadCourierVehicles(userSlice?.id, 100, 1);
			},
		});
	}, []);
	const handleDeleteAction = useCallback(async (vehicleId: string, is_active: boolean) => {
		if (is_active) {
			hideGlobalModal();
			showGlobalModal({
				children: <WarningModal text="Active vehicle cannot deleted" />,
			});
			return;
		}
		showGlobalModal({
			padding: 0,
			children: (
				<ConfirmationModal
					icon={<Icon name="TrashIconSvg" width={20} height={20} color={colors.red[600]} />}
					text="Are you sure want to delete vehicle?"
					onConfirm={async () => {
						hideGlobalModal();
						showGlobalModal({
							children: <LoadingModal />,
							backgroundColor: 'transparent',
						});
						const res = await deleteCourierVehicle(vehicleId);
						if (res.error && isFetchBaseQueryError(res.error)) {
							hideGlobalModal();
							showGlobalModal({
								minWidth: 100,
								minHeight: 100,
								children: <WarningModal text={res.error.data.title} />,
							});
						}
						hideGlobalModal();
						showGlobalModal({
							minWidth: 100,
							minHeight: 100,
							children: <SuccessModal text={res.data?.message} />,
							whenClose() {
								loadCourierVehicles(userSlice?.id, 100, 1);
							},
						});
					}}
					onCancel={() => hideGlobalModal()}
				/>
			),
			onClose: () => hideGlobalModal(),
		});
	}, []);
	const loadCourierVehicles = (courier_id?: string, size: number = 100, page: number = 1) => {
		if (!courier_id) return;
		showGlobalModal({
			children: <LoadingModal />,
			backgroundColor: colors.transparent,
		});
		getCourierVehicles({
			page,
			size,
			courier_id,
		})
			.unwrap()
			.catch((err) => console.error(err))
			.finally(() => hideGlobalModal());
	};
	useFocusEffect(
		useCallback(() => {
			if (!userSlice?.id) {
				navigation.goBack();
				return;
			}
			loadCourierVehicles(userSlice.id, 100, 1);
		}, []),
	);
	return (
		<SafeAreaView style={styles.container}>
			<View style={styles.myVehiclesContainer}>
				<FlatList
					showsVerticalScrollIndicator={false}
					data={data?.data ?? []}
					refreshControl={
						<RefreshControl onRefresh={() => loadCourierVehicles(userSlice?.id)} refreshing={isFetching} />
					}
					renderItem={({ item: vehicle }) => {
						const contextMenuActions: Array<MenuAction> = [
							{ id: 'show', title: t('common.show') },
							{ id: 'update', title: t('common.update') },
						];
						if (!vehicle.is_active && vehicle.status === 'approved') {
							contextMenuActions.push({
								id: 'set_active_vehicle',
								title: 'Set Active Vehicle',
							});
						}

						contextMenuActions.push({ id: 'delete', title: t('common.delete') });
						return (
							<MenuView
								actions={contextMenuActions}
								shouldOpenOnLongPress={false}
								isAnchoredToRight
								onPressAction={({ nativeEvent }) => {
									if (nativeEvent.event === 'show') {
										navigation.navigate('AppCourierStack', {
											screen: 'CourierProfileStack',
											params: {
												screen: 'CourierVehicleView',
												params: {
													courier_vehicle_id: vehicle.id,
												},
											},
										});
										return;
									}
									if (nativeEvent.event === 'update') {
										// handleUpdateAction(vehicle.id)
										return;
									}
									if (nativeEvent.event === 'set_active_vehicle') {
										handleSetActiveVehicleAction(vehicle.id, vehicle.status);
										return;
									}

									if (nativeEvent.event === 'delete') {
										handleDeleteAction(vehicle.id, vehicle.is_active);
										return;
									}
								}}
							>
								<View style={[styles.vehicleContainer]}>
									<View style={styles.vehicleInnerContainer}>
										<View style={styles.vehicleIconContainer}>
											{vehicle.type === 'bike' && <Icon name="BikeIconSvg" />}
											{vehicle.type === 'motorcycle' && <Icon name="MotorcycleIconSvg" />}
											{vehicle.type === 'car' && <Icon name="CarIconSvg" />}
										</View>
										<PalRiderText style={styles.vehicleText}>
											{maskUKPlate(vehicle.plate_number) || t('common.bike')}
										</PalRiderText>
									</View>
									<View style={styles.vehicleStatusContainer}>
										{vehicle.status === 'pending' && (
											<Icon name="ImageSearchIconSvg" width={20} height={20} color={colors.orange[600]} />
										)}
										{vehicle.status === 'approved' && (
											<Icon name="VerifiedIconSvg" width={24} height={24} color={colors.green[600]} />
										)}
										{vehicle.status === 'refused' && (
											<Icon name="UnverifiedIconSvg" width={24} height={24} color={colors.red[600]} />
										)}
									</View>
								</View>
							</MenuView>
						);
					}}
					ListEmptyComponent={
						<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
							<PalRiderText>{t('screen.courier.profile.vehicle.no_vehicle_found')}</PalRiderText>
						</View>
					}
					ListFooterComponent={
						<PalRiderButton
							style={styles.addButton}
							onPress={() =>
								navigation.navigate('AppCourierStack', {
									screen: 'CourierProfileStack',
									params: {
										screen: 'CourierVehiclesStack',
										params: {
											screen: 'CourierVehicleCreate',
										},
									},
								})
							}
						>
							<VehicleAddIconSvg width={20} height={30} color={colors.white} />
							<PalRiderText fontSize={font.mini} fontFamily={FontFamily.Semibold} color={colors.white}>
								{t('screen.courier.profile.vehicle.add_new_vehicle')}
							</PalRiderText>
						</PalRiderButton>
					}
					contentContainerStyle={{ flex: 1, gap: PADDING.large }}
				/>
			</View>
		</SafeAreaView>
	);
};
const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.white,
	},
	myVehiclesContainer: {
		flex: 1,
		gap: PADDING.large,
		padding: PADDING.large,
	},
	vehicleContainer: {
		padding: PADDING.large,
		borderRadius: PADDING.medium,
		justifyContent: 'space-between',
		flexDirection: 'row',
		alignItems: 'center',
		borderWidth: 1,
		borderColor: colors.gray[300],
		backgroundColor: colors.white,
	},
	vehicleInnerContainer: {
		flexDirection: 'row',
		flex: 1,
		alignItems: 'center',
	},
	vehicleIconContainer: {
		marginRight: PADDING.medium,
	},
	vehicleStatusContainer: {
		alignItems: 'center',
	},
	vehicleText: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.small,
		flex: 1,
		color: colors.black,
	},
	deleteIconContainer: {},
	rightActionContainer: {
		flexDirection: 'row',
		justifyContent: 'space-around',
		alignItems: 'center',
		paddingHorizontal: PADDING.medium,
		gap: PADDING.medium,
	},
	rightActionButton: {
		borderWidth: 1,
		borderColor: colors.gray[300],
		borderRadius: PADDING.medium,
		padding: PADDING.medium,
	},
	addContainer: {
		borderRadius: PADDING.medium,
	},
	addButton: {
		flexDirection: 'row',
		alignItems: 'center',
		justifyContent: 'center',
		gap: PADDING.small,
		padding: PADDING.large,
	},
});
export default AppCourierProfileVehiclesHomeScreen;
