import React, { useEffect, useMemo, useState } from 'react';
import { ScrollView, StyleSheet, TouchableOpacity, View } from 'react-native';
import colors from '@/theme/colors.ts';
import { font, PADDING } from '@/theme/responsive.ts';
import PalRiderText from '@/components/PalRiderText.tsx';
import { useAppDispatch, useAppSelector } from '@/redux/hooks.ts';
import { FontFamily } from '@/theme/fonts.ts';
import { setToken, setUser } from '@/redux/slices/userSlice.ts';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { CompositeScreenProps } from '@react-navigation/native';
import { AppCompanyProfileParamList, AppCompanyTabParamList } from '@/navigation/company-navigation';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import { useTranslation } from 'react-i18next';
import { CompanyAreaAddressUserDTO } from 'palriderapptypes/company';
import Icon from '@/components/Icon';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyProfile'>,
	CompositeScreenProps<
		BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
		NativeStackScreenProps<RootStackParamList>
	>
>;
const AppCompanyProfileScreen: React.FC<Props> = ({ navigation }) => {
	const dispatch = useAppDispatch();
	const user = useAppSelector((state) => state.userSlice);
	const handleLogout = async () => {
		await AsyncStorage.removeItem('token');
		navigation.navigate('Splash');
		dispatch(setToken(null));
		dispatch(setUser(null));
	};
	const addressUser = user.user?.company_area_address_user as CompanyAreaAddressUserDTO;
	const { t } = useTranslation();
	const profileActionItems = useMemo(
		() => [
			{
				title: t('screen.company.profile.my_account'),
				icon: <Icon name="ProfileIconSvg" width={20} height={20} />,
				action: () =>
					navigation.navigate('AppCompanyStack', {
						screen: 'CompanyProfileStack',
						params: {
							screen: 'CompanyMyAccount',
						},
					}),
				isHidden: false,
			},
			{
				title: t('common.wallet'),
				icon: <Icon name="WalletIconSvg" width={20} height={20} />,
				action: () => {
					navigation.navigate('AppCompanyStack', {
						screen: 'CompanyProfileStack',
						params: {
							screen: 'CompanyWallet',
						},
					});
				},
				isHidden: !(
					addressUser?.company_area_address_user_role?.name.includes('Owner') ||
					addressUser?.company_area_address_user_role?.name.includes('Paymaster')
				),
			},

			{
				title: 'Addresses',
				icon: <Icon name="BuildingIconSvg" width={20} height={20} />,
				action: () => {
					navigation.navigate('AppCompanyStack', {
						screen: 'CompanyProfileStack',
						params: {
							screen: 'CompanyAreaStack',
							params: {
								screen: 'CompanyAreaAddresses',
								params: {
									company_id: user.user?.company_area_address_user.company_id,
									company_area_id: user.user?.company_area_address_user.company_area_id,
								},
							},
						},
					});
				},
				isHidden: !(
					addressUser?.company_area_address_user_role?.name.includes('Owner') ||
					addressUser?.company_area_address_user_role?.name.includes('Manager')
				),
			},
			{
				title: t('screen.company.profile.settings'),
				icon: <Icon name="CogIconSvg" width={20} height={20} />,
				action: () => {
					navigation.navigate('AppCompanyStack', {
						screen: 'CompanyProfileStack',
						params: {
							screen: 'CompanySettings',
						},
					});
				},
				isHidden: false,
			},
			{
				title: t('screen.company.profile.help'),
				icon: <Icon name="CommentQuestionIconSvg" width={20} height={20} />,
				action: () => {
					navigation.navigate('AppCompanyStack', {
						screen: 'CompanyProfileStack',
						params: {
							screen: 'CompanyHelpStack',
							params: {
								screen: 'CompanyHelp',
							},
						},
					});
				},
				isHidden: false,
			},
		],
		[addressUser?.company_area_address_user_role],
	);
	return (
		<View style={{ flex: 1 }}>
			<ScrollView style={styles.container}>
				{profileActionItems
					.filter((x) => x.isHidden == false)
					.map((profileAction, index) => (
						<TouchableOpacity key={index} style={styles.profileItemContainer} onPress={profileAction.action}>
							{profileAction.icon}
							<View style={styles.profileItemTextContainer}>
								<PalRiderText style={styles.profileItemText}>{profileAction.title}</PalRiderText>
							</View>
							<Icon name="ChevronRightIconSvg" />
						</TouchableOpacity>
					))}
				<TouchableOpacity
					style={[styles.profileItemContainer, { borderBottomWidth: 0 }]}
					onPress={() => handleLogout()}
				>
					<Icon name="LogoutIconSvg" color={colors.red[500]} width={16} height={16} />
					<View style={styles.profileItemTextContainer}>
						<PalRiderText style={[styles.profileItemText, { color: colors.red[500] }]}>
							{t('common.logout')}
						</PalRiderText>
					</View>
				</TouchableOpacity>
			</ScrollView>
		</View>
	);
};
const styles = StyleSheet.create({
	container: {
		backgroundColor: colors.white,
		flex: 1,
	},
	profileContainer: {
		width: '100%',
		padding: PADDING.xlarge,
		paddingVertical: PADDING.large,
		flexDirection: 'row',
		alignItems: 'center',
		gap: PADDING.large,
		borderBottomWidth: 1,
		borderBottomColor: colors.gray[300],
	},
	profileImageContainer: {
		width: PADDING.xlarge * 3,
		height: PADDING.xlarge * 3,
		borderRadius: PADDING.xlarge * 3,
		backgroundColor: colors.white,
		shadowColor: colors.orange[900],
		shadowOpacity: 0.2,
		shadowOffset: {
			width: 0,
			height: 3,
		},
		shadowRadius: 6,
	},
	profileImage: {
		width: PADDING.xlarge * 3,
		height: PADDING.xlarge * 3,
		borderRadius: PADDING.xlarge * 3,
	},
	profileUserContainer: {
		flex: 1,
		gap: PADDING.small,
	},
	profileUsernameText: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.medium,
		color: colors.white,
	},
	profilePhoneNumberText: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.xmini,
		color: colors.orange[200],
	},
	profileItemContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		paddingVertical: PADDING.large,
		paddingHorizontal: PADDING.large,
		borderBottomWidth: 1,
		borderBottomColor: colors.gray[200],
		gap: PADDING.medium,
	},
	profileItemTextContainer: {
		flex: 1,
	},
	profileItemText: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.small,
	},
});
export default AppCompanyProfileScreen;
