import React, { useEffect } from 'react';
import { FlatList, Pressable, RefreshControl, ScrollView, StyleSheet, View } from 'react-native';
import PalRiderText from '@/components/PalRiderText';
import colors from '@/theme/colors';
import { useModal } from '@/components/ModalProvider';
import { FetchBaseQueryErrorExpected, formatHumanReadableDate, snakeToHumanReadable } from '@/utils';
import WarningModal from '@/components/custom-modal/WarningModal';
import { FontFamily } from '@/theme/fonts';
import { font, PADDING } from '@/theme/responsive';
import PullToRefreshView from '@/components/PullDownToRefreshView';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { useLazyCourierWalletQuery } from '@/services/api/courier/courier-wallet';
import { CompositeScreenProps } from '@react-navigation/native';
import { CourierWalletTransactionDTO } from 'palriderapptypes/courier';
import { AppCourierProfileStackParamList, AppCourierTabParamList } from '@/navigation/courier-navigation';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { RootStackParamList } from '@/navigation';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import Icon from '@/components/Icon';

const { format } = Intl.NumberFormat('en-UK', {
	currency: 'GBP',
	style: 'currency',
});

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCourierProfileStackParamList, 'CourierWallet'>,
	CompositeScreenProps<
		BottomTabScreenProps<AppCourierTabParamList, 'CourierProfileStack'>,
		NativeStackScreenProps<RootStackParamList>
	>
>;

const WalletTransactionItemRender: React.FC<{ walletItem: CourierWalletTransactionDTO }> = ({ walletItem }) => {
	const [showItemList, setShowItemList] = React.useState(false);

	const transactionTypeToColor = (transaction_type: CourierWalletTransactionDTO['transaction_type']): string => {
		switch (transaction_type) {
			case 'incoming':
				return colors.green[600];
			case 'outgoing':
				return colors.red[400];
			case 'tip':
				return colors.orange[600];
			case 'punishment':
				return colors.red[700];
			default:
				return colors.gray[600];
		}
	};

	return (
		<View style={styles.transactionCard}>
			<View style={{ flexDirection: 'row', alignItems: 'center' }}>
				<View style={styles.transactionIconContainer}>
					<Icon name="PoundBanknoteIconSvg" width={28} height={28} />
				</View>
				<View style={{ flex: 1, marginHorizontal: PADDING.medium }}>
					<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.small}>
						{snakeToHumanReadable(walletItem.transaction_type)}
					</PalRiderText>
					<PalRiderText fontSize={font.xmini} color={colors.gray[500]}>
						{formatHumanReadableDate(walletItem.created_at)}
					</PalRiderText>
				</View>
				<PalRiderText
					color={transactionTypeToColor(walletItem.transaction_type)}
					fontSize={font.medium}
					fontFamily={FontFamily.Semibold}
				>
					{format(walletItem.amount)}
				</PalRiderText>
				<Pressable
					style={{ padding: PADDING.small, transform: [{ rotate: showItemList ? '90deg' : '0deg' }] }}
					onPress={() => setShowItemList((prev) => !prev)}
				>
					<Icon name="ChevronRightIconSvg" />
				</Pressable>
			</View>
			{showItemList && (
				<View style={styles.transactionExpand}>
					{walletItem.courier_wallet_transaction_items.map((item, idx) => (
						<View key={idx} style={styles.transactionExpandRow}>
							<View style={{ flex: 1 }}>
								<PalRiderText fontSize={font.mini} fontFamily={FontFamily.Semibold}>
									{item.name}
								</PalRiderText>
								<PalRiderText fontSize={font.xmini} color={colors.gray[600]}>
									{item.description}
								</PalRiderText>
							</View>
							<PalRiderText fontFamily={FontFamily.Semibold}>{format(item.amount)}</PalRiderText>
						</View>
					))}
				</View>
			)}
		</View>
	);
};

const WalletHeader: React.FC<{ data: any; navigation: any }> = ({ data, navigation }) => (
	<>
		<View style={styles.balanceCard}>
			<View style={styles.actionRow}>
				<View style={{ flex: 1 }}>
					<PalRiderText style={styles.balanceTitle}>Current Balance</PalRiderText>
					<PalRiderText style={styles.balanceAmount}>{format(data?.data.balance ?? 0)}</PalRiderText>
				</View>
				<Pressable
					style={styles.actionButton}
					onPress={() => {
						navigation.navigate('AppCourierStack', {
							screen: 'CourierProfileStack',
							params: { screen: 'CourierWalletWithdraw' },
						});
					}}
				>
					<View style={styles.actionIcon}>
						<Icon name="WithdrawalIconSvg" color={colors.white} width={18} height={18} />
					</View>
					<PalRiderText style={styles.actionText}>Withdraw</PalRiderText>
				</Pressable>
			</View>
		</View>
		<View style={styles.sectionHeader}>
			<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.large}>
				Transactions
			</PalRiderText>
			<Pressable style={{ flexDirection: 'row', alignItems: 'center' }}>
				<PalRiderText color={colors.gray[600]} fontFamily={FontFamily.Semibold} fontSize={font.small}>
					See All
				</PalRiderText>
				<Icon name="ChevronRightIconSvg" />
			</Pressable>
		</View>
	</>
);

const AppCourierProfileWalletScreen: React.FC<Props> = ({ navigation }) => {
	const [getCourierWallet, { data, isFetching }] = useLazyCourierWalletQuery();
	const { showGlobalModal, hideGlobalModal } = useModal();

	const loadWallet = async () => {
		showGlobalModal({ children: <LoadingModal />, backgroundColor: colors.transparent });
		const res = await getCourierWallet();
		if (res.error) {
			const error = res.error as FetchBaseQueryErrorExpected;
			showGlobalModal({ children: <WarningModal text={error.data.title} /> });
		}
		hideGlobalModal();
	};

	useEffect(() => {
		loadWallet();
	}, []);

	const flatListData = data
		? [
				{ type: 'header', data },
				...data.data.courier_wallet_transactions.map((item: CourierWalletTransactionDTO) => ({
					type: 'transaction',
					data: item,
				})),
			]
		: [];

	const renderItem = ({ item }: { item: any }) =>
		item.type === 'header' ? (
			<WalletHeader data={item.data} navigation={navigation} />
		) : (
			<WalletTransactionItemRender walletItem={item.data} />
		);

	return (
		<ScrollView refreshControl={<RefreshControl refreshing={isFetching} onRefresh={() => loadWallet()} />}>
			{data?.data && (
				<FlatList
					data={flatListData}
					keyExtractor={(item, idx) => (item.type === 'header' ? 'header' : idx.toString())}
					style={styles.container}
					renderItem={renderItem}
					ListEmptyComponent={
						<View style={styles.emptyState}>
							<Icon name="PoundBanknoteIconSvg" width={64} height={64} />
							<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.medium}>
								Wallet has no transactions
							</PalRiderText>
						</View>
					}
				/>
			)}
		</ScrollView>
	);
};

const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.gray[50],
		padding: PADDING.large,
	},
	balanceCard: {
		backgroundColor: colors.white,
		padding: PADDING.xlarge,
		borderRadius: 20,
		shadowColor: '#000',
		shadowOpacity: 0.2,
		shadowRadius: 10,
		elevation: 4,
		marginBottom: PADDING.large,
	},
	balanceTitle: {
		color: colors.gray[600],
		fontSize: font.small,
	},
	balanceAmount: {
		fontSize: font.xxlarge,
		fontFamily: FontFamily.Bold,
		color: colors.gray[900],
		marginTop: PADDING.small,
	},
	actionRow: {
		flexDirection: 'row',
		justifyContent: 'space-between',
	},
	actionButton: {
		alignItems: 'center',
	},
	actionIcon: {
		backgroundColor: colors.orange[600],
		padding: PADDING.medium,
		borderRadius: 16,
		marginBottom: PADDING.small,
	},
	actionText: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.small,
		color: colors.gray[800],
	},
	sectionHeader: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
		marginBottom: PADDING.medium,
	},
	transactionCard: {
		backgroundColor: colors.white,
		borderRadius: 16,
		padding: PADDING.large,
		marginBottom: PADDING.medium,
		shadowColor: '#000',
		shadowOpacity: 0.1,
		elevation: 3,
		shadowRadius: 6,
	},
	transactionIconContainer: {
		backgroundColor: colors.gray[100],
		padding: PADDING.small,
		borderRadius: 12,
		justifyContent: 'center',
		alignItems: 'center',
	},
	transactionExpand: {
		marginTop: PADDING.medium,
		borderTopWidth: 1,
		borderColor: colors.gray[200],
		paddingTop: PADDING.medium,
	},
	transactionExpandRow: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		marginBottom: PADDING.small,
	},
	emptyState: {
		flex: 1,
		justifyContent: 'center',
		alignItems: 'center',
		marginTop: PADDING.xxlarge,
	},
});

export default AppCourierProfileWalletScreen;
