import { createApi } from '@reduxjs/toolkit/query/react';
import { baseQueryConfigWithReAuth } from 'src/services/api/baseQueryConfig.ts';
import {
	SmartyApiAutocompleteAddressDTO,
	SmartyApiAutocompleteValidateAddressDTO,
	SmartyApiPostCodeDTO,
} from '@/@types/smarty-api-types';
import { SuccessfulResponseT } from 'palriderapptypes';

export const smartyApi = createApi({
	reducerPath: 'smartyApi',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		autocompletePostCode: builder.query<SuccessfulResponseT<Array<SmartyApiPostCodeDTO>>, string>({
			query(search) {
				return {
					method: 'GET',
					params: {
						search,
					},
					url: 'smarty/autocomplete-post-code',
				};
			},
		}),
		autocompleteAddresses: builder.query<SuccessfulResponseT<Array<SmartyApiAutocompleteAddressDTO>>, string>({
			query(post_code_id) {
				return {
					method: 'GET',
					params: {
						id: post_code_id,
					},
					url: 'smarty/autocomplete-addresses',
				};
			},
		}),
		validateAddress: builder.query<SuccessfulResponseT<Array<SmartyApiAutocompleteValidateAddressDTO>>, string>({
			query(address) {
				return {
					method: 'GET',
					params: {
						freeform: address,
					},
					url: 'smarty/validate-address',
				};
			},
		}),
	}),
});

export const { useLazyAutocompletePostCodeQuery, useLazyAutocompleteAddressesQuery, useLazyValidateAddressQuery } =
	smartyApi;
