import DeviceInfo from 'react-native-device-info';
import NetInfo from '@react-native-community/netinfo';
import * as RNLocalize from 'react-native-localize';
import { Platform } from 'react-native';
import { UpdateUserAppInformationRequestDTO } from 'palriderapptypes/common';

NetInfo.configure({
	useNativeReachability: true,
});
export const getAppInfo = async (): Promise<Partial<UpdateUserAppInformationRequestDTO>> => {
	const app_version_id = DeviceInfo.getVersion();

	const device_model = DeviceInfo.getModel();
	const os_version = DeviceInfo.getSystemVersion();
	const platform = Platform.OS;

	const language = RNLocalize.getLocales()[0]?.languageCode ?? 'en';
	const timezone = RNLocalize.getTimeZone();

	const net = await NetInfo.fetch();
	const network_type = net.type ?? 'unknown';
	const carrier = (await DeviceInfo.getCarrier()) ?? 'unknown';

	return {
		app_version_id,
		platform,
		device_model,
		os_version,
		language,
		timezone,
		network_type,
		carrier,
	};
};
