import { useEffect, useRef, useState, useCallback } from 'react';
import * as signalR from '@microsoft/signalr';
import { BASE_URL } from '@env';
import { useModal } from '@/components/ModalProvider';
import SuccessModal from '@/components/custom-modal/SuccessModal';

interface OrderNotification {
	orderId: string;
	message: string;
}

export const useOrderHub = (token: string | null, refreshOrder: () => void) => {
	const connectionRef = useRef<signalR.HubConnection | null>(null);
	const [connected, setConnected] = useState(false);
	const [joinedOrders, setJoinedOrders] = useState<Set<string>>(new Set());
	const { showGlobalModal } = useModal();

	// Handlers map
	const [notifications, setNotifications] = useState<OrderNotification[]>([]);

	// Create connection
	useEffect(() => {
		console.log(token);
		if (!token) return;

		const connection = new signalR.HubConnectionBuilder()
			.withUrl(BASE_URL + 'orderhub', {
				accessTokenFactory: () => token,
			})
			.withAutomaticReconnect()
			.build();

		// Register handlers
		connection.on('OrderAccessed', (data) => {
			setNotifications((prev) => [...prev, { orderId: data.orderId, message: 'Order updated' }]);
		});

		connection.on('OrderCourierAttendeeAttended', (data) => {
			setNotifications((prev) => [...prev, { orderId: data.orderId, message: data.message }]);
			showGlobalModal({
				children: <SuccessModal text={data.message} />,
				closeAfterDelay: 1000,
				whenClose() {
					refreshOrder();
				},
			});
		});
		connection.on('OrderCourierAttendeeArrived', (data) => {
			setNotifications((prev) => [...prev, { orderId: data.orderId, message: data.message }]);
			showGlobalModal({
				children: <SuccessModal text={data.message} />,
				closeAfterDelay: 1000,
				whenClose() {
					refreshOrder();
				},
			});
		});
		connection.on('OrderCourierAttendeeAccepted', (data) => {
			console.log('test');
			setNotifications((prev) => [...prev, { orderId: data.orderId, message: data.message }]);
			showGlobalModal({
				children: <SuccessModal text={data.message} />,
				closeAfterDelay: 1000,
				whenClose() {
					refreshOrder();
				},
			});
		});

		connectionRef.current = connection;

		const startConnection = async () => {
			try {
				await connection.start();
				console.log('SignalR connected');
				setConnected(true);
			} catch (err) {
				console.error('SignalR connection failed:', err);
			}
		};

		startConnection();

		return () => {
			connection.stop().catch(() => {});
			setConnected(false);
		};
	}, [token]);

	// Join an order room
	const joinOrderRoom = useCallback(
		async (orderId: string) => {
			if (!connectionRef.current || !connected) return;
			if (joinedOrders.has(orderId)) return;

			try {
				await connectionRef.current.invoke('JoinOrderRoom', orderId);
				setJoinedOrders((prev) => new Set(prev).add(orderId));
				console.log(`Joined room ${orderId}`);
			} catch (err) {
				console.error(`Failed to join room ${orderId}:`, err);
			}
		},
		[connected, joinedOrders],
	);

	// Leave an order room
	const leaveOrderRoom = useCallback(
		async (orderId: string) => {
			if (!connectionRef.current || !connected) return;
			if (!joinedOrders.has(orderId)) return;

			try {
				await connectionRef.current.invoke('LeaveOrderRoom', orderId);
				setJoinedOrders((prev) => {
					const copy = new Set(prev);
					copy.delete(orderId);
					return copy;
				});
				console.log(`Left room ${orderId}`);
			} catch (err) {
				console.error(`Failed to leave room ${orderId}:`, err);
			}
		},
		[connected, joinedOrders],
	);

	return {
		connected,
		notifications,
		joinOrderRoom,
		leaveOrderRoom,
		connection: connectionRef.current,
	};
};
