import { createApi } from '@reduxjs/toolkit/query/react';
import { baseQueryConfigWithReAuth } from '../../baseQueryConfig';
import { PaginationDataResultT, SuccessfulResponse, SuccessfulResponseT } from 'palriderapptypes';
import {
	CreateOrderShipmentRequestDTO,
	OrderShipmentCancellationReasonDTO,
	OrderShipmentDestinationCancellationReasonDTO,
	OrderShipmentDTO,
} from 'palriderapptypes/order';
import { FileType, PaginationRequestDTO } from 'palriderapptypes/common';

export const orderShipmentApi = createApi({
	reducerPath: 'orderShipment',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		createShipment: builder.mutation<SuccessfulResponse, CreateOrderShipmentRequestDTO & { order_id: string }>({
			query(body) {
				return {
					method: 'POST',
					body: {
						destinations: body.destinations,
					},
					url: `order/${body.order_id}/create-shipment`,
				};
			},
		}),
		updateShipment: builder.mutation<
			SuccessfulResponse,
			CreateOrderShipmentRequestDTO & { order_id: string; order_shipment_id: string }
		>({
			query(body) {
				return {
					method: 'PUT',
					body: {
						destinations: body.destinations,
					},
					url: `order/${body.order_id}/shipment/${body.order_shipment_id}/update-shipment`,
				};
			},
		}),
		getActiveOrderShipment: builder.query<
			SuccessfulResponseT<OrderShipmentDTO>,
			{ order_id: string; order_shipment_id: string }
		>({
			query(body) {
				return {
					method: 'GET',
					url: `order/${body.order_id}/shipment/${body.order_shipment_id}`,
				};
			},
		}),
		startOrderShipment: builder.query<SuccessfulResponse, { order_id: string; order_shipment_id: string }>({
			query(body) {
				return {
					method: 'GET',
					url: `order/${body.order_id}/shipment/${body.order_shipment_id}/start`,
				};
			},
		}),
		deliverOrderShipmentDestination: builder.mutation<
			SuccessfulResponse,
			{
				order_id: string;
				order_shipment_id: string;
				order_shipment_destination_id: string;
				notes: string;
				order_shipment_destination_delivery_photos: Array<FileType>;
				latitude: number;
				longitude: number;
			}
		>({
			query(body) {
				const formData = new FormData();
				formData.append('notes', body.notes);
				formData.append('latitude', body.latitude);
				formData.append('longitude', body.longitude);
				for (let i = 0; i < body.order_shipment_destination_delivery_photos.length; i++) {
					formData.append(
						'order_shipment_destination_delivery_photos',
						body.order_shipment_destination_delivery_photos[i],
					);
				}
				return {
					method: 'POST',
					url: `order/${body.order_id}/shipment/${body.order_shipment_id}/destination/${body.order_shipment_destination_id}/deliver`,
					headers: {
						'Content-Type': 'multipart/form-data',
					},
					body: formData,
				};
			},
		}),
		cancelOrderShipment: builder.query<
			SuccessfulResponse,
			{
				order_id: string;
				order_shipment_id: string;
				order_shipment_cancellation_reason_id: string;
			}
		>({
			query(body) {
				return {
					method: 'GET',
					url: `order/${body.order_id}/shipment/${body.order_shipment_id}/cancel`,
				};
			},
		}),
		removeOrderShipmentDestination: builder.query<
			SuccessfulResponse,
			{
				order_id: string;
				order_shipment_id: string;
				order_shipment_destination_id: string;
			}
		>({
			query(body) {
				return {
					method: 'GET',
					url: `order/${body.order_id}/shipment/${body.order_shipment_id}/${body.order_shipment_destination_id}/remove`,
				};
			},
		}),
		cancelOrderShipmentDestination: builder.mutation<
			SuccessfulResponse,
			{
				order_id: string;
				order_shipment_id: string;
				order_shipment_destination_id: string;
				latitude: number;
				longitude: number;
				order_shipment_destination_cancellation_reason_id: string;
				notes: string;
				order_shipment_destination_cancellation_photos: Array<FileType>;
			}
		>({
			query(body) {
				const formData = new FormData();
				formData.append('notes', body.notes);
				formData.append('latitude', body.latitude);
				formData.append('longitude', body.longitude);
				formData.append(
					'order_shipment_destination_cancellation_reason_id',
					body.order_shipment_destination_cancellation_reason_id,
				);
				formData.append('order_id', body.order_id);
				formData.append('order_shipment_id', body.order_shipment_id);
				formData.append('order_shipment_destination_id', body.order_shipment_destination_id);
				for (let i = 0; i < body.order_shipment_destination_cancellation_photos.length; i++) {
					formData.append(
						'order_shipment_destination_cancellation_photos',
						body.order_shipment_destination_cancellation_photos[i],
					);
				}
				return {
					method: 'POST',
					url: `order/${body.order_id}/shipment/${body.order_shipment_id}/destination/${body.order_shipment_destination_id}/cancel`,
					headers: {
						'Content-Type': 'multipart/form-data',
					},
					body: formData,
				};
			},
		}),
		getOrderShipmentDestinationCancellationReasons: builder.query<
			PaginationDataResultT<OrderShipmentDestinationCancellationReasonDTO>,
			PaginationRequestDTO
		>({
			query(body) {
				return {
					method: 'GET',
					url: `order-shipment-destination-cancellation-reason?page=${body.page}&size=${body.size}`,
				};
			},
		}),
		getOrderShipmentCancellationReasons: builder.query<
			PaginationDataResultT<OrderShipmentCancellationReasonDTO>,
			PaginationRequestDTO
		>({
			query(body) {
				return {
					method: 'GET',
					url: `order-shipment-cancellation-reason?page=${body.page}&size=${body.size}`,
				};
			},
		}),
		getOrderShipmentDestinationDeliveryPhotoLink: builder.query<{ url: string }, string>({
			query(order_shipment_destination_delivery_photo_id) {
				return {
					url: `shipment/destination-photo/${order_shipment_destination_delivery_photo_id}/signed-url`,
					method: 'GET',
				};
			},
		}),
		getOrderShipmentDestinationCancellationPhotoLink: builder.query<{ url: string }, string>({
			query(order_shipment_destination_cancellation_photo_id) {
				return {
					url: `shipment/cancellation-photo/${order_shipment_destination_cancellation_photo_id}/signed-url`,
					method: 'GET',
				};
			},
		}),
	}),
});

export const {
	useCreateShipmentMutation,
	useUpdateShipmentMutation,
	useLazyCancelOrderShipmentQuery,
	useLazyRemoveOrderShipmentDestinationQuery,
	useLazyStartOrderShipmentQuery,
	useLazyGetActiveOrderShipmentQuery,
	useLazyGetOrderShipmentDestinationCancellationReasonsQuery,
	useDeliverOrderShipmentDestinationMutation,
	useCancelOrderShipmentDestinationMutation,
	useLazyGetOrderShipmentCancellationReasonsQuery,
	useLazyGetOrderShipmentDestinationDeliveryPhotoLinkQuery,
	useLazyGetOrderShipmentDestinationCancellationPhotoLinkQuery,
} = orderShipmentApi;
