import { FontFamily } from '@/theme/fonts';
import { font } from '@/theme/responsive';
import React from 'react';
import { Text, TextProps } from 'react-native';
import colors from '@/theme/colors.ts';

type PalRiderTextProps = {
	color?: string;
	fontFamily?: string;
	fontSize?: number;
} & TextProps;

const PalRiderText: React.FC<PalRiderTextProps> = (props) => {
	const { color = colors.black, fontFamily = FontFamily.Regular, fontSize = font.small } = props;
	return (
		<Text
			{...props}
			style={[
				{
					fontFamily: fontFamily,
					fontSize: fontSize,
					color: color,
				},
				props.style,
			]}
			allowFontScaling={false}
			textBreakStrategy="highQuality"
			maxFontSizeMultiplier={1}
		>
			{props.children}
		</Text>
	);
};

export default PalRiderText;
