import PalRiderButton from '@/components/PalRiderButton.tsx';
import PalRiderText from '@/components/PalRiderText.tsx';
import PalRiderTextInput from '@/components/PalRiderTextInput.tsx';
import colors from '@/theme/colors.ts';
import { FontFamily } from '@/theme/fonts.ts';
import { font, normalize, PADDING } from '@/theme/responsive.ts';
import { yupTyped } from '@/types';
import { maskUKPlate } from '@/utils';
import { useFormik } from 'formik';
import React, { forwardRef, ForwardRefRenderFunction, useImperativeHandle, useState } from 'react';
import { Image, Modal, Pressable, SafeAreaView, ScrollView, StyleSheet, View } from 'react-native';
import { array, number, object, string } from 'yup';
import { buttonStyling } from '@/theme/defaults';
import Dropdown from 'react-native-input-select';
import { TSelectedItem } from 'react-native-input-select/lib/typescript/src/types/index.types';
import { globalStyles } from '@/utils/global-styles';
import PalRiderBottomSelectModal from '@/components/PalRiderBottomSelectModal';
import { launchCamera, launchImageLibrary } from 'react-native-image-picker';
import { FileType } from '@/@types';
import { CreateCourierVehicleRequestDTO } from 'palriderapptypes/courier';
import Icon from '@/components/Icon';

type SignUpCourierVehicleAddModalProps = {
	onVehicleAdded: (vehicle: CreateCourierVehicleRequestDTO) => void;
};
export type SignUpCourierVehicleAddModalRef = {
	openModal: () => void;
	closeModal: () => void;
};
const SignUpCourierVehicleAddScreen: ForwardRefRenderFunction<
	SignUpCourierVehicleAddModalRef,
	SignUpCourierVehicleAddModalProps
> = (props, ref) => {
	const [modalVisible, setModalVisible] = useState(false);
	const [imageModalVisible, setImageModalVisible] = useState(false);
	const vehicleAddFormik = useFormik<CreateCourierVehicleRequestDTO>({
		initialValues: {
			type: 'bike',
			plate_number: '',
			photos: [],
		},
		validationSchema: yupTyped<CreateCourierVehicleRequestDTO>({
			type: string().required().label('Type'),
			plate_number: string()
				.label('Plate Number')
				.when('type', (type, schema) => {
					if (type && (type.includes('motorcycle') || type.includes('car'))) {
						return schema.required().min(3);
					}
					return schema;
				}),
			photos: array()
				.of(
					object().shape({
						name: string().required('File name required'),
						size: number().required().max(10000000),
					}),
				)
				.required()
				.label('Vehicle Images')
				.min(1, 'At least one image required')
				.max(3, 'No more than 3 images are allowed'),
		}),
		onSubmit: async (values) => {
			try {
				setModalVisible(false);
				props.onVehicleAdded(values);
			} catch {
				// LoaderUtil.hide();
			}
		},
	});
	useImperativeHandle(ref, () => ({
		openModal: () => setModalVisible(true),
		closeModal: () => setModalVisible(false),
	}));

	const isNotBicycle = () =>
		vehicleAddFormik.values.type &&
		(vehicleAddFormik.values.type.includes('motorcycle') || vehicleAddFormik.values.type.includes('car'));

	return (
		<Modal
			presentationStyle="formSheet"
			animationType="slide"
			visible={modalVisible}
			onDismiss={async () => {
				setModalVisible(false);
				vehicleAddFormik.resetForm();
			}}
			onRequestClose={() => setModalVisible(false)}
		>
			<PalRiderBottomSelectModal
				data={[
					{
						text: 'Pick From Library',
						async onPress() {
							const res = await launchImageLibrary({
								mediaType: 'photo',
								includeExtra: true,
								presentationStyle: 'fullScreen',
								quality: 1,
								selectionLimit: 1,
							});
							if (res.didCancel || res.errorCode || !res.assets || !res.assets[0]) {
								return;
							}
							const file = res.assets[0];
							const images = [
								...vehicleAddFormik.values.photos,
								{
									name: file.fileName,
									size: file.fileSize,
									type: file.type,
									uri: file.uri,
								} as FileType,
							];
							vehicleAddFormik.setFieldValue('photos', images);
							setImageModalVisible(false);
						},
					},
					{
						text: 'Take A Photo',
						async onPress() {
							try {
								const res = await launchCamera({
									mediaType: 'photo',
									includeExtra: true,
									presentationStyle: 'overCurrentContext',
									quality: 1,
									saveToPhotos: true,
								});
								if (res.didCancel || res.errorCode || !res.assets || !res.assets[0]) {
									return;
								}
								const file = res.assets[0];
								const images = [...vehicleAddFormik.values.photos, file];
								vehicleAddFormik.setFieldValue('photos', images);
								setImageModalVisible(false);
							} catch (e) {
								console.error(e);
							}
						},
					},
				]}
				isVisible={imageModalVisible}
				title="Select"
				cancelOnPress={() => setImageModalVisible(false)}
				isCoverScreen
			/>
			<SafeAreaView>
				<View style={styles.container}>
					<Dropdown
						{...globalStyles.dropdownProps}
						options={[
							{
								value: 'bike',
								label: 'Bicycle / Electric Bike',
							},
							{
								value: 'motorcycle',
								label: 'Motorcycle',
							},
							{
								value: 'car',
								label: 'Car',
							},
						]}
						isSearchable
						isMultiple={false}
						selectedValue={vehicleAddFormik.values.type as TSelectedItem}
						onValueChange={(value) => vehicleAddFormik.setFieldValue('type', value)}
						maxSelectableItems={1}
					/>
					{vehicleAddFormik.errors.type && (
						<PalRiderText style={globalStyles.errorTextStyle}>{vehicleAddFormik.errors.type}</PalRiderText>
					)}
					{vehicleAddFormik.values.type !== undefined && (
						<View style={vehicleSytles.container}>
							{isNotBicycle() && (
								<View style={{ marginTop: normalize(10) }}>
									<PalRiderTextInput
										title="Plate Number"
										onChangeText={(text) => vehicleAddFormik.setFieldValue('plate_number', text, true)}
										maxLength={8}
										placeholder="AA00 AAA"
										onBlur={vehicleAddFormik.handleBlur('plate_number')}
										value={vehicleAddFormik.values.plate_number}
										error={vehicleAddFormik.errors.plate_number}
										autoCapitalize="characters"
										required
									/>
								</View>
							)}
							<ScrollView
								style={[
									vehicleSytles.addImageContainer,
									{
										marginTop: isNotBicycle() ? normalize(0) : normalize(10),
									},
								]}
							>
								<PalRiderText style={vehicleSytles.imageTitle}>Vehicle Images</PalRiderText>
								<View
									style={{
										flexDirection: 'column',
										gap: normalize(8),
										marginTop: 10,
									}}
								>
									{vehicleAddFormik.values.photos.length > 0 &&
										vehicleAddFormik.values.photos.map((vehicleImage, vehicleImageIndex) => (
											<View style={vehicleSytles.vehicleImageContainer} key={vehicleImageIndex}>
												<Pressable
													onPress={async () => {
														const images = vehicleAddFormik.values.photos.filter(
															(_, _vehicleImageIndex) => vehicleImageIndex !== _vehicleImageIndex,
														);
														await vehicleAddFormik.setFieldValue('photos', images);
													}}
													style={vehicleSytles.vehicleImageRemoveButton}
												>
													<Icon name="TrashIconSvg" width={20} height={20} color="white" />
												</Pressable>
												<Image
													source={{
														uri: vehicleImage.uri,
													}}
													style={{
														width: '100%',
														height: normalize(160),
													}}
												/>
											</View>
										))}
									{vehicleAddFormik.values.photos.length > 0 && vehicleAddFormik.values.photos.length < 3 && (
										<View style={vehicleSytles.vehicleImageContainer}>
											<Pressable style={vehicleSytles.vehicleImageAddButton} onPress={() => setImageModalVisible(true)}>
												<Icon name="PlusIconSvg" width={20} height={20} color="white" />
											</Pressable>
										</View>
									)}
								</View>
								{vehicleAddFormik.values.photos.length === 0 && (
									<Pressable style={vehicleSytles.addImageContainerInner} onPress={() => setImageModalVisible(true)}>
										<View style={vehicleSytles.addImageButton}>
											<Icon name="CameraIconSvg" />
										</View>
										<View style={vehicleSytles.takeAPhotoContainer}>
											<PalRiderText style={vehicleSytles.takeAPhotoText}>Take A Photo</PalRiderText>
											<PalRiderText style={vehicleSytles.takeAPhotoDescription} lineBreakStrategyIOS="standard">
												You must take a minimum of 1 and a maximum of 3 photos to continue.
											</PalRiderText>
										</View>
									</Pressable>
								)}
							</ScrollView>
						</View>
					)}
					<PalRiderButton
						style={[buttonStyling.dark, { marginTop: PADDING.large }]}
						onPress={() => vehicleAddFormik.handleSubmit()}
					>
						<PalRiderText color="white">Continue</PalRiderText>
					</PalRiderButton>
				</View>
			</SafeAreaView>
		</Modal>
	);
};

const styles = StyleSheet.create({
	container: {
		padding: normalize(20),
	},

	radioButton: {
		width: 20,
		height: 20,
		borderRadius: 20 / 2,
		borderWidth: 3,
		borderColor: 'white',
	},
});

const vehicleSytles = StyleSheet.create({
	container: {
		gap: normalize(10),
	},
	addImageContainer: {
		gap: normalize(4),
	},
	imageTitle: {
		fontFamily: FontFamily.Semibold,
	},
	addImageContainerInner: {
		flexDirection: 'row',
		alignItems: 'center',
		width: '100%',
		gap: normalize(12),
	},
	addImageButton: {
		backgroundColor: 'rgba(0,0,0,.1)',
		justifyContent: 'center',
		alignItems: 'center',
		width: normalize(80),
		height: normalize(80),
		borderRadius: normalize(12),
	},
	vehicleImageContainer: {
		backgroundColor: 'rgba(0,0,0,.1)',
		justifyContent: 'center',
		alignItems: 'center',
		width: '100%',
		height: normalize(160),
		borderRadius: normalize(12),
		overflow: 'hidden',
	},
	vehicleImageRemoveButton: {
		position: 'absolute',
		width: '100%',
		height: '100%',
		justifyContent: 'center',
		alignItems: 'center',
		backgroundColor: 'rgba(0,0,0,.4)',
		zIndex: 999,
	},
	vehicleImageAddButton: {
		position: 'absolute',
		width: '100%',
		height: '100%',
		justifyContent: 'center',
		alignItems: 'center',
		backgroundColor: 'rgba(0,0,0,.7)',
		zIndex: 999,
	},
	takeAPhotoContainer: {
		flex: 1,
	},
	takeAPhotoText: {
		fontFamily: FontFamily.Semibold,
		fontSize: normalize(14),
	},
	takeAPhotoDescription: {
		fontFamily: FontFamily.Regular,
		fontSize: normalize(10),
		color: colors.gray[400],
	},
});
export default forwardRef(SignUpCourierVehicleAddScreen);
