import React, { useCallback, useEffect, useState } from 'react';
import PalRiderText from '@/components/PalRiderText';
import { Pressable, StyleSheet, View } from 'react-native';
import { SafeAreaView, useSafeAreaInsets } from 'react-native-safe-area-context';
import { PADDING } from '@/theme/responsive';
import { buttonStyling } from '@/theme/defaults';
import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { CompositeScreenProps } from '@react-navigation/native';
import { useCreateShipmentMutation, useUpdateShipmentMutation } from '@/services/api/order/shipment';
import { useModal } from '@/components/ModalProvider';
import { calculateDistance, calculateDistanceInMiles, isFetchBaseQueryError, safeAreaEdges } from '@/utils';
import {
	CreateOrderShipmentDestinationRequestDTO,
	OrderShipmentDestinationDTO,
	OrderShipmentDTO,
} from 'palriderapptypes/order';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { AppOrderStackParamList } from '@/navigation/order-navigation';
import { RootStackParamList } from '@/navigation';
import DraggableFlatList, { ScaleDecorator } from '@bwjohns4/react-native-draggable-flatlist';
import Swipeable from 'react-native-gesture-handler/ReanimatedSwipeable';
import PalRiderButton from '@/components/PalRiderButton';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import WarningModal from '@/components/custom-modal/WarningModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import Icon from '@/components/Icon';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppOrderStackParamList, 'UpdateShipment'>,
	CompositeScreenProps<NativeStackScreenProps<AppOrderStackParamList>, NativeStackScreenProps<RootStackParamList>>
>;
const AppActiveOrderUpdateOrderShipmentScreen: React.FC<Props> = ({ route, navigation }) => {
	const [updateShipment] = useUpdateShipmentMutation();
	const { showGlobalModal, hideGlobalModal } = useModal();
	const [orderShipment, setOrderShipment] = useState<OrderShipmentDTO>(route.params.shipment);
	const [orderShipmentDestinations, setOrderShipmentDestinations] = useState<
		CreateOrderShipmentDestinationRequestDTO[]
	>(
		route.params.shipment.order_shipment_destinations.map((dest) => ({
			address: dest.address,
			contains_adult_content: dest.contains_adult_content,
			latitude: dest.latitude,
			longitude: dest.longitude,
			notes: dest.notes,
			payment_at_the_door: dest.pay_at_the_door,
			receive_fee: dest.received_fee,
			sort: dest.sort,
			post_code: dest.post_code ?? '',
		})),
	);

	useEffect(() => {
		if (!route.params.shipment) navigation.goBack();
	}, []);
	const removeFromDestinations = (sort: number) => {
		const updatedDestinations = orderShipmentDestinations
			.filter((x) => x.sort !== sort)
			.map((item, index) => ({
				...item,
				sort: index + 1, // Reassign sort order sequentially
			}));

		setOrderShipmentDestinations(updatedDestinations);
	};
	const reorderAddresses = (from: number, to: number) => {
		const newArray = [...orderShipmentDestinations];
		const item = newArray.splice(from, 1)[0]; // Remove the item at the 'from' index
		newArray.splice(to, 0, item); // Insert the item at the 'to' index

		setOrderShipmentDestinations(
			newArray.map((newArrItem, index) => ({
				...newArrItem,
				sort: index + 1,
			})),
		);
	};
	const renderRightActions = useCallback(
		(sort: number) => {
			return (
				<View style={{ justifyContent: 'center', alignItems: 'center', width: 80 }}>
					<Pressable style={[buttonStyling.error, { width: 50 }]} onPress={() => removeFromDestinations(sort)}>
						<Icon name="TrashIconSvg" color={colors.white} />
					</Pressable>
				</View>
			);
		},
		[orderShipmentDestinations, removeFromDestinations],
	);
	const updateDestinations = async () => {
		try {
			showGlobalModal({
				children: <LoadingModal />,
				backgroundColor: colors.transparent,
				preventHiding: true,
			});

			const result = await updateShipment({
				destinations: orderShipmentDestinations,
				order_shipment_id: route.params.shipment.id,
				order_id: route.params.shipment.order_id,
			});
			hideGlobalModal();
			if (result.error && isFetchBaseQueryError(result.error)) {
				showGlobalModal({
					children: <WarningModal text={result.error.data.title} />,
				});
				return;
			}
			showGlobalModal({
				children: <SuccessModal text="Shipment Updated" />,
				closeAfterDelay: 2000,
				whenClose() {
					navigation.goBack();
				},
			});
		} catch (err) {
			console.error(err);
		}
	};
	return (
		<SafeAreaView style={{ flex: 1, padding: PADDING.large }} edges={safeAreaEdges}>
			<View style={styles.addressListContainer}>
				<DraggableFlatList
					data={orderShipmentDestinations}
					keyExtractor={(_, index) => index.toString()}
					containerStyle={{ overflow: 'visible', gap: PADDING.large }}
					contentContainerStyle={{ gap: PADDING.large }}
					showsVerticalScrollIndicator={false}
					onDragEnd={({ from, to }) => reorderAddresses(from, to)}
					renderItem={({ item, getIndex, drag, isActive }) => {
						return (
							<Swipeable renderRightActions={() => renderRightActions(item.sort)} overshootFriction={20}>
								<ScaleDecorator activeScale={0.9}>
									<Pressable onLongPress={drag} disabled={isActive} style={styles.addressContainer}>
										<View style={styles.addressInnerContainer}>
											<View style={styles.roundedBox}>
												<PalRiderText color={colors.white}>{getIndex()! + 1}</PalRiderText>
											</View>
											<View style={styles.addressTextContainer}>
												<PalRiderText fontFamily={FontFamily.Semibold} numberOfLines={1}>
													{item.address}
												</PalRiderText>
											</View>
										</View>
										<View style={styles.shipmentInfoContainer}>
											<View style={styles.shipmentInfoItemContainer}>
												<PalRiderText>Is Customer Paying ?</PalRiderText>
												{item.payment_at_the_door ? (
													<Icon name="CheckCircleIconSvg" color={colors.green[600]} />
												) : (
													<Icon name="CloseIconSvg" color={colors.red[600]} />
												)}
											</View>

											<View style={styles.shipmentInfoItemContainer}>
												<PalRiderText>Shipmet has adult staffs ?</PalRiderText>
												{item.contains_adult_content ? (
													<Icon name="CheckCircleIconSvg" color={colors.green[600]} />
												) : (
													<Icon name="CloseIconSvg" color={colors.red[600]} />
												)}
											</View>
											<View style={styles.shipmentInfoItemContainer}>
												<PalRiderText>Approximate Distance</PalRiderText>
												<PalRiderText>
													{calculateDistanceInMiles(
														item.latitude,
														item.longitude,
														orderShipment.order_shipment_departure.company_area_address.latitude,
														orderShipment.order_shipment_departure.company_area_address.longitude,
													).toFixed(2)}{' '}
													Mile
												</PalRiderText>
											</View>
										</View>
									</Pressable>
								</ScaleDecorator>
							</Swipeable>
						);
					}}
				/>
			</View>
			<PalRiderButton style={[buttonStyling.dark]} onPress={updateDestinations}>
				<PalRiderText color={colors.white}>Update Destinations</PalRiderText>
			</PalRiderButton>
		</SafeAreaView>
	);
};
const styles = StyleSheet.create({
	container: { flex: 1 },
	addressListContainer: {
		flex: 1,
		marginVertical: PADDING.large,
		flexDirection: 'column',
		rowGap: PADDING.medium,
		zIndex: 999999,
	},
	addressContainer: {
		flexDirection: 'column',
		gap: PADDING.small,
		borderWidth: 1,
		borderColor: colors.gray[300],
		padding: PADDING.medium,
		borderRadius: PADDING.medium,
		zIndex: 999999,
		backgroundColor: colors.white,
	},
	addressInnerContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		columnGap: PADDING.small,
		paddingRight: PADDING.medium,
	},
	roundedBox: {
		width: PADDING.xlarge * 2,
		height: PADDING.xlarge * 2,
		backgroundColor: colors.green[600],
		justifyContent: 'center',
		alignItems: 'center',
		borderRadius: PADDING.xlarge * 2,
	},
	addressTextContainer: { flex: 1, alignItems: 'center' },
	shipmentInfoContainer: {
		flexDirection: 'column',
		rowGap: PADDING.large,
		marginTop: PADDING.medium,
	},
	shipmentInfoItemContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		justifyContent: 'space-between',
	},
	buttonContainer: {
		gap: PADDING.medium,
	},
});
export default AppActiveOrderUpdateOrderShipmentScreen;
