// Area stack navigator
function AppCompanyProfileCompanyAreaStack() {
	const { t } = useTranslation();
	return (
		<AreaStack.Navigator
			initialRouteName="CompanyAreas"
			screenOptions={{
				headerShown: true, // Default to false
				headerBackButtonDisplayMode: 'minimal',
				headerTintColor: colors.white,
				headerStyle: { backgroundColor: colors.orange[600] },
				headerTitleAlign: 'center',
				headerTitleStyle: {
					fontFamily: FontFamily.Semibold,
					fontSize: font.medium,
					color: colors.white,
				},
			}}
		>
			{/* Remove the group-level headerShown: false since it's now in screenOptions */}
			<AreaStack.Group>
				<AreaStack.Screen
					name="CompanyAreas"
					options={{ headerShown: true, title: t('screen.titles.company.profile_screen.areas') }}
					component={AppCompanyProfileCompanyAreasScreen}
				/>
				<AreaStack.Screen
					name="CompanyAreaView"
					component={AppCompanyProfileCompanyAreaViewScreen}
					options={{ headerShown: true, title: t('screen.titles.company.profile_screen.areas_screen.view_area') }}
				/>
				<AreaStack.Screen
					name="CompanyAreaCreate"
					component={AppCompanyProfileAreaCreateScreen}
					options={{
						headerShown: true,
						title: t('screen.titles.company.profile_screen.areas_screen.create_area'),
					}}
				/>
			</AreaStack.Group>

			{/* Area Addresses Group */}
			<AreaStack.Group>
				<AreaStack.Screen
					name="CompanyAreaAddresses"
					component={AppCompanyProfileCompanyAreaAddressesScreen}
					options={{ headerShown: true, title: t('screen.titles.company.profile_screen.area.addresses') }}
				/>
				<AreaStack.Screen
					name="CompanyAreaAddressCreate"
					component={AppCompanyProfileCompanyAreaAddressCreateScreen}
					options={{
						headerShown: true,
						title: t('screen.titles.company.profile_screen.area.addresses_screen.create_address'),
					}}
				/>
				<AreaStack.Screen
					name="CompanyAreaAddressView"
					component={AppCompanyProfileCompanyAreaAddressViewScreen}
					options={{
						headerShown: true,
						title: t('screen.titles.company.profile_screen.area.addresses_screen.view_address'),
					}}
				/>
			</AreaStack.Group>

			{/* Area Documents Group */}
			<AreaStack.Group>
				<AreaStack.Screen
					name="CompanyAreaAddressDocuments"
					component={AppCompanyProfileCompanyAreaAddressDocumentsScreen}
					options={{ headerShown: true, title: 'Address Documents' }}
				/>
				<AreaStack.Screen
					name="CompanyAreaAddressDocumentCreate"
					component={AppCompanyProfileCompanyAreaAddressDocumentAddScreen}
					options={{
						headerShown: true,
						title: 'Upload Address Document',
					}}
				/>
			</AreaStack.Group>

			<AreaStack.Group>
				<AreaStack.Screen
					name="CompanyAreaAddressPhotos"
					component={AppCompanyProfileCompanyAreaAddressPhotosScreen}
					options={{ headerShown: true, title: 'Photos' }}
				/>
				<AreaStack.Screen
					name="CompanyAreaAddressPhotoCreate"
					component={AppCompanyProfileCompanyAreaAddressPhotoAddScreen}
					options={{
						headerShown: true,
						title: 'Add Photo',
					}}
				/>
			</AreaStack.Group>

			{/* Area Users Group */}
			<AreaStack.Group>
				<AreaStack.Screen
					name="CompanyAreaAddressUsers"
					component={AppCompanyProfileCompanyAreaAddressUsersScreen}
					options={{ headerShown: true, title: 'Address Users' }}
				/>
				<AreaStack.Screen
					name="CompanyAreaAddressUserView"
					component={AppCompanyProfileCompanyAreaAddressUserViewScreen}
					options={{
						headerShown: true,
						title: 'View Address User',
					}}
				/>
				<AreaStack.Screen
					name="CompanyAreaAddressUserCreate"
					component={AppCompanyProfileCompanyAreaAddressUserCreateScreen}
					options={{
						headerShown: true,
						title: 'Create Address User',
					}}
				/>
			</AreaStack.Group>
			<AreaStack.Group>
				<AreaStack.Screen
					name="CompanyAreaAddressWallet"
					component={AppCompanyProfileCompanyAreaAddressWalletScreen}
					options={{ headerShown: true, title: 'Address Wallet' }}
				/>
				<AreaStack.Screen
					name="CompanyAreaAddressWalletTransaction"
					component={AppCompanyProfileCompanyAreaWalletTransactionListScreen}
					options={{
						headerShown: true,
						title: 'Address Wallet Transaction List',
					}}
				/>
				<AreaStack.Screen
					name="CompanyAreaAddressWalletTransferRequests"
					component={AppCompanyProfileCompanyAreaAddressWalletTransferRequestScreen}
					options={{
						headerShown: true,
						title: 'Address Wallet Transfer Requests',
					}}
				/>
				<AreaStack.Screen
					name="CompanyAreaAddressWalletCreate"
					component={CompanyAppProfileAddNewCompanyAreaAddressWalletScreen}
					options={{
						headerShown: true,
						title: 'Create Address Wallet',
					}}
				/>
				<AreaStack.Screen
					name="CompanyAreaAddressWalletUpdate"
					component={CompanyAppProfileUpdateCompanyAreaWalletScreen}
					options={{
						headerShown: true,
						title: 'Update Address Wallet',
					}}
				/>
			</AreaStack.Group>
		</AreaStack.Navigator>
	);
}

