// Bottom tab navigator
export function AppCompanyStackNavigator() {
	const { t } = useTranslation();

	return (
		<View style={{ flex: 1 }}>
			<Tab.Navigator
				screenOptions={{
					headerShadowVisible: false,
					tabBarStyle: {
						height: Platform.OS == 'android' ? 60 : 80,
						paddingBottom: 5,
						paddingTop: 5,
					},
					tabBarLabelStyle: {
						fontFamily: FontFamily.Semibold,
						fontSize: font.mini,
						paddingBottom: 5,
					},
					headerTitleAlign: 'center',
					tabBarActiveTintColor: colors.orange[600],
					tabBarInactiveTintColor: colors.black,
					headerTintColor: colors.white,
					headerStyle: { backgroundColor: colors.orange[600] },
				}}
			>
				<Tab.Screen
					name="CompanyHome"
					component={AppCompanyHomeScreen}
					options={{
						title: t('screen.titles.company.home'),
						headerShown: false,
						tabBarIcon: ({ focused }) => (
							<HomeIconSvg width={20} height={20} color={focused ? colors.orange[600] : colors.black} />
						),
					}}
				/>

				<Tab.Screen
					name="CompanyOrderStack"
					component={AppCompanyOrderStack}
					options={{
						title: t('screen.titles.company.order'),
						headerShown: false,
						tabBarIcon: ({ focused }) => (
							<ShippingBoxIconSvg width={20} height={20} color={focused ? colors.orange[600] : colors.black} />
						),
						headerTintColor: colors.white,
					}}
				/>
				<Tab.Screen
					name="CompanyNotifications"
					component={AppCompanyNotificationsScreen}
					options={{
						title: t('screen.titles.company.notifications'),
						headerShown: false,
						tabBarIcon: ({ focused }) => (
							<NotificationIconSvg width={20} height={20} color={focused ? colors.orange[600] : colors.black} />
						),
					}}
				/>
				<Tab.Screen
					name="CompanyProfileStack"
					component={AppCompanyProfileStack}
					options={{
						title: t('screen.titles.company.profile'),
						headerShown: false,
						tabBarIcon: ({ focused }) => (
							<ProfileIconSvg width={20} height={20} color={focused ? colors.orange[600] : colors.black} />
						),
					}}
				/>
			</Tab.Navigator>
			<PalRiderCallRiderFab />
		</View>
	);
}
