import { PaginatedRequestDTO } from '@/@types';
import { createApi } from '@reduxjs/toolkit/query/react';
import { PaginationDataResultT, SuccessfulResponse, SuccessfulResponseT } from 'palriderapptypes';
import { SearchAndSortRequestDTO } from 'palriderapptypes/common';
import {
	CompanyAreaAddressDTO,
	CompanyAreaDTO,
	CompanyDTO,
	OnboardingCompanyRequestDTO,
} from 'palriderapptypes/company';
import { baseQueryConfigWithReAuth } from 'src/services/api/baseQueryConfig.ts';

export type CompanyStatisticsDTO = {
	area_count: number;
	area_address_count: number;
	area_address_user_count: number;
	current_month_invoice_total: number;
	total_shipment_count: number;
	total_shipment_destination_count: number;
	successful_shipment_destination_count: number;
	unsuccessful_shipment_destination_count: number;
	total_worked_courier: number;
	current_month_total_order: number;
};

export const companyApi = createApi({
	reducerPath: 'company',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		companyOnboarding: builder.mutation<SuccessfulResponse, OnboardingCompanyRequestDTO>({
			query(body) {
				const formData = new FormData();
				formData.append('company.name', body.company.name);
				formData.append('company.official_name', body.company.official_name);
				formData.append('company.company_category_id', body.company.company_category_id);
				formData.append('area.info.name', body.area.info.name);
				formData.append('area.info.email', body.area.info.email);
				formData.append('area.user.name', body.area.user.name);
				formData.append('area.user.surname', body.area.user.surname);
				formData.append('area.user.birthday', body.area.user.birthday);
				formData.append('area.address.address', body.area.address.address);
				formData.append('area.address.latitude', body.area.address.latitude);
				formData.append('area.address.longitude', body.area.address.longitude);
				formData.append('area.address.building', body.area.address.building);
				formData.append('area.address.post_code', body.area.address.post_code);
				formData.append('area.address.directions', body.area.address.directions);
				for (let i = 0; i < body.area.address.documents.length; i++) {
					formData.append('area.address.documents', body.area.address.documents[i]);
				}
				for (let i = 0; i < body.area.address.photos.length; i++) {
					formData.append('area.address.photos', body.area.address.photos[i]);
				}
				return {
					headers: {
						'Content-Type': 'multipart/form-data',
					},
					method: 'POST',
					url: 'company/onboarding',
					body: formData,
				};
			},
		}),
		getCompanyAreasFromCompany: builder.query<
			PaginationDataResultT<CompanyAreaDTO>,
			PaginatedRequestDTO & { company_id: string }
		>({
			query(body) {
				return {
					method: 'GET',
					url: `company/${body.company_id}/areas?page=${body.page_number}&size=${body.page_size}`,
				};
			},
		}),
		getCompanyAddressesFromCompany: builder.query<
			PaginationDataResultT<CompanyAreaAddressDTO>,
			PaginatedRequestDTO & { company_id: string } & Partial<SearchAndSortRequestDTO>
		>({
			query(body) {
				var uri = new URLSearchParams();
				if (body.page_number) {
					uri.append('page', body.page_number.toString());
				}
				if (body.page_size) {
					uri.append('size', body.page_size.toString());
				}
				if (body.search) {
					uri.append('search', body.search.toString());
				}
				if (body.sorting) {
					uri.append('sorting', body.sorting.toString());
				}
				if (body.sorting_column) {
					uri.append('sorting_column', body.sorting_column.toString());
				}
				return {
					method: 'GET',
					url: `company/${body.company_id}/addresses?${uri.toString()}`,
				};
			},
		}),
		getCompanyStatistics: builder.query<SuccessfulResponseT<CompanyStatisticsDTO>, void>({
			query() {
				return {
					method: 'GET',
					url: `company/statistics`,
				};
			},
		}),
	}),
});

export const {
	useCompanyOnboardingMutation,
	useLazyGetCompanyAreasFromCompanyQuery,
	useLazyGetCompanyStatisticsQuery,
	useLazyGetCompanyAddressesFromCompanyQuery,
} = companyApi;
