import React, { memo, useMemo, useState } from 'react';
import PalRiderText from '@/components/PalRiderText';
import { Pressable, ScrollView, StyleSheet, View } from 'react-native';
import { font, PADDING } from '@/theme/responsive';
import colors from '@/theme/colors';
import PalRiderBadge from '@/components/PalRiderBadge.tsx';
import { snakeToHumanReadable } from '@/utils';
import PalRiderPopupMenu from '@/components/PalRiderPopupMenu.tsx';
import { FontFamily } from '@/theme/fonts';
import { OrderShipmentDestinationDTO, OrderShipmentDTO } from 'palriderapptypes/order';
import { useTranslation } from 'react-i18next';
import { useModal } from '@/components/ModalProvider';
import WarningModal from '@/components/custom-modal/WarningModal';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import {
	useLazyGetOrderShipmentDestinationCancellationPhotoLinkQuery,
	useLazyGetOrderShipmentDestinationDeliveryPhotoLinkQuery,
} from '@/services/api/order/shipment';
import PalRiderDeliveryGalleryModal from '@/components/PalRiderDeliveryGalleryModal';
import EmptyModal from '@/components/custom-modal/EmptyModal';
import Icon from '@/components/Icon';

type Props = {
	shipments: Array<OrderShipmentDTO>;
};

const SingleShipment = memo((shipment: OrderShipmentDTO) => {
	const { showGlobalModal, hideGlobalModal } = useModal();
	const { t } = useTranslation();
	const [isOpened, setIsOpened] = useState(false);
	const [getOrderShipmentDestinationDeliveryPhotoLink] = useLazyGetOrderShipmentDestinationDeliveryPhotoLinkQuery();
	const [getOrderShipmentDestinationCancellationPhotoLink] =
		useLazyGetOrderShipmentDestinationCancellationPhotoLinkQuery();
	const handleBackgroundColor = useMemo(() => {
		return (status: OrderShipmentDestinationDTO['status']) => {
			switch (status) {
				case 'waiting_delivery':
					return colors.black;
				case 'on_the_way':
					return colors.purple[600];
				case 'delivered':
					return colors.green[600];
				case 'cancelled':
					return colors.red[600];
				default:
					return '';
			}
		};
	}, []);
	const findWhichShipment = useMemo(() => {
		return (orderShipment: OrderShipmentDTO) => {
			if (orderShipment.status === 'completed') return t('common.completed');
			if (orderShipment.status === 'cancelled') return t('common.cancelled');
			if (orderShipment.status === 'waiting_delivery') return t('common.waiting_delivery');
			if (orderShipment.status === 'on_delivery') {
				const findIndex = orderShipment.order_shipment_destinations.findIndex(
					(x) => x.id === shipment.current_order_shipment_destination_id,
				);
				return (
					orderShipment.order_shipment_destinations[findIndex !== -1 ? findIndex : 0].sort + '. ' + t('common.delivery')
				);
			}
		};
	}, []);
	const handleShowDeliveryImages = async (shipmentDestination: OrderShipmentDestinationDTO) => {
		const photoIds = shipmentDestination.order_shipment_destination_delivery_photos.map((p) => p.id);

		showGlobalModal({ children: <LoadingModal /> });

		try {
			const responses = await Promise.all(
				photoIds.map((id) => getOrderShipmentDestinationDeliveryPhotoLink(id).unwrap()),
			);
			const urls = responses.map((res) => res.url);
			showGlobalModal({
				children: <PalRiderDeliveryGalleryModal imageUrls={urls} onClose={() => hideGlobalModal()} />,
			});
		} catch (err) {
			console.error(err);
			showGlobalModal({
				children: <WarningModal text="Could not load images." />,
			});
		}
	};
	const handleShowCancellationImages = async (shipmentDestination: OrderShipmentDestinationDTO) => {
		const photoIds = shipmentDestination.order_shipment_destination_cancellation_photos.map((p) => p.id);

		showGlobalModal({ children: <LoadingModal /> });

		try {
			const responses = await Promise.all(
				photoIds.map((id) => getOrderShipmentDestinationCancellationPhotoLink(id).unwrap()),
			);
			const urls = responses.map((res) => res.url);

			showGlobalModal({
				children: <PalRiderDeliveryGalleryModal imageUrls={urls} onClose={() => hideGlobalModal()} />,
			});
		} catch (err) {
			console.error(err);
			showGlobalModal({
				children: <WarningModal text="Could not load images." />,
			});
		}
	};
	return (
		<View style={styles.container}>
			<View style={styles.shipmentContainer}>
				<View style={{ flex: 1 }}>
					<Pressable style={styles.shipmentTitleContainer} onPress={() => setIsOpened((prev) => !prev)}>
						<PalRiderText fontSize={font.mini} fontFamily={FontFamily.Semibold}>
							#{shipment?.order_shipment_no} - {new Date(shipment.created_at)?.toLocaleDateString()}{' '}
							{new Date(shipment.created_at)?.toLocaleTimeString()}
						</PalRiderText>
						{isOpened ? <Icon name="ChevronUpIconSvg" /> : <Icon name="ChevronDownIconSvg" />}
					</Pressable>
					<View style={{ flex: 1, flexDirection: 'row', alignItems: 'center' }}>
						<View style={{ flex: 1 }}>
							<View style={styles.shipmentBadgeContainer}>
								<PalRiderBadge text={shipment.courier.name} color={colors.blue[600]} />
								<PalRiderBadge
									text={shipment.order_shipment_destinations.length?.toString() + ' Destinations'}
									color={colors.orange[600]}
								/>
								<PalRiderBadge text={`${findWhichShipment(shipment)}`} color={colors.green[600]} />
								<View style={{ justifyContent: 'center' }}>
									<PalRiderPopupMenu trigger={<Icon name="ThreeHorizontalDotIconSvg" />}>
										{(closeModal) => (
											<>
												{shipment.order_shipment_cancellation_reason != null && (
													<PalRiderPopupMenu.MenuItem
														text={t('screen.company.order_info.show_cancellation_reason')}
														onPress={() => {
															showGlobalModal({
																children: (
																	<WarningModal text={shipment.order_shipment_cancellation_reason?.description} />
																),
															});
															closeModal();
														}}
													/>
												)}
											</>
										)}
									</PalRiderPopupMenu>
								</View>
							</View>
						</View>
					</View>
				</View>
			</View>
			{isOpened && (
				<View style={{ padding: PADDING.large }}>
					<View style={orderShipmentDestinationStyles.orderShipmentDestinationContainer}>
						{shipment.order_shipment_destinations.length > 0 &&
							shipment.order_shipment_destinations.map((shipmentDestination, shipmentDestinationIndex) => (
								<View key={shipmentDestination.id} style={{ flexDirection: 'row', gap: PADDING.large }}>
									<PalRiderText style={{ width: 10 }}>{shipmentDestination.sort}</PalRiderText>
									<View
										style={[
											orderShipmentDestinationStyles.pathContainer,
											{
												backgroundColor: handleBackgroundColor(shipmentDestination.status),
											},
										]}
									>
										{shipmentDestinationIndex === 0 && (
											<View
												style={[
													orderShipmentDestinationStyles.pathDotTop,
													{
														backgroundColor: handleBackgroundColor(shipmentDestination.status),
													},
												]}
											/>
										)}
										{shipmentDestinationIndex === shipment.order_shipment_destinations.length - 1 && (
											<View style={orderShipmentDestinationStyles.pathDotBottom} />
										)}
									</View>
									<View style={{ flex: 1, gap: PADDING.small, flexWrap: 'wrap' }}>
										<PalRiderText
											numberOfLines={1}
											style={{ maxWidth: '80%' }}
											fontSize={font.xmini}
											color={colors.gray[500]}
										>
											{shipmentDestination.address}
										</PalRiderText>
										<View style={{ flexDirection: 'row', gap: PADDING.small, flexWrap: 'wrap' }}>
											<PalRiderBadge
												color={handleBackgroundColor(shipmentDestination.status)}
												text={snakeToHumanReadable(shipmentDestination.status)}
											/>
										</View>
									</View>
									<View style={{ justifyContent: 'center' }}>
										<PalRiderPopupMenu trigger={<Icon name="ThreeHorizontalDotIconSvg" />}>
											{(closeModal) => (
												<>
													{shipmentDestination.order_shipment_destination_cancellation_reason != null && (
														<PalRiderPopupMenu.MenuItem
															text={t('screen.company.order_info.show_cancellation_reason')}
															onPress={() => {
																showGlobalModal({
																	children: (
																		<WarningModal
																			text={
																				shipmentDestination.order_shipment_destination_cancellation_reason?.description
																			}
																		/>
																	),
																});
																closeModal();
															}}
														/>
													)}
													{shipmentDestination.status === 'cancelled' &&
														shipmentDestination.order_shipment_destination_cancellation_photos?.length > 0 && (
															<PalRiderPopupMenu.MenuItem
																text="Show Cancellation Images"
																onPress={async () => {
																	handleShowCancellationImages(shipmentDestination);
																	closeModal();
																}}
															/>
														)}

													{shipmentDestination.notes && (
														<PalRiderPopupMenu.MenuItem
															text={t('screen.company.order_info.show_courier_note')}
															onPress={() => {
																showGlobalModal({
																	minHeight: 'auto',
																	children: (
																		<EmptyModal>
																			<PalRiderText>{shipmentDestination.notes?.trim()}</PalRiderText>
																		</EmptyModal>
																	),
																});
																closeModal();
															}}
														/>
													)}

													{shipmentDestination.status === 'delivered' &&
														shipmentDestination.order_shipment_destination_delivery_photos?.length > 0 && (
															<PalRiderPopupMenu.MenuItem
																text="Show Delivery Images"
																onPress={async () => {
																	handleShowDeliveryImages(shipmentDestination);
																	closeModal();
																}}
															/>
														)}
												</>
											)}
										</PalRiderPopupMenu>
									</View>
								</View>
							))}
					</View>
				</View>
			)}
		</View>
	);
});

const CompanyOrderShipmentTab: React.FC<Props> = ({ shipments }) => {
	if (shipments.length === 0) {
		return (
			<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
				<Icon name="MapPinsIconSvg" width={52} height={52} />
				<PalRiderText>Has no delivery in this status.</PalRiderText>
			</View>
		);
	}
	return (
		<ScrollView style={styles.container} contentInsetAdjustmentBehavior="automatic">
			{shipments.map((shipment) => (
				<SingleShipment key={shipment.id} {...shipment} />
			))}
		</ScrollView>
	);
};
const styles = StyleSheet.create({
	container: {
		flex: 1,
	},
	shipmentContainer: {
		borderWidth: 1,
		borderColor: colors.gray[300],
		borderTopColor: colors.transparent,
		backgroundColor: colors.white,
	},
	shipmentTitleContainer: {
		padding: PADDING.large,
		borderBottomColor: colors.gray[300],
		borderBottomWidth: 1,
		flex: 1,
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
	},
	shipmentBadgeContainer: {
		padding: PADDING.large,
		gap: PADDING.small,
		marginVertical: PADDING.small,
		flexDirection: 'row',
		flexWrap: 'wrap',
	},
	toggleButton: {},
});
const orderShipmentDestinationStyles = StyleSheet.create({
	orderShipmentDestinationContainer: {
		flexDirection: 'column',
		flex: 1,
		gap: PADDING.medium,
	},
	pathContainer: {
		width: 2,
		height: 'auto',
		backgroundColor: colors.orange[600],
		position: 'relative',
	},
	pathDotTop: {
		width: 8,
		height: 8,
		borderRadius: 8,
		backgroundColor: colors.orange[600],
		position: 'absolute',
		left: -3,
		top: 0,
	},
	pathDotBottom: {
		width: 8,
		height: 8,
		borderRadius: 8,
		backgroundColor: colors.purple[600],
		position: 'absolute',
		left: -3,
		bottom: 0,
	},
	actionButton: {
		padding: PADDING.small,
		backgroundColor: colors.black,
		borderRadius: PADDING.small,
		justifyContent: 'center',
	},
});
export default CompanyOrderShipmentTab;
