import React, { useRef, useState } from 'react';
import { StyleSheet, TouchableOpacity, View } from 'react-native';
import PalRiderText from '@/components/PalRiderText.tsx';
import PalRiderButton from '@/components/PalRiderButton.tsx';
import colors from '@/theme/colors.ts';
import { font, PADDING } from '@/theme/responsive.ts';
import { buttonStyling } from '@/theme/defaults.ts';
import WarningModal from '@/components/custom-modal/WarningModal';
import { isEmptyJson, isFetchBaseQueryError } from '@/utils';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { CompositeNavigationProp, StackActions } from '@react-navigation/native';
import Dropdown from 'react-native-input-select';
import { useAppDispatch, useAppSelector } from '@/redux/hooks.ts';
import { callRiderInititalState, setCallRiderState } from '@/redux/slices/callRiderSlice.ts';
import { useCreateOrderMutation } from '@/services/api/order';
import EmptyModal from '@/components/custom-modal/EmptyModal';
import { useTranslation } from 'react-i18next';
import { globalStyles } from '@/utils/global-styles';
import { array, number, object, ref } from 'yup';
import { ErrorMessage, FieldArray, Formik, FormikProps } from 'formik';
import { FontFamily } from '@/theme/fonts';
import PalRiderTextInput from '@/components/PalRiderTextInput';
import PalRiderCurrencyInput from '@/components/PalRiderCurrencyInput';
import { KeyboardAwareScrollView } from 'react-native-keyboard-aware-scroll-view';
import Icon from '@/components/Icon';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';
import { AppCompanyOrderParamList, AppCompanyTabParamList } from '@/navigation/company-navigation';
import { BottomTabNavigationProp } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import { useCostCalculations } from '../call-rider-price-info';
import { CompanyAreaAddressUserDTO } from 'palriderapptypes/company';

type Props = {
	prevStep: () => void;
	navigation: CompositeNavigationProp<
		NativeStackNavigationProp<AppCompanyOrderParamList, 'CompanyCallRider'>,
		CompositeNavigationProp<
			BottomTabNavigationProp<AppCompanyTabParamList, 'CompanyOrderStack'>,
			NativeStackNavigationProp<RootStackParamList>
		>
	>;
};

const validationSchema = object().shape({
	fields: array()
		.of(
			object().shape({
				min: number()
					.transform((_, originalValue) => (originalValue === '' ? undefined : Number(originalValue)))
					.required('From is required')
					.min(1, 'From must be at least 1'),
				max: number()
					.transform((_, originalValue) => (originalValue === '' ? undefined : Number(originalValue)))
					.required('To is required')
					.moreThan(ref('min'), 'To must be greater than From'),
				price: number()
					.transform((_, originalValue) => (originalValue === '' ? undefined : Number(originalValue)))
					.required('Price is required')
					.min(0, 'Price must be greater than or equal to 0'),
			}),
		)
		.test('sequential-ranges', 'Ranges must be continuous without gaps', function (fields) {
			if (!fields || fields.length === 0) return true;

			for (let i = 0; i < fields.length; i++) {
				const current = fields[i];
				if (!current || current.min == null || current.max == null) return false;

				// Check min <= max
				if (current.max < current.min) {
					return this.createError({
						path: `fields[${i}].max`,
						message: 'Max must be greater than or equal to Min',
					});
				}

				// Sequential relationship check
				if (i > 0) {
					const prev = fields[i - 1];

					if (current.min !== prev.max + 1) {
						return this.createError({
							path: `fields[${i}].min`,
							message: `From must be exactly ${prev.max + 1}`,
						});
					}

					// NEW: Price must not be less than previous price
					if (current.price <= prev.price) {
						return this.createError({
							path: `fields[${i}].price`,
							message: `Price must be at least ${prev.price + 0.1}`,
						});
					}
				}
			}

			return true;
		}),
});
type BonusType = {
	min: number | undefined;
	max: number | undefined;
	price: number | undefined;
	sort: number;
};
const CallRiderBonusInfo: React.FC<Props> = ({ prevStep, navigation }) => {
	const { t } = useTranslation();
	const dispatch = useAppDispatch();
	const callRiderSlice = useAppSelector((x) => x.callRiderSlice);
	const { showGlobalModal, hideGlobalModal } = useModal();
	const [createOrder] = useCreateOrderMutation();
	const [selectedBonusType, setSelectedBonusType] = useState<'none' | 'by_distance' | 'per_shipment'>('none');
	const initialValues: {
		fields: Array<BonusType>;
	} = {
		fields: callRiderSlice.order_bonuses,
	};
	const companyAreaAddressUser = useAppSelector(
		(x) => x.userSlice.user?.company_area_address_user,
	) as CompanyAreaAddressUserDTO;

	const formikRef = useRef<FormikProps<typeof initialValues>>(null);
	const [isFocusedIndex, setIsFocusedIndex] = useState<number | null>(null);

	const handleAddField = (push: (item: BonusType) => void, currentFields: BonusType[]) => {
		const nextSort = currentFields.length > 0 ? Math.max(...currentFields.map((f) => f.sort || 0)) + 1 : 1;
		push({ min: undefined, max: undefined, price: undefined, sort: nextSort });
	};
	const costBreakdown = useCostCalculations(
		callRiderSlice.hourly_rate,
		callRiderSlice.work_hour,
		callRiderSlice.courier_count,
		companyAreaAddressUser.company_app_fee,
	);

	const handleCallRider = async (formValues?: typeof initialValues) => {
		try {
			showGlobalModal({
				children: <LoadingModal />,
				preventHiding: false,
				backgroundColor: colors.transparent,
			});
			const result = await createOrder({
				company_area_id: callRiderSlice.company_area_id,
				company_area_address_id: callRiderSlice.company_area_address_id,
				company_area_address_wallet_id: callRiderSlice.company_area_address_wallet_id,
				courier_count: callRiderSlice.courier_count,
				start_time: callRiderSlice.start_time,
				work_hour: callRiderSlice.work_hour,
				hourly_rate: callRiderSlice.hourly_rate,
				vehicle_types: callRiderSlice.vehicle_types,
				order_bonuses:
					formValues?.fields.flatMap((item) => ({
						min: Number(item.min),
						max: Number(item.max),
						price: Number(item.price),
						sort: Number(item.sort),
					})) ?? [],
				order_bonus_type: selectedBonusType,
			});
			hideGlobalModal();
			if (result.error && isFetchBaseQueryError(result.error)) {
				if (result.error.data.metadata) {
					if (result.error.data.metadata?.type === 'has_no_balance') {
						showGlobalModal({
							children: (
								<EmptyModal>
									<Icon name="PoundBanknoteIconSvg" />
									<PalRiderText>{result.error.data.title}</PalRiderText>
									<PalRiderButton
										style={{ marginTop: PADDING.medium, width: '100%' }}
										onPress={() => {
											navigation.navigate('AppCompanyStack', {
												screen: 'CompanyProfileStack',
												params: {
													screen: 'CompanyWallet',
												},
											});
										}}
									>
										<PalRiderText color={colors.white}>{t('common.add_balance')}</PalRiderText>
									</PalRiderButton>
								</EmptyModal>
							),
						});
						return;
					}

					if (result.error.data.metadata?.type === 'estimate_price_going_higher') {
						showGlobalModal({
							children: (
								<EmptyModal>
									<Icon name="PoundBanknoteIconSvg" />
									<PalRiderText style={{ textAlign: 'center' }}>{result.error.data.title}</PalRiderText>
									<PalRiderButton
										style={{ marginTop: PADDING.medium, width: '100%' }}
										onPress={() => {
											navigation.navigate('AppCompanyStack', {
												screen: 'CompanyProfileStack',
												params: {
													screen: 'CompanyAreaStack',
													params: {
														screen: 'CompanyAreaAddressWallet',
														params: {
															company_area_address_id: callRiderSlice.company_area_address_id,
															company_area_address_wallet_id: callRiderSlice.company_area_address_wallet_id,
															add_new_balance: true,
															remaining_balance: Number(costBreakdown.hourlyRate.toString().substring(1)),
														},
													},
												},
											});

											hideGlobalModal();
										}}
									>
										<PalRiderText color={colors.white}>{t('common.add_balance')}</PalRiderText>
									</PalRiderButton>
								</EmptyModal>
							),
						});
						return;
					}
				}
				showGlobalModal({
					children: <WarningModal text={result.error.data.title} />,
				});
				return;
			}
			showGlobalModal({
				closeAfterDelay: 2000,
				children: <SuccessModal text="Order Created" />,
				whenClose() {
					dispatch(setCallRiderState(callRiderInititalState));
					navigation.dispatch(
						StackActions.replace('AppCompanyStack', {
							screen: 'CompanyHome',
						}),
					);
				},
			});
		} catch {}
	};

	return (
		<KeyboardAwareScrollView style={{ flex: 1 }} contentContainerStyle={{ flex: 1 }}>
			<View style={{ flex: 1, marginVertical: PADDING.large }}>
				<View style={{ paddingHorizontal: PADDING.large }}>
					<View style={{ flexDirection: 'row', columnGap: PADDING.mini }}>
						<PalRiderText style={globalStyles.titleTextStyle}>Select Bonus Type</PalRiderText>
					</View>

					<Dropdown
						{...globalStyles.dropdownProps}
						options={[
							{ value: 'none', label: 'None' },
							{ value: 'by_distance', label: 'By Distance' },
							{ value: 'per_shipment', label: 'Per Shipment' },
						]}
						isSearchable
						isMultiple={false}
						selectedValue={selectedBonusType as string}
						onValueChange={(value) => setSelectedBonusType(value as any)}
					/>
				</View>
				{selectedBonusType != 'none' && (
					<Formik
						innerRef={formikRef}
						initialValues={initialValues}
						validationSchema={validationSchema}
						validateOnChange={true}
						validateOnBlur={true}
						enableReinitialize
						onSubmit={(values) => {
							handleCallRider(values);
						}}
					>
						{({ values, setFieldValue, errors, handleBlur }) => (
							<View style={{ padding: PADDING.large }}>
								<FieldArray name="fields">
									{({ push, remove }) => (
										<>
											{values.fields.map((_, index: number) => (
												<View key={index}>
													{!isEmptyJson(errors) && (
														<View
															style={[
																{
																	padding: errors.fields && errors.fields !== undefined ? PADDING.mini : 0,
																},
															]}
														>
															{typeof errors.fields === 'string' && errors.fields != '' && (
																<ErrorMessage
																	name={`fields`}
																	render={(error) => (
																		<PalRiderText fontFamily={FontFamily.Semibold} color={colors.red[600]}>
																			&#183;&nbsp;{error}
																		</PalRiderText>
																	)}
																/>
															)}
															<ErrorMessage
																name={`fields[${index}].min`}
																render={(error) => (
																	<PalRiderText fontFamily={FontFamily.Semibold} color={colors.red[600]}>
																		&#183;&nbsp;{error}
																	</PalRiderText>
																)}
															/>
															<ErrorMessage
																name={`fields[${index}].max`}
																render={(error) => (
																	<PalRiderText fontFamily={FontFamily.Semibold} color={colors.red[600]}>
																		&#183;&nbsp;{error}
																	</PalRiderText>
																)}
															/>

															<ErrorMessage
																name={`fields[${index}].price`}
																render={(error) => (
																	<PalRiderText fontFamily={FontFamily.Semibold} color={colors.red[600]}>
																		&#183;&nbsp;{error}
																	</PalRiderText>
																)}
															/>
														</View>
													)}

													<View style={styles.bonusContainer}>
														<PalRiderText style={styles.bonusText}>
															{selectedBonusType == 'by_distance' ? 'Mile' : 'Shipment'}
														</PalRiderText>
														<PalRiderTextInput
															inputStyle={styles.bonusInputStyle}
															placeholder="0"
															keyboardType="numeric"
															onChangeText={(text) => setFieldValue(`fields[${index}].min`, text)}
															onBlur={handleBlur(`fields[${index}].min`)}
														/>
														<PalRiderText style={styles.bonusText}>To</PalRiderText>
														<PalRiderTextInput
															inputStyle={styles.bonusInputStyle}
															placeholder="0"
															keyboardType="numeric"
															value={
																index === values.fields.length - 1
																	? values.fields[index]?.max !== undefined && values.fields[index]?.max !== null
																		? String(values.fields[index].max) + (isFocusedIndex === index ? '' : '+')
																		: ''
																	: values.fields[index]?.max != null
																		? String(values.fields[index].max)
																		: ''
															}
															onFocus={() => setIsFocusedIndex(index)}
															onBlur={() => {
																setIsFocusedIndex(null);
																handleBlur(`fields[${index}].max`);
															}}
															onChangeText={(text) => {
																// Always strip "+" and store numeric
																const cleaned = text.replace('+', '');
																setFieldValue(`fields[${index}].max`, cleaned);
															}}
														/>

														<PalRiderCurrencyInput
															containerStyle={{ flex: 1 }}
															inputStyle={styles.bonusInputStyle}
															currencyValue={values.fields[index]?.price ?? 0}
															onChangeCurrencyText={(text) => {
																const formattedText = text.replace(/[^0-9.]/g, '');
																if (formattedText) {
																	const decimalCount = formattedText.split('.').length - 1;
																	if (decimalCount <= 1) {
																		setFieldValue(`fields[${index}].price`, formattedText, true);
																	}
																}
															}}
															onBlur={handleBlur(`fields[${index}].price`)}
														/>
														<TouchableOpacity
															onPress={() => {
																remove(index);

																// Reindex sorts after removing
																const updatedFields = values.fields
																	.filter((_, i) => i !== index)
																	.map((f, i) => ({
																		...f,
																		sort: i + 1,
																	}));
																setFieldValue('fields', updatedFields);
															}}
														>
															<Icon name="CloseIconSvg" color={colors.red[600]} />
														</TouchableOpacity>
													</View>
												</View>
											))}
											{values.fields.length < 5 && (
												<View style={{ marginVertical: PADDING.large }}>
													<PalRiderButton
														style={[buttonStyling.success]}
														onPress={() => handleAddField(push, values.fields)}
													>
														<PalRiderText color={colors.white} fontFamily={FontFamily.Semibold}>
															Add Bonus
														</PalRiderText>
													</PalRiderButton>
												</View>
											)}
										</>
									)}
								</FieldArray>
							</View>
						)}
					</Formik>
				)}
			</View>
			<View
				style={{
					padding: PADDING.large,
					paddingBottom: PADDING.large,
					flexDirection: 'row',
					gap: PADDING.small,
				}}
			>
				<PalRiderButton style={[buttonStyling.dark, { flex: 1 }]} onPress={() => prevStep()}>
					<PalRiderText color="white">{t('common.go_back')}</PalRiderText>
				</PalRiderButton>
				<PalRiderButton
					style={[buttonStyling.dark, { flex: 1 }]}
					onPress={() => {
						if (selectedBonusType != 'none') {
							formikRef.current?.handleSubmit();
							return;
						}
						handleCallRider();
						return;
					}}
				>
					<PalRiderText color="white">{t('common.callrider')}</PalRiderText>
				</PalRiderButton>
			</View>
		</KeyboardAwareScrollView>
	);
};

const styles = StyleSheet.create({
	tabContentContainer: {},
	bonusInputStyle: {
		minWidth: PADDING.xxlarge * 2,
		textAlign: 'center',
		backgroundColor: colors.white,
	},
	bonusText: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.mini,
	},
	bonusContainer: {
		backgroundColor: colors.gray[100],
		flexDirection: 'row',
		alignItems: 'center',
		gap: PADDING.medium,
		padding: PADDING.large,
		borderBottomLeftRadius: 0,
		borderBottomRightRadius: 0,
	},
	bonusAddButton: {
		height: PADDING.xxlarge,
		justifyContent: 'center',
		alignItems: 'center',
		backgroundColor: colors.gray[200],
		borderTopWidth: 1,
		borderTopColor: colors.gray[300],
		borderBottomLeftRadius: PADDING.medium,
		borderBottomRightRadius: PADDING.medium,
	},
});
export default CallRiderBonusInfo;
