import React from 'react';
import { TextStyle, View } from 'react-native';
import PalRiderText from '../PalRiderText';
import { FontFamily } from '@/theme/fonts';
import colors from '@/theme/colors';
import { CloseIconSvg } from '@/assets/svg/ui';
type WarningModalProps = {
	title?: string;
	text?: string;
	width?: number;
	height?: number;
	icon?: React.ReactNode;
	textStyle?: TextStyle;
};
const WarningModal: React.FC<WarningModalProps> = (props) => {
	return (
		<View
			style={{
				height: props.height ?? 'auto',
				width: props.width ?? 'auto',
				justifyContent: 'center',
				alignItems: 'center',
			}}
		>
			{(props.icon && props.icon) || <CloseIconSvg width={64} height={64} color={colors.red[600]} />}
			<PalRiderText
				style={[{ textAlign: 'center', flexWrap: 'wrap' }, props.textStyle]}
				fontFamily={FontFamily.Semibold}
			>
				{props.text}
			</PalRiderText>
		</View>
	);
};

export default WarningModal;
