import { createApi } from '@reduxjs/toolkit/query/react';
import { PaginationDataResultT, SuccessfulResponse } from 'palriderapptypes';
import { CompanyAreaAddressDocumentDTO, CreateCompanyAreaAddressDocumentRequestDTO } from 'palriderapptypes/company';
import { baseQueryConfigWithReAuth } from 'src/services/api/baseQueryConfig.ts';

export const companyAreaAddressDocumentApi = createApi({
	reducerPath: 'companyAreaAddressDocument',
	baseQuery: baseQueryConfigWithReAuth,
	refetchOnMountOrArgChange: 30,
	endpoints: (builder) => ({
		getCompanyAreaAddressDocumentLink: builder.query<Blob, string>({
			query(company_area_address_document_id) {
				return {
					url: `company-area-address-document/${company_area_address_document_id}/link`,
					method: 'GET',
					headers: {
						'x-response-type': 'blob',
					},
					responseHandler: async (response) => {
						const blob = await response.blob();
						const contentType = response.headers.get('Content-Type') || 'application/octet-stream';
						const typedBlob = new Blob([blob], { type: contentType, lastModified: 0 });
						return typedBlob;
					},
				};
			},
		}),
		storeCompanyAreaAddressDocument: builder.mutation<SuccessfulResponse, CreateCompanyAreaAddressDocumentRequestDTO>({
			query(body) {
				const formData = new FormData();
				body.documents.forEach((document) => {
					formData.append('documents', document);
				});
				return {
					url: `company-area-address/${body.company_area_address_id}/create-document`,
					method: 'POST',
					headers: {
						'Content-Type': 'multipart/form-data',
					},
					body: formData,
				};
			},
		}),
		deleteCompanyAreaAddressDocument: builder.query<SuccessfulResponse, string>({
			query(company_area_document_id) {
				return {
					url: `company-area-address-document/${company_area_document_id}`,
					method: 'DELETE',
				};
			},
		}),
	}),
});

export const {
	useLazyGetCompanyAreaAddressDocumentLinkQuery,
	useStoreCompanyAreaAddressDocumentMutation,
	useLazyDeleteCompanyAreaAddressDocumentQuery,
} = companyAreaAddressDocumentApi;
