import { PayloadAction } from '@reduxjs/toolkit';
import * as yup from 'yup';
import { object } from 'yup';

export type ConditionalSchema<T> = T extends string
	? yup.StringSchema
	: T extends number
		? yup.NumberSchema
		: T extends boolean
			? yup.BooleanSchema
			: T extends object
				? yup.ObjectSchema<undefined>
				: T extends undefined[]
					? yup.ArraySchema<undefined, undefined>
					: yup.AnySchema;
export type Shape<Fields> = {
	[Key in keyof Fields]: ConditionalSchema<Fields[Key]>;
};
export const yupTyped = <T>(obj: Partial<Record<keyof T, yup.AnySchema>>) => {
	return object().shape(obj as Record<string, yup.AnySchema>);
};
export interface ErrorResponse {
	type: string;
	title: string;
	status: number;
}

// Transformed error type
export interface TransformedError {
	errorType: string;
	errorMessage: string;
	statusCode: number;
}
export type RejectedAction = PayloadAction<
	{ error: ErrorResponse }, // Payload structure
	string // Action type (e.g., 'someSlice/action/rejected')
>;
