import { FileType } from '@/@types';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import WarningModal from '@/components/custom-modal/WarningModal';
import Icon from '@/components/Icon';
import { useModal } from '@/components/ModalProvider';
import PalRiderBottomSelectModal from '@/components/PalRiderBottomSelectModal';
import PalRiderSwipeButton from '@/components/PalRiderSwipeButton';
import PalRiderText from '@/components/PalRiderText';
import PalRiderTextInput from '@/components/PalRiderTextInput';
import { useDeliverOrderShipmentDestinationMutation } from '@/services/api/order/shipment';
import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { font, PADDING } from '@/theme/responsive';
import { isFetchBaseQueryError, requestLocationPermission } from '@/utils';
import { BottomSheetModal, BottomSheetView } from '@gorhom/bottom-sheet';
import Geolocation from '@react-native-community/geolocation';
import { OrderShipmentDTO } from 'palriderapptypes/order';
import React, { forwardRef, useCallback, useImperativeHandle, useRef, useState } from 'react';
import { Image, Platform, Pressable, StyleSheet, View } from 'react-native';
import { launchCamera, launchImageLibrary } from 'react-native-image-picker';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

// Define props for your modal
type ActiveOrderShipmentDestinationDeliveryCompleteModalProps = {
	navigation: any;
};

// Define the ref methods that will be exposed
export type ActiveOrderShipmentDestinationDeliveryCompleteModalRef = {
	openModal: (orderShipment: OrderShipmentDTO) => void;
	closeModal: () => void;
};

const ActiveOrderShipmentDestinationDeliveryCompleteModal = forwardRef<
	ActiveOrderShipmentDestinationDeliveryCompleteModalRef,
	ActiveOrderShipmentDestinationDeliveryCompleteModalProps
>(({ navigation }, ref) => {
	const insets = useSafeAreaInsets();
	const [orderShipment, setOrderShipment] = useState<OrderShipmentDTO | null>(null);
	const { showGlobalModal, hideGlobalModal } = useModal();
	const [deliveryNote, setDeliveryNote] = useState('');
	const [deliverOrderShipmentDestination] = useDeliverOrderShipmentDestinationMutation();
	const [deliveryImageSelectModalVisible, setDeliveryImageSelectModalVisible] = useState(false);
	const [deliveryImages, setDeliveryImages] = useState<Array<FileType>>([]);

	// Create a ref for the BottomSheetModal
	const bottomSheetRef = useRef<BottomSheetModal>(null);

	const handleOrderShipmentDestinationDelivery = async () => {
		if (deliveryImages.length == 0) {
			showGlobalModal({
				children: <WarningModal text="At least one delivery image required" />,
			});
			return;
		}
		if (orderShipment) {
			hideGlobalModal();
			showGlobalModal({
				maxHeight: 200,
				backgroundColor: colors.transparent,
				children: <LoadingModal />,
			});
			try {
				const requestAccess = await requestLocationPermission();
				if (!requestAccess) {
					showGlobalModal({
						children: (
							<WarningModal
								icon={<Icon name="LocationNotGrantedIconSvg" width={128} height={128} color={colors.red[600]} />}
								text="If you want to deliver this order shipment must grant location for application."
							/>
						),
					});
					return;
				}
				Geolocation.getCurrentPosition(
					async (position) => {
						const res = await deliverOrderShipmentDestination({
							notes: deliveryNote,
							order_shipment_destination_id: orderShipment.current_order_shipment_destination_id!,
							order_shipment_id: orderShipment.id,
							order_id: orderShipment.order_id,
							order_shipment_destination_delivery_photos: deliveryImages,
							latitude: position.coords.latitude,
							longitude: position.coords.longitude,
						});
						if (res.error && isFetchBaseQueryError(res.error)) {
							showGlobalModal({
								children: (
									<WarningModal
										icon={<Icon name="WarningIconSvg" color={colors.orange[600]} width={50} height={50} />}
										text={res.error.data.title}
									/>
								),
							});
						}

						if (res.error && isFetchBaseQueryError(res.error)) {
							hideGlobalModal();
							showGlobalModal({
								maxHeight: 200,
								children: <WarningModal text={res.error.data.title ?? ''} />,
							});
						} else {
							hideGlobalModal();
							showGlobalModal({
								maxHeight: 200,
								children: <SuccessModal text="Shipment delivered" />,
								closeAfterDelay: 2000,
								whenClose() {
									navigation.replace('Splash');
								},
							});
						}
					},
					(geoError) => {
						showGlobalModal({
							children: <WarningModal text={geoError.message} />,
						});
					},
					{
						timeout: 15000,
					},
				);
			} catch (err) {
				hideGlobalModal();
				showGlobalModal({
					maxHeight: 200,
					children: <WarningModal text="Shipment cannot delivered" />,
				});
			}
		}
	};
	const handleRemoveDeliveryImage = (index: number) => {
		const cloned = [...deliveryImages];
		setDeliveryImages(cloned.filter((_, indexFilter) => index != indexFilter));
	};
	const renderDeliveryImages = useCallback(() => {
		if (deliveryImages.length > 0) {
			return deliveryImages.map((image, index) => (
				<View style={{ width: 100, height: 100, position: 'relative' }}>
					<Pressable
						style={{
							width: 25,
							height: 25,
							backgroundColor: colors.black,
							position: 'absolute',
							top: 5,
							right: 5,
							zIndex: 999,
							borderRadius: PADDING.large,
							justifyContent: 'center',
							alignItems: 'center',
						}}
						onPress={() => handleRemoveDeliveryImage(index)}
					>
						<Icon name="CloseIconSvg" color={colors.white} width={20} height={20} />
					</Pressable>
					<Image source={{ uri: image.uri }} width={100} height={100} />
				</View>
			));
		}
	}, [deliveryImages]);

	// Expose the modal methods using `useImperativeHandle`
	useImperativeHandle(ref, () => ({
		openModal: (orderShipmentVal: OrderShipmentDTO) => {
			bottomSheetRef.current?.present();
			setOrderShipment(orderShipmentVal);
		},
		closeModal: () => {
			bottomSheetRef.current?.dismiss();
			setOrderShipment(null);
		},
	}));

	return (
		<View>
			<PalRiderBottomSelectModal
				key={'delivery_picture'}
				data={[
					{
						text: 'Pick From Library',
						async onPress() {
							showGlobalModal({
								children: <LoadingModal />,
								backgroundColor: colors.transparent,
							});
							const res = await launchImageLibrary({
								mediaType: 'photo',
								includeExtra: true,
								selectionLimit: 1,
							});
							hideGlobalModal();
							if (res.didCancel || res.errorCode || !res.assets || !res.assets[0]) {
								return;
							}
							const file = res.assets[0];
							setDeliveryImages((prev) => [
								...prev,
								{
									name: file.fileName,
									size: file.fileSize,
									type: file.type,
									uri: file.uri,
								} as FileType,
							]);
							setDeliveryImageSelectModalVisible(false);
						},
					},
					{
						text: 'Take A Photo',
						async onPress() {
							try {
								const res = await launchCamera({
									mediaType: 'photo',
									includeExtra: true,
									presentationStyle: 'overCurrentContext',
									quality: 1,
									saveToPhotos: true,
								});
								if (res.didCancel || res.errorCode || !res.assets || !res.assets[0]) {
									return;
								}
								const file = res.assets[0];
								setDeliveryImages((prev) => [
									...prev,
									{
										name: file.fileName,
										size: file.fileSize,
										type: file.type,
										uri: file.uri,
									} as FileType,
								]);
								setDeliveryImageSelectModalVisible(false);
							} catch (e) {
								console.error(e);
							}
						},
					},
				]}
				isVisible={deliveryImageSelectModalVisible}
				title="Select"
				cancelOnPress={() => setDeliveryImageSelectModalVisible(false)}
				isCoverScreen
			/>
			<BottomSheetModal ref={bottomSheetRef} enableDynamicSizing>
				<BottomSheetView
					style={{ padding: PADDING.large, paddingBottom: Platform.OS === 'ios' ? insets.bottom : insets.bottom + 20 }}
				>
					<View style={{ gap: PADDING.large }}>
						<PalRiderTextInput
							title="Notes"
							numberOfLines={5}
							inputStyle={{ minHeight: 80 }}
							multiline
							maxLength={255}
							onChangeText={(text) => setDeliveryNote(text)}
						/>
						<PalRiderText fontSize={font.mini} fontFamily={FontFamily.Semibold}>
							Delivery Images (Required if when delivery completing)
						</PalRiderText>
						<View style={styles.addImageContainer}>{renderDeliveryImages()}</View>
						<View style={styles.addImageContainer}>
							<Pressable style={styles.addImageButton} onPress={() => setDeliveryImageSelectModalVisible(true)}>
								<Icon name="PlusIconSvg" color={colors.gray[600]} />
							</Pressable>
						</View>
						<PalRiderSwipeButton
							swipeText="Complete"
							swipedText="Shipment Complete"
							button={
								<Pressable>
									<Icon name="ChevronRightIconSvg" color={colors.white} width={20} height={20} />
								</Pressable>
							}
							onSwipe={() => handleOrderShipmentDestinationDelivery()}
						/>
					</View>
				</BottomSheetView>
			</BottomSheetModal>
		</View>
	);
});

const styles = StyleSheet.create({
	addImageContainer: {
		flexDirection: 'row',
		columnGap: PADDING.medium,
	},
	addImageButton: {
		width: PADDING.xxlarge * 3,
		height: PADDING.xxlarge * 3,
		borderWidth: 1,
		borderColor: colors.gray[300],
		borderRadius: PADDING.large,
		justifyContent: 'center',
		alignItems: 'center',
	},
});
export default ActiveOrderShipmentDestinationDeliveryCompleteModal;
