import React from 'react';
import PalRiderButton from '@/components/PalRiderButton';
import PalRiderText from '@/components/PalRiderText';
import { useLazyAbondonOrderQuery, useLazyArriveOrderQuery, useLazyGetOrderQuery } from '@/services/api/order';
import colors from '@/theme/colors';
import { buttonStyling } from '@/theme/defaults';
import { FontFamily } from '@/theme/fonts';
import { font, PADDING } from '@/theme/responsive';
import { requestLocationPermission, UKCenterMap } from '@/utils';
import Geolocation from '@react-native-community/geolocation';
import { useEffect, useRef, useState } from 'react';
import { ActivityIndicator, Linking, Platform, StyleSheet, View } from 'react-native';
import MapView, { LatLng, Marker, Polyline } from 'react-native-maps';
import PalRiderSwipeButton from '@/components/PalRiderSwipeButton';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import BottomSheet, { BottomSheetView } from '@gorhom/bottom-sheet';
import { useAppDispatch, useAppSelector } from '@/redux/hooks';
import { CompositeScreenProps, StackActions } from '@react-navigation/native';
import { useModal } from '@/components/ModalProvider';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import WarningModal from '@/components/custom-modal/WarningModal';
import { Pressable } from 'react-native-gesture-handler';
import { OrderDTO } from 'palriderapptypes/order';
import { AppOrderStackParamList } from '@/navigation/order-navigation';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { RootStackParamList } from '@/navigation';
import useUserNavigation from '@/hooks/useUserNavigation';
import { setToken } from '@/redux/slices/userSlice';
import AsyncStorage from '@react-native-async-storage/async-storage';
import Icon from '@/components/Icon';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppOrderStackParamList, 'OrderArriving'>,
	CompositeScreenProps<NativeStackScreenProps<AppOrderStackParamList>, NativeStackScreenProps<RootStackParamList>>
>;
const AppOrderArrivingScreen: React.FC<Props> = ({ route, navigation }) => {
	const [order, setOrder] = useState<OrderDTO | null>(null);
	const [getOrder, { isLoading, isFetching }] = useLazyGetOrderQuery();
	const [abondonOrder] = useLazyAbondonOrderQuery();
	const [handleArriveOrder] = useLazyArriveOrderQuery();
	const [currentLocation, setCurrentLocation] = useState<LatLng | null>(null);
	const courierSelector = useAppSelector((x) => x.userSlice.user?.courier);
	const mapRef = useRef<MapView>(null);
	const { showGlobalModal, hideGlobalModal } = useModal();
	const dispatch = useAppDispatch();
	const { handle: hanldeLogoutNavigation } = useUserNavigation();

	const handleLogout = async () => {
		dispatch(setToken(null));
		await AsyncStorage.removeItem('token');
		await hanldeLogoutNavigation();
	};

	const bottomSheetModalRef = useRef<BottomSheet>(null);
	const insets = useSafeAreaInsets();
	useEffect(() => {
		getOrder(route.params.order_id)
			.unwrap()
			.then((res) => setOrder(res.data))
			.catch((err) => console.log(err));
	}, []);
	useEffect(() => {
		(async () => {
			const requestAccess = await requestLocationPermission();
			if (!requestAccess) {
				showGlobalModal({
					maxHeight: 200,
					children: (
						<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', gap: PADDING.xlarge }}>
							<Icon name="LocationNotGrantedIconSvg" width={128} height={128} color={colors.red[600]} />
							<PalRiderText style={{ textAlign: 'center' }}>
								If you want arrive this location plase open location and grant permission.
							</PalRiderText>
						</View>
					),
				});
				return;
			}

			Geolocation.getCurrentPosition(
				(position) => {
					setCurrentLocation({
						latitude: position.coords.latitude,
						longitude: position.coords.longitude,
					});
				},
				(error) => {
					console.log(error.message);
				},
				{ enableHighAccuracy: true, timeout: 15000, maximumAge: 10000 },
			);
		})();
	}, []);
	const handleArrive = async () => {
		showGlobalModal({
			maxHeight: 200,
			children: (
				<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', gap: PADDING.large }}>
					<Icon name="CheckIconSvg" width={32} height={32} />
					<PalRiderText>Arriving to order please wait...</PalRiderText>
				</View>
			),
		});
		handleArriveOrder({
			order_id: route.params.order_id,
			courier_id: courierSelector?.id ?? '',
		})
			.unwrap()
			.then(() => {
				hideGlobalModal();

				showGlobalModal({
					maxHeight: 200,
					children: <SuccessModal text="Successfuly Arrived To Order" />,
					closeAfterDelay: 1500,
					whenClose() {
						navigation.replace('AppOrderStack', {
							screen: 'OrderArriveWaiting',
							params: {
								order_id: route.params.order_id,
							},
						});
					},
				});
			})
			.catch(() => {
				hideGlobalModal();
				showGlobalModal({
					children: <WarningModal text="Cannot arriving to plase try again later" />,
				});
			});
	};
	const handleGooglePress = () => {
		const { latitude, longitude, address } = order!.company_area_address!;
		const url = Platform.select({
			ios: `maps:${latitude},${longitude}?q=${address}`,
			android: `geo:${latitude},${longitude}?q=${address}`,
		});
		if (url) Linking.openURL(url);
	};
	const handleYandexPress = () => {
		const { latitude, longitude, address } = order!.company_area_address!;
		const url = Platform.select({
			ios: `maps:${latitude},${longitude}?q=${address}`,
			android: `geo:${latitude},${longitude}?q=${address}`,
		});
		if (url) Linking.openURL(url);
	};

	const handleAbondon = () => {
		if (order) {
			showGlobalModal({
				maxHeight: 200,
				children: (
					<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', gap: PADDING.large }}>
						<Icon name="CheckIconSvg" width={32} height={32} />
						<PalRiderText>Order abondoning plase wait...</PalRiderText>
					</View>
				),
			});
			abondonOrder(order.id)
				.unwrap()
				.then(() => {
					setTimeout(() => {
						hideGlobalModal();
						navigation.navigate('AppCourierStack', {
							screen: 'CourierHome',
						});
					}, 2000);
				})
				.catch(() => {
					hideGlobalModal();
					showGlobalModal({
						children: <WarningModal text="Order cannot abondoning please try again" />,
					});
				});
		}
	};

	return (
		<View style={styles.container}>
			{(isLoading || isFetching) && (
				<View style={styles.loadingContainer}>
					<ActivityIndicator size="large" color={colors.black} />
				</View>
			)}
			{order && (
				<>
					<MapView
						ref={mapRef}
						userInterfaceStyle="light"
						provider="google"
						style={StyleSheet.absoluteFillObject}
						onMapLoaded={() => {
							if (order != null && currentLocation != null && mapRef.current) {
								mapRef.current?.fitToCoordinates(
									[
										{
											latitude: order?.company_area_address?.latitude ?? 0,
											longitude: order?.company_area_address?.longitude ?? 0,
										},
										{
											latitude: currentLocation?.latitude,
											longitude: currentLocation?.longitude,
										},
									],
									{
										animated: true,
										edgePadding: {
											left: 120,
											bottom: 120,
											right: 120,
											top: 120,
										},
									},
								);
							}
						}}
						region={UKCenterMap}
					>
						<Marker
							coordinate={{
								latitude: currentLocation?.latitude ?? 0,
								longitude: currentLocation?.longitude ?? 0,
							}}
						>
							<Icon name="LocationIconSvg" />
						</Marker>
						<Marker
							coordinate={{
								latitude: order.company_area_address?.latitude ?? 0,
								longitude: order.company_area_address?.longitude ?? 0,
							}}
						>
							<Icon name="CompanyIconSvg" />
						</Marker>
					</MapView>
					<BottomSheet
						ref={bottomSheetModalRef}
						enableDynamicSizing
						enablePanDownToClose={false}
						handleComponent={null}
					>
						<BottomSheetView style={{ flex: 1, paddingHorizontal: PADDING.small, paddingBottom: insets.bottom }}>
							<View style={styles.container}>
								<View
									style={{
										flexDirection: 'row',
										justifyContent: 'center',
										alignItems: 'center',
										gap: PADDING.small,
										paddingHorizontal: PADDING.large,
									}}
								>
									<Icon name="LocationIconSvg" width={24} height={24} />
									<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.mini} style={{ textAlign: 'center' }}>
										{order.company_area_address?.address}
									</PalRiderText>
								</View>
								<View style={styles.openWithContainer}>
									<PalRiderButton style={styles.openWithItemContainer} onPress={handleGooglePress}>
										<PalRiderText fontSize={font.mini}>Open with</PalRiderText>
										<Icon name="GoogleMapsIconSvg" width={24} height={24} />
									</PalRiderButton>
									<PalRiderButton style={styles.openWithItemContainer} onPress={handleYandexPress}>
										<PalRiderText fontSize={font.mini}>Open with</PalRiderText>
										<Icon name="YandexIconSvg" width={24} height={24} color={colors.orange[600]} />
									</PalRiderButton>
								</View>
								<View style={styles.bottomSheetContainerInner}>
									<PalRiderSwipeButton
										swipeText="Swipe for when arrived"
										swipedText="I'm arrived location"
										button={
											<Pressable>
												<Icon name="ChevronRightIconSvg" color={colors.white} width={20} height={20} />
											</Pressable>
										}
										onSwipe={handleArrive}
									/>
									<PalRiderButton style={[buttonStyling.error]} onPress={handleAbondon}>
										<PalRiderText color={colors.white} fontFamily={FontFamily.Semibold}>
											Abondon Order
										</PalRiderText>
									</PalRiderButton>

									<PalRiderButton variant="warning" onPress={handleLogout}>
										<PalRiderText color={colors.white} fontFamily={FontFamily.Semibold}>
											Logout
										</PalRiderText>
									</PalRiderButton>
								</View>
							</View>
						</BottomSheetView>
					</BottomSheet>
				</>
			)}
		</View>
	);
};
const styles = StyleSheet.create({
	container: {
		flex: 1,
		padding: PADDING.large,
	},
	bottomSheetContainerInner: {
		flex: 1,
		gap: PADDING.large,
	},
	openWithContainer: {
		flexDirection: 'row',
		gap: PADDING.small,
		marginVertical: PADDING.large,
		justifyContent: 'center',
	},
	openWithItemContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		justifyContent: 'center',
		padding: PADDING.medium,
		paddingHorizontal: PADDING.xlarge,
		gap: PADDING.large,
		backgroundColor: colors.gray[200],
		borderRadius: PADDING.large,
	},
	loadingContainer: {
		padding: PADDING.large,
		flex: 1,
		borderRadius: PADDING.large,
		gap: PADDING.large,
		justifyContent: 'center',
		alignItems: 'center',
	},
});
export default AppOrderArrivingScreen;
