import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import {
	OnboardCourierRequestDTO,
	OnboardingCourierDocumentInfoRequestDTO,
	OnboardingCourierUserRequestDTO,
	OnboardingCourierVehicleInfoRequestDTO,
} from 'palriderapptypes/courier';

type OnboardingCourierRequestSlice = Omit<OnboardCourierRequestDTO, 'user'> & {
	user: Omit<OnboardingCourierUserRequestDTO, 'user'> & {
		phone_number?: string;
	};
};
export const courierOnboardingInitialValues: OnboardingCourierRequestSlice = {
	user: {
		name: '',
		surname: '',
		birthday: '',
		phone_number: '',
	},
	documents: {
		profile_photo: null,
		identity_card_back: null,
		identity_card_front: null,
		driver_licence_back: null,
		driver_licence_front: null,
	},
	vehicles: [],
};

const courierOnboardingSlice = createSlice({
	name: 'courierOnboarding',
	initialState: courierOnboardingInitialValues,
	reducers: {
		setCourierInfoOnboardingState: (state, action: PayloadAction<OnboardingCourierRequestSlice['user']>) => {
			return {
				...state,
				user: { ...action.payload },
			};
		},
		setCourierDocumentOnboardingState: (state, action: PayloadAction<OnboardingCourierDocumentInfoRequestDTO>) => {
			return {
				...state,
				documents: { ...action.payload },
			};
		},
		setCourierVehicleOnboardingState: (state, action: PayloadAction<Array<OnboardingCourierVehicleInfoRequestDTO>>) => {
			return {
				...state,
				vehicles: [...action.payload],
			};
		},
		setCourierPhoneNumber: (state, action: PayloadAction<string>) => {
			return {
				...state,
				user: {
					...state.user,
					phone_number: action.payload,
				},
			};
		},
	},
});
export const {
	setCourierInfoOnboardingState,
	setCourierVehicleOnboardingState,
	setCourierDocumentOnboardingState,
	setCourierPhoneNumber,
} = courierOnboardingSlice.actions;
export default courierOnboardingSlice.reducer;
