import React from 'react';
import { Image, StyleSheet, View } from 'react-native';
import { font, PADDING } from '@/theme/responsive.ts';
import PalRiderText from '@/components/PalRiderText.tsx';
import { FontFamily } from '@/theme/fonts.ts';
import { isFetchBaseQueryError, metersToMiles, snakeToHumanReadable } from '@/utils';
import PalRiderStarRating from '@/components/PalRiderStarRating.tsx';
import PalRiderButton from '@/components/PalRiderButton.tsx';
import colors from '@/theme/colors.ts';
import { BottomSheetFlatList } from '@gorhom/bottom-sheet';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { useLazyAcceptAttendeeQuery } from '@/services/api/order';
import { useModal } from '@/components/ModalProvider';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import WarningModal from '@/components/custom-modal/WarningModal';
import { OrderCourierAttendeeDTO } from 'palriderapptypes/order';
import { useTranslation } from 'react-i18next';
import Icon from '@/components/Icon';

type Props = {
	attendees: Array<OrderCourierAttendeeDTO>;
	order_id?: string;
	courierActionHandle: () => void;
};

const CompanyOrderCourierAttendeeTabList: React.FC<Props> = ({ attendees, order_id, courierActionHandle }) => {
	const { t } = useTranslation();
	const insets = useSafeAreaInsets();
	const [acceptCourier] = useLazyAcceptAttendeeQuery();
	const { showGlobalModal } = useModal();
	const handleAcceptOrder = async (attendee: OrderCourierAttendeeDTO) => {
		const res = await acceptCourier({
			order_id: order_id ?? '',
			courier_id: attendee.courier_id,
		});
		if (res.error && isFetchBaseQueryError(res.error)) {
			showGlobalModal({
				children: (
					<WarningModal
						icon={<Icon name="CloseIconSvg" width={32} height={32} color={colors.red[600]} />}
						text={res.error.data.title}
					/>
				),
				closeAfterDelay: 1500,
			});
			return;
		}
		showGlobalModal({
			children: <SuccessModal text={res.data?.message} />,
			closeAfterDelay: 1000,
			whenClose() {
				courierActionHandle();
			},
		});
	};

	const handleStopWorking = () => {};

	if (attendees.length === 0) {
		return (
			<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', gap: PADDING.medium }}>
				<Icon name="ElectricBikeIconSvg" width={52} height={52} color={colors.gray[300]} />
				<PalRiderText fontFamily={FontFamily.Semibold} color={colors.gray[500]}>
					{t('screen.company.order_info.no_carrier_in_here')}
				</PalRiderText>
			</View>
		);
	}
	return (
		<BottomSheetFlatList
			style={{
				flex: 1,
			}}
			data={attendees}
			keyExtractor={(item) => item.id}
			contentInset={{ bottom: insets.bottom }}
			renderItem={({ item }) => (
				<View style={styles.attendeeContainer} key={item.id}>
					<View style={{ flexDirection: 'row', flex: 1, alignItems: 'center' }}>
						<View>
							<Image
								source={{
									uri: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQ4YreOWfDX3kK-QLAbAL4ufCPc84ol2MA8Xg&s',
									width: 50,
									height: 50,
								}}
							/>
						</View>
						<View
							style={{
								paddingLeft: PADDING.large,
								gap: PADDING.mini,
								flex: 1,
								flexDirection: 'column',
							}}
						>
							<PalRiderText fontFamily={FontFamily.Semibold} numberOfLines={1}>
								{item.name} {item.surname}
							</PalRiderText>
							<PalRiderText fontSize={font.mini} style={{ maxWidth: 180 }}>
								{snakeToHumanReadable(item.status)}
							</PalRiderText>
							<PalRiderText fontSize={font.mini}>
								{metersToMiles(item.distance).toFixed(2)} {t('common.km_away')}
							</PalRiderText>
							<PalRiderStarRating rating={4} />
						</View>
					</View>
					{item.status === 'waiting_for_company_approval' && (
						<View style={{ flexDirection: 'row', gap: PADDING.small }}>
							<PalRiderButton
								style={[
									styles.attendeeActionButton,
									{
										backgroundColor: colors.green[600],
									},
								]}
								onPress={() => handleAcceptOrder(item)}
							>
								<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.small} color={colors.white}>
									{t('common.accept')}
								</PalRiderText>
							</PalRiderButton>
							<PalRiderButton
								style={[
									styles.attendeeActionButton,
									{
										backgroundColor: colors.red[600],
									},
								]}
							>
								<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.small} color={colors.white}>
									{t('common.reject')}
								</PalRiderText>
							</PalRiderButton>
						</View>
					)}
					{item.status === 'working' && (
						<View style={{ flexDirection: 'row', gap: PADDING.small }}>
							<PalRiderButton
								style={[
									styles.attendeeActionButton,
									{
										backgroundColor: colors.red[600],
									},
								]}
								onPress={() => handleStopWorking()}
							>
								<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.small} color={colors.white}>
									{t('common.stop_working')}
								</PalRiderText>
							</PalRiderButton>
						</View>
					)}
				</View>
			)}
		/>
	);
};
const styles = StyleSheet.create({
	attendeeContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		padding: PADDING.large,
	},
	attendeeActionButton: {
		height: 30,
		justifyContent: 'center',
		alignItems: 'center',
		borderRadius: PADDING.small,
		padding: PADDING.small,
	},
});
export default CompanyOrderCourierAttendeeTabList;
