export const parseAuthPhoneNumber = (str: string | null | undefined): string => {
	if (!str) {
		return '';
	}
	const mobilePhone = str.slice(3, str.length);
	return formatStringByPattern(parse.phoneNonExtra.mask, mobilePhone);
};

export const parsePhoneNumber = (str: string | null | undefined): string => {
	if (!str) {
		return '';
	}
	return formatStringByPattern(parse.phone.mask, str);
};

export const checkCreditCardExpirationDate = (str: string) => {
	if (!str) {
		return false;
	}
	const unParseStr = str.replace(/[^0-9]/g, '');

	if (unParseStr.length < 4) {
		return false;
	}

	const nowYear = moment().get('year').toString();
	const nowMonth = moment().get('months').toString();

	if (Number(unParseStr?.slice(0, 2)) > 12) {
		return false;
	}
	if (Number(unParseStr?.slice(2, 4)) < Number(nowYear.slice(2, 4))) {
		return false;
	}
	if (
		Number(unParseStr?.slice(0, 2)) < Number(nowMonth) + 1 &&
		Number(unParseStr?.slice(2, 4)) <= Number(nowYear.slice(2, 4))
	) {
		return false;
	}

	return /^\d+$/.test(unParseStr);
};

export function snakeToHumanReadable(snakeCaseStr: string): string {
	return snakeCaseStr
		.split('_')
		.map((word) => word.charAt(0).toUpperCase() + word.slice(1))
		.join(' ');
}

export function formatHumanReadableDate(isoString: string): string {
	const date = new Date(isoString);
	const now = new Date();

	const isToday = date.toDateString() === now.toDateString();
	const yesterday = new Date();
	yesterday.setDate(now.getDate() - 1);
	const isYesterday = date.toDateString() === yesterday.toDateString();

	const options: Intl.DateTimeFormatOptions = { hour: '2-digit', minute: '2-digit' };
	const time = date.toLocaleTimeString('en-US', options);

	if (isToday) return `Today ${time}`;
	if (isYesterday) return `Yesterday ${time}`;

	const monthYear = date.toLocaleDateString('en-US', { year: 'numeric', month: 'short' });
	return `${monthYear}, ${time}`;
}

export const requestGalleryWithPermission = async (fileMaxSize: number) => {
	try {
		if (Platform.OS === 'android') {
			const deviceVersion = getSystemVersion();
			let granted = PermissionsAndroid.RESULTS.DENIED;
			if (deviceVersion >= '13') {
				granted = PermissionsAndroid.RESULTS.GRANTED;
			} else {
				granted = await PermissionsAndroid.request(PermissionsAndroid.PERMISSIONS.READ_EXTERNAL_STORAGE);
			}
			if (granted) {
				return pickImageFromGallery(fileMaxSize);
			}
		} else {
			return pickImageFromGallery(fileMaxSize);
		}
	} catch (error) {
		return null;
	}
};

function getFileExtension(uri: string) {
	const lastDotIndex = uri.lastIndexOf('.');
	if (lastDotIndex !== -1) {
		return uri.slice(lastDotIndex + 1);
	}
	return null; // or an appropriate default value
}

const pickImageFromGallery = async (FILE_MAX_SIZE = 99999999) => {
	try {
		const image = await ImageCropPicker.openPicker({
			// width: 300,
			// height: 400,
			// cropping: true,
			multiple: false,
			mediaType: 'photo',
		});

		if (image) {
			const pathCompressed = await Image.compress(image?.path, {
				maxWidth: 1500,
				maxHeight: 1000,
			});
			const imageCompressed = await RNFS.stat(pathCompressed);

			if (imageCompressed.size > FILE_MAX_SIZE) {
				Alert.alert('File Size Limit Exceeded', 'Please select a file up to 10 MB.');
			} else {
				return {
					name: image?.filename || `image_${Date.now()}.${getFileExtension(imageCompressed?.path)}`,
					type: image?.mime,
					uri: imageCompressed?.path,
					size: imageCompressed?.size,
				};
			}
		}
	} catch (error) {
		return null;
	}
};

