const pickDocument = async (FILE_MAX_SIZE = 999999999, multiSelection = false) => {
	try {
		const result = await DocumentPicker.pick({
			allowMultiSelection: multiSelection,
			type: [DocumentPicker.types.pdf],
			mode: 'import',
		});
		if (result) {
			for (let i = 0; i < result.length - 1; i++) {
				const { size } = result[i];
				if (size && size > FILE_MAX_SIZE) {
					Alert.alert('File Size Limit Exceeded', 'Please select a file up to 2 MB.');
					return null;
				}
			}

			return result;
		}
	} catch (err) {
		if (DocumentPicker.isErrorWithCode(err)) {
		} else {
		}
		return null;
	}
};

export const requestCameraWithPermission = async () => {
	try {
		const permissionType = Platform.OS === 'android' ? PERMISSIONS.ANDROID.CAMERA : PERMISSIONS.IOS.CAMERA;
		const cameraPermission = await check(permissionType);

		if (cameraPermission === RESULTS.GRANTED) {
			return pickImageFromCamera();
		}
		const cameraPermissionResult = await request(permissionType);

		if (cameraPermissionResult === RESULTS.GRANTED) {
			return pickImageFromCamera();
		}
	} catch (error) {
		return null;
	}
};
const pickImageFromCamera = async (FILE_MAX_SIZE = 999999999) => {
	try {
		const image = await ImageCropPicker.openCamera({
			// width: 300,
			// height: 400,
			cropping: true,
			multiple: false,
			mediaType: 'photo',
		});

		if (image) {
			const pathCompressed = await Image.compress(image?.path, {
				// compress image below 2mb
				maxWidth: 1500,
				maxHeight: 1000,
			});
			const imageCompressed = await RNFS.stat(pathCompressed);

			if (imageCompressed.size > FILE_MAX_SIZE) {
				Alert.alert('File Size Limit Exceeded', 'Please select a file up to 2 MB.');
			} else {
				// The picked document is available in the 'result' object

				return {
					name: image?.filename || `image_${Date.now()}.${getFileExtension(imageCompressed?.path)}`,
					type: image?.mime,
					uri: imageCompressed?.path,
					size: imageCompressed?.size,
				};
			}
		}
	} catch (error) {
		return null;
	}
};

