export function checkCardType(text: string) {
	for (const cardType in card_types) {
		if (card_types.hasOwnProperty(cardType)) {
			const regex = card_types[cardType];
			if (regex.test(text)) {
				return cardType;
			}
		}
	}
	return null;
}

