export function formatTime(time: number): string {
	const hours = Math.floor(time);
	const minutes = Math.round((time - hours) * 60); // Multiply by 60 instead of 100

	return [hours ? `${hours}h ` : '', minutes ? `${minutes}m` : ''].join('').trim() || '0m';
}
