export function metersToMiles(meters: number): number {
	if (typeof meters !== 'number' || isNaN(meters)) {
		return 0;
	}
	if (meters < 0) {
		return 0;
	}
	const metersInMile = 1609.34;
	return meters / metersInMile;
}

