export async function addressForCoordinate(
	address_components: {
		long_name: string;
		short_name: string;
		types: string[];
	}[],
) {
	const organizedAddress: {
		street: string | undefined;
		city: string | undefined;
		county: string | undefined;
		country: string | undefined;
		postcode: string | undefined;
	} = {
		street: undefined,
		country: undefined,
		postcode: undefined,
		county: undefined,
		city: undefined,
	};

	for (const component of address_components) {
		for (const addressType of component.types) {
			switch (addressType) {
				case 'route':
					organizedAddress.street = component.long_name;
					break;
				case 'postal_town':
					organizedAddress.city = component.long_name;
					break;
				case 'administrative_area_level_1':
				case 'administrative_area_level_2':
					organizedAddress.county = component.long_name;
					break;
				case 'country':
					organizedAddress.country = component.long_name;
					break;
				case 'postal_code':
					organizedAddress.postcode = component.long_name;
					break;
				default:
					break;
			}
		}
	}

	return organizedAddress;
}
