export async function showAnonymousBlob(blob: Blob): Promise<{ data: string; mimeType: string }> {
	const mimeType = blob.type || 'image/jpg';
	const ext = getExtensionFromMime(mimeType);
	const tempFileName = `tempfile_${Date.now()}.${ext}`;
	const path = `${RNFS.DocumentDirectoryPath}/${tempFileName}`;

	return Promise.resolve({
		data: await blobToBase64(blob),
		mimeType: mimeType,
	});
}

function getExtensionFromMime(mimeType: string): string {
	const map: Record<string, string> = {
		'application/pdf': 'pdf',
		'application/msword': 'doc',
		'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
		'application/vnd.ms-excel': 'xls',
		'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
		'text/plain': 'txt',
		'image/jpeg': 'jpg',
		'image/png': 'png',
		'application/zip': 'zip',
	};
	return map[mimeType] || 'bin';
}

// Helper: convert Blob to base64
function blobToBase64(blob: Blob): Promise<string> {
	return new Promise((resolve, reject) => {
		const reader = new FileReader();
		reader.onloadend = () => {
			const base64 = (reader.result as string).split(',')[1];
			resolve(base64);
		};
		reader.onerror = reject;
		reader.readAsDataURL(blob);
	});
}

export const uuidv4Gen = () =>
	'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
		const r = (Math.random() * 16) | 0;
		const v = c === 'x' ? r : (r & 0x3) | 0x8;
		return v.toString(16);
	});

