import colors from '@/theme/colors';
import React, { useCallback } from 'react';
import { View } from 'react-native';
import PalRiderWizard, { PalRiderWizardStep } from '@/components/PalRiderWizard.tsx';
import CallRiderLocationInfo from '@/screens/app/company/call-rider/components/call-rider-location-info';
import CallRiderPriceInfo from '@/screens/app/company/call-rider/components/call-rider-price-info';
import CallRiderBonusInfo from './components/call-rider-bonus-info';
import { CompositeScreenProps, useFocusEffect } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { AppCompanyOrderParamList, AppCompanyTabParamList } from '@/navigation/company-navigation';
import { RootStackParamList } from '@/navigation';
import { useTranslation } from 'react-i18next';
import Icon from '@/components/Icon';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyOrderParamList, 'CompanyCallRider'>,
	CompositeScreenProps<
		BottomTabScreenProps<AppCompanyTabParamList, 'CompanyOrderStack'>,
		NativeStackScreenProps<RootStackParamList>
	>
>;

const AppCompanyCallRiderScreen: React.FC<Props> = ({ navigation }) => {
	const { t } = useTranslation();

	useFocusEffect(
		useCallback(() => {
			navigation.getParent()?.setOptions({
				title: 'Call Rider',
				tabBarIcon: ({ focused }: any) => (
					<Icon name="MotorcycleIconSvg" width={20} height={20} color={focused ? colors.orange[600] : colors.black} />
				),
			});
		}, []),
	);
	return (
		<View
			style={{
				flex: 1,
				backgroundColor: colors.white,
			}}
		>
			<PalRiderWizard>
				<PalRiderWizardStep title={t('screen.company.callrider.step.locationrider')}>
					{({ nextStep }) => (
						<>
							<CallRiderLocationInfo nextStep={nextStep} />
						</>
					)}
				</PalRiderWizardStep>
				<PalRiderWizardStep title={t('common.price')}>
					{({ nextStep, prevStep }) => (
						<>
							<CallRiderPriceInfo nextStep={nextStep} prevStep={prevStep} />
						</>
					)}
				</PalRiderWizardStep>
				<PalRiderWizardStep title={t('common.bonuses')}>
					{({ prevStep }) => (
						<>
							<CallRiderBonusInfo prevStep={prevStep} navigation={navigation} />
						</>
					)}
				</PalRiderWizardStep>
			</PalRiderWizard>
		</View>
	);
};

export default AppCompanyCallRiderScreen;
