import React from 'react';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import { Platform } from 'react-native';
import { HomeIconSvg, ShippingBoxIconSvg } from '@/assets/svg/custom';
import { NotificationIconSvg, ProfileIconSvg } from '@/assets/svg/ui';
import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { font } from '@/theme/responsive';
import AppCourierHomeScreen from '@/screens/app/courier/home';
import AppCourierOrderScreen from '@/screens/app/courier/orders';
import AppCourierProfileScreen from '@/screens/app/courier/profile';
import AppCourierProfileBankAccountScreen from '@/screens/app/courier/profile/bank-account';
import AppCourierProfileBankAccountCreateScreen from '@/screens/app/courier/profile/bank-account/create';
import AppCourierProfileVehiclesHomeScreen from '@/screens/app/courier/profile/vehicles';
import AppCourierProfileVehicleCreateVehicleScreen from '@/screens/app/courier/profile/vehicles/create';
import AppCompanyProfileCourierDocumentsScreen from '@/screens/app/courier/profile/documents';
import AppCompanyProfileCourierDocumentAddScreen from '@/screens/app/courier/profile/documents/create';
import AppCourierProfileWalletScreen from '@/screens/app/courier/profile/wallet';
import AppCourierProfileWalletWithdrawScreen from '@/screens/app/courier/profile/wallet/withdraw';
import AppCourierProfileSettingsScreen from '@/screens/app/courier/profile/settings';
import { NavigatorScreenParams, useNavigation } from '@react-navigation/native';
import AppCourierProfileMyAccountScreen from '@/screens/app/courier/profile/my-account';
import AppCourierNotificationsScreen from '@/screens/app/courier/notifications';
import { useTranslation } from 'react-i18next';
import AppCourierProfileVehicleViewScreen from '@/screens/app/courier/profile/vehicles/view';
import { HeaderBackButton } from '@react-navigation/elements';

export type AppCourierVehiclesStackParamList = {
	CourierVehicles: undefined;
	CourierVehicleCreate: undefined;
};

export type AppCourierDocumentsStackParamList = {
	CourierDocuments: undefined;
	CourierDocumentCreate: { courier_id: string };
};

export type AppCourierProfileStackParamList = {
	CourierProfile: undefined;
	CourierMyAccount: undefined;
	CourierBankAccount: undefined;
	CourierCreateBankAccount: undefined;
	CourierVehiclesStack: NavigatorScreenParams<AppCourierVehiclesStackParamList>;
	CourierVehicleView: {
		courier_vehicle_id: string;
	};
	CourierDocumentsStack: NavigatorScreenParams<AppCourierDocumentsStackParamList>;
	CourierWallet: undefined;
	CourierWalletWithdraw: undefined;
	CourierSettings: undefined;
};

export type AppCourierTabParamList = {
	CourierHome: undefined;
	CourierOrder: undefined;
	CourierNotifications: undefined;
	CourierProfileStack: NavigatorScreenParams<AppCourierProfileStackParamList>;
};
const VehiclesStack = createNativeStackNavigator<AppCourierVehiclesStackParamList>();
const DocumentsStack = createNativeStackNavigator<AppCourierDocumentsStackParamList>();
const ProfileStack = createNativeStackNavigator<AppCourierProfileStackParamList>();
const Tab = createBottomTabNavigator<AppCourierTabParamList>();

export const AppCourierVehiclesStackNavigator = () => {
	const { t } = useTranslation();
	const navigation = useNavigation();
	return (
		<VehiclesStack.Navigator
			screenOptions={{
				headerTintColor: colors.white,
				headerStyle: { backgroundColor: colors.orange[600] },
			}}
		>
			<VehiclesStack.Screen
				name="CourierVehicles"
				component={AppCourierProfileVehiclesHomeScreen}
				options={{
					title: t('screen.titles.courier.profile_screen.vehicles'),
					headerTitleAlign: 'center',
					headerShown: true,
					headerLeft: () => (Platform.OS === 'ios' ? <HeaderBackButton onPress={() => navigation.goBack()} /> : null),
				}}
			/>
			<VehiclesStack.Screen
				name="CourierVehicleCreate"
				component={AppCourierProfileVehicleCreateVehicleScreen}
				options={{
					title: t('screen.titles.courier.profile_screen.vehicle.create_vehicle'),
					headerTitleAlign: 'center',
					headerShown: true,
					headerBackButtonDisplayMode: 'minimal',
				}}
			/>
		</VehiclesStack.Navigator>
	);
};

export const AppCourierDocumentsStackNavigator = () => {
	const navigation = useNavigation();
	return (
		<DocumentsStack.Navigator
			screenOptions={{
				headerTintColor: colors.white,
				headerStyle: { backgroundColor: colors.orange[600] },
				headerBackButtonDisplayMode: 'minimal',
				headerTitleAlign: 'center',
			}}
		>
			<DocumentsStack.Screen
				name="CourierDocuments"
				component={AppCompanyProfileCourierDocumentsScreen}
				options={{
					title: 'Courier Documents',
					headerShown: true,
					headerTitleAlign: 'center',
					headerLeft: () => (Platform.OS === 'ios' ? <HeaderBackButton onPress={() => navigation.goBack()} /> : null),
				}}
			/>
			<DocumentsStack.Screen
				name="CourierDocumentCreate"
				component={AppCompanyProfileCourierDocumentAddScreen}
				options={{
					title: 'Create Document',
					headerTitleAlign: 'center',
					headerShown: true,
					headerBackButtonDisplayMode: 'minimal',
				}}
			/>
		</DocumentsStack.Navigator>
	);
};

export const AppCourierProfileStackNavigator = () => {
	const { t } = useTranslation();
	return (
		<ProfileStack.Navigator
			initialRouteName="CourierProfile"
			screenOptions={{
				headerTintColor: colors.white,
				headerStyle: { backgroundColor: colors.orange[600] },
				headerBackButtonDisplayMode: 'minimal',
				headerTitleAlign: 'center',
			}}
		>
			<ProfileStack.Screen
				name="CourierProfile"
				component={AppCourierProfileScreen}
				options={{
					title: t('screen.titles.courier.profile'),
					headerTitleAlign: 'center',
				}}
			/>
			<ProfileStack.Screen
				name="CourierMyAccount"
				component={AppCourierProfileMyAccountScreen}
				options={{ title: t('screen.titles.courier.profile_screen.my_account'), headerTitleAlign: 'center' }}
			/>
			<ProfileStack.Screen
				name="CourierBankAccount"
				component={AppCourierProfileBankAccountScreen}
				options={{ title: t('screen.titles.courier.profile_screen.bank_accounts'), headerTitleAlign: 'center' }}
			/>
			<ProfileStack.Screen
				name="CourierCreateBankAccount"
				component={AppCourierProfileBankAccountCreateScreen}
				options={{ title: t('screen.titles.courier.profile_screen.bank_account_create'), headerTitleAlign: 'center' }}
			/>
			<ProfileStack.Screen
				name="CourierVehiclesStack"
				component={AppCourierVehiclesStackNavigator}
				options={{ headerShown: false }}
			/>
			<ProfileStack.Screen
				name="CourierVehicleView"
				component={AppCourierProfileVehicleViewScreen}
				options={{ headerShown: true, title: 'Courier Vehicle' }}
			/>
			<ProfileStack.Screen
				name="CourierDocumentsStack"
				component={AppCourierDocumentsStackNavigator}
				options={{ headerShown: false }}
			/>
			<ProfileStack.Screen
				name="CourierWallet"
				component={AppCourierProfileWalletScreen}
				options={{ title: t('screen.titles.courier.profile_screen.wallet'), headerTitleAlign: 'center' }}
			/>
			<ProfileStack.Screen
				name="CourierWalletWithdraw"
				component={AppCourierProfileWalletWithdrawScreen}
				options={{ title: 'Widthdraw Request List', headerTitleAlign: 'center' }}
			/>
			<ProfileStack.Screen
				name="CourierSettings"
				component={AppCourierProfileSettingsScreen}
				options={{ title: t('screen.titles.courier.profile_screen.settings'), headerTitleAlign: 'center' }}
			/>
		</ProfileStack.Navigator>
	);
};

export const AppCourierNavigator = () => {
	const { t } = useTranslation();
	return (
		<Tab.Navigator
			screenOptions={{
				headerShadowVisible: false,
				tabBarStyle: {
					height: Platform.OS == 'android' ? 60 : 80,
					paddingBottom: 5,
					paddingTop: 5,
				},
				tabBarLabelStyle: {
					fontFamily: FontFamily.Semibold,
					fontSize: font.mini,
					paddingBottom: 5,
				},
				headerTitleAlign: 'center',
				tabBarActiveTintColor: colors.orange[600],
				tabBarInactiveTintColor: colors.black,
				headerTintColor: colors.white,
				headerStyle: {
					backgroundColor: colors.orange[600],
				},
			}}
		>
			<Tab.Screen
				name="CourierHome"
				component={AppCourierHomeScreen}
				options={{
					title: t('screen.titles.courier.home'),
					tabBarIcon: ({ focused }) => (
						<HomeIconSvg width={20} height={20} color={focused ? colors.orange[600] : colors.black} />
					),
				}}
			/>
			<Tab.Screen
				name="CourierOrder"
				component={AppCourierOrderScreen}
				options={{
					title: t('screen.titles.courier.order'),
					tabBarIcon: ({ focused }) => (
						<ShippingBoxIconSvg width={20} height={20} color={focused ? colors.orange[600] : colors.black} />
					),
				}}
			/>
			<Tab.Screen
				name="CourierNotifications"
				component={AppCourierNotificationsScreen}
				options={{
					title: t('screen.titles.courier.notifications'),
					headerShown: false,
					tabBarIcon: ({ focused }) => (
						<NotificationIconSvg width={20} height={20} color={focused ? colors.orange[600] : colors.black} />
					),
				}}
			/>
			<Tab.Screen
				name="CourierProfileStack"
				component={AppCourierProfileStackNavigator}
				options={{
					title: t('screen.titles.courier.profile'),
					headerShown: false,
					tabBarIcon: ({ focused }) => (
						<ProfileIconSvg width={20} height={20} color={focused ? colors.orange[600] : colors.black} />
					),
				}}
			/>
		</Tab.Navigator>
	);
};
