import { FileType } from '@/@types';
import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import {
	OnboardingCompanyAreaAddressRequestDTO,
	OnboardingCompanyAreaInfoRequestDTO,
	OnboardingCompanyAreaRequestDTO,
	OnboardingCompanyAreaUserRequestDTO,
	OnboardingCompanyInfoRequestDTO,
	OnboardingCompanyRequestDTO,
} from 'palriderapptypes/company';

type OnboardingCompanyRequestSlice = Omit<OnboardingCompanyRequestDTO, 'area'> & {
	area: Omit<OnboardingCompanyAreaRequestDTO, 'user'> & {
		user: OnboardingCompanyAreaUserRequestDTO & {
			phone_number: string;
		};
	};
};
export const companyOnboardingInitialValues: OnboardingCompanyRequestSlice = {
	company: {
		name: '',
		official_name: '',
		company_category_id: '',
	},
	area: {
		info: {
			name: '',
			email: '',
		},
		user: {
			name: '',
			surname: '',
			birthday: '',
			phone_number: '',
		},
		address: {
			address: '',
			building: '',
			latitude: 0,
			longitude: 0,
			post_code: '',
			directions: '',
			documents: [],
			photos: [],
		},
	},
};

const companyOnboardingSlice = createSlice({
	name: 'companyOnboarding',
	initialState: companyOnboardingInitialValues,
	reducers: {
		setCompanyInfoOnboardingState: (state, action: PayloadAction<OnboardingCompanyInfoRequestDTO>) => {
			return {
				...state,
				company: { ...action.payload },
			};
		},
		setCompanyAreaInfoOnboardingState: (state, action: PayloadAction<OnboardingCompanyAreaInfoRequestDTO>) => {
			return {
				...state,
				area: {
					...state.area,
					info: { ...action.payload },
				},
			};
		},
		setCompanyAreaAddressInfoOnboardingState: (
			state,
			action: PayloadAction<Omit<OnboardingCompanyAreaAddressRequestDTO, 'documents' | 'photos'>>,
		) => {
			return {
				...state,
				area: {
					...state.area,
					address: { ...action.payload, documents: state.area.address.documents, photos: state.area.address.photos },
				},
			};
		},
		setCompanyAreaUserInfoOnboardingState: (
			state,
			action: PayloadAction<OnboardingCompanyRequestSlice['area']['user']>,
		) => {
			return {
				...state,
				area: {
					...state.area,
					user: { ...action.payload },
				},
			};
		},
		setCompanyAreaAddressDocumentState: (state, action: PayloadAction<Array<FileType>>) => {
			return {
				...state,
				area: {
					...state.area,
					address: {
						...state.area.address,
						documents: [...action.payload],
					},
				},
			};
		},
		setCompanyAreaAddressPhotoState: (state, action: PayloadAction<Array<FileType>>) => {
			return {
				...state,
				area: {
					...state.area,
					address: {
						...state.area.address,
						photos: [...action.payload],
					},
				},
			};
		},
	},
});
export const {
	setCompanyInfoOnboardingState,
	setCompanyAreaInfoOnboardingState,
	setCompanyAreaAddressInfoOnboardingState,
	setCompanyAreaUserInfoOnboardingState,
	setCompanyAreaAddressDocumentState,
	setCompanyAreaAddressPhotoState,
} = companyOnboardingSlice.actions;
export default companyOnboardingSlice.reducer;
