import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { LinkingOptions, NavigationContainer, NavigatorScreenParams } from '@react-navigation/native';
import SplashScreen from '@/screens/splash';

import { AuthStackNavigator, AuthStackParamList } from './auth-navigation';
import { AppCourierNavigator, AppCourierTabParamList } from './courier-navigation';
import { AppCompanyStackNavigator, AppCompanyTabParamList } from './company-navigation';
import { AppOrderStackNavigator, AppOrderStackParamList } from './order-navigation';
import React, { useEffect, useRef } from 'react';
import { GlobalParamList } from '@/hooks/useUserNavigation';
import { useAppLifecycle } from '@/hooks/useAppLifecycle';
import { View } from 'react-native';
export type RootStackParamList = {
	Splash: undefined;
	AuthStack: NavigatorScreenParams<AuthStackParamList>;
	AppCompanyStack: NavigatorScreenParams<AppCompanyTabParamList>;
	AppCourierStack: NavigatorScreenParams<AppCourierTabParamList>;
	AppOrderStack: NavigatorScreenParams<AppOrderStackParamList>;
};

const Stack = createNativeStackNavigator<RootStackParamList>();

const RootNavigation = () => {
	const navigationRef = useRef(null);
	useAppLifecycle();

	const linking: LinkingOptions<GlobalParamList> = {
		prefixes: ['palriderapp://', 'https://palrider.app'],
		config: {
			screens: {
				AppCourierStack: {
					screens: {
						CourierProfileStack: {
							screens: {
								CourierDocumentsStack: {
									screens: {
										CourierDocuments: 'courier-documents',
									},
								},
							},
						},
					},
				},
				AppCompanyStack: {
					screens: {
						CompanyProfileStack: {
							screens: {
								CompanyAreaStack: {
									screens: {
										CompanyAreaDocuments: {
											path: 'company-area-address-documents/:company_area_address_id',
											parse: { company_area_address_id: String },
										},
									},
								},
							},
						},
					},
				},
			},
		},
	};
	return (
		<View style={{ flex: 1 }}>
			<NavigationContainer ref={navigationRef} linking={linking}>
				<Stack.Navigator initialRouteName="Splash" screenOptions={{ headerShown: false, headerTitleAlign: 'center' }}>
					<Stack.Screen name="Splash" component={SplashScreen} />
					<Stack.Screen name="AuthStack" component={AuthStackNavigator} />
					<Stack.Screen name="AppCourierStack" component={AppCourierNavigator} />
					<Stack.Screen name="AppCompanyStack" component={AppCompanyStackNavigator} />
					<Stack.Screen name="AppOrderStack" component={AppOrderStackNavigator} />
				</Stack.Navigator>
			</NavigationContainer>
		</View>
	);
};

export default RootNavigation;
