import colors from '@/theme/colors';
import React, { ReactNode } from 'react';
import { Pressable, StyleSheet, ViewStyle } from 'react-native';
import Animated, {
	interpolate,
	interpolateColor,
	SharedValue,
	useAnimatedStyle,
	useSharedValue,
	withTiming,
} from 'react-native-reanimated';

type Props = {
	value: SharedValue<number>;
	onPress?: (status: boolean) => void;
	style?: ViewStyle;
	duration?: number;
	trackColors?: { on: string; off: string };
	textComponent: ReactNode;
};
const PalRirderSwitch: React.FC<Props> = ({
	value,
	onPress,
	style,
	duration = 400,
	trackColors = { on: colors.green[600], off: colors.gray[300] },
	textComponent,
}) => {
	const height = useSharedValue(0);
	const width = useSharedValue(0);

	const trackAnimatedStyle = useAnimatedStyle(() => {
		const color = interpolateColor(value.value, [0, 1], [trackColors.off, trackColors.on]);
		const colorValue = withTiming(color, { duration });

		return {
			backgroundColor: colorValue,
			borderRadius: height.value / 2,
		};
	});

	const thumbAnimatedStyle = useAnimatedStyle(() => {
		const moveValue = interpolate(Number(value.value), [0, 1], [0, width.value - height.value]);
		const translateValue = withTiming(moveValue, { duration });

		return {
			transform: [{ translateX: translateValue }],
			borderRadius: height.value / 2,
		};
	});
	const handleOnPress = () => {
		value.value = value.value === 0 ? 1 : 0;
		if (onPress) onPress(value.value === 0 ? true : false);
	};

	return (
		<Pressable onPress={handleOnPress} style={switchStyles.container}>
			{textComponent}
			<Animated.View
				onLayout={(e) => {
					height.value = e.nativeEvent.layout.height;
					width.value = e.nativeEvent.layout.width;
				}}
				style={[switchStyles.track, style, trackAnimatedStyle]}
			>
				<Animated.View style={[switchStyles.thumb, thumbAnimatedStyle]} />
			</Animated.View>
		</Pressable>
	);
};

const switchStyles = StyleSheet.create({
	container: {
		justifyContent: 'space-between',
		alignItems: 'center',
		flexDirection: 'row',
	},
	track: {
		alignItems: 'flex-start',
		width: 60,
		height: 40,
		padding: 5,
	},
	thumb: {
		height: '100%',
		aspectRatio: 1,
		backgroundColor: 'white',
	},
});

export default PalRirderSwitch;
