import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { CreateOrderBonusRequestDTO } from 'palriderapptypes/order';

type OrderBonusType = {
	min: number;
	max: number;
	sort: number;
	price: number;
};
export type CallRiderSliceType = {
	company_area_id: string;
	company_area_address_id: string;
	start_duration: Date;
	end_duration: Date;
	hourly_rate: number;
	courier_count: number;
	vehicle_types: Array<string>;
	order_bonus_type: 'none' | 'by_distance' | 'per_shipment';
	order_bonuses: Array<OrderBonusType>;
	estimated_total_cost: number;
	start_time: number;
	work_hour: number;
	company_area_address_wallet_id: string;
};

export const callRiderInititalState: CallRiderSliceType = {
	company_area_id: '',
	company_area_address_id: '',
	start_duration: new Date(),
	end_duration: new Date(),
	courier_count: 1,
	hourly_rate: 0,
	vehicle_types: [],
	order_bonus_type: 'none',
	order_bonuses: [],
	estimated_total_cost: 0,
	start_time: 0,
	work_hour: 0,
	company_area_address_wallet_id: '',
};

const callRiderSlice = createSlice({
	name: 'callRiderSlice',
	initialState: callRiderInititalState,
	reducers: {
		setCallRiderState: (state, action: PayloadAction<Partial<CallRiderSliceType>>) => {
			return {
				...state,
				...action.payload,
			};
		},
		setCallRiderCourierCount: (state, action: PayloadAction<number>) => {
			return {
				...state,
				courier_count: action.payload,
			};
		},
		setCallRiderOrderBonuses: (state, action: PayloadAction<Array<CreateOrderBonusRequestDTO>>) => {
			return {
				...state,
				order_bonuses: action.payload,
			};
		},
	},
});

export const { setCallRiderState, setCallRiderCourierCount, setCallRiderOrderBonuses } = callRiderSlice.actions;
export default callRiderSlice.reducer;
