import { RootState, storeDispatch } from '@/redux/store';
import { BASE_URL } from '@env';
import { BaseQueryFn, FetchArgs, FetchBaseQueryError, fetchBaseQuery } from '@reduxjs/toolkit/query/react';
import { setToken, setUser } from '@/redux/slices/userSlice.ts';
import { getDeviceLocale } from '@/utils/localization';

const baseQueryConfig = fetchBaseQuery({
	baseUrl: BASE_URL,
	mode: 'cors',
	timeout: 30000,
	prepareHeaders: (headers, { getState }) => {
		const token = (getState() as RootState).userSlice.token;
		if (token) {
			headers.set('Authorization', `Bearer ${token}`);
		}
		const deviceLocale = getDeviceLocale();
		headers.set('Accept', 'application/json');
		headers.set('Accept-Language', deviceLocale.toLowerCase());
		if (!headers.has('Content-Type')) {
			headers.set('Content-Type', 'application/json');
		}
		return headers;
	},
});

const baseQueryConfigWithReAuth: BaseQueryFn<string | FetchArgs, unknown, FetchBaseQueryError> = async (
	args,
	api,
	extraOptions,
) => {
	const result = await baseQueryConfig(args, api, extraOptions);
	if (result.error && result.error.status === 401) {
		// Dispatch logout action
		api.dispatch(storeDispatch(setToken(null)));
		api.dispatch(storeDispatch(setUser(null)));
	}

	return result;
};

export { baseQueryConfigWithReAuth };
export default baseQueryConfig;
