import React, { useEffect } from 'react';
import { StyleSheet, View } from 'react-native';
import colors from '@/theme/colors.ts';
import { font, PADDING } from '@/theme/responsive.ts';
import PalRiderButton from '@/components/PalRiderButton.tsx';
import PalRiderText from '@/components/PalRiderText.tsx';
import { useLazyGetCourierBankAccountsQuery } from '@/services/api/courier/courier-bank-account';
import { FontFamily } from '@/theme/fonts';
import { CompositeScreenProps } from '@react-navigation/native';
import { FlatList, RefreshControl } from 'react-native-gesture-handler';
import CourierBankAccountItemRenderer from './components/CourierBankAccountItemRenderer';
import { AppCourierProfileStackParamList, AppCourierTabParamList } from '@/navigation/courier-navigation';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { RootStackParamList } from '@/navigation';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import Icon from '@/components/Icon';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCourierProfileStackParamList, 'CourierBankAccount'>,
	CompositeScreenProps<
		BottomTabScreenProps<AppCourierTabParamList, 'CourierProfileStack'>,
		NativeStackScreenProps<RootStackParamList>
	>
>;

const AppCourierProfileBankAccountScreen: React.FC<Props> = ({ navigation }) => {
	const [getBankAccounts, { isFetching, currentData }] = useLazyGetCourierBankAccountsQuery();
	const loadBankAccounts = () => {
		getBankAccounts({
			page: 1,
			size: 100,
		});
	};
	useEffect(() => {
		loadBankAccounts();
	}, []);
	const navigateToCreate = () => {
		navigation.navigate('AppCourierStack', {
			screen: 'CourierProfileStack',
			params: {
				screen: 'CourierCreateBankAccount',
			},
		});
	};
	return (
		<View style={styles.container}>
			<FlatList
				data={currentData?.data ?? []}
				refreshing={isFetching}
				refreshControl={<RefreshControl refreshing={isFetching} onRefresh={loadBankAccounts} />}
				renderItem={(props) => (
					<CourierBankAccountItemRenderer {...props} load={loadBankAccounts} navigation={navigation} />
				)}
				style={{ flex: 1 }}
				contentContainerStyle={{ flex: 1, padding: PADDING.large }}
				ListFooterComponent={
					<View style={styles.footerStyle}>
						<PalRiderButton variant="dark" onPress={navigateToCreate}>
							<PalRiderText color={colors.white} fontSize={font.mini}>
								Add Bank Information
							</PalRiderText>
						</PalRiderButton>
					</View>
				}
				ListEmptyComponent={
					<View style={styles.emptyListContainer}>
						<Icon name="CreditCardIconSvg" color={colors.black} />
						<PalRiderText fontSize={font.medium} fontFamily={FontFamily.Semibold} style={styles.emptyListText}>
							You do not have a registered bank account.
						</PalRiderText>
					</View>
				}
			/>
		</View>
	);
};
const styles = StyleSheet.create({
	container: {
		backgroundColor: colors.white,
		flex: 1,
	},
	emptyListContainer: {
		flex: 1,
		justifyContent: 'center',
		alignItems: 'center',
		gap: PADDING.xxlarge,
	},
	emptyListText: {
		maxWidth: 300,
		textAlign: 'center',
	},
	footerStyle: {},
});
export default AppCourierProfileBankAccountScreen;
