import React, { useState } from 'react';
import { CompositeScreenProps } from '@react-navigation/native';
import { Pressable, StyleSheet, View } from 'react-native';
import { useFormik } from 'formik';
import PalRiderText from '@/components/PalRiderText';
import PalRiderButton from '@/components/PalRiderButton';
import { FontFamily } from '@/theme/fonts';
import colors from '@/theme/colors';
import { font, PADDING } from '@/theme/responsive';
import { yupTyped } from '@/types';
import { number, object, string } from 'yup';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { isFetchBaseQueryError, snakeToHumanReadable } from '@/utils';
import WarningModal from '@/components/custom-modal/WarningModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import { CourierDocumentType, CreateCourierDocumentRequestDTO } from 'palriderapptypes/courier';
import PalRiderTextInput from '@/components/PalRiderTextInput';
import Dropdown from 'react-native-input-select';
import { globalStyles } from '@/utils/global-styles';
import { TSelectedItem } from 'react-native-input-select/lib/typescript/src/types/index.types';
import PalRiderBottomSelectModal from '@/components/PalRiderBottomSelectModal';
import { launchCamera, launchImageLibrary } from 'react-native-image-picker';
import { FileType } from '@/@types';
import { useStoreCourierDocumentMutation } from '@/services/api/courier/courier-document';

import { NativeStackScreenProps } from '@react-navigation/native-stack';
import {
	AppCourierDocumentsStackParamList,
	AppCourierProfileStackParamList,
	AppCourierTabParamList,
} from '@/navigation/courier-navigation';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import { SafeAreaView } from 'react-native-safe-area-context';

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCourierDocumentsStackParamList, 'CourierDocumentCreate'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCourierProfileStackParamList, 'CourierDocumentsStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCourierTabParamList, 'CourierProfileStack'>,
			NativeStackScreenProps<RootStackParamList>
		>
	>
>;
const AppCompanyProfileCourierDocumentAddScreen: React.FC<Props> = ({ route, navigation }) => {
	const { showGlobalModal } = useModal();
	const [storeCourierDocument] = useStoreCourierDocumentMutation();
	const [modalOpened, setModalOpened] = useState(false);
	const documentFormik = useFormik<CreateCourierDocumentRequestDTO>({
		initialValues: {
			courier_id: route.params.courier_id,
			document: null,
			type: null,
		},
		validationSchema: yupTyped<CreateCourierDocumentRequestDTO>({
			document: object()
				.shape({
					name: string().required('File name required'),
					size: number().required().max(10000000),
					uri: string().required('File uri is required'),
					type: string().required('File type is required'),
				})
				.required()
				.label('Courier Document'),
			type: string().required().label('Courier Document Type'),
		}),
		onSubmit: async (values) => {
			showGlobalModal({
				children: <LoadingModal />,
				backgroundColor: colors.transparent,
			});
			const res = await storeCourierDocument({
				courier_id: values.courier_id,
				document: values.document,
				type: values.type,
			});
			if (res.error && isFetchBaseQueryError(res.error)) {
				showGlobalModal({
					children: <WarningModal text={res.error.data.title} />,
				});
				return;
			}
			showGlobalModal({
				children: <SuccessModal text={'Courier document added'} />,
				closeAfterDelay: 1500,
				whenClose() {
					navigation.goBack();
				},
			});
		},
	});

	const courierDocumentTypes: { label: string; value: CourierDocumentType }[] = (
		['identity_card_front', 'identity_card_back', 'driver_licence_front', 'driver_licence_back'] as const
	).map((v) => ({ label: snakeToHumanReadable(v), value: v }));
	return (
		<SafeAreaView style={[styles.container]} edges={['bottom']}>
			<PalRiderBottomSelectModal
				data={[
					{
						text: 'Pick From Library',
						async onPress() {
							const res = await launchImageLibrary({
								mediaType: 'photo',
								includeExtra: true,
								presentationStyle: 'fullScreen',
								quality: 1,
								selectionLimit: 1,
							});
							if (res.didCancel || res.errorCode || !res.assets || !res.assets[0]) {
								return;
							}
							const file = res.assets[0];
							documentFormik.setFieldValue('document', {
								name: file.fileName,
								size: file.fileSize,
								type: file.type,
								uri: file.uri,
							} as FileType);
							setModalOpened(false);
						},
					},
					{
						text: 'Take A Photo',
						async onPress() {
							try {
								const res = await launchCamera({
									mediaType: 'photo',
									includeExtra: true,
									presentationStyle: 'overCurrentContext',
									quality: 1,
									saveToPhotos: false,
								});
								if (res.didCancel || res.errorCode || !res.assets || !res.assets[0]) {
									return;
								}
								const file = res.assets[0];
								documentFormik.setFieldValue('document', {
									name: file.fileName,
									size: file.fileSize,
									type: file.type,
									uri: file.uri,
								} as FileType);
								setModalOpened(false);
							} catch (e) {
								console.error(e);
							}
						},
					},
				]}
				isVisible={modalOpened}
				title="Select"
				cancelOnPress={() => setModalOpened(false)}
				isCoverScreen
			/>
			<View style={styles.documentContainer}>
				<View style={styles.chooseContainer}>
					<Pressable
						onPress={() => {
							setModalOpened(true);
						}}
					>
						<PalRiderTextInput
							pointerEvents="none"
							editable={false}
							placeholder="Select Document"
							error={documentFormik.errors?.document}
							value={documentFormik.values?.document?.name ? 'Document Selected' : ''}
						/>
					</Pressable>

					<View style={{ marginVertical: PADDING.medium }}>
						<View style={{ flexDirection: 'row', columnGap: PADDING.mini }}>
							<PalRiderText style={styles.titleText}>Courier Document Type</PalRiderText>
						</View>
						<Dropdown
							{...globalStyles.dropdownProps}
							options={courierDocumentTypes}
							placeholder="Select Document Type"
							isSearchable
							autoCloseOnSelect
							isMultiple={false}
							selectedValue={documentFormik.values.type as TSelectedItem}
							onValueChange={(value) => documentFormik.setFieldValue('type', value, true)}
							maxSelectableItems={1}
						/>

						{documentFormik.errors.type && (
							<PalRiderText style={globalStyles.errorTextStyle}>{documentFormik.errors.type}</PalRiderText>
						)}
					</View>
				</View>
			</View>
			<View style={[styles.buttonContainer]}>
				<PalRiderButton variant="dark" style={{ flex: 1 }} onPress={() => documentFormik.handleSubmit()}>
					<PalRiderText color="white">Add</PalRiderText>
				</PalRiderButton>
			</View>
		</SafeAreaView>
	);
};
const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.white,
		padding: PADDING.large,
		gap: PADDING.large,
	},
	documentContainer: {},
	chooseContainer: {},
	buttonContainer: {
		flexDirection: 'row',
		gap: PADDING.large,
	},
	selectedDocumentsContainer: {
		width: '100%',
		marginBottom: PADDING.large,
	},
	selectedDocumentsContentContainerStyle: {
		gap: PADDING.medium,
		width: '100%',
	},
	documentItemContainer: {
		padding: PADDING.large,
		paddingVertical: PADDING.xxlarge,
		borderWidth: 1,
		borderColor: colors.gray[600],
		flexDirection: 'row',
		flex: 1,
		alignItems: 'center',
		justifyContent: 'space-between',
		gap: PADDING.large,
	},
	titleText: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.mini,
		marginBottom: PADDING.medium,
	},
	radioButton: {
		flexDirection: 'row',
		alignItems: 'center',
		marginBottom: 10,
	},
});

export default AppCompanyProfileCourierDocumentAddScreen;
