import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { normalize } from '@/theme/responsive';
import React, { forwardRef } from 'react';
import { StyleSheet, TextInput, TextInputProps, View, ViewStyle } from 'react-native';
import PalRiderText from './PalRiderText';
import { UKFlagIconSvg } from '@/assets/svg/flag.tsx';
import { ChevronDownIconSvg } from '@/assets/svg/ui';

type PalRiderPhoneInputTypes = {
	title?: string;
	textInputContainerStyle?: ViewStyle;
	containerStyles?: ViewStyle;
	leftComponent?: React.ReactNode | React.ReactNode[] | undefined;
	rightComponent?: React.ReactNode | React.ReactNode[] | undefined;
	error?: string;
	touched?: boolean;
	required?: boolean;
	value?: string | null | undefined;
	areaCode: string;
	onAreaCodePress: () => void;
} & TextInputProps;
const PalRiderPhoneInput = forwardRef((props: PalRiderPhoneInputTypes, ref: React.LegacyRef<TextInput>) => {
	const {
		title,
		textInputContainerStyle,
		containerStyles,
		rightComponent,
		error,
		touched,
		required,
		value,
		areaCode,
		onAreaCodePress,
		...otherTextInputProps
	} = props;
	return (
		<View style={containerStyles}>
			<View style={{ flexDirection: 'row', columnGap: normalize(2) }}>
				<PalRiderText style={styles.titleText}>{title}</PalRiderText>
				{required && (
					<PalRiderText color={colors.red[600]} fontFamily={FontFamily.Semibold}>
						*
					</PalRiderText>
				)}
			</View>
			<View
				style={[
					styles.inputContainer,
					{
						borderColor: error ? colors.red[600] : colors.gray[300],
					},
				]}
			>
				<View style={[styles.leftComponentView, textInputContainerStyle]}>
					<View style={styles.leftItems} onTouchStart={() => onAreaCodePress()}>
						{/* <UKFlagIconSvg /> */}
						<PalRiderText style={styles.phoneAreaCode}>+{areaCode}</PalRiderText>
						<ChevronDownIconSvg width={20} height={20} />
					</View>
					<TextInput
						maxLength={12}
						style={[styles.textInputStyle]}
						keyboardType="phone-pad"
						numberOfLines={1}
						ref={ref}
						{...otherTextInputProps}
						onChangeText={(text) => {
							const numericValue = text.replace(/\D/g, '');

							let formattedNumber = '';
							if (numericValue.length > 0) {
								formattedNumber += numericValue.substring(0, 3);
							}
							if (numericValue.length > 3) {
								formattedNumber += ' ' + numericValue.substring(3, 6);
							}
							if (numericValue.length > 6) {
								formattedNumber += ' ' + numericValue.substring(6, 10);
							}

							otherTextInputProps.onChangeText && otherTextInputProps.onChangeText(formattedNumber);
						}}
						value={value ? value : undefined}
					/>
				</View>
				{rightComponent && <View style={styles.center}>{rightComponent}</View>}
			</View>
			{touched || (error && <PalRiderText style={styles.errorText}>{error}</PalRiderText>)}
		</View>
	);
});
const styles = StyleSheet.create({
	inputContainer: {
		flexDirection: 'row',
		borderWidth: normalize(1, 'width'),
		minHeight: normalize(40),
		backgroundColor: colors.gray[100],
		paddingHorizontal: normalize(12),
		paddingLeft: 0,
		borderRadius: normalize(8),
	},
	titleText: {
		fontFamily: FontFamily.Semibold,
		fontSize: normalize(12),
		marginBottom: normalize(6),
		paddingLeft: normalize(4),
	},
	textInputStyle: {
		fontFamily: FontFamily.Semibold,
		fontSize: normalize(14),
		flex: 1,
		color: colors.black,
	},
	leftComponentView: {
		flex: 1,
		flexDirection: 'row',
		alignContent: 'center',
	},
	title: {
		fontFamily: FontFamily.Semibold,
		fontSize: normalize(14),
		marginBottom: normalize(6),
		paddingLeft: normalize(4),
	},
	center: {
		justifyContent: 'center',
	},
	leftItems: {
		alignItems: 'center',
		paddingHorizontal: normalize(10, 'width'),
		marginRight: normalize(10),
		flexDirection: 'row',
		backgroundColor: colors.gray[200],
		gap: normalize(8),
		borderTopLeftRadius: normalize(8),
		borderBottomLeftRadius: normalize(8),
	},
	phoneAreaCode: {
		fontSize: normalize(14),
		fontFamily: FontFamily.Bold,
		color: colors.black,
	},
	errorText: {
		fontFamily: FontFamily.Semibold,
		color: colors.red[500],
		fontSize: normalize(12),
		paddingLeft: normalize(4),
		marginTop: normalize(6),
	},
});

export default PalRiderPhoneInput;
