import PalRiderButton from '@/components/PalRiderButton';
import PalRiderText from '@/components/PalRiderText';
import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { font, PADDING } from '@/theme/responsive';
import { useState } from 'react';
import { StyleSheet, TouchableOpacity, View } from 'react-native';
import { useModal } from '@/components/ModalProvider';
import WarningModal from '@/components/custom-modal/WarningModal';
import { CompositeScreenProps } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { AuthStackParamList } from '@/navigation/auth-navigation';
import { RootStackParamList } from '@/navigation';
import { useTranslation } from 'react-i18next';
import { SafeAreaView } from 'react-native-safe-area-context';
import { safeAreaEdges } from '@/utils';
import Icon from '@/components/Icon';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AuthStackParamList, 'AuthSelect'>,
	NativeStackScreenProps<RootStackParamList>
>;
const AuthSelectScreen: React.FC<Props> = ({ navigation }) => {
	const { t } = useTranslation();
	const [selected, setSelected] = useState<'company' | 'courier'>();
	const { showGlobalModal } = useModal();
	const goToSignIn = () => {
		navigation.navigate('PhoneInfo');
	};
	const goToSignUp = async () => {
		if (!selected) {
			showGlobalModal({
				children: <WarningModal text={t('screen.auth.auth_select.user_selection_mandatory')} />,
			});
		}
		if (selected === 'company') {
			navigation.navigate('AuthStack', {
				screen: 'SignUpCompanyAreaUser',
			});
			return;
		}
		if (selected === 'courier') {
			navigation.navigate('AuthStack', {
				screen: 'SignUpCourier',
			});
			return;
		}
	};
	return (
		<SafeAreaView style={styles.container} edges={safeAreaEdges}>
			<PalRiderText style={styles.title}>{t('screen.auth.auth_select.please_choose')}</PalRiderText>
			<PalRiderText style={styles.description}>{t('screen.auth.auth_select.please_choose_description')}</PalRiderText>
			<View style={styles.typeContainer}>
				<TouchableOpacity
					style={[
						styles.type,
						{
							borderColor: selected === 'company' ? colors.green[600] : colors.gray[300],
						},
					]}
					onPress={() => setSelected('company')}
					activeOpacity={1}
				>
					<View style={styles.typeInnerContainer}>
						<Icon name="CompanyIconWomen" />
					</View>
					<PalRiderText style={styles.typeText}>{t('common.company')}</PalRiderText>
				</TouchableOpacity>
				<TouchableOpacity
					style={[
						styles.type,
						{
							borderColor: selected === 'courier' ? colors.green[600] : colors.gray[300],
						},
					]}
					onPress={() => setSelected('courier')}
					activeOpacity={1}
				>
					<View style={styles.typeInnerContainer}>
						<Icon name="CourierManIconSvg" />
					</View>
					<PalRiderText style={styles.typeText}>{t('common.courier')}</PalRiderText>
				</TouchableOpacity>
			</View>
			<View style={{ paddingHorizontal: PADDING.large, marginTop: PADDING.xxlarge }}>
				<PalRiderButton variant="dark" style={{ width: '100%' }} onPress={goToSignUp}>
					<PalRiderText fontFamily={FontFamily.Semibold} color={colors.white}>
						{t('common.continue')}
					</PalRiderText>
				</PalRiderButton>
			</View>
			<View style={styles.alreadyHaveAccount}>
				<PalRiderText>{t('screen.auth.auth_select.already_an_account')}</PalRiderText>
				<TouchableOpacity onPress={goToSignIn}>
					<PalRiderText style={styles.signInText}>{t('screen.auth.auth_select.sign_in')}</PalRiderText>
				</TouchableOpacity>
			</View>
		</SafeAreaView>
	);
};
const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.white,
		justifyContent: 'center',
	},
	title: {
		fontFamily: FontFamily.Bold,
		fontSize: font.xxlarge,
		textAlign: 'center',
		paddingVertical: PADDING.large,
	},
	description: {
		paddingHorizontal: PADDING.large,
		fontFamily: FontFamily.Regular,
		textAlign: 'center',
		fontSize: font.small,
		color: colors.gray[500],
	},
	typeContainer: {
		flexDirection: 'row',
		justifyContent: 'center',
		alignItems: 'center',
		marginTop: PADDING.large,
		columnGap: PADDING.xxlarge,
	},
	type: {
		borderWidth: 2,
		borderRadius: PADDING.large,
		alignItems: 'center',
		padding: PADDING.medium,
		minWidth: 150,
	},
	typeText: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.small,
		marginTop: PADDING.medium,
	},
	typeInnerContainer: {
		width: 140,
		alignItems: 'center',
		backgroundColor: colors.gray[200],
		borderRadius: PADDING.large,
		paddingTop: PADDING.large,
	},
	alreadyHaveAccount: {
		justifyContent: 'center',
		flexDirection: 'row',
		columnGap: PADDING.medium,
		marginTop: PADDING.xlarge,
	},
	signInText: {
		textDecorationLine: 'underline',
		color: colors.orange[500],
		fontFamily: FontFamily.Semibold,
	},
});
export default AuthSelectScreen;
