import React from 'react';
import colors from '@/theme/colors.ts';
import PalRiderWizard, { PalRiderWizardStep } from '@/components/PalRiderWizard.tsx';
import SignUpCourierPersonalInformationStep from '@/screens/auth/signup/courier/components/courier-personal-information';
import SignUpCourierDocumentInformationStep from '@/screens/auth/signup/courier/components/courier-document';
import SignUpCourierVehicleInformationStep from '@/screens/auth/signup/courier/components/courier-vehicle';
import SignUpCourierPhoneInfoStep from '@/screens/auth/signup/courier/components/courier-authenticate';
import SignUpCourierPhoneCodeStep from '@/screens/auth/signup/courier/components/courier-verify';
import { SafeAreaView } from 'react-native-safe-area-context';
import { AuthStackParamList } from '@/navigation/auth-navigation';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { RootStackParamList } from '@/navigation';
import { CompositeScreenProps } from '@react-navigation/native';
import { View } from 'react-native';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AuthStackParamList, 'SignUpCourier'>,
	NativeStackScreenProps<RootStackParamList>
>;
const SignUpCourierScreen: React.FC<Props> = ({navigation}) => {
	return (
		<View
			style={{
				flex: 1,
				backgroundColor: colors.white,
			}}
		>
			<PalRiderWizard>
				<PalRiderWizardStep title={'Info'}>
					{({ nextStep }) => (
						<>
							<SignUpCourierPersonalInformationStep nextStep={nextStep} />
						</>
					)}
				</PalRiderWizardStep>
				<PalRiderWizardStep title={'Document'}>
					{({ nextStep, prevStep }) => (
						<>
							<SignUpCourierDocumentInformationStep prevStep={prevStep} nextStep={nextStep} />
						</>
					)}
				</PalRiderWizardStep>
				<PalRiderWizardStep title={'Vehicle'}>
					{({ nextStep, prevStep }) => (
						<>
							<SignUpCourierVehicleInformationStep prevStep={prevStep} nextStep={nextStep} />
						</>
					)}
				</PalRiderWizardStep>
				<PalRiderWizardStep title={'Authenticate'}>
					{({ nextStep, prevStep }) => (
						<>
							<SignUpCourierPhoneInfoStep prevStep={prevStep} nextStep={nextStep} />
						</>
					)}
				</PalRiderWizardStep>
				<PalRiderWizardStep title={'Verify'}>
					{({ prevStep }) => (
						<>
							<SignUpCourierPhoneCodeStep prevStep={prevStep} />
						</>
					)}
				</PalRiderWizardStep>
			</PalRiderWizard>
		</View>
	);
};
export default SignUpCourierScreen;
