import React, { useEffect, useState } from 'react';
import { StyleSheet, View } from 'react-native';
import colors from '@/theme/colors.ts';
import PalRiderText from '@/components/PalRiderText.tsx';
import { PADDING } from '@/theme/responsive';
import PalRiderButton from '@/components/PalRiderButton';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { CompositeScreenProps } from '@react-navigation/native';
import { isFetchBaseQueryError } from '@/utils';
import WarningModal from '@/components/custom-modal/WarningModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import { AppCompanyProfileParamList, AppCompanyTabParamList } from '@/navigation/company-navigation';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import { useGetCompanyAreaAddressWalletListQuery } from '@/services/api/company/company-area-address';
import { useTransferBalanceMutation } from '@/services/api/company/company-wallet';
import {
	useLazyGetAllCompanyAreaQuery,
	useLazyGetCompanyAreaAddressesQuery,
} from '@/services/api/company/company-area';
import Dropdown from 'react-native-input-select';
import { globalStyles } from '@/utils/global-styles';
import { CompanyAreaAddressDTO, CompanyAreaAddressWalletDTO, CompanyAreaDTO } from 'palriderapptypes/company';
import PalRiderCurrencyInput from '@/components/PalRiderCurrencyInput';
import ConfirmationModal from '@/components/custom-modal/ConfirmationModal';
import Icon from '@/components/Icon';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyWalletTransfer'>,
	CompositeScreenProps<
		BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
		NativeStackScreenProps<RootStackParamList>
	>
>;

const AppCompanyProfileCompanyWalletTransferScreen: React.FC<Props> = ({ navigation, route }) => {
	const { showGlobalModal, hideGlobalModal } = useModal();
	const [getCompanyAreas] = useLazyGetAllCompanyAreaQuery();
	const [getCompanyAreaAddresses] = useLazyGetCompanyAreaAddressesQuery();
	const [selectedCompanyArea, setSelectedCompanyArea] = useState<string | undefined>(undefined);
	const [selectedCompanyAreaAddress, setSelectedCompanyAreaAddress] = useState<string | undefined>(undefined);
	const [selectedCompanyAreaAddressWallet, setSelectedCompanyAreaAddressWallet] = useState<string | undefined>(
		undefined,
	);
	const [transferAmount, setTransferAmount] = useState(route.params.balance ? route.params.balance.toString() : '');
	const [transferBalance] = useTransferBalanceMutation();

	const { data: companyAreaAddressWalletsData } = useGetCompanyAreaAddressWalletListQuery(
		selectedCompanyAreaAddress as string,
		{ skip: !selectedCompanyAreaAddress },
	);

	const [companyAreas, setCompanyAreas] = useState<Array<CompanyAreaDTO>>([]);
	const [companyAreaAddresses, setCompanyAreaAddresses] = useState<Array<CompanyAreaAddressDTO>>([]);
	const companyAreaAddressWallets: CompanyAreaAddressWalletDTO[] = companyAreaAddressWalletsData?.data ?? [];

	useEffect(() => {
		getCompanyAreas({ page: 1, size: 100 })
			.unwrap()
			.then((res) => setCompanyAreas(res.data));
	}, []);

	useEffect(() => {
		if (selectedCompanyArea) {
			getCompanyAreaAddresses({ company_area_id: selectedCompanyArea, page: 1, size: 100 })
				.unwrap()
				.then((res) => setCompanyAreaAddresses(res.data));
		}
	}, [selectedCompanyArea]);

	const handleTransferConfirm = () => {
		if (Number(transferAmount) <= 0) {
			showGlobalModal({
				children: <WarningModal text="Transfer amount must be at least 1" />,
			});
			return;
		}
		showGlobalModal({
			padding: 0,
			children: (
				<ConfirmationModal
					icon={<Icon name="TransferFillIconSvg" width={48} height={48} color={colors.green[600]} />}
					text={'Are you sure want to transfer ?'}
					textColor={colors.green[600]}
					onConfirm={() => handleTransfer()}
					onCancel={() => hideGlobalModal()}
				/>
			),
		});
		return;
	};

	const handleTransfer = async () => {
		showGlobalModal({
			children: <LoadingModal />,
			backgroundColor: colors.transparent,
			padding: 0,
		});
		if (!selectedCompanyAreaAddressWallet) {
			showGlobalModal({
				children: <WarningModal text="Company area address wallet must be selected" />,
			});
			return;
		}
		const res = await transferBalance({
			amount: Number(transferAmount),
			company_area_address_wallet_id: selectedCompanyAreaAddressWallet,
			company_wallet_id: route.params.company_wallet_id,
		});
		if (res.error && isFetchBaseQueryError(res.error)) {
			showGlobalModal({
				children: <WarningModal text={res.error.data.title} />,
			});
			return;
		}

		showGlobalModal({
			children: <SuccessModal text={res.data?.message} />,
			closeAfterDelay: 1000,
			whenClose() {
				if (route.params.return_call_rider) {
					navigation.navigate('AppCompanyStack', {
						screen: 'CompanyOrderStack',
						params: { screen: 'CompanyCallRider' },
					});
					return;
				}
				navigation.canGoBack() && navigation.goBack();
			},
		});
	};

	useEffect(() => {
		if (route.params.company_area_id && companyAreas.length > 0) {
			setSelectedCompanyArea(route.params.company_area_id);
		}
	}, [route.params.company_area_id, companyAreas]);

	useEffect(() => {
		if (route.params.company_area_address_id && companyAreaAddresses.length > 0) {
			setSelectedCompanyAreaAddress(route.params.company_area_address_id);
		}
	}, [route.params.company_area_address_id, companyAreaAddresses]);

	useEffect(() => {
		if (route.params.company_area_address_wallet_id && companyAreaAddressWallets.length > 0) {
			setSelectedCompanyAreaAddressWallet(route.params.company_area_address_wallet_id);
		}
	}, [route.params.company_area_address_wallet_id, companyAreaAddressWallets]);

	return (
		<View style={styles.container}>
			<View>
				<PalRiderText style={globalStyles.titleTextStyle}>Company Areas</PalRiderText>
				<Dropdown
					{...globalStyles.dropdownProps}
					options={companyAreas.map((area) => ({ value: area.id, label: area.name }))}
					isSearchable
					isMultiple={false}
					selectedValue={selectedCompanyArea}
					onValueChange={(value) => setSelectedCompanyArea(value as string)}
					maxSelectableItems={1}
				/>
			</View>

			{selectedCompanyArea && companyAreaAddresses.length > 0 && (
				<View>
					<PalRiderText style={globalStyles.titleTextStyle}>Company Area Addresses</PalRiderText>
					<Dropdown
						{...globalStyles.dropdownProps}
						options={companyAreaAddresses.map((address) => ({ value: address.id, label: address.address }))}
						isSearchable
						isMultiple={false}
						selectedValue={selectedCompanyAreaAddress}
						onValueChange={(value) => setSelectedCompanyAreaAddress(value as string)}
						maxSelectableItems={1}
					/>
				</View>
			)}

			{selectedCompanyAreaAddress && companyAreaAddressWallets.length > 0 && (
				<View>
					<PalRiderText style={globalStyles.titleTextStyle}>Company Area Address Wallets</PalRiderText>
					<Dropdown
						{...globalStyles.dropdownProps}
						options={companyAreaAddressWallets.map((wallet) => ({ value: wallet.id, label: wallet.name }))}
						isSearchable
						isMultiple={false}
						selectedValue={selectedCompanyAreaAddressWallet}
						onValueChange={(value) => setSelectedCompanyAreaAddressWallet(value as string)}
						maxSelectableItems={1}
					/>
				</View>
			)}

			{selectedCompanyAreaAddressWallet && (
				<View style={{ gap: PADDING.large }}>
					<PalRiderCurrencyInput
						title="Transfer Amount"
						onChangeCurrencyText={async (text) => setTransferAmount(text)}
						value={transferAmount}
						currencyValue={'0.00'}
					/>
					<PalRiderButton variant="success" onPress={handleTransferConfirm}>
						Transfer
					</PalRiderButton>
				</View>
			)}
		</View>
	);
};

const styles = StyleSheet.create({
	container: {
		backgroundColor: colors.white,
		flex: 1,
		padding: PADDING.large,
		rowGap: PADDING.large,
	},
});

export default AppCompanyProfileCompanyWalletTransferScreen;
