import React, { useEffect, useRef, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, useWindowDimensions, View } from 'react-native';
import PalRiderText from '@/components/PalRiderText.tsx';
import { useFinishOrderEarlyMutation, useLazyGetOrderQuery, useLazyGetOrderShipmentsQuery } from '@/services/api/order';
import { font, PADDING } from '@/theme/responsive.ts';
import { RefreshControl } from 'react-native-gesture-handler';
import colors from '@/theme/colors.ts';
import { FontFamily } from '@/theme/fonts.ts';
import { SceneRendererProps, TabBar, TabBarItem, TabView } from 'react-native-tab-view';
import { BottomSheetModal, BottomSheetView } from '@gorhom/bottom-sheet';
import CompanyOrderCourierAttendeeTabList from '@/screens/app/company/orders/modals/tabs/CompanyOrderCourierAttendeeTabList.tsx';
import { CompositeScreenProps } from '@react-navigation/native';
import CompanyOrderShipmentTab from '../modals/tabs/CompanyOrderShipmentTab';
import { formatTime, isFetchBaseQueryError } from '@/utils';

import { useModal } from '@/components/ModalProvider';
import ConfirmationModal from '@/components/custom-modal/ConfirmationModal';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import WarningModal from '@/components/custom-modal/WarningModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { AppCompanyOrderParamList, AppCompanyTabParamList } from '@/navigation/company-navigation';
import { RootStackParamList } from '@/navigation';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { useTranslation } from 'react-i18next';
import { OrderDTO } from 'palriderapptypes/order';
import { MenuAction, MenuView } from '@react-native-menu/menu';
import { useAppSelector } from '@/redux/hooks';
import { useOrderHub } from '@/hooks/useOrderHub';
import Icon from '@/components/Icon';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyOrderParamList, 'CompanyOrderView'>,
	CompositeScreenProps<
		BottomTabScreenProps<AppCompanyTabParamList, 'CompanyOrderStack'>,
		NativeStackScreenProps<RootStackParamList>
	>
>;
const AppCompanyOrderViewScreen: React.FC<Props> = ({ route, navigation }) => {
	const { t } = useTranslation();
	const user = useAppSelector((x) => x.userSlice);
	const [getOrder, { data: order }] = useLazyGetOrderQuery();
	const [finishOrderEarly] = useFinishOrderEarlyMutation();
	const [getShipments, { data: shipments }] = useLazyGetOrderShipmentsQuery();
	const [loading, setLoading] = useState(true);
	const bottomSheetModalRef = useRef<BottomSheetModal>(null);
	const { showGlobalModal, hideGlobalModal } = useModal();

	const [orderShipmentTabIndex, setOrderShipmentTabIndex] = useState(0);
	const [orderCourierAttendeeTabIndex, setOrderCourierAttendeeTabIndex] = useState(0);
	const layout = useWindowDimensions();

	const [orderShipmentRoutes] = useState([
		{ key: 'active', title: t('common.active_shipments') },
		{ key: 'completed', title: t('common.completed_shipments') },
		{ key: 'cancelled', title: t('common.cancelled_shipments') },
	]);
	const [orderCourierAttendeeRoutes] = useState([
		{ key: 'arriving', title: t('common.arriving') },
		{ key: 'waiting', title: t('common.waiting') },
		{ key: 'working', title: t('common.working') },
		{ key: 'completed', title: t('common.completed') },
		{ key: 'rejected', title: t('common.rejected') },
	]);
	const fetchOrder = async () => {
		await getOrder(route.params.order_id);
	};

	const fetchShipments = async () => {
		await getShipments({
			order_id: route.params.order_id,
			page: 1,
			size: 100,
		});
	};
	const fetchAll = () => {
		setLoading(true);
		Promise.all([fetchOrder(), fetchShipments()])
			.then(() => {
				setLoading(false);
			})
			.catch(() => {
				setLoading(false);
			});
	};

	const courierActionHandle = () => {
		fetchAll();
	};

	const renderOrderShipmentsScene = (renderProps: SceneRendererProps & { route: { key: string; title: string } }) => {
		switch (renderProps.route.key) {
			case 'active':
				return (
					<CompanyOrderShipmentTab
						shipments={
							shipments?.data?.filter((x) => x.status === 'on_delivery' || x.status === 'waiting_delivery') ?? []
						}
					/>
				);
			case 'completed':
				return <CompanyOrderShipmentTab shipments={shipments?.data?.filter((x) => x.status === 'completed') ?? []} />;
			case 'cancelled':
				return <CompanyOrderShipmentTab shipments={shipments?.data?.filter((x) => x.status === 'cancelled') ?? []} />;
			default:
				return null;
		}
	};
	const handleFinishEarly = async (order_id: string) => {
		showGlobalModal({
			backgroundColor: colors.transparent,
			children: <LoadingModal />,
		});

		const res = await finishOrderEarly(order_id);
		if (res.error && isFetchBaseQueryError(res.error)) {
			showGlobalModal({
				children: <WarningModal text={res.error.data.title} />,
			});
			return;
		}
		showGlobalModal({
			children: <SuccessModal text={res.data?.message} />,
		});
	};
	const renderHeaderRightActions = (order: OrderDTO) => {
		const actionMenu: Array<MenuAction> = [];
		if (order.status == 'on_going') {
			actionMenu.push({ id: 'finish_order_early', title: t('screen.company.order_info.finish_order_early') });
		}
		if (order.status == 'pending') {
			actionMenu.push({
				id: 'cancel_order',
				title: 'Cancel Order',
			});
		}
		if (actionMenu.length == 0) return null;
		return (
			<View style={{ flexDirection: 'row', gap: PADDING.medium }}>
				<MenuView
					onPressAction={({ nativeEvent }) => {
						if (nativeEvent.event === 'finish_order_early') {
							showGlobalModal({
								padding: 0,
								children: (
									<ConfirmationModal
										icon={<Icon name="TimerPauseRoundedIconSvg" width={48} height={48} color={colors.red[600]} />}
										text={t('screen.company.order_info.finish_order_early_request')}
										textColor={colors.red[600]}
										onConfirm={() => handleFinishEarly(order.id)}
										onCancel={() => hideGlobalModal()}
									/>
								),
							});
							return;
						}
						if (nativeEvent.event === 'cancel_order') {
							showGlobalModal({
								padding: 0,
								children: (
									<ConfirmationModal
										icon={<Icon name="TimerPauseRoundedIconSvg" width={48} height={48} color={colors.red[600]} />}
										text={'Are you want to sure cancel order ?'}
										textColor={colors.red[600]}
										onConfirm={() => handleFinishEarly(order.id)}
										onCancel={() => hideGlobalModal()}
									/>
								),
							});
							return;
						}
					}}
					actions={actionMenu}
					shouldOpenOnLongPress={false}
				>
					<Pressable>
						<Icon name="ThreeHorizontalDotIconSvg" color={colors.white} />
					</Pressable>
				</MenuView>
				<Pressable onPress={() => fetchAll()}>
					<Icon name="RefreshIconSvg" color={colors.white} />
				</Pressable>
			</View>
		);
	};

	const renderOrderCourierAttendeeScene = (
		renderProps: SceneRendererProps & { route: { key: string; title: string } },
	) => {
		switch (renderProps.route.key) {
			case 'arriving':
				return (
					<CompanyOrderCourierAttendeeTabList
						attendees={order?.data.order_courier_attendees.filter((x) => x.status === 'arriving') ?? []}
						courierActionHandle={courierActionHandle}
						order_id={order?.data.id}
					/>
				);
			case 'waiting':
				return (
					<CompanyOrderCourierAttendeeTabList
						attendees={
							order?.data.order_courier_attendees.filter((x) => x.status === 'waiting_for_company_approval') ?? []
						}
						courierActionHandle={courierActionHandle}
						order_id={order?.data.id}
					/>
				);
			case 'working':
				return (
					<CompanyOrderCourierAttendeeTabList
						attendees={order?.data.order_courier_attendees.filter((x) => x.status === 'working') ?? []}
						courierActionHandle={courierActionHandle}
						order_id={order?.data.id}
					/>
				);
			case 'completed':
				return (
					<CompanyOrderCourierAttendeeTabList
						attendees={order?.data.order_courier_attendees.filter((x) => x.status === 'completed') ?? []}
						courierActionHandle={courierActionHandle}
						order_id={order?.data.id}
					/>
				);
			case 'rejected':
				return (
					<CompanyOrderCourierAttendeeTabList
						attendees={order?.data.order_courier_attendees.filter((x) => x.status === 'rejected') ?? []}
						courierActionHandle={courierActionHandle}
						order_id={order?.data.id}
					/>
				);
			default:
				return (
					<View>
						<PalRiderText>Test</PalRiderText>
					</View>
				);
		}
	};
	const handleShowAttendees = () => {
		bottomSheetModalRef.current?.present();
	};
	useEffect(() => {
		fetchAll();
	}, []);
	useEffect(() => {
		if (order) {
			navigation.setOptions({
				title: t('common.order') + ' #' + order?.data.order_no,
				headerRight: () => renderHeaderRightActions(order.data),
			});
		}
	}, [order]);
	const { joinOrderRoom, leaveOrderRoom } = useOrderHub(user.token!, fetchAll);

	// Join a room for a specific order
	useEffect(() => {
		if (!order?.data.id) return;
		joinOrderRoom(order.data.id);

		return () => {
			leaveOrderRoom(order.data.id);
		};
	}, [order?.data.id]);

	if (!order || !order.data) {
		return (
			<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
				<ActivityIndicator color={colors.orange[600]} />
			</View>
		);
	}
	return (
		<>
			<ScrollView
				style={{ flex: 1 }}
				contentContainerStyle={{ flex: 1, backgroundColor: colors.white }}
				contentInsetAdjustmentBehavior="automatic"
				refreshControl={<RefreshControl onRefresh={fetchAll} refreshing={loading} />}
			>
				{(!order || !order.data) && (
					<View>
						<PalRiderText>Order Not Found</PalRiderText>
					</View>
				)}
				<View style={styles.orderInfoContainer}>
					<View style={styles.orderInfoItem}>
						<PalRiderText style={styles.orderInfoTitle}>{t('common.order_no')}</PalRiderText>
						<PalRiderText style={styles.orderInfoText}>#{order?.data.order_no}</PalRiderText>
					</View>
					<View style={styles.orderInfoItem}>
						<PalRiderText style={styles.orderInfoTitle}>Working Hours</PalRiderText>
						<PalRiderText style={styles.orderInfoText}>{formatTime(order?.data.current_hour)}</PalRiderText>
					</View>
					<View style={styles.orderInfoItem}>
						<PalRiderText style={styles.orderInfoTitle}>Driven Mile</PalRiderText>
						<PalRiderText style={styles.orderInfoText}>
							{Number(order?.data.current_mile ?? 0).toFixed(2)} Mile
						</PalRiderText>
					</View>
					<View style={styles.orderInfoItem}>
						<PalRiderText style={styles.orderInfoTitle}>Hourly Rate</PalRiderText>
						<PalRiderText style={styles.orderInfoText}>£{order.data.hourly_rate}</PalRiderText>
					</View>
					<View style={styles.orderInfoItem}>
						<PalRiderText style={styles.orderInfoTitle}>{t('common.attendees')}</PalRiderText>
						<Pressable onPress={() => handleShowAttendees()}>
							<PalRiderText fontFamily={FontFamily.Bold} fontSize={font.mini}>
								{t('common.show')} {t('common.attendees')} ({order?.data.order_courier_attendees.length})
							</PalRiderText>
						</Pressable>
					</View>
				</View>
				<TabView
					renderTabBar={(props) => (
						<TabBar
							indicatorStyle={{ backgroundColor: colors.gray[500] }}
							activeColor={colors.black}
							indicatorContainerStyle={{ width: 'auto' }}
							inactiveColor={colors.gray[500]}
							tabStyle={{ width: 'auto' }}
							renderTabBarItem={(tabBarItemprops) => (
								<TabBarItem
									{...tabBarItemprops}
									labelStyle={{
										fontFamily: FontFamily.Semibold,
										fontSize: font.xmini,
										color: colors.black,
									}}
									key={tabBarItemprops.key}
								/>
							)}
							style={{
								backgroundColor: colors.white,
								borderBottomWidth: 1,
								borderBottomColor: colors.gray[300],
							}}
							{...props}
						/>
					)}
					navigationState={{ index: orderShipmentTabIndex, routes: orderShipmentRoutes }}
					renderScene={renderOrderShipmentsScene}
					onIndexChange={setOrderShipmentTabIndex}
					overScrollMode={'always'}
					initialLayout={{ width: layout.width, height: layout.height * 0.5 }}
				/>
			</ScrollView>
			<BottomSheetModal
				ref={bottomSheetModalRef}
				index={1}
				snapPoints={[layout.height * 0.5]}
				enablePanDownToClose
				enableDynamicSizing
			>
				<BottomSheetView style={{ flex: 1 }}>
					<TabView
						renderTabBar={(props) => (
							<TabBar
								indicatorStyle={{ backgroundColor: colors.gray[500] }}
								activeColor={colors.black}
								indicatorContainerStyle={{ width: 'auto' }}
								inactiveColor={colors.gray[500]}
								tabStyle={{ width: 'auto' }}
								renderTabBarItem={(tabBarItemprops) => (
									<TabBarItem
										{...tabBarItemprops}
										labelStyle={{
											fontFamily: FontFamily.Semibold,
											fontSize: font.xmini,
											color: colors.black,
										}}
										key={tabBarItemprops.key}
									/>
								)}
								style={{
									backgroundColor: colors.white,
									borderBottomWidth: 1,
									borderBottomColor: colors.gray[300],
								}}
								{...props}
							/>
						)}
						navigationState={{
							index: orderCourierAttendeeTabIndex,
							routes: orderCourierAttendeeRoutes,
						}}
						renderScene={renderOrderCourierAttendeeScene}
						onIndexChange={setOrderCourierAttendeeTabIndex}
						initialLayout={{ width: layout.width }}
					/>
				</BottomSheetView>
			</BottomSheetModal>
		</>
	);
};
const styles = StyleSheet.create({
	orderInfoContainer: {
		borderRadius: PADDING.large,
		gap: PADDING.small,
	},
	orderInfoTitle: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.small,
	},
	orderInfoText: {
		fontFamily: FontFamily.Regular,
		fontSize: font.mini,
		color: colors.gray[500],
	},
	orderInfoItem: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
		padding: PADDING.large,
		paddingVertical: PADDING.medium,
		borderBottomWidth: 1,
		borderColor: colors.gray[300],
	},
	editRow: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: PADDING.medium,
	},
});
export default AppCompanyOrderViewScreen;
