import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import PalRiderText from '@/components/PalRiderText';
import { Platform, StyleSheet, View } from 'react-native';
import MapView, { Marker, Polyline } from 'react-native-maps';
import BottomSheet, {
	BottomSheetFooter,
	BottomSheetFooterProps,
	BottomSheetModal,
	BottomSheetView,
} from '@gorhom/bottom-sheet';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { normalize, PADDING } from '@/theme/responsive';
import PalRiderButton from '@/components/PalRiderButton';
import { buttonStyling } from '@/theme/defaults';
import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { useFormik } from 'formik';
import CreateOrderShipmentAddressList from './components/CreateOrderShipmentAddressList';
import CreateOrderShipmentAddDestinationModal from './components/CreateOrderShipmentAddDestinationModal';
import LocationMarker from '@/components/LocationMarker';
import { array, object } from 'yup';
import { CompositeScreenProps } from '@react-navigation/native';
import { useCreateShipmentMutation } from '@/services/api/order/shipment';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import WarningModal from '@/components/custom-modal/WarningModal';
import { APP_WINDOW_HEIGHT, isFetchBaseQueryError } from '@/utils';
import { CourierActiveOrderDTO, CreateOrderShipmentDestinationRequestDTO } from 'palriderapptypes/order';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { AppOrderStackParamList } from '@/navigation/order-navigation';
import { RootStackParamList } from '@/navigation';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppOrderStackParamList, 'CreateShipment'>,
	CompositeScreenProps<NativeStackScreenProps<AppOrderStackParamList>, NativeStackScreenProps<RootStackParamList>>
>;
const AppActiveOrderCreateOrderShipmentScreen: React.FC<Props> = ({ route, navigation }) => {
	const addDestinationBottomSheetModalRef = useRef<BottomSheetModal>(null);
	const createDestinationBottomSheetModalRef = useRef<BottomSheet>(null);
	const [order, setOrder] = useState<CourierActiveOrderDTO>();
	const [createShipment] = useCreateShipmentMutation();
	const { showGlobalModal, hideGlobalModal } = useModal();
	const [addressListSheetBottomHeight, setAddressListSheetBottomHeight] = useState(0);

	const insets = useSafeAreaInsets();
	const createOrderShipmentFormik = useFormik<{ destinations: Array<CreateOrderShipmentDestinationRequestDTO> }>({
		initialValues: {
			destinations: [],
		},
		validateOnChange: false,
		validationSchema: object().shape({
			destinations: array().min(1),
		}),
		onSubmit: async (values) => {
			try {
				if (!route.params.order) return;
				showGlobalModal({
					children: <LoadingModal />,
					backgroundColor: colors.transparent,
					preventHiding: true,
				});

				const result = await createShipment({
					destinations: values.destinations,
					order_id: route.params.order.id,
				});
				hideGlobalModal();
				if (result.error && isFetchBaseQueryError(result.error)) {
					showGlobalModal({
						children: <WarningModal text={result.error.data.title} />,
					});
					return;
				}
				showGlobalModal({
					children: <SuccessModal text="Shipment Created" />,
					closeAfterDelay: 2000,
					whenClose() {
						if (order) {
							navigation.navigate('ActiveOrderStack', {
								screen: 'Shipments',
								params: {
									order_id: order.id,
								},
							});
						}
					},
				});
			} catch (err) {
				console.error(err);
			}
		},
	});

	const snapPoints = useMemo(() => ['25%', '75%'], []);
	const renderFooter = useCallback(
		(footerProps: BottomSheetFooterProps) => (
			<BottomSheetFooter
				{...footerProps}
				style={{
					paddingHorizontal: PADDING.large,
					paddingTop: PADDING.large,
					paddingBottom: Platform.OS === 'ios' ? insets.bottom : PADDING.large,
					backgroundColor: colors.white,
					borderTopWidth: 1,
					borderTopColor: colors.gray[300],
				}}
			>
				<View
					style={[styles.buttonContainer]}
					onLayout={(e) => {
						setAddressListSheetBottomHeight(e.nativeEvent.layout.height + 20);
					}}
				>
					<PalRiderButton
						style={[buttonStyling.dark, { flex: 1 }]}
						onPress={() => addDestinationBottomSheetModalRef.current?.present()}
					>
						<PalRiderText color={colors.white}>Add Destination</PalRiderText>
					</PalRiderButton>
					{createOrderShipmentFormik.values.destinations.length > 0 && (
						<>
							<PalRiderButton
								style={[buttonStyling.success, { flex: 1 }]}
								onPress={() => createOrderShipmentFormik.handleSubmit()}
							>
								<PalRiderText color={colors.white}>Create Shipment</PalRiderText>
							</PalRiderButton>
						</>
					)}
				</View>
			</BottomSheetFooter>
		),
		[createOrderShipmentFormik.values.destinations.length],
	);
	const bottomSheetPaddingBottom = useCallback(() => insets.bottom + PADDING.xlarge, [addressListSheetBottomHeight]);
	useEffect(() => {
		if (!route.params.order) navigation.goBack();
		setOrder(route.params.order);
	}, []);

	return (
		<View style={styles.container}>
			{order && (
				<>
					<MapView
						provider="google"
						userInterfaceStyle="light"
						style={StyleSheet.absoluteFillObject}
						region={{
							latitude: order.company_area_address?.latitude ?? 0,
							longitude: order.company_area_address?.longitude ?? 0,
							longitudeDelta: 0.1,
							latitudeDelta: 0.1,
						}}
					>
						<Marker
							coordinate={{
								latitude: order.company_area_address?.latitude ?? 0,
								longitude: order.company_area_address?.longitude ?? 0,
							}}
							pinColor={colors.blue[600]}
						/>
						{createOrderShipmentFormik.values.destinations.map((address) => (
							<Polyline
								key={address.sort}
								coordinates={[
									{
										latitude: order.company_area_address?.latitude ?? 0,
										longitude: order.company_area_address?.longitude ?? 0,
									},
									{
										latitude: address.latitude,
										longitude: address.longitude,
									},
								]}
							/>
						))}

						{createOrderShipmentFormik.values.destinations.map((address) => (
							<Marker
								key={address.sort}
								coordinate={{
									latitude: address.latitude,
									longitude: address.longitude,
								}}
								pinColor={colors.green[600]}
								style={{ zIndex: address.sort }}
							>
								<LocationMarker text={address.sort.toString()} />
							</Marker>
						))}
					</MapView>

					<BottomSheet
						ref={createDestinationBottomSheetModalRef}
						snapPoints={snapPoints}
						index={1}
						enableOverDrag={false}
						enablePanDownToClose={false}
						maxDynamicContentSize={APP_WINDOW_HEIGHT * 0.7}
						handleComponent={() => {
							if (createOrderShipmentFormik.values.destinations.length === 0)
								return (
									<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', padding: PADDING.large }}>
										<PalRiderText>There is no destination address</PalRiderText>
									</View>
								);
							return (
								<View
									style={{
										flex: 1,
										justifyContent: 'center',
										alignItems: 'center',
										padding: PADDING.small,
									}}
								>
									<View
										style={{ width: 30, height: 4, borderRadius: PADDING.small, backgroundColor: colors.gray[400] }}
									/>
								</View>
							);
						}}
						footerComponent={renderFooter}
					>
						<BottomSheetView style={{ flex: 1, paddingBottom: bottomSheetPaddingBottom() }}>
							<CreateOrderShipmentAddressList
								reorderAddresses={(from, to) => {
									const newArray = [...createOrderShipmentFormik.values.destinations];
									const item = newArray.splice(from, 1)[0]; // Remove the item at the 'from' index
									newArray.splice(to, 0, item); // Insert the item at the 'to' index

									createOrderShipmentFormik.setFieldValue(
										'destinations',
										newArray.map((newArrItem, index) => ({
											...newArrItem,
											sort: index + 1,
										})),
									);
								}}
								companyAreaAddress={order.company_area_address!}
								destinations={createOrderShipmentFormik.values.destinations}
								removeFromDestinations={(sort) => {
									const updatedDestinations = createOrderShipmentFormik.values.destinations
										.filter((x) => x.sort !== sort)
										.map((item, index) => ({
											...item,
											sort: index + 1, // Reassign sort order sequentially
										}));

									createOrderShipmentFormik.setFieldValue('destinations', updatedDestinations);
								}}
							/>
						</BottomSheetView>
					</BottomSheet>
					<CreateOrderShipmentAddDestinationModal
						ref={addDestinationBottomSheetModalRef}
						handleAddDestination={(address) => {
							const currentDestinations = [...createOrderShipmentFormik.values.destinations];

							const newSort =
								currentDestinations.length > 0 ? Math.max(...currentDestinations.map((dest) => dest.sort)) + 1 : 1;

							const newDestination = {
								sort: newSort,
								address: address.address,
								latitude: address.latitude,
								longitude: address.longitude,
								payment_at_the_door: address.payment_at_the_door,
								contains_adult_content: address.contains_adult_content,
								received_fee: address.receive_fee,
								post_code: address.post_code,
							};

							createOrderShipmentFormik.setFieldValue('destinations', [...currentDestinations, newDestination]);

							addDestinationBottomSheetModalRef.current?.dismiss();
							createDestinationBottomSheetModalRef.current?.snapToIndex(2);
						}}
					>
						<></>
					</CreateOrderShipmentAddDestinationModal>
				</>
			)}
		</View>
	);
};
const styles = StyleSheet.create({
	container: { flex: 1 },
	mapView: {
		flex: 1,
	},
	bottomSheetViewContainer: {
		flex: 1,
	},
	selectInput: {},
	selectContainer: {
		padding: Platform.OS === 'ios' ? PADDING.large : normalize(2),
		borderWidth: 1,
		borderColor: colors.gray[300],
		borderRadius: PADDING.large,
	},
	titleText: {
		fontFamily: FontFamily.Semibold,
		fontSize: normalize(12),
		marginBottom: normalize(6),
		paddingLeft: normalize(4),
	},
	buttonContainer: {
		gap: PADDING.medium,
		flexDirection: 'row',
		justifyContent: 'center',
		backgroundColor: colors.white,
	},
	bottomSheetFooterContainer: {},
});
export default AppActiveOrderCreateOrderShipmentScreen;
