import { CreateStripePaymentIntentRequestDTO, CreateStripePaymentIntentResponseDTO } from '@/@types/stripe-types';
import { createApi } from '@reduxjs/toolkit/query/react';
import { SuccessfulResponseT } from 'palriderapptypes';
import { baseQueryConfigWithReAuth } from 'src/services/api/baseQueryConfig.ts';

export const stripeApi = createApi({
	reducerPath: 'stripe',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		createStripePaymentIntent: builder.mutation<
			SuccessfulResponseT<CreateStripePaymentIntentResponseDTO>,
			CreateStripePaymentIntentRequestDTO
		>({
			query(body) {
				if (body.company_wallet_id) {
					return {
						method: 'POST',
						body,
						url: `stripe/create-company-wallet-payment-sheet`,
					};
				}
				return {
					method: 'POST',
					body,
					url: `stripe/create-payment-sheet`,
				};
			},
		}),
	}),
});

export const { useCreateStripePaymentIntentMutation } = stripeApi;
