import { useLazyGetCompanyWalletTransactionListQuery } from '@/services/api/company/company-wallet';
import Icon from '@/components/Icon';

const { format } = Intl.NumberFormat('en-UK', {
	currency: 'GBP',
	style: 'currency',
});

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyWalletTransaction'>,
	CompositeScreenProps<
		BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
		NativeStackScreenProps<RootStackParamList>
	>
>;
const WalletTransactionItemRender: React.FC<{ walletItem: CompanyWalletTransactionDTO }> = ({ walletItem }) => {
	const [showItemList, setShowItemList] = useState(false);
	const transactionTypeToColor = (transaction_type: CompanyWalletTransactionType): string => {
		switch (transaction_type) {
			case 'add':
				return colors.green[600];
			case 'subtract':
				return colors.red[300];
			case 'transfer':
				return colors.blue[300];
			case 'start':
				return colors.blue[300];
		}
	};
	return (
		<View style={{ marginVertical: PADDING.large }}>
			<View style={{ paddingHorizontal: PADDING.large, flexDirection: 'row', gap: PADDING.large }}>
				<View style={styles.transactionIconContainer}>
					<Icon name="PoundBanknoteIconSvg" width={32} height={32} />
				</View>
				<View style={styles.transactionItemContainer}>
					<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.small}>
						{snakeToHumanReadable(walletItem.type)}
					</PalRiderText>
					<PalRiderText fontSize={font.mini} color={colors.gray[500]}>
						{formatHumanReadableDate(walletItem.created_at)}
					</PalRiderText>
				</View>
				<View style={styles.transactionAmountContainer}>
					<PalRiderText
						color={transactionTypeToColor(walletItem.type)}
						fontSize={font.medium}
						fontFamily={FontFamily.Semibold}
					>
						{format(walletItem.amount)}
					</PalRiderText>
				</View>
				{walletItem.type != 'start' && (
					<View style={{ justifyContent: 'center' }}>
						<TouchableOpacity
							style={{
								transform: [
									{
										rotate: !showItemList ? '0deg' : '90deg',
									},
								],
								padding: PADDING.medium,
								justifyContent: 'center',
							}}
							onPress={() => setShowItemList((prev) => !prev)}
						>
							<Icon name="ChevronRightIconSvg" />
						</TouchableOpacity>
					</View>
				)}
			</View>
			{showItemList && (
				<FlatList
					data={walletItem.company_wallet_transaction_items}
					style={{
						backgroundColor: colors.gray[100],
						borderColor: colors.gray[300],
						marginTop: PADDING.large,
					}}
					ItemSeparatorComponent={() => (
						<View style={{ height: 1, marginVertical: PADDING.medium, backgroundColor: colors.gray[300] }} />
					)}
					renderItem={({ item }) => (
						<View style={{ flexDirection: 'row', padding: PADDING.large }}>
							<View style={{ flex: 1, gap: PADDING.mini }}>
								<PalRiderText fontSize={font.mini} fontFamily={FontFamily.Semibold}>
									{item.name}
								</PalRiderText>
								<PalRiderText fontSize={font.xmini} color={colors.gray[600]}>
									{item.description}
								</PalRiderText>
							</View>
							<PalRiderText>{format(item.amount)}</PalRiderText>
						</View>
					)}
				/>
			)}
		</View>
	);
};
const AppCompanyProfileCompanyWalletTransactionListScreen: React.FC<Props> = ({ route, navigation }) => {
	const [getCompanyWalletTransactionList, { data }] = useLazyGetCompanyWalletTransactionListQuery();
	const { showGlobalModal, hideGlobalModal } = useModal();
	const { t } = useTranslation();
	const loadWallet = async () => {
		showGlobalModal({
			children: <LoadingModal />,
			backgroundColor: colors.transparent,
		});
		const res = await getCompanyWalletTransactionList({
			company_wallet_id: route.params.company_wallet_id,
			page: 1,
			size: 100,
		});
		if (res.error) {
			const error = res.error as FetchBaseQueryErrorExpected;
			showGlobalModal({
				children: <WarningModal text={error.data.title} />,
			});
		}
		hideGlobalModal();
	};

	useEffect(() => {
		loadWallet();
	}, []);

	return (
		<PullToRefreshView onRefresh={async () => loadWallet()}>
			{data && (
				<ScrollView style={styles.container}>
					<FlatList
						scrollEnabled={false}
						data={data.data}
						keyExtractor={(x) => x.id}
						contentContainerStyle={{ flex: 1 }}
						renderItem={({ item }) => <WalletTransactionItemRender walletItem={item} />}
						stickyHeaderIndices={[0]}
						bounces={false}
						ListHeaderComponent={
							<View style={styles.walletTranscationHeaderContainer}>
								<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.large}>
									Wallet Transaction List
								</PalRiderText>
							</View>
						}
						ListEmptyComponent={
							<View style={styles.noBalanceTransactionContainer}>
								<Icon name="PoundBanknoteIconSvg" width={72} height={72} />
								<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.medium}>
									No Transaction
								</PalRiderText>
							</View>
						}
					/>
				</ScrollView>
			)}
		</PullToRefreshView>
	);
};
