import { useAppDispatch } from '@/redux/hooks';
import { setCompanyAreaAddressUser } from '@/redux/slices/company-slice';
import { setGlobalLoadState } from '@/redux/slices/global-load-slice';
import { setToken, setUser } from '@/redux/slices/userSlice';
import { storeDispatch } from '@/redux/store';
import {
	useLazyGetUserQuery,
	useUpdateNotificationInfoMutation,
	useUpdateUserAppInformationMutation,
} from '@/services/api/user';
import { isFetchBaseQueryError } from '@/utils';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { StackActions } from '@react-navigation/native';
import { QueryStatus } from '@reduxjs/toolkit/query';
import { OneSignal } from 'react-native-onesignal';

import { NavigationProp, useNavigation } from '@react-navigation/native';
import { RootStackParamList } from '@/navigation';
import { AppActiveOrderTabParamList, AppOrderStackParamList } from '@/navigation/order-navigation';
import {
	AppCompanyProfileCompanyAreaParamList,
	AppCompanyProfileParamList,
	AppCompanyTabParamList,
} from '@/navigation/company-navigation';
import { getAppInfo } from './getAppInfo';

export type GlobalParamList = RootStackParamList &
	AppOrderStackParamList &
	AppActiveOrderTabParamList &
	AppCompanyProfileParamList &
	AppCompanyProfileCompanyAreaParamList &
	AppCompanyTabParamList;
export type GlobalNavigation = NavigationProp<GlobalParamList>;

const useUserNavigation = () => {
	const [getUser] = useLazyGetUserQuery();
	const dispatch = useAppDispatch();
	const navigation = useNavigation<GlobalNavigation>();
	const [updateNoticationInfo] = useUpdateNotificationInfoMutation();
	const [sendUserAppInfo] = useUpdateUserAppInformationMutation();
	const handle = async () => {
		dispatch(setGlobalLoadState(true));
		const result = await getUser();
		if (result.error || !result.data) {
			if (isFetchBaseQueryError(result.error)) {
				if (result.status === QueryStatus.rejected && result.error.status === 401) {
					await AsyncStorage.clear();
					dispatch(setToken(null));
					dispatch(setUser(null));
					navigation.dispatch(
						StackActions.replace('AuthStack', {
							screen: 'PhoneInfo',
						}),
					);
				}
			}
			navigation.dispatch(
				StackActions.replace('AuthStack', {
					screen: 'PhoneInfo',
				}),
			);
			return;
		}

		const user = result.data.data;
		storeDispatch(setUser(user));

		// ✅ Send user_app_infos to backend if logged in
		try {
			const appInfo = await getAppInfo();
			await sendUserAppInfo(appInfo);
		} catch (err) {
			console.warn('❌ Failed to send user app info', err);
		}
		const hasPermission = await OneSignal.Notifications.getPermissionAsync();
		const canRequestPermisson = await OneSignal.Notifications.canRequestPermission();

		if (hasPermission) {
			const app_user_id = await OneSignal.User.pushSubscription.getIdAsync();
			if (app_user_id) {
				updateNoticationInfo({
					one_signal_app_player_id: app_user_id,
				});
			}
		} else {
			if (canRequestPermisson) {
				await OneSignal.Notifications.requestPermission(true).then(async (val) => {
					const app_user_id = await OneSignal.User.pushSubscription.getIdAsync();
					if (app_user_id) {
						updateNoticationInfo({
							one_signal_app_player_id: app_user_id,
						});
					}
				});
			}
		}

		if (user.user_type === 'company_area_address_user') {
			const companyAreaAddressUser = user.company_area_address_user;
			if (companyAreaAddressUser != null) {
				dispatch(setCompanyAreaAddressUser(companyAreaAddressUser));

				navigation.dispatch(
					StackActions.replace('AppCompanyStack', {
						screen: 'CompanyHome',
					}),
				);
				dispatch(setGlobalLoadState(false));
				return;
			}
		}
		if (user.user_type === 'courier') {
			const courier = user.courier!;
			if (
				courier.current_active_order_id &&
				courier.current_active_order_shipment_id &&
				courier.current_active_order_shipment_destination_id
			) {
				await AsyncStorage.setItem('current_active_order_id', courier.current_active_order_id);
				await AsyncStorage.setItem('current_active_order_shipment_id', courier.current_active_order_shipment_id);
				await AsyncStorage.setItem(
					'current_active_order_shipment_destination_id',
					courier.current_active_order_shipment_destination_id,
				);
				navigation.dispatch(
					StackActions.replace('AppOrderStack', {
						screen: 'OrderShipmentDelivery',
						params: {
							order_id: courier.current_active_order_id,
							order_shipment_id: courier.current_active_order_shipment_id,
						},
					}),
				);
				dispatch(setGlobalLoadState(false));
				return;
			}
			if (courier.current_active_order_id && courier.current_active_order_shipment_id) {
				await AsyncStorage.setItem('current_active_order_id', courier.current_active_order_id);
				await AsyncStorage.setItem('current_active_order_shipment_id', courier.current_active_order_shipment_id);
				navigation.dispatch(
					StackActions.replace('AppOrderStack', {
						screen: 'OrderShipmentDelivery',
						params: {
							order_id: courier.current_active_order_id,
							order_shipment_id: courier.current_active_order_shipment_id,
						},
					}),
				);
				dispatch(setGlobalLoadState(false));
				return;
			}
			if (courier.current_active_arriving_order_id) {
				navigation.dispatch(
					StackActions.replace('AppOrderStack', {
						screen: 'OrderArriving',
						params: {
							order_id: courier.current_active_arriving_order_id,
						},
					}),
				);
				return;
			} else if (courier.current_active_arrived_order_id) {
				navigation.dispatch(
					StackActions.replace('AppOrderStack', {
						screen: 'OrderArriveWaiting',
						params: {
							order_id: courier.current_active_arrived_order_id,
						},
					}),
				);
				dispatch(setGlobalLoadState(false));
				return;
			} else if (courier.current_active_order_id) {
				await AsyncStorage.setItem('current_active_order_id', courier.current_active_order_id);
				navigation.dispatch(
					StackActions.replace('AppOrderStack', {
						screen: 'ActiveOrderStack',
						params: {
							screen: 'Home',
							params: {
								order_id: courier.current_active_order_id,
							},
						},
					}),
				);
				dispatch(setGlobalLoadState(false));
				return;
			} else {
				dispatch(setGlobalLoadState(false));
				navigation.dispatch(
					StackActions.replace('AppCourierStack', {
						screen: 'CourierHome',
					}),
				);
			}
		}

		// if (response?.status === QueryStatus.rejected && token) {
		// 	await AsyncStorage.clear();
		// 	dispatch(setToken(null));
		// 	navigation.navigate('AuthStack', {
		// 		screen: 'PhoneInfo',
		// 	});
		// }
		// if (response.status === QueryStatus.rejected && response.isError) {
		// 	navigation.navigate('AuthStack', {
		// 		screen: 'PhoneInfo',
		// 	});
		// }
	};

	return { handle };
};
export default useUserNavigation;
