import React, { useEffect, useState } from 'react';
import { View, FlatList, StyleSheet, RefreshControl, Pressable, Text } from 'react-native';
import { CompositeNavigationProp } from '@react-navigation/native';
import { useLazyGetOrdersQuery } from '@/services/api/order';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { OrderDTO, OrderStatus } from 'palriderapptypes/order';
import colors from '@/theme/colors.ts';
import { PADDING, font } from '@/theme/responsive.ts';
import { FontFamily } from '@/theme/fonts.ts';
import { formatTime, priceFormat, snakeToHumanReadable } from '@/utils';
import { DateType } from 'react-native-ui-datepicker';
import { useAppDispatch } from '@/redux/hooks';
import { setCallRiderCourierCount, setCallRiderOrderBonuses, setCallRiderState } from '@/redux/slices/callRiderSlice';

const brandColor = 'rgb(234, 88, 12)';
const statusColors: Record<OrderStatus, { bg: string; text: string }> = {
	pending: { bg: 'rgba(234,179,8,0.15)', text: colors.yellow[700] },
	on_going: { bg: 'rgba(59,130,246,0.15)', text: colors.blue[700] },
	in_review: { bg: 'rgba(249,115,22,0.15)', text: colors.orange[700] },
	cancelled: { bg: 'rgba(239,68,68,0.15)', text: colors.red[700] },
	completed: { bg: 'rgba(34,197,94,0.15)', text: colors.green[700] },
};
const OrderTimelineItem = ({
	order,
	isLast,
	navigation,
	onRecreateOrder,
}: {
	order: OrderDTO;
	isLast: boolean;
	navigation: any;
	onRecreateOrder: (order: OrderDTO) => void;
}) => {
	const [cardHeight, setCardHeight] = useState(0);
	const isCompleted = order.status === 'completed' || order.status === 'cancelled';

	return (
		<View style={styles.orderRow}>
			{/* Timeline */}
			<View style={styles.timelineContainer}>
				<View style={styles.circle} />
				{!isLast && <View style={[styles.verticalLine, { height: cardHeight }]} />}
			</View>

			{/* Order Card */}
			<View style={styles.orderCard} onLayout={(e) => setCardHeight(e.nativeEvent.layout.height)}>
				<Pressable
					onPress={() => {
						navigation.navigate('AppCompanyStack', {
							screen: 'CompanyOrderStack',
							params: { screen: 'CompanyOrderView', params: { order_id: order.id } },
						});
					}}
				>
					<Text style={styles.orderNo}>#{order.order_no}</Text>
					<Text style={styles.orderTime}>{new Date(order.created_at).toLocaleString()}</Text>

					<View style={styles.badgeRow}>
						<View style={[styles.badge, { backgroundColor: brandColor }]}>
							<Text style={styles.badgeText}>£{order.hourly_rate}/h</Text>
						</View>
						<View style={[styles.badge, { backgroundColor: colors.green[600] }]}>
							<Text style={styles.badgeText}>{formatTime(order.current_hour)} hr</Text>
						</View>
						<View style={[styles.badge, { backgroundColor: brandColor }]}>
							<Text style={styles.badgeText}>{order.current_mile?.toFixed(2)} km</Text>
						</View>
					</View>

					<View style={styles.detailsRow}>
						<Text style={styles.detailLabel}>Status:</Text>
						<View style={[styles.statusBadge, { backgroundColor: statusColors[order.status as OrderStatus].bg }]}>
							<Text style={[styles.statusText, { color: statusColors[order.status as OrderStatus].text }]}>
								{snakeToHumanReadable(order.status)}
							</Text>
						</View>
					</View>
					<View style={styles.detailsRow}>
						<Text style={styles.detailLabel}>Shipments:</Text>
						<Text style={styles.detailValue}>{order.order_shipments?.length}</Text>
					</View>
					<View style={styles.detailsRow}>
						<Text style={styles.detailLabel}>Total:</Text>
						<Text style={styles.detailValue}>{priceFormat(order.amount_to_paid)}</Text>
					</View>
				</Pressable>

				{/* Recreate Order Button - Only show for completed orders */}
				{isCompleted && (
					<View style={styles.buttonContainer}>
						<Pressable style={styles.recreateButton} onPress={() => onRecreateOrder(order)}>
							<Text style={styles.recreateButtonText}>Repeat Call</Text>
						</Pressable>
					</View>
				)}
			</View>
		</View>
	);
};

const CompanyAppOrders: React.FC<{
	status: string;
	company_area_id: string | null;
	company_area_address_id: string | null;
	order_start_date?: DateType | null;
	order_end_date?: DateType | null;
	order_no: string | null;
	navigation: CompositeNavigationProp<any, any>;
	setFiltering: React.Dispatch<React.SetStateAction<any>>;
}> = ({
	status,
	company_area_id,
	company_area_address_id,
	order_start_date,
	order_end_date,
	order_no,
	navigation,
	setFiltering,
}) => {
	const { showGlobalModal, hideGlobalModal } = useModal();
	const [getOrders, { data, isLoading, isFetching }] = useLazyGetOrdersQuery();
	const [isFiltered, setIsFiltered] = useState(false);
	const dispatch = useAppDispatch();

	const fetchOrders = async () => {
		showGlobalModal({
			children: <LoadingModal />,
			backgroundColor: 'transparent',
			preventHiding: true,
		});
		await getOrders({
			status,
			page: 1,
			size: 20,
			company_area_id,
			company_area_address_id,
			order_start_date,
			order_end_date,
			order_no,
		});
		hideGlobalModal();
	};

	useEffect(() => {
		if (
			company_area_id ||
			company_area_address_id ||
			order_start_date ||
			order_end_date ||
			status !== 'all' ||
			order_no
		) {
			setIsFiltered(true);
		}
		fetchOrders();
	}, [company_area_id, company_area_address_id, status, order_start_date, order_end_date, order_no]);

	const resetFilter = () => {
		setFiltering({
			status: 'all',
			company_area_id: null,
			company_area_address_id: null,
			order_start_date: undefined,
			order_end_date: undefined,
			order_no: '',
		});
	};

	const handleRecreateOrder = (order: OrderDTO) => {
		dispatch(
			setCallRiderState({
				company_area_id: order.company_area.id,
				company_area_address_id: order.company_area_address.id,
				vehicle_types: order.vehicle_types,
				start_time: Number(0),
				company_area_address_wallet_id: order.company_area_address_wallet.id,
				work_hour: order.work_hour,
				hourly_rate: order.hourly_rate,
			}),
		);

		dispatch(setCallRiderCourierCount(Number(order.courier_count)));
		dispatch(
			setCallRiderOrderBonuses(
				order.order_bonuses.map((bonus) => ({
					max: bonus.max_value,
					min: bonus.min_value,
					price: bonus.price,
					sort: bonus.sort,
				})),
			),
		);

		navigation.navigate('AppCompanyStack', {
			screen: 'CompanyOrderStack',
			params: {
				screen: 'CompanyCallRider',
			},
		});
	};

	return (
		<View style={styles.container}>
			<FlatList
				data={data?.data ?? []}
				refreshControl={<RefreshControl refreshing={isLoading || isFetching} onRefresh={fetchOrders} />}
				keyExtractor={(item) => item.id}
				renderItem={({ item, index }) => (
					<OrderTimelineItem
						order={item}
						isLast={index === (data?.data?.length ?? 1) - 1}
						navigation={navigation}
						onRecreateOrder={handleRecreateOrder}
					/>
				)}
				ListEmptyComponent={
					<View style={styles.emptyContainer}>
						<Text style={styles.emptyText}>
							{isFiltered ? 'No orders found with current filters' : 'No orders have been created yet.'}
						</Text>
						{isFiltered && (
							<Pressable onPress={resetFilter}>
								<Text style={styles.resetFilter}>Reset Filter</Text>
							</Pressable>
						)}
					</View>
				}
				contentContainerStyle={{ padding: PADDING.large }}
			/>
		</View>
	);
};

