import React, { useEffect, useLayoutEffect, useRef, useState } from 'react';
import {
	View,
	FlatList,
	Pressable,
	RefreshControl,
	ActivityIndicator,
	TouchableOpacity,
	StyleSheet,
} from 'react-native';
import LinearGradient from 'react-native-linear-gradient';
import { useTranslation } from 'react-i18next';
import { CompositeScreenProps } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import {
	AppCompanyProfileCompanyAreaParamList,
	AppCompanyProfileParamList,
	AppCompanyTabParamList,
} from '@/navigation/company-navigation';

import colors from '@/theme/colors';
import PalRiderText from '@/components/PalRiderText';
import PalRiderTextInput from '@/components/PalRiderTextInput';
import Icon from '@/components/Icon';
import { MenuAction, MenuView } from '@react-native-menu/menu';
import { useAppSelector } from '@/redux/hooks';
import { CompanyAreaAddressUserDTO } from 'palriderapptypes/company';
import { useLazyGetCompanyAddressesFromCompanyQuery } from '@/services/api/company/company-api';
import { useDeleteCompanyAreaAddressMutation } from '@/services/api/company/company-area-address';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import WarningModal from '@/components/custom-modal/WarningModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import { isFetchBaseQueryError, snakeToHumanReadable } from '@/utils';
import { font, PADDING } from '@/theme/responsive';
import { FontFamily } from '@/theme/fonts';

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList, 'CompanyAreaAddresses'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyAreaStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
			NativeStackScreenProps<RootStackParamList>
		>
	>
>;

const AppCompanyProfileCompanyAreaAddressesScreen: React.FC<Props> = ({ route, navigation }) => {
	const { t } = useTranslation();
	const { showGlobalModal } = useModal();
	const companyAreaAddressUser = useAppSelector(
		(x) => x.userSlice.user?.company_area_address_user,
	) as CompanyAreaAddressUserDTO;

	const [deleteCompanyAreaAddress] = useDeleteCompanyAreaAddressMutation();
	const [getCompanyAddressFromCompany, { data, isFetching }] = useLazyGetCompanyAddressesFromCompanyQuery();
	const [searchTextOpened, setSearchTextOpened] = useState(false);
	const [searchText, setSearchText] = useState('');
	const debounceTimeout = useRef<NodeJS.Timeout>(null);

	useEffect(() => {
		loadData();
	}, []);

	const loadData = async () => {
		getCompanyAddressFromCompany({
			company_id: route.params.company_id,
			page_number: 1,
			page_size: 100,
		});
	};

	const handleDeleteAction = async (company_area_address_id: string) => {
		showGlobalModal({ children: <LoadingModal />, backgroundColor: colors.transparent });
		const res = await deleteCompanyAreaAddress({ company_area_address_id });

		if (res.error && isFetchBaseQueryError(res.error)) {
			showGlobalModal({ children: <WarningModal text={res.error.data.title} /> });
			return;
		}

		showGlobalModal({
			children: <SuccessModal text={res.data?.message} />,
			whenClose: loadData,
		});
	};

	useLayoutEffect(() => {
		navigation.setOptions({
			headerRight: () => (
				<TouchableOpacity
					onPress={() => setSearchTextOpened(true)}
					activeOpacity={0.7}
					style={{ paddingRight: PADDING.medium }}
				>
					<Icon name="SearchIconSvg" color={colors.gray[800]} width={22} height={22} />
				</TouchableOpacity>
			),
		});
	});

	useEffect(() => {
		if (debounceTimeout.current) clearTimeout(debounceTimeout.current);

		if (searchText) {
			debounceTimeout.current = setTimeout(() => {
				getCompanyAddressFromCompany({
					company_id: route.params.company_id,
					page_number: 1,
					page_size: 100,
					search: searchText,
				});
			}, 500);
		} else {
			loadData();
		}

		return () => {
			if (debounceTimeout.current) clearTimeout(debounceTimeout.current);
		};
	}, [searchText]);

	return (
		<View style={styles.container}>
			{searchTextOpened && (
				<View style={{ marginBottom: PADDING.large }}>
					<PalRiderTextInput
						title="Search"
						value={searchText}
						onChangeText={setSearchText}
						placeholder={t('common.search')}
					/>
				</View>
			)}

			<FlatList
				data={data?.data ?? []}
				showsVerticalScrollIndicator={false}
				contentContainerStyle={{ gap: PADDING.medium, paddingBottom: PADDING.xxlarge }}
				ListEmptyComponent={
					<View style={styles.emptyContainer}>
						<PalRiderText fontSize={font.medium} color={colors.gray[500]}>
							{t('screen.company.profile.areas.address.no_address_found')}
						</PalRiderText>
					</View>
				}
				ListHeaderComponent={isFetching ? <ActivityIndicator /> : null}
				ListFooterComponent={
					(companyAreaAddressUser.company_area_address_user_role?.name === 'Owner' && (
						<LinearGradient
							colors={[colors.orange.primary, colors.orange[500]]}
							style={styles.addContainer}
							start={{ x: 0, y: 1 }}
							end={{ x: 1, y: 0 }}
						>
							<Pressable
								style={styles.addButton}
								onPress={() =>
									navigation.navigate('AppCompanyStack', {
										screen: 'CompanyProfileStack',
										params: {
											screen: 'CompanyAreaStack',
											params: {
												screen: 'CompanyAreaAddressCreate',
												params: { company_area_id: route.params.company_area_id },
											},
										},
									})
								}
							>
								<Icon name="LocationIconSvg" width={22} height={36} colorSpace={[colors.white, colors.white]} />
								<PalRiderText fontSize={font.small} fontFamily={FontFamily.Semibold} color={colors.white}>
									Create New Address
								</PalRiderText>
							</Pressable>
						</LinearGradient>
					)) ||
					undefined
				}
				refreshControl={<RefreshControl refreshing={isFetching} onRefresh={loadData} />}
				renderItem={({ item: address }) => {
					const actions: MenuAction[] = [
						{ id: 'show', title: t('common.show') },
						{ id: 'show_photos', title: 'Show Photos' },
						{ id: 'show_documents', title: t('screen.company.profile.areas_screen.show_documents') },
						{ id: 'show_users', title: t('screen.company.profile.areas_screen.show_users') },
						{
							id: 'wallets',
							title: t('common.wallet'),
							attributes: {
								hidden: !['Owner', 'Manager'].includes(
									companyAreaAddressUser.company_area_address_user_role?.name || '',
								),
							},
						},
						{
							id: 'update',
							title: t('common.update'),
							attributes: {
								hidden: companyAreaAddressUser.company_area_address_user_role?.name !== 'Owner',
							},
						},
						{
							id: 'delete',
							title: t('common.delete'),
							attributes: {
								hidden: companyAreaAddressUser.company_area_address_user_role?.name !== 'Owner',
							},
						},
					];

					return (
						<MenuView
							actions={actions}
							shouldOpenOnLongPress={false}
							isAnchoredToRight
							onPressAction={({ nativeEvent }) => {
								if (nativeEvent.event === 'show') {
									navigation.navigate('AppCompanyStack', {
										screen: 'CompanyProfileStack',
										params: {
											screen: 'CompanyAreaStack',
											params: {
												screen: 'CompanyAreaAddressView',
												params: {
													company_area_address_id: address.id,
												},
											},
										},
									});
								}

								if (nativeEvent.event === 'show_documents') {
									navigation.navigate('AppCompanyStack', {
										screen: 'CompanyProfileStack',
										params: {
											screen: 'CompanyAreaStack',
											params: {
												screen: 'CompanyAreaAddressDocuments',
												params: {
													company_area_address_id: address.id,
												},
											},
										},
									});
								}
								if (nativeEvent.event === 'show_photos') {
									navigation.navigate('AppCompanyStack', {
										screen: 'CompanyProfileStack',
										params: {
											screen: 'CompanyAreaStack',
											params: {
												screen: 'CompanyAreaAddressPhotos',
												params: {
													company_area_address_id: address.id,
												},
											},
										},
									});
								}
								if (nativeEvent.event === 'show_users') {
									navigation.navigate('AppCompanyStack', {
										screen: 'CompanyProfileStack',
										params: {
											screen: 'CompanyAreaStack',
											params: {
												screen: 'CompanyAreaAddressUsers',
												params: {
													company_area_address_id: address.id,
													company_area_id: address.company_area_id,
												},
											},
										},
									});
								}
								if (nativeEvent.event === 'wallets') {
									navigation.navigate('AppCompanyStack', {
										screen: 'CompanyProfileStack',
										params: {
											screen: 'CompanyAreaStack',
											params: {
												screen: 'CompanyAreaAddressWallet',
												params: {
													company_area_address_id: address.id,
												},
											},
										},
									});
								}
								if (nativeEvent.event === 'update') {
									// navigation.navigate('AppCompanyStack', {
									// 	screen: 'CompanyProfileStack',
									// 	params: {
									// 		screen: 'CompanyAreaStack',
									// 		params: {
									// 			screen: 'CompanyAreaAddressUpdate',
									// 			params: {
									// 				company_area_address_id: address.id,
									// 			},
									// 		},
									// 	},
									// });
								}
								if (nativeEvent.event === 'delete') {
									handleDeleteAction(address.id);
								}
							}}
						>
							<Pressable style={styles.card} key={address.id}>
								<View>
									<Icon name="LocationIconSvg" width={20} height={32} />
								</View>
								<View style={styles.cardContent}>
									<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.small} color={colors.gray[900]}>
										{address.address}
									</PalRiderText>
									<View style={styles.badgeRow}>
										<View style={styles.badgePrimary}>
											<PalRiderText fontSize={font.xmini} color={colors.white}>
												{t('screen.company.profile.areas_screen.user', {
													prop: address.company_area_address_users?.length,
												})}
											</PalRiderText>
										</View>
										<View style={styles.badgeSecondary}>
											<PalRiderText fontSize={font.xmini} color={colors.white}>
												{snakeToHumanReadable(address.onboarding_state)}
											</PalRiderText>
										</View>
									</View>
								</View>
							</Pressable>
						</MenuView>
					);
				}}
			/>
		</View>
	);
};

const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.gray[50],
		padding: PADDING.large,
	},
	card: {
		flexDirection: 'row',
		alignItems: 'center',
		padding: PADDING.large,
		borderRadius: PADDING.large,
		backgroundColor: colors.white,
		borderWidth: 1,
		borderColor: colors.gray[300],
	},
	cardContent: {
		flex: 1,
		marginLeft: PADDING.medium,
		gap: PADDING.small,
	},
	badgeRow: {
		flexDirection: 'row',
		gap: PADDING.small,
	},
	badgePrimary: {
		backgroundColor: colors.green[600],
		borderRadius: PADDING.medium,
		paddingVertical: PADDING.mini,
		paddingHorizontal: PADDING.medium,
	},
	badgeSecondary: {
		backgroundColor: colors.gray[600],
		borderRadius: PADDING.medium,
		paddingVertical: PADDING.mini,
		paddingHorizontal: PADDING.medium,
	},
	addContainer: {
		borderRadius: PADDING.large,
		marginTop: PADDING.large,
	},
	addButton: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: PADDING.medium,
		padding: PADDING.medium,
	},
	emptyContainer: {
		flex: 1,
		justifyContent: 'center',
		alignItems: 'center',
		paddingTop: PADDING.xxlarge * 2,
	},
});

export default AppCompanyProfileCompanyAreaAddressesScreen;
