import colors from '@/theme/colors';
import { buttonStyling } from '@/theme/defaults';
import React from 'react';
import {
	ActivityIndicator,
	TouchableOpacity,
	StyleProp,
	StyleSheet,
	TextStyle,
	View,
	ViewStyle,
	TouchableOpacityProps,
	GestureResponderEvent,
} from 'react-native';
import PalRiderText from './PalRiderText';
import { FontFamily } from '@/theme/fonts';
import { PADDING } from '@/theme/responsive';

type ButtonVariant = 'success' | 'warning' | 'error' | 'dark' | 'ghost' | 'primary';
type ButtonSize = 'small' | 'medium' | 'large';

type PalRiderButtonProps = {
	isTextInside?: boolean;
	loading?: boolean;
	variant?: ButtonVariant;
	size?: ButtonSize;
	fullWidth?: boolean;
	textCustomStyle?: StyleProp<TextStyle>;
	contentStyle?: StyleProp<ViewStyle>;
	disabled?: boolean;
	children?: React.ReactNode;
	accessibilityLabel?: string;
	leftIcon?: React.ReactNode;
	rightIcon?: React.ReactNode;
} & TouchableOpacityProps;

const MIN_BUTTON_SIZE = 44; // minimum touch target size (UX best practice)

const PalRiderButton: React.FC<PalRiderButtonProps> = ({
	loading = false,
	fullWidth = false,
	variant = 'dark',
	size = 'small',
	textCustomStyle,
	contentStyle,
	disabled = false,
	isTextInside = false,
	children,
	accessibilityLabel,
	leftIcon,
	rightIcon,
	style,
	onPress,
	...restProps
}) => {
	// Get variant styles
	const variantStyle: StyleProp<ViewStyle> =
		(buttonStyling[variant] as StyleProp<ViewStyle>) || (buttonStyling.dark as StyleProp<ViewStyle>);
	let textStyle: StyleProp<TextStyle> = { color: colors.white };

	// Set up text color based on variant
	if (variant === 'ghost') {
		textStyle = { color: colors.black };
	}
	if (variant === 'primary') {
		textStyle = { color: colors.white };
	}

	// Apply size-specific styles
	let sizeStyle: StyleProp<ViewStyle> = {};
	switch (size) {
		case 'small':
			sizeStyle = {
				borderRadius: PADDING.large,
				paddingHorizontal: PADDING.medium,
				paddingVertical: PADDING.small,
				minHeight: MIN_BUTTON_SIZE,
			};
			break;
		case 'medium':
			sizeStyle = {
				borderRadius: PADDING.large,
				paddingHorizontal: PADDING.large,
				paddingVertical: PADDING.medium,
				minHeight: MIN_BUTTON_SIZE,
			};
			break;
		case 'large':
			sizeStyle = {
				borderRadius: PADDING.large,
				paddingHorizontal: PADDING.xxlarge,
				paddingVertical: PADDING.large,
				minHeight: MIN_BUTTON_SIZE,
			};
			break;
	}

	// Apply full width if needed
	const fullWidthStyle = fullWidth ? { flex: 1 } : {};

	// Combine all styles
	const combinedStyle = [variantStyle, sizeStyle, fullWidthStyle, disabled && styles.disabled, style];

	// Handle text styling
	const finalTextStyle = [textStyle, textCustomStyle];

	// Render the button content
	const renderContent = () => {
		return (
			<View style={[styles.contentWrapper, contentStyle]}>
				{leftIcon && <View style={styles.iconContainer}>{leftIcon}</View>}

				{loading && (
					<ActivityIndicator
						size="small"
						color={variant === 'ghost' ? colors.black : colors.white}
						style={styles.spinner}
					/>
				)}

				{typeof children === 'string' && !isTextInside ? (
					<PalRiderText style={finalTextStyle} fontFamily={FontFamily.Semibold}>
						{children}
					</PalRiderText>
				) : (
					children
				)}

				{rightIcon && <View style={styles.iconContainer}>{rightIcon}</View>}
			</View>
		);
	};

	// Handle press with debounce to prevent multiple triggers
	const handlePress = (e: GestureResponderEvent) => {
		if (disabled || loading) return;
		if (onPress) onPress(e);
	};

	return (
		<TouchableOpacity
			activeOpacity={0.7}
			style={combinedStyle}
			disabled={disabled || loading}
			onPress={handlePress}
			accessibilityLabel={accessibilityLabel || (typeof children === 'string' ? children : undefined)}
			accessibilityRole="button"
			accessibilityState={{ disabled: disabled || loading }}
			hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
			{...restProps}
		>
			{renderContent()}
		</TouchableOpacity>
	);
};

const styles = StyleSheet.create({
	contentWrapper: {
		flexDirection: 'row',
		justifyContent: 'center',
		alignItems: 'center',
		padding: 4,
	},
	spinner: {
		marginRight: 8,
	},
	disabled: {
		opacity: 0.7,
	},
	iconContainer: {
		marginHorizontal: 8,
	},
});

export default PalRiderButton;
