import React from 'react';
import { StyleSheet, View } from 'react-native';
import colors from '@/theme/colors';
import { CompositeScreenProps } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import {
	AppCompanyProfileCompanyAreaParamList,
	AppCompanyProfileParamList,
	AppCompanyTabParamList,
} from '@/navigation/company-navigation';
import { useTranslation } from 'react-i18next';
import PalRiderWizard, { PalRiderWizardStep } from '@/components/PalRiderWizard';
import AppCompanyProfileCompanyAreaAddressCreateLocation from './components/AppCompanyProfileCompanyAreaAddressCreateLocation';
import AppCompanyProfileCompanyAreaAddressCreateDocument from './components/AppCompanyProfileCompanyAreaAddressCreateDocument';
import AppCompanyProfileCompanyAreaAddressCreatePhoto from './components/AppCompanyProfileCompanyAreaAddressCreatePhoto';

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList, 'CompanyAreaAddressCreate'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyAreaStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
			CompositeScreenProps<
				NativeStackScreenProps<RootStackParamList>,
				NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList>
			>
		>
	>
>;

const AppCompanyProfileCompanyAreaAddressCreateScreen: React.FC<Props> = ({ route, navigation }) => {
	const { t } = useTranslation();
	if (!route.params.company_area_id) navigation.goBack();
	return (
		<View style={styles.container}>
			<PalRiderWizard>
				<PalRiderWizardStep title={'Location'}>
					{({ nextStep }) => (
						<>
							<AppCompanyProfileCompanyAreaAddressCreateLocation
								nextStep={nextStep}
								company_area_id={route.params.company_area_id}
							/>
						</>
					)}
				</PalRiderWizardStep>
				<PalRiderWizardStep title={'Documents'}>
					{({ nextStep, prevStep }) => (
						<>
							<AppCompanyProfileCompanyAreaAddressCreateDocument nextStep={nextStep} prevStep={prevStep} />
						</>
					)}
				</PalRiderWizardStep>
				<PalRiderWizardStep title={'Photos'}>
					{({ nextStep, prevStep }) => (
						<>
							<AppCompanyProfileCompanyAreaAddressCreatePhoto nextStep={nextStep} prevStep={prevStep} />
						</>
					)}
				</PalRiderWizardStep>
			</PalRiderWizard>
		</View>
	);
};
const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.white,
	},
});
export default AppCompanyProfileCompanyAreaAddressCreateScreen;
