import { createApi } from '@reduxjs/toolkit/query/react';
import { PaginationDataResultT, SuccessfulResponse } from 'palriderapptypes';
import { CourierDocumentDTO, CreateCourierDocumentRequestDTO } from 'palriderapptypes/courier';
import { baseQueryConfigWithReAuth } from 'src/services/api/baseQueryConfig.ts';

export const courierDocumentApi = createApi({
	reducerPath: 'courierDocument',
	baseQuery: baseQueryConfigWithReAuth,
	refetchOnMountOrArgChange: 30,
	endpoints: (builder) => ({
		getCourierDocuments: builder.query<PaginationDataResultT<CourierDocumentDTO>, string>({
			query(courier_id) {
				return {
					url: `courier/${courier_id}/documents`,
					method: 'GET',
				};
			},
		}),
		getCourierDocumentLink: builder.query<Blob, string>({
			query(courier_document_id) {
				return {
					url: `courier-document/${courier_document_id}/link`,
					method: 'GET',
					headers: {
						'x-response-type': 'blob',
					},
					responseHandler: async (response) => {
						const blob = await response.blob();
						const contentType = response.headers.get('Content-Type') || 'application/octet-stream';
						const typedBlob = new Blob([blob], { type: contentType, lastModified: 0 });
						return typedBlob;
					},
				};
			},
		}),
		storeCourierDocument: builder.mutation<SuccessfulResponse, CreateCourierDocumentRequestDTO>({
			query(body) {
				const formData = new FormData();
				formData.append("document", body.document);
				formData.append("type", body.type);
				return {
					url: `courier-document`,
					method: 'POST',
					headers: {
						'Content-Type': 'multipart/form-data',
					},
					body: formData,
				};
			},
		}),
	}),
});

export const { useLazyGetCourierDocumentsQuery, useLazyGetCourierDocumentLinkQuery, useStoreCourierDocumentMutation } = courierDocumentApi;
