import React from 'react';
import { Pressable, StyleSheet, View, TouchableOpacity } from 'react-native';
import colors from '@/theme/colors';
import PalRiderText from '@/components/PalRiderText';
import { FontFamily } from '@/theme/fonts';
import { font, PADDING } from '@/theme/responsive';
import Icon from '@/components/Icon';
import PalRiderTextInput from '@/components/PalRiderTextInput';

type PalRiderInfoRowProps = {
	label: string;
	value?: string | null;
	editable?: boolean;
	showInput?: boolean;
	inputValue?: string;
	onChangeText?: (text: string) => void;
	onSubmit?: () => void;
	onPress?: () => void;
};

export const PalRiderInfoRow: React.FC<PalRiderInfoRowProps> = ({
	label,
	value,
	editable,
	showInput,
	inputValue,
	onChangeText,
	onSubmit,
	onPress,
}) => {
	if (showInput) {
		return (
			<View style={styles.updateRow}>
				<PalRiderTextInput
					containerStyle={{ flex: 1 }}
					title={label}
					defaultValue={inputValue}
					onChangeText={onChangeText}
					onEndEditing={(e) => {
						if (e.nativeEvent.text && onChangeText) {
							onChangeText(e.nativeEvent.text);
							onSubmit?.();
						}
					}}
					rightComponent={
						<TouchableOpacity style={styles.updateBtn} onPress={onSubmit}>
							<Icon name="CheckCircleIconSvg" color={colors.green[600]} width={18} height={18} />
						</TouchableOpacity>
					}
				/>
			</View>
		);
	}

	return (
		<Pressable
			style={({ pressed }) => [styles.row, pressed && { backgroundColor: colors.gray[100] }]}
			onPress={editable ? onPress : undefined}
		>
			<PalRiderText style={styles.label}>{label}</PalRiderText>
			<View style={styles.valueContainer}>
				<PalRiderText style={[styles.valueText, !value && { color: colors.gray[400], fontStyle: 'italic' }]}>
					{value || 'Not available'}
				</PalRiderText>
				{editable && <Icon name="EditIconSvg" width={20} height={20} />}
			</View>
		</Pressable>
	);
};

type PalRiderInfoCardProps = {
	title: string;
	children: React.ReactNode;
};

export const PalRiderInfoCard: React.FC<PalRiderInfoCardProps> = ({ title, children }) => (
	<View style={styles.card}>
		<PalRiderText style={styles.sectionTitle}>{title}</PalRiderText>
		{children}
	</View>
);

const styles = StyleSheet.create({
	card: {
		backgroundColor: colors.white,
		borderRadius: 24,
		paddingVertical: PADDING.large,
		shadowColor: '#000',
		shadowOffset: { width: 0, height: 6 },
		shadowOpacity: 0.1,
		shadowRadius: 12,
		elevation: 6,
	},
	sectionTitle: {
		fontFamily: FontFamily.Bold,
		fontSize: font.medium,
		color: colors.gray[800],
		paddingHorizontal: PADDING.large,
		paddingBottom: PADDING.medium,
	},
	row: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
		paddingHorizontal: PADDING.large,
		paddingVertical: PADDING.large,
		borderTopWidth: StyleSheet.hairlineWidth,
		borderColor: colors.gray[200],
	},
	label: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.small,
		color: colors.gray[700],
	},
	valueContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: PADDING.small,
		maxWidth: '70%',
	},
	valueText: {
		fontFamily: FontFamily.Regular,
		fontSize: font.small,
		color: colors.gray[600],
	},
	updateRow: {
		flexDirection: 'row',
		alignItems: 'center',
		paddingHorizontal: PADDING.large,
		paddingVertical: PADDING.medium,
	},
	updateBtn: {
		marginLeft: PADDING.small,
		borderWidth: 1,
		borderColor: colors.green[600],
		padding: PADDING.small,
		borderRadius: PADDING.large,
		alignItems: 'center',
		justifyContent: 'center',
	},
});
