import React, { useEffect, useState } from 'react';
import {
	FlatList,
	ScrollView,
	StyleSheet,
	TouchableOpacity,
	View,
	LayoutAnimation,
	Platform,
	UIManager,
} from 'react-native';
import PalRiderText from '@/components/PalRiderText';
import colors from '@/theme/colors';
import { useModal } from '@/components/ModalProvider';
import { FetchBaseQueryErrorExpected, formatHumanReadableDate, snakeToHumanReadable } from '@/utils';
import WarningModal from '@/components/custom-modal/WarningModal';
import { FontFamily } from '@/theme/fonts';
import { font, PADDING } from '@/theme/responsive';
import PullToRefreshView from '@/components/PullDownToRefreshView';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { CompositeScreenProps } from '@react-navigation/native';
import {
	AppCompanyProfileCompanyAreaParamList,
	AppCompanyProfileParamList,
	AppCompanyTabParamList,
} from '@/navigation/company-navigation';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { RootStackParamList } from '@/navigation';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { useTranslation } from 'react-i18next';
import {
	CompanyAreaAddressWalletTransactionDTO,
	CompanyAreaAddressWalletTransactionType,
} from 'palriderapptypes/company';
import { useLazyGetCompanyAreaAddressWalletTransactionListQuery } from '@/services/api/company/company-area-address-wallet';
import Icon from '@/components/Icon';

// Enable LayoutAnimation on Android
if (Platform.OS === 'android' && UIManager.setLayoutAnimationEnabledExperimental) {
	UIManager.setLayoutAnimationEnabledExperimental(true);
}

const { format } = Intl.NumberFormat('en-UK', {
	currency: 'GBP',
	style: 'currency',
});

const WalletTransactionItemRender: React.FC<{ walletItem: CompanyAreaAddressWalletTransactionDTO }> = ({
	walletItem,
}) => {
	const [showItemList, setShowItemList] = useState(false);

	const toggleExpand = () => {
		LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);
		setShowItemList((prev) => !prev);
	};

	const transactionTypeToColor = (transaction_type: CompanyAreaAddressWalletTransactionType): string => {
		switch (transaction_type) {
			case 'add':
				return colors.green[600];
			case 'subtract':
				return colors.red[400];
			case 'start':
				return colors.blue[400];
		}
	};

	return (
		<View style={styles.card}>
			<View style={styles.row}>
				<View style={styles.transactionIconContainer}>
					<Icon name="PoundBanknoteIconSvg" width={28} height={28} />
				</View>

				<View style={styles.transactionItemContainer}>
					<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.small}>
						{snakeToHumanReadable(walletItem.type)}
					</PalRiderText>
					<PalRiderText fontSize={font.xmini} color={colors.gray[500]}>
						{formatHumanReadableDate(walletItem.created_at)}
					</PalRiderText>
				</View>

				<View style={styles.transactionAmountContainer}>
					<PalRiderText
						color={transactionTypeToColor(walletItem.type)}
						fontSize={font.medium}
						fontFamily={FontFamily.Semibold}
					>
						{format(walletItem.amount)}
					</PalRiderText>
				</View>

				{walletItem.type !== 'start' && (
					<TouchableOpacity
						style={[
							styles.chevronBtn,
							{
								transform: [{ rotate: showItemList ? '90deg' : '0deg' }],
							},
						]}
						onPress={toggleExpand}
					>
						<Icon name="ChevronRightIconSvg" width={20} height={20} />
					</TouchableOpacity>
				)}
			</View>

			{showItemList && (
				<View style={styles.itemListContainer}>
					<FlatList
						data={walletItem.company_area_address_wallet_transaction_items}
						keyExtractor={(item, idx) => `${walletItem.id}-${idx}`}
						ItemSeparatorComponent={() => <View style={styles.itemSeparator} />}
						renderItem={({ item }) => (
							<View style={styles.itemRow}>
								<View style={{ flex: 1, gap: PADDING.mini }}>
									<PalRiderText fontSize={font.mini} fontFamily={FontFamily.Semibold}>
										{item.name}
									</PalRiderText>
									<PalRiderText fontSize={font.xmini} color={colors.gray[600]}>
										{item.description}
									</PalRiderText>
								</View>
								<PalRiderText fontSize={font.small} color={colors.gray[800]}>
									{format(item.amount)}
								</PalRiderText>
							</View>
						)}
					/>
				</View>
			)}
		</View>
	);
};

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList, 'CompanyAreaAddressWalletTransaction'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyAreaStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
			CompositeScreenProps<
				NativeStackScreenProps<RootStackParamList>,
				NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList>
			>
		>
	>
>;

const AppCompanyProfileCompanyAreaWalletTransactionListScreen: React.FC<Props> = ({ route }) => {
	const [getCompanyAreaWalletTransactionList, { data }] = useLazyGetCompanyAreaAddressWalletTransactionListQuery();
	const { showGlobalModal, hideGlobalModal } = useModal();
	const { t } = useTranslation();

	const loadWallet = async () => {
		showGlobalModal({
			children: <LoadingModal />,
			backgroundColor: colors.transparent,
		});
		const res = await getCompanyAreaWalletTransactionList({
			company_area_address_wallet_id: route.params.company_area_address_wallet_id,
			page: 1,
			size: 100,
		});
		if (res.error) {
			const error = res.error as FetchBaseQueryErrorExpected;
			showGlobalModal({
				children: <WarningModal text={error.data.title} />,
			});
		}
		hideGlobalModal();
	};

	useEffect(() => {
		loadWallet();
	}, []);

	return (
		<PullToRefreshView onRefresh={loadWallet}>
			{data && (
				<ScrollView style={styles.container}>
					<FlatList
						scrollEnabled={false}
						data={data.data}
						keyExtractor={(x) => x.id}
						contentContainerStyle={{ padding: PADDING.large }}
						renderItem={({ item }) => <WalletTransactionItemRender walletItem={item} />}
						ListHeaderComponent={
							<View style={styles.headerContainer}>
								<PalRiderText fontFamily={FontFamily.Bold} fontSize={font.large}>
									{t('screen.titles.company.profile_screen.area_wallet_transaction_list')}
								</PalRiderText>
							</View>
						}
						ListEmptyComponent={
							<View style={styles.noTransactionContainer}>
								<Icon name="PoundBanknoteIconSvg" width={72} height={72} />
								<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.medium}>
									{t('common.no_transaction')}
								</PalRiderText>
							</View>
						}
					/>
				</ScrollView>
			)}
		</PullToRefreshView>
	);
};

const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.gray[50],
	},
	headerContainer: {
		paddingVertical: PADDING.large,
	},
	card: {
		backgroundColor: colors.white,
		borderRadius: PADDING.medium,
		padding: PADDING.large,
		marginBottom: PADDING.large,
		shadowColor: '#000',
		shadowOpacity: 0.08,
		shadowRadius: 8,
		elevation: 3,
	},
	row: {
		flexDirection: 'row',
		alignItems: 'center',
	},
	transactionIconContainer: {
		width: 44,
		height: 44,
		borderRadius: 22,
		backgroundColor: colors.gray[100],
		justifyContent: 'center',
		alignItems: 'center',
		marginRight: PADDING.medium,
	},
	transactionItemContainer: {
		flex: 1,
	},
	transactionAmountContainer: {
		alignItems: 'flex-end',
		justifyContent: 'center',
	},
	chevronBtn: {
		padding: PADDING.small,
		justifyContent: 'center',
		alignItems: 'center',
	},
	itemListContainer: {
		marginTop: PADDING.medium,
		backgroundColor: colors.gray[50],
		borderRadius: PADDING.small,
		padding: PADDING.medium,
	},
	itemRow: {
		flexDirection: 'row',
		alignItems: 'center',
		justifyContent: 'space-between',
	},
	itemSeparator: {
		height: 1,
		backgroundColor: colors.gray[200],
		marginVertical: PADDING.small,
	},
	noTransactionContainer: {
		flex: 1,
		alignItems: 'center',
		justifyContent: 'center',
		paddingVertical: PADDING.xxlarge,
		gap: PADDING.medium,
	},
});

export default AppCompanyProfileCompanyAreaWalletTransactionListScreen;
