import { BottomSheetModalProvider } from '@gorhom/bottom-sheet';
import React, { useEffect } from 'react';
import { Appearance, Platform, StatusBar } from 'react-native';
import 'react-native-gesture-handler';
import 'react-native-url-polyfill/auto';
import { GestureHandlerRootView } from 'react-native-gesture-handler';
import { SafeAreaProvider, SafeAreaView } from 'react-native-safe-area-context';
import { Provider as StoreProvider } from 'react-redux';
import { PersistGate } from 'redux-persist/integration/react';
import { persistor, store } from './src/redux/store';
import { ModalProvider } from './src/components/ModalProvider';
import 'react-native-get-random-values';
import RootNavigation from './src/navigation';
import { StripeProvider } from '@stripe/stripe-react-native';
import Geolocation from '@react-native-community/geolocation';
import AppUserOnboardingState from './src/components/onboarding_state/AppUserOnboardingState';
import { LogLevel, OneSignal } from 'react-native-onesignal';
import AsyncStorage from '@react-native-async-storage/async-storage';
import * as RNLocalize from 'react-native-localize';
import i18n from './src/utils/localization';

function App(): React.JSX.Element {
	OneSignal.Debug.setLogLevel(LogLevel.Debug);
	OneSignal.initialize('fc2e5980-10f8-4f5b-9f55-11d7061d3c42');

	useEffect(() => {
		Geolocation.setRNConfiguration({
			skipPermissionRequests: false,
			authorizationLevel: 'always',
			enableBackgroundLocationUpdates: true,
			locationProvider: 'auto',
		});
		Appearance.setColorScheme('light');
	}, []);

	useEffect(() => {
		const locale = RNLocalize.getLocales()[0].languageCode;
		i18n.changeLanguage(locale);
	}, []);

	useEffect(() => {
		const listener = OneSignal.User.pushSubscription.addEventListener('change', async (event) => {
			if (event.current && event.current.id) {
				await AsyncStorage.setItem('APP_USER_ID', event.current.id);
			}
		});

		return () => {
			OneSignal.User.pushSubscription.removeEventListener('change', listener as any);
		};
	}, []);

	return (
		<StripeProvider
			publishableKey="pk_test_51Qj5JbDOfUJaU2SioPf5iRUDAL5dlKIs0ZS5WgAbj9mlGkddp71unmK7ac5vwKTRnF02321YmpPzNCE95RqTSJvS00DII7I0Mp"
			merchantIdentifier="merchant.identifier"
			urlScheme="url-scheme"
		>
			<SafeAreaProvider>
				<StoreProvider store={store}>
					<StatusBar translucent hidden backgroundColor={'transparent'} />
					<ModalProvider>
						<PersistGate persistor={persistor}>
							<AppUserOnboardingState>
								<GestureHandlerRootView style={{ flex: 1 }}>
									<BottomSheetModalProvider>
										<SafeAreaView
											style={{ flex: 1, backgroundColor: 'transparent' }}
											edges={Platform.OS === 'ios' ? [] : ['bottom', 'left', 'right']}
										>
											<RootNavigation />
										</SafeAreaView>
									</BottomSheetModalProvider>
								</GestureHandlerRootView>
							</AppUserOnboardingState>
						</PersistGate>
					</ModalProvider>
				</StoreProvider>
			</SafeAreaProvider>
		</StripeProvider>
	);
}

export default App;
