import { FileType } from '@/@types';
import PalRiderText from '@/components/PalRiderText.tsx';
import colors from '@/theme/colors.ts';
import { FontFamily } from '@/theme/fonts.ts';
import { font, normalize, PADDING } from '@/theme/responsive.ts';
import React from 'react';
import { Pressable, ScrollView, StyleSheet, View } from 'react-native';
import { globalStyles } from '@/utils/global-styles';
import Icon from '@/components/Icon';
type Props = {
	onPress: () => void;
	value: FileType | null;
	error: string | undefined;
	title: string;
};
const SignUpCourierDocumentInfoScreenDocument: React.FC<Props> = (props) => {
	const { value, error, title, onPress } = props;
	return (
		<View style={styles.documentContainer}>
			<View style={{ flexDirection: 'row', columnGap: normalize(2) }}>
				<PalRiderText style={styles.documentTitleText}>{title}</PalRiderText>
				<PalRiderText color={colors.red[600]} fontFamily={FontFamily.Semibold}>
					*
				</PalRiderText>
			</View>
			<Pressable style={styles.documentUploadButton} onPress={() => onPress()}>
				<Icon name="UploadIconSvg" width={16} height={16} />
				{value && (
					<ScrollView horizontal showsHorizontalScrollIndicator={false}>
						<View onStartShouldSetResponder={() => true}>
							<PalRiderText fontFamily={FontFamily.Semibold}>{title} Photo</PalRiderText>
						</View>
					</ScrollView>
				)}
				{!value && <PalRiderText>Please upload well taken photo.</PalRiderText>}
			</Pressable>
			{error && <PalRiderText style={globalStyles.errorTextStyle}>{error}</PalRiderText>}
		</View>
	);
};
const styles = StyleSheet.create({
	documentContainer: {
		paddingVertical: PADDING.small,
	},
	documentTitleText: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.small,
	},
	documentUploadButton: {
		padding: PADDING.large,
		borderWidth: 1,
		gap: PADDING.large,
		marginTop: PADDING.large,
		borderRadius: PADDING.large,
		alignItems: 'center',
		flexDirection: 'row',
		borderColor: colors.gray[300],
		overflow: 'hidden',
	},
});
export default SignUpCourierDocumentInfoScreenDocument;
