import React from 'react';
import { StyleSheet, TouchableOpacity, View } from 'react-native';
import Modal from 'react-native-modal';
import { SafeAreaView, useSafeAreaInsets } from 'react-native-safe-area-context';
import PalRiderText from './PalRiderText';
import colors from '@/theme/colors';
import { font, PADDING } from '@/theme/responsive';
import { FontFamily } from '@/theme/fonts';
import PalRiderButton from './PalRiderButton';

type PalRiderBottomSelectModalProps = {
	data: Array<{
		text: string;
		icon?: React.ReactNode;
		color?: string;
		isErrorSelection?: boolean;
		onPress: () => void;
	}>;
	title?: string;
	isVisible: boolean;
	isCoverScreen?: boolean;
	cancelOnPress?: () => void;
};

const PalRiderBottomSelectModal: React.FC<PalRiderBottomSelectModalProps> = ({
	isCoverScreen = false,
	data,
	title,
	isVisible,
	cancelOnPress,
}) => {
	const insets = useSafeAreaInsets();

	if (!data) return null;

	const handleClose = () => {
		if (typeof cancelOnPress === 'function') {
			cancelOnPress();
		}
	};

	return (
		<Modal
			isVisible={isVisible}
			style={styles.modalContainer}
			animationInTiming={300}
			animationOutTiming={300}
			coverScreen={isCoverScreen}
			backdropOpacity={0.7}
			hideModalContentWhileAnimating={false}
			onBackButtonPress={handleClose}
			onBackdropPress={handleClose}
			useNativeDriverForBackdrop={true}
			statusBarTranslucent={true}
		>
			<SafeAreaView style={[styles.contentContainer]} edges={['bottom']}>
				<View style={styles.container}>
					<View style={styles.contentView}>
						{title && (
							<PalRiderText color={colors.gray[500]} style={styles.title}>
								{title}
							</PalRiderText>
						)}
						{data.map((item, index) => {
							const textColor = item?.color;
							const isErrorSelection = item?.isErrorSelection;
							return (
								<TouchableOpacity
									key={`key_${index}`}
									style={[
										styles.selectView,
										{
											borderBottomWidth: data.length !== index + 1 ? 0.4 : 0,
											justifyContent: item.icon ? 'flex-start' : 'center',
											borderBottomColor: colors.gray[200],
										},
									]}
									activeOpacity={0.7}
									onPress={() => {
										// Small delay to ensure smooth animation
										setTimeout(() => {
											item.onPress();
										}, 100);
									}}
								>
									{item.icon && item.icon}
									<PalRiderText
										fontFamily={FontFamily.Bold}
										color={textColor ? textColor : isErrorSelection ? colors.red[600] : colors.black}
										style={[styles.selectText, { marginLeft: item?.icon ? 18 : 0 }]}
									>
										{item.text}
									</PalRiderText>
								</TouchableOpacity>
							);
						})}
					</View>
					<PalRiderButton variant="dark" onPress={handleClose}>
						<PalRiderText color={colors.white}>Close</PalRiderText>
					</PalRiderButton>
				</View>
			</SafeAreaView>
		</Modal>
	);
};

const styles = StyleSheet.create({
	modalContainer: {
		justifyContent: 'flex-end',
		margin: 0,
	},
	container: {
		justifyContent: 'flex-end',
	},
	contentContainer: {
		backgroundColor: colors.white,
		borderTopLeftRadius: 20,
		borderTopRightRadius: 20,
		padding: PADDING.large,
		height: 'auto',
	},
	contentView: {
		marginBottom: PADDING.large,
	},
	title: {
		fontSize: font.medium,
		textAlign: 'center',
		marginBottom: PADDING.medium,
		fontFamily: FontFamily.Semibold,
	},
	selectView: {
		flexDirection: 'row',
		alignItems: 'center',
		paddingVertical: PADDING.large,
		borderBottomColor: colors.gray[200],
		minHeight: 50,
	},
	selectText: {
		fontSize: font.medium,
		flex: 1,
	},
});

export default PalRiderBottomSelectModal;
