import React, { useCallback } from 'react';
import { View, ScrollView, StyleSheet, RefreshControl, Alert } from 'react-native';
import PalRiderText from '@/components/PalRiderText.tsx';
import PalRiderButton from '@/components/PalRiderButton';
import colors from '@/theme/colors.ts';
import { font, PADDING } from '@/theme/responsive';
import { FontFamily } from '@/theme/fonts';
import { usePalRiderOrderCheckout } from '@/hooks/usePalRiderCheckout';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { useLazyGetCompanyWalletQuery } from '@/services/api/company/company-wallet';
import { useAppSelector } from '@/redux/hooks';
import { CompositeScreenProps, useFocusEffect } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import { AppCompanyProfileParamList, AppCompanyTabParamList } from '@/navigation/company-navigation';
import { useTranslation } from 'react-i18next';

const { format } = Intl.NumberFormat('en-UK', {
	currency: 'GBP',
	style: 'currency',
});

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyWallet'>,
	CompositeScreenProps<
		BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
		NativeStackScreenProps<RootStackParamList>
	>
>;

const AppCompanyProfileCompanyWalletScreen: React.FC<Props> = ({ navigation }) => {
	const [getCompanyWallet, { data, isFetching, isLoading }] = useLazyGetCompanyWalletQuery();
	const user = useAppSelector((x) => x.userSlice.user);
	const { initializeAndOpenPaymentSheet } = usePalRiderOrderCheckout();
	const { showGlobalModal, hideGlobalModal } = useModal();
	const { t } = useTranslation();

	const loadCompanyWallet = async () => {
		showGlobalModal({ children: <LoadingModal />, backgroundColor: colors.transparent, preventHiding: true });
		if (!user || !user.company_area_address_user) return;
		await getCompanyWallet(user.company_area_address_user.company_wallet_id);
		hideGlobalModal();
	};

	useFocusEffect(
		useCallback(() => {
			loadCompanyWallet();
		}, []),
	);

	const handleAddFunds = async (amount: number) => {
		if (!data?.data) return;
		await initializeAndOpenPaymentSheet({
			amount: amount * 100,
			company_wallet_id: data.data.id,
			type: 'main_wallet',
			whenSucceeded: () => loadCompanyWallet(),
		});
	};

	return (
		<ScrollView
			style={styles.container}
			refreshControl={<RefreshControl refreshing={isFetching || isLoading} onRefresh={loadCompanyWallet} />}
			contentContainerStyle={{ paddingBottom: PADDING.xxlarge }}
		>
			{/* HEADER WALLET CARD */}
			<View style={styles.walletCard}>
				<PalRiderText fontSize={font.large} fontFamily={FontFamily.Bold} color={colors.gray[900]}>
					{data?.data?.name || t('loading')}
				</PalRiderText>
				<PalRiderText fontSize={font.xxlarge} fontFamily={FontFamily.Bold} color={colors.orange[600]}>
					{format(data?.data?.balance || 0)}
				</PalRiderText>
			</View>

			{/* QUICK ADD FUNDS */}
			<View style={styles.quickAdd}>
				<PalRiderButton onPress={() => handleAddFunds(25)} style={styles.addButton}>
					<PalRiderText fontFamily={FontFamily.Bold} color={colors.white}>
						+£25
					</PalRiderText>
				</PalRiderButton>
				<PalRiderButton onPress={() => handleAddFunds(50)} style={styles.addButton}>
					<PalRiderText fontFamily={FontFamily.Bold} color={colors.white}>
						+£50
					</PalRiderText>
				</PalRiderButton>
				<PalRiderButton onPress={() => handleAddFunds(100)} style={styles.addButton}>
					<PalRiderText fontFamily={FontFamily.Bold} color={colors.white}>
						+£100
					</PalRiderText>
				</PalRiderButton>
				<PalRiderButton
					onPress={() =>
						Alert.prompt(
							t('common.amount'),
							t('common.amount') + ' ?',
							[
								{ text: 'Cancel', style: 'cancel' },
								{
									text: 'OK',
									onPress: (text) => handleAddFunds(Number(text)),
									style: 'default',
								},
							],
							'plain-text',
							'',
							'number-pad',
						)
					}
					style={styles.addButtonCustom}
				>
					<PalRiderText fontSize={font.small} fontFamily={FontFamily.Bold} color={colors.white}>
						Custom
					</PalRiderText>
				</PalRiderButton>
			</View>

			{/* ACTION BUTTONS */}
			<View style={styles.actions}>
				<PalRiderButton
					variant="success"
					onPress={() =>
						navigation.navigate('AppCompanyStack', {
							screen: 'CompanyProfileStack',
							params: { screen: 'CompanyWalletTransfer', params: { company_wallet_id: data?.data?.id! } },
						})
					}
					style={styles.actionButton}
				>
					<PalRiderText fontFamily={FontFamily.Bold} color={colors.white}>
						Transfer
					</PalRiderText>
				</PalRiderButton>

				<PalRiderButton
					variant="primary"
					onPress={() =>
						navigation.navigate('AppCompanyStack', {
							screen: 'CompanyProfileStack',
							params: { screen: 'CompanyWalletTransferRequests', params: { company_wallet_id: data?.data?.id! } },
						})
					}
					style={styles.actionButton}
				>
					<PalRiderText fontFamily={FontFamily.Bold} color={colors.white}>
						Transfer Requests
					</PalRiderText>
				</PalRiderButton>
			</View>

			<PalRiderButton
				variant="dark"
				onPress={() =>
					navigation.navigate('AppCompanyStack', {
						screen: 'CompanyProfileStack',
						params: { screen: 'CompanyWalletTransaction', params: { company_wallet_id: data?.data?.id! } },
					})
				}
				style={styles.actionButton}
			>
				<PalRiderText fontFamily={FontFamily.Bold} color={colors.white}>
					Transactions
				</PalRiderText>
			</PalRiderButton>
		</ScrollView>
	);
};

const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.gray[50],
		padding: PADDING.large,
	},
	walletCard: {
		backgroundColor: colors.white,
		borderRadius: 16,
		padding: PADDING.xxlarge,
		alignItems: 'center',
		marginBottom: PADDING.xxlarge,
		shadowColor: colors.black,
		shadowOffset: { width: 0, height: 5 },
		shadowOpacity: 0.1,
		shadowRadius: 10,
		elevation: 3,
	},
	quickAdd: {
		flexDirection: 'row',
		flexWrap: 'wrap',
		justifyContent: 'space-between',
		marginBottom: PADDING.xxlarge,
	},
	addButton: {
		flex: 1,
		margin: PADDING.small,
		backgroundColor: colors.orange[600],
	},
	addButtonCustom: {
		flex: 1,
		margin: PADDING.small,
		backgroundColor: colors.gray[700],
	},
	actions: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		marginBottom: PADDING.large,
	},
	actionButton: {
		flex: 1,
		marginHorizontal: PADDING.small,
	},
});

export default AppCompanyProfileCompanyWalletScreen;
