import React, { useCallback, useEffect } from 'react';
import { StyleSheet, View, TouchableWithoutFeedback, Dimensions, DimensionValue } from 'react-native';
import Animated, { useSharedValue, useAnimatedStyle, withSpring, withTiming, runOnJS } from 'react-native-reanimated';

const { height: SCREEN_HEIGHT, width: SCREEN_WIDTH } = Dimensions.get('window');

// Updated PalRiderCustomModalProps
export type PalRiderCustomModalProps = {
	isVisible: boolean;
	onClose: () => void;
	children: React.ReactNode;
	backgroundColor?: string;
	overlayOpacity?: number;
	minWidth?: number;
	maxWidth?: number;
	minHeight?: DimensionValue;
	maxHeight?: number;
	padding?: number;
	springConfig?: {
		damping: number;
		mass: number;
		stiffness: number;
	};
	whenClose?: () => void;
	closeAfterDelay?: number;
	preventHiding?: boolean; // New prop to prevent hiding
};

const PalRiderCustomModal = ({
	isVisible,
	onClose,
	children,
	backgroundColor = 'white',
	overlayOpacity = 0.5,
	minWidth = SCREEN_WIDTH * 0.8,
	maxWidth = SCREEN_WIDTH * 0.9,
	minHeight = 'auto',
	maxHeight = SCREEN_HEIGHT * 0.8,
	padding = 16,
	springConfig = {
		damping: 15,
		mass: 0.7,
		stiffness: 100,
	},
	whenClose,
	closeAfterDelay,
	preventHiding = false, // Default preventHiding to false
}: PalRiderCustomModalProps) => {
	const translateY = useSharedValue(SCREEN_HEIGHT);
	const scale = useSharedValue(0.8);
	const overlayOpacityValue = useSharedValue(0);

	const showModal = useCallback(() => {
		translateY.value = withSpring(0, springConfig);
		scale.value = withSpring(1, springConfig);
		overlayOpacityValue.value = withTiming(overlayOpacity, { duration: 300 });
	}, [springConfig, overlayOpacity]);

	const hideModal = useCallback(() => {
		translateY.value = withSpring(SCREEN_HEIGHT, springConfig);
		scale.value = withSpring(0.8, springConfig);
		overlayOpacityValue.value = withTiming(0, { duration: 300 }, () => {
			if (onClose) runOnJS(onClose)();
			if (whenClose) runOnJS(whenClose)();
		});
	}, [springConfig, onClose, whenClose]);

	useEffect(() => {
		if (isVisible) {
			showModal();
			if (closeAfterDelay) {
				setTimeout(() => {
					hideModal();
				}, closeAfterDelay);
			}
		}
	}, [isVisible, showModal, hideModal]);

	const modalAnimatedStyle = useAnimatedStyle(() => ({
		transform: [{ translateY: translateY.value }, { scale: scale.value }],
	}));

	const overlayAnimatedStyle = useAnimatedStyle(() => ({
		opacity: overlayOpacityValue.value,
	}));

	return (
		<>
			{isVisible && (
				<View style={[StyleSheet.absoluteFill, { zIndex: 9999 }]}>
					<TouchableWithoutFeedback onPress={!preventHiding ? hideModal : undefined}>
						<Animated.View style={[styles.overlay, overlayAnimatedStyle]} />
					</TouchableWithoutFeedback>

					<View style={styles.modalWrapper} pointerEvents="box-none">
						<TouchableWithoutFeedback>
							<Animated.View
								style={[
									styles.modalContainer,
									modalAnimatedStyle,
									{
										backgroundColor,
										minWidth,
										maxWidth,
										minHeight,
										maxHeight,
										padding,
									},
								]}
							>
								<View style={styles.contentWrapper}>{children}</View>
							</Animated.View>
						</TouchableWithoutFeedback>
					</View>
				</View>
			)}
		</>
	);
};

const styles = StyleSheet.create({
	overlay: {
		...StyleSheet.absoluteFillObject,
		backgroundColor: 'black',
		zIndex: 1,
	},
	modalWrapper: {
		...StyleSheet.absoluteFillObject,
		justifyContent: 'center',
		alignItems: 'center',
		zIndex: 2,
	},
	modalContainer: {
		borderRadius: 12,
		shadowColor: '#000',
		shadowOffset: {
			width: 0,
			height: 0,
		},
		shadowOpacity: 0.25,
		shadowRadius: 3.84,
	},
	contentWrapper: {
		flexGrow: 0,
	},
});

export default PalRiderCustomModal;
