import React, { ReactNode, useCallback, useMemo } from 'react';
import { Pressable, StyleSheet, View } from 'react-native';
import { useFormik } from 'formik';
import { KeyboardAwareScrollView } from 'react-native-keyboard-aware-scroll-view';
import Animated, { FadeInDown, FadeOutUp } from 'react-native-reanimated';
import Dropdown from 'react-native-input-select';
import { useNavigation } from '@react-navigation/native';
import { useTranslation } from 'react-i18next';
import { number, object, string } from 'yup';

import PalRiderCurrencyInput from '@/components/PalRiderCurrencyInput';
import PalRiderText from '@/components/PalRiderText';
import PalRiderButton from '@/components/PalRiderButton';
import { RollingCurrencyText } from '@/components/RollingCurrencyText';

import colors from '@/theme/colors';
import { font, normalize, PADDING } from '@/theme/responsive';
import { FontFamily } from '@/theme/fonts';
import { buttonStyling } from '@/theme/defaults';
import { globalStyles } from '@/utils/global-styles';

import { useAppDispatch, useAppSelector } from '@/redux/hooks';
import { setCallRiderState } from '@/redux/slices/callRiderSlice';

import { useGetCompanyAreaAddressWalletListQuery } from '@/services/api/company/company-area-address';

import { CompanyAreaAddressUserDTO } from 'palriderapptypes/company';

// ---------- Constants & Helpers ----------
const WORK_HOURS_COUNT = 24;
const HOUR_INCREMENT = 0.5;
const GROWTH_RATE = 0.2;
const MAX_WORKING_HOUR = 21;

const formatCurrency = (amount: number): string =>
	new Intl.NumberFormat('en-UK', {
		currency: 'GBP',
		style: 'currency',
	}).format(amount);

const createTimeOptions = () => {
	const now = new Date();
	const currentHour = now.getHours();
	const times: { label: string; value: string }[] = [];
	for (let i = currentHour + 1; i <= MAX_WORKING_HOUR; i++) {
		const period = i >= 12 ? 'pm' : 'am';
		const formattedHour = i > 12 ? i - 12 : i;
		times.push({ label: `${formattedHour}${period}`, value: i.toString() });
	}
	return [{ label: 'Now', value: '0' }, ...times];
};

const createWorkHourOptions = () =>
	Array.from({ length: WORK_HOURS_COUNT }, (_, i) => {
		const value = HOUR_INCREMENT + i * HOUR_INCREMENT;
		const label = Number.isInteger(value) ? `${value} Hour` : `${Math.floor(value)}.30 Hour`;
		return { label, value: value.toString() };
	});

const cleanCurrencyInput = (input: string) => {
	const cleaned = input.replace(/[^0-9.]/g, '');
	if (!cleaned) return cleaned;
	const decimalCount = cleaned.split('.').length - 1;
	return decimalCount <= 1 ? cleaned : input;
};

const useFormValidation = (t: (key: string, opts?: any) => string) =>
	useMemo(
		() =>
			object().shape({
				hourly_rate: number()
					.transform((val, orig) => (typeof orig === 'string' ? parseFloat(orig.replace(/,/g, '')) : val))
					.typeError('Amount must be a number')
					.required()
					.min(0.1)
					.label(t('common.hourly_rate')),
				company_area_address_wallet_id: string().required(t('validation.required', { field: t('common.wallet') })),
				start_time: number().required(t('validation.required', { field: t('common.start_time') })),
				work_hour: number()
					.min(0.5, t('validation.min', { field: t('common.work_hour'), min: 0.5 }))
					.required(t('validation.required', { field: t('common.work_hour') })),
			}),
		[t],
	);

export const useCostCalculations = (
	hourlyRate: number,
	workHour: number,
	courierCount: number,
	companyAppFee: number,
) =>
	useMemo(() => {
		const rate = Number(String(hourlyRate).replace(/,/g, ''));
		const growthOverPrice = workHour * rate * GROWTH_RATE;
		const appFeePrice = workHour * companyAppFee;
		const singleCourierEarning = workHour * rate;
		const couriersMaxEarning = singleCourierEarning * courierCount;
		const appFeeAndOver = appFeePrice + growthOverPrice;
		const totalCost = couriersMaxEarning + appFeeAndOver;
		return {
			hourlyRate: rate > 0 ? formatCurrency(totalCost) : 0,
			singleCourierEarning,
			couriersMaxEarning,
			appFeeAndGrowthPrice: appFeeAndOver,
		};
	}, [hourlyRate, workHour, courierCount, companyAppFee]);

// ---------- Small Components ----------
const RequiredAsterisk = () => (
	<PalRiderText color={colors.red[600]} fontFamily={FontFamily.Semibold}>
		*
	</PalRiderText>
);

const ErrorText = ({ error }: { error?: string | ReactNode }) =>
	error ? <PalRiderText style={styles.errorText}>{error}</PalRiderText> : null;

const TransferBalanceButton = ({
	navigation,
	companyAreaAddressUser,
	selectedWallet,
	walletId,
	isOwnerOrPaymaster,
	balance,
}: {
	navigation: any;
	companyAreaAddressUser: CompanyAreaAddressUserDTO;
	selectedWallet: any;
	walletId: string;
	isOwnerOrPaymaster: boolean;
	balance: number;
}) => {
	const text = isOwnerOrPaymaster ? 'Transfer Balance' : 'Request Balance';
	const handlePress = useCallback(() => {
		if (isOwnerOrPaymaster) {
			navigation.navigate('AppCompanyStack', {
				screen: 'CompanyProfileStack',
				params: {
					screen: 'CompanyWalletTransfer',
					params: {
						company_wallet_id: companyAreaAddressUser?.company_wallet_id,
						company_area_address_id: selectedWallet?.company_area_address_id,
						company_area_id: selectedWallet?.company_area_id,
						company_area_address_wallet_id: walletId,
						return_call_rider: true,
						balance: Number(balance),
					},
				},
			});
		} else {
			navigation.navigate('AppCompanyStack', {
				screen: 'CompanyProfileStack',
				params: {
					screen: 'CompanyWalletTransferRequestCreate',
					params: {
						company_wallet_id: companyAreaAddressUser?.company_wallet_id,
						company_area_address_wallet_id: walletId,
						return_call_rider: true,
					},
				},
			});
		}
	}, [navigation, companyAreaAddressUser, selectedWallet, walletId]);

	return (
		<View style={styles.transferButtonContainer}>
			<Pressable onPress={handlePress}>
				<PalRiderText fontFamily={FontFamily.Bold} color={colors.blue[600]} style={styles.transferButtonText}>
					{text}
				</PalRiderText>
			</Pressable>
		</View>
	);
};

const CostBreakdownItem = ({ label, value }: { label: string; value: string | number }) => (
	<View style={styles.estimatedCostItemContainer}>
		<PalRiderText color={colors.orange[400]} fontFamily={FontFamily.Regular} fontSize={font.mini}>
			{label}
		</PalRiderText>
		<RollingCurrencyText input={String(value)} />
	</View>
);

// ---------- Main Component ----------
const CallRiderPriceInfo: React.FC<{ nextStep: () => void; prevStep: () => void }> = ({ nextStep, prevStep }) => {
	const { t } = useTranslation();
	const navigation = useNavigation<any>();
	const dispatch = useAppDispatch();

	const callRiderSlice = useAppSelector((x) => x.callRiderSlice);
	const companyAreaAddressUser = useAppSelector(
		(x) => x.userSlice.user?.company_area_address_user,
	) as CompanyAreaAddressUserDTO;

	// Wallets
	const { data: wallets } = useGetCompanyAreaAddressWalletListQuery(callRiderSlice.company_area_address_id, {
		skip: !callRiderSlice.company_area_address_id,
	});

	const walletOptions = useMemo(() => {
		if (!wallets?.data?.length) return [];
		return wallets.data.map((item) => ({
			label: `${item.name} (£${Number(item.balance).toFixed(2)})`,
			value: String(item.id).trim().toLowerCase(),
		}));
	}, [wallets]);
	const initialWalletId =
		callRiderSlice.company_area_address_wallet_id && String(callRiderSlice.company_area_address_wallet_id).trim();
	const validationSchema = useFormValidation(t);

	// Formik
	const formik = useFormik({
		enableReinitialize: true,
		initialValues: {
			company_area_address_wallet_id: initialWalletId,
			hourly_rate: callRiderSlice.hourly_rate,
			start_time: callRiderSlice.start_time,
			work_hour: callRiderSlice.work_hour,
		},
		validateOnChange: false,
		validationSchema,
		onSubmit: (values) => {
			dispatch(
				setCallRiderState({
					start_time: Number(values.start_time),
					company_area_address_wallet_id: values.company_area_address_wallet_id,
					work_hour: values.work_hour,
					hourly_rate: values.hourly_rate,
				}),
			);
			nextStep();
		},
	});

	// Cost calculations
	const costBreakdown = useCostCalculations(
		formik.values.hourly_rate,
		formik.values.work_hour,
		callRiderSlice.courier_count,
		companyAreaAddressUser.company_app_fee,
	);

	const selectedWallet = wallets?.data.find((x) => String(x.id) === formik.values.company_area_address_wallet_id);

	const isOwnerOrPaymaster = useMemo(() => {
		const roleName = companyAreaAddressUser.company_area_address_user_role?.name;
		return roleName?.includes('Owner') || roleName?.includes('Paymaster');
	}, [companyAreaAddressUser.company_area_address_user_role?.name]);

	const shouldShowTransferButton =
		formik.values.company_area_address_wallet_id &&
		companyAreaAddressUser?.company_wallet_id &&
		selectedWallet &&
		selectedWallet.balance < Number(costBreakdown.hourlyRate.toString().substring(1));

	return (
		<KeyboardAwareScrollView
			contentContainerStyle={styles.scrollContainer}
			showsVerticalScrollIndicator={false}
			keyboardShouldPersistTaps="handled"
		>
			{/* Wallet Selection */}
			<View style={styles.section}>
				<View style={styles.titleRow}>
					<PalRiderText style={styles.titleText}>Company Area Address Wallet</PalRiderText>
					<RequiredAsterisk />
				</View>

				<Dropdown
					{...globalStyles.dropdownProps}
					options={walletOptions}
					isSearchable
					isMultiple={false}
					selectedValue={formik.values.company_area_address_wallet_id}
					onValueChange={(val) => formik.setFieldValue('company_area_address_wallet_id', val)}
					maxSelectableItems={1}
				/>

				<ErrorText error={formik.errors.company_area_address_wallet_id} />

				{shouldShowTransferButton && (
					<TransferBalanceButton
						navigation={navigation}
						companyAreaAddressUser={companyAreaAddressUser}
						selectedWallet={selectedWallet}
						walletId={formik.values.company_area_address_wallet_id}
						isOwnerOrPaymaster={isOwnerOrPaymaster ?? false}
						balance={Number(
							(
								Number(costBreakdown.hourlyRate.toString().substring(1)) -
								(wallets?.data.find((x) => x.id == formik.values.company_area_address_wallet_id)?.balance ?? 0)
							).toFixed(2),
						)}
					/>
				)}
			</View>

			{/* Time selection */}
			<View style={styles.rowContainer}>
				<View style={styles.timeSection}>
					<View style={styles.titleRow}>
						<PalRiderText style={styles.titleText}>{t('common.start_time')}</PalRiderText>
						<RequiredAsterisk />
					</View>
					<Dropdown
						{...globalStyles.dropdownProps}
						options={createTimeOptions()}
						selectedValue={String(formik.values.start_time)}
						onValueChange={(val) => formik.setFieldValue('start_time', val)}
					/>
					<ErrorText error={formik.errors.start_time} />
				</View>
				<View style={styles.timeSection}>
					<View style={styles.titleRow}>
						<PalRiderText style={styles.titleText}>{t('common.work_hour')}</PalRiderText>
						<RequiredAsterisk />
					</View>
					<Dropdown
						{...globalStyles.dropdownProps}
						options={createWorkHourOptions()}
						selectedValue={String(formik.values.work_hour)}
						onValueChange={(val) => formik.setFieldValue('work_hour', val)}
					/>
					<ErrorText error={formik.errors.work_hour} />
				</View>
			</View>

			{/* Hourly rate */}
			<View style={styles.section}>
				<PalRiderCurrencyInput
					containerStyle={styles.currencyInputContainer}
					title={t('common.hourly_rate')}
					onChangeCurrencyText={(text) => formik.setFieldValue('hourly_rate', cleanCurrencyInput(text), true)}
					currencyValue={formik.values.hourly_rate}
					error={formik.errors.hourly_rate}
				/>
			</View>

			{/* Cost breakdown */}
			{formik.values.hourly_rate > 0 && (
				<Animated.View
					entering={FadeInDown.duration(300)}
					exiting={FadeOutUp.duration(200)}
					style={styles.estimatedCostContainer}
				>
					<CostBreakdownItem
						label={t('screen.company.callrider.price_info.courier_max_earnings')}
						value={costBreakdown.couriersMaxEarning}
					/>
					<CostBreakdownItem
						label={t('screen.company.callrider.price_info.single_courier_earning')}
						value={costBreakdown.singleCourierEarning}
					/>
					<CostBreakdownItem
						label={t('screen.company.callrider.price_info.app_fee_and_growth_price')}
						value={costBreakdown.appFeeAndGrowthPrice}
					/>
					<CostBreakdownItem
						label={t('screen.company.callrider.price_info.estimated_max_total_cost')}
						value={costBreakdown.hourlyRate}
					/>
				</Animated.View>
			)}

			{/* Buttons */}
			<View style={styles.buttonContainer}>
				<PalRiderButton style={[buttonStyling.dark, styles.button]} onPress={prevStep}>
					<PalRiderText color="white">{t('common.go_back')}</PalRiderText>
				</PalRiderButton>
				<PalRiderButton style={[buttonStyling.dark, styles.button]} onPress={() => formik.handleSubmit()}>
					<PalRiderText color="white">{t('common.continue')}</PalRiderText>
				</PalRiderButton>
			</View>
		</KeyboardAwareScrollView>
	);
};

