import WarningModal from '@/components/custom-modal/WarningModal';
import { useModal } from '@/components/ModalProvider';
import PalRiderText from '@/components/PalRiderText';
import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { font, PADDING } from '@/theme/responsive';
import { isFetchBaseQueryError, parsePhoneNumber } from '@/utils';
import React, { useEffect } from 'react';
import { FlatList, Pressable, StyleSheet, View } from 'react-native';

import LinearGradient from 'react-native-linear-gradient';

import { CompositeScreenProps } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import {
	AppCompanyProfileCompanyAreaParamList,
	AppCompanyProfileParamList,
	AppCompanyTabParamList,
} from '@/navigation/company-navigation';
import { useTranslation } from 'react-i18next';
import { useLazyGetAllCompanyAreaAddressUsersQuery } from '@/services/api/company/company-area-address-user';
import { MenuAction, MenuView } from '@react-native-menu/menu';
import { useAppSelector } from '@/redux/hooks';
import { CompanyAreaAddressUserDTO } from 'palriderapptypes/company';
import Icon from '@/components/Icon';

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList, 'CompanyAreaAddressUsers'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyAreaStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
			CompositeScreenProps<
				NativeStackScreenProps<RootStackParamList>,
				NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList>
			>
		>
	>
>;
const AppCompanyProfileCompanyAreaAddressUsersScreen: React.FC<Props> = ({ route, navigation }) => {
	const currentCompanyAreaAddressUser = useAppSelector(
		(x) => x.userSlice.user?.company_area_address_user,
	) as CompanyAreaAddressUserDTO;
	const { t } = useTranslation();
	const { showGlobalModal } = useModal();
	if (!route.params.company_area_address_id) navigation.goBack();
	const [getAllCompanyAreaUser, { data, isLoading }] = useLazyGetAllCompanyAreaAddressUsersQuery();
	const loadAllCompanyAreaUser = async () => {
		const res = await getAllCompanyAreaUser({
			size: 100,
			page: 1,
			company_area_address_id: route.params.company_area_address_id,
		});
		if (res.error && isFetchBaseQueryError(res.error)) {
			showGlobalModal({
				children: <WarningModal text={res.error.data.title} />,
			});
			return;
		}
	};
	useEffect(() => {
		loadAllCompanyAreaUser();
	}, []);
	return (
		<View style={styles.container}>
			<FlatList
				showsVerticalScrollIndicator={false}
				refreshing={isLoading}
				onRefresh={loadAllCompanyAreaUser}
				data={data?.data ?? []}
				contentContainerStyle={{ flex: 1, gap: PADDING.large }}
				contentInsetAdjustmentBehavior="automatic"
				ListEmptyComponent={
					<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', gap: PADDING.medium }}>
						<Icon name="UserGroupIconSvg" width={56} height={56} color={colors.black} />
						<PalRiderText fontFamily={FontFamily.Semibold} color={colors.gray[600]}>
							No users found
						</PalRiderText>
					</View>
				}
				ListFooterComponent={
					<>
						{currentCompanyAreaAddressUser.company_area_address_user_role?.name == 'Owner' && (
							<LinearGradient
								style={styles.addContainer}
								colors={[colors.red[500], colors.orange[500]]}
								start={{ x: 0, y: 1 }}
								end={{ x: 1, y: 0 }}
							>
								<Pressable
									style={styles.addButton}
									onPress={() => {
										navigation.navigate('AppCompanyStack', {
											screen: 'CompanyProfileStack',
											params: {
												screen: 'CompanyAreaStack',
												params: {
													screen: 'CompanyAreaAddressUserCreate',
													params: {
														company_area_address_id: route.params.company_area_address_id,
														company_area_id: route.params.company_area_id,
													},
												},
											},
										});
									}}
								>
									<Icon name="UserGroupIconSvg" width={20} height={35} color={colors.white} />
									<PalRiderText fontSize={font.small} fontFamily={FontFamily.Semibold} color={colors.white}>
										Add Address User
									</PalRiderText>
								</Pressable>
							</LinearGradient>
						)}
					</>
				}
				renderItem={({ item: companyAreaAddressUser }) => {
					const contextMenuActions: Array<MenuAction> = [
						{ id: 'show', title: t('common.show') },
						{ id: 'make_inactive', title: 'Make Inactive' },
						{ id: 'delete', title: t('common.delete') },
					];
					return (
						<MenuView
							actions={contextMenuActions}
							shouldOpenOnLongPress={false}
							isAnchoredToRight
							onPressAction={({ nativeEvent }) => {
								if (nativeEvent.event === 'show') {
									navigation.navigate('AppCompanyStack', {
										screen: 'CompanyProfileStack',
										params: {
											screen: 'CompanyAreaStack',
											params: {
												screen: 'CompanyAreaAddressUserView',
												params: {
													company_area_address_user_id: companyAreaAddressUser.id,
												},
											},
										},
									});
								}
								if (nativeEvent.event === 'make_inactive') {
									// handleUpdateAction(vehicle.id)
								}
								if (nativeEvent.event === 'delete') {
									// handleDeleteAction(vehicle.id, vehicle.is_active);
									// navigation.push('CompanyAreaView', {
									//   company_area_id: areae.id,
									// })
								}
							}}
						>
							<Pressable key={companyAreaAddressUser.id} style={styles.userContainer}>
								<View>
									<Icon name="UserStarsIconSvg" width={20} height={35} />
								</View>
								<View style={styles.userInfoContainerr}>
									<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.mini} color={colors.black}>
										{companyAreaAddressUser.name} {companyAreaAddressUser.surname}
									</PalRiderText>
									<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.xmini} color={colors.gray[500]}>
										{parsePhoneNumber(companyAreaAddressUser.phone_number)}
									</PalRiderText>
								</View>
								<View style={{ flexDirection: 'row', alignItems: 'center', gap: PADDING.medium }}>
									<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.mini}>
										{companyAreaAddressUser.company_area_address_user_role?.name ?? 'Has No Role'}
									</PalRiderText>
									{companyAreaAddressUser.is_active && (
										<Icon name="CheckCircleIconSvg" color={colors.green[600]} width={16} height={16} />
									)}
									{!companyAreaAddressUser.is_active && (
										<Icon name="CloseIconSvg" color={colors.red[600]} width={20} height={20} />
									)}
								</View>
							</Pressable>
						</MenuView>
					);
				}}
			/>
		</View>
	);
};
const styles = StyleSheet.create({
	container: {
		backgroundColor: colors.white,
		padding: PADDING.large,
		flex: 1,
	},
	userContainer: {
		backgroundColor: colors.white,
		flexDirection: 'row',
		alignItems: 'center',
		borderWidth: 1,
		borderColor: colors.gray[200],
		padding: PADDING.large,
		gap: PADDING.large,
		borderRadius: PADDING.large,
		overflow: 'hidden',
	},
	userInfoContainerr: {
		flex: 1,
		gap: PADDING.small,
	},
	addContainer: {
		borderRadius: PADDING.medium,
	},
	addButton: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: PADDING.medium,
		padding: PADDING.small,
		paddingHorizontal: PADDING.medium,
	},
	statusContainer: {
		position: 'absolute',
		top: -10,
		right: 10,
		backgroundColor: colors.white,
		zIndex: 9999,
	},
});
export default AppCompanyProfileCompanyAreaAddressUsersScreen;
