import React, { createContext, ReactElement, useContext, useEffect, useRef, useState } from 'react';
import { FlatList, LayoutChangeEvent, StyleSheet, View } from 'react-native';
import PalRiderText from '@/components/PalRiderText.tsx';
import { normalize } from '@/theme/responsive.ts';
import colors from '@/theme/colors.ts';
import { FontFamily } from '@/theme/fonts.ts';
import Animated, { Easing, useAnimatedStyle, useSharedValue, withTiming } from 'react-native-reanimated';
import { CheckIconSvg } from '@/assets/svg/ui.tsx';

type PalRiderWizardContextValuesType = {
	step: number;
	nextStep: () => void;
	prevStep: () => void;
};
const PalRiderWizardContext = createContext<PalRiderWizardContextValuesType>({
	step: 0,
	nextStep: () => {},
	prevStep: () => {},
});

type PalRiderWizardProps = {
	children: ReactElement<PalRiderWizardStepProps> | ReactElement<PalRiderWizardStepProps>[];
};
type PalRiderWizardStepItemProps = {
	nextStep: () => void;
	prevStep: () => void;
};
type PalRiderWizardStepProps = {
	children:
		| React.ReactNode
		| React.ReactNode[]
		| (({ nextStep, prevStep }: PalRiderWizardStepItemProps) => React.ReactNode | React.ReactNode[]);
	title?: string;
};

export const PalRiderWizardStep: React.FC<PalRiderWizardStepProps> = (props) => {
	const ctx = useContext(PalRiderWizardContext);
	return (
		<View style={{ flex: 1, backgroundColor: colors.white }}>
			{typeof props.children === 'function'
				? props.children({ nextStep: ctx.nextStep, prevStep: ctx.prevStep })
				: props.children}
		</View>
	);
};

const MAX_VISIBLE = 5;

const PalRiderWizard: React.FC<PalRiderWizardProps> = ({ children }) => {
	const [stepNumber, setStepNumber] = React.useState(1);
	const steps = React.Children.toArray(children) as ReactElement<PalRiderWizardStepProps>[];
	const stepsLength = steps.length;
	const step = steps[stepNumber - 1];

	const widthPercentage = useSharedValue((stepNumber / stepsLength) * 100);
	const wizardProgressAnimatedStyle = useAnimatedStyle(() => ({
		width: `${widthPercentage.value}%`,
	}));

	// --- Horizontal list sizing/scrolling
	const listRef = useRef<FlatList>(null);
	const [navWidth, setNavWidth] = useState(0);
	const ITEM_WIDTH = navWidth > 0 ? navWidth / MAX_VISIBLE : 0;

	const onNavLayout = (e: LayoutChangeEvent) => setNavWidth(e.nativeEvent.layout.width);

	useEffect(() => {
		if (stepsLength > MAX_VISIBLE && ITEM_WIDTH > 0 && listRef.current) {
			// keep current step roughly centered
			listRef.current.scrollToIndex({
				index: Math.min(stepNumber - 1, stepsLength - 1),
				animated: true,
				viewPosition: 0.5,
			});
		}
	}, [stepNumber, stepsLength, ITEM_WIDTH]);

	const getItemLayout = (_: any, index: number) => ({
		length: ITEM_WIDTH,
		offset: ITEM_WIDTH * index,
		index,
	});

	return (
		<PalRiderWizardContext.Provider
			value={{
				step: stepNumber,
				nextStep: () => {
					if (stepNumber < stepsLength) {
						const next = stepNumber + 1;
						setStepNumber(next);
						widthPercentage.value = withTiming((next / stepsLength) * 100, {
							duration: 500,
							easing: Easing.inOut(Easing.ease),
						});
					}
				},
				prevStep: () => {
					if (stepNumber > 1) {
						const prev = stepNumber - 1;
						setStepNumber(prev);
						widthPercentage.value = withTiming((prev / stepsLength) * 100, {
							duration: 500,
							easing: Easing.inOut(Easing.ease),
						});
					}
				},
			}}
		>
			<View style={styles.wizardContainer}>
				<View style={styles.wizardNavigationContainer} onLayout={onNavLayout}>
					<FlatList
						ref={listRef}
						horizontal
						data={steps}
						keyExtractor={(_, i) => `wizard-navigation-item-${i}`}
						showsHorizontalScrollIndicator={false}
						getItemLayout={ITEM_WIDTH ? getItemLayout : undefined}
						contentContainerStyle={[
							styles.wizardNavigationInnerContainer,
							stepsLength < MAX_VISIBLE && { flexGrow: 1, justifyContent: 'space-between' },
						]}
						renderItem={({ item, index }) => {
							const isActive = stepNumber === index + 1;
							const isReached = stepNumber > index + 1;

							return (
								<View
									style={[
										styles.wizardNavigationItem,
										{
											width: stepsLength >= MAX_VISIBLE ? ITEM_WIDTH || normalize(60) : undefined,
											flex: stepsLength < MAX_VISIBLE ? 1 : undefined,
										},
									]}
								>
									<View
										style={[
											styles.wizardNavigationStep,
											{
												backgroundColor: isActive || isReached ? colors.orange[600] : colors.gray[300],
											},
										]}
									>
										<PalRiderText
											style={[styles.wizardNavigationItemText, { color: isActive ? colors.white : colors.black }]}
										>
											{(isReached && (
												<View style={{ justifyContent: 'center', alignItems: 'center' }}>
													<CheckIconSvg width={12} height={12} color={colors.white} />
												</View>
											)) ||
												index + 1}
										</PalRiderText>
									</View>

									<View style={styles.wizardTitleContainer}>
										<PalRiderText style={[styles.wizardTitle, { color: isActive ? colors.black : colors.gray[500] }]}>
											{item.props.title}
										</PalRiderText>
									</View>
								</View>
							);
						}}
					/>

					<View style={styles.wizardProgressContainer}>
						<Animated.View
							style={[{ height: 3, backgroundColor: colors.red[600], zIndex: 999 }, wizardProgressAnimatedStyle]}
						/>
						<View
							style={{
								width: '100%',
								height: 3,
								position: 'absolute',
								backgroundColor: colors.gray[300],
							}}
						/>
					</View>
				</View>

				{step}
			</View>
		</PalRiderWizardContext.Provider>
	);
};

const styles = StyleSheet.create({
	wizardContainer: { flex: 1, backgroundColor: colors.white },
	wizardNavigationContainer: {},
	wizardNavigationInnerContainer: {
		paddingHorizontal: normalize(8),
		paddingVertical: normalize(8),
		borderRadius: normalize(8),
		backgroundColor: colors.white,
	},
	wizardTitleContainer: { alignItems: 'center', marginTop: normalize(4) },
	wizardTitle: {
		fontFamily: FontFamily.Semibold,
		fontSize: normalize(8),
		textAlign: 'center',
		textShadowColor: colors.black[500],
		textShadowRadius: 3,
		textShadowOffset: { width: 0, height: 0 },
	},
	wizardNavigationItem: {
		// NOTE: no flex: 1 here — fixed width lets us show max 5 at once and scroll for more
		justifyContent: 'center',
		alignItems: 'center',
		marginRight: normalize(12),
	},
	wizardNavigationStep: {
		width: normalize(30),
		height: normalize(30),
		borderRadius: normalize(30),
		justifyContent: 'center',
		alignItems: 'center',
	},
	wizardNavigationItemText: {
		fontFamily: FontFamily.Semibold,
		fontSize: normalize(12),
		justifyContent: 'center',
		alignItems: 'center',
	},
	wizardProgressContainer: {},
});

export default PalRiderWizard;
