import PalRiderButton from '@/components/PalRiderButton.tsx';
import PalRiderText from '@/components/PalRiderText.tsx';
import colors from '@/theme/colors.ts';
import { normalize, PADDING } from '@/theme/responsive.ts';
import React, { useRef, useState } from 'react';
import { StyleSheet, View } from 'react-native';
import { KeyboardAwareScrollView } from 'react-native-keyboard-aware-scroll-view';
import SignUpCourierVehicleAddScreen, {
	SignUpCourierVehicleAddModalRef,
} from 'src/screens/auth/signup/courier/components/courier-vehicle/components/SignUpCourierVehicleAddScreen.tsx';

import SignUpCourierVehicles from 'src/screens/auth/signup/courier/components/courier-vehicle/components/SignUpCourierVehicles.tsx';
import { buttonStyling } from '@/theme/defaults.ts';
import { useAppDispatch, useAppSelector } from '@/redux/hooks.ts';
import { setCourierVehicleOnboardingState } from '@/redux/slices/courier-onboarding.ts';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { useModal } from '@/components/ModalProvider';
import WarningModal from '@/components/custom-modal/WarningModal';
import { CreateCourierVehicleRequestDTO } from 'palriderapptypes/courier';

type Props = {
	nextStep: () => void;
	prevStep: () => void;
};
const SignUpCourierVehicleInformationStep: React.FC<Props> = ({ nextStep, prevStep }) => {
	const dispatch = useAppDispatch();
	const insets = useSafeAreaInsets();
	const courierOnboardingSelector = useAppSelector((x) => x.courierOnboardingSlice.vehicles);
	const [vehicles, setVehicles] = useState<Array<CreateCourierVehicleRequestDTO>>(courierOnboardingSelector);
	const vehicleAddScreenModalRef = useRef<SignUpCourierVehicleAddModalRef>(null);
	const { showGlobalModal } = useModal();
	const handleVehicleAdd = () => {
		if (vehicles.length === 0) {
			showGlobalModal({
				children: <WarningModal text="At least one vehicle required" />,
			});
			return;
		}
		dispatch(setCourierVehicleOnboardingState(vehicles));
		nextStep();
	};
	return (
		<KeyboardAwareScrollView
			contentContainerStyle={{ flex: 1, paddingBottom: insets.bottom }}
			style={[styles.scrollContainer]}
		>
			<View style={styles.container}>
				<SignUpCourierVehicleAddScreen
					onVehicleAdded={(vehicle) => setVehicles((prev) => [...prev, vehicle])}
					ref={vehicleAddScreenModalRef}
				/>
				<KeyboardAwareScrollView>
					{vehicles.length > 0 && <SignUpCourierVehicles vehicles={vehicles} setVehicles={setVehicles} />}
					<PalRiderButton style={styles.addNewVehicle} onPress={() => vehicleAddScreenModalRef.current?.openModal()}>
						<PalRiderText color="white">Add New Vehicle</PalRiderText>
					</PalRiderButton>
				</KeyboardAwareScrollView>
				<View
					style={{
						flexDirection: 'row',
						gap: normalize(10),
					}}
				>
					<PalRiderButton style={[buttonStyling.dark, { flex: 1 }]} onPress={() => prevStep()}>
						<PalRiderText color="white">Go Back</PalRiderText>
					</PalRiderButton>
					<PalRiderButton style={[buttonStyling.dark, { flex: 1 }]} onPress={handleVehicleAdd}>
						<PalRiderText color="white">Continue</PalRiderText>
					</PalRiderButton>
				</View>
			</View>
		</KeyboardAwareScrollView>
	);
};
const styles = StyleSheet.create({
	scrollContainer: {
		flex: 1,
		backgroundColor: colors.white,
	},
	container: {
		flex: 1,
		padding: PADDING.large,
	},
	addNewVehicle: {
		backgroundColor: colors.black,
		height: normalize(80),
		borderRadius: normalize(12),
		justifyContent: 'center',
		alignItems: 'center',
	},
});
export default SignUpCourierVehicleInformationStep;
