import React, { useRef } from 'react';
import { font, normalize, PADDING } from '@/theme/responsive.ts';
import { FlatList, Pressable, StyleSheet, View } from 'react-native';
import PalRiderButton from '@/components/PalRiderButton.tsx';
import PalRiderText from '@/components/PalRiderText.tsx';
import { SafeAreaView } from 'react-native-safe-area-context';
import colors from '@/theme/colors.ts';
import { FontFamily } from '@/theme/fonts';
import PalRiderFilePicker, { PalRiderFilePickerRef } from '@/components/PalRiderFilePicker';
import { useFormik } from 'formik';
import { FileType } from '@/@types';
import { array, number, object, string } from 'yup';
import { yupTyped } from '@/types';
import { DocumentPickerResponse } from '@react-native-documents/picker';
import { useAppDispatch, useAppSelector } from '@/redux/hooks';
import { setCompanyAreaAddressDocumentState } from '@/redux/slices/company-onboarding';
import { buttonStyling } from '@/theme/defaults';
import { safeAreaEdges } from '@/utils';
import { useTranslation } from 'react-i18next';
import Icon from '@/components/Icon';

type Props = {
	nextStep: () => void;
	prevStep: () => void;
};
type SignUpCompanyAreaDocumentInfoFormikType = {
	documents: Array<FileType>;
};
const SignUpCompanyAreaDocumentInfoStep: React.FC<Props> = ({ nextStep, prevStep }) => {
	const { t } = useTranslation();
	const filePickerRef = useRef<PalRiderFilePickerRef>(null);
	const dispatch = useAppDispatch();
	const companyOnboardingSelector = useAppSelector((x) => x.companyOnboardingSlice.area.address);
	const signUpCompanyAreaDocumentInfoFormik = useFormik<SignUpCompanyAreaDocumentInfoFormikType>({
		initialValues: {
			documents: companyOnboardingSelector.documents,
		},
		validationSchema: yupTyped<SignUpCompanyAreaDocumentInfoFormikType>({
			documents: array()
				.of(
					object().shape({
						name: string().required(t('validation.required', { field: t('common.name') })),
						size: number().required().max(10000000),
						uri: string().required('File uri is required'),
						type: string().required('File type is required'),
					}),
				)
				.required()
				.min(1, 'At least one document is required'),
		}),
		onSubmit: (values) => {
			dispatch(setCompanyAreaAddressDocumentState(values.documents));
			nextStep();
		},
	});
	const onFileSelected = (files: DocumentPickerResponse[]) => {
		const oldDocuments = signUpCompanyAreaDocumentInfoFormik.values.documents;
		const newDocuments: Array<FileType> = [];
		files.map((file) => {
			if (!file.name || !file.uri || !file.size || !file.type) return;
			newDocuments.push({
				name: file.name,
				uri: file.uri,
				size: file.size,
				type: file.type,
			});
		});

		dispatch(setCompanyAreaAddressDocumentState([...oldDocuments, ...newDocuments]));
		signUpCompanyAreaDocumentInfoFormik.setFieldValue('documents', [...oldDocuments, ...newDocuments]);
	};
	const handleRemoveDocumentItem = (index: number) => {
		const documents = signUpCompanyAreaDocumentInfoFormik.values.documents;
		const filteredDocuments = documents.filter((_, i) => i !== index);
		signUpCompanyAreaDocumentInfoFormik.setFieldValue('documents', filteredDocuments);
		dispatch(setCompanyAreaAddressDocumentState(filteredDocuments));
	};
	return (
		<SafeAreaView style={styles.container} edges={safeAreaEdges}>
			<View style={styles.selectedDocumentsContainer}>
				{companyOnboardingSelector.documents && companyOnboardingSelector.documents.length > 0 && (
					<FlatList
						data={companyOnboardingSelector.documents}
						keyExtractor={(_, index) => index.toString()}
						style={{ width: '100%' }}
						contentContainerStyle={styles.selectedDocumentsContentContainerStyle}
						renderItem={({ item, index }) => (
							<View style={styles.documentItemContainer}>
								<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.mini}>
									{item.name}
								</PalRiderText>
								<Pressable onPress={() => handleRemoveDocumentItem(index)}>
									<Icon name="TrashIconSvg" width={20} height={20} color={colors.red[600]} />
								</Pressable>
							</View>
						)}
					/>
				)}
			</View>
			<View
				style={[
					styles.documentContainer,
					{
						justifyContent: signUpCompanyAreaDocumentInfoFormik.values.documents.length > 0 ? 'flex-start' : 'center',
						paddingBottom: signUpCompanyAreaDocumentInfoFormik.values.documents.length > 0 ? PADDING.medium : 0,
					},
				]}
			>
				<PalRiderText style={styles.infoText}>
					{t('screen.auth.sign_up_company.document_info.documents_description')}
				</PalRiderText>
				<View style={styles.infoListContainer}>
					<PalRiderText style={styles.infoListText}>
						1. {t('screen.auth.sign_up_company.document_info.document_list_1')}
					</PalRiderText>
					<PalRiderText style={styles.infoListText}>
						2. {t('screen.auth.sign_up_company.document_info.document_list_2')}
					</PalRiderText>
					<PalRiderText style={styles.infoListText}>
						3. {t('screen.auth.sign_up_company.document_info.document_list_3')}
					</PalRiderText>
				</View>
				<View style={styles.chooseContainer}>
					<PalRiderFilePicker ref={filePickerRef} onFileSelected={onFileSelected} />
					<PalRiderButton
						onPress={() => filePickerRef.current?.openFilePicker()}
						variant="dark"
						contentStyle={{ flexDirection: 'row', gap: PADDING.large }}
					>
						<PalRiderText fontFamily={FontFamily.Semibold} color={colors.white}>
							{t('screen.auth.sign_up_company.document_info.upload_document')}
						</PalRiderText>
						<Icon name="UploadIconSvg" color={colors.white} width={16} height={16} />
					</PalRiderButton>
				</View>
			</View>
			<View style={{ marginVertical: PADDING.medium }}>
				<PalRiderButton variant="warning" onPress={() => nextStep()}>
					<PalRiderText color={colors.white}>Skip For Now</PalRiderText>
				</PalRiderButton>
			</View>
			<View style={[styles.buttonContainer]}>
				<PalRiderButton style={[buttonStyling.dark, { flex: 1 }]} onPress={() => prevStep()}>
					<PalRiderText color="white">{t('common.go_back')}</PalRiderText>
				</PalRiderButton>
				<PalRiderButton
					variant="dark"
					style={{ flex: 1 }}
					onPress={() => signUpCompanyAreaDocumentInfoFormik.handleSubmit()}
				>
					<PalRiderText color="white">{t('common.continue')}</PalRiderText>
				</PalRiderButton>
			</View>
		</SafeAreaView>
	);
};
const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.white,
		padding: PADDING.large,
	},
	documentContainer: {
		flex: 1,
	},
	infoText: {
		textAlign: 'left',
		fontSize: font.mini,
		paddingHorizontal: PADDING.large,
		marginBottom: PADDING.medium,
		fontFamily: FontFamily.Semibold,
	},
	infoListContainer: {
		alignItems: 'center',
		paddingHorizontal: PADDING.large,
		gap: PADDING.small,
		marginBottom: PADDING.medium,
		fontFamily: FontFamily.Semibold,
		fontSize: font.mini,
	},
	infoListText: {
		alignSelf: 'flex-start',
		color: colors.green[700],
		fontSize: font.mini,
		fontFamily: FontFamily.Semibold,
	},
	chooseContainer: {
		paddingHorizontal: PADDING.large,
	},
	buttonContainer: {
		flexDirection: 'row',
		gap: normalize(10),
	},
	selectedDocumentsContainer: {
		width: '100%',
		marginBottom: PADDING.large,
	},
	selectedDocumentsContentContainerStyle: {
		gap: PADDING.medium,
		width: '100%',
	},
	documentItemContainer: {
		padding: PADDING.large,
		paddingVertical: PADDING.xxlarge,
		borderWidth: 1,
		borderColor: colors.gray[600],
		flexDirection: 'row',
		flex: 1,
		alignItems: 'center',
		justifyContent: 'space-between',
		gap: PADDING.large,
	},
});
export default SignUpCompanyAreaDocumentInfoStep;
