import React from 'react';
import { Icons, IconName, IconPropsMap } from '@/assets/svg/registry';

type Props<T extends IconName> = { name: T } & IconPropsMap[T];

export default function Icon<T extends IconName>({ name, ...props }: Props<T>) {
	const Component = Icons[name] as React.ComponentType<any>;
	return <Component {...props} />;
}
