import React, { useState } from 'react';
import { BottomSheetModal, BottomSheetModalProps, BottomSheetTextInput, BottomSheetView } from '@gorhom/bottom-sheet';
import { forwardRef } from 'react';
import { useSharedValue } from 'react-native-reanimated';
import PalRiderButton from '@/components/PalRiderButton';
import PalRirderSwitch from '@/components/PalRiderSwitch';
import PalRiderText from '@/components/PalRiderText';
import Dropdown from 'react-native-input-select';
import colors from '@/theme/colors';
import { buttonStyling } from '@/theme/defaults';
import { FontFamily } from '@/theme/fonts';
import { PADDING, normalize, font } from '@/theme/responsive';
import { useFormik } from 'formik';
import { View, ActivityIndicator, Platform, StyleSheet, Pressable } from 'react-native';
import {
	useLazyWooSmapAutocompleteAddressFromPostCodeQuery,
	useLazyWooSmapAutocompletePostCodeQuery,
	useLazyWooSmapValidateAddressQuery,
} from '@/services/api/woosmap';
import { WooSmapAutocompleteAddressResult, WooSmapAutocompletePostCodeResult } from '@/@types/woosmap-api-types';
import { useModal } from '@/components/ModalProvider';
import { globalStyles } from '@/utils/global-styles';
import { CreateOrderShipmentDestinationRequestDTO } from 'palriderapptypes/order';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import Icon from '@/components/Icon';

interface Props extends BottomSheetModalProps {
	handleAddDestination: (
		address: Omit<CreateOrderShipmentDestinationRequestDTO, 'sort' | 'notes' | 'received_fee'>,
	) => void;
}
const CreateOrderShipmentAddDestinationModal = forwardRef<BottomSheetModal, Props>((props, ref) => {
	const { handleAddDestination, ...otherProps } = props;
	const [getPostCodes, { isFetching: postCodesFetching }] = useLazyWooSmapAutocompletePostCodeQuery();
	const [getAutocompleteAddresses, { isFetching: autocompleteAddressFetching }] =
		useLazyWooSmapAutocompleteAddressFromPostCodeQuery();
	const [getValidateAddress] = useLazyWooSmapValidateAddressQuery();
	const [postCodeText, setPostCodeText] = useState<string>('');
	const [selectedPostCode, setSelecetedPostCode] = useState<string | null>(null);
	const [selectedAddress, setSelectedAddress] = useState<string | null>(null);
	const [searchPostCodes, setSearchPostCodes] = useState<WooSmapAutocompletePostCodeResult | null>(null);
	const [autocompleteAddresses, setAutocomleteAddresses] = useState<WooSmapAutocompleteAddressResult | null>(null);
	const payment_at_the_door = useSharedValue(0);
	const contains_adult_content = useSharedValue(0);
	const { hideGlobalModal, showGlobalModal } = useModal();
	const insets = useSafeAreaInsets();

	const addOrderShipmentFormik = useFormik({
		initialValues: {
			latitude: 0,
			longitude: 0,
			address: '',
			post_code: '',
			isAddressValidated: false,
			payment_at_the_door: false,
			received_fee: 0,
			contains_adult_content: false,
		},
		onSubmit: () => {},
	});

	const handleSearchPostCode = async () => {
		setSearchPostCodes(null);
		setAutocomleteAddresses(null);
		if (postCodeText.length > 2) {
			getPostCodes(postCodeText)
				.unwrap()
				.then((res) => setSearchPostCodes(res));
		}
	};
	const handlePostCodeSelect = async (selected: string) => {
		if (!selected || selected === 'null') return;

		setAutocomleteAddresses(null);
		setSelecetedPostCode(selected);
		getAutocompleteAddresses(selected)
			.unwrap()
			.then((res) => setAutocomleteAddresses(res))
			.catch((err) => console.log(err));
	};
	const handleSelectAddress = (public_id: string) => {
		if (!public_id || public_id === 'null') return;

		setSelectedAddress(public_id);
		showGlobalModal({
			maxHeight: 200,
			children: (
				<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', gap: PADDING.xlarge }}>
					<ActivityIndicator color={colors.black} />
					<PalRiderText>Address validating...</PalRiderText>
				</View>
			),
		});
		getValidateAddress(public_id)
			.unwrap()
			.then((res) => {
				hideGlobalModal();
				if (!res.result) {
					showGlobalModal({
						maxHeight: 200,
						children: (
							<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', gap: PADDING.large }}>
								<Icon name="CloseIconSvg" width={32} height={32} color={colors.red[600]} />
								<PalRiderText>Selected address not found.</PalRiderText>
							</View>
						),
					});
					return;
				}

				const findPostalCodes = res.result.address_components.filter((x) => x.types.includes('postal_codes'));
				if (findPostalCodes.length === 0) return;
				addOrderShipmentFormik.setFieldValue('latitude', res.result.geometry.location.lat);
				addOrderShipmentFormik.setFieldValue('longitude', res.result.geometry.location.lng);
				addOrderShipmentFormik.setFieldValue('address', res.result.formatted_address);
				addOrderShipmentFormik.setFieldValue('post_code', findPostalCodes[0].short_name);
				addOrderShipmentFormik.setFieldValue('isAddressValidated', true);
				showGlobalModal({
					maxHeight: 200,
					children: (
						<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', gap: PADDING.large }}>
							<Icon name="CheckCircleIconSvg" width={32} height={32} color={colors.green[600]} />
							<PalRiderText>Address validated.</PalRiderText>
						</View>
					),
				});
			})
			.catch(() => {
				hideGlobalModal();
				showGlobalModal({
					maxHeight: 200,
					children: (
						<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', gap: PADDING.large }}>
							<Icon name="CloseIconSvg" width={32} height={32} color={colors.red[600]} />
							<PalRiderText>Cannot select order please try again</PalRiderText>
						</View>
					),
				});
			})
			.finally(() => {
				hideGlobalModal();
			});
	};
	const addDestination = () => {
		handleAddDestination({
			address: addOrderShipmentFormik.values.address,
			contains_adult_content: addOrderShipmentFormik.values.contains_adult_content,
			latitude: addOrderShipmentFormik.values.latitude,
			longitude: addOrderShipmentFormik.values.longitude,
			payment_at_the_door: addOrderShipmentFormik.values.payment_at_the_door,
			receive_fee: addOrderShipmentFormik.values.received_fee,
			post_code: addOrderShipmentFormik.values.post_code,
		});
		clearAddress();
	};
	const clearAddress = () => {
		setSearchPostCodes(null);
		setAutocomleteAddresses(null);
		setPostCodeText('');
		addOrderShipmentFormik.setFieldValue('latitude', 0);
		addOrderShipmentFormik.setFieldValue('longitude', 0);
		addOrderShipmentFormik.setFieldValue('address', '');
		addOrderShipmentFormik.setFieldValue('post_code', '');
		addOrderShipmentFormik.setFieldValue('isAddressValidated', false);
		addOrderShipmentFormik.setFieldValue('payment_at_the_door', false);
		addOrderShipmentFormik.setFieldValue('received_fee', 0);
		addOrderShipmentFormik.setFieldValue('contains_adult_content', false);
		payment_at_the_door.value = 0;
		contains_adult_content.value = 0;
	};
	return (
		<BottomSheetModal
			ref={ref}
			enableDynamicSizing
			enablePanDownToClose={true}
			keyboardBehavior="interactive"
			keyboardBlurBehavior="restore"
			{...otherProps}
		>
			<BottomSheetView style={styles.container}>
				<View
					style={{
						padding: PADDING.large,
						marginBottom: insets.bottom,
						rowGap: PADDING.large,
					}}
				>
					<View style={{ position: 'relative', rowGap: PADDING.medium, marginBottom: PADDING.large }}>
						<View>
							<View style={{ flexDirection: 'row', columnGap: normalize(2) }}>
								<PalRiderText style={styles.titleText}>Post Code</PalRiderText>
							</View>
							<BottomSheetTextInput
								style={{
									minHeight: normalize(40),
									borderWidth: normalize(1),
									borderRadius: normalize(8),
									backgroundColor: colors.gray[100],
									borderColor: colors.gray[300],
									paddingLeft: PADDING.medium,
									fontFamily: FontFamily.Semibold,
									fontSize: font.xmini,
								}}
								onChangeText={(text) => setPostCodeText(text)}
								placeholder="Search For Post Code"
								placeholderTextColor={colors.gray[700]}
								enablesReturnKeyAutomatically
								returnKeyType="search"
								onSubmitEditing={handleSearchPostCode}
							/>
						</View>
						{postCodesFetching && <ActivityIndicator color={colors.black} />}
						{!postCodesFetching && searchPostCodes && searchPostCodes.localities.length >= 1 && (
							<View>
								<View style={{ flexDirection: 'row', columnGap: normalize(2) }}>
									<PalRiderText style={styles.titleText}>Select Post Code</PalRiderText>
								</View>

								<Dropdown
									{...globalStyles.dropdownProps}
									options={searchPostCodes.localities.map((item) => ({
										value: item.public_id,
										label: item.description,
									}))}
									isSearchable
									isMultiple={false}
									selectedValue={selectedPostCode as string}
									onValueChange={async (selected) => handlePostCodeSelect(selected as string)}
									maxSelectableItems={1}
								/>
							</View>
						)}
						{autocompleteAddressFetching && <ActivityIndicator color={colors.black} />}
						{autocompleteAddresses && autocompleteAddresses.result.addresses.list.length >= 1 && (
							<View>
								<View style={{ flexDirection: 'row', columnGap: normalize(2) }}>
									<PalRiderText style={styles.titleText}>Select Address</PalRiderText>
								</View>
								<Dropdown
									{...globalStyles.dropdownProps}
									options={autocompleteAddresses?.result.addresses.list.map((item) => ({
										value: item.public_id,
										label: item.description,
									}))}
									isSearchable
									isMultiple={false}
									selectedValue={selectedAddress as string}
									onValueChange={(selected) => {
										handleSelectAddress(selected as string);
									}}
									maxSelectableItems={1}
								/>
							</View>
						)}
						<View style={{ justifyContent: 'center', alignItems: 'center', marginTop: PADDING.small }}>
							{addOrderShipmentFormik.values.isAddressValidated && (
								<Pressable onPress={clearAddress}>
									<PalRiderText style={{ textDecorationLine: 'underline' }}>Clear Address</PalRiderText>
								</Pressable>
							)}
						</View>
						<PalRirderSwitch
							textComponent={
								<PalRiderText color={colors.green[600]} fontSize={font.mini} fontFamily={FontFamily.Semibold}>
									Payment At The Door
								</PalRiderText>
							}
							value={payment_at_the_door}
							onPress={(status) => addOrderShipmentFormik.setFieldValue('payment_at_the_door', status)}
						/>
						<PalRirderSwitch
							textComponent={
								<View style={{ flexDirection: 'row', alignItems: 'center', gap: PADDING.medium }}>
									<PalRiderText color={colors.red[600]} fontSize={font.medium} fontFamily={FontFamily.Semibold}>
										+18
									</PalRiderText>
									<PalRiderText color={colors.red[600]} fontSize={font.mini}>
										(Includes adult content)
									</PalRiderText>
								</View>
							}
							value={contains_adult_content}
							onPress={(status) => addOrderShipmentFormik.setFieldValue('contains_adult_content', status)}
						/>
					</View>
					<PalRiderButton style={[buttonStyling.dark]} onPress={addDestination}>
						<PalRiderText color={colors.white}>Create Destination</PalRiderText>
					</PalRiderButton>
				</View>
			</BottomSheetView>
		</BottomSheetModal>
	);
});

const styles = StyleSheet.create({
	container: { minHeight: 10 },
	mapView: {
		flex: 1,
	},
	bottomSheetViewContainer: {
		flex: 1,
	},
	selectInput: {},
	selectContainer: {
		padding: Platform.OS === 'ios' ? PADDING.large : normalize(2),
		borderWidth: 1,
		borderColor: colors.gray[300],
		borderRadius: PADDING.large,
		backgroundColor: colors.gray[100],
	},
	titleText: {
		fontFamily: FontFamily.Semibold,
		fontSize: normalize(12),
		marginBottom: normalize(6),
		paddingLeft: normalize(4),
	},
	buttonContainer: {
		gap: PADDING.medium,
		flexDirection: 'row',
		justifyContent: 'center',
		paddingTop: PADDING.large,
		paddingHorizontal: PADDING.large,
		shadowColor: colors.gray[800],
		shadowOffset: {
			width: 0,
			height: -2,
		},
		backgroundColor: colors.white,
		shadowOpacity: 0.35,
		shadowRadius: 6,
		elevation: 5,
	},
	radioButton: {
		width: 20,
		height: 20,
		borderRadius: 20 / 2,
		borderWidth: 3,
		borderColor: 'white',
	},

	bottomSheetFooterContainer: {},
});
export default CreateOrderShipmentAddDestinationModal;
