import { MotorcycleIconSvg } from '@/assets/svg/vehicle';
import colors from '@/theme/colors';
import { useNavigation, useNavigationState, useRoute, getFocusedRouteNameFromRoute } from '@react-navigation/native';
import { StyleSheet, TouchableOpacity } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

const PalRiderCallRiderFab = () => {
	const navigation = useNavigation<any>();
	const insets = useSafeAreaInsets();

	// This will re-render whenever navigation state changes
	const currentRouteName = useNavigationState((state) => {
		const route = state.routes[state.index];
		return getFocusedRouteNameFromRoute(route) ?? route.name;
	});

	// Decide visibility
	const isHidden =
		currentRouteName?.includes('Profile') ||
		currentRouteName?.includes('CallRider') ||
		currentRouteName?.includes('Order');

	if (isHidden) return null;

	return (
		<TouchableOpacity
			style={[styles.fab, { bottom: insets.bottom + 60 }]}
			onPress={() => {
				navigation.navigate('AppCompanyStack', {
					screen: 'CompanyOrderStack',
					params: {
						screen: 'CompanyCallRider',
					},
				});
			}}
		>
			<MotorcycleIconSvg color={colors.white} />
		</TouchableOpacity>
	);
};

export default PalRiderCallRiderFab;

const styles = StyleSheet.create({
	fab: {
		position: 'absolute',
		right: 20,
		bottom: 40,
		backgroundColor: colors.orange[600],
		width: 56,
		height: 56,
		borderRadius: 28,
		justifyContent: 'center',
		alignItems: 'center',
		elevation: 5,
		shadowColor: '#000',
		shadowOpacity: 0.3,
		shadowOffset: { width: 0, height: 2 },
		shadowRadius: 4,
	},
});
