import React, { useRef, useState } from 'react';
import { Animated, PanResponder, View, ActivityIndicator, StyleSheet } from 'react-native';
import { useModal } from './ModalProvider';
import LoadingModal from './custom-modal/LoadingModal';
import colors from '@/theme/colors';

const PullToRefreshView: React.FC<{ onRefresh: () => Promise<void>; children: React.ReactNode }> = ({
	onRefresh,
	children,
}) => {
	const translateY = useRef(new Animated.Value(0)).current;
	const [refreshing, setRefreshing] = useState(false);
	const { showGlobalModal, hideGlobalModal } = useModal();

	const panResponder = useRef(
		PanResponder.create({
			onMoveShouldSetPanResponder: (_, gestureState) => gestureState.dy > 10,
			onPanResponderMove: (_, gestureState) => {
				if (!refreshing && gestureState.dy > 0) {
					translateY.setValue(gestureState.dy);
				}
			},
			onPanResponderRelease: async (_, gestureState) => {
				if (gestureState.dy > 50) {
					setRefreshing(true);
					showGlobalModal({
						children: <LoadingModal />,
						backgroundColor: colors.transparent,
					});
					Animated.timing(translateY, {
						toValue: 60,
						duration: 200,
						useNativeDriver: true,
					}).start();

					await onRefresh();

					Animated.timing(translateY, {
						toValue: 0,
						duration: 300,
						useNativeDriver: true,
					}).start(() => {
						setRefreshing(false);
						hideGlobalModal();
					});
				} else {
					Animated.timing(translateY, {
						toValue: 0,
						duration: 200,
						useNativeDriver: true,
					}).start();
				}
			},
		}),
	).current;

	return (
		<View style={styles.container} {...panResponder.panHandlers}>
			{refreshing && (
				<View style={styles.loadingIndicator}>
					<ActivityIndicator size="small" color="#000" />
				</View>
			)}
			<Animated.View style={[styles.refreshIndicator, { transform: [{ translateY }] }]}>
				<ActivityIndicator size="small" color="#000" />
			</Animated.View>
			<View style={styles.content}>{children}</View>
		</View>
	);
};

const styles = StyleSheet.create({
	container: {
		flex: 1,
		justifyContent: 'center',
		alignItems: 'center',
		overflow: 'hidden',
		zIndex: 9999999,
	},
	refreshIndicator: {
		position: 'absolute',
		top: -60,
		left: 0,
		right: 0,
		height: 60,
		justifyContent: 'center',
		alignItems: 'center',
		zIndex: 99999999,
	},
	loadingIndicator: {
		position: 'absolute',
		top: 0,
		left: 0,
		right: 0,
		alignItems: 'center',
		zIndex: 9999999,
	},
	content: {
		flex: 1,
		width: '100%',
		zIndex: 99,
	},
});

export default PullToRefreshView;
