import React, { useCallback, useRef } from 'react';
import { useModal } from '@/components/ModalProvider';
import PalRiderBadge from '@/components/PalRiderBadge';
import ConfirmationModal from '@/components/custom-modal/ConfirmationModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import WarningModal from '@/components/custom-modal/WarningModal';
import {
	useLazyCancelOrderShipmentQuery,
	useLazyRemoveOrderShipmentDestinationQuery,
	useLazyStartOrderShipmentQuery,
} from '@/services/api/order/shipment';

import { convertHoursToHoursMinutes, snakeToHumanReadable } from '@/utils';
import { useState } from 'react';
import { Linking, ListRenderItemInfo, Platform, Pressable, StyleSheet, View } from 'react-native';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import colors from '@/theme/colors';
import PalRiderButton from '@/components/PalRiderButton';
import Animated, { FadeInUp } from 'react-native-reanimated';
import PalRiderText from '@/components/PalRiderText';
import { font, PADDING } from '@/theme/responsive';
import { FontFamily } from '@/theme/fonts';
import {
	OrderShipmentCancellationReasonDTO,
	OrderShipmentDestinationDTO,
	OrderShipmentDTO,
} from 'palriderapptypes/order';
import { BottomSheetModal, BottomSheetView } from '@gorhom/bottom-sheet';
import PalRiderDropdown from '@/components/PalRiderDropdown';
import { MenuView } from '@react-native-menu/menu';
import Icon from '@/components/Icon';

const AppActiveOrderShipmentItemRenderer: React.FC<
	ListRenderItemInfo<OrderShipmentDTO> & {
		loadOrderShipments: () => void;
		navigation: any;
		orderShipmentCancellationReasons: Array<OrderShipmentCancellationReasonDTO>;
	}
> = ({ item: shipment, loadOrderShipments, navigation, orderShipmentCancellationReasons }) => {
	const [destinationsVisible, setDestinationsVisible] = useState(false);
	const { showGlobalModal, hideGlobalModal } = useModal();
	const [removeOrderShipmentDestination] = useLazyRemoveOrderShipmentDestinationQuery();
	const [cancelOrderShipment] = useLazyCancelOrderShipmentQuery();
	const [selectedOrderShipmentId, setSelectedOrderShipmentId] = useState('');
	const [selectedCancellationReasonId, setSelectedCancellationReasonId] = useState('');

	const shipmentCancellationModal = useRef<BottomSheetModal>(null);

	const [startOrderShipment] = useLazyStartOrderShipmentQuery();

	const handleStartDelivery = (order_id: string, order_shipment_id: string) => {
		showGlobalModal({
			padding: 0,
			children: (
				<ConfirmationModal
					onConfirm={() => {
						try {
							hideGlobalModal();
							showGlobalModal({
								maxHeight: 200,
								children: <LoadingModal />,
							});
							startOrderShipment({
								order_id,
								order_shipment_id,
							})
								.unwrap()
								.then(() => {
									hideGlobalModal();
									showGlobalModal({
										maxHeight: 200,
										children: <SuccessModal text="Delivery started" />,
										closeAfterDelay: 1000,
										whenClose() {
											navigation.navigate('AppOrderStack', {
												screen: 'OrderShipmentDelivery',
												params: {
													order_id: order_id,
													order_shipment_id: order_shipment_id,
												},
											});
										},
									});
								})
								.catch(() => {
									hideGlobalModal();
									showGlobalModal({
										maxHeight: 200,
										children: <WarningModal text="Delivery cannot started" />,
									});
								});
						} catch (e) {
							hideGlobalModal();
							showGlobalModal({
								maxHeight: 200,
								children: <WarningModal text="Something went wrong please try again" />,
							});
						}
					}}
					onCancel={() => hideGlobalModal()}
					icon={<Icon name="CheckCircleIconSvg" width={30} height={30} color={colors.green[600]} />}
					text="Are you sure you want to start the delivery? This process cannot be reversed!"
				/>
			),
		});
	};

	const handleRemoveOrderShipmentDestination = (
		order_id: string,
		order_shipment_id: string,
		order_shipment_destination_id: string,
	) => {
		hideGlobalModal();
		showGlobalModal({
			maxHeight: 200,
			padding: 0,
			children: (
				<ConfirmationModal
					onConfirm={() => {
						try {
							hideGlobalModal();
							showGlobalModal({
								maxHeight: 200,
								children: <LoadingModal />,
							});
							removeOrderShipmentDestination({
								order_id,
								order_shipment_id,
								order_shipment_destination_id,
							})
								.unwrap()
								.then(() => {
									hideGlobalModal();
									showGlobalModal({
										maxHeight: 200,
										children: <SuccessModal text="Destination deleted" />,
										whenClose() {
											loadOrderShipments();
										},
									});
								})
								.catch(() => {
									hideGlobalModal();
									showGlobalModal({
										maxHeight: 200,
										children: <WarningModal text="Destination cannot deleted" />,
									});
								});
						} catch (e) {
							hideGlobalModal();
							showGlobalModal({
								maxHeight: 200,
								children: <WarningModal text="Something went wrong please try again" />,
							});
						}
					}}
					onCancel={() => hideGlobalModal()}
					icon={<Icon name="CheckCircleIconSvg" width={60} height={60} color={colors.red[600]} />}
					text="Are you sure want to delete destination ?"
				/>
			),
		});
	};

	const openCancelOrderShipmentModal = (order_shipment_id: string) => {
		shipmentCancellationModal.current?.present();
		setSelectedOrderShipmentId(order_shipment_id);
		return;
	};

	const handleCancelOrderShipment = () => {
		hideGlobalModal();
		if (selectedCancellationReasonId == '') {
			showGlobalModal({
				children: <WarningModal text="Order shipment cancellation not selected" />,
			});
			return;
		}
		showGlobalModal({
			maxHeight: 200,
			padding: 0,
			children: (
				<ConfirmationModal
					textColor={colors.red[600]}
					onConfirm={() => {
						try {
							showGlobalModal({
								maxHeight: 200,
								children: <LoadingModal />,
							});
							cancelOrderShipment({
								order_id: shipment.id,
								order_shipment_id: selectedOrderShipmentId,
								order_shipment_cancellation_reason_id: selectedCancellationReasonId,
							})
								.unwrap()
								.then(() => {
									hideGlobalModal();
									showGlobalModal({
										maxHeight: 200,
										children: <SuccessModal text="Delivery cancelled." />,
										whenClose() {
											loadOrderShipments();
											setSelectedOrderShipmentId('');
											setSelectedCancellationReasonId('');
										},
									});
								})
								.catch(() => {
									hideGlobalModal();
									showGlobalModal({
										maxHeight: 200,
										children: <WarningModal text="Delivery cannot be cancelled." />,
									});
								});
						} catch (e) {
							hideGlobalModal();
							showGlobalModal({
								maxHeight: 200,
								children: <WarningModal text="Something went wrong please try again" />,
							});
						}
					}}
					onCancel={() => hideGlobalModal()}
					icon={<Icon name="CloseIconSvg" width={60} height={60} color={colors.red[600]} />}
					text="Are you sure want to cancel delivery ?"
				/>
			),
		});
	};

	const renderOrderStatus = useCallback(({ destination }: { destination: OrderShipmentDestinationDTO }) => {
		let statusColor = colors.gray[300];
		switch (destination.status) {
			case 'waiting_delivery':
				statusColor = colors.orange[600];
				break;
			case 'on_the_way':
				statusColor = colors.green[600];
				break;
			case 'delivered':
				statusColor = colors.green[600];
				break;
			case 'cancelled':
				statusColor = colors.red[600];
				break;
		}
		return <PalRiderBadge color={statusColor} text={snakeToHumanReadable(destination.status)} />;
	}, []);

	return (
		<View style={styles.shipmentContainer} key={shipment.id}>
			{/* Header Section with Departure */}
			<View style={styles.headerSection}>
				<View style={styles.shipmentDepartureContainer}>
					<View style={styles.locationIconContainer}>
						<Icon name="LocationIconSvg" width={18} height={18} colorSpace={[colors.white, colors.white]} />
					</View>
					<View style={styles.departureTextContainer}>
						<PalRiderText style={styles.departureLabel}>#{shipment.order_shipment_no}</PalRiderText>
						<PalRiderText style={styles.departureLabel}>From</PalRiderText>
						<PalRiderText numberOfLines={2} style={styles.departureAddress}>
							{shipment?.order_shipment_departure?.company_area_address?.address}
						</PalRiderText>
					</View>
				</View>

				<Pressable style={styles.expandButton} onPress={() => setDestinationsVisible((prev) => !prev)}>
					<Icon
						name={destinationsVisible ? 'ChevronUpIconSvg' : 'ChevronDownIconSvg'}
						width={20}
						height={20}
						color={colors.gray[600]}
					/>
				</Pressable>
			</View>

			{/* Destinations List */}
			{destinationsVisible && (
				<Animated.View entering={FadeInUp.duration(200)} style={styles.destinationsSection}>
					<View style={styles.destinationsHeader}>
						<PalRiderText style={styles.destinationsTitle}>Destinations</PalRiderText>
						<PalRiderText style={styles.destinationsCount}>
							{shipment.order_shipment_destinations.length} stops
						</PalRiderText>
					</View>

					{shipment.order_shipment_destinations.map((destination, i) => (
						<View key={i} style={styles.destinationWrapper}>
							<View style={styles.destinationItem}>
								<View style={styles.destinationNumber}>
									<PalRiderText style={styles.destinationNumberText}>{(i + 1).toString()}</PalRiderText>
								</View>

								<View style={styles.destinationContent}>
									<MenuView
										actions={[
											{ id: 'show_in_maps', title: 'Show In Maps' },
											{
												id: 'remove_destination',
												title: 'Remove Destination',
												attributes: {
													destructive: true,
													hidden:
														shipment.status !== 'waiting_delivery' || shipment.order_shipment_destinations.length <= 1,
												},
											},
										]}
										shouldOpenOnLongPress={false}
										isAnchoredToRight
										onPressAction={({ nativeEvent }) => {
											if (nativeEvent.event === 'show_in_maps') {
												const url = Platform.select({
													ios: `maps:${destination.latitude},${destination.longitude}?q=${destination.address}`,
													android: `geo:${destination.latitude},${destination.longitude}?q=${destination.address}`,
												});
												if (url) Linking.openURL(url);
											}
											if (nativeEvent.event === 'remove_destination') {
												handleRemoveOrderShipmentDestination(
													shipment.id,
													destination.order_shipment_id,
													destination.id,
												);
											}
										}}
									>
										<Pressable style={styles.addressContainer}>
											<PalRiderText numberOfLines={2} style={styles.destinationAddress}>
												{destination.address}
											</PalRiderText>
										</Pressable>
									</MenuView>

									<View style={styles.statusContainer}>
										{renderOrderStatus({ destination })}
										{destination.status === 'cancelled' &&
											destination.order_shipment_destination_cancellation_reason && (
												<PalRiderBadge
													text={destination.order_shipment_destination_cancellation_reason?.name}
													color={colors.red[600]}
												/>
											)}
									</View>
								</View>
							</View>

							{i !== shipment.order_shipment_destinations.length - 1 && (
								<View style={styles.destinationConnector}>
									<Icon name="LineDottedIconSvg" width={20} height={20} color={colors.gray[300]} />
								</View>
							)}
						</View>
					))}
				</Animated.View>
			)}

			{/* Action Buttons */}
			{shipment.status === 'waiting_delivery' && (
				<View style={styles.actionsSection}>
					<View style={styles.secondaryActions}>
						<PalRiderButton
							fullWidth
							size="small"
							variant="ghost"
							style={styles.secondaryButton}
							onPress={() => {
								navigation.navigate('AppOrderStack', {
									screen: 'UpdateShipment',
									params: { shipment: shipment },
								});
							}}
						>
							<PalRiderText style={styles.secondaryButtonText}>Update</PalRiderText>
						</PalRiderButton>
						<PalRiderButton fullWidth size="small" variant="ghost" style={styles.secondaryButton}>
							<PalRiderText style={styles.secondaryButtonText}>Add Stop</PalRiderText>
						</PalRiderButton>
					</View>

					<View style={styles.primaryActions}>
						<PalRiderButton
							fullWidth
							variant="error"
							size="small"
							style={styles.cancelButton}
							onPress={() => openCancelOrderShipmentModal(shipment.id)}
						>
							<PalRiderText color={colors.white} style={styles.primaryButtonText}>
								Cancel Delivery
							</PalRiderText>
						</PalRiderButton>
						<PalRiderButton
							variant="success"
							size="small"
							style={styles.startButton}
							fullWidth
							onPress={() => handleStartDelivery(shipment.order_id, shipment.id)}
						>
							<PalRiderText color={colors.white} style={styles.primaryButtonText}>
								Start Delivery
							</PalRiderText>
						</PalRiderButton>
					</View>
				</View>
			)}

			{/* Footer with Stats */}
			<View style={styles.footerSection}>
				<View style={styles.statsRow}>
					{(shipment.status === 'cancelled' || shipment.status === 'completed') && (
						<PalRiderBadge
							text={snakeToHumanReadable(shipment.status)}
							color={shipment.status === 'cancelled' ? colors.red[600] : colors.green[600]}
						/>
					)}
					<PalRiderBadge
						text={
							shipment.order_shipment_destinations &&
							shipment.order_shipment_destinations
								.reduce((acc, destination) => destination.distance + acc, 0)
								.toFixed(1) + ' mi'
						}
						color={colors.blue[600]}
					/>
					<PalRiderBadge
						text={convertHoursToHoursMinutes(
							shipment.order_shipment_destinations &&
								shipment.order_shipment_destinations?.reduce((acc, destination) => destination.duration + acc, 0),
						)}
						color={colors.purple[600]}
					/>
				</View>

				{shipment.status === 'cancelled' && shipment.order_shipment_cancellation_reason && (
					<View style={styles.cancellationReason}>
						<PalRiderBadge text={shipment.order_shipment_cancellation_reason?.name} color={colors.red[600]} />
					</View>
				)}
			</View>

			{/* Bottom Sheet Modal */}
			<BottomSheetModal ref={shipmentCancellationModal} enablePanDownToClose enableDynamicSizing>
				<BottomSheetView style={styles.bottomSheetContent}>
					<View style={styles.modalContent}>
						<PalRiderText style={styles.modalTitle}>Select Cancellation Reason</PalRiderText>
						<PalRiderDropdown
							options={
								orderShipmentCancellationReasons?.map((item) => ({
									value: item.id,
									label: item.name,
								})) ?? []
							}
							selectedValue={selectedCancellationReasonId}
							onValueChange={(value) => setSelectedCancellationReasonId(value)}
						/>
					</View>
					<PalRiderButton variant="error" onPress={handleCancelOrderShipment}>
						<PalRiderText color={colors.white}>Cancel Shipment</PalRiderText>
					</PalRiderButton>
				</BottomSheetView>
			</BottomSheetModal>
		</View>
	);
};

