import React, { useEffect } from 'react';
import { FlatList, Pressable, ScrollView, StyleSheet, View } from 'react-native';
import colors from '@/theme/colors.ts';
import { font, normalize, PADDING } from '@/theme/responsive.ts';
import PalRiderText from '@/components/PalRiderText.tsx';
import { FontFamily } from '@/theme/fonts.ts';
import { useLazyGetAllCompanyAreaQuery } from '@/services/api/company/company-area.ts';
import { RefreshControl } from 'react-native-gesture-handler';

import LinearGradient from 'react-native-linear-gradient';
import { useAppSelector } from '@/redux/hooks';
import { CompositeScreenProps, useIsFocused } from '@react-navigation/native';
import {
	AppCompanyProfileCompanyAreaParamList,
	AppCompanyProfileParamList,
	AppCompanyTabParamList,
} from '@/navigation/company-navigation';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import { useTranslation } from 'react-i18next';
import { MenuAction, MenuView } from '@react-native-menu/menu';
import { CompanyAreaAddressUserDTO } from 'palriderapptypes/company';
import Icon from '@/components/Icon';

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList, 'CompanyAreas'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyAreaStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
			CompositeScreenProps<
				NativeStackScreenProps<RootStackParamList>,
				NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList>
			>
		>
	>
>;
const AppCompanyProfileCompanyAreasScreen: React.FC<Props> = ({ navigation }) => {
	const companyAreaAddressUser = useAppSelector(
		(x) => x.userSlice.user?.company_area_address_user,
	) as CompanyAreaAddressUserDTO;
	const [getAllAreas, { data, isFetching }] = useLazyGetAllCompanyAreaQuery();
	const { t } = useTranslation();
	const refreshList = () => getAllAreas({ page: 1, size: 100 });
	const isFocused = useIsFocused();
	useEffect(() => {
		if (!companyAreaAddressUser) return;
		if (isFocused) refreshList();
	}, [isFocused]);
	return (
		<View style={[styles.container, { padding: PADDING.large }]}>
			<FlatList
				showsVerticalScrollIndicator={false}
				data={data?.data ?? []}
				contentContainerStyle={{ gap: normalize(10) }}
				ListEmptyComponent={
					<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
						<PalRiderText>No areas found</PalRiderText>
					</View>
				}
				ListFooterComponent={
					<>
						{companyAreaAddressUser.company_area_address_user_role?.name == 'Owner' && (
							<LinearGradient
								style={styles.addContainer}
								colors={[colors.red[500], colors.orange[500]]}
								start={{ x: 0, y: 1 }}
								end={{ x: 1, y: 0 }}
							>
								<Pressable
									style={styles.addButton}
									onPress={() => {
										navigation.navigate('AppCompanyStack', {
											screen: 'CompanyProfileStack',
											params: {
												screen: 'CompanyAreaStack',
												params: {
													screen: 'CompanyAreaCreate',
													params: {
														company_id: companyAreaAddressUser.company_id!,
													},
												},
											},
										});
									}}
								>
									<Icon name="BuildingIconSvg" width={20} height={35} color={colors.white} />
									<PalRiderText fontSize={font.small} fontFamily={FontFamily.Semibold} color={colors.white}>
										{t('screen.company.profile.areas_screen.add_new_area')}
									</PalRiderText>
								</Pressable>
							</LinearGradient>
						)}
					</>
				}
				refreshControl={<RefreshControl onRefresh={refreshList} refreshing={isFetching} />}
				renderItem={({ item: areae }) => {
					const contextMenuActions: Array<MenuAction> = [
						{ id: 'show', title: t('common.show') },
						{
							id: 'show_addresses',
							title: t('screen.company.profile.areas_screen.show_addresses'),
							attributes: {
								hidden: !(
									companyAreaAddressUser.company_area_address_user_role?.name == 'Owner' ||
									companyAreaAddressUser.company_area_address_user_role?.name == 'Manager'
								),
							},
						},
						{
							id: 'update',
							title: t('common.update'),
							attributes: {
								hidden: !(
									companyAreaAddressUser.company_area_address_user_role?.name == 'Owner' ||
									companyAreaAddressUser.company_area_address_user_role?.name == 'Manager'
								),
							},
						},
						{
							id: 'delete',
							title: t('common.delete'),
							attributes: {
								hidden: !(
									companyAreaAddressUser.company_area_address_user_role?.name == 'Owner' ||
									companyAreaAddressUser.company_area_address_user_role?.name == 'Manager'
								),
							},
						},
					];

					return (
						<MenuView
							actions={contextMenuActions}
							shouldOpenOnLongPress={false}
							isAnchoredToRight
							onPressAction={({ nativeEvent }) => {
								if (nativeEvent.event == 'show') {
									navigation.navigate('AppCompanyStack', {
										screen: 'CompanyProfileStack',
										params: {
											screen: 'CompanyAreaStack',
											params: {
												screen: 'CompanyAreaView',
												initial: true,
												params: {
													company_area_id: areae.id,
												},
											},
										},
									});
									return;
								}
								if (nativeEvent.event == 'show_addresses') {
									navigation.navigate('AppCompanyStack', {
										screen: 'CompanyProfileStack',
										params: {
											screen: 'CompanyAreaStack',
											params: {
												screen: 'CompanyAreaAddresses',
												params: {
													company_area_id: areae.id,
													company_id: areae.company_id,
												},
											},
										},
									});
								}
								if (nativeEvent.event === 'update') {
									// handleUpdateAction(vehicle.id)
								}
								if (nativeEvent.event === 'Delete') {
									// handleDeleteAction(vehicle.id, vehicle.is_active);
									// navigation.push('CompanyAreaView', {
									// 	company_area_id: areae.id,
									// });
								}
							}}
						>
							<View style={styles.areaContainer}>
								<View>
									<Icon name="BuildingIconSvg" width={20} height={35} />
								</View>
								<View style={styles.areaInfoContainer}>
									<PalRiderText fontFamily={FontFamily.Semibold} fontSize={14}>
										{areae.name}
									</PalRiderText>
									<ScrollView
										horizontal
										showsHorizontalScrollIndicator={false}
										contentContainerStyle={styles.areaBadgeContainer}
									>
										<View style={styles.areaBadge}>
											<PalRiderText fontFamily={FontFamily.Semibold} fontSize={10} color={colors.white}>
												{t('screen.company.profile.areas_screen.location', {
													prop: areae.company_area_addresses?.length,
												})}
											</PalRiderText>
										</View>
									</ScrollView>
								</View>
								<View>
									<Icon name="ChevronRightIconSvg" width={16} height={16} />
								</View>
							</View>
						</MenuView>
					);
				}}
			/>
		</View>
	);
};
const styles = StyleSheet.create({
	container: {
		backgroundColor: colors.white,
		flex: 1,
	},
	areaContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		borderWidth: 1,
		borderColor: colors.gray[200],
		padding: PADDING.large,
		gap: PADDING.large,
		borderRadius: PADDING.large,
	},
	areaInfoContainer: {
		flex: 1,
		gap: PADDING.small,
	},
	areaBadgeContainer: {
		flexDirection: 'row',
		gap: PADDING.small,
	},
	areaBadge: {
		padding: PADDING.small,
		backgroundColor: colors.orange[600],
		borderRadius: PADDING.large,
		paddingHorizontal: PADDING.medium,
		justifyContent: 'center',
		alignItems: 'center',
	},
	addContainer: {
		borderRadius: PADDING.medium,
	},
	addButton: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: PADDING.medium,
		padding: PADDING.small,
		paddingHorizontal: PADDING.medium,
	},
});
export default AppCompanyProfileCompanyAreasScreen;
