import React, { useImperativeHandle } from 'react';
import { forwardRef, ForwardRefRenderFunction } from 'react';
import { PermissionsAndroid, Platform, View } from 'react-native';
import { check, openSettings, PERMISSIONS, request, RESULTS } from 'react-native-permissions';
import DocumentPicker, { DocumentPickerResponse, pick } from '@react-native-documents/picker';
import { CloseIconSvg } from '@/assets/svg/ui';
import PalRiderText from './PalRiderText';
import colors from '@/theme/colors';
import { PADDING } from '@/theme/responsive';
import PalRiderButton from './PalRiderButton';
import { FontFamily } from '@/theme/fonts';
import { useModal } from './ModalProvider';
import WarningModal from './custom-modal/WarningModal';

type PalRiderFilePickerProps = {
	onFileSelected: (files: DocumentPickerResponse[]) => void;
};
export type PalRiderFilePickerRef = {
	openFilePicker: (multiSelect?: boolean) => void;
};
const DeniedPermissionModal = () => {
	return (
		<View
			style={{
				flex: 1,
				justifyContent: 'center',
				alignItems: 'center',
				gap: PADDING.xlarge,
			}}
		>
			<CloseIconSvg color={colors.red[600]} width={32} height={32} />
			<PalRiderText>Please give permission for select file.</PalRiderText>
			<PalRiderButton variant="dark" style={{ width: '100%' }} onPress={() => openSettings()}>
				<PalRiderText color={colors.white} fontFamily={FontFamily.Semibold}>
					Go To Settings
				</PalRiderText>
			</PalRiderButton>
		</View>
	);
};
const PalRiderFilePicker: ForwardRefRenderFunction<PalRiderFilePickerRef, PalRiderFilePickerProps> = (props, ref) => {
	useImperativeHandle(ref, () => ({
		openFilePicker: (multiSelect) => handleFilePick(multiSelect),
	}));
	const { showGlobalModal } = useModal();
	const requestStoragePermission = async () => {
		const permission =
			Platform.OS === 'android' ? PERMISSIONS.ANDROID.READ_EXTERNAL_STORAGE : PERMISSIONS.IOS.MEDIA_LIBRARY;

		const result = await check(permission);

		if (result === RESULTS.GRANTED) {
			return true;
		} else if (result === RESULTS.DENIED) {
			if (Platform.OS === 'android') {
				const granted = await PermissionsAndroid.request(PERMISSIONS.ANDROID.READ_MEDIA_IMAGES, {
					title: 'Camera Permission',
					message: 'App needs access to your camera ' + 'so you can take pictures.',
					buttonNeutral: 'Ask Me Later',
					buttonNegative: 'Cancel',
					buttonPositive: 'OK',
				});
				if (granted === PermissionsAndroid.RESULTS.GRANTED) {
					return true;
				} else {
					showGlobalModal({
						children: <DeniedPermissionModal />,
					});
					return false;
				}
			} else {
				await request(permission);
			}
			return false;
		} else if (result === RESULTS.BLOCKED) {
			showGlobalModal({
				children: <WarningModal text="Please give permission for select file.(blocked)" />,
			});
			return false;
		}
		return false;
	};

	const handleFilePick = async (multiSelect: boolean = true) => {
		const hasPermission = await requestStoragePermission();
		if (hasPermission) {
			try {
				const [...res] = await pick({
					allowMultiSelection: multiSelect,
					allowVirtualFiles: true,
					mode: 'open',
				});
				props.onFileSelected(res);
			} catch (err) {
				if (DocumentPicker.isErrorWithCode(err)) {
					console.log('User canceled file picker');
				} else {
					console.error('File picking error:', err);
				}
			}
		}
	};
	return <></>;
};
export default forwardRef(PalRiderFilePicker);
