const { format } = Intl.NumberFormat('en-UK', {
	currency: 'GBP',
	style: 'currency',
});

const WalletWithDrawRequestItemRender: React.FC<{ item: CourierWalletWithdrawRequestDTO }> = ({ item }) => {
	const withdrawRequestStatusColor = (status: CourierWalletWithdrawRequestDTO['status']): string => {
		switch (status) {
			case 'processing':
				return colors.yellow[600];
			case 'accepted':
				return colors.green[600];
			case 'requested':
				return colors.orange[600];
			case 'rejected':
				return colors.red[600];
		}
	};
	return (
		<View>
			<View
				style={{ paddingHorizontal: PADDING.large, flexDirection: 'row', gap: PADDING.large, alignItems: 'center' }}
			>
				<View style={styles.transactionItemContainer}>
					<View style={styles.transactionIconContainer}>
						<Icon name="TransferFillIconSvg" />
					</View>
					<PalRiderText fontSize={font.mini} color={colors.gray[500]}>
						{formatHumanReadableDate(item.created_at)}
					</PalRiderText>
				</View>
				<View style={styles.transactionAmountContainer}>
					<PalRiderText
						color={withdrawRequestStatusColor(item.status)}
						fontSize={font.mini}
						fontFamily={FontFamily.Semibold}
					>
						{format(item.amount)}
					</PalRiderText>
					<View
						style={[
							styles.transactionStatusContainer,
							{
								backgroundColor: withdrawRequestStatusColor(item.status),
							},
						]}
					>
						<PalRiderText color={colors.white} fontSize={font.mini} fontFamily={FontFamily.Semibold}>
							{snakeToHumanReadable(item.status)}
						</PalRiderText>
					</View>
				</View>
			</View>
		</View>
	);
};

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCourierProfileStackParamList, 'CourierWalletWithdraw'>,
	CompositeScreenProps<
		BottomTabScreenProps<AppCourierTabParamList, 'CourierProfileStack'>,
		NativeStackScreenProps<RootStackParamList>
	>
>;
const AppCourierProfileWalletWithdrawScreen: React.FC<Props> = () => {
	const [getCourierWalletWithdrawalList, { data, isLoading }] = useLazyCourierWalletWithdrawRequestListQuery();
	const [walletWithdrawRequest] = useLazyCourierWalletWithdrawRequestQuery();
	const [selectedCourierBankAccountId, setSelectedCourierBankAccountId] = useState('');
	const walletWithdrawRequestBottomModalRef = useRef<BottomSheetModal>(null);
	const [getCourierBankAccounts, { data: courierBankAccounts }] = useLazyGetCourierBankAccountsQuery();
	const { showGlobalModal, hideGlobalModal } = useModal();
	const insets = useSafeAreaInsets();

	const memoCourierBankAccounts = useMemo(() => {
		if (courierBankAccounts?.data.length == 0) return [];
		return courierBankAccounts?.data.map((bankAccount) => ({
			label: bankAccount.title,
			value: bankAccount.id,
		})) as TFlatList;
	}, [courierBankAccounts]);

	const loadData = async () => {
		showGlobalModal({
			children: <LoadingModal />,
		});
		const result = await getCourierWalletWithdrawalList();
		if (result.error) {
			showGlobalModal({
				children: <WarningModal text="Something went wrong, cannot load data" />,
			});
			return;
		}
		hideGlobalModal();
	};

	const handleWithdrawRequestModalOpen = async () => {
		await getCourierBankAccounts({ page: 1, size: 100 });
		walletWithdrawRequestBottomModalRef.current?.present();
	};
	const handleWithdrawRequest = async () => {
		showGlobalModal({
			children: <LoadingModal />,
		});
		const result = await walletWithdrawRequest(selectedCourierBankAccountId);
		if (result.error) {
			const error = result.error as FetchBaseQueryErrorExpected;
			showGlobalModal({
				children: <WarningModal text={error.data.title} />,
			});
			return;
		}
		showGlobalModal({
			children: <SuccessModal text="Courier wallet withdraw requested" />,
		});
	};

	useEffect(() => {
		loadData();
	}, []);
	return (
		<View style={styles.container}>
			<BottomSheetModal enableDynamicSizing index={0} ref={walletWithdrawRequestBottomModalRef}>
				<BottomSheetView
					style={{ padding: PADDING.large, paddingBottom: insets.bottom + PADDING.large, gap: PADDING.large }}
				>
					<View style={{ marginVertical: PADDING.large }}>
						<View style={{ flexDirection: 'row', columnGap: PADDING.medium }}>
							<PalRiderText style={globalStyles.titleTextStyle}>Select Bank Account</PalRiderText>
						</View>
						<Dropdown
							{...globalStyles.dropdownProps}
							options={memoCourierBankAccounts}
							selectedValue={selectedCourierBankAccountId}
							onValueChange={(value) => setSelectedCourierBankAccountId(value as string)}
							autoCloseOnSelect
							isMultiple={false}
						/>
					</View>
					<PalRiderButton variant="success" onPress={handleWithdrawRequest}>
						<PalRiderText color={colors.white}>Request</PalRiderText>
					</PalRiderButton>
				</BottomSheetView>
			</BottomSheetModal>
			<FlatList
				data={data?.data ?? []}
				style={{ backgroundColor: colors.gray[50] }}
				contentContainerStyle={styles.listContainerStyle}
				refreshControl={<RefreshControl refreshing={isLoading} onRefresh={loadData} />}
				ListEmptyComponent={
					<View style={globalStyles.centeredViewStyle}>
						<PalRiderText>Has No Request</PalRiderText>
					</View>
				}
				renderItem={({ item }) => <WalletWithDrawRequestItemRender item={item} />}
			/>
			<View style={{ padding: PADDING.large }}>
				<PalRiderButton variant="dark" onPress={handleWithdrawRequestModalOpen}>
					<PalRiderText color={colors.white}>Request A Withdraw</PalRiderText>
				</PalRiderButton>
			</View>
		</View>
	);
};
