import React, { useEffect } from 'react';
import { ActivityIndicator, ScrollView, StyleSheet, TouchableOpacity, View } from 'react-native';
import colors from '@/theme/colors.ts';
import { font, PADDING } from '@/theme/responsive.ts';
import PalRiderText from '@/components/PalRiderText.tsx';
import { CompositeScreenProps } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import { AppCourierProfileStackParamList, AppCourierTabParamList } from '@/navigation/courier-navigation';
import { useLazyGetCourierVehicleQuery } from '@/services/api/courier/courier-vehicle';
import { FontFamily } from '@/theme/fonts';
import { snakeToHumanReadable } from '@/utils';
import moment from 'moment';
import Icon from '@/components/Icon';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCourierProfileStackParamList, 'CourierVehicleView'>,
	CompositeScreenProps<
		BottomTabScreenProps<AppCourierTabParamList, 'CourierProfileStack'>,
		NativeStackScreenProps<RootStackParamList>
	>
>;

const AppCourierProfileVehicleViewScreen: React.FC<Props> = ({ route }) => {
	const [getCourierVehicle, { data: vehicle, isFetching }] = useLazyGetCourierVehicleQuery();

	useEffect(() => {
		if (route.params.courier_vehicle_id) {
			getCourierVehicle({ courier_vehicle_id: route.params.courier_vehicle_id });
		}
	}, [route.params.courier_vehicle_id]);

	const renderStatusIcon = (status: string) => {
		if (status === 'approved') return <Icon name="VerifiedIconSvg" width={20} height={20} color={colors.green[600]} />;
		if (status === 'pending' || status === 'refused')
			return <Icon name="UnverifiedIconSvg" width={20} height={20} color={colors.red[600]} />;
		return null;
	};

	return (
		<View style={styles.container}>
			{!vehicle && isFetching && <ActivityIndicator size="large" color={colors.blue[600]} />}
			{vehicle && (
				<ScrollView contentInsetAdjustmentBehavior="automatic" contentContainerStyle={styles.scrollContent}>
					{/* Card Container */}
					<View style={styles.card}>
						{/* Vehicle Type */}
						<View style={styles.infoItem}>
							<PalRiderText style={styles.infoTitle}>Type</PalRiderText>
							<PalRiderText style={styles.infoText}>{snakeToHumanReadable(vehicle.data.type)}</PalRiderText>
						</View>

						{/* Plate Number */}
						{vehicle.data.type !== 'bike' && (
							<View style={styles.infoItem}>
								<PalRiderText style={styles.infoTitle}>Plate Number</PalRiderText>
								<PalRiderText style={styles.infoText}>{vehicle.data.plate_number}</PalRiderText>
							</View>
						)}

						{/* Status */}
						<View style={styles.infoItem}>
							<PalRiderText style={styles.infoTitle}>Status</PalRiderText>
							<View style={styles.statusRow}>
								{renderStatusIcon(vehicle.data.status)}
								<PalRiderText
									style={[
										styles.infoText,
										vehicle.data.status === 'approved' && { color: colors.green[600] },
										vehicle.data.status === 'refused' && { color: colors.red[600] },
									]}
								>
									{snakeToHumanReadable(vehicle.data.status)}
								</PalRiderText>
							</View>
						</View>

						{/* Conditional Fields */}
						{vehicle.data.status === 'refused' && vehicle.data.rejected_at && (
							<View style={styles.infoItem}>
								<PalRiderText style={styles.infoTitle}>Rejected At</PalRiderText>
								<PalRiderText style={styles.infoText}>{moment(vehicle.data.rejected_at).fromNow()}</PalRiderText>
							</View>
						)}

						{vehicle.data.status === 'refused' && vehicle.data.courier_vehicle_refuse_type && (
							<View style={styles.infoItem}>
								<PalRiderText style={styles.infoTitle}>Rejected For</PalRiderText>
								<PalRiderText style={styles.infoText}>{vehicle.data.courier_vehicle_refuse_type.name}</PalRiderText>
							</View>
						)}

						{vehicle.data.status === 'approved' && vehicle.data.confirmed_at && (
							<View style={styles.infoItem}>
								<PalRiderText style={styles.infoTitle}>Confirmed At</PalRiderText>
								<PalRiderText style={styles.infoText}>{moment(vehicle.data.confirmed_at).fromNow()}</PalRiderText>
							</View>
						)}

						{/* Photos */}
						<View style={styles.infoItem}>
							<PalRiderText style={styles.infoTitle}>Photos</PalRiderText>
							<TouchableOpacity activeOpacity={0.8}>
								<PalRiderText fontFamily={FontFamily.Semibold} color={colors.blue[600]}>
									Show Photos ({vehicle.data.courier_vehicle_photos.length})
								</PalRiderText>
							</TouchableOpacity>
						</View>
					</View>
				</ScrollView>
			)}
		</View>
	);
};

const styles = StyleSheet.create({
	container: {
		backgroundColor: colors.gray[50],
		flex: 1,
	},
	scrollContent: {
		padding: PADDING.large,
	},
	card: {
		backgroundColor: colors.white,
		borderRadius: PADDING.large,
		shadowColor: '#000',
		shadowOpacity: 0.06,
		shadowOffset: { width: 0, height: 4 },
		shadowRadius: 8,
		elevation: 4,
		gap: PADDING.medium,
	},
	infoItem: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		padding: PADDING.large,
		alignItems: 'center',
		borderBottomWidth: StyleSheet.hairlineWidth,
		borderColor: colors.gray[200],
	},
	infoTitle: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.small,
		color: colors.gray[700],
	},
	infoText: {
		fontFamily: FontFamily.Regular,
		fontSize: font.small,
		color: colors.gray[600],
	},
	statusRow: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: PADDING.mini,
	},
});

export default AppCourierProfileVehicleViewScreen;
