import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import React, { useEffect, useMemo } from 'react';
import { View, Text, StyleSheet } from 'react-native';
import Animated, { useSharedValue, useAnimatedStyle, withTiming, Easing } from 'react-native-reanimated';

const FONT_SIZE = 12;
const DIGIT_HEIGHT = FONT_SIZE * 1.2; // ≈14.4

const RollingDigit = ({ digit }: { digit: number }) => {
	const offset = useSharedValue(-digit * DIGIT_HEIGHT);

	useEffect(() => {
		offset.value = withTiming(-digit * DIGIT_HEIGHT, {
			duration: 500,
			easing: Easing.out(Easing.quad),
		});
	}, [digit]);

	const animatedStyle = useAnimatedStyle(() => ({
		transform: [{ translateY: offset.value }],
	}));

	return (
		<View style={styles.digitContainer}>
			<Animated.View style={[styles.digitsWrapper, animatedStyle]}>
				{Array.from({ length: 10 }, (_, i) => (
					<Text key={i} style={styles.digit}>
						{i}
					</Text>
				))}
			</Animated.View>
		</View>
	);
};
const formatToGBP = (input: string): string => {
	const cleaned = input.replace(/[^0-9.]/g, '');
	const value = parseFloat(cleaned);
	if (isNaN(value)) return '£0.00';

	return new Intl.NumberFormat('en-GB', {
		style: 'currency',
		currency: 'GBP',
		minimumFractionDigits: 2,
	}).format(value);
};

export const RollingCurrencyText = ({ input }: { input: string }) => {
	const formattedGBP = useMemo(() => formatToGBP(input), [input]);

	return (
		<View style={styles.row}>
			{formattedGBP.split('').map((char, index) =>
				/\d/.test(char) ? (
					<RollingDigit key={index} digit={parseInt(char)} />
				) : (
					<Text key={index} style={styles.staticChar}>
						{char}
					</Text>
				),
			)}
		</View>
	);
};

const styles = StyleSheet.create({
	row: {
		flexDirection: 'row',
		alignItems: 'flex-end',
	},
	digitContainer: {
		height: DIGIT_HEIGHT,
		overflow: 'hidden',
		width: FONT_SIZE * 0.6, // narrow width for digit
	},
	digitsWrapper: {
		flexDirection: 'column',
	},
	digit: {
		height: DIGIT_HEIGHT,
		fontSize: FONT_SIZE,
		textAlign: 'center',
		color: colors.orange[600],
		fontFamily: FontFamily.Black,
	},
	staticChar: {
		fontSize: FONT_SIZE - 1,
		fontFamily: FontFamily.Black,
		color: colors.orange[600],
	},
});
