import React from 'react';
import { ScrollView, StyleSheet, View } from 'react-native';
import colors from '@/theme/colors.ts';
import { useAppSelector } from '@/redux/hooks.ts';
import { useFormik } from 'formik';
import PalRiderTextInput from '@/components/PalRiderTextInput.tsx';
import { normalize, PADDING } from '@/theme/responsive.ts';
import PalRiderPhoneInput from '@/components/PalRiderPhoneInput.tsx';
import { parseAuthPhoneNumber } from '@/utils';
import PalRiderButton from '@/components/PalRiderButton.tsx';
import { buttonStyling } from '@/theme/defaults.ts';
import PalRiderText from '@/components/PalRiderText.tsx';
import { BaseUserDTO } from 'palriderapptypes/common';
import { CompositeScreenProps } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import { AppCourierProfileStackParamList, AppCourierTabParamList } from '@/navigation/courier-navigation';
import { useTranslation } from 'react-i18next';
import Icon from '@/components/Icon';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCourierProfileStackParamList, 'CourierMyAccount'>,
	CompositeScreenProps<
		BottomTabScreenProps<AppCourierTabParamList, 'CourierProfileStack'>,
		NativeStackScreenProps<RootStackParamList>
	>
>;

const AppCourierProfileMyAccountScreen: React.FC<Props> = () => {
	const { t } = useTranslation();
	const userSlice = useAppSelector((x) => x.userSlice.user!);

	const formik = useFormik<Partial<BaseUserDTO>>({
		initialValues: {
			name: userSlice.name!,
			surname: userSlice.surname!,
			email: userSlice.email,
			phone_number: parseAuthPhoneNumber(userSlice.phone_number),
		},
		onSubmit: () => {},
	});

	return (
		<View style={styles.container}>
			<ScrollView contentContainerStyle={styles.scrollContent} contentInsetAdjustmentBehavior="automatic">
				{/* Profile Header */}
				<View style={styles.profileHeader}>
					<View style={styles.avatarContainer}>
						<Icon name="UserGroupIconSvg" width={64} height={64} color={colors.gray[600]} />
					</View>
					<PalRiderText fontSize={normalize(18)} fontFamily="Semibold">
						{userSlice.name} {userSlice.surname}
					</PalRiderText>
					<PalRiderText fontSize={normalize(12)} color={colors.gray[500]}>
						{userSlice.email}
					</PalRiderText>
				</View>

				{/* Account Info Card */}
				<View style={styles.card}>
					<PalRiderTextInput
						title={t('common.name')}
						value={formik.values.name ?? ''}
						onChangeText={formik.handleChange('name')}
						onBlur={formik.handleBlur('name')}
					/>
					<PalRiderTextInput
						title={t('common.surname')}
						value={formik.values.surname ?? ''}
						onChangeText={formik.handleChange('surname')}
						onBlur={formik.handleBlur('surname')}
					/>
					<PalRiderTextInput
						title={t('common.email')}
						value={formik.values.email}
						onChangeText={formik.handleChange('email')}
						onBlur={formik.handleBlur('email')}
						leftComponent={<Icon name="EmailSignIconSvg" width={16} height={16} color={colors.gray[500]} />}
						rightComponent={<Icon name="UnverifiedIconSvg" width={20} height={20} color={colors.red[600]} />}
					/>
					<PalRiderPhoneInput
						areaCode="44"
						onAreaCodePress={() => {}}
						title={t('common.phone_number')}
						value={formik.values.phone_number}
						onChangeText={formik.handleChange('phone_number')}
						onBlur={formik.handleBlur('phone_number')}
						editable={false}
						rightComponent={<Icon name="VerifiedIconSvg" width={20} height={20} color={colors.green[600]} />}
					/>
				</View>

				{/* Update Button */}
				<View style={styles.buttonContainer}>
					<PalRiderButton style={[buttonStyling.dark, styles.updateButton]}>
						<PalRiderText color={colors.white} fontFamily="Semibold">
							{t('common.update')}
						</PalRiderText>
					</PalRiderButton>
				</View>
			</ScrollView>
		</View>
	);
};

const styles = StyleSheet.create({
	container: {
		backgroundColor: colors.gray[50],
		flex: 1,
	},
	scrollContent: {
		padding: PADDING.large,
		gap: normalize(16),
	},
	profileHeader: {
		alignItems: 'center',
		gap: normalize(6),
		marginBottom: PADDING.large,
	},
	avatarContainer: {
		width: 80,
		height: 80,
		borderRadius: 40,
		backgroundColor: colors.gray[200],
		justifyContent: 'center',
		alignItems: 'center',
		marginBottom: PADDING.small,
	},
	card: {
		backgroundColor: colors.white,
		borderRadius: PADDING.medium,
		padding: PADDING.large,
		gap: normalize(12),
		shadowColor: '#000',
		shadowOpacity: 0.06,
		shadowOffset: { width: 0, height: 2 },
		shadowRadius: 6,
		elevation: 3,
	},
	buttonContainer: {
		marginTop: PADDING.large,
	},
	updateButton: {
		borderRadius: PADDING.medium,
		paddingVertical: PADDING.medium,
	},
});

export default AppCourierProfileMyAccountScreen;
