import PalRiderButton from '@/components/PalRiderButton.tsx';
import PalRiderPhoneCodeInput from '@/components/PalRiderPhoneCodeInput.tsx';
import PalRiderText from '@/components/PalRiderText.tsx';
import useUserNavigation from '@/hooks/useUserNavigation.tsx';
import { useAppDispatch, useAppSelector } from '@/redux/hooks.ts';
import { useAuthenticateVerifyCompanyAreaAddressUserMutation } from '@/services/api/company/auth-company-area-address-user';
import colors from '@/theme/colors.ts';
import { buttonStyling } from '@/theme/defaults.ts';
import { FontFamily } from '@/theme/fonts.ts';
import { font, normalize, PADDING } from '@/theme/responsive.ts';
import React from 'react';
import { StyleSheet, View } from 'react-native';
import { KeyboardAwareScrollView } from 'react-native-keyboard-aware-scroll-view';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useCompanyOnboardingMutation } from '@/services/api/company/company-api';
import { setToken } from '@/redux/slices/userSlice.ts';
import LottieView from 'lottie-react-native';
import { useModal } from '@/components/ModalProvider';
import { isFetchBaseQueryError, safeAreaEdges } from '@/utils';
import WarningModal from '@/components/custom-modal/WarningModal';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { useTranslation } from 'react-i18next';

type Props = {
	prevStep: () => void;
};
const SignUpCompanyPhoneCodeStep: React.FC<Props> = ({ prevStep }) => {
	const { t } = useTranslation();
	const dispatch = useAppDispatch();
	const companyOnboardingSelector = useAppSelector((x) => x.companyOnboardingSlice);
	const [verifyCompanyAreaAddressUser, { isError }] = useAuthenticateVerifyCompanyAreaAddressUserMutation();
	const { showGlobalModal, hideGlobalModal } = useModal();

	const [onboardCompany] = useCompanyOnboardingMutation();
	const { handle: handleNavigation } = useUserNavigation();

	const verificationCodeComplete = async (code: string) => {
		showGlobalModal({
			children: <LoadingModal />,
			backgroundColor: colors.transparent,
			preventHiding: true,
		});
		const res = await verifyCompanyAreaAddressUser({
			phone_number: companyOnboardingSelector.area.user.phone_number!,
			code,
		});

		if (res.error && isFetchBaseQueryError(res.error)) {
			hideGlobalModal();
			showGlobalModal({
				children: <WarningModal text={res.error.data.title} />,
			});
			return;
		}

		if (res.data) {
			showGlobalModal({
				children: <LoadingModal />,
				backgroundColor: colors.transparent,
				preventHiding: true,
			});
			dispatch(setToken(res.data.data));

			const onboardingResult = await onboardCompany(companyOnboardingSelector);

			if (onboardingResult.error && isFetchBaseQueryError(onboardingResult.error)) {
				hideGlobalModal();
				showGlobalModal({
					children: <WarningModal text={onboardingResult.error.data.title} />,
				});
				return;
			}
			hideGlobalModal();
			await handleNavigation();
		}
	};
	return (
		<SafeAreaView
			edges={safeAreaEdges}
			style={{
				flex: 1,
				backgroundColor: colors.white,
				padding: PADDING.large,
			}}
		>
			<KeyboardAwareScrollView
				style={styles.container}
				overScrollMode="never"
				contentContainerStyle={styles.scrollViewContentContainerStyle}
				showsVerticalScrollIndicator={false}
				keyboardShouldPersistTaps="handled"
			>
				<View style={styles.contentContainer}>
					<View style={{ alignItems: 'center', gap: PADDING.large }}>
						<LottieView
							style={{ width: '100%', height: 220 }}
							source={require('@/assets/animations/phone-verication.json')}
							autoPlay
							loop
						/>
						<PalRiderText fontSize={font.mini} color={colors.gray[600]} style={{ textAlign: 'center' }}>
							{t('screen.auth.sign_up_company.user_auth.authenticate_description')}
						</PalRiderText>
					</View>
					<PalRiderText style={styles.title}>
						{t('screen.auth.sign_up_company.user_auth.code_verification')}
					</PalRiderText>
					<PalRiderPhoneCodeInput
						containerStyle={{
							borderWidth: normalize(1),
							borderColor: isError ? colors.red[600] : colors.transparent,
						}}
						onComplete={verificationCodeComplete}
					/>
					<View style={styles.codeView}>
						<PalRiderText style={styles.descriptionText}>
							{t('screen.auth.sign_up_company.user_auth.verification_description')}
							<PalRiderText style={styles.againSendCodeText} onPress={() => {}}>
								{t('screen.auth.sign_up_company.user_auth.resend_code')}
							</PalRiderText>
						</PalRiderText>
					</View>
				</View>
			</KeyboardAwareScrollView>
			<View
				style={{
					flexDirection: 'row',
					gap: normalize(10),
				}}
			>
				<PalRiderButton style={[buttonStyling.dark, { flex: 1 }]} onPress={() => prevStep()}>
					<PalRiderText color="white">{t('common.go_back')}</PalRiderText>
				</PalRiderButton>
			</View>
		</SafeAreaView>
	);
};
export default SignUpCompanyPhoneCodeStep;

const styles = StyleSheet.create({
	container: {
		flex: 1,
	},
	contentContainer: {
		paddingHorizontal: normalize(20),
		justifyContent: 'center',
	},
	contentSheetContainer: {
		alignItems: 'center',
		padding: normalize(16),
	},
	title: {
		textAlign: 'center',
		fontSize: normalize(30),
		color: colors.black,
		fontFamily: FontFamily.Bold,
	},
	description: {
		textAlign: 'center',
		fontSize: normalize(14),
		fontFamily: FontFamily.Semibold,
		color: colors.gray[200],
		marginTop: normalize(10),
		marginBottom: normalize(30),
	},
	codeView: {
		flexDirection: 'row',
		alignItems: 'center',
		marginTop: normalize(30),
	},
	descriptionText: {
		flex: 1,
		textAlign: 'center',
		color: colors.gray[600],
		fontSize: normalize(14),
		fontFamily: FontFamily.Semibold,
	},
	againSendCodeText: {
		textDecorationLine: 'underline',
		color: colors.black,
		fontSize: normalize(14),
	},
	errorText: {
		color: colors.gray[600],
		fontSize: normalize(14),
		marginBottom: normalize(20),
		alignSelf: 'flex-end',
	},
	recaptchaContainer: {
		backgroundColor: colors.transparent,
	},
	continueButton: {
		marginVertical: normalize(16),
	},
	continueButtonText: {
		fontFamily: FontFamily.Bold,
		color: colors.white,
	},
	scrollViewContentContainerStyle: {
		paddingTop: normalize(20),
		alignContent: 'center',
		justifyContent: 'center',
		flex: 1,
		borderTopLeftRadius: normalize(20),
		borderTopRightRadius: normalize(20),
	},
	goBackContainer: {
		position: 'absolute',
		zIndex: 9999,
		left: 10,
		width: normalize(30),
		height: normalize(30),
		justifyContent: 'center',
		alignItems: 'center',
	},
});
