import colors from '@/theme/colors';
import { normalize, PADDING } from '@/theme/responsive';
import React from 'react';
import { StyleSheet, TouchableOpacity, View, ViewStyle } from 'react-native';
import { CheckIconSvg } from '@/assets/svg/ui.tsx';

type PalRiderCheckBoxProps = {
	value: boolean;
	isDisabled?: boolean;
	onValueChange?: (value: boolean) => void;
	containerStyle?: ViewStyle;
	error?: string;
	children?: React.ReactNode;
};

const PalRiderCheckBox: React.FC<PalRiderCheckBoxProps> = ({
	value,
	isDisabled,
	onValueChange,
	error,
	containerStyle,
	children,
}: PalRiderCheckBoxProps) => {
	return (
		<TouchableOpacity
			activeOpacity={isDisabled ? 1 : 0.75}
			style={[
				styles.container,
				containerStyle,
				{
					flexDirection: children ? 'row' : 'column',
					gap: children ? PADDING.medium : 0,
				},
			]}
			onPress={() => {
				if (isDisabled) {
					return;
				}
				if (typeof onValueChange === 'function') {
					onValueChange(!value);
				}
			}}
		>
			<View
				style={[
					styles.checkView,
					{
						borderColor: error ? colors.red[600] : colors.gray[200],
					},
				]}
			>
				{value && <CheckIconSvg />}
			</View>
			{children}
		</TouchableOpacity>
	);
};
const styles = StyleSheet.create({
	container: {
		marginRight: normalize(4, 'width'),
		paddingRight: normalize(10, 'width'),
		paddingVertical: normalize(6),
		backgroundColor: colors.transparent,
	},
	checkView: {
		width: normalize(16),
		height: normalize(16),
		backgroundColor: colors.gray[100],
		justifyContent: 'center',
		alignItems: 'center',
		borderRadius: normalize(2),
		borderWidth: normalize(2),
	},
});

export default PalRiderCheckBox;
