import React, { useRef, useState } from 'react';
import {
	Modal,
	Dimensions,
	View,
	TouchableOpacity,
	Text,
	StyleSheet,
	ActivityIndicator,
	Image,
	ScrollView,
} from 'react-native';
import Gallery, { GalleryRef } from 'react-native-awesome-gallery';

type Props = {
	imageUrls: string[];
	initialIndex?: number;
	onClose: () => void;
};

const { width, height } = Dimensions.get('window');
const THUMB_SIZE = 60;

const PalRiderDeliveryGalleryModal: React.FC<Props> = ({ imageUrls, initialIndex = 0, onClose }) => {
	const galleryRef = useRef<GalleryRef>(null);
	const [loadingMap, setLoadingMap] = useState<{ [uri: string]: boolean }>(() =>
		Object.fromEntries(imageUrls.map((uri) => [uri, true])),
	);
	const [currentIndex, setCurrentIndex] = useState(initialIndex);

	const goToPrevious = () => {
		if (currentIndex > 0) {
			const newIndex = currentIndex - 1;
			setCurrentIndex(newIndex);
			galleryRef.current?.setIndex(newIndex);
		}
	};

	const goToNext = () => {
		if (currentIndex < imageUrls.length - 1) {
			const newIndex = currentIndex + 1;
			setCurrentIndex(newIndex);
			galleryRef.current?.setIndex(newIndex);
		}
	};

	const handleLoadEnd = (uri: string) => {
		setLoadingMap((prev) => ({ ...prev, [uri]: false }));
	};

	const renderItem = ({ item }: { item: string }) => (
		<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
			{loadingMap[item] && <ActivityIndicator size="large" color="#fff" style={StyleSheet.absoluteFill} />}
			<Image
				source={{ uri: item }}
				style={{ width, height, resizeMode: 'cover' }}
				onLoadEnd={() => handleLoadEnd(item)}
			/>
		</View>
	);

	return (
		<Modal visible animationType="fade" onRequestClose={onClose}>
			<View style={{ flex: 1, backgroundColor: 'black' }}>
				<Gallery
					ref={galleryRef}
					data={imageUrls}
					initialIndex={initialIndex}
					numToRender={imageUrls.length}
					keyExtractor={(item) => item}
					onSwipeToClose={onClose}
					onIndexChange={setCurrentIndex}
					renderItem={renderItem}
				/>

				{/* Navigation Buttons */}
				<View style={styles.navContainer}>
					{currentIndex > 0 && (
						<TouchableOpacity onPress={goToPrevious} style={styles.navButton}>
							<Text style={styles.navText}>←</Text>
						</TouchableOpacity>
					)}
					{currentIndex < imageUrls.length - 1 && (
						<TouchableOpacity onPress={goToNext} style={styles.navButton}>
							<Text style={styles.navText}>→</Text>
						</TouchableOpacity>
					)}
				</View>

				{/* Thumbnail Strip */}
				<View style={styles.thumbnailContainer}>
					<ScrollView horizontal showsHorizontalScrollIndicator={false}>
						{imageUrls.map((url, index) => (
							<TouchableOpacity
								activeOpacity={0.8}
								key={url}
								onPress={() => {
									setCurrentIndex(index);
									galleryRef.current?.setIndex(index);
								}}
								style={[styles.thumbnailWrapper, currentIndex === index && styles.selectedThumbnail]}
							>
								<Image source={{ uri: url }} style={styles.thumbnail} resizeMode="cover" />
							</TouchableOpacity>
						))}
					</ScrollView>
				</View>
			</View>
		</Modal>
	);
};

const styles = StyleSheet.create({
	navContainer: {
		position: 'absolute',
		top: height / 2 - 25,
		width: width,
		flexDirection: 'row',
		justifyContent: 'space-between',
		paddingHorizontal: 20,
		zIndex: 10,
	},
	navButton: {
		width: 50,
		height: 50,
		backgroundColor: 'rgba(0,0,0,0.5)',
		padding: 10,
		borderRadius: 50,
	},
	navText: {
		position: 'absolute',
		left: 15,
		top: 5,
		color: 'white',
		fontSize: 24,
		fontWeight: 'bold',
	},
	thumbnailContainer: {
		position: 'absolute',
		bottom: 30,
		width: width,
		paddingHorizontal: 10,
	},
	thumbnailWrapper: {
		marginHorizontal: 5,
		borderRadius: 4,
		borderWidth: 2,
		borderColor: 'transparent',
		overflow: 'hidden',
	},
	selectedThumbnail: {
		borderColor: '#00f0ff',
	},
	thumbnail: {
		width: THUMB_SIZE,
		height: THUMB_SIZE,
		borderRadius: 4,
	},
});

export default PalRiderDeliveryGalleryModal;
