import React, { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, View } from 'react-native';
import { useLazyGetCompanyAreaAddressesQuery } from '@/services/api/company/company-area.ts';
import { PalRiderRadio } from '@/components/PalRiderRadio.tsx';
import PalRiderText from '@/components/PalRiderText.tsx';
import PalRiderButton from '@/components/PalRiderButton.tsx';
import colors from '@/theme/colors.ts';
import { font, normalize, PADDING } from '@/theme/responsive.ts';
import { useAppDispatch, useAppSelector } from '@/redux/hooks.ts';
import { FontFamily } from '@/theme/fonts.ts';
import { buttonStyling } from '@/theme/defaults.ts';
import CallRiderBicycleSvg from '@/screens/app/company/call-rider/components/svg/CallRiderBicycleSvg.tsx';
import { setCallRiderCourierCount, setCallRiderState } from '@/redux/slices/callRiderSlice.ts';
import CallRiderMotorcycleIconSvg from '../svg/CallRiderMotorcycleSvg';
import CallRiderCarIconSvg from '../svg/CallRiderCarSvg';
import { useModal } from '@/components/ModalProvider';
import WarningModal from '@/components/custom-modal/WarningModal';
import PalRiderTextInput from '@/components/PalRiderTextInput';
import { useTranslation } from 'react-i18next';
import Icon from '@/components/Icon';

type Props = {
	nextStep: () => void;
};
const CallRiderLocationInfo: React.FC<Props> = ({ nextStep }) => {
	const { t } = useTranslation();
	const userSelector = useAppSelector((x) => x.userSlice?.user?.company_area_address_user);
	const callRiderSelector = useAppSelector((x) => x.callRiderSlice);
	const dispatch = useAppDispatch();
	const { showGlobalModal, hideGlobalModal } = useModal();
	const [
		getAllCompanyAreaAddresses,
		{ data: companyAreaAddresses, isLoading: companyAreaAddressLoading, isFetching: companyAreaAddressFetching },
	] = useLazyGetCompanyAreaAddressesQuery();
	const [selectedLocation, setSelectedLocation] = useState<string | null>(callRiderSelector.company_area_address_id);
	const [selectedRiderTypes, setSelectedRiderTypes] = useState<Array<string>>(callRiderSelector.vehicle_types);
	const [courierCount, setCourierCount] = useState('1');
	const riderOptions = [
		{
			type: 'bike',
			icon: <CallRiderBicycleSvg />,
			title: t('common.bike'),
		},
		{
			type: 'motorcycle',
			icon: <CallRiderMotorcycleIconSvg />,
			title: t('common.motorcycle'),
		},
		{
			type: 'car',
			icon: <CallRiderCarIconSvg />,
			title: t('common.car'),
		},
	];

	const goToNextStep = async () => {
		hideGlobalModal();
		if (!selectedLocation) {
			showGlobalModal({
				children: <WarningModal text={t('screen.company.callrider.location_info.location_not_selected')} />,
			});
			return;
		}
		if (selectedRiderTypes.length === 0) {
			showGlobalModal({
				maxHeight: 200,
				children: <WarningModal text={t('screen.company.callrider.location_info.rider_type_not_selected')} />,
			});
			return;
		}

		dispatch(
			setCallRiderState({
				company_area_id: userSelector?.company_area_id,
				company_area_address_id: selectedLocation,
				vehicle_types: selectedRiderTypes,
			}),
		);
		dispatch(setCallRiderCourierCount(Number(courierCount)));
		nextStep();
	};

	useEffect(() => {
		if (userSelector?.company_area_id) {
			getAllCompanyAreaAddresses({
				page: 1,
				size: 1000,
				company_area_id: userSelector.company_area_id,
			})
				.unwrap()
				.then((res) => {
					setSelectedLocation(res.data[0].id);
				});
		}
	}, []);
	return (
		<ScrollView style={{ flex: 1 }} contentContainerStyle={{ flex: 1 }}>
			<PalRiderRadio value={selectedLocation}>
				{(value) => (
					<ScrollView
						contentContainerStyle={{
							gap: PADDING.large,
							padding: PADDING.large,
						}}
					>
						{(companyAreaAddressLoading || companyAreaAddressFetching) && (
							<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
								<ActivityIndicator />
							</View>
						)}
						{!companyAreaAddressLoading &&
							!companyAreaAddressFetching &&
							companyAreaAddresses?.data.map((address) => (
								<Pressable key={address.id} onPress={() => setSelectedLocation(address.id)} style={styles.addressRadio}>
									<View style={{ flexDirection: 'row', alignItems: 'center', gap: PADDING.medium, flex: 1 }}>
										<Icon name="BuildingIconSvg" />
										<View style={{ flex: 1, paddingRight: PADDING.large }}>
											<PalRiderText
												numberOfLines={1}
												style={{
													fontFamily: FontFamily.Semibold,
													fontSize: font.mini,
												}}
											>
												{address.address}
											</PalRiderText>
										</View>
									</View>
									<View>
										<Icon
											name="CheckCircleIconSvg"
											color={address.id === value ? colors.green[600] : colors.gray[500]}
										/>
									</View>
								</Pressable>
							))}
					</ScrollView>
				)}
			</PalRiderRadio>
			<View style={{ flex: 1 }}>
				<View style={{ padding: PADDING.large }}>
					<PalRiderTextInput
						value={courierCount.toString()}
						onChangeText={(t) => {
							setCourierCount(t);
						}}
						title={t('screen.company.callrider.location_info_step.question')}
					/>
				</View>
				{riderOptions.map((rider, riderIndex) => {
					return (
						<Pressable
							key={'rider-select' + riderIndex}
							onPress={async () => {
								if (selectedRiderTypes.includes(rider.type)) {
									const vehicleType = selectedRiderTypes.filter((x) => x !== rider.type);
									setSelectedRiderTypes(vehicleType);
								} else {
									setSelectedRiderTypes([...selectedRiderTypes, rider.type]);
								}
							}}
							style={[
								styles.riderContainer,
								{
									backgroundColor: selectedRiderTypes.includes(rider.type) ? colors.gray[100] : colors.white,
									borderBottomColor: riderIndex !== riderOptions.length - 1 ? colors.gray[200] : colors.transparent,
									borderBottomWidth: 1,
								},
							]}
						>
							{rider.icon}
							<PalRiderText>{rider.title}</PalRiderText>
							<View
								style={[
									styles.checkIconContainer,
									{
										borderColor: selectedRiderTypes.includes(rider.type) ? colors.black : colors.gray[300],
									},
								]}
							>
								{selectedRiderTypes.includes(rider.type) && <Icon name="CheckIconSvg" />}
							</View>
						</Pressable>
					);
				})}
			</View>
			<View style={{ padding: PADDING.large, position: 'relative', backgroundColor: colors.white }}>
				<PalRiderButton style={[buttonStyling.dark]} onPress={() => goToNextStep()}>
					<PalRiderText color={colors.white}>{t('common.continue')}</PalRiderText>
				</PalRiderButton>
			</View>
		</ScrollView>
	);
};
const styles = StyleSheet.create({
	addressRadio: {
		flexDirection: 'row',
		alignItems: 'center',
		justifyContent: 'space-between',
		borderWidth: 1,
		borderColor: colors.gray[400],
		borderRadius: PADDING.large,
		padding: PADDING.large,
		backgroundColor: colors.white,
	},
	riderContainer: {
		padding: normalize(20),
		justifyContent: 'space-between',
		flexDirection: 'row',
		alignItems: 'center',
	},
	riderTypeContainer: {},
	riderTypeSelectText: {
		textAlign: 'center',
		fontSize: normalize(16),
		fontFamily: FontFamily.Semibold,
		marginVertical: normalize(20),
	},
	checkIconContainer: {
		width: normalize(30),
		height: normalize(30),
		borderWidth: 1,
		borderColor: colors.gray[300],
		borderRadius: normalize(20),
		justifyContent: 'center',
		alignItems: 'center',
	},
});
export default CallRiderLocationInfo;
