import { useAppSelector } from '@/redux/hooks';
import { Platform, StyleSheet, View } from 'react-native';
import PalRiderText from '../PalRiderText';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { PADDING } from '@/theme/responsive';
import { useEffect, useMemo } from 'react';
import Animated, { Easing, useAnimatedStyle, useSharedValue, withTiming } from 'react-native-reanimated';

type Props = {
	children: React.ReactNode;
};

const AppUserOnboardingState: React.FC<Props> = ({ children }) => {
	const userSelector = useAppSelector((x) => x.userSlice);
	const globalLoadSelector = useAppSelector((x) => x.globalLoadSlice);
	const insets = useSafeAreaInsets();
	const hasWaitingState = useMemo(() => {
		return (
			(userSelector.user?.user_type === 'courier' &&
				userSelector.user.courier?.acceptance_waiting_list &&
				userSelector.user.courier?.acceptance_waiting_list.length > 0) ||
			(userSelector.user?.user_type === 'company_area_address_user' &&
				userSelector.user.company_area_address_user?.acceptance_waiting_list &&
				userSelector.user.company_area_address_user?.acceptance_waiting_list.length > 0)
		);
	}, [userSelector.user, userSelector]);

	const bottom = useSharedValue(0); // Start offscreen below
	const opacity = useSharedValue(0); // Start offscreen below

	useEffect(() => {
		if (hasWaitingState && !globalLoadSelector.isLoading) {
			bottom.value = withTiming(insets.bottom + (Platform.OS === 'ios' ? 40 : 60), {
				duration: 300,
				easing: Easing.out(Easing.ease),
			});
			opacity.value = withTiming(1, {
				duration: 300,
				easing: Easing.in(Easing.linear),
			});
		} else {
			bottom.value = 0;
			opacity.value = 0;
		}
	}, [hasWaitingState, insets, globalLoadSelector.isLoading]);

	const animatedStyle = useAnimatedStyle(() => ({
		bottom: bottom.value,
		opacity: opacity.value,
	}));
	return <View style={{ flex: 1, position: 'relative' }}>{children}</View>;
};
const courierOnboardingStateStyles = StyleSheet.create({
	container: {
		position: 'absolute',
		zIndex: 999,
		width: '100%',
		padding: PADDING.large,
		bottom: 0,
	},
	innerContainer: {
		padding: PADDING.large,
		backgroundColor: 'white',
		borderRadius: PADDING.large,
		gap: PADDING.medium,
		boxShadow: '0.3 0.3 10 1 rgba(0,0,0,.25)',
	},
});
export default AppUserOnboardingState;
