import React, { useEffect } from 'react';
import { StyleSheet, View } from 'react-native';
import LinearGradient from 'react-native-linear-gradient';
import LottieView from 'lottie-react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { CompositeScreenProps } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { getBuildNumber, getVersion } from 'react-native-device-info';

import PalRiderText from '@/components/PalRiderText';
import { useAppDispatch } from '@/redux/hooks';
import { setToken } from '@/redux/slices/userSlice';
import useUserNavigation from '@/hooks/useUserNavigation';
import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { normalize } from '@/theme/responsive';

import { RootStackParamList } from '@/navigation';
import { AuthStackParamList } from '@/navigation/auth-navigation';
import { AppCourierTabParamList } from '@/navigation/courier-navigation';
import { AppCompanyTabParamList } from '@/navigation/company-navigation';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { uuidv4Gen } from '@/utils';
import { BASE_URL } from '@env';
import Icon from '@/components/Icon';

export type Props = CompositeScreenProps<
	NativeStackScreenProps<RootStackParamList, 'Splash'>,
	CompositeScreenProps<
		NativeStackScreenProps<AuthStackParamList>,
		CompositeScreenProps<BottomTabScreenProps<AppCourierTabParamList>, BottomTabScreenProps<AppCompanyTabParamList>>
	>
>;

const SplashScreen: React.FC<Props> = () => {
	const insets = useSafeAreaInsets();
	const appVersionInfo = `${getVersion()}(${getBuildNumber()})`;
	const dispatch = useAppDispatch();
	const { handle: handleUserNavigation } = useUserNavigation();

	// Get token from async storage
	const getToken = async (): Promise<string | null> => {
		return await AsyncStorage.getItem('token');
	};

	useEffect(() => {
		(async () => {
			try {
				const token = await getToken();

				if (token) {
					dispatch(setToken(token));
				}
				await handleUserNavigation();

				AsyncStorage.getItem('APP_USER_GOOGLE_MAPS_TOKEN', (value) => {
					if (value == null) {
						AsyncStorage.setItem('APP_USER_GOOGLE_MAPS_TOKEN', uuidv4Gen());
					}
				});
			} catch (error) {}
		})();
	}, []);

	return (
		<LinearGradient
			colors={[colors.red[300], colors.orange[300]]}
			start={{ x: 0, y: 0 }}
			end={{ x: 1, y: 0 }}
			style={styles.container}
		>
			<Icon name="Logo" width={170} height={170} />
			<View style={[styles.infoView, { bottom: insets.bottom + normalize(10) }]}>
				<LottieView
					style={{ width: 200, height: 150 }}
					source={require('@/assets/animations/loader.json')}
					autoPlay
					loop
				/>
				<PalRiderText style={styles.versionText}>{appVersionInfo}</PalRiderText>
				<PalRiderText style={styles.versionText}>{BASE_URL}</PalRiderText>
			</View>
		</LinearGradient>
	);
};

const styles = StyleSheet.create({
	container: {
		flex: 1,
		justifyContent: 'center',
		alignItems: 'center',
	},
	infoView: {
		position: 'absolute',
		alignItems: 'center',
	},
	versionText: {
		color: colors.white,
		fontSize: normalize(12),
		fontFamily: FontFamily.Regular,
	},
});

export default SplashScreen;
