import { createApi } from '@reduxjs/toolkit/query/react';
import { baseQueryConfigWithReAuth } from '../baseQueryConfig';
import { SuccessfulResponse, SuccessfulResponseT } from 'palriderapptypes';
import { CourierWalletDTO, CourierWalletWithdrawRequestDTO } from 'palriderapptypes/courier';
export const courierWalletApi = createApi({
	reducerPath: 'courierWallet',
	baseQuery: baseQueryConfigWithReAuth,
	keepUnusedDataFor: 0,
	endpoints: (builder) => ({
		courierWallet: builder.query<SuccessfulResponseT<CourierWalletDTO>, void>({
			query() {
				return {
					url: `courier-wallet`,
					method: 'GET',
				};
			},
		}),
		courierWalletWithdrawRequestList: builder.query<SuccessfulResponseT<Array<CourierWalletWithdrawRequestDTO>>, void>({
			query() {
				return {
					url: `courier-wallet/withdraw-request-list?page=1&size=100`,
					method: 'GET',
				};
			},
		}),

		courierWalletWithdrawRequest: builder.query<SuccessfulResponse, string>({
			query(courier_bank_account_id: string) {
				return {
					url: `courier-wallet/withdraw`,
					method: 'POST',
					body: {
						courier_bank_account_id,
					},
				};
			},
		}),
	}),
});

export const {
	useLazyCourierWalletQuery,
	useLazyCourierWalletWithdrawRequestListQuery,
	useLazyCourierWalletWithdrawRequestQuery,
} = courierWalletApi;
