import React, { useEffect, useRef, useState } from 'react';
import { ScrollView, StyleSheet, View, TouchableOpacity } from 'react-native';
import colors from '@/theme/colors';
import { font, normalize, PADDING } from '@/theme/responsive';
import { useModal } from '@/components/ModalProvider';
import PalRiderTextInput from '@/components/PalRiderTextInput';
import PalRiderButton from '@/components/PalRiderButton';
import PalRiderText from '@/components/PalRiderText';
import { FontFamily } from '@/theme/fonts';
import { useFormik } from 'formik';
import Dropdown from 'react-native-input-select';
import { globalStyles } from '@/utils/global-styles';
import { yupTyped } from '@/types';
import { string } from 'yup';
import { isFetchBaseQueryError, phoneNumberRegex } from '@/utils';
import WarningModal from '@/components/custom-modal/WarningModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import { CreateCompanyAreaAddresssUserRequestDTO } from 'palriderapptypes/company';

import { CompositeScreenProps } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import {
	AppCompanyProfileCompanyAreaParamList,
	AppCompanyProfileParamList,
	AppCompanyTabParamList,
} from '@/navigation/company-navigation';
import PalRiderPhoneInput from '@/components/PalRiderPhoneInput';
import { DropdownSelectHandle } from 'react-native-input-select/lib/typescript/src/types/index.types';
import {
	useLazyGetCompanyAreaAddressUserRolesQuery,
	useStoreCompanyAreaAddressUserMutation,
} from '@/services/api/company/company-area-address-user';
import { PalRiderInfoCard, PalRiderInfoRow } from '@/components/PalRiderInfoCard';
import Icon from '@/components/Icon';

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList, 'CompanyAreaAddressUserCreate'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyAreaStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
			CompositeScreenProps<
				NativeStackScreenProps<RootStackParamList>,
				NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList>
			>
		>
	>
>;

const AppCompanyProfileCompanyAreaAddressUserCreateScreen: React.FC<Props> = ({ route, navigation }) => {
	const { showGlobalModal } = useModal();
	if (!route?.params?.company_area_address_id) navigation.goBack();
	const [getCompanyAreaAddressUserRoles, { data: companyAreaUserRoles }] = useLazyGetCompanyAreaAddressUserRolesQuery();
	const [areaCode, setAreaCode] = useState('44');
	const areaCodeRef = useRef<DropdownSelectHandle | null>(null);

	const [storeCompanyAreaAddressUser, { isLoading }] = useStoreCompanyAreaAddressUserMutation();

	const [showRole, setShowRole] = useState(false);

	const createCompanyAreaUserFormik = useFormik<CreateCompanyAreaAddresssUserRequestDTO>({
		initialValues: {
			name: '',
			surname: '',
			email: '',
			phone_number: '',
			company_area_address_id: route.params.company_area_address_id,
			company_area_address_user_role_id: '',
		},
		validateOnChange: false,
		validateOnMount: false,
		isInitialValid: true,
		validationSchema: yupTyped<CreateCompanyAreaAddresssUserRequestDTO>({
			name: string().label('Name').min(2).required(),
			surname: string().label('Surname').min(2).required(),
			phone_number: string()
				.label('Phone Number')
				.required('Phone Number is required')
				.test('phone-regex', 'Phone number must be valid', function (value) {
					return phoneNumberRegex.test('+44' + value);
				}),
			company_area_address_id: string().label('Company Area Address').required().uuid(),
			company_area_address_user_role_id: string().label('User Role').required(),
		}),
		onSubmit: async (values) => {
			const res = await storeCompanyAreaAddressUser({
				...values,
				phone_number: '+' + areaCode + values.phone_number.replace(/\D/g, ''),
			});
			if (res.error && isFetchBaseQueryError(res.error)) {
				showGlobalModal({
					children: <WarningModal text={res.error.data.title} />,
				});
				return;
			}
			showGlobalModal({
				children: <SuccessModal text={res.data?.message} />,
				closeAfterDelay: 1000,
				whenClose() {
					navigation.goBack();
				},
			});
		},
	});

	useEffect(() => {
		getCompanyAreaAddressUserRoles({ page: 1, size: 100 });
	}, []);

	return (
		<View style={styles.container}>
			<ScrollView
				style={{ flex: 1 }}
				contentContainerStyle={{ padding: PADDING.large }}
				contentInsetAdjustmentBehavior="automatic"
			>
				<PalRiderInfoCard title="Create User">
					<View style={{ paddingHorizontal: PADDING.large, gap: PADDING.large }}>
						<PalRiderTextInput
							title="First Name"
							onChangeText={createCompanyAreaUserFormik.handleChange('name')}
							required
							error={createCompanyAreaUserFormik.errors.name}
							value={createCompanyAreaUserFormik.values.name}
						/>
						<PalRiderTextInput
							title="Last Name"
							onChangeText={createCompanyAreaUserFormik.handleChange('surname')}
							required
							error={createCompanyAreaUserFormik.errors.surname}
							value={createCompanyAreaUserFormik.values.surname}
						/>
						<PalRiderTextInput
							title="Email"
							onChangeText={createCompanyAreaUserFormik.handleChange('email')}
							error={createCompanyAreaUserFormik.errors.email}
							value={createCompanyAreaUserFormik.values.email}
						/>

						<Dropdown
							ref={areaCodeRef}
							dropdownContainerStyle={{ display: 'none' }}
							dropdownStyle={{ display: 'none', height: 0 }}
							options={[
								{ label: 'United Kingdom (+44)', value: '44' },
								{ label: 'Turkey (+90)', value: '90' },
							]}
							selectedValue={areaCode}
							onValueChange={(value) => setAreaCode(value !== '' ? (value as string) : '44')}
							autoCloseOnSelect
							isMultiple={false}
						/>

						<PalRiderPhoneInput
							areaCode={areaCode}
							onAreaCodePress={() => areaCodeRef.current?.open()}
							title="Phone Number"
							onChangeText={(text) => {
								createCompanyAreaUserFormik.setFieldValue('phone_number', text, true);
							}}
							error={createCompanyAreaUserFormik.errors.phone_number}
							value={createCompanyAreaUserFormik.values.phone_number}
							keyboardType="number-pad"
						/>
					</View>

					{!showRole ? (
						<PalRiderInfoRow
							label="Role"
							value={
								companyAreaUserRoles?.data.find(
									(r) => r.id === createCompanyAreaUserFormik.values.company_area_address_user_role_id,
								)?.name
							}
							editable
							onPress={() => setShowRole(true)}
						/>
					) : (
						<View style={styles.roleDropdownRow}>
							<Dropdown
								{...globalStyles.dropdownProps}
								options={
									companyAreaUserRoles?.data.map((role) => ({
										value: role.id,
										label: role.name,
									})) ?? []
								}
								isSearchable
								isMultiple={false}
								selectedValue={createCompanyAreaUserFormik.values.company_area_address_user_role_id}
								onValueChange={(value) => {
									createCompanyAreaUserFormik.setFieldValue('company_area_address_user_role_id', value, true);
									setShowRole(false);
								}}
								maxSelectableItems={1}
							/>
							<TouchableOpacity onPress={() => setShowRole(false)}>
								<Icon name="CheckCircleIconSvg" color={colors.green[600]} width={20} height={20} />
							</TouchableOpacity>
						</View>
					)}

					{createCompanyAreaUserFormik.errors.company_area_address_user_role_id && (
						<PalRiderText style={globalStyles.errorTextStyle}>
							{createCompanyAreaUserFormik.errors.company_area_address_user_role_id}
						</PalRiderText>
					)}
				</PalRiderInfoCard>
			</ScrollView>

			<View style={styles.footer}>
				<PalRiderButton variant="dark" loading={isLoading} onPress={() => createCompanyAreaUserFormik.handleSubmit()}>
					<PalRiderText fontFamily={FontFamily.Semibold} color={colors.white}>
						Add User
					</PalRiderText>
				</PalRiderButton>
			</View>
		</View>
	);
};

const styles = StyleSheet.create({
	container: {
		backgroundColor: colors.gray[50],
		flex: 1,
	},
	footer: {
		position: 'absolute',
		bottom: 0,
		left: 0,
		right: 0,
		padding: PADDING.large,
		backgroundColor: colors.white,
		borderTopWidth: StyleSheet.hairlineWidth,
		borderTopColor: colors.gray[200],
	},
	roleDropdownRow: {
		flexDirection: 'row',
		alignItems: 'center',
		justifyContent: 'space-between',
		paddingHorizontal: PADDING.large,
		paddingVertical: PADDING.medium,
	},
});

export default AppCompanyProfileCompanyAreaAddressUserCreateScreen;
