import LoadingModal from '@/components/custom-modal/LoadingModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import WarningModal from '@/components/custom-modal/WarningModal';
import { useModal } from '@/components/ModalProvider';
import PalRiderButton from '@/components/PalRiderButton';
import PalRiderSwipeButton from '@/components/PalRiderSwipeButton';
import PalRiderText from '@/components/PalRiderText';
import PalRiderTextInput from '@/components/PalRiderTextInput';
import {
	useCancelOrderShipmentDestinationMutation,
	useLazyGetOrderShipmentDestinationCancellationReasonsQuery,
} from '@/services/api/order/shipment';
import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { font, normalize, PADDING } from '@/theme/responsive';
import { BottomSheetModal, BottomSheetView } from '@gorhom/bottom-sheet';
import { StackActions, useNavigation } from '@react-navigation/native';
import React, { forwardRef, useCallback, useEffect, useImperativeHandle, useRef, useState } from 'react';
import { Image, Platform, Pressable, StyleSheet, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { isFetchBaseQueryError, requestLocationPermission } from '@/utils';
import { globalStyles } from '@/utils/global-styles';
import { OrderShipmentDTO } from 'palriderapptypes/order';
import PalRiderDropdown from '@/components/PalRiderDropdown';
import { launchCamera, launchImageLibrary } from 'react-native-image-picker';
import PalRiderBottomSelectModal from '@/components/PalRiderBottomSelectModal';
import { FileType } from '@/@types';
import Geolocation from '@react-native-community/geolocation';
import Icon from '@/components/Icon';

// Define props for your modal
type ActiveOrderShipmentDestinationCancellationModalProps = unknown;

// Define the ref methods that will be exposed
export type ActiveOrderShipmentDestinationCancellationModalRef = {
	openModal: (orderShipment: OrderShipmentDTO) => void;
	closeModal: () => void;
};

const ActiveOrderShipmentDestinationCancellationModal = forwardRef<
	ActiveOrderShipmentDestinationCancellationModalRef,
	ActiveOrderShipmentDestinationCancellationModalProps
>((_, ref) => {
	const navigation = useNavigation();
	const insets = useSafeAreaInsets();
	const [orderShipment, setOrderShipment] = useState<OrderShipmentDTO | null>(null);
	const { showGlobalModal, hideGlobalModal } = useModal();
	const [cancellationNote, setCancellationNote] = useState('');
	const [cancelOrderShipmentDestination] = useCancelOrderShipmentDestinationMutation();
	const [deliveryImageSelectModalVisible, setCancellationImageSelectModalVisible] = useState(false);
	const [cancellationImages, setCancellationImages] = useState<Array<FileType>>([]);

	const [selectedCancellationReasonId, setSelectedCancellationReasonId] = useState<string>('');
	const [getOrderShipmentDestinationCancellationReasons, { data: orderShipmentDestinationCancellationReasons }] =
		useLazyGetOrderShipmentDestinationCancellationReasonsQuery();

	// Create a ref for the BottomSheetModal
	const bottomSheetRef = useRef<BottomSheetModal>(null);
	const handleOrderShipmentDestinationDelivery = async () => {
		if (cancellationImages.length === 0) {
			showGlobalModal({
				children: <WarningModal text="At least one cancellation image required" />,
			});
			return;
		}
		if (orderShipment) {
			hideGlobalModal();
			showGlobalModal({
				maxHeight: 200,
				backgroundColor: colors.transparent,
				children: <LoadingModal />,
			});
			try {
				if (!selectedCancellationReasonId) {
					showGlobalModal({
						children: <WarningModal text="Order shipment cancellation must be selected" />,
					});
					return;
				}
				if (cancellationImages.length <= 0) {
					showGlobalModal({
						children: <WarningModal text="Order shipment cancellation images must be uploaded" />,
					});
					return;
				}
				const requestAccess = await requestLocationPermission();
				if (!requestAccess) {
					showGlobalModal({
						children: (
							<WarningModal
								icon={<Icon name="LocationNotGrantedIconSvg" width={128} height={128} color={colors.red[600]} />}
								text="If you want to cancel this order shipment must grant location for application."
							/>
						),
					});
					return;
				}
				Geolocation.getCurrentPosition(
					async (position) => {
						const result = await cancelOrderShipmentDestination({
							notes: cancellationNote,
							order_shipment_destination_id: orderShipment.current_order_shipment_destination_id!,
							order_shipment_id: orderShipment.id,
							order_id: orderShipment.order_id,
							order_shipment_destination_cancellation_reason_id: selectedCancellationReasonId,
							latitude: position.coords.latitude,
							longitude: position.coords.longitude,
							order_shipment_destination_cancellation_photos: cancellationImages,
						});

						if (!result.error) {
							hideGlobalModal();
							showGlobalModal({
								maxHeight: 200,
								children: <SuccessModal text="Shipment cancelled" />,
								closeAfterDelay: 1000,
								async whenClose() {
									navigation.dispatch(StackActions.replace('Splash'));
								},
							});
						} else {
							if (isFetchBaseQueryError(result.error)) {
								showGlobalModal({
									maxHeight: 200,
									children: <WarningModal text={result.error.data.title ?? ''} />,
								});
							}
						}
					},
					(geoError) => {
						showGlobalModal({
							children: <WarningModal text={geoError.message} />,
						});
					},
					{
						enableHighAccuracy: true,
						maximumAge: 10000,
						timeout: 15000,
					},
				);
			} catch (err) {
				hideGlobalModal();
				showGlobalModal({
					maxHeight: 200,
					children: <WarningModal text="Shipment cannot cancelled" />,
				});
			}
		}
	};
	const handleRemoveCancellationImage = (index: number) => {
		const cloned = [...cancellationImages];
		setCancellationImages(cloned.filter((__, indexFilter) => index !== indexFilter));
	};
	const renderCancellationImages = useCallback(() => {
		if (cancellationImages.length > 0) {
			return cancellationImages.map((image, index) => (
				<View style={{ width: 100, height: 100, position: 'relative' }}>
					<Pressable
						style={{
							width: 25,
							height: 25,
							backgroundColor: colors.black,
							position: 'absolute',
							top: 5,
							right: 5,
							zIndex: 999,
							borderRadius: PADDING.large,
							justifyContent: 'center',
							alignItems: 'center',
						}}
						onPress={() => handleRemoveCancellationImage(index)}
					>
						<Icon name="CloseIconSvg" color={colors.white} width={20} height={20} />
					</Pressable>
					<Image source={{ uri: image.uri }} width={100} height={100} />
				</View>
			));
		}
	}, [cancellationImages]);

	// Expose the modal methods using `useImperativeHandle`
	useImperativeHandle(ref, () => ({
		openModal: (orderShipmentVal: OrderShipmentDTO) => {
			bottomSheetRef.current?.present();
			setOrderShipment(orderShipmentVal);
		},
		closeModal: () => {
			bottomSheetRef.current?.dismiss();
			setOrderShipment(null);
		},
	}));
	useEffect(() => {
		getOrderShipmentDestinationCancellationReasons({
			page: 1,
			size: 100,
		}).unwrap();
	}, []);

	return (
		<View>
			<PalRiderBottomSelectModal
				key={'cancellation_picture'}
				data={[
					{
						text: 'Pick From Library',
						async onPress() {
							showGlobalModal({
								children: <LoadingModal />,
								backgroundColor: colors.transparent,
							});
							const res = await launchImageLibrary({
								mediaType: 'photo',
								includeExtra: true,
								selectionLimit: 1,
							});
							hideGlobalModal();
							if (res.didCancel || res.errorCode || !res.assets || !res.assets[0]) {
								return;
							}
							const file = res.assets[0];
							setCancellationImages((prev) => [
								...prev,
								{
									name: file.fileName,
									size: file.fileSize,
									type: file.type,
									uri: file.uri,
								} as FileType,
							]);
							setCancellationImageSelectModalVisible(false);
						},
					},
					{
						text: 'Take A Photo',
						async onPress() {
							try {
								const res = await launchCamera({
									mediaType: 'photo',
									includeExtra: true,
									presentationStyle: 'overCurrentContext',
									quality: 1,
									saveToPhotos: true,
								});
								if (res.didCancel || res.errorCode || !res.assets || !res.assets[0]) {
									return;
								}
								const file = res.assets[0];
								setCancellationImages((prev) => [
									...prev,
									{
										name: file.fileName,
										size: file.fileSize,
										type: file.type,
										uri: file.uri,
									} as FileType,
								]);
								setCancellationImageSelectModalVisible(false);
							} catch (e) {
								console.error(e);
							}
						},
					},
				]}
				isVisible={deliveryImageSelectModalVisible}
				title="Select"
				cancelOnPress={() => setCancellationImageSelectModalVisible(false)}
				isCoverScreen
			/>
			<BottomSheetModal
				ref={bottomSheetRef}
				enableDynamicSizing
				enableOverDrag={false}
				keyboardBlurBehavior="restore"
				enableContentPanningGesture={false}
			>
				<BottomSheetView
					style={{ padding: PADDING.large, paddingBottom: Platform.OS === 'ios' ? insets.bottom : insets.bottom + 20 }}
				>
					<View style={{ gap: PADDING.large }}>
						<View style={{ flexDirection: 'row', columnGap: normalize(2) }}>
							<PalRiderText style={styles.titleText}>Choose Cancelleation Reason</PalRiderText>
							<PalRiderText color={colors.red[600]} fontFamily={FontFamily.Semibold}>
								*
							</PalRiderText>
						</View>

						<PalRiderDropdown
							{...globalStyles.dropdownProps}
							options={
								orderShipmentDestinationCancellationReasons?.data.map((item) => ({
									value: item.id,
									label: item.name,
								})) ?? []
							}
							selectedValue={selectedCancellationReasonId}
							onValueChange={(value) => setSelectedCancellationReasonId(value)}
						/>
						<PalRiderText fontSize={font.mini} fontFamily={FontFamily.Semibold}>
							Cancellation Images (Min 1 image required)
						</PalRiderText>
						<View style={styles.addImageContainer}>{renderCancellationImages()}</View>
						<View style={styles.addImageContainer}>
							<Pressable style={styles.addImageButton} onPress={() => setCancellationImageSelectModalVisible(true)}>
								<Icon name="PlusIconSvg" color={colors.gray[600]} />
							</Pressable>
						</View>

						<PalRiderTextInput
							title="Notes"
							numberOfLines={5}
							inputStyle={{ minHeight: 80 }}
							multiline
							maxLength={255}
							onChangeText={(text) => setCancellationNote(text)}
						/>
						<PalRiderSwipeButton
							swipeText="Cancel"
							firstColor={colors.red[500]}
							secondColor={colors.red[600]}
							swipeColor={colors.red[600]}
							swipedText="Shipment cancelling...."
							button={
								<PalRiderButton variant="error">
									<Icon name="ChevronRightIconSvg" color={colors.white} width={20} height={20} />
								</PalRiderButton>
							}
							onSwipe={() => handleOrderShipmentDestinationDelivery()}
						/>
					</View>
				</BottomSheetView>
			</BottomSheetModal>
		</View>
	);
});

const styles = StyleSheet.create({
	addImageContainer: {
		flexDirection: 'row',
		columnGap: PADDING.medium,
	},
	addImageButton: {
		width: PADDING.xxlarge * 3,
		height: PADDING.xxlarge * 3,
		borderWidth: 1,
		borderColor: colors.gray[300],
		borderRadius: PADDING.large,
		justifyContent: 'center',
		alignItems: 'center',
	},

	titleText: {
		fontFamily: FontFamily.Semibold,
		fontSize: normalize(12),
		marginBottom: normalize(6),
		paddingLeft: normalize(4),
	},

	radioButton: {
		width: 20,
		height: 20,
		borderRadius: 20 / 2,
		borderWidth: 3,
		borderColor: 'white',
	},
});
export default ActiveOrderShipmentDestinationCancellationModal;
