import React, { memo, useEffect, useMemo, useRef } from 'react';
import { Pressable, ScrollView, StyleSheet, View } from 'react-native';
import { useLazyAbondonActiveOrderQuery, useLazyGetCourierActiveOrderQuery } from '@/services/api/order';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { CompositeScreenProps, StackActions, useFocusEffect } from '@react-navigation/native';
import PalRiderText from '@/components/PalRiderText';
import { RefreshControl } from 'react-native-gesture-handler';
import PalRiderButton from '@/components/PalRiderButton';
import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { font, PADDING } from '@/theme/responsive';
import { useAppDispatch } from '@/redux/hooks';
import { setToken } from '@/redux/slices/userSlice';
import useUserNavigation from '@/hooks/useUserNavigation';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { isFetchBaseQueryError, priceFormat } from '@/utils';
import WarningModal from '@/components/custom-modal/WarningModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import ConfirmationModal from '@/components/custom-modal/ConfirmationModal';
import { AppActiveOrderTabParamList } from '@/navigation/order-navigation';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { RootStackParamList } from '@/navigation';
import { MenuView } from '@react-native-menu/menu';
import Icon from '@/components/Icon';
import { CourierActiveOrderDTO } from 'palriderapptypes/order';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppActiveOrderTabParamList, 'Home'>,
	NativeStackScreenProps<RootStackParamList>
>;

const AppActiveOrderHomeScreen: React.FC<Props> = ({ route, navigation }) => {
	const reloadInterval = useRef<NodeJS.Timeout>(null);
	const dispatch = useAppDispatch();
	const [getActiveOrder, { isLoading, data }] = useLazyGetCourierActiveOrderQuery();
	const [abondonActiveOrder] = useLazyAbondonActiveOrderQuery();
	const { showGlobalModal, hideGlobalModal } = useModal();

	const loadDashboard = async () => {
		const order_id = await AsyncStorage.getItem('current_active_order_id');
		if (!order_id) return;
		const res = await getActiveOrder(order_id);

		if (res.error && isFetchBaseQueryError(res.error)) {
			if (res.error.status === 403) {
				showGlobalModal({
					children: <SuccessModal text="Order is finished" />,
					whenClose() {
						navigation.dispatch(
							StackActions.replace('AppCourierStack', {
								screen: 'CourierHome',
							}),
						);
					},
				});
			}
		}
	};

	const { handle: hanldeLogoutNavigation } = useUserNavigation();

	const handleLogout = async () => {
		dispatch(setToken(null));
		await AsyncStorage.removeItem('token');
		await hanldeLogoutNavigation();
	};

	const handleAbondon = async () => {
		if (!data?.data || !data?.data.id) return;
		showGlobalModal({
			preventHiding: true,
			padding: 0,
			children: (
				<ConfirmationModal
					icon={<Icon name="InfoIconSvg" width={32} height={32} />}
					text="When an order abondened you get penalty. Are you sure ?"
					onConfirm={async () => {
						showGlobalModal({
							preventHiding: true,
							children: <LoadingModal />,
							backgroundColor: colors.transparent,
						});
						const res = await abondonActiveOrder(data?.data.id);
						if (res.error && isFetchBaseQueryError(res.error)) {
							showGlobalModal({
								children: <WarningModal text={res.error.data.title} />,
							});
							return;
						}
						showGlobalModal({
							children: <SuccessModal text="Order successfuly finished" />,
							whenClose() {
								navigation.dispatch(
									StackActions.replace('AppStack', {
										screen: 'AppCourierStack',
										params: { screen: 'Home' },
									}),
								);
							},
						});
					}}
					onCancel={() => hideGlobalModal()}
				/>
			),
		});
	};

	useEffect(() => {
		loadDashboard();
		navigation.setOptions({
			headerStyle: {
				backgroundColor: colors.orange[600],
			},
			headerTintColor: colors.white,
			headerRight: () => (
				<View style={{ paddingRight: PADDING.large }}>
					<MenuView
						actions={[
							{
								id: 'abondon_order',
								title: 'Abondon Order',
								attributes: { destructive: true, hidden: !data?.data.could_work },
							},
							{ id: 'logout', title: 'Logout' },
						]}
						onPressAction={({ nativeEvent }) => {
							if (nativeEvent.event === 'abondon_order') {
								handleAbondon();
								return;
							}
							if (nativeEvent.event === 'logout') {
								handleLogout();
								return;
							}
						}}
						shouldOpenOnLongPress={false}
					>
						<Pressable style={styles.menuButton}>
							<Icon name="ThreeHorizontalDotIconSvg" color={colors.white} />
						</Pressable>
					</MenuView>
				</View>
			),
		});
	}, [route.params, data?.data?.could_work]);
	const matchedBonusId = useMemo(() => {
		if (!data?.data) return null;

		const order = data.data as CourierActiveOrderDTO;
		const bonuses = [...(order.order_bonuses ?? [])].sort((a, b) => a.sort - b.sort);

		if (order.order_bonus_type === 'by_distance') {
			const m = bonuses.find((b) => order.driven_km >= b.min_value && order.driven_km <= b.max_value);
			return m?.id ?? null;
		}

		if (order.order_bonus_type === 'per_shipment') {
			const shipmentCount = order.order_shipments?.length ?? 0;
			const m = bonuses.find((b) => shipmentCount >= b.min_value && shipmentCount <= b.max_value);
			return m?.id ?? null;
		}

		return null;
	}, [data?.data]);

	useFocusEffect(
		React.useCallback(() => {
			reloadInterval.current = setInterval(loadDashboard, 60000);

			return () => {
				if (reloadInterval.current) {
					clearInterval(reloadInterval.current);
					reloadInterval.current = null;
				}
			};
		}, []),
	);

	return (
		<View style={styles.container}>
			{/* Header Card */}
			{data?.data && (
				<View style={styles.headerCard}>
					<View style={styles.headerContent}>
						<View style={styles.orderInfo}>
							<PalRiderText color={colors.white} fontSize={font.small} fontFamily={FontFamily.Semibold}>
								Active Order
							</PalRiderText>
							<PalRiderText color={colors.white} fontSize={font.large} fontFamily={FontFamily.Bold}>
								#{data.data.order_no}
							</PalRiderText>
						</View>
						<View style={styles.earningsCard}>
							<PalRiderText color={colors.orange[600]} fontSize={font.mini} fontFamily={FontFamily.Semibold}>
								TOTAL EARNINGS
							</PalRiderText>
							<PalRiderText color={colors.orange[700]} fontSize={font.xlarge} fontFamily={FontFamily.Bold}>
								{priceFormat(data.data.total_earning)}
							</PalRiderText>
						</View>
					</View>
				</View>
			)}

			<ScrollView
				style={styles.scrollView}
				contentContainerStyle={styles.scrollContent}
				refreshControl={
					<RefreshControl
						tintColor={colors.orange[600]}
						colors={[colors.orange[600]]}
						refreshing={isLoading}
						onRefresh={() => loadDashboard()}
					/>
				}
				showsVerticalScrollIndicator={false}
			>
				{data?.data && (
					<>
						{/* Stats Grid */}
						<View style={styles.statsGrid}>
							<View style={[styles.statCard, styles.statCardPrimary]}>
								<View style={styles.statIcon}>
									<PalRiderText fontSize={font.xxlarge}>🚗</PalRiderText>
								</View>
								<PalRiderText fontSize={font.large} fontFamily={FontFamily.Bold} color={colors.orange[600]}>
									{data.data.driven_km}
								</PalRiderText>
								<PalRiderText fontSize={font.small} color={colors.gray[600]} fontFamily={FontFamily.Semibold}>
									Miles Driven
								</PalRiderText>
							</View>

							<View style={[styles.statCard, styles.statCardSecondary]}>
								<View style={styles.statIcon}>
									<PalRiderText fontSize={font.xxlarge}>📦</PalRiderText>
								</View>
								<PalRiderText fontSize={font.large} fontFamily={FontFamily.Bold} color={colors.blue[600]}>
									{data.data.location_visited}
								</PalRiderText>
								<PalRiderText fontSize={font.small} color={colors.gray[600]} fontFamily={FontFamily.Semibold}>
									Deliveries
								</PalRiderText>
							</View>
						</View>

						{/* Work Time Card */}
						<View style={styles.timeCard}>
							<View style={styles.timeHeader}>
								<View style={styles.timeIcon}>
									<PalRiderText fontSize={font.large}>⏰</PalRiderText>
								</View>
								<View>
									<PalRiderText fontSize={font.medium} fontFamily={FontFamily.Bold} color={colors.gray[800]}>
										Active Shift Time
									</PalRiderText>
									<PalRiderText fontSize={font.small} color={colors.gray[600]}>
										Current session duration
									</PalRiderText>
								</View>
							</View>
							<View style={styles.timeDisplay}>
								<PalRiderText fontSize={font.xlarge} fontFamily={FontFamily.Bold} color={colors.green[600]}>
									{data.data.current_working_hours}
								</PalRiderText>
							</View>
						</View>

						{data.data.order_bonus_type !== 'none' && (
							<View style={styles.bonusSection}>
								<View style={styles.bonusHeader}>
									<View style={styles.bonusIcon}>
										<PalRiderText fontSize={font.large}>🎁</PalRiderText>
									</View>
									<PalRiderText fontSize={font.medium} fontFamily={FontFamily.Bold} color={colors.gray[800]}>
										Order Bonuses
									</PalRiderText>
								</View>

								<View style={styles.bonusGrid}>
									{[...data.data.order_bonuses]
										.sort((a, b) => a.sort - b.sort)
										.map((bonus, index, arr) => (
											<View key={bonus.id} style={styles.bonusItem}>
												<View style={styles.bonusRange}>
													<PalRiderText fontSize={font.small} color={colors.gray[700]} fontFamily={FontFamily.Semibold}>
														{bonus.min_value} - {bonus.max_value}
														{index === arr.length - 1 ? '+' : ''}
													</PalRiderText>
													<PalRiderText fontSize={font.mini} color={colors.gray[500]}>
														{data.data.order_bonus_type === 'by_distance' ? 'Miles' : 'Shipments'}
													</PalRiderText>
												</View>

												<View style={styles.bonusPrice}>
													<PalRiderText fontSize={font.medium} fontFamily={FontFamily.Bold} color={colors.green[600]}>
														{priceFormat(bonus.price)}
													</PalRiderText>

													{matchedBonusId === bonus.id ? <Icon name="CheckIconSvg" color={colors.green[600]} /> : null}
												</View>
											</View>
										))}
								</View>
							</View>
						)}

						{/* Action Buttons */}
						<View style={styles.actionSection}>
							{data.data.could_work && (
								<PalRiderButton variant="error" onPress={handleAbondon} style={styles.actionButton}>
									<PalRiderText color={colors.white} fontFamily={FontFamily.Bold} fontSize={font.medium}>
										Abandon Order
									</PalRiderText>
								</PalRiderButton>
							)}
							<PalRiderButton variant="warning" onPress={handleLogout} style={styles.actionButton}>
								<PalRiderText color={colors.white} fontFamily={FontFamily.Bold} fontSize={font.medium}>
									Logout
								</PalRiderText>
							</PalRiderButton>
						</View>
					</>
				)}
			</ScrollView>
		</View>
	);
};

