import React, { useEffect } from 'react';
import CourierHomeActiveVehicle from './components/CourierHomeActiveVehicle';
import CourierHomeAverageRating from './components/CourierHomeAverageRating';
import CourierHomeTotalEarnings from './components/CourierHomeTotalEarnings';
import CourierHomeTotalInfo from './components/CourierHomeTotalInfo';
import CourierHomeWalletEarnings from './components/CourierHomeWalletEarnings';
import { useLazyStatisticsQuery } from '@/services/api/courier';
import { CompositeScreenProps } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { RootStackParamList } from '@/navigation';
import { AppCourierTabParamList } from '@/navigation/courier-navigation';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RefreshControl, ScrollView, StyleSheet, View } from 'react-native';
import colors from '@/theme/colors';

type Props = CompositeScreenProps<
	BottomTabScreenProps<AppCourierTabParamList, 'CourierHome'>,
	NativeStackScreenProps<RootStackParamList>
>;

const AppCourierHomeScreen: React.FC<Props> = () => {
	const [getCourierStatistics, { data: statisticsData, isFetching }] = useLazyStatisticsQuery();

	const loadData = async () => {
		await getCourierStatistics();
	};

	useEffect(() => {
		loadData();
	}, []);

	return (
		<ScrollView
			style={styles.page}
			refreshControl={<RefreshControl refreshing={isFetching} onRefresh={() => loadData()} />}
		>
			<View style={styles.section}>
				<CourierHomeActiveVehicle />
			</View>

			<View style={styles.section}>
				<CourierHomeTotalEarnings value={statisticsData?.data.total_earnings} />
			</View>

			<View style={styles.section}>
				<CourierHomeWalletEarnings value={statisticsData?.data.total_wallet} />
			</View>

			<View style={styles.section}>
				<CourierHomeTotalInfo value={[statisticsData?.data.total_km, statisticsData?.data.total_shipment_count]} />
			</View>

			<View style={styles.section}>
				<CourierHomeAverageRating />
			</View>
		</ScrollView>
	);
};

const styles = StyleSheet.create({
	page: {
		flex: 1,
		backgroundColor: colors.gray[100],
	},
	section: {
		marginVertical: 8,
		marginHorizontal: 12,
	},
});

export default AppCourierHomeScreen;
