import { createApi } from '@reduxjs/toolkit/query/react';
import { baseQueryConfigWithReAuth } from './baseQueryConfig';
import { SuccessfulResponse, SuccessfulResponseT } from 'palriderapptypes';
import {
	BaseUserDTO,
	UpdateNotificationInfoRequestDTO,
	UpdateUserAppInformationRequestDTO,
} from 'palriderapptypes/common';
export const userApi = createApi({
	reducerPath: 'user',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		getUser: builder.query<SuccessfulResponseT<BaseUserDTO>, void>({
			query() {
				return {
					url: 'user/me',
				};
			},
		}),
		authenticateUser: builder.mutation<SuccessfulResponse, { phone_number: string }>({
			query(body) {
				return {
					method: 'POST',
					url: 'user/auth/authenticate',
					body,
				};
			},
		}),
		updateNotificationInfo: builder.mutation<SuccessfulResponse, UpdateNotificationInfoRequestDTO>({
			query(body) {
				return {
					method: 'POST',
					url: 'user/update-notification-info',
					body,
				};
			},
		}),
		updateUserAppInformation: builder.mutation<SuccessfulResponse, Partial<UpdateUserAppInformationRequestDTO>>({
			query(body) {
				return {
					method: 'POST',
					url: 'user/updateUserAppInformation',
					body,
				};
			},
		}),
		verifyUser: builder.mutation<SuccessfulResponseT<string>, { phone_number: string; code: string }>({
			query(body) {
				return {
					method: 'POST',
					url: 'user/auth/verify',
					body,
				};
			},
		}),
	}),
});

export const {
	useLazyGetUserQuery,
	useAuthenticateUserMutation,
	useVerifyUserMutation,
	useUpdateNotificationInfoMutation,
	useUpdateUserAppInformationMutation,
} = userApi;
