import { createApi } from '@reduxjs/toolkit/query/react';
import { SuccessfulResponse, SuccessfulResponseT } from 'palriderapptypes';
import { AuthenticateCourierRequestDTO, VerifyCourierRequestDTO } from 'palriderapptypes/courier';
import { baseQueryConfigWithReAuth } from 'src/services/api/baseQueryConfig.ts';
export const authCourierApi = createApi({
	reducerPath: 'authCourier',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		authenticateCourier: builder.mutation<SuccessfulResponse, AuthenticateCourierRequestDTO>({
			query(body) {
				return {
					method: 'POST',
					url: 'courier/auth/authenticate',
					body,
				};
			},
		}),
		authenticateVerifyCourier: builder.mutation<SuccessfulResponseT<string>, VerifyCourierRequestDTO>({
			query(body) {
				return {
					method: 'POST',
					url: 'courier/auth/verify',
					body,
				};
			},
		}),
	}),
});

export const { useAuthenticateCourierMutation, useAuthenticateVerifyCourierMutation } = authCourierApi;
