import { SuccessfulResponse, SuccessfulResponseT } from 'palriderapptypes';
import { createApi } from '@reduxjs/toolkit/query/react';
import { baseQueryConfigWithReAuth } from 'src/services/api/baseQueryConfig.ts';
import { CompanyAreaUserAuthenticateRequestDTO, CompanyAreaUserVerifyRequestDTO } from 'palriderapptypes/company';
export const authCompanyAreaAddressUserApi = createApi({
	reducerPath: 'authCompanyAreaAddressUser',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		authenticateCompanyAreaAddressUser: builder.mutation<SuccessfulResponse, CompanyAreaUserAuthenticateRequestDTO>({
			query(body) {
				return {
					method: 'POST',
					url: 'company-area-address-user/auth/authenticate',
					body,
				};
			},
		}),
		authenticateVerifyCompanyAreaAddressUser: builder.mutation<
			SuccessfulResponseT<string>,
			CompanyAreaUserVerifyRequestDTO
		>({
			query(body) {
				return {
					method: 'POST',
					url: 'company-area-address-user/auth/verify',
					body,
				};
			},
		}),
	}),
});

export const { useAuthenticateCompanyAreaAddressUserMutation, useAuthenticateVerifyCompanyAreaAddressUserMutation } =
	authCompanyAreaAddressUserApi;
