import React, { useEffect, useState } from 'react';
import {
	Linking,
	Platform,
	Pressable,
	RefreshControl,
	ScrollView,
	StyleSheet,
	View,
	TouchableOpacity,
} from 'react-native';
import colors from '@/theme/colors';
import PalRiderText from '@/components/PalRiderText';
import { FontFamily } from '@/theme/fonts';
import { font, PADDING } from '@/theme/responsive';
import { EditIconSvg } from '@/assets/svg/ui';
import {
	useLazyGetCompanyAreaAddressQuery,
	useUpdateCompanyAreaAddressMutation,
} from '@/services/api/company/company-area-address';
import { useModal } from '@/components/ModalProvider';
import PalRiderTextInput from '@/components/PalRiderTextInput';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { isFetchBaseQueryError } from '@/utils';
import WarningModal from '@/components/custom-modal/WarningModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import { CompositeScreenProps } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import {
	AppCompanyProfileCompanyAreaParamList,
	AppCompanyProfileParamList,
	AppCompanyTabParamList,
} from '@/navigation/company-navigation';
import Icon from '@/components/Icon';

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList, 'CompanyAreaAddressView'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyAreaStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
			CompositeScreenProps<
				NativeStackScreenProps<RootStackParamList>,
				NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList>
			>
		>
	>
>;

const AppCompanyProfileCompanyAreaAddressViewScreen: React.FC<Props> = ({ route, navigation }) => {
	const { showGlobalModal } = useModal();
	if (!route?.params?.company_area_address_id) navigation.goBack();
	const [getCompanyAreaAddress, { data, isLoading }] = useLazyGetCompanyAreaAddressQuery();
	const [updateCompanyAreaAddress] = useUpdateCompanyAreaAddressMutation();

	const [updateValues, setUpdateValues] = useState({
		showBuilding: false,
		showDirections: false,
		building: '',
		directions: '',
	});

	const handleUpdate = async () => {
		if (!data?.data) return;
		showGlobalModal({
			children: <LoadingModal />,
			backgroundColor: colors.transparent,
		});
		const res = await updateCompanyAreaAddress({ ...updateValues, company_area_address_id: data.data.id });
		if (res.error && isFetchBaseQueryError(res.error)) {
			showGlobalModal({
				children: <WarningModal text={res.error.data.title} />,
			});
			return;
		}
		showGlobalModal({
			children: <SuccessModal text="Company area address updated" />,
			closeAfterDelay: 1000,
			whenClose() {
				loadCompanyAreaAddress();
				setUpdateValues((prev) => ({
					...prev,
					showBuilding: false,
					showDirections: false,
				}));
			},
		});
	};

	const loadCompanyAreaAddress = async () => {
		const res = await getCompanyAreaAddress(route.params.company_area_address_id);
		if (res.error && isFetchBaseQueryError(res.error)) {
			showGlobalModal({
				children: <WarningModal text={res.error.data.title} />,
			});
			return;
		}
		if (res.data && res.data.data) {
			setUpdateValues((prev) => ({
				...prev,
				building: res.data!.data.building_name_or_number ?? '',
				directions: res.data!.data.directions ?? '',
			}));
		}
	};

	useEffect(() => {
		loadCompanyAreaAddress();
	}, []);

	const renderRow = (label: string, value?: string | null | undefined, onPress?: () => void, editable = false) => (
		<Pressable
			style={({ pressed }) => [styles.row, pressed && { backgroundColor: colors.gray[100] }]}
			onPress={onPress}
		>
			<PalRiderText style={styles.label}>{label}</PalRiderText>
			<View style={styles.valueContainer}>
				<PalRiderText style={[styles.valueText, !value && { color: colors.gray[400], fontStyle: 'italic' }]}>
					{value || 'Not available'}
				</PalRiderText>
				{editable && <EditIconSvg width={20} height={20} />}
			</View>
		</Pressable>
	);

	return (
		<View style={styles.container}>
			<ScrollView
				contentContainerStyle={{ gap: PADDING.large, padding: PADDING.large }}
				refreshControl={<RefreshControl onRefresh={loadCompanyAreaAddress} refreshing={isLoading} />}
			>
				<View style={styles.card}>
					<PalRiderText style={styles.sectionTitle}>Address Information</PalRiderText>

					{/* Address */}
					{renderRow('Address', data?.data.address)}

					{/* Building */}
					{!updateValues.showBuilding ? (
						renderRow(
							'Building',
							data?.data.building_name_or_number,
							() => setUpdateValues((prev) => ({ ...prev, showBuilding: true })),
							true,
						)
					) : (
						<View style={styles.updateRow}>
							<PalRiderTextInput
								containerStyle={{ flex: 1 }}
								title="Building"
								defaultValue={data?.data.building_name_or_number || undefined}
								onEndEditing={(event) => {
									if (event.nativeEvent.text) {
										setUpdateValues((prev) => ({ ...prev, building: event.nativeEvent.text }));
										handleUpdate();
									}
								}}
								onChangeText={(text) => setUpdateValues((prev) => ({ ...prev, building: text }))}
								rightComponent={
									<TouchableOpacity style={styles.updateBtn} onPress={handleUpdate}>
										<Icon name="CheckCircleIconSvg" color={colors.green[600]} width={18} height={18} />
									</TouchableOpacity>
								}
							/>
						</View>
					)}

					{/* Directions */}
					{!updateValues.showDirections ? (
						renderRow(
							'Directions',
							data?.data.directions,
							() => setUpdateValues((prev) => ({ ...prev, showDirections: true })),
							true,
						)
					) : (
						<View style={styles.updateRow}>
							<PalRiderTextInput
								containerStyle={{ flex: 1 }}
								title="Directions"
								defaultValue={data?.data.directions || undefined}
								onEndEditing={(event) => {
									if (event.nativeEvent.text) {
										setUpdateValues((prev) => ({ ...prev, directions: event.nativeEvent.text }));
										handleUpdate();
									}
								}}
								onChangeText={(text) => setUpdateValues((prev) => ({ ...prev, directions: text }))}
								rightComponent={
									<TouchableOpacity style={styles.updateBtn} onPress={handleUpdate}>
										<Icon name="CheckCircleIconSvg" color={colors.green[600]} width={18} height={18} />
									</TouchableOpacity>
								}
							/>
						</View>
					)}

					{/* Post Code */}
					{renderRow('Post Code', data?.data.post_code)}

					{/* Maps */}
					<Pressable
						style={({ pressed }) => [styles.row, pressed && { backgroundColor: colors.gray[100] }]}
						onPress={() => {
							const url = Platform.select({
								ios: `maps:${data?.data.latitude},${data?.data.longitude}?q=${data?.data.address}`,
								android: `geo:${data?.data.latitude},${data?.data.longitude}?q=${data?.data.address}`,
							});
							if (url) Linking.openURL(url);
						}}
					>
						<PalRiderText style={styles.label}>Maps</PalRiderText>
						<PalRiderText style={[styles.valueText, { color: colors.blue[600], fontFamily: FontFamily.Bold }]}>
							Open in Maps
						</PalRiderText>
					</Pressable>
				</View>
			</ScrollView>
		</View>
	);
};

const styles = StyleSheet.create({
	container: {
		backgroundColor: colors.gray[50],
		flex: 1,
	},
	card: {
		backgroundColor: colors.white,
		borderRadius: 24,
		paddingVertical: PADDING.large,
		shadowColor: '#000',
		shadowOffset: { width: 0, height: 6 },
		shadowOpacity: 0.1,
		shadowRadius: 12,
		elevation: 6,
	},
	sectionTitle: {
		fontFamily: FontFamily.Bold,
		fontSize: font.medium,
		color: colors.gray[800],
		paddingHorizontal: PADDING.large,
		paddingBottom: PADDING.medium,
	},
	row: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
		paddingHorizontal: PADDING.large,
		paddingVertical: PADDING.large,
		borderTopWidth: StyleSheet.hairlineWidth,
		borderColor: colors.gray[200],
	},
	label: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.small,
		color: colors.gray[700],
	},
	valueContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: PADDING.small,
		maxWidth: '70%',
	},
	valueText: {
		fontFamily: FontFamily.Regular,
		fontSize: font.small,
		color: colors.gray[600],
	},
	updateRow: {
		flexDirection: 'row',
		alignItems: 'center',
		paddingHorizontal: PADDING.large,
		paddingVertical: PADDING.medium,
	},
	updateBtn: {
		marginLeft: PADDING.small,
		borderWidth: 1,
		borderColor: colors.green[600],
		padding: PADDING.small,
		borderRadius: PADDING.large,
		alignItems: 'center',
		justifyContent: 'center',
	},
});

export default AppCompanyProfileCompanyAreaAddressViewScreen;
