import { createApi } from '@reduxjs/toolkit/query/react';
import { baseQueryConfigWithReAuth } from 'src/services/api/baseQueryConfig.ts';
import { CompanyAreaAddressDTO, CompanyAreaDTO, CreateCompanyAreaRequestDTO } from 'palriderapptypes/company';
import { PaginationDataResultT, SuccessfulResponse, SuccessfulResponseT } from 'palriderapptypes';
import { PaginationRequestDTO } from 'palriderapptypes/common';

export const companyAreaApi = createApi({
	reducerPath: 'companyArea',
	baseQuery: baseQueryConfigWithReAuth,
	refetchOnMountOrArgChange: 30,
	endpoints: (builder) => ({
		getAllCompanyArea: builder.query<PaginationDataResultT<CompanyAreaDTO>, PaginationRequestDTO>({
			query({ page = 1, size = 50 }) {
				return {
					method: 'GET',
					url: 'company-area?page=' + page + '&size=' + size,
				};
			},
		}),
		getCompanyAreaAddresses: builder.query<
			PaginationDataResultT<CompanyAreaAddressDTO>,
			PaginationRequestDTO & { company_area_id: string }
		>({
			query(body) {
				return {
					url: `company-area/${body.company_area_id}/addresses`,
					params: {
						page: body.page,
						size: body.size,
					},
					method: 'GET',
				};
			},
		}),
		getCompanyArea: builder.query<SuccessfulResponseT<CompanyAreaDTO>, string>({
			query(company_area_id) {
				return {
					url: `company-area/${company_area_id}`,
					method: 'GET',
				};
			},
		}),
		getNearestCounty: builder.query<SuccessfulResponseT<{ name: string }>, string>({
			query(postCode) {
				return {
					url: `common/get-nearest-county?PostCode=${postCode}`,
					method: 'GET',
				};
			},
		}),
		storeCompanyArea: builder.mutation<SuccessfulResponse, CreateCompanyAreaRequestDTO>({
			query(body) {
				return {
					url: `company-area`,
					body,
					method: 'POST',
				};
			},
		}),
	}),
});

export const {
	useLazyGetAllCompanyAreaQuery,
	useLazyGetCompanyAreaAddressesQuery,
	useGetCompanyAreaAddressesQuery,
	useGetCompanyAreaQuery,
	useStoreCompanyAreaMutation,
	useLazyGetNearestCountyQuery,
} = companyAreaApi;
