import React, { useState } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, ScrollView } from 'react-native';
import { ChevronRightIconSvg } from '@/assets/svg/ui';
import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { normalize, PADDING } from '@/theme/responsive';

export type DropdownOption = {
	value: string;
	label: string;
};

type PalRiderDropdownProps = {
	options: DropdownOption[];
	selectedValue: string;
	onValueChange: (value: string) => void;
	placeholder?: string;
};

const PalRiderDropdown: React.FC<PalRiderDropdownProps> = ({
	options,
	selectedValue,
	onValueChange,
	placeholder = 'Select an option',
}) => {
	const [isOpen, setIsOpen] = useState(false);

	const selectedOption = options.find((opt) => opt.value === selectedValue);

	return (
		<View style={styles.wrapper}>
			<TouchableOpacity style={styles.dropdown} activeOpacity={0.8} onPress={() => setIsOpen((prev) => !prev)}>
				<Text style={styles.selectedText}>{selectedOption?.label || placeholder}</Text>
				<ChevronRightIconSvg color={colors.gray[600]} style={{ transform: [{ rotate: isOpen ? '90deg' : '0deg' }] }} />
			</TouchableOpacity>

			{isOpen && (
				<View style={styles.optionsContainer}>
					<ScrollView style={{ maxHeight: 150 }} nestedScrollEnabled={true} keyboardShouldPersistTaps="handled">
						{options.map((opt) => (
							<TouchableOpacity
								key={opt.value}
								style={styles.optionItem}
								onPress={() => {
									onValueChange(opt.value);
									setIsOpen(false);
								}}
							>
								<Text style={styles.optionText}>{opt.label}</Text>
							</TouchableOpacity>
						))}
					</ScrollView>
				</View>
			)}
		</View>
	);
};

const styles = StyleSheet.create({
	wrapper: {
		width: '100%',
		zIndex: 10, // Üstte görünmesi için
	},
	dropdown: {
		borderWidth: 1,
		borderColor: colors.gray[300],
		padding: PADDING.medium,
		borderRadius: PADDING.small,
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
		backgroundColor: colors.white,
	},
	selectedText: {
		fontSize: normalize(12),
		color: colors.gray[800],
		fontFamily: FontFamily.Semibold,
	},
	optionsContainer: {
		marginTop: 4,
		borderWidth: 1,
		borderColor: colors.gray[200],
		borderRadius: PADDING.small,
		backgroundColor: colors.white,
	},
	optionItem: {
		padding: PADDING.medium,
		borderBottomWidth: 1,
		borderBottomColor: colors.gray[100],
	},
	optionText: {
		fontSize: normalize(12),
		color: colors.gray[800],
	},
});

export default PalRiderDropdown;
