import { authCompanyAreaAddressUserApi } from '@/services/api/company/auth-company-area-address-user';
import { authCourierApi } from '@/services/api/courier/auth-courier.ts';
import { companyAreaAddressApi } from '@/services/api/company/company-area-address.ts';
import { companyCategoryApi } from '@/services/api/company/company-category.ts';
import { courierApi } from '@/services/api/courier';
import { courierVehicleApi } from '@/services/api/courier/courier-vehicle';
import { orderApi } from '@/services/api/order';
import { userApi } from '@/services/api/user';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { configureStore } from '@reduxjs/toolkit';
import { setupListeners } from '@reduxjs/toolkit/query';
import { persistReducer, persistStore } from 'redux-persist';
import { rootReducer } from './rootReducer';
import { companyApi } from '@/services/api/company/company-api';
import { companyAreaApi } from '@/services/api/company/company-area.ts';
import { notificationApi } from '@/services/api/notification';
import { smartyApi } from '@/services/api/smarty';
import { wooSmapApi } from '@/services/api/woosmap';
import { companyAreaAddressWalletApi } from '@/services/api/company/company-area-address-wallet';
import { companyAreaAddressUserApi } from '@/services/api/company/company-area-address-user';
import { orderShipmentApi } from '@/services/api/order/shipment';
import { courierWalletApi } from '@/services/api/courier/courier-wallet';
import { stripeApi } from '@/services/api/stripe';
import { courierBankAccountApi } from '@/services/api/courier/courier-bank-account';
import { companyAreaAddressDocumentApi } from '@/services/api/company/company-area-address-documents';
import { courierDocumentApi } from '@/services/api/courier/courier-document';
import { googleMapsApi } from '@/services/api/googlemaps';
import { companyWalletApi } from '@/services/api/company/company-wallet';
import { companyWalletTransferRequestApi } from '@/services/api/company/company-wallet-transfer-request';
import { companyAreaAddressPhotoApi } from '@/services/api/company/company-area-address-photos';

const persistConfig = {
	key: 'root',
	storage: AsyncStorage,
	blacklist: [],
	whitelist: [],
};
const persistedReducer = persistReducer(persistConfig, rootReducer);
const store = configureStore({
	reducer: persistedReducer,
	middleware: (getDefaultMiddleware) =>
		getDefaultMiddleware({
			serializableCheck: false,
			immutableCheck: false,
		})
			.concat(authCompanyAreaAddressUserApi.middleware)
			.concat(authCourierApi.middleware)
			.concat(courierApi.middleware)
			.concat(userApi.middleware)
			.concat(companyCategoryApi.middleware)
			.concat(courierVehicleApi.middleware)
			.concat(courierDocumentApi.middleware)
			.concat(courierWalletApi.middleware)
			.concat(courierBankAccountApi.middleware)
			.concat(orderApi.middleware)
			.concat(orderShipmentApi.middleware)
			.concat(companyAreaApi.middleware)
			.concat(companyAreaAddressApi.middleware)
			.concat(companyAreaAddressDocumentApi.middleware)
			.concat(companyAreaAddressPhotoApi.middleware)
			.concat(companyAreaAddressUserApi.middleware)
			.concat(companyAreaAddressWalletApi.middleware)
			.concat(companyApi.middleware)
			.concat(companyWalletApi.middleware)
			.concat(companyWalletTransferRequestApi.middleware)
			.concat(notificationApi.middleware)
			.concat(smartyApi.middleware)
			.concat(wooSmapApi.middleware)
			.concat(stripeApi.middleware)
			.concat(googleMapsApi.middleware),
});

const persistor = persistStore(store);
setupListeners(store.dispatch);
export type RootState = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;
export { persistor, store };
export const { dispatch: storeDispatch } = store;
