import React, { useCallback, useEffect } from 'react';
import PalRiderText from '@/components/PalRiderText';
import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { font, PADDING } from '@/theme/responsive';
import { FlatList, Pressable, RefreshControl, StyleSheet, View } from 'react-native';

import { CompositeScreenProps, useFocusEffect } from '@react-navigation/native';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import WarningModal from '@/components/custom-modal/WarningModal';
import { APP_WINDOW_WIDTH, isFetchBaseQueryError, snakeToHumanReadable } from '@/utils';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import { useLazyGetCourierDocumentsQuery } from '@/services/api/courier/courier-document';
import { WebView } from 'react-native-webview';
import { BASE_URL } from '@env';
import { useAppSelector } from '@/redux/hooks';

import { NativeStackScreenProps } from '@react-navigation/native-stack';
import {
	AppCourierDocumentsStackParamList,
	AppCourierProfileStackParamList,
	AppCourierTabParamList,
} from '@/navigation/courier-navigation';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import { MenuAction, MenuView } from '@react-native-menu/menu';
import { useLazyDeleteCompanyAreaAddressDocumentQuery } from '@/services/api/company/company-area-address-documents';
import Icon from '@/components/Icon';

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCourierDocumentsStackParamList, 'CourierDocuments'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCourierProfileStackParamList, 'CourierDocumentsStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCourierTabParamList, 'CourierProfileStack'>,
			NativeStackScreenProps<RootStackParamList>
		>
	>
>;

const AppCompanyProfileCourierDocumentsScreen: React.FC<Props> = ({ navigation }) => {
	const user = useAppSelector((x) => x.userSlice.user);
	const [getCourierDocuments, { data, isFetching, isLoading }] = useLazyGetCourierDocumentsQuery();
	const [deleteCompanyAreaDocument] = useLazyDeleteCompanyAreaAddressDocumentQuery();
	const { showGlobalModal } = useModal();

	const refreshList = async () => {
		if (!user?.courier.id) return;
		getCourierDocuments(user.courier.id);
	};

	const handleDeleteAction = async (courier_document_id: string) => {
		showGlobalModal({
			children: <LoadingModal />,
			backgroundColor: colors.transparent,
		});
		const res = await deleteCompanyAreaDocument(courier_document_id);
		if (res.error && isFetchBaseQueryError(res.error)) {
			showGlobalModal({
				children: <WarningModal text={res.error.data.title} />,
			});
			return;
		}
		showGlobalModal({
			children: <SuccessModal text={res.data?.message} />,
		});
	};

	useFocusEffect(
		useCallback(() => {
			refreshList();
		}, []),
	);
	return (
		<View style={styles.container}>
			<FlatList
				style={{ flex: 1 }}
				showsVerticalScrollIndicator={false}
				data={data?.data ?? []}
				refreshing={isFetching || isLoading}
				onRefresh={() => refreshList()}
				contentContainerStyle={{ flex: 1, gap: PADDING.large, marginTop: PADDING.large }}
				ListEmptyComponent={
					<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
						<PalRiderText>No documents found</PalRiderText>
					</View>
				}
				ListFooterComponent={
					<Pressable
						style={styles.addButton}
						onPress={() => {
							navigation.navigate('AppCourierStack', {
								screen: 'CourierProfileStack',
								params: {
									screen: 'CourierDocumentsStack',
									params: {
										screen: 'CourierDocumentCreate',
										params: {
											courier_id: user?.courier.id,
										},
									},
								},
							});
						}}
					>
						<Icon name="PlusIconSvg" width={16} height={16} color={colors.white} />
						<PalRiderText fontSize={font.small} fontFamily={FontFamily.Semibold} color={colors.white}>
							Add Document
						</PalRiderText>
					</Pressable>
				}
				renderItem={({ item: document }) => {
					const contextMenuActions: Array<MenuAction> = [
						{ id: 'show', title: 'Show' },
						{ id: 'delete', title: 'Delete' },
					];
					return (
						<MenuView
							actions={contextMenuActions}
							shouldOpenOnLongPress={false}
							isAnchoredToRight
							onPressAction={({ nativeEvent }) => {
								if (nativeEvent.event === 'show') {
									showGlobalModal({
										children: <LoadingModal />,
										backgroundColor: colors.transparent,
									});
									showGlobalModal({
										minHeight: 500,
										minWidth: APP_WINDOW_WIDTH * 0.8,
										children: (
											<WebView
												javaScriptEnabled
												originWhitelist={['*']}
												source={{ uri: BASE_URL + 'courier-document/' + document.id + '/preview' }}
												style={{ flex: 1 }}
											/>
										),
									});
								}

								if (nativeEvent.event === 'delete') {
									handleDeleteAction(document.id);
								}
							}}
						>
							<Pressable style={styles.addressContainer} key={document.id}>
								<View>
									<Icon name="PDFIconSvg" width={20} height={35} />
								</View>
								<View style={styles.documentInfoContainer}>
									<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.small}>
										{snakeToHumanReadable(document.type)}
									</PalRiderText>
									<View style={styles.documentStatusContainer}>
										{document.status === 'pending' && (
											<Icon name="ImageSearchIconSvg" width={20} height={20} color={colors.orange[600]} />
										)}
										{document.status === 'approved' && (
											<Icon name="VerifiedIconSvg" width={24} height={24} color={colors.green[600]} />
										)}
										{document.status === 'refused' && (
											<Icon name="UnverifiedIconSvg" width={24} height={24} color={colors.red[600]} />
										)}
									</View>
								</View>
							</Pressable>
						</MenuView>
					);
				}}
			/>
		</View>
	);
};
const styles = StyleSheet.create({
	container: {
		backgroundColor: colors.white,
		flex: 1,
		padding: PADDING.large,
	},
	addressContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		borderWidth: 1,
		borderColor: colors.gray[200],
		padding: PADDING.small,
		paddingHorizontal: PADDING.medium,
		gap: PADDING.large,
		borderRadius: PADDING.large,
	},
	documentInfoContainer: {
		flex: 1,
		gap: PADDING.small,
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
	},
	areaBadgeContainer: {
		flexDirection: 'row',
		gap: PADDING.small,
	},
	addContainer: {
		borderRadius: PADDING.medium,
	},
	addButton: {
		backgroundColor: colors.black,
		borderRadius: PADDING.large,
		flexDirection: 'row',
		alignItems: 'center',
		gap: PADDING.medium,
		padding: PADDING.large,
		paddingHorizontal: PADDING.medium,
	},
	documentStatusContainer: {
		alignItems: 'center',
	},
});
export default AppCompanyProfileCourierDocumentsScreen;
