import { createApi } from '@reduxjs/toolkit/query/react';
import { SuccessfulResponse } from 'palriderapptypes';
import {
	CreateCompanyAreaAddressDocumentRequestDTO,
	CreateCompanyAreaAddressPhotoRequestDTO,
} from 'palriderapptypes/company';
import { baseQueryConfigWithReAuth } from 'src/services/api/baseQueryConfig.ts';

export const companyAreaAddressPhotoApi = createApi({
	reducerPath: 'companyAreaAddressPhoto',
	baseQuery: baseQueryConfigWithReAuth,
	refetchOnMountOrArgChange: 30,
	endpoints: (builder) => ({
		getCompanyAreaAddressPhotoLink: builder.query<Blob, string>({
			query(company_area_address_photo_id) {
				return {
					url: `company-area-address-photo/${company_area_address_photo_id}/link`,
					method: 'GET',
					headers: {
						'x-response-type': 'blob',
					},
					responseHandler: async (response) => {
						const blob = await response.blob();
						const contentType = response.headers.get('Content-Type') || 'application/octet-stream';
						const typedBlob = new Blob([blob], { type: contentType, lastModified: 0 });
						return typedBlob;
					},
				};
			},
		}),
		storeCompanyAreaAddressPhoto: builder.mutation<SuccessfulResponse, CreateCompanyAreaAddressPhotoRequestDTO>({
			query(body) {
				const formData = new FormData();
				formData.append('photo', body.photo);
				return {
					url: `company-area-address/${body.company_area_address_id}/create-photo`,
					method: 'POST',
					headers: {
						'Content-Type': 'multipart/form-data',
					},
					body: formData,
				};
			},
		}),
		deleteCompanyAreaAddressPhoto: builder.query<SuccessfulResponse, string>({
			query(company_area_document_id) {
				return {
					url: `company-area-address-photo/${company_area_document_id}`,
					method: 'DELETE',
				};
			},
		}),
	}),
});

export const {
	useLazyDeleteCompanyAreaAddressPhotoQuery,
	useLazyGetCompanyAreaAddressPhotoLinkQuery,
	useStoreCompanyAreaAddressPhotoMutation,
} = companyAreaAddressPhotoApi;
