import PalRiderButton from '@/components/PalRiderButton.tsx';
import PalRiderText from '@/components/PalRiderText.tsx';
import colors from '@/theme/colors.ts';
import { font, normalize, PADDING } from '@/theme/responsive.ts';
import { yupTyped } from '@/types';
import { useFormik } from 'formik';
import React, { useMemo, useState } from 'react';
import { ActivityIndicator, KeyboardAvoidingView, Platform, ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { FontFamily } from '@/theme/fonts.ts';
import { number, string } from 'yup';
import { useAppDispatch, useAppSelector } from '@/redux/hooks.ts';
import {
	setCompanyAreaAddressInfoOnboardingState,
	setCompanyAreaInfoOnboardingState,
} from '@/redux/slices/company-onboarding';
import MapView, { LatLng, Marker } from 'react-native-maps';
import { useModal } from '@/components/ModalProvider';
import { englandCountiesByRegion, isFetchBaseQueryError, safeAreaEdges } from '@/utils';
import { OnboardingCompanyAreaInfoRequestDTO } from 'palriderapptypes/company';
import { useTranslation } from 'react-i18next';
import WarningModal from '@/components/custom-modal/WarningModal';
import { globalStyles } from '@/utils/global-styles';
import Dropdown from 'react-native-input-select';
import {
	useLazyWooSmapAutocompleteAddressFromPostCodeQuery,
	useLazyWooSmapAutocompletePostCodeQuery,
	useLazyWooSmapValidateAddressQuery,
} from '@/services/api/woosmap';
import { WooSmapAutocompleteAddressResult, WooSmapAutocompletePostCodeResult } from '@/@types/woosmap-api-types';
import PalRiderTextInput from '@/components/PalRiderTextInput';
import ConfirmationModal from '@/components/modal/items/ConfirmationModal';
import Icon from '@/components/Icon';

type Props = {
	nextStep: () => void;
	prevStep: () => void;
};
type CompanyAreaInfoOnboardingFormikType = OnboardingCompanyAreaInfoRequestDTO &
	LatLng & { address: string; building: string; post_code: string; directions: string };
const SignUpCompanyAreaInfoStep: React.FC<Props> = ({ nextStep, prevStep }) => {
	const { t } = useTranslation();
	const { showGlobalModal, hideGlobalModal } = useModal();
	const companyOnboardingSelector = useAppSelector((x) => x.companyOnboardingSlice.area);
	const dispatch = useAppDispatch();
	const [getPostCodes, { isFetching: postCodesFetching }] = useLazyWooSmapAutocompletePostCodeQuery();
	const [getAutocompleteAddresses, { isFetching: autocompleteAddressFetching }] =
		useLazyWooSmapAutocompleteAddressFromPostCodeQuery();
	const [getValidateAddress] = useLazyWooSmapValidateAddressQuery();
	const [postCodeText, setPostCodeText] = useState<string>('');
	const [selectedPostCode, setSelecetedPostCode] = useState<string | null>(null);
	const [selectedAddress, setSelectedAddress] = useState<string | null>(null);
	const [searchPostCodes, setSearchPostCodes] = useState<WooSmapAutocompletePostCodeResult | null>(null);
	const [autocompleteAddresses, setAutocomleteAddresses] = useState<WooSmapAutocompleteAddressResult | null>(null);

	const handleSearchPostCode = async () => {
		setSearchPostCodes(null);
		setAutocomleteAddresses(null);
		if (postCodeText.length > 2) {
			getPostCodes(postCodeText)
				.unwrap()
				.then((res) => {
					setSearchPostCodes(res);
					companyAreaInfoOnboardingFormik.setFieldValue('building', '', false);
					companyAreaInfoOnboardingFormik.setFieldValue('latitude', 0, false);
					companyAreaInfoOnboardingFormik.setFieldValue('longitude', 0, false);
					companyAreaInfoOnboardingFormik.setFieldValue('address', '', false);
					companyAreaInfoOnboardingFormik.setFieldValue('post_code', '', false);
					companyAreaInfoOnboardingFormik.setFieldValue('name', '', false);
				});
		}
	};
	const handlePostCodeSelect = async (selected: string) => {
		if (!selected || selected === 'null') return;

		setAutocomleteAddresses(null);
		setSelecetedPostCode(selected);
		companyAreaInfoOnboardingFormik.setFieldValue('building', '', false);
		companyAreaInfoOnboardingFormik.setFieldValue('latitude', 0, false);
		companyAreaInfoOnboardingFormik.setFieldValue('longitude', 0, false);
		companyAreaInfoOnboardingFormik.setFieldValue('address', '', false);
		companyAreaInfoOnboardingFormik.setFieldValue('post_code', '', false);
		companyAreaInfoOnboardingFormik.setFieldValue('name', '', false);

		getAutocompleteAddresses(selected)
			.unwrap()
			.then((res) => setAutocomleteAddresses(res));
	};
	const handleSelectAddress = async (public_id: string) => {
		if (!public_id || public_id === 'null') return;

		setSelectedAddress(public_id);
		showGlobalModal({
			maxHeight: 200,
			children: (
				<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', gap: PADDING.xlarge }}>
					<ActivityIndicator color={colors.black} />
					<PalRiderText>Address validating...</PalRiderText>
				</View>
			),
		});
		const res = await getValidateAddress(public_id);
		if (res.error && isFetchBaseQueryError(res.error)) {
			showGlobalModal({
				children: (
					<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', gap: PADDING.large }}>
						<Icon name="CloseIconSvg" width={32} height={32} color={colors.red[600]} />
						<PalRiderText>Cannot select location please try again</PalRiderText>
					</View>
				),
			});
		}
		var address = res.data?.result;
		if (!address) {
			showGlobalModal({
				maxHeight: 200,
				children: (
					<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', gap: PADDING.large }}>
						<Icon name="CloseIconSvg" width={32} height={32} color={colors.red[600]} />
						<PalRiderText>Selected address not found.</PalRiderText>
					</View>
				),
			});
			return;
		}

		if (address['status'] && address['status'] == 'not_yet_built') {
			showGlobalModal({
				children: <WarningModal text="Address cannot selected" />,
			});
			return;
		}

		const findPostalCodes = address.address_components.filter((x) => x.types.includes('postal_codes'));
		const findCountyName = address.address_components.filter(
			(x) =>
				x.types.includes('administrative_area_level_1') ||
				x.types.includes('county') ||
				x.types.includes('division_level_2'),
		);
		const findStreetNumber = address.address_components.filter((x) => x.types.includes('street_number'));
		hideGlobalModal();
		showGlobalModal({
			children: (
				<ConfirmationModal
					onYesPress={() => {
						companyAreaInfoOnboardingFormik.setFieldValue('latitude', address!.geometry.location.lat);
						companyAreaInfoOnboardingFormik.setFieldValue('longitude', address!.geometry.location.lng);
						companyAreaInfoOnboardingFormik.setFieldValue('address', address!.formatted_address);
						companyAreaInfoOnboardingFormik.setFieldValue(
							'post_code',
							findPostalCodes[0] ? findPostalCodes[0].short_name : '',
						);
						companyAreaInfoOnboardingFormik.setFieldValue(
							'building',
							findStreetNumber[0] ? findStreetNumber[0].short_name : '',
						);
						companyAreaInfoOnboardingFormik.setFieldValue('name', findCountyName[0] ? findCountyName[0].long_name : '');
						hideGlobalModal();
					}}
					onCancelPress={() => hideGlobalModal()}
				>
					<View style={{ gap: PADDING.large }}>
						<View style={{ alignItems: 'center' }}>
							<PalRiderText fontSize={font.medium} fontFamily={FontFamily.Semibold}>
								Is selected location correct ?
							</PalRiderText>
						</View>
						<View style={{ gap: PADDING.mini, alignItems: 'center' }}>
							<PalRiderText fontSize={font.mini} fontFamily={FontFamily.Semibold}>
								Address
							</PalRiderText>
							<PalRiderText
								numberOfLines={1}
								textBreakStrategy="highQuality"
								fontSize={font.mini}
								style={{ textAlign: 'center' }}
							>
								{address.formatted_address}{' '}
							</PalRiderText>
						</View>
						<View style={{ gap: PADDING.mini, alignItems: 'center' }}>
							<PalRiderText fontSize={font.mini} fontFamily={FontFamily.Semibold}>
								Street Number
							</PalRiderText>
							<PalRiderText fontSize={font.mini}>{findStreetNumber[0]?.long_name} </PalRiderText>
						</View>
						<View style={{ gap: PADDING.mini, alignItems: 'center' }}>
							<PalRiderText fontSize={font.mini} fontFamily={FontFamily.Semibold}>
								Post Code
							</PalRiderText>
							<PalRiderText fontSize={font.mini}>{findPostalCodes[0]?.long_name} </PalRiderText>
						</View>
						<MapView
							userInterfaceStyle="light"
							style={{ width: '100%', height: 200 }}
							provider="google"
							initialRegion={{
								latitude: address.geometry.location.lat,
								longitude: address.geometry.location.lng,
								latitudeDelta: 0.0005,
								longitudeDelta: 0.0005,
							}}
						>
							<Marker
								coordinate={{
									latitude: address.geometry.location.lat,
									longitude: address.geometry.location.lng,
								}}
							/>
						</MapView>
					</View>
				</ConfirmationModal>
			),
		});
	};
	const companyAreaInfoOnboardingFormik = useFormik<CompanyAreaInfoOnboardingFormikType>({
		initialValues: {
			name: companyOnboardingSelector.info.name,
			email: companyOnboardingSelector.info.email,
			latitude: companyOnboardingSelector.address.latitude,
			longitude: companyOnboardingSelector.address.longitude,
			address: companyOnboardingSelector.address.address,
			building: companyOnboardingSelector.address.building,
			post_code: companyOnboardingSelector.address.post_code,
			directions: companyOnboardingSelector.address.directions,
		},
		validateOnChange: false,
		validateOnBlur: false,
		validationSchema: yupTyped<CompanyAreaInfoOnboardingFormikType>({
			name: string()
				.required(t('validation.required', { field: t('common.name') }))
				.max(255, t('validation.max', { field: t('common.name'), max: 255 }))
				.min(3, t('validation.min', { field: t('common.name'), min: 3 })),
			building: string().required(t('validation.required', { field: 'Building' })),
			latitude: number().required(),
			longitude: number().required(),
			post_code: string().required(),
			address: string().required(),
		}),
		onSubmit: async (values) => {
			try {
				if (values.post_code === '' || values.address === '') {
					showGlobalModal({
						children: <WarningModal text={'Location Must Be selected'} />,
					});

					return;
				}
				dispatch(
					setCompanyAreaInfoOnboardingState({
						name: values.name,
						email: values.email,
					}),
				);
				dispatch(setCompanyAreaAddressInfoOnboardingState(values));
				nextStep();
			} catch (err) {
				showGlobalModal({
					children: <WarningModal text={t('error.cannot_save_changes')} />,
				});
			}
		},
	});
	const companyAreaAddressSelected = useMemo(() => {
		return companyAreaInfoOnboardingFormik.values.latitude && companyAreaInfoOnboardingFormik.values.longitude;
	}, [companyAreaInfoOnboardingFormik.values.latitude, companyAreaInfoOnboardingFormik.values.longitude]);

	return (
		<SafeAreaView style={styles.safeAreaContainer} edges={safeAreaEdges}>
			<KeyboardAvoidingView
				style={styles.container}
				behavior={Platform.OS === 'ios' ? 'padding' : undefined}
				keyboardVerticalOffset={Platform.OS === 'ios' ? 0 : 20} // optional tweak
			>
				<ScrollView keyboardShouldPersistTaps="handled">
					<View
						style={{
							gap: PADDING.large,
							flex: 1,
						}}
					>
						<View>
							<View style={{ flexDirection: 'row', columnGap: normalize(2) }}>
								<PalRiderText style={globalStyles.titleTextStyle}>
									Select Branch Area <PalRiderText fontSize={font.xmini}>( Dont select if you dont know )</PalRiderText>
								</PalRiderText>
							</View>

							<Dropdown
								{...globalStyles.dropdownProps}
								options={englandCountiesByRegion.map((county) => ({
									value: county,
									label: county,
								}))}
								isSearchable
								isMultiple={false}
								selectedValue={companyAreaInfoOnboardingFormik.values.name}
								onValueChange={(value) => companyAreaInfoOnboardingFormik.setFieldValue('name', value)}
								maxSelectableItems={1}
								autoCloseOnSelect
							/>
							{companyAreaInfoOnboardingFormik.errors.name && (
								<PalRiderText style={globalStyles.errorTextStyle}>
									{companyAreaInfoOnboardingFormik.errors.name}
								</PalRiderText>
							)}
						</View>
						<View>
							<View style={{ flexDirection: 'row', columnGap: normalize(2) }}>
								<PalRiderText style={globalStyles.titleTextStyle}>Post Code</PalRiderText>
							</View>
							<PalRiderTextInput
								onChangeText={(text) => setPostCodeText(text)}
								placeholder="Search For Post Code"
								placeholderTextColor={colors.gray[700]}
								enablesReturnKeyAutomatically
								returnKeyType="search"
								onSubmitEditing={handleSearchPostCode}
							/>
						</View>
						{postCodesFetching && <ActivityIndicator color={colors.black} />}
						{!postCodesFetching && searchPostCodes && searchPostCodes.localities.length >= 1 && (
							<View>
								<View style={{ flexDirection: 'row', columnGap: normalize(2) }}>
									<PalRiderText style={globalStyles.titleTextStyle}>Select Post Code</PalRiderText>
								</View>

								<Dropdown
									{...globalStyles.dropdownProps}
									options={searchPostCodes.localities.map((item) => ({
										value: item.public_id,
										label: item.description,
									}))}
									isSearchable
									isMultiple={false}
									selectedValue={selectedPostCode as string}
									onValueChange={async (selected) => handlePostCodeSelect(selected as string)}
									maxSelectableItems={1}
								/>
							</View>
						)}
						{autocompleteAddressFetching && <ActivityIndicator color={colors.black} />}
						{autocompleteAddresses && autocompleteAddresses.result.addresses.list.length >= 1 && (
							<View>
								<View style={{ flexDirection: 'row', columnGap: normalize(2) }}>
									<PalRiderText style={globalStyles.titleTextStyle}>Select Address</PalRiderText>
								</View>
								<Dropdown
									{...globalStyles.dropdownProps}
									options={autocompleteAddresses?.result.addresses.list.map((item) => ({
										value: item.public_id,
										label: item.description,
									}))}
									isSearchable
									isMultiple={false}
									selectedValue={selectedAddress as string}
									onValueChange={(selected) => {
										handleSelectAddress(selected as string);
									}}
									maxSelectableItems={1}
								/>
							</View>
						)}

						{companyAreaAddressSelected &&
							companyAreaInfoOnboardingFormik.values.latitude &&
							companyAreaInfoOnboardingFormik.values.longitude && (
								<View style={{ gap: PADDING.large }}>
									<View>
										<PalRiderTextInput
											title="Building"
											onChangeText={(text) => companyAreaInfoOnboardingFormik.setFieldValue('building', text)}
											placeholder="Building"
											placeholderTextColor={colors.gray[700]}
											value={companyAreaInfoOnboardingFormik.values.building}
										/>

										{companyAreaInfoOnboardingFormik.errors.building && (
											<PalRiderText style={globalStyles.errorTextStyle}>
												{companyAreaInfoOnboardingFormik.errors.building}
											</PalRiderText>
										)}
									</View>
									<MapView
										userInterfaceStyle="light"
										provider="google"
										style={{ width: '100%', height: 200, borderRadius: PADDING.large, overflow: 'hidden' }}
										region={{
											latitude: companyAreaInfoOnboardingFormik.values.latitude,
											longitude: companyAreaInfoOnboardingFormik.values.longitude,
											latitudeDelta: 0.001,
											longitudeDelta: 0.001,
										}}
									>
										<Marker
											tracksInfoWindowChanges
											coordinate={{
												latitude: companyAreaInfoOnboardingFormik.values.latitude,
												longitude: companyAreaInfoOnboardingFormik.values.longitude,
											}}
										/>
									</MapView>
								</View>
							)}
					</View>
				</ScrollView>
				<View
					style={{
						flexDirection: 'row',
						gap: PADDING.medium,
					}}
				>
					<PalRiderButton variant="dark" style={{ flex: 1 }} onPress={() => prevStep()}>
						<PalRiderText color="white">{t('common.go_back')}</PalRiderText>
					</PalRiderButton>
					<PalRiderButton
						variant="dark"
						style={{ flex: 1 }}
						onPress={() => companyAreaInfoOnboardingFormik.handleSubmit()}
					>
						<PalRiderText color="white">{t('common.continue')}</PalRiderText>
					</PalRiderButton>
				</View>
			</KeyboardAvoidingView>
		</SafeAreaView>
	);
};
const styles = StyleSheet.create({
	safeAreaContainer: {
		flex: 1,
		backgroundColor: colors.white,
	},
	container: {
		backgroundColor: colors.white,
		padding: PADDING.large,
		flex: 1,
	},
	locationContainer: {
		marginTop: PADDING.large,
		minHeight: normalize(50),
		borderRadius: normalize(12),
		padding: normalize(8),
		alignItems: 'center',
		gap: normalize(8),
		flexDirection: 'row',
		backgroundColor: colors.gray[200],
		shadowColor: colors.gray[400],
		shadowOpacity: 0.3,
		elevation: 5,
		shadowOffset: {
			width: 0,
			height: 1,
		},
	},
	selectedLocationContainer: {
		flex: 1,
	},
	locationText: {
		fontFamily: FontFamily.Regular,
		fontSize: normalize(10),
		color: colors.gray[400],
	},
});
export default SignUpCompanyAreaInfoStep;
