import PalRiderButton from '@/components/PalRiderButton';
import PalRiderText from '@/components/PalRiderText';
import { useAppSelector } from '@/redux/hooks';
import { useLazyGetCompanyAreasFromCompanyQuery } from '@/services/api/company/company-api';
import { useLazyGetCompanyAreaAddressesQuery } from '@/services/api/company/company-area';
import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { normalize, PADDING } from '@/theme/responsive';
import { globalStyles } from '@/utils/global-styles';
import { BottomSheetModal, BottomSheetView } from '@gorhom/bottom-sheet';
import { CompanyAreaAddressUserDTO } from 'palriderapptypes/company';
import { RefObject, useEffect, useState } from 'react';
import { StyleSheet, View } from 'react-native';
import { TextInput } from 'react-native-gesture-handler';
import Dropdown from 'react-native-input-select';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import DateTimePicker, { DateType, useDefaultStyles } from 'react-native-ui-datepicker';

type AppCompanyOrdersHomeFilterModalProps = {
	filterBottomSheet: RefObject<BottomSheetModal<any>>;
	filterOrders: (
		status: string,
		order_area_id: string | null,
		order_area_address_id: string | null,
		order_start_date: DateType | undefined,
		order_end_date: DateType | undefined,
		order_no: string,
	) => void;
};

const AppCompanyOrdersHomeFilterModal: React.FC<AppCompanyOrdersHomeFilterModalProps> = ({
	filterBottomSheet,
	filterOrders,
}) => {
	const user = useAppSelector((x) => x.userSlice.user?.company_area_address_user) as CompanyAreaAddressUserDTO;
	const [getCompanyAreas, { data: companyAreas }] = useLazyGetCompanyAreasFromCompanyQuery();
	const [getCompanyAreaAddresses, { data: companyAreaAddresses }] = useLazyGetCompanyAreaAddressesQuery();
	const [selectedStartDate, setSelectedStartDate] = useState<DateType>();
	const [selectedEndDate, setSelectedEndDate] = useState<DateType>();
	const [selectedCompanyArea, setSelectedCompanyArea] = useState<string | null>(null);
	const [selectedCompanyAreaAddress, setSelectedCompanyAreaAddress] = useState<string | null>(null);
	const [selectedStatus, setSelectedStatus] = useState('all');
	const [orderNo, setOrderNo] = useState<string>('');
	const datePickerDefaultStyles = useDefaultStyles();
	const insets = useSafeAreaInsets();

	useEffect(() => {
		getCompanyAreas({ company_id: user.company_id as string, page_number: 1, page_size: 100 });
	}, []);
	useEffect(() => {
		if (selectedCompanyArea) {
			getCompanyAreaAddresses({ company_area_id: selectedCompanyArea, page: 1, size: 100 });
		}
	}, [selectedCompanyArea]);
	return (
		<BottomSheetModal enableDynamicSizing index={1} snapPoints={['90%']} ref={filterBottomSheet}>
			<BottomSheetView style={[styles.container, { paddingBottom: insets.bottom }]}>
				<View style={{ paddingHorizontal: PADDING.large, marginVertical: PADDING.medium }}>
					<View style={{ flexDirection: 'row', columnGap: PADDING.mini }}>
						<PalRiderText style={globalStyles.titleTextStyle}>Order No</PalRiderText>
					</View>
					<TextInput
						onChangeText={(val) => setOrderNo(val)}
						style={{
							minHeight: normalize(40),
							borderWidth: normalize(1),
							borderRadius: PADDING.large,
							backgroundColor: colors.gray[100],
							borderColor: colors.gray[300],
							color: colors.black,
							fontFamily: FontFamily.Semibold,
						}}
					/>
				</View>
				<View style={{ paddingHorizontal: PADDING.large, marginVertical: PADDING.medium }}>
					<View style={{ flexDirection: 'row', columnGap: PADDING.mini }}>
						<PalRiderText style={globalStyles.titleTextStyle}>Company Area</PalRiderText>
					</View>

					<Dropdown
						{...globalStyles.dropdownProps}
						options={companyAreas?.data?.map((area) => ({ value: area.id, label: area.name })) ?? []}
						isSearchable
						isMultiple={false}
						selectedValue={selectedCompanyArea ?? ''}
						onValueChange={(value) => setSelectedCompanyArea(value as string)}
					/>
				</View>
				<View style={{ paddingHorizontal: PADDING.large, marginVertical: PADDING.medium }}>
					<View style={{ flexDirection: 'row', columnGap: PADDING.mini }}>
						<PalRiderText style={globalStyles.titleTextStyle}>Company Area Address</PalRiderText>
					</View>

					<Dropdown
						{...globalStyles.dropdownProps}
						options={
							companyAreaAddresses?.data?.map((address) => ({ value: address.id, label: address.address })) ?? []
						}
						isSearchable
						isMultiple={false}
						selectedValue={selectedCompanyAreaAddress ?? ''}
						onValueChange={(value) => setSelectedCompanyAreaAddress(value as string)}
					/>
				</View>
				<View style={{ paddingHorizontal: PADDING.large, marginVertical: PADDING.medium }}>
					<View style={{ flexDirection: 'row', columnGap: PADDING.mini }}>
						<PalRiderText style={globalStyles.titleTextStyle}>Status</PalRiderText>
					</View>

					<Dropdown
						{...globalStyles.dropdownProps}
						options={
							[
								{
									value: 'all',
									label: 'All',
								},
								{
									value: 'active',
									label: 'Active',
								},
								{
									value: 'completed',
									label: 'Completed',
								},
								{
									value: 'cancelled',
									label: 'Cancelled',
								},
							].map((val) => ({ value: val.value, label: val.label })) ?? []
						}
						isSearchable
						isMultiple={false}
						selectedValue={selectedStatus}
						onValueChange={(value) => setSelectedStatus(value as string)}
					/>
				</View>
				<View style={{ paddingHorizontal: PADDING.large, marginVertical: PADDING.medium }}>
					<View style={{ flexDirection: 'row', columnGap: PADDING.mini }}>
						<PalRiderText style={globalStyles.titleTextStyle}>Order Start - End Date</PalRiderText>
					</View>
					<DateTimePicker
						mode="range"
						startDate={selectedStartDate}
						endDate={selectedEndDate}
						onChange={({ startDate, endDate }) => {
							setSelectedStartDate(startDate);
							setSelectedEndDate(endDate);
						}}
						styles={datePickerDefaultStyles}
					/>
				</View>
				<View style={{ paddingHorizontal: PADDING.large, marginVertical: PADDING.medium }}>
					<PalRiderButton
						variant="dark"
						onPress={() => {
							filterOrders(
								selectedStatus,
								selectedCompanyArea,
								selectedCompanyAreaAddress,
								selectedStartDate,
								selectedEndDate,
								orderNo,
							);
							if (filterBottomSheet != null) {
								filterBottomSheet.current.forceClose();
							}
						}}
					>
						<PalRiderText color={colors.white}>Filter</PalRiderText>
					</PalRiderButton>
				</View>
			</BottomSheetView>
		</BottomSheetModal>
	);
};
const styles = StyleSheet.create({
	container: {
		flex: 1,
	},
});
export default AppCompanyOrdersHomeFilterModal;
