import { useStripe } from '@stripe/stripe-react-native';
import { useCallback } from 'react';
import { useCreateStripePaymentIntentMutation } from '@/services/api/stripe';
import { isFetchBaseQueryError } from '@/utils';
import { useModal } from '@/components/ModalProvider';
import WarningModal from '@/components/custom-modal/WarningModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import colors from '@/theme/colors';

type UsePalRiderOrderCheckoutParams = {
	amount: number;
	company_area_address_wallet_id?: string;
	company_wallet_id?: string;
	type?: 'main_wallet' | 'address_wallet';
	whenSucceeded?: () => void;
};

export const usePalRiderOrderCheckout = () => {
	const { initPaymentSheet, presentPaymentSheet } = useStripe();
	const [createPaymentIntent] = useCreateStripePaymentIntentMutation();
	const { showGlobalModal } = useModal();

	const initializeAndOpenPaymentSheet = useCallback(
		async (initParams: UsePalRiderOrderCheckoutParams) => {
			const defaultParams: UsePalRiderOrderCheckoutParams = {
				amount: initParams.amount,
				company_area_address_wallet_id: initParams.company_area_address_wallet_id,
				company_wallet_id: initParams.company_wallet_id,
				whenSucceeded: initParams.whenSucceeded,
				type: initParams.type ? initParams.type : 'address_wallet',
			};
			try {
				showGlobalModal({
					children: <LoadingModal />,
					backgroundColor: colors.transparent,
					preventHiding: true,
				});

				const { amount, company_area_address_wallet_id, company_wallet_id, type, whenSucceeded } = defaultParams;
				if (type == 'address_wallet') {
					const response = await createPaymentIntent({ amount, company_area_address_wallet_id });

					if (response.error && isFetchBaseQueryError(response.error)) {
						showGlobalModal({ children: <WarningModal text={response.error.data.title} /> });
						return;
					}

					if (!response.data) {
						showGlobalModal({ children: <WarningModal text="Payment initialization failed" /> });
						return;
					}

					const { payment_intent, ephemeral_key, customer, confirm_return_url } = response.data?.data;

					// Step 2: Initialize payment sheet (retry logic included)
					const initPaymentSheetWithRetry = async () => {
						const { error: initError } = await initPaymentSheet({
							merchantDisplayName: 'PalRider',
							customerId: customer,
							customerEphemeralKeySecret: ephemeral_key,
							paymentIntentClientSecret: payment_intent,
							allowsDelayedPaymentMethods: false,
							applePay: { merchantCountryCode: 'GB' },
							googlePay: { merchantCountryCode: 'GB', testEnv: true },
							returnURL: confirm_return_url,
						});

						if (initError) {
							return { success: false };
						}
						return { success: true };
					};

					let paymentSheetInitialized = await initPaymentSheetWithRetry();

					// Retry once if the first attempt fails
					if (!paymentSheetInitialized.success) {
						paymentSheetInitialized = await initPaymentSheetWithRetry();
					}

					if (!paymentSheetInitialized.success) {
						showGlobalModal({ children: <WarningModal text="Cannot initialize payment sheet" /> });
						return;
					}

					// Step 3: Open the payment sheet
					const { error: paymentError } = await presentPaymentSheet();

					if (paymentError) {
						showGlobalModal({ children: <WarningModal text={paymentError.localizedMessage} /> });
						return;
					}

					// Step 4: Show success modal
					showGlobalModal({
						children: <SuccessModal text="Payment completed" />,
						whenClose: initParams.whenSucceeded,
						closeAfterDelay: 1000,
					});
				} else if (type == 'main_wallet') {
					const response = await createPaymentIntent({ amount, company_wallet_id });

					if (response.error && isFetchBaseQueryError(response.error)) {
						showGlobalModal({ children: <WarningModal text={response.error.data.title} /> });
						return;
					}

					if (!response.data) {
						showGlobalModal({ children: <WarningModal text="Payment initialization failed" /> });
						return;
					}

					const { payment_intent, ephemeral_key, customer, confirm_return_url } = response.data?.data;

					// Step 2: Initialize payment sheet (retry logic included)
					const initPaymentSheetWithRetry = async () => {
						const { error: initError } = await initPaymentSheet({
							merchantDisplayName: 'PalRider',
							customerId: customer,
							customerEphemeralKeySecret: ephemeral_key,
							paymentIntentClientSecret: payment_intent,
							allowsDelayedPaymentMethods: false,
							applePay: { merchantCountryCode: 'GB' },
							googlePay: { merchantCountryCode: 'GB', testEnv: true },
							returnURL: confirm_return_url,
						});

						if (initError) {
							return { success: false };
						}
						return { success: true };
					};

					let paymentSheetInitialized = await initPaymentSheetWithRetry();

					// Retry once if the first attempt fails
					if (!paymentSheetInitialized.success) {
						paymentSheetInitialized = await initPaymentSheetWithRetry();
					}

					if (!paymentSheetInitialized.success) {
						showGlobalModal({ children: <WarningModal text="Cannot initialize payment sheet" /> });
						return;
					}

					// Step 3: Open the payment sheet
					const { error: paymentError } = await presentPaymentSheet();

					if (paymentError) {
						showGlobalModal({ children: <WarningModal text={paymentError.localizedMessage} /> });
						return;
					}

					// Step 4: Show success modal
					showGlobalModal({
						children: <SuccessModal text="Payment completed" />,
						whenClose: initParams.whenSucceeded,
						closeAfterDelay: 1000,
					});
				}
			} catch (error) {
				showGlobalModal({ children: <WarningModal text="An unexpected error occurred" /> });
			}
		},
		[createPaymentIntent, initPaymentSheet, presentPaymentSheet, showGlobalModal],
	);

	return { initializeAndOpenPaymentSheet };
};
