import { FontFamily } from '@/theme/fonts';
import { normalize } from '@/theme/responsive';
import React from 'react';
import PalRiderText from './PalRiderText';
import PalRiderTextInput, { PalRiderTextInputProps } from './PalRiderTextInput';

interface PalRiderCurrencyInputProps extends PalRiderTextInputProps {
	onChangeCurrencyText?: (text: string) => void;
	currencyValue: string | number;
}
const PalRiderCurrencyInput: React.FC<PalRiderCurrencyInputProps> = (props) => {
	const { format } = Intl.NumberFormat('en-UK', {
		currency: 'GBP',
		style: 'currency',
	});

	const formatCurrency = (input: string): string => {
		const decimal = Number(input.replace(/\D/g, '')) / 100;
		return format(decimal || 0).replace('£', '');
	};

	const handleChange = (text: string) => {
		const formattedValue = formatCurrency(text);

		if (props.onChangeCurrencyText) {
			props.onChangeCurrencyText(formattedValue);
		}
	};
	return (
		<PalRiderTextInput
			value={props.currencyValue.toString()}
			textAlign="right"
			leftComponent={
				<PalRiderText
					style={{
						fontFamily: FontFamily.Bold,
						fontSize: normalize(12),
					}}
				>
					£
				</PalRiderText>
			}
			onChangeText={handleChange}
			keyboardType="numeric"
			placeholder="0.00"
			{...props}
		/>
	);
};
export default PalRiderCurrencyInput;
