import React from 'react';
import { StyleSheet, View } from 'react-native';
import { FilledStarIconSvg, HalfFilledStarIconSvg, UnFilledStarIconSvg } from '@/assets/svg/custom.tsx';
type Props = {
	rating: number;
	maxRating?: number;
	fullStar?: React.ReactNode;
	halfStar?: React.ReactNode;
	emptyStar?: React.ReactNode;
};
const PalRiderStarRating: React.FC<Props> = (props) => {
	const { rating = 0, maxRating = 5 } = props;

	function getStars(_rating: number, _maxStars: number) {
		return [...Array(_maxStars)].map((_, i) => {
			if (_rating - i >= 1) {
				return 'full';
			}

			return _rating - i >= 0.5 ? 'half' : 'empty';
		});
	}
	return (
		<View style={styles.ratingContainer}>
			{getStars(rating, maxRating).map((item, key) => {
				return (
					<View key={key + item}>
						{item === 'empty' && <UnFilledStarIconSvg width={16} height={16} />}
						{item === 'half' && <HalfFilledStarIconSvg width={16} height={16} />}
						{item === 'full' && <FilledStarIconSvg width={16} height={16} />}
					</View>
				);
			})}
		</View>
	);
};
const styles = StyleSheet.create({
	ratingContainer: {
		flexDirection: 'row',
	},
});
export default PalRiderStarRating;
