import React from 'react';
import { ScrollView, StyleSheet, View } from 'react-native';
import PalRiderText from '@/components/PalRiderText.tsx';
import colors from '@/theme/colors.ts';
import { font, normalize, PADDING } from '@/theme/responsive.ts';
import { FontFamily } from '@/theme/fonts.ts';
import { useAppDispatch, useAppSelector } from '@/redux/hooks.ts';
import useUserNavigation from '@/hooks/useUserNavigation.tsx';
import { setToken, setUser } from '@/redux/slices/userSlice.ts';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { CompositeScreenProps, useNavigation } from '@react-navigation/native';
import { Pressable } from 'react-native-gesture-handler';
import { AppCourierProfileStackParamList, AppCourierTabParamList } from '@/navigation/courier-navigation';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { RootStackParamList } from '@/navigation';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import Icon from '@/components/Icon';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCourierProfileStackParamList, 'CourierProfile'>,
	CompositeScreenProps<
		BottomTabScreenProps<AppCourierTabParamList, 'CourierProfileStack'>,
		NativeStackScreenProps<RootStackParamList>
	>
>;

const AppCourierProfileScreen: React.FC<Props> = ({ navigation }) => {
	const dispatch = useAppDispatch();
	const { handle: hanldeLogoutNavigation } = useUserNavigation();
	const user = useAppSelector((x) => x.userSlice.user);
	const handleLogout = async () => {
		dispatch(setToken(null));
		dispatch(setUser(null));
		await AsyncStorage.removeItem('token');
		await hanldeLogoutNavigation();
	};
	const profileActionItems = [
		{
			title: 'My Account',
			icon: <Icon name="ProfileIconSvg" width={20} height={20} />,
			action: () => {
				navigation.navigate('AppCourierStack', {
					screen: 'CourierProfileStack',
					params: {
						screen: 'CourierMyAccount',
					},
				});
			},
		},
		{
			title: 'Vehicles',
			icon: <Icon name="GarageIconSvg" width={20} height={20} />,
			action: () => {
				navigation.navigate('AppCourierStack', {
					screen: 'CourierProfileStack',
					params: {
						screen: 'CourierVehiclesStack',
						params: {
							screen: 'CourierVehicles',
						},
					},
				});
			},
		},
		{
			title: 'Documents',
			icon: <Icon name="DefaultDocumentIconSvg" width={20} height={20} />,
			action: () => {
				navigation.navigate('AppCourierStack', {
					screen: 'CourierProfileStack',
					params: {
						screen: 'CourierDocumentsStack',
						params: {
							screen: 'CourierDocuments',
						},
					},
				});
			},
		},
		{
			title: 'Wallet',
			icon: <Icon name="WalletIconSvg" width={20} height={20} />,
			action: () => {
				navigation.navigate('AppCourierStack', {
					screen: 'CourierProfileStack',
					params: {
						screen: 'CourierWallet',
					},
				});
			},
		},
		{
			title: 'Bank Account Information',
			icon: <Icon name="WalletIconSvg" width={20} height={20} />,
			action: () => {
				navigation.navigate('AppCourierStack', {
					screen: 'CourierProfileStack',
					params: {
						screen: 'CourierBankAccount',
					},
				});
			},
		},
		{
			title: 'Settings',
			icon: <Icon name="CogIconSvg" width={20} height={20} />,
			action: () => {
				navigation.navigate('AppCourierStack', {
					screen: 'CourierProfileStack',
					params: {
						screen: 'CourierSettings',
					},
				});
			},
		},
		{
			title: 'Help',
			icon: <Icon name="CommentQuestionIconSvg" width={20} height={20} />,
			action: () => {},
		},
	];
	return (
		<View style={{ flex: 1 }}>
			<ScrollView style={styles.container}>
				{profileActionItems.map((profileAction, index) => (
					<Pressable key={index} style={styles.profileItemContainer} onPress={profileAction.action}>
						{profileAction.icon}
						<View style={styles.profileItemTextContainer}>
							<PalRiderText style={styles.profileItemText}>{profileAction.title}</PalRiderText>
						</View>
						<Icon name="ChevronRightIconSvg" />
					</Pressable>
				))}
				<Pressable style={styles.profileItemContainer} onPress={() => handleLogout()}>
					<Icon name="LogoutIconSvg" color={colors.red[500]} width={16} height={16} />
					<View style={styles.profileItemTextContainer}>
						<PalRiderText style={[styles.profileItemText, { color: colors.red[500] }]}>Logout</PalRiderText>
					</View>
				</Pressable>
			</ScrollView>
		</View>
	);
};
const styles = StyleSheet.create({
	container: {
		backgroundColor: colors.white,
		flex: 1,
	},
	profileContainer: {
		width: '100%',
		padding: PADDING.xlarge,
		paddingVertical: PADDING.large,
		flexDirection: 'row',
		alignItems: 'center',
		gap: PADDING.large,
		borderBottomWidth: 1,
		borderBottomColor: colors.gray[300],
	},
	profileImageContainer: {
		width: PADDING.xlarge * 3,
		height: PADDING.xlarge * 3,
		borderRadius: PADDING.xlarge * 3,
		backgroundColor: colors.white,
		shadowColor: colors.orange[900],
		shadowOpacity: 0.2,
		shadowOffset: {
			width: 0,
			height: 3,
		},
		shadowRadius: 6,
	},
	profileImage: {
		width: PADDING.xlarge * 3,
		height: PADDING.xlarge * 3,
		borderRadius: PADDING.xlarge * 3,
	},
	profileUserContainer: {
		flex: 1,
		gap: PADDING.small,
	},
	profileUsernameText: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.medium,
		color: colors.white,
	},
	profilePhoneNumberText: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.xmini,
		color: colors.orange[200],
	},
	profileItemContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		paddingVertical: PADDING.large,
		paddingHorizontal: PADDING.large,
		borderBottomWidth: 1,
		borderBottomColor: colors.gray[200],
		gap: PADDING.medium,
	},
	profileItemTextContainer: {
		flex: 1,
	},
	profileItemText: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.small,
	},
});
export default AppCourierProfileScreen;
