import React, { useCallback, useState } from 'react';
import { Image, Pressable, StyleSheet, View, ScrollView, Alert } from 'react-native';
import { useFormik } from 'formik';
import { FileType } from '@/@types';
import PalRiderText from '@/components/PalRiderText';
import PalRiderButton from '@/components/PalRiderButton';
import { FontFamily } from '@/theme/fonts';
import colors from '@/theme/colors';
import { font, PADDING } from '@/theme/responsive';
import { yupTyped } from '@/types';
import { array, number, object, string } from 'yup';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { isFetchBaseQueryError } from '@/utils';
import WarningModal from '@/components/custom-modal/WarningModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import { CompositeScreenProps } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import {
	AppCompanyProfileCompanyAreaParamList,
	AppCompanyProfileParamList,
	AppCompanyTabParamList,
} from '@/navigation/company-navigation';
import { useTranslation } from 'react-i18next';
import Icon from '@/components/Icon';
import { useStoreCompanyAreaAddressPhotoMutation } from '@/services/api/company/company-area-address-photos';
import PalRiderBottomSelectModal from '@/components/PalRiderBottomSelectModal';
import { launchCamera, launchImageLibrary } from 'react-native-image-picker';

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList, 'CompanyAreaAddressPhotoCreate'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyAreaStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
			CompositeScreenProps<
				NativeStackScreenProps<RootStackParamList>,
				NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList>
			>
		>
	>
>;

const AppCompanyProfileCompanyAreaAddressPhotoAddScreen: React.FC<Props> = ({ route, navigation }) => {
	const { t } = useTranslation();
	const [activeModal, setActiveModal] = useState<boolean>(false);
	const { showGlobalModal } = useModal();
	const [storeCompanyAreaAddressPhoto] = useStoreCompanyAreaAddressPhotoMutation();

	const photoFormik = useFormik<any>({
		initialValues: {
			company_area_address_id: route.params.company_area_address_id,
			photos: [],
		},
		validationSchema: yupTyped<any>({
			photos: array()
				.of(
					object().shape({
						name: string().required(t('validation.required', { field: t('common.name') })),
						size: number().required().max(10000000, 'File size must be less than 10MB'),
						uri: string().required('File uri is required'),
						type: string().required('File type is required'),
					}),
				)
				.required('Photo is required')
				.min(1, 'Please upload a photo')
				.max(1, 'Only one photo allowed'),
		}),
		onSubmit: async (values) => {
			if (values.photos.length === 0) {
				Alert.alert('No Photo', 'Please add a photo before submitting.');
				return;
			}

			showGlobalModal({
				children: <LoadingModal />,
				backgroundColor: colors.transparent,
			});

			try {
				const res = await storeCompanyAreaAddressPhoto({
					company_area_address_id: values.company_area_address_id,
					photo: values.photos[0],
				});

				if (res.error && isFetchBaseQueryError(res.error)) {
					showGlobalModal({
						children: <WarningModal text={res.error.data.title} />,
					});
					return;
				}

				showGlobalModal({
					children: <SuccessModal text={res.data?.message || 'Photo uploaded successfully!'} />,
					whenClose() {
						navigation.goBack();
					},
				});
			} catch (error) {
				showGlobalModal({
					children: <WarningModal text="Failed to upload photo. Please try again." />,
				});
			}
		},
	});

	const onFileSelected = useCallback(
		(files: FileType[]) => {
			const validFiles: FileType[] = files
				.filter((file) => file.name && file.uri && file.size && file.type)
				.map((file) => ({
					name: file.name!,
					uri: file.uri!,
					size: file.size!,
					type: file.type!,
				}));

			if (validFiles.length > 0) {
				photoFormik.setFieldValue('photos', [validFiles[0]]);
			}
		},
		[photoFormik],
	);

	const pickFromLibrary = useCallback(async () => {
		try {
			const result = await launchImageLibrary({
				mediaType: 'photo',
				selectionLimit: 1,
				quality: 0.8,
			});

			if (result.assets && result.assets.length > 0) {
				const file = result.assets[0];
				const fileData: FileType = {
					name: file.fileName || `photo_${Date.now()}.jpg`,
					size: file.fileSize || 0,
					type: file.type || 'image/jpeg',
					uri: file.uri || '',
				};

				onFileSelected([fileData]);
			}
		} catch (error) {
			console.error('Error picking from library:', error);
			Alert.alert('Error', 'Failed to select image from library');
		}
		setActiveModal(false);
	}, [onFileSelected]);

	const takePhoto = useCallback(async () => {
		try {
			const result = await launchCamera({
				mediaType: 'photo',
				saveToPhotos: true,
				quality: 0.8,
			});

			if (result.assets && result.assets.length > 0) {
				const file = result.assets[0];
				const fileData: FileType = {
					name: file.fileName || `photo_${Date.now()}.jpg`,
					size: file.fileSize || 0,
					type: file.type || 'image/jpeg',
					uri: file.uri || '',
				};

				onFileSelected([fileData]);
			}
		} catch (error) {
			console.error('Error taking photo:', error);
			Alert.alert('Error', 'Failed to take photo');
		}
		setActiveModal(false);
	}, [onFileSelected]);

	const handleRemoveImage = useCallback(() => {
		photoFormik.setFieldValue('photos', []);
	}, [photoFormik]);

	const hasPhoto = photoFormik.values.photos.length > 0;
	const currentPhoto = hasPhoto ? photoFormik.values.photos[0] : null;

	return (
		<View style={styles.container}>
			<PalRiderBottomSelectModal
				data={[
					{
						text: 'Choose from Gallery',
						onPress: pickFromLibrary,
					},
					{
						text: 'Take Photo',
						onPress: takePhoto,
					},
				]}
				isVisible={activeModal}
				title="Add Photo"
				cancelOnPress={() => setActiveModal(false)}
				isCoverScreen
			/>

			<ScrollView style={styles.scrollView} showsVerticalScrollIndicator={false}>
				{/* Header */}
				<View style={styles.header}>
					<PalRiderText style={styles.title}>Add Address Photo</PalRiderText>
					<PalRiderText style={styles.subtitle}>
						Upload a clear photo of your address location for verification
					</PalRiderText>
				</View>

				{/* Photo Upload Area */}
				<View style={styles.uploadArea}>
					{!hasPhoto ? (
						<Pressable style={styles.uploadPlaceholder} onPress={() => setActiveModal(true)}>
							<View style={styles.uploadIconContainer}>
								<Icon name="UploadIconSvg" color={colors.orange[600]} width={40} height={40} />
							</View>
							<PalRiderText style={styles.uploadTitle}>Upload Photo</PalRiderText>
							<PalRiderText style={styles.uploadSubtitle}>Tap to add a photo of your location</PalRiderText>
							<View style={styles.uploadHint}>
								<PalRiderText style={styles.uploadHintText}>JPG, PNG • Max 10MB</PalRiderText>
							</View>
						</Pressable>
					) : (
						<View style={styles.photoPreviewContainer}>
							<Image source={{ uri: currentPhoto.uri }} style={styles.photoPreview} />
							<Pressable style={styles.removeButton} onPress={handleRemoveImage}>
								<Icon name="CloseIconSvg" color={colors.white} width={18} height={18} />
							</Pressable>

							<View style={styles.photoDetails}>
								<View style={styles.photoInfo}>
									<PalRiderText style={styles.photoName} numberOfLines={1}>
										{currentPhoto.name}
									</PalRiderText>
									<PalRiderText style={styles.photoSize}>
										{(currentPhoto.size / 1024 / 1024).toFixed(1)} MB
									</PalRiderText>
								</View>

								<Pressable style={styles.changePhotoButton} onPress={() => setActiveModal(true)}>
									<Icon name="EditIconSvg" color={colors.orange[100]} width={16} height={16} />
									<PalRiderText style={styles.changePhotoText}>Change</PalRiderText>
								</Pressable>
							</View>
						</View>
					)}
				</View>

				{/* Guidelines */}
				<View style={styles.guidelines}>
					<PalRiderText style={styles.guidelinesTitle}>Photo Guidelines</PalRiderText>
					<View style={styles.guidelinesItems}>
						<View style={styles.guidelineItem}>
							<View style={styles.guidelineIcon}>
								<Icon name="CheckIconSvg" color={colors.green[600]} width={16} height={16} />
							</View>
							<PalRiderText style={styles.guidelineText}>Clear view of the building or address</PalRiderText>
						</View>
						<View style={styles.guidelineItem}>
							<View style={styles.guidelineIcon}>
								<Icon name="CheckIconSvg" color={colors.green[600]} width={16} height={16} />
							</View>
							<PalRiderText style={styles.guidelineText}>Good lighting and focus</PalRiderText>
						</View>
						<View style={styles.guidelineItem}>
							<View style={styles.guidelineIcon}>
								<Icon name="CheckIconSvg" color={colors.green[600]} width={16} height={16} />
							</View>
							<PalRiderText style={styles.guidelineText}>Include visible address markers if available</PalRiderText>
						</View>
					</View>
				</View>

				{/* Error Message */}
				{photoFormik.errors.photos && (
					<View style={styles.errorContainer}>
						<Icon name="WarningIconSvg" color={colors.red[500]} width={16} height={16} />
						<PalRiderText style={styles.errorText}>
							{typeof photoFormik.errors.photos === 'string'
								? photoFormik.errors.photos
								: 'Please fix the photo errors'}
						</PalRiderText>
					</View>
				)}
			</ScrollView>

			{/* Bottom Submit Button */}
			<View style={styles.bottomSection}>
				<PalRiderButton
					onPress={() => photoFormik.handleSubmit()}
					disabled={!hasPhoto}
					style={[styles.submitButton, !hasPhoto && styles.submitButtonDisabled]}
				>
					<PalRiderText color="white" fontFamily={FontFamily.Semibold} style={styles.submitButtonText}>
						Submit Photo
					</PalRiderText>
				</PalRiderButton>
			</View>
		</View>
	);
};

