import React, { useState } from 'react';
import { StyleSheet, View } from 'react-native';
import colors from '@/theme/colors.ts';
import { PADDING } from '@/theme/responsive';
import PalRiderButton from '@/components/PalRiderButton';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { CompositeScreenProps } from '@react-navigation/native';
import { isFetchBaseQueryError } from '@/utils';
import WarningModal from '@/components/custom-modal/WarningModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import { AppCompanyProfileParamList, AppCompanyTabParamList } from '@/navigation/company-navigation';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import PalRiderCurrencyInput from '@/components/PalRiderCurrencyInput';
import ConfirmationModal from '@/components/custom-modal/ConfirmationModal';
import { useRequestTransferMutation } from '@/services/api/company/company-wallet-transfer-request';
import Icon from '@/components/Icon';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyWalletTransferRequestCreate'>,
	CompositeScreenProps<
		BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
		NativeStackScreenProps<RootStackParamList>
	>
>;

const AppCompanyProfileCompanyWalletTransferRequestCreateScreen: React.FC<Props> = ({ navigation, route }) => {
	if (!route.params.company_wallet_id || !route.params.company_area_address_wallet_id) {
		navigation.goBack();
		return;
	}
	const { showGlobalModal, hideGlobalModal } = useModal();
	const [transferAmount, setTransferAmount] = useState('0');
	const [requestTransfer] = useRequestTransferMutation();
	const handleTransferConfirm = () => {
		if (Number(transferAmount) <= 0) {
			showGlobalModal({
				children: <WarningModal text="Transfer amount must be at least 1" />,
			});
			return;
		}
		showGlobalModal({
			padding: 0,
			children: (
				<ConfirmationModal
					icon={<Icon name="TransferFillIconSvg" width={48} height={48} color={colors.green[600]} />}
					text={'Are you sure want to request transfer ?'}
					textColor={colors.green[600]}
					onConfirm={() => handleTransfer()}
					onCancel={() => hideGlobalModal()}
				/>
			),
		});
		return;
	};
	const handleTransfer = async () => {
		showGlobalModal({
			children: <LoadingModal />,
			backgroundColor: colors.transparent,
			padding: 0,
		});
		const res = await requestTransfer({
			amount: Number(transferAmount),
			company_area_address_wallet_id: route.params.company_area_address_wallet_id,
			company_wallet_id: route.params.company_wallet_id,
		});
		if (res.error && isFetchBaseQueryError(res.error)) {
			showGlobalModal({
				children: <WarningModal text={res.error.data.title} />,
			});
			return;
		}

		showGlobalModal({
			children: <SuccessModal text={res.data?.message} />,
			closeAfterDelay: 1000,
			whenClose() {
				if (route.params.return_call_rider) {
					navigation.navigate('AppCompanyStack', {
						screen: 'CompanyOrderStack',
						params: {
							screen: 'CompanyCallRider',
						},
					});
					return;
				}
				navigation.canGoBack() && navigation.goBack();
			},
		});
	};

	return (
		<View style={styles.container}>
			<View style={{ gap: PADDING.large }}>
				<PalRiderCurrencyInput
					title="Transfer Amount"
					onChangeCurrencyText={async (text) => {
						setTransferAmount(text);
					}}
					value={transferAmount}
					currencyValue={'0.00'}
				/>
				<PalRiderButton variant="success" onPress={handleTransferConfirm}>
					Request Transfer
				</PalRiderButton>
			</View>
		</View>
	);
};
const styles = StyleSheet.create({
	container: {
		backgroundColor: colors.white,
		flex: 1,
		padding: PADDING.large,
		rowGap: PADDING.large,
	},
});
export default AppCompanyProfileCompanyWalletTransferRequestCreateScreen;
