import { createApi } from '@reduxjs/toolkit/query/react';
import { baseQueryConfigWithReAuth } from '../baseQueryConfig';
import { PaginationDataResultT, SuccessfulResponse } from 'palriderapptypes';
import { CourierBankAccountDTO, CreateCourierBankAccountRequestDTO } from 'palriderapptypes/courier';
import { PaginationRequestDTO } from 'palriderapptypes/common';
export const courierBankAccountApi = createApi({
	reducerPath: 'courierBankAccount',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		getCourierBankAccounts: builder.query<PaginationDataResultT<CourierBankAccountDTO>, PaginationRequestDTO>({
			query({ page, size }) {
				return {
					url: `courier/bank-account?page=${page}&size=${size}`,
					method: 'GET',
				};
			},
		}),
		createBankAccount: builder.mutation<SuccessfulResponse, CreateCourierBankAccountRequestDTO>({
			query(body) {
				return {
					url: `courier/bank-account`,
					method: 'POST',
					body,
				};
			},
		}),
		deleteBankAccount: builder.query<SuccessfulResponse, string>({
			query(bank_account_id) {
				return {
					url: `courier/bank-account/${bank_account_id}`,
					method: 'DELETE',
				};
			},
		}),
		setPrimaryBankAccount: builder.query<SuccessfulResponse, string>({
			query(bank_account_id) {
				return {
					url: `courier/bank-account/${bank_account_id}/set-primary`,
					method: 'GET',
				};
			},
		}),
	}),
});

export const {
	useLazyGetCourierBankAccountsQuery,
	useCreateBankAccountMutation,
	useLazyDeleteBankAccountQuery,
	useLazySetPrimaryBankAccountQuery,
} = courierBankAccountApi;
