import { createApi } from '@reduxjs/toolkit/query/react';
import { SuccessfulResponse } from 'palriderapptypes';
import { baseQueryConfigWithReAuth } from 'src/services/api/baseQueryConfig.ts';

export const companyWalletTransferRequestApi = createApi({
	reducerPath: 'companyWalletTransaferRequest',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		// getCompanyWallet: builder.query<SuccessfulResponseT<CompanyWalletDTO>, string>({
		// 	query(company_wallet_id) {
		// 		return {
		// 			url: `company-wallet/${company_wallet_id}`,
		// 			method: 'GET',
		// 		};
		// 	},
		// }),
		requestTransfer: builder.mutation<
			SuccessfulResponse,
			{ company_wallet_id: string; company_area_address_wallet_id: string; amount: number }
		>({
			query(body) {
				return {
					url: `company-wallet-transfer-request`,
					method: 'POST',
					body: {
						amount: body.amount,
						company_area_address_wallet_id: body.company_area_address_wallet_id,
						company_wallet_id: body.company_wallet_id,
					},
				};
			},
		}),

		approveTransferRequest: builder.query<SuccessfulResponse, { company_wallet_transfer_request_id: string }>({
			query(body) {
				return {
					url: `company-wallet-transfer-request/${body.company_wallet_transfer_request_id}/approve`,
					method: 'GET',
				};
			},
		}),
		rejectTransferRequest: builder.query<SuccessfulResponse, { company_wallet_transfer_request_id: string }>({
			query(body) {
				return {
					url: `company-wallet-transfer-request/${body.company_wallet_transfer_request_id}/reject`,
					method: 'GET',
				};
			},
		}),
	}),
});

export const { useRequestTransferMutation, useLazyApproveTransferRequestQuery, useLazyRejectTransferRequestQuery } =
	companyWalletTransferRequestApi;
