import React, { useEffect } from 'react';
import PalRiderText from '@/components/PalRiderText';
import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { normalize, font, PADDING } from '@/theme/responsive';
import { FlatList, RefreshControl, StyleSheet, View } from 'react-native';

import LinearGradient from 'react-native-linear-gradient';
import { Pressable } from 'react-native-gesture-handler';
import { useModal } from '@/components/ModalProvider';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import WarningModal from '@/components/custom-modal/WarningModal';
import { APP_WINDOW_WIDTH, isFetchBaseQueryError } from '@/utils';
import SuccessModal from '@/components/custom-modal/SuccessModal';
import WebView from 'react-native-webview';
import { useAppSelector } from '@/redux/hooks';
import { BASE_URL } from '@env';

import { CompositeScreenProps } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { RootStackParamList } from '@/navigation';
import {
	AppCompanyProfileCompanyAreaParamList,
	AppCompanyProfileParamList,
	AppCompanyTabParamList,
} from '@/navigation/company-navigation';
import { useTranslation } from 'react-i18next';
import { MenuAction, MenuView } from '@react-native-menu/menu';
import { useLazyGetCompanyAreaAddressPhotosQuery } from '@/services/api/company/company-area-address';
import Icon from '@/components/Icon';
import {
	useLazyDeleteCompanyAreaAddressPhotoQuery,
	useLazyGetCompanyAreaAddressPhotoLinkQuery,
} from '@/services/api/company/company-area-address-photos';

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList, 'CompanyAreaAddressPhotos'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyAreaStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
			CompositeScreenProps<
				NativeStackScreenProps<RootStackParamList>,
				NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList>
			>
		>
	>
>;
const AppCompanyProfileCompanyAreaAddressPhotosScreen: React.FC<Props> = ({ route, navigation }) => {
	const { t } = useTranslation();
	const user = useAppSelector((x) => x.userSlice);
	if (!route.params.company_area_address_id) navigation.goBack();
	const [getCompanyAreaAddressPhotos, { data, isFetching, isLoading }] = useLazyGetCompanyAreaAddressPhotosQuery();
	const [linkCompanyAreaAddressPhoto] = useLazyGetCompanyAreaAddressPhotoLinkQuery();
	const [deleteCompanyAreaAddressPhoto] = useLazyDeleteCompanyAreaAddressPhotoQuery();
	const { showGlobalModal } = useModal();

	const refreshList = async () => {
		console.log(route.params);
		if (!route.params.company_area_address_id) return;
		getCompanyAreaAddressPhotos(route.params.company_area_address_id);
	};

	const handleDeleteAction = async (company_area_photo_id: string) => {
		showGlobalModal({
			children: <LoadingModal />,
			backgroundColor: colors.transparent,
		});
		const res = await deleteCompanyAreaAddressPhoto(company_area_photo_id);
		if (res.error && isFetchBaseQueryError(res.error)) {
			showGlobalModal({
				children: <WarningModal text={res.error.data.title} />,
			});
			return;
		}
		showGlobalModal({
			children: <SuccessModal text={res.data?.message} />,
		});
	};

	useEffect(() => {
		refreshList();
	}, []);
	return (
		<View style={styles.container}>
			<FlatList
				style={{ flex: 1 }}
				showsVerticalScrollIndicator={false}
				data={data?.data ?? []}
				refreshing={isFetching || isLoading}
				contentContainerStyle={{ flex: 1, gap: normalize(10) }}
				contentInsetAdjustmentBehavior="automatic"
				ListEmptyComponent={
					<View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>No Photo Found</View>
				}
				ListFooterComponent={
					<LinearGradient
						style={styles.addContainer}
						colors={[colors.red[500], colors.orange[500]]}
						start={{ x: 0, y: 1 }}
						end={{ x: 1, y: 0 }}
					>
						<Pressable
							style={styles.addButton}
							onPress={() => {
								navigation.navigate('AppCompanyStack', {
									screen: 'CompanyProfileStack',
									params: {
										screen: 'CompanyAreaStack',
										params: {
											screen: 'CompanyAreaAddressPhotoCreate',
											params: {
												company_area_address_id: route.params.company_area_address_id,
											},
										},
									},
								});
							}}
						>
							<Icon name="PlusIconSvg" width={16} height={16} color={colors.white} />
							<PalRiderText fontSize={font.small} fontFamily={FontFamily.Semibold} color={colors.white}>
								Add Address Photo
							</PalRiderText>
						</Pressable>
					</LinearGradient>
				}
				refreshControl={<RefreshControl onRefresh={refreshList} refreshing={isFetching} />}
				renderItem={({ item: photo }) => {
					const contextMenuActions: Array<MenuAction> = [
						{ id: 'show', title: t('common.show') },
						{ id: 'delete', title: t('common.delete') },
					];
					return (
						<MenuView
							actions={contextMenuActions}
							shouldOpenOnLongPress={false}
							isAnchoredToRight
							onPressAction={({ nativeEvent }) => {
								if (nativeEvent.event === 'show') {
									showGlobalModal({
										children: <LoadingModal />,
										backgroundColor: colors.transparent,
									});
									linkCompanyAreaAddressPhoto(photo.id)
										.unwrap()
										.then(async () => {
											const token = user.token;

											showGlobalModal({
												minHeight: 500,
												minWidth: APP_WINDOW_WIDTH * 0.8,
												children: (
													<WebView
														javaScriptEnabled
														originWhitelist={['*']}
														source={{
															uri: BASE_URL + 'company-area-address-photo/' + photo.id + '/preview',
															headers: {
																Authorization: 'Bearer ' + token,
															},
														}}
														style={{ flex: 1 }}
													/>
												),
											});
										});
								}
								if (nativeEvent.event === 'delete') {
									handleDeleteAction(photo.id);
								}
							}}
						>
							<Pressable style={styles.addressContainer} key={photo.id}>
								<View>
									<Icon name="ImageSearchIconSvg" width={20} height={35} />
								</View>

								<View style={styles.documentInfoContainer}>
									<PalRiderText fontFamily={FontFamily.Semibold} fontSize={font.small}>
										{photo.company_area_address_photo_type?.name ?? t('common.photo', 'Photo')}
									</PalRiderText>
									<View style={styles.documentStatusContainer}>
										{photo.status === 'pending' && (
											<Icon name="ImageSearchIconSvg" width={20} height={20} color={colors.orange[600]} />
										)}
										{photo.status === 'approved' && (
											<Icon name="VerifiedIconSvg" width={24} height={24} color={colors.green[600]} />
										)}
										{photo.status === 'refused' && (
											<Icon name="UnverifiedIconSvg" width={24} height={24} color={colors.red[600]} />
										)}
									</View>
								</View>
							</Pressable>
						</MenuView>
					);
				}}
			/>
		</View>
	);
};
const styles = StyleSheet.create({
	container: {
		backgroundColor: colors.white,
		flex: 1,
		padding: PADDING.large,
	},
	addressContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		borderWidth: 1,
		borderColor: colors.gray[200],
		padding: PADDING.small,
		paddingHorizontal: PADDING.medium,
		gap: PADDING.large,
		borderRadius: PADDING.large,
	},
	documentInfoContainer: {
		flex: 1,
		gap: PADDING.small,
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
	},
	areaBadgeContainer: {
		flexDirection: 'row',
		gap: PADDING.small,
	},
	addContainer: {
		borderRadius: PADDING.medium,
	},
	addButton: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: PADDING.medium,
		padding: PADDING.large,
		paddingHorizontal: PADDING.medium,
	},
	documentStatusContainer: {
		alignItems: 'center',
	},
});
export default AppCompanyProfileCompanyAreaAddressPhotosScreen;
