import { useModal } from '@/components/ModalProvider';
import PalRiderText from '@/components/PalRiderText';
import LoadingModal from '@/components/custom-modal/LoadingModal';
import { useLazyGetCourierActiveOrderQuery, useLazyGetCourierActiveOrderShipmentsQuery } from '@/services/api/order';
import colors from '@/theme/colors';
import { FontFamily } from '@/theme/fonts';
import { font, PADDING } from '@/theme/responsive';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { CompositeScreenProps, useIsFocused } from '@react-navigation/native';
import React, { useEffect, useState } from 'react';
import { Pressable, RefreshControl, StyleSheet, View } from 'react-native';
import AppActiveOrderShipmentItemRenderer from './components/AppActiveOrderShipmentItemRenderer';
import { FlatList } from 'react-native-gesture-handler';
import { AppActiveOrderTabParamList, AppOrderStackParamList } from '@/navigation/order-navigation';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { RootStackParamList } from '@/navigation';
import { useLazyGetOrderShipmentCancellationReasonsQuery } from '@/services/api/order/shipment';
import Icon from '@/components/Icon';

type Props = CompositeScreenProps<
	NativeStackScreenProps<AppActiveOrderTabParamList, 'Shipments'>,
	CompositeScreenProps<NativeStackScreenProps<AppOrderStackParamList>, NativeStackScreenProps<RootStackParamList>>
>;

const AppActiveOrderShipmentsScreen: React.FC<Props> = ({ navigation }) => {
	const [activeOrderId, setActiveOrderId] = useState<string | null>(null);
	const { showGlobalModal, hideGlobalModal } = useModal();
	const [getOrderShipments, { data, isFetching }] = useLazyGetCourierActiveOrderShipmentsQuery();
	const [getOrderShipmentCancellationReasons, { data: orderShipmentCancellationReasons }] =
		useLazyGetOrderShipmentCancellationReasonsQuery();
	const [getOrder, { data: orderData }] = useLazyGetCourierActiveOrderQuery();

	const handleCreateShipment = () => {
		if (!activeOrderId) return;
		navigation.navigate('AppOrderStack', {
			screen: 'CreateShipment',
			params: { order: orderData!.data },
		});
	};

	const loadOrderShipments = async () => {
		const order_id = await AsyncStorage.getItem('current_active_order_id');
		if (!order_id) return;
		setActiveOrderId(order_id);
		hideGlobalModal();
		showGlobalModal({
			maxHeight: 200,
			children: <LoadingModal />,
			backgroundColor: colors.transparent,
		});
		getOrder(order_id);
		getOrderShipments()
			.catch((err) => console.log(err))
			.finally(() => hideGlobalModal());
	};

	const isFocused = useIsFocused();
	useEffect(() => {
		if (isFocused) {
			loadOrderShipments();
			getOrderShipmentCancellationReasons({ page: 1, size: 100 });
		}
	}, [isFocused]);

	return (
		<View style={styles.container}>
			<FlatList
				data={data?.data}
				contentContainerStyle={{ gap: PADDING.large, paddingBottom: PADDING.xxlarge }}
				refreshControl={<RefreshControl refreshing={isFetching} onRefresh={loadOrderShipments} />}
				showsVerticalScrollIndicator={false}
				renderItem={(props) => (
					<AppActiveOrderShipmentItemRenderer
						{...props}
						loadOrderShipments={loadOrderShipments}
						navigation={navigation}
						orderShipmentCancellationReasons={orderShipmentCancellationReasons?.data ?? []}
					/>
				)}
				ListHeaderComponent={
					(orderData?.data.could_work && (
						<View style={styles.headerButtonWrapper}>
							<Pressable onPress={handleCreateShipment} style={styles.addButton}>
								<Icon name="PlusIconSvg" width={22} height={22} color={colors.white} />
								<PalRiderText color={colors.white} fontFamily={FontFamily.Semibold}>
									Add New Shipment
								</PalRiderText>
							</Pressable>
						</View>
					)) ||
					null
				}
				ListEmptyComponent={
					<View style={styles.emptyStateWrapper}>
						<Icon name="ShipmentsIconSvg" width={70} height={70} color={colors.gray[400]} />
						<PalRiderText style={styles.emptyText}>No shipments have been created yet.</PalRiderText>
					</View>
				}
			/>
		</View>
	);
};

const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.gray[50],
	},
	headerButtonWrapper: {
		padding: PADDING.large,
	},
	addButton: {
		backgroundColor: colors.green[600],
		paddingVertical: PADDING.medium,
		borderRadius: PADDING.large,
		flexDirection: 'row',
		alignItems: 'center',
		justifyContent: 'center',
		gap: PADDING.small,
		shadowColor: colors.black,
		shadowOpacity: 0.1,
		shadowRadius: 6,
		elevation: 6,
	},
	emptyStateWrapper: {
		flex: 1,
		alignItems: 'center',
		justifyContent: 'center',
		padding: PADDING.xxlarge,
		gap: PADDING.large,
	},
	emptyText: {
		fontFamily: FontFamily.Semibold,
		fontSize: font.medium,
		textAlign: 'center',
		color: colors.gray[500],
	},
});

export default AppActiveOrderShipmentsScreen;
