import { createApi } from '@reduxjs/toolkit/query/react';
import { baseQueryConfigWithReAuth } from 'src/services/api/baseQueryConfig.ts';
import {
	WooSmapAutocompleteAddressResult,
	WooSmapAutocompletePostCodeResult,
	WooSmapValidateAdddressResult,
} from '@/@types/woosmap-api-types';

export const wooSmapApi = createApi({
	reducerPath: 'wooSmapApi',
	baseQuery: baseQueryConfigWithReAuth,
	endpoints: (builder) => ({
		wooSmapAutocompletePostCode: builder.query<WooSmapAutocompletePostCodeResult, string>({
			query(search) {
				return {
					method: 'GET',
					params: {
						search,
					},
					url: 'woosmap/autocomplete-post-code',
				};
			},
		}),

		wooSmapAutocompleteAddressFromPostCode: builder.query<WooSmapAutocompleteAddressResult, string>({
			query(public_id) {
				return {
					method: 'POST',
					body: {
						public_id,
					},
					url: 'woosmap/autocomplete-address',
				};
			},
		}),
		wooSmapValidateAddress: builder.query<WooSmapValidateAdddressResult, string>({
			query(public_id) {
				return {
					method: 'POST',
					body: {
						public_id,
					},
					url: 'woosmap/validate-address',
				};
			},
		}),
	}),
});

export const {
	useLazyWooSmapAutocompletePostCodeQuery,
	useLazyWooSmapAutocompleteAddressFromPostCodeQuery,
	useLazyWooSmapValidateAddressQuery,
} = wooSmapApi;
