import { Dimensions, PixelRatio } from 'react-native';

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get('window');

const widthBaseScale = SCREEN_WIDTH / 375;
const heightBaseScale = SCREEN_HEIGHT / 812;

export function normalize(size: number, based: 'width' | 'height' = 'height') {
	const newSize = based === 'height' ? size * heightBaseScale : size * widthBaseScale;
	return Math.round(PixelRatio.roundToNearestPixel(newSize));
}

export interface FontType {
	/**
	 * @param mini - Default Value = 10
	 */
	xmini: number;
	/**
	 * @param mini - Default Value = 12
	 */
	mini: number;
	/**
	 * @param small - Default Value = 14
	 */
	small: number;
	/**
	 * @param medium - Default Value = 16
	 */
	medium: number;
	/**
	 * @param large - Default Value = 18
	 */
	large: number;
	/**
	 * @param xlarge - Default Value = 20
	 */
	xlarge: number;
	/**
	 * @param xxlarge - Default Value = 22
	 */
	xxlarge: number;
	/**
	 * @param xxxlarge - Default Value = 24
	 */
	xxxlarge: number;

	/**
	 * @param xxxxlarge - Default Value = 26
	 */
	xxxxlarge: number;
}

export interface PaddingType {
	/**
	 * @param mini - Default Value = 2
	 */
	mini: number;
	/**
	 * @param small - Default Value = 4
	 */
	small: number;
	/**
	 * @param medium - Default Value = 8
	 */
	medium: number;
	/**
	 * @param large - Default Value = 12
	 */
	large: number;
	/**
	 * @param xlarge - Default Value = 16
	 */
	xlarge: number;
	/**
	 * @param xlarge - Default Value = 20
	 */
	xxlarge: number;
}

export const font: FontType = {
	xmini: normalize(10),
	mini: normalize(12),
	small: normalize(14),
	medium: normalize(16),
	large: normalize(18),
	xlarge: normalize(20),
	xxlarge: normalize(22),
	xxxlarge: normalize(24),
	xxxxlarge: normalize(26),
} as const;

export const PADDING: PaddingType = {
	mini: normalize(2),
	small: normalize(4),
	medium: normalize(8),
	large: normalize(12),
	xlarge: normalize(16),
	xxlarge: normalize(20),
} as const;

export type SVGComponentPropType = {
	width?: number | string;
	height?: number | string;
};

export type SVGComponentPropTypeWithColor = {
	color?: string;
} & SVGComponentPropType;

export type SVGComponentPropTypeWithMultiColor = {
	colorSpace?: Array<string>;
} & SVGComponentPropType;
