import React, { useCallback } from 'react';
import { Alert, RefreshControl, ScrollView, StyleSheet, View, Pressable, InteractionManager } from 'react-native';
import { CompositeScreenProps, useFocusEffect } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { BottomTabScreenProps } from '@react-navigation/bottom-tabs';
import { MenuView } from '@react-native-menu/menu';

import colors from '@/theme/colors';
import { font, PADDING } from '@/theme/responsive';
import { FontFamily } from '@/theme/fonts';

import PalRiderText from '@/components/PalRiderText';
import PalRiderButton from '@/components/PalRiderButton';
import Icon from '@/components/Icon';

import LoadingModal from '@/components/custom-modal/LoadingModal';
import WarningModal from '@/components/custom-modal/WarningModal';
import SuccessModal from '@/components/custom-modal/SuccessModal';

import { useDeleteCompanyAreaAddressWalletMutation } from '@/services/api/company/company-area-address-wallet';
import { useGetCompanyAreaAddressWalletListQuery } from '@/services/api/company/company-area-address';

import { usePalRiderOrderCheckout } from '@/hooks/usePalRiderCheckout';
import { useModal } from '@/components/ModalProvider';
import { useAppSelector } from '@/redux/hooks';
import { isFetchBaseQueryError } from '@/utils';

import {
	AppCompanyProfileCompanyAreaParamList,
	AppCompanyProfileParamList,
	AppCompanyTabParamList,
} from '@/navigation/company-navigation';
import { RootStackParamList } from '@/navigation';
import { CompanyAreaAddressUserDTO, CompanyAreaAddressWalletDTO } from 'palriderapptypes/company';

const { format } = Intl.NumberFormat('en-UK', { currency: 'GBP', style: 'currency' });

export type Props = CompositeScreenProps<
	NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList, 'CompanyAreaAddressWallet'>,
	CompositeScreenProps<
		NativeStackScreenProps<AppCompanyProfileParamList, 'CompanyAreaStack'>,
		CompositeScreenProps<
			BottomTabScreenProps<AppCompanyTabParamList, 'CompanyProfileStack'>,
			CompositeScreenProps<
				NativeStackScreenProps<RootStackParamList>,
				NativeStackScreenProps<AppCompanyProfileCompanyAreaParamList>
			>
		>
	>
>;

const AppCompanyProfileCompanyAreaWalletScreen: React.FC<Props> = ({ navigation, route }) => {
	const companyAreaAddressUser = useAppSelector(
		(s) => s.userSlice.user?.company_area_address_user,
	) as CompanyAreaAddressUserDTO;

	const { company_area_address_id, company_area_address_wallet_id, add_new_balance, remaining_balance } = route.params;

	const { data, isFetching, isLoading, refetch } = useGetCompanyAreaAddressWalletListQuery(company_area_address_id, {
		skip: !company_area_address_id,
	});

	const [deleteWallet] = useDeleteCompanyAreaAddressWalletMutation();
	const { initializeAndOpenPaymentSheet } = usePalRiderOrderCheckout();
	const { showGlobalModal, hideGlobalModal } = useModal();

	const handleAddBalance = (walletId: string, amount: number) => {
		showGlobalModal({ children: <LoadingModal />, backgroundColor: colors.transparent });
		initializeAndOpenPaymentSheet({
			amount: amount * 100,
			company_area_address_wallet_id: walletId,
			whenSucceeded: () => {
				refetch();
				hideGlobalModal();
			},
		});
	};

	useFocusEffect(
		useCallback(() => {
			if (add_new_balance && remaining_balance && company_area_address_wallet_id) {
				InteractionManager.runAfterInteractions(() => {
					handleAddBalance(company_area_address_wallet_id, remaining_balance);
				});
			}
		}, [add_new_balance, remaining_balance, company_area_address_wallet_id]),
	);

	const goToAddScreen = () =>
		navigation.navigate('AppCompanyStack', {
			screen: 'CompanyProfileStack',
			params: {
				screen: 'CompanyAreaStack',
				params: {
					screen: 'CompanyAreaAddressWalletCreate',
					params: { company_area_address_id },
				},
			},
		});

	const handleMenuAction = async (event: string, wallet: any) => {
		switch (event) {
			case 'update':
				navigation.navigate('AppCompanyStack', {
					screen: 'CompanyProfileStack',
					params: {
						screen: 'CompanyAreaStack',
						params: {
							screen: 'CompanyAreaAddressWalletUpdate',
							params: { name: wallet.name, company_area_address_wallet_id: wallet.id },
						},
					},
				});
				break;
			case 'delete':
				showGlobalModal({ children: <LoadingModal />, backgroundColor: colors.transparent });
				const res = await deleteWallet({ company_area_address_wallet_id: wallet.id });
				if (res.error && isFetchBaseQueryError(res.error)) {
					showGlobalModal({ children: <WarningModal text={res.error.data.title} /> });
					return;
				}
				showGlobalModal({ children: <SuccessModal text="Wallet deleted" /> });
				refetch();
				break;
			case 'add_100_pound':
				handleAddBalance(wallet.id, 100);
				break;
			case 'add_50_pound':
				handleAddBalance(wallet.id, 50);
				break;
			case 'add_25_pound':
				handleAddBalance(wallet.id, 25);
				break;
			case 'add_custom_pound':
				Alert.prompt(
					'Amount',
					'Enter custom amount',
					[
						{ text: 'Cancel', style: 'cancel' },
						{
							text: 'OK',
							onPress: (text?: string) => text && handleAddBalance(wallet.id, Number(text)),
						},
					],
					'plain-text',
					'',
					'number-pad',
				);
				break;
			case 'show_wallet_transaction_list':
				navigation.navigate('AppCompanyStack', {
					screen: 'CompanyProfileStack',
					params: {
						screen: 'CompanyAreaStack',
						params: {
							screen: 'CompanyAreaAddressWalletTransaction',
							params: { company_area_address_wallet_id: wallet.id },
						},
					},
				});
				break;
			case 'show_transfer_requests':
				navigation.navigate('AppCompanyStack', {
					screen: 'CompanyProfileStack',
					params: {
						screen: 'CompanyAreaStack',
						params: {
							screen: 'CompanyAreaAddressWalletTransferRequests',
							params: { company_area_address_wallet_id: wallet.id },
						},
					},
				});
				break;
		}
	};

	return (
		<View style={styles.container}>
			<ScrollView
				contentContainerStyle={styles.scrollContent}
				refreshControl={
					<RefreshControl
						refreshing={isFetching}
						onRefresh={refetch}
						tintColor={colors.orange[600]}
						colors={[colors.orange[600]]}
					/>
				}
			>
				{isLoading ? (
					<LoadingModal />
				) : (
					data?.data.map((wallet: CompanyAreaAddressWalletDTO) => (
						<View key={wallet.id} style={styles.walletCard}>
							<View style={styles.cardHeader}>
								<PalRiderText fontSize={font.medium} fontFamily={FontFamily.Semibold} color={colors.white}>
									{wallet.name}
								</PalRiderText>
								<MenuView
									actions={[
										{ id: 'update', title: 'Edit Name' },
										{ id: 'delete', title: 'Delete' },
										{ id: 'add_100_pound', title: 'Add £100' },
										{ id: 'add_50_pound', title: 'Add £50' },
										{ id: 'add_25_pound', title: 'Add £25' },
										{ id: 'add_custom_pound', title: 'Add Custom Amount' },
										{ id: 'show_wallet_transaction_list', title: 'View Transactions' },
										{
											id: 'show_transfer_requests',
											title: 'Show Transfer Requests',
											attributes: {
												hidden: !['Owner', 'Manager'].includes(
													companyAreaAddressUser.company_area_address_user_role?.name ?? '',
												),
											},
										},
									]}
									onPressAction={({ nativeEvent }) => handleMenuAction(nativeEvent.event, wallet)}
								>
									<Pressable style={styles.menuButton}>
										<Icon name="LineDottedIconSvg" color={colors.white} />
									</Pressable>
								</MenuView>
							</View>

							<View style={styles.balanceContainer}>
								<PalRiderText fontSize={font.small} color={colors.gray[100]}>
									Account Balance
								</PalRiderText>
								<View style={styles.balanceRow}>
									<PalRiderText fontSize={font.xlarge} color={colors.white} fontFamily={FontFamily.Bold}>
										{format(wallet.balance)}
									</PalRiderText>
									<PalRiderText fontSize={font.mini} color={colors.gray[200]}>
										({format(wallet.inconsumable_balance)})
									</PalRiderText>
								</View>
							</View>
						</View>
					))
				)}

				<PalRiderButton variant="primary" onPress={goToAddScreen}>
					<PalRiderText color={colors.white} fontFamily={FontFamily.Semibold}>
						Add New Wallet
					</PalRiderText>
				</PalRiderButton>
			</ScrollView>
		</View>
	);
};

const styles = StyleSheet.create({
	container: { flex: 1, backgroundColor: colors.gray[50] },
	scrollContent: { flexGrow: 1, padding: PADDING.large, gap: PADDING.large, paddingBottom: 100 },
	walletCard: {
		backgroundColor: colors.orange[600],
		borderRadius: 20,
		padding: PADDING.large,
		shadowColor: '#000',
		shadowOpacity: 0.1,
		shadowRadius: 8,
		elevation: 4,
	},
	cardHeader: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
		marginBottom: PADDING.medium,
	},
	menuButton: {
		padding: PADDING.small,
		borderRadius: 20,
		backgroundColor: 'rgba(255,255,255,0.2)',
	},
	balanceContainer: { marginTop: PADDING.small },
	balanceRow: { flexDirection: 'row', alignItems: 'flex-end', gap: PADDING.small },
});

export default AppCompanyProfileCompanyAreaWalletScreen;
