import React, { useState } from 'react';
import { View, StyleSheet, Dimensions, ViewStyle } from 'react-native';
import Animated, {
	useSharedValue,
	useAnimatedStyle,
	withSpring,
	runOnJS,
	interpolateColor,
} from 'react-native-reanimated';
import { GestureDetector, Gesture } from 'react-native-gesture-handler';
import colors from '@/theme/colors';
import { font, PADDING } from '@/theme/responsive';
import { FontFamily } from '@/theme/fonts';
const { width } = Dimensions.get('window');

// Define the props type
interface PalRiderSwipeButtonProps {
	swipeText: string;
	swipedText: string;
	containerStyle?: ViewStyle;
	button: React.ReactNode;
	onSwipe: () => void;
	firstColor?: string;
	secondColor?: string;
	swipeColor?: string;
}

const PalRiderSwipeButton: React.FC<PalRiderSwipeButtonProps> = (props) => {
	const {
		swipeText,
		swipedText,
		button,
		containerStyle,
		firstColor = colors.green[200],
		secondColor = colors.green[400],
		swipeColor = colors.green[600],
		onSwipe,
	} = props;
	const translateX = useSharedValue(0);
	const [isSwiped, setIsSwiped] = useState(false);
	const SWIPEABLE_WIDTH = width - 30 - 70;

	const panGesture = Gesture.Pan()
		.onUpdate((event) => {
			'worklet';
			translateX.value = Math.max(0, Math.min(event.translationX, SWIPEABLE_WIDTH));
			if (translateX.value > SWIPEABLE_WIDTH * 0.8) {
				runOnJS(setIsSwiped)(true);
			} else runOnJS(setIsSwiped)(false);
		})
		.onEnd(() => {
			if (translateX.value < SWIPEABLE_WIDTH * 0.8) {
				translateX.value = withSpring(0);
			} else {
				translateX.value = withSpring(0);
				runOnJS(onSwipe)();
				runOnJS(setIsSwiped)(false);
			}
		});

	const animatedStyle = useAnimatedStyle(() => ({
		transform: [{ translateX: translateX.value }],
	}));

	const animatedBackgroundStyle = useAnimatedStyle(() => ({
		backgroundColor: interpolateColor(translateX.value, [0, SWIPEABLE_WIDTH], [firstColor, secondColor]),
	}));

	const animatedColorStyle = useAnimatedStyle(() => ({
		color: interpolateColor(translateX.value, [0, SWIPEABLE_WIDTH], ['rgb(0,0,0)', 'rgb(255,255,255)']),
	}));
	return (
		<View style={styles.container}>
			<View
				style={[
					styles.swipeContainer,
					{
						backgroundColor: firstColor,
					},
				]}
			>
				<Animated.View style={[styles.background, animatedBackgroundStyle, containerStyle]}>
					<Animated.Text style={[animatedColorStyle, { fontFamily: FontFamily.Semibold, fontSize: font.mini }]}>
						{(isSwiped && swipedText) || swipeText}
					</Animated.Text>
				</Animated.View>
				<GestureDetector gesture={panGesture}>
					<Animated.View style={[styles.swipeable, animatedStyle, { backgroundColor: swipeColor }]}>
						{button}
					</Animated.View>
				</GestureDetector>
			</View>
		</View>
	);
};

const styles = StyleSheet.create({
	container: {
		justifyContent: 'center',
		alignItems: 'center',
		backgroundColor: colors.transparent,
	},
	swipeContainer: {
		width: width - 30,
		height: 60,
		overflow: 'hidden',
		justifyContent: 'center',
		borderRadius: PADDING.large,
	},
	swipeable: {
		width: 70,
		height: 60,
		justifyContent: 'center',
		alignItems: 'center',
		position: 'absolute',
		borderRadius: PADDING.large,
	},
	background: {
		...StyleSheet.absoluteFillObject,
		justifyContent: 'center',
		alignItems: 'center',
	},
});

export default PalRiderSwipeButton;
