import PalRiderButton from '@/components/PalRiderButton.tsx';
import PalRiderCheckBox from '@/components/PalRiderCheckBox.tsx';
import PalRiderPhoneInput from '@/components/PalRiderPhoneInput.tsx';
import PalRiderText from '@/components/PalRiderText.tsx';
import PalRiderTextInput from '@/components/PalRiderTextInput.tsx';
import colors from '@/theme/colors.ts';
import { buttonStyling } from '@/theme/defaults.ts';
import { FontFamily } from '@/theme/fonts.ts';
import { font, normalize, PADDING } from '@/theme/responsive.ts';
import { Shape } from '@/types';
import { isFetchBaseQueryError, phoneNumberRegex } from '@/utils';
import { useFormik } from 'formik';
import React, { useRef, useState } from 'react';
import { Pressable, StyleSheet, View } from 'react-native';
import { KeyboardAwareScrollView } from 'react-native-keyboard-aware-scroll-view';
import { boolean, object, string } from 'yup';
import { useAppDispatch } from '@/redux/hooks.ts';
import { useAuthenticateCourierMutation } from '@/services/api/courier/auth-courier.ts';
import { setCourierPhoneNumber } from '@/redux/slices/courier-onboarding.ts';
import LottieView from 'lottie-react-native';
import { useModal } from '@/components/ModalProvider';
import WarningModal from '@/components/custom-modal/WarningModal';
import Dropdown from 'react-native-input-select';
import { DropdownSelectHandle } from 'react-native-input-select/lib/typescript/src/types/index.types';
import Icon from '@/components/Icon';

type FormikType = {
	phone_number: string;
	email: string;
	authentication_type: 'phone' | 'email';
	agreement: boolean;
};
type Props = {
	nextStep: () => void;
	prevStep: () => void;
};
const SignUpCourierPhoneInfoStep: React.FC<Props> = ({ prevStep, nextStep }) => {
	const dispatch = useAppDispatch();
	const [authenticateCourier, { isLoading }] = useAuthenticateCourierMutation();
	const { showGlobalModal } = useModal();
	const areaCodeRef = useRef<DropdownSelectHandle | null>(null);
	const [areaCode, setAreaCode] = useState('44');
	const signUpCourierAuthenticateFormik = useFormik<FormikType>({
		initialValues: {
			authentication_type: 'phone',
			phone_number: '',
			email: '',
			agreement: true,
		},
		validationSchema: object<Shape<FormikType>>({
			authentication_type: string(),
			phone_number: string().when('authentication_type', {
				is: (value: string) => value === 'phone',
				then: (schema) =>
					schema
						.required('Phone Number is required')
						.test('phone-regex', 'Phone number must be valid', function (value) {
							return phoneNumberRegex.test('+44' + value);
						}),
				otherwise: (schema) => schema,
			}),
			email: string().when('authentication_type', {
				is: (value: string) => value === 'email',
				then: (schema) => schema.required('Email is required').email('Email must be valid'),
				otherwise: (schema) => schema,
			}),
			agreement: boolean().required().oneOf([true], 'The terms and conditions must be accepted.'),
		}),
		onSubmit: async (values) => {
			var result = await authenticateCourier({
				phone_number: '+' + areaCode + values.phone_number.replace(/\D/g, ''),
			});
			if (result.error && isFetchBaseQueryError(result.error)) {
				showGlobalModal({
					children: <WarningModal text={result.error.data.title} />,
				});
				return;
			}
			dispatch(setCourierPhoneNumber('+' + areaCode + values.phone_number.replace(/\D/g, '')));
			nextStep();
		},
	});
	return (
		<KeyboardAwareScrollView
			style={styles.container}
			alwaysBounceVertical={false}
			bounces={false}
			overScrollMode="never"
			contentContainerStyle={styles.scrollViewContentContainerStyle}
			extraHeight={normalize(15)}
			showsVerticalScrollIndicator={false}
			keyboardShouldPersistTaps="handled"
		>
			<View style={styles.contentContainer}>
				<View style={{ alignItems: 'center', gap: PADDING.large }}>
					<LottieView
						style={{ width: '100%', height: 220 }}
						source={require('@/assets/animations/phone-verication.json')}
						autoPlay
						loop
					/>
					<PalRiderText fontSize={font.xxlarge} fontFamily={FontFamily.Semibold}>
						Phone Verification
					</PalRiderText>
					<PalRiderText fontSize={font.mini} color={colors.gray[600]} style={{ textAlign: 'center' }}>
						We need to register your phone number before getting started !
					</PalRiderText>
				</View>

				<Dropdown
					ref={areaCodeRef}
					dropdownStyle={{
						display: 'none',
					}}
					options={[
						{
							label: 'United Kingdom (+44)',
							value: '44',
						},
						{
							label: 'Turkiye (+90)',
							value: '90',
						},
					]}
					isMultiple={false}
					selectedValue={areaCode}
					onValueChange={(value) => setAreaCode(value as string)}
					maxSelectableItems={1}
				/>
				{signUpCourierAuthenticateFormik.values.authentication_type === 'phone' && (
					<PalRiderPhoneInput
						onAreaCodePress={() => areaCodeRef.current?.open()}
						areaCode={areaCode}
						title="Phone Number"
						onChangeText={(text) => {
							signUpCourierAuthenticateFormik.setFieldValue('phone_number', text, true);
						}}
						error={signUpCourierAuthenticateFormik.errors.phone_number}
						touched={!signUpCourierAuthenticateFormik.errors.phone_number}
						value={signUpCourierAuthenticateFormik.values.phone_number}
					/>
				)}
				{signUpCourierAuthenticateFormik.values.authentication_type === 'email' && (
					<PalRiderTextInput
						title="Email"
						value={signUpCourierAuthenticateFormik.values.email}
						onChangeText={(text) => signUpCourierAuthenticateFormik.setFieldValue('email', text)}
						error={signUpCourierAuthenticateFormik.errors.email}
						keyboardType="email-address"
						autoComplete="email"
						autoCapitalize="none"
						autoCorrect={false}
						leftComponent={<Icon name="EmailSignIconSvg" width={16} height={16} />}
					/>
				)}
				<View
					style={{
						flexDirection: 'row',
						alignItems: 'center',
						marginHorizontal: normalize(4),
					}}
				>
					<PalRiderCheckBox
						value={signUpCourierAuthenticateFormik.values.agreement}
						error={signUpCourierAuthenticateFormik.errors.agreement}
						onValueChange={(val) => signUpCourierAuthenticateFormik.setFieldValue('agreement', val)}
					/>
					<View
						style={{
							flexDirection: 'row',
							flexWrap: 'wrap',
							gap: normalize(4),
							marginVertical: normalize(8),
						}}
					>
						<PalRiderText
							style={{
								justifyContent: 'center',
								flexWrap: 'wrap',
							}}
						>
							<PalRiderText style={styles.linkedText}>I have read, understood and accepted the {'\n'}</PalRiderText>
							<Pressable>
								<PalRiderText style={[styles.linkText, { top: 3, marginRight: normalize(4) }]}>
									Terms of Use
								</PalRiderText>
							</Pressable>
							<PalRiderText style={styles.linkedText}>and</PalRiderText>
							<Pressable>
								<PalRiderText style={[styles.linkText, { top: 3, left: 4 }]}>Privacy Policy.</PalRiderText>
							</Pressable>
						</PalRiderText>
					</View>
				</View>
				<View
					style={{
						flexDirection: 'row',
						gap: normalize(10),
					}}
				>
					<PalRiderButton style={[buttonStyling.dark, { flex: 1 }]} onPress={() => prevStep()}>
						<PalRiderText color="white">Go Back</PalRiderText>
					</PalRiderButton>
					<PalRiderButton
						style={[buttonStyling.success, { flex: 1 }]}
						loading={isLoading}
						onPress={() => signUpCourierAuthenticateFormik.handleSubmit()}
					>
						<PalRiderText color="white">Send OTP</PalRiderText>
					</PalRiderButton>
				</View>
			</View>
		</KeyboardAwareScrollView>
	);
};
const styles = StyleSheet.create({
	container: {
		flex: 1,
		backgroundColor: colors.white,
		padding: PADDING.large,
	},
	contentContainer: {
		backgroundColor: colors.white,
		justifyContent: 'center',
	},
	title: {
		textAlign: 'center',
		fontSize: normalize(30),
		color: colors.black,
		fontFamily: FontFamily.Bold,
	},
	description: {
		textAlign: 'center',
		fontSize: normalize(14),
		fontFamily: FontFamily.Semibold,
		color: colors.gray[200],
		marginTop: normalize(10),
		marginBottom: normalize(30),
	},
	scrollViewContentContainerStyle: {
		justifyContent: 'center',
	},
	continueButton: {
		marginTop: normalize(8),
	},
	continueButtonText: {
		fontFamily: FontFamily.Bold,
		color: colors.white,
	},
	signUpButton: {
		flex: 1,
		flexDirection: 'row',
		columnGap: 10,
		alignItems: 'center',
		justifyContent: 'center',
	},
	signUpButtonGoogle: {
		backgroundColor: colors.orange[600],
	},
	signUpButtonFacebook: {
		backgroundColor: colors.blue[700],
	},
	signUpButtonText: {
		color: 'white',
		fontSize: normalize(12),
		fontFamily: FontFamily.Bold,
	},
	signUpWithEmailContainer: {
		marginVertical: normalize(8),
		alignItems: 'flex-end',
	},
	signUpWithEmailText: {
		fontFamily: FontFamily.Semibold,
		textDecorationStyle: 'solid',
		textDecorationLine: 'underline',
	},
	linkContainer: {
		marginBottom: normalize(40),
		justifyContent: 'center',
		flexDirection: 'row',
	},
	linkText: {
		color: colors.orange[600],
		fontFamily: FontFamily.Semibold,
		fontSize: normalize(12),
	},
	linkedText: {
		fontFamily: FontFamily.Semibold,
		fontSize: normalize(12),
	},
});
export default SignUpCourierPhoneInfoStep;
