import PalRiderTextInput from '@/components/PalRiderTextInput';
import { PADDING } from '@/theme/responsive';
import { yupTyped } from '@/types';
import { isFetchBaseQueryError } from '@/utils';
import { format } from 'date-fns';
import { useFormik } from 'formik';
import React, { useState } from 'react';
import { StyleSheet, View } from 'react-native';
import DatePicker from 'react-native-date-picker';
import { KeyboardAwareScrollView } from 'react-native-keyboard-aware-scroll-view';
import { date, string } from 'yup';
import { useAppDispatch, useAppSelector } from '@/redux/hooks.ts';
import { setCourierInfoOnboardingState } from '@/redux/slices/courier-onboarding.ts';
import CalendarIconSvg from '@/assets/svg/custom/CalenderIconSvg';
import PalRiderButton from '@/components/PalRiderButton';
import PalRiderText from '@/components/PalRiderText';
import colors from '@/theme/colors';
import { OnboardingCourierUserRequestDTO } from 'palriderapptypes/courier';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

type Props = {
	nextStep: () => void;
};
const SignUpCourierPersonalInformationStep: React.FC<Props> = ({ nextStep }) => {
	const dispatch = useAppDispatch();
	const [datePickerOpened, setDatePickerOpened] = useState(false);
	const minDate = new Date(new Date().setFullYear(new Date().getFullYear() - 80)); // 80 years before today
	const maxDate = new Date(new Date().setFullYear(new Date().getFullYear() - 18)); // 18 years before today
	const courierOnboardingSlice = useAppSelector((x) => x.courierOnboardingSlice.user);
	const insets = useSafeAreaInsets();
	const signUpCourierFormik = useFormik<OnboardingCourierUserRequestDTO>({
		initialValues: {
			name: courierOnboardingSlice.name,
			surname: courierOnboardingSlice.surname,
			birthday: courierOnboardingSlice.birthday,
		},
		validationSchema: yupTyped<OnboardingCourierUserRequestDTO>({
			name: string().required().label('Name'),
			surname: string().required().label('Surname'),
			birthday: date()
				.max(maxDate, 'Birthday must be at least 18 before today')
				.min(minDate, 'Birthday cannot be more than 80 years ago')
				.required('Birthday is required'),
		}),
		validateOnChange: false,
		onSubmit: async (values) => {
			try {
				dispatch(
					setCourierInfoOnboardingState({
						name: values.name,
						surname: values.surname,
						birthday: values.birthday,
					}),
				);
				nextStep();
			} catch (err) {
				if (isFetchBaseQueryError(err)) {
					return;
				}
			}
		},
	});
	return (
		<KeyboardAwareScrollView
			showsVerticalScrollIndicator={false}
			contentContainerStyle={[
				styles.scrollViewContainer,
				{
					paddingBottom: insets.bottom,
				},
			]}
		>
			<View style={styles.container}>
				<View style={[styles.rowContainer, { alignItems: 'center' }]}>
					<View style={{ flex: 1, gap: PADDING.large }}>
						<PalRiderTextInput
							title="Name"
							required
							placeholder="Ex. Adam"
							value={signUpCourierFormik.values.name}
							onChangeText={signUpCourierFormik.handleChange('name')}
							onBlur={signUpCourierFormik.handleBlur('name')}
							error={signUpCourierFormik.errors.name}
						/>
						<PalRiderTextInput
							title="Surname"
							required
							placeholder="Ex. Handler"
							value={signUpCourierFormik.values.surname}
							onChangeText={signUpCourierFormik.handleChange('surname')}
							onBlur={signUpCourierFormik.handleBlur('surname')}
							error={signUpCourierFormik.errors.surname}
						/>
						{/* <PalRiderTextInput */}
						{/* 	title="Email" */}
						{/* 	placeholder="Ex. example@mail.com" */}
						{/* 	value={signUpCourierFormik.values.email} */}
						{/* 	onChangeText={signUpCourierFormik.handleChange('email')} */}
						{/* 	onBlur={signUpCourierFormik.handleBlur('email')} */}
						{/* 	error={signUpCourierFormik.errors.email} */}
						{/* 	keyboardType="email-address" */}
						{/* 	autoComplete="email" */}
						{/* 	clearTextOnFocus={true} */}
						{/* 	leftComponent={<EmailSignIconSvg width={16} height={16} />} */}
						{/* /> */}
						<PalRiderTextInput
							required
							title={'Birthday'}
							value={signUpCourierFormik.values.birthday}
							onPressIn={() => setDatePickerOpened(true)}
							error={signUpCourierFormik.errors.birthday}
							leftComponent={<CalendarIconSvg width={16} height={16} />}
						/>
					</View>
				</View>
				<DatePicker
					modal
					locale="en"
					mode="date"
					title={'Birthday'}
					theme="dark"
					date={new Date(new Date().setFullYear(new Date().getFullYear() - 18))}
					open={datePickerOpened}
					maximumDate={new Date(new Date().setFullYear(new Date().getFullYear() - 18))}
					minimumDate={new Date(new Date().setFullYear(new Date().getFullYear() - 80))}
					onConfirm={(seletectedDate) => {
						setDatePickerOpened(false);
						signUpCourierFormik.setFieldValue('birthday', format(seletectedDate, 'yyyy-MM-dd'), true);
					}}
					onCancel={() => {
						setDatePickerOpened(false);
					}}
				/>
			</View>
			<PalRiderButton
				variant="dark"
				onPress={() => {
					signUpCourierFormik.handleSubmit();
				}}
			>
				<PalRiderText color={colors.white}>Continue</PalRiderText>
			</PalRiderButton>
		</KeyboardAwareScrollView>
	);
};
const styles = StyleSheet.create({
	container: {
		flex: 1,
	},
	columnContainer: {
		rowGap: PADDING.large,
	},
	rowContainer: {
		flexDirection: 'row',
		width: '100%',
	},
	scrollViewContainer: {
		rowGap: PADDING.large,
		flex: 1,
		padding: PADDING.large,
	},
});
export default SignUpCourierPersonalInformationStep;
